class Schedule:
    def __init__(self, free_hours):
        self.free_hours = free_hours  # dictionary of free hours for each day
        self.schedule = {day: [] for day in free_hours}  # initialize empty schedule

    def add_task(self, task, day):
        if self.free_hours[day] >= task.duration:
            self.schedule[day].append(task)
            self.free_hours[day] -= task.duration
            return True
        return False

    def optimize_schedule(self, tasks):
        # Sort tasks by priority (higher priority first)
        tasks.sort(key=lambda x: x.priority, reverse=True)

        for task in tasks:
            for day in self.free_hours:
                if self.add_task(task, day):
                    break

    def print_schedule(self):
        for day, tasks in self.schedule.items():
            print(f"{day}:")
            for task in tasks:
                print(f"  - {task}")

import num2words
from num2words import num2words

def number_to_words(n, lang='en'):
    if lang == 'en':
        return num2words(n, lang='en').replace('-', ' ').replace(',', '')
    elif lang == 'fr':
        return num2words(n, lang='fr').replace('-', ' ').replace(',', '')
    else:
        raise ValueError("Unsupported language")

def generate_latex_table(numbers):
    if not all(1 <= n <= 100 for n in numbers):
        raise ValueError("All numbers must be between 1 and 100")

    latex_table = "\\begin{tabular}{|c|c|c|}\n"
    latex_table += "\\hline\n"
    latex_table += "Numerical Value & English & French \\\\\n"
    latex_table += "\\hline\n"

    for n in numbers:
        en_word = number_to_words(n, 'en')
        fr_word = number_to_words(n, 'fr')
        latex_table += f"{n} & {en_word} & {fr_word} \\\\\n"
        latex_table += "\\hline\n"

    latex_table += "\\end{tabular}\n"
    return latex_table

def main():
    import sys

    if len(sys.argv) < 2:
        print("Usage: python script.py <comma-separated-list-of-numbers>")
        sys.exit(1)

    try:
        input_list = [int(n) for n in sys.argv[1].split(',')]
