class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        rootU = self.find(u)
        rootV = self.find(v)
        if rootU != rootV:
            if self.rank[rootU] > self.rank[rootV]:
                self.parent[rootV] = rootU
            elif self.rank[rootU] < self.rank[rootV]:
                self.parent[rootU] = rootV
            else:
                self.parent[rootV] = rootU
                self.rank[rootU] += 1
            return True
        return False

def kruskal(n, edges, exclude=None, include=None):
    uf = UnionFind(n)
    mst_weight = 0
    if include is not None:
        u, v, w = include
        if uf.union(u, v):
            mst_weight += w
    for i, (u, v, w) in enumerate(edges):
        if exclude is not None and i == exclude:
            continue
        if uf.union(u, v):
            mst_weight += w
    return mst_weight if all(uf.find(i) == uf.find(0) for i in range(n)) else float('inf')

def findCriticalAndPseudoCriticalEdges(n: int, edges: List[List[int]]) -> List[List[int]]:
    # Add index to edges for easy reference
    edges = [(u, v, w, i) for i, (u, v, w) in enumerate(edges)]
    # Sort edges by weight
    edges.sort(key=lambda x: x[2])

    # Calculate the weight of the MST
    mst_weight = kruskal(n, [(u, v, w) for u, v, w, _ in edges])

    critical_edges = []
    pseudo_critical_edges = []

    for i, (u, v, w, idx) in enumerate(edges):
        # Check if the edge is critical
        if kruskal(n, [(u, v, w) for u, v, w, _ in edges], exclude=i) > mst_weight:
            critical_edges.append(idx)
        else:
            # Check if the edge is pseudo-critical
            if kruskal(n, [(u, v, w) for u, v, w, _ in edges], include=(u, v, w)) == mst_weight:
                pseudo_critical_edges.append(idx)

    return [critical_edges, pseudo_critical_edges, mst_weight]

