def geometric_mean(a, b, c):
    try:
        # Calculate the geometric mean
        return (a * b * c) ** (1/3)
    except ZeroDivisionError:
        print("Error: One or more inputs are zero, which is invalid for geometric mean calculation.")
        sys.exit(1)
    except Exception as e:
        print(f"Error: An unexpected error occurred: {e}")
        sys.exit(1)

def get_user_input():
    try:
        # Get user input
        a = float(input("Enter the first number: "))
        b = float(input("Enter the second number: "))
        c = float(input("Enter the third number: "))

        # Check for distinct values
        if len({a, b, c}) < 3:
            print("Error: All three numbers must be distinct.")
            sys.exit(1)

        return a, b, c
    except ValueError:
        print("Error: Invalid input. Please enter numerical values.")
        sys.exit(1)

def main():
    if len(sys.argv) == 4:
        try:
            a, b, c = map(float, sys.argv[1:])
            if len({a, b, c}) < 3:
                print("Error: All three numbers must be distinct.")
                sys.exit(1)
        except ValueError:
            print("Error: Invalid input. Please provide three numerical values as command line arguments.")
            sys.exit(1)
    else:
        a, b, c = get_user_input()

    # Calculate and print the geometric mean
    result = geometric_mean(a, b, c)
    print(f"The geometric mean of {a}, {b}, and {c} is: {result}")

