class Phone:
    def __init__(self, brand, model, os, battery_capacity, screen_size):
        self.brand = brand
        self.model = model
        self.os = os
        self.battery_capacity = battery_capacity
        self.screen_size = screen_size
        self.battery_level = battery_capacity  # Initially fully charged
        self.is_powered_on = False

    def power_on(self):
        if not self.is_powered_on:
            self.is_powered_on = True
            print(f"{self.brand} {self.model} is powered on.")
        else:
            print(f"{self.brand} {self.model} is already powered on.")

    def power_off(self):
        if self.is_powered_on:
            self.is_powered_on = False
            print(f"{self.brand} {self.model} is powered off.")
        else:
            print(f"{self.brand} {self.model} is already powered off.")

    def use_battery(self, usage):
        if self.is_powered_on:
            if self.battery_level >= usage:
                self.battery_level -= usage
                print(f"Battery level: {self.battery_level} mAh")
            else:
                print("Not enough battery to perform this action.")
        else:
            print("The phone is powered off. Please power it on.")

    def charge_battery(self, amount):
        if self.battery_level + amount <= self.battery_capacity:
            self.battery_level += amount
            print(f"Battery level: {self.battery_level} mAh")
        else:
            self.battery_level = self.battery_capacity
            print("Battery is fully charged.")

def find_largest_number(numbers):
    if not numbers:
        return "Error: The list is empty."
    largest = numbers[0]
    for number in numbers[1:]:
        if number > largest:
            largest = number
    return largest

def find_smallest_number(numbers):
    if not numbers:
        return "Error: The list is empty."
    smallest = numbers[0]
    for number in numbers[1:]:
        if number < smallest:
            smallest = number
    return smallest

def calculate_average(numbers):
    if not numbers:
        return "Error: The list is empty."
    total_sum = sum(numbers)
    return total_sum / len(numbers)

def calculate_median(numbers):
    if not numbers:
        return "Error: The list is empty."
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    if n % 2 == 1:
        return sorted_numbers[n // 2]
    else:
        return (sorted_numbers[n // 2 - 1] + sorted_numbers[n // 2]) / 2

def calculate_mode(numbers):
    if not numbers:
        return "Error: The list is empty."
    count_dict = {}
    for number in numbers:
        if number in count_dict:
            count_dict[number] += 1
        else:
            count_dict[number] = 1
    max_count = max(count_dict.values())
    mode = [number for number, count in count_dict.items() if count == max_count]
    return mode[0] if len(mode) == 1 else mode

