# Custom reminders added by the user
CUSTOM_REMINDERS = {}

def is_leap_year(year):
    """Check if a year is a leap year."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def validate_date(date_str):
    """Validate the date string and return the date object."""
    try:
        date = datetime.strptime(date_str, "%d %B")
        year = datetime.now().year
        if date.month == 2 and date.day > 29:
            raise InvalidDateError("February can have at most 29 days in a leap year.")
        if date.month == 2 and date.day > 28 and not is_leap_year(year):
            raise InvalidDateError("February can have at most 28 days in a non-leap year.")
        if date.day > calendar.monthrange(year, date.month)[1]:
            raise InvalidDateError(f"Invalid day for the month of {date.strftime('%B')}.")
        return date
    except ValueError:
        raise InvalidDateError("Invalid date format. Please use 'DD Month' format.")

def get_reminder(date):
    """Get the reminder for the given date."""
    month = date.strftime("%B")
    if month in PRE_DEFINED_REMINDERS:
        return PRE_DEFINED_REMINDERS[month]
    if (date.day, month) in CUSTOM_REMINDERS:
        return CUSTOM_REMINDERS[(date.day, month)]
    raise NoReminderError(f"No reminder defined for {date.strftime('%d %B')}.")

def add_custom_reminder(date, reminder):
    """Add a custom reminder for a specific date."""
    CUSTOM_REMINDERS[(date.day, date.strftime("%B"))] = reminder

def main():
    while True:
        date_str = input("Enter the date (DD Month) or 'exit' to quit: ")
        if date_str.lower() == 'exit':
            break
        try:
            date = validate_date(date_str)
            try:
                reminder = get_reminder(date)
                print(f"Reminder for {date_str}: {reminder}")
            except NoReminderError as e:
                print(e)
                add_custom = input("Do you want to add a custom reminder for this date? (yes/no): ")
                if add_custom.lower() == 'yes':
                    custom_reminder = input("Enter the custom reminder: ")
                    add_custom_reminder(date, custom_reminder)
                    print(f"Custom reminder added for {date_str}: {custom_reminder}")
        except InvalidDateError as e:
            print(e)

if __name__ == "__main__":
    main()

import os
import pickle
from typing import List, Tuple
from collections import defaultdict
from datetime import datetime, timedelta

# Persistent storage file
STORAGE_FILE = 'fibfib_persistent_storage.pkl'
# Time to live for pre-calculated values
TTL = timedelta(hours=24)

def load_storage():
    if os.path.exists(STORAGE_FILE):
        with open(STORAGE_FILE, 'rb') as f:
            return pickle.load(f)
    return defaultdict(lambda: {})

def save_storage(storage):
    with open(STORAGE_FILE, 'wb') as f:
        pickle.dump(storage, f)

def fibfib_with_offset(n: int, offset: int):
    if n < 0 or offset < 0:
        raise ValueError("n and offset must be non-negative integers")

    storage = load_storage()
    if (n, offset) in storage:
        value, timestamp = storage[(n, offset)]
        if datetime.now() - timestamp < TTL:
            return value

    if n == 0:
        result = 0
    elif n == 1:
        result = 1
    else:
        result = fibfib_with_offset(n - 1, offset) + fibfib_with_offset(n - 2, offset)

    storage[(n, offset)] = (result, datetime.now())
    save_storage(storage)
    return result

def fibfib_multiple_queries(queries: List[Tuple[int, int]]) -> List[int]:
    if not all(len(query) == 2 and all(isinstance(x, int) and x >= 0 for x in query) for query in queries):
        raise ValueError("Each query must be a tuple of two non-negative integers")

    storage = load_storage()
    results = []

    for a, b in queries:
        if (a, b) in storage:
            value, timestamp = storage[(a, b)]
            if datetime.now() - timestamp < TTL:
                results.append(value)
                continue

        result = fibfib_with_offset(a, b)
        results.append(result)

    return results

def cleanup_storage():
    storage = load_storage()
    current_time = datetime.now()
    keys_to_remove = []

    for key, (value, timestamp) in storage.items():
        if current_time - timestamp > TTL:
            keys_to_remove.append(key)

    for key in keys_to_remove:
        del storage[key]

    save_storage(storage)

# Example usage
if __name__ == "__main__":
    # Calculate fibfib(5, 0)
    print(fibfib_with_offset(5, 0))  # Output: 5

    # Multiple queries
    queries = [(5, 0), (6, 0), (7, 0)]
    results = fibfib_multiple_queries(queries)
    print(results)  # Output: [5, 8, 13]

    # Cleanup storage
    cleanup_storage()

