x, y, z = 100, 0, 50
y_lock = Lock()

def complex_statement(i, y, z):
    if i > z:
        y = i + 20
    else:
        y = i**2 + z
    return y

def complex_statement_two(x, y, z):
    if x == z:
        y = x - 20
    else:
        y = z * 2
    return y

def process_complex_statement(i, y, z):
    with y_lock:
        y = complex_statement(i, y, z)
        print(f"Thread {i}: y = {y}")

def process_complex_statement_two(x, y, z):
