        y = complex_statement_two(x, y, z)
        print(f"Thread {x//10}: y = {y}")

def main():
    global y
    if x > z:
        with ThreadPoolExecutor(max_workers=10) as executor:
            for i in range(x):
                executor.submit(process_complex_statement, i, y, z)
    else:
        with ThreadPoolExecutor(max_workers=10) as executor:
