import socket
import json
import threading

class OCamlCommunicationServer:
    def __init__(self, host='127.0.0.1', port=65432):
        self.host = host
        self.port = port
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen()
        print(f"Server started on {self.host}:{self.port}")

    def start(self):
        while True:
            client_socket, client_address = self.server_socket.accept()
            print(f"Connected by {client_address}")
            client_thread = threading.Thread(target=self.handle_client, args=(client_socket,))
            client_thread.start()

    def handle_client(self, client_socket):
        with client_socket:
            while True:
                message = client_socket.recv(1024)
                if not message:
                    break
                self.execute_command(message)

    def execute_command(self, message):
        try:
            command = json.loads(message)
            if command['type'] == 'command':
                exec(command['data'])
            else:
                print("Unknown command type")
        except Exception as e:
            print(f"Error executing command: {e}")

if __name__ == "__main__":
    server = OCamlCommunicationServer()
    server.start()

from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class Boat(ABC):
    def __init__(self, name, length, capacity):
        self.name = name
        self.length = length
        self.capacity = capacity

    def anchor(self):
        current_time = datetime.now().strftime("%H:%M:%S")
        print(f"Boat {self.name} is anchored at {current_time}")

    def sail(self, destination, distance):
        # Assuming a constant average speed of 10 knots for the boat
        average_speed = 10  # knots
        estimated_time = distance / average_speed
        eta = datetime.now() + timedelta(hours=estimated_time)
        eta_formatted = eta.strftime("%H:%M:%S")
        print(f"Boat {self.name} is sailing to {destination} and is expected to arrive at {eta_formatted}")

    @abstractmethod
    def additional_feature(self):
        pass

class MotorBoat(Boat):
    def __init__(self, name, length, capacity, fuel_capacity, engine_power):
        super().__init__(name, length, capacity)
        self.fuel_capacity = fuel_capacity
        self.engine_power = engine_power

    def start_engine(self):
        print(f"Engine of MotorBoat {self.name} started with {self.engine_power} horsepower")

    def refuel(self, amount):
        if amount > 0:
            self.fuel_capacity += amount
            print(f"MotorBoat {self.name} refueled with {amount} liters. Current fuel: {self.fuel_capacity} liters")
        else:
            print("Refueling amount must be positive")

    def additional_feature(self):
        print(f"MotorBoat {self.name} has an engine with {self.engine_power} horsepower and a fuel capacity of {self.fuel_capacity} liters")

