from typing import List, Tuple, Union, Dict
from threading import Lock
import time

class Account:
    def __init__(self, account_number: int):
        self.account_number = account_number
        self.balance = 0
        self.lock = Lock()

    def deposit(self, amount: int) -> bool:
        if amount < 0:
            return False
        with self.lock:
            self.balance += amount
        return True

    def withdraw(self, amount: int) -> bool:
        if amount < 0 or amount > self.balance:
            return False
        with self.lock:
            self.balance -= amount
        return True

class Bank:
    def __init__(self):
        self.accounts: Dict[int, Account] = {}
        self.lock = Lock()

    def get_account(self, account_number: int) -> Union[Account, None]:
        with self.lock:
            return self.accounts.get(account_number)

    def create_account(self, account_number: int) -> Account:
        with self.lock:
            if account_number not in self.accounts:
                self.accounts[account_number] = Account(account_number)
            return self.accounts[account_number]

def account_transactions(accounts_transactions: List[Tuple[int, str, int]]) -> Union[bool, str, List[int]]:
    bank = Bank()
    error_indices = []
    error_messages = []

    for index, (account_number, operation, amount) in enumerate(accounts_transactions):
        account = bank.get_account(account_number)
        if account is None:
            account = bank.create_account(account_number)

        if operation == 'Deposit':
            if not account.deposit(amount):
                error_indices.append(index)
                error_messages.append(f"Invalid deposit amount for account {account_number}.")
        elif operation == 'Withdrawal':
            if not account.withdraw(amount):
                error_indices.append(index)
                error_messages.append(f"Invalid withdrawal amount for account {account_number}.")
        else:
            error_indices.append(index)
            error_messages.append(f"Invalid operation type for account {account_number}.")

    if error_indices:
        return f"Errors encountered: {', '.join(error_messages)}", error_indices

    for account in bank.accounts.values():
        if account.balance < 0:
            return True

    return False

# Examples
print(account_transactions([(1, 'Deposit', 1), (2, 'Deposit', 2), (1, 'Deposit', 3), (2, 'Withdrawal', 4)]))
print(account_transactions([(1, 'Deposit', 5), (1, 'Withdrawal', 6), (1, 'Deposit', 1), (1, 'Withdrawal', 2)]))
print(account_transactions([(3, 'Deposit', -10), (4, 'Deposit', -5)]))

class DiscountCalculatorError(Exception):
    """Base class for exceptions in this module."""
    pass

class InvalidPriceError(DiscountCalculatorError):
    """Exception raised for non-numeric or negative price."""
    def __init__(self, price):
        self.price = price
        super().__init__(f"Invalid price: {price}. Price must be a non-negative number.")

class InvalidCashCouponError(DiscountCalculatorError):
    """Exception raised for non-numeric or negative cash coupon."""
    def __init__(self, cash_coupon):
        self.cash_coupon = cash_coupon
        super().__init__(f"Invalid cash coupon: {cash_coupon}. Cash coupon must be a non-negative number.")

class InvalidPercentageCouponError(DiscountCalculatorError):
    """Exception raised for non-numeric or out-of-range percentage coupon."""
    def __init__(self, percentage_coupon):
        self.percentage_coupon = percentage_coupon
        super().__init__(f"Invalid percentage coupon: {percentage_coupon}. Percentage coupon must be a number between 0 and 100.")

class DiscountCalculator:
    def __init__(self, price, cash_coupon, percentage_coupon):
        self.validate_inputs(price, cash_coupon, percentage_coupon)
        self.price = price
        self.cash_coupon = cash_coupon
        self.percentage_coupon = percentage_coupon

    def validate_inputs(self, price, cash_coupon, percentage_coupon):
        try:
            price = float(price)
            cash_coupon = float(cash_coupon)
            percentage_coupon = float(percentage_coupon)
        except ValueError:
            raise ValueError("All inputs must be numeric.")

        if price < 0:
            raise InvalidPriceError(price)
        if cash_coupon < 0:
            raise InvalidCashCouponError(cash_coupon)
        if not (0 <= percentage_coupon <= 100):
            raise InvalidPercentageCouponError(percentage_coupon)

    def calculate_discount(self):
        discounted_price = max(0, self.price - self.cash_coupon)
        final_price = discounted_price * (100 - self.percentage_coupon) / 100
        return final_price

# Test cases
if __name__ == "__main__":
    try:
        # Valid input
        calculator = DiscountCalculator(100, 20, 10)
