# Define the thesaurus
thesaurus = {
    'happy': ['joyful', 'content', 'pleased'],
    'sad': ['unhappy', 'miserable', 'sorrowful'],
    'pleased': ['satisfied'],
    'unhappy': ['miserable']
}

# 1. Show the number of synonyms each word in the thesaurus has.
def show_synonym_counts(thesaurus):
    for word, synonyms in thesaurus.items():
        print(f"{word} has {len(synonyms)} synonyms.")

# 2. List all synonyms for each word.
def list_synonyms(thesaurus):
    for word, synonyms in thesaurus.items():
        print(f"{word}: {', '.join(synonyms)}")

# 3. Find and display words that share at least one synonym.
def find_shared_synonyms(thesaurus):
    shared_synonyms = {}
    for word1, synonyms1 in thesaurus.items():
        for word2, synonyms2 in thesaurus.items():
            if word1 != word2 and set(synonyms1) & set(synonyms2):
                shared_synonyms.setdefault(word1, []).append(word2)

    for word, shared_words in shared_synonyms.items():
        print(f"{word} shares synonyms with: {', '.join(shared_words)}")

# 4. Find and display a 'synonym path' from a specified word to another specified word.
def find_synonym_path(thesaurus, start_word, end_word):
    # Create a graph from the thesaurus
    graph = {}
    for word, synonyms in thesaurus.items():
        graph[word] = set(synonyms)
        for synonym in synonyms:
            if synonym not in graph:
                graph[synonym] = set()
            graph[synonym].add(word)

    # BFS to find the path
    from collections import deque
    queue = deque([(start_word, [start_word])])
    visited = set([start_word])

    while queue:
        current_word, path = queue.popleft()
        if current_word == end_word:
            return path
        for neighbor in graph.get(current_word, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))

    return None

# Example usage
if __name__ == "__main__":
    # 1. Show the number of synonyms each word in the thesaurus has.
    print("Number of synonyms for each word:")
    show_synonym_counts(thesaurus)
    print()

    # 2. List all synonyms for each word.
    print("List of synonyms for each word:")
    list_synonyms(thesaurus)
    print()

    # 3. Find and display words that share at least one synonym.
    print("Words that share at least one synonym:")
    find_shared_synonyms(thesaurus)
    print()

    # 4. Find and display a 'synonym path' from a specified word to another specified word.
    start_word = 'happy'
    end_word = 'sorrowful'
    path = find_synonym_path(thesaurus, start_word, end_word)
    if path:
        print(f"Synonym path from '{start_word}' to '{end_word}': {', '.join(path)}")
    else:
        print(f"No synonym path found from '{start_word}' to '{end_word}'")

import requests
from bs4 import BeautifulSoup
from collections import Counter
import re

def fetch_webpage(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        print(f"Error fetching the webpage: {e}")
        return None

def extract_urls(html_content, keyword, exclude_phrase):
    soup = BeautifulSoup(html_content, 'html.parser')
    urls = []
    for link in soup.find_all('a', href=True):
        href = link['href']
        if keyword in href and exclude_phrase not in href:
            urls.append(href)
    return urls

def count_keyword_occurrences(urls, keyword):
    url_counts = Counter()
    for url in urls:
        count = len(re.findall(re.escape(keyword), url, re.IGNORECASE))
        if count > 0:
            url_counts[url] = count
    return url_counts

def filter_and_sort_urls(url_counts, min_occurrences):
    filtered_urls = {url: count for url, count in url_counts.items() if count > min_occurrences}
    sorted_urls = sorted(filtered_urls.items(), key=lambda x: x[1], reverse=True)
    return sorted_urls

def main():
    url = 'http://www.example.com'
    keyword = 'technology'
    exclude_phrase = 'advertisement'
    min_occurrences = 5

    html_content = fetch_webpage(url)
    if html_content:
        urls = extract_urls(html_content, keyword, exclude_phrase)
        url_counts = count_keyword_occurrences(urls, keyword)
        sorted_urls = filter_and_sort_urls(url_counts, min_occurrences)

        for url, count in sorted_urls:
            print(f"URL: {url}, Keyword Occurrences: {count}")

if __name__ == "__main__":
    main()

import json
import re
from datetime import datetime, timedelta

# Sample JSON data
json_data = '''
{
    "users": [
        {
            "name": "John Doe",
            "code": "Abc123",
            "used": true,
            "last_active": "2023-10-01T12:00:00Z"
        },
        {
            "name": "Jane Smith",
            "code": "Def456",
            "used": false,
            "last_active": "2023-09-01T12:00:00Z"
        },
        {
            "name": "Alice Johnson",
            "code": "Ghi789",
            "used": true,
            "last_active": "2023-11-01T12:00:00Z"
        }
    ]
}
'''

# Load JSON data
data = json.loads(json_data)

# Define the list of special characters
special_characters = ['!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '-', '+', '=', '{', '}', '[', ']', '|', '\\', ':', ';', '<', '>', '?', '/', '.', ',', '~', '`']

# Function to validate name format
def is_valid_name(name):
    return bool(re.match(r'^[A-Za-z\s]+$', name))

# Function to check if a code contains at least one special character
def contains_special_character(code, special_characters):
    return any(char in code for char in special_characters)

# Function to determine if a user is active
def is_active(last_active):
    last_active_date = datetime.fromisoformat(last_active.replace('Z', '+00:00'))
    one_month_ago = datetime.now() - timedelta(days=30)
    return last_active_date > one_month_ago

# Process each user
for user in data['users']:
    # Validate name and add email field
    if is_valid_name(user['name']):
        user['email'] = f"{user['name'].replace(' ', '').lower()}@example.com"
    else:
        print(f"Invalid name format for user: {user['name']}")

    # Check code for special characters
    if not contains_special_character(user['code'], special_characters):
        print(f"Code for user {user['name']} does not contain a special character. Please update the code.")

    # Update status field
    user['status'] = 'active' if is_active(user['last_active']) else 'inactive'
    del user['used']  # Remove the 'used' field

# Output the modified JSON data
print(json.dumps(data, indent=4))

from flask import Flask, request, jsonify
   from flask_sqlalchemy import SQLAlchemy
   from flask_marshmallow import Marshmallow

   app = Flask(__name__)
   app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///items.db'
   app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

   db = SQLAlchemy(app)
   ma = Marshmallow(app)

   class Item(db.Model):
       id = db.Column(db.Integer, primary_key=True)
       name = db.Column(db.String(100), unique=True, nullable=False)
       description = db.Column(db.String(200))

       def __init__(self, name, description):
           self.name = name
           self.description = description

   class ItemSchema(ma.Schema):
       class Meta:
           fields = ('id', 'name', 'description')

   item_schema = ItemSchema()
   items_schema = ItemSchema(many=True)

   @app.route('/items', methods=['POST'])
   def add_item():
       name = request.json['name']
       description = request.json['description']
       new_item = Item(name, description)
       db.session.add(new_item)
       db.session.commit()
       return item_schema.jsonify(new_item), 201

   @app.route('/items', methods=['GET'])
   def get_items():
       all_items = Item.query.all()
       result = items_schema.dump(all_items)
       return jsonify(result)

   @app.route('/items/<id>', methods=['GET'])
   def get_item(id):
       item = Item.query.get(id)
       if item is None:
           return jsonify({'message': 'Item not found'}), 404
       return item_schema.jsonify(item)

   @app.route('/items/<id>', methods=['PUT'])
   def update_item(id):
       item = Item.query.get(id)
       if item is None:
           return jsonify({'message': 'Item not found'}), 404
       name = request.json['name']
       description = request.json['description']
       item.name = name
       item.description = description
       db.session.commit()
       return item_schema.jsonify(item)

   @app.route('/items/<id>', methods=['DELETE'])
   def delete_item(id):
       item = Item.query.get(id)
       if item is None:
           return jsonify({'message': 'Item not found'}), 404
       db.session.delete(item)
       db.session.commit()
       return item_schema.jsonify(item)

   if __name__ == '__main__':
       db.create_all()
       app.run(debug=True)

import math
from contextlib import contextmanager

class Triangle:
    count = 0  # Class attribute to keep track of the number of Triangle objects created

    def __init__(self, side1, side2, side3):
        if not self._is_valid_triangle(side1, side2, side3):
            raise ValueError("Invalid triangle sides")
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3
        Triangle.count += 1

    def _is_valid_triangle(self, side1, side2, side3):
        return side1 > 0 and side2 > 0 and side3 > 0 and \
               side1 + side2 > side3 and side1 + side3 > side2 and side2 + side3 > side1

    def get_perimeter(self):
        return self.side1 + self.side2 + self.side3

    def get_area(self):
        return self._recursive_area(self.side1, self.side2, self.side3)

    def _recursive_area(self, a, b, c, depth=0):
        if depth > 100:  # Prevent infinite recursion
            raise RecursionError("Recursion depth exceeded")
        s = (a + b + c) / 2
        if s - a <= 0 or s - b <= 0 or s - c <= 0:
            return 0
        area = math.sqrt(s * (s - a) * (s - b) * (s - c))
        return area

    @property
    def is_equilateral(self):
        return self.side1 == self.side2 == self.side3

    @property
    def is_isosceles(self):
        return self.side1 == self.side2 or self.side1 == self.side3 or self.side2 == self.side3

    @contextmanager
    def resize(self, new_side1, new_side2, new_side3):
        if not self._is_valid_triangle(new_side1, new_side2, new_side3):
            print("Error: New sides do not form a valid triangle")
            yield False
        else:
            old_sides = (self.side1, self.side2, self.side3)
            self.side1, self.side2, self.side3 = new_side1, new_side2, new_side3
            yield True
            self.side1, self.side2, self.side3 = old_sides

# Example usage:
try:
    t1 = Triangle(3, 4, 5)
    print(f"Perimeter: {t1.get_perimeter()}")
    print(f"Area: {t1.get_area()}")
    print(f"Is equilateral: {t1.is_equilateral}")
    print(f"Is isosceles: {t1.is_isosceles}")

    with t1.resize(5, 5, 5) as success:
        if success:
            print(f"Resized to equilateral: {t1.is_equilateral}")
        else:
            print("Failed to resize")

