# Function to get an access token
def get_access_token(client_id, client_secret):
    url = 'https://accounts.spotify.com/api/token'
    headers = {
        'Content-Type': 'application/x-www-form-urlencoded'
    }
    data = {
        'grant_type': 'client_credentials',
        'client_id': client_id,
        'client_secret': client_secret
    }
    response = requests.post(url, headers=headers, data=data)
    if response.status_code == 200:
        return response.json()['access_token']
    else:
        raise Exception('Could not get access token: {}'.format(response.text))

# Function to search for a song
def search_song(token, song_name, artist_name):
    url = 'https://api.spotify.com/v1/search'
    headers = {
        'Authorization': 'Bearer {}'.format(token)
    }
    params = {
        'q': 'track:{} artist:{}'.format(song_name, artist_name),
        'type': 'track',
        'limit': 1
    }
    response = requests.get(url, headers=headers, params=params)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception('Could not search for the song: {}'.format(response.text))

# Function to get audio features of a song
def get_audio_features(token, track_id):
    url = 'https://api.spotify.com/v1/audio-features/{}'.format(track_id)
    headers = {
        'Authorization': 'Bearer {}'.format(token)
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception('Could not get audio features: {}'.format(response.text))

# Function to classify the song based on audio features
def classify_song(audio_features):
    # Define some heuristic rules based on typical audio features of genres
    if audio_features['energy'] > 0.8 and audio_features['loudness'] > -6.0:
        return 'rock'
    elif audio_features['acousticness'] > 0.5 and audio_features['instrumentalness'] > 0.5:
        return 'country'
    elif audio_features['speechiness'] > 0.3 and audio_features['tempo'] > 100:
        return 'hip-hop'
    else:
        return 'pop'

# Main function
