def process_instruction(instruction, wires):
    tokens = instruction.split()
    if 'AND' in tokens:
        left, _, right, _, dest = tokens
        if left.isdigit() and right in wires:
            wires[dest] = int(left) & wires[right]
        elif left in wires and right in wires:
            wires[dest] = wires[left] & wires[right]
    elif 'OR' in tokens:
        left, _, right, _, dest = tokens
        if left in wires and right in wires:
            wires[dest] = wires[left] | wires[right]
    elif 'LSHIFT' in tokens:
        src, _, value, _, dest = tokens
        if src in wires:
            wires[dest] = wires[src] << int(value)
    elif 'RSHIFT' in tokens:
        src, _, value, _, dest = tokens
        if src in wires:
            wires[dest] = wires[src] >> int(value)
    elif 'NOT' in tokens:
        _, src, _, dest = tokens
        if src in wires:
            wires[dest] = ~wires[src] & 0xFFFF
    else:
        src, _, dest = tokens
        if src.isdigit():
            wires[dest] = int(src)
        elif src in wires:
            wires[dest] = wires[src]

def assemble_circuit(instructions):
    wires = {}
    while instructions:
        instruction = instructions.pop(0)
        process_instruction(instruction, wires)
        if not set(instruction.split()) & set(wires.keys()) == set(instruction.split()):
            instructions.append(instruction)
    return wires['a']

