import re
from typing import List

class Customer:
    def __init__(self, name: str, email: str, phone: str):
        self._name = None
        self._email = None
        self._phone = None
        self.set_name(name)
        self.set_email(email)
        self.set_phone(phone)

    def get_name(self) -> str:
        return self._name

    def set_name(self, name: str):
        if not name.isalpha():
            raise ValueError("Name should only contain alphabetical characters.")
        self._name = name

    def get_email(self) -> str:
        return self._email

    def set_email(self, email: str):
        if not re.match(r"[^@]+@[^@]+\.[^@]+", email):
            raise ValueError("Invalid email address format.")
        self._email = email

    def get_phone(self) -> str:
        return self._phone

    def set_phone(self, phone: str):
        if not re.match(r"^\+?\d{10,15}$", phone):
            raise ValueError("Invalid phone number format.")
        self._phone = phone

    def display_info(self):
        print(f"Name: {self._name}")
        print(f"Email: {self._email}")
        print(f"Phone: {self._phone}")

    @staticmethod
    def sort_customers(customers: List['Customer']) -> List['Customer']:
        return sorted(customers, key=lambda customer: customer.get_name())

    @staticmethod
    def filter_by_domain(customers: List['Customer'], domain: str) -> List['Customer']:
        return [customer for customer in customers if customer.get_email().endswith(f"@{domain}")]

# Example usage
