def encode_cyclic(s: str, group_size: int = 5, alphabet: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    This function implements a cyclic shift to groups of 'group_size' subsequent characters.
    It handles unique characters and empty spaces, and processes larger inputs without performance drop.
    """
    if not s:
        return ""

    # Ensure the alphabet is unique
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain unique characters")

    # Map each character in the alphabet to its index
    char_to_index = {char: idx for idx, char in enumerate(alphabet)}

    # Encode the string
    encoded = []
    for i in range(0, len(s), group_size):
        group = s[i:i + group_size]
        encoded_group = ""
        for char in group:
            if char in char_to_index:
                new_index = (char_to_index[char] + group_size) % len(alphabet)
                encoded_group += alphabet[new_index]
            else:
                encoded_group += char  # Non-alphabet characters are not encoded
        encoded.append(encoded_group)

    return "".join(encoded)

def decode_cyclic(s: str, group_size: int = 5, alphabet: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    This function takes an encoded string from the encode_cyclic function and retrieves its original form.
    It handles unique characters and empty spaces, and processes larger inputs without performance drop.
    """
    if not s:
        return ""

    # Ensure the alphabet is unique
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain unique characters")

    # Map each character in the alphabet to its index
    char_to_index = {char: idx for idx, char in enumerate(alphabet)}

    # Decode the string
    decoded = []
    for i in range(0, len(s), group_size):
        group = s[i:i + group_size]
        decoded_group = ""
        for char in group:
            if char in char_to_index:
                new_index = (char_to_index[char] - group_size) % len(alphabet)
                decoded_group += alphabet[new_index]
            else:
                decoded_group += char  # Non-alphabet characters are not decoded
        decoded.append(decoded_group)

    return "".join(decoded)

# Example usage:
if __name__ == "__main__":
    original_text = "Hello, World! This is a test."
    encoded_text = encode_cyclic(original_text, group_size=5, alphabet="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    print(f"Encoded: {encoded_text}")

    decoded_text = decode_cyclic(encoded_text, group_size=5, alphabet="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    print(f"Decoded: {decoded_text}")

