import re

class HTMLValidator:
    def __init__(self):
        self.tag_stack = []
        self.errors = []
        self.line_number = 1
        self.position = 1

    def validate(self, html):
        self.errors = []
        self.line_number = 1
        self.position = 1
        self.parse(html)
        return self.errors

    def parse(self, html):
        tag_pattern = re.compile(r'<(/?[\w-]+)([^>]*?)>')
        attribute_pattern = re.compile(r'(\w+)(?:\s*=\s*([\'"])(.*?)\2)?')
        boolean_attributes = {'checked', 'disabled', 'selected', 'readonly', 'required'}

        while html:
            match = tag_pattern.search(html)
            if not match:
                break

            start, end = match.span()
            tag, attributes = match.groups()

            # Update line and position
            self.position += start
            self.line_number += html[:start].count('\n')

            if tag.startswith('/'):
                self.close_tag(tag[1:])
            else:
                self.open_tag(tag, attributes, attribute_pattern, boolean_attributes)

            html = html[end:]
            self.position += end - start

        if self.tag_stack:
            self.add_error(f"Unclosed tags: {', '.join([tag for tag, _ in self.tag_stack])}")

    def open_tag(self, tag, attributes, attribute_pattern, boolean_attributes):
        if tag in boolean_attributes:
            self.add_error(f"Boolean attribute used as a tag: <{tag}> at line {self.line_number}, position {self.position}")
            return

        self.tag_stack.append((tag, self.line_number))

        for attr, value in attribute_pattern.findall(attributes):
            if not attr.isalnum():
                self.add_error(f"Invalid attribute name: {attr} at line {self.line_number}, position {self.position}")

            if attr in boolean_attributes and value is not None:
                self.add_error(f"Boolean attribute {attr} should not have a value at line {self.line_number}, position {self.position}")

            if value is None and attr not in boolean_attributes:
                self.add_error(f"Attribute {attr} requires a value at line {self.line_number}, position {self.position}")

    def close_tag(self, tag):
        if not self.tag_stack:
            self.add_error(f"Unexpected closing tag: </{tag}> at line {self.line_number}, position {self.position}")
            return

        if self.tag_stack[-1][0] != tag:
            self.add_error(f"Expected closing tag: </{self.tag_stack[-1][0]}> but found </{tag}> at line {self.line_number}, position {self.position}")
            return

        self.tag_stack.pop()

    def add_error(self, message):
        self.errors.append((self.line_number, self.position, message))

def test_validator():
    validator = HTMLValidator()
    test_cases = [
        ("<b>hello</b>", []),
        ("<b>hello</p>", [(1, 12, "Expected closing tag: </b> but found </p> at line 1, position 12")]),
        ("<p><b>hello</b></p>", []),
        ("<p><b>hello</p></b>", [(1, 16, "Expected closing tag: </b> but found </p> at line 1, position 16")]),
        ("<p class='test'>hello</p>", []),
        ("<p class=321>hello</p>", [(1, 4, "Invalid attribute name: class at line 1, position 4")]),
        ("<p class=''>hello</p>", [(1, 4, "Attribute class requires a value at line 1, position 4")]),
        ("<p checked>hello</p>", []),
        ("<p checked='true'>hello</p>", [(1, 4, "Boolean attribute checked should not have a value at line 1, position 4")]),
        ("<script>alert('XSS')</script>", [(1, 1, "Potential security vulnerability: <script> tag at line 1, position 1")]),
        ("<div><p>hello</div>", [(1, 16, "Unclosed tags: p")])
    ]

    for html, expected_errors in test_cases:
        errors = validator.validate(html)
        assert errors == expected_errors, f"Failed for input: {html}. Expected: {expected_errors}, Got: {errors}"

if __name__ == "__main__":
    test_validator()
    print("All tests passed!")

