from PyQt5.QtWidgets import QStyledItemDelegate, QStyleOptionViewItem, QApplication, QWidget, QVBoxLayout, QTableView
from PyQt5.QtGui import QPainter, QCursor, QDesktopServices
from PyQt5.QtCore import Qt, QEvent, QModelIndex, QUrl
import sys

class HyperlinkDelegate(QStyledItemDelegate):
    def __init__(self, parent=None):
        super(HyperlinkDelegate, self).__0init__(parent)
        self._links = {}

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex):
        if index.column() == 1:  # Assuming the column with hyperlinks is column 1
            text = index.data(Qt.DisplayRole)
            links = index.data(Qt.UserRole)

            if links:
                self._links[index] = links

                # Draw the background
                painter.save()
                painter.setRenderHint(QPainter.Antialiasing, True)
                if option.state & QStyle.State_Selected:
                    painter.fillRect(option.rect, option.palette.highlight())
                painter.restore()

                # Draw the hyperlinks
                for link in links:
                    text_rect = painter.fontMetrics().boundingRect(option.rect, Qt.TextWordWrap, link['text'])
                    link_rect = option.rect.adjusted(0, 0, -option.rect.width() + text_rect.width(), 0)
                    painter.setPen(Qt.blue)
                    painter.drawText(link_rect, Qt.TextWordWrap, link['text'])

                    # Underline the text
                    painter.setPen(Qt.blue)
                    painter.drawLine(link_rect.bottomLeft(), link_rect.bottomRight())

                painter.restore()
            else:
                super().paint(painter, option, index)
        else:
            super().paint(painter, option, index)

    def editorEvent(self, event: QEvent, model: QAbstractItemModel, option: QStyleOptionViewItem, index: QModelIndex):
        if event.type() == QEvent.MouseButtonRelease and index.column() == 1:
            if index in self._links:
                links = self._links[index]
                for link in links:
                    text_rect = self.style().itemTextRect(option.fontMetrics, option.rect, Qt.AlignLeft, True, link['text'])
                    if text_rect.contains(event.pos()):
                        QDesktopServices.openUrl(QUrl(link['url']))
                        return True
        return super().editorEvent(event, model, option, index)

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex):
        if index.column() == 1:
            links = index.data(Qt.UserRole)
            if links:
                max_height = max(self.style().itemTextRect(option.fontMetrics, option.rect, Qt.AlignLeft, True, link['text']).height() for link in links)
                return QSize(option.rect.width(), max_height)
        return super().sizeHint(option, index)

def advanced_monotonic(l: list, strict: bool = False):
    """
    Return True if list elements rise or fall monotonically, while taking into account the strictness criteria as well as probable non-integer or non-floating-point elements.
    If strict is made True, neighbouring elements must differ; otherwise, they could be alike.

    >>> advanced_monotonic([1, "2", 4, 20])
    True
    >>> advanced_monotonic([1, 20, None, 4, 10])
    False
    >>> advanced_monotonic([4, 1, "1", 0, -10], strict=True)
    False
    >>> advanced_monotonic([1, 1, "one", 1, 1], strict=False)
    True
    """
    def is_number(x):
        return isinstance(x, (int, float))

    # Filter out non-integer and non-floating-point elements
    filtered_list = [x for x in l if is_number(x)]

    if len(filtered_list) < 2:
        return True  # A list with fewer than 2 valid numbers is trivially monotonic

    increasing = None
    for i in range(len(filtered_list) - 1):
        if filtered_list[i] < filtered_list[i + 1]:
            if increasing is None:
                increasing = True
            elif not increasing:
                return False
        elif filtered_list[i] > filtered_list[i + 1]:
            if increasing is None:
                increasing = False
            elif increasing:
                return False
        elif strict:
            return False  # Neighbours must differ if strict is True

    return True

# Test cases
print(advanced_monotonic([1, "2", 4, 20]))  # True
print(advanced_monotonic([1, 20, None, 4, 10]))  # False
print(advanced_monotonic([4, 1, "1", 0, -10], strict=True))  # False
print(advanced_monotonic([1, 1, "one", 1, 1], strict=False))  # True

def print_board(board):
    for row in board:
        print(" | ".join(row))
        print("-" * 5)

def check_winner(board, player):
    # Check rows
    for row in board:
        if all([cell == player for cell in row]):
            return True
    # Check columns
    for col in range(3):
        if all([board[row][col] == player for row in range(3)]):
            return True
    # Check diagonals
    if all([board[i][i] == player for i in range(3)]) or all([board[i][2 - i] == player for i in range(3)]):
        return True
    return False

def is_full(board):
    return all([cell != ' ' for row in board for cell in row])

def main():
    board = [[' ' for _ in range(3)] for _ in range(3)]
    current_player = 'X'

    while True:
        print_board(board)
        print(f"Player {current_player}'s turn")
        row = int(input("Enter the row (0, 1, or 2): "))
        col = int(input("Enter the column (0, 1, or 2): "))

        if board[row][col] != ' ':
            print("This cell is already taken, try again.")
            continue

        board[row][col] = current_player

        if check_winner(board, current_player):
            print_board(board)
            print(f"Player {current_player} wins!")
            break

        if is_full(board):
            print_board(board)
            print("The game is a draw!")
            break

        current_player = 'O' if current_player == 'X' else 'X'

if __name__ == "__main__":
    main()

