import math

def find_exponent(input_value):
    if input_value < 2:
        return None  # No valid base and exponent for input values less than 2

    max_base = int(math.sqrt(input_value)) + 1  # Upper limit for base
    for base in range(2, max_base):
        exponent = int(math.log(input_value, base))
        if base ** exponent == input_value:
            return base, exponent
        if base ** (exponent + 1) == input_value:
            return base, exponent + 1
    return None

