import cx_Oracle
import sys

def connect_to_database(username, password, dsn):
    try:
        db = cx_Oracle.connect(username, password, dsn)
        print("Connected to the database")
        return db
    except cx_Oracle.DatabaseError as e:
        error, = e.args
        if error.code == 1017:
            print('Please check your credentials.')
        else:
            print('Database connection error: %s'.format(e))
        sys.exit(1)  # Terminate the script if connection fails

def execute_ddl_statements(db, ddl_statements):
    cursor = db.cursor()
    try:
        cursor.execute(ddl_statements)
    except cx_Oracle.DatabaseError as e:
        error, = e.args
        if error.code == 955:
            print('Table already exists')
        elif error.code == 1031:
            print("Insufficient privileges - are you sure you're using the owner account?")
        else:
            print(f"Database error: {error.code} - {error.message}")
        cursor.close()
        db.rollback()  # Rollback any changes in case of an error
        raise  # Re-raise the exception to be handled by the calling code
    cursor.close()
    db.commit()

