def process_input(input_list: [str]):
    grid = [[0 for _ in range(1000)] for _ in range(1000)]

    for instruction in input_list:
        action, pos1, pos2 = parse_instruction(instruction)
        apply_action(grid, action, pos1, pos2)

    return grid

def parse_instruction(instruction: str):
    parts = instruction.split()

    if parts[0] == 'turn':
        action = parts[1]
        start = tuple(map(int, parts[2].split(',')))
        end = tuple(map(int, parts[4].split(',')))

    else:  # toggle
        action = 'toggle'
        start = tuple(map(int, parts[1].split(',')))
        end = tuple(map(int, parts[3].split(',')))

    return action, start, end


def apply_action(grid, action, pos1, pos2):
