class InvalidArgumentError(Exception):
    def __init__(self, message="Invalid argument provided. Only positive integers greater than 10 are allowed."):
        self.message = message
        super().__init__(self.message)

def calculate_average(*args):
    total = 0
    count = 0

    for arg in args:
        if not isinstance(arg, int) or arg <= 0:
            raise InvalidArgumentError(f"Invalid argument: {arg}")
        if arg > 10:
            total += arg
            count += 1

    if count == 0:
        return 0
    average = total / count
    return average

def recommend_dish(available_ingredients, dishes):
    # Convert available ingredients to a dictionary for easier manipulation
    available = {ingredient: int(quantity.split()[0]) for ingredient, quantity in available_ingredients.items()}

    # Initialize variables to store the best match and remaining ingredients
    best_match = None
    remaining_ingredients = {}

    for dish_name, required_ingredients in dishes.items():
        can_make = True
        remaining = available.copy()

        for ingredient, required_quantity in required_ingredients.items():
            if ingredient not in available or available[ingredient] < required_quantity:
                can_make = False
                break
            else:
                remaining[ingredient] -= required_quantity

        if can_make:
            best_match = dish_name
            remaining_ingredients = {k: v for k, v in remaining.items() if v > 0}
            break

    return best_match, remaining_ingredients

