from typing import List, Union
from collections import defaultdict

class Term:
    def __init__(self, coefficient: int, exponent: int):
        self.coefficient = coefficient
        self.exponent = exponent

    def __add__(self, other: 'Term') -> 'Term':
        if self.exponent == other.exponent:
            return Term(self.coefficient + other.coefficient, self.exponent)
        else:
            raise ValueError("Terms must have the same exponent to be added")

    def __sub__(self, other: 'Term') -> 'Term':
        if self.exponent == other.exponent:
            return Term(self.coefficient - other.coefficient, self.exponent)
        else:
            raise ValueError("Terms must have the same exponent to be subtracted")

    def __mul__(self, other: Union['Term', int]) -> 'Term':
        if isinstance(other, Term):
            return Term(self.coefficient * other.coefficient, self.exponent + other.exponent)
        elif isinstance(other, int):
            return Term(self.coefficient * other, self.exponent)
        else:
            raise TypeError("Unsupported type for multiplication")

    def __truediv__(self, other: Union['Term', int]) -> 'Term':
        if isinstance(other, Term):
            if other.coefficient == 0:
                raise ZeroDivisionError("Division by zero")
            return Term(self.coefficient // other.coefficient, self.exponent - other.exponent)
        elif isinstance(other, int):
            return Term(self.coefficient // other, self.exponent)
        else:
            raise TypeError("Unsupported type for division")

    def __str__(self) -> str:
        if self.coefficient == 0:
            return "0"
        elif self.exponent == 0:
            return str(self.coefficient)
        elif self.exponent == 1:
            return f"{self.coefficient}x"
        else:
            return f"{self.coefficient}x^{self.exponent}"

    def __repr__(self) -> str:
        return self.__str__()

class Polynomial:
    def __init__(self, terms: List[Term] = None):
        self.terms = defaultdict(int)
        if terms:
            for term in terms:
                self.terms[term.exponent] += term.coefficient

    def __add__(self, other: 'Polynomial') -> 'Polynomial':
        result = Polynomial()
        for exponent, coefficient in self.terms.items():
            result.terms[exponent] += coefficient
        for exponent, coefficient in other.terms.items():
            result.terms[exponent] += coefficient
        return result

    def __sub__(self, other: 'Polynomial') -> 'Polynomial':
        result = Polynomial()
        for exponent, coefficient in self.terms.items():
            result.terms[exponent] += coefficient
        for exponent, coefficient in other.terms.items():
            result.terms[exponent] -= coefficient
        return result

    def __mul__(self, other: Union['Polynomial', int]) -> 'Polynomial':
        if isinstance(other, Polynomial):
            result = Polynomial()
            for exp1, coeff1 in self.terms.items():
                for exp2, coeff2 in other.terms.items():
                    result.terms[exp1 + exp2] += coeff1 * coeff2
            return result
        elif isinstance(other, int):
            result = Polynomial()
            for exponent, coefficient in self.terms.items():
                result.terms[exponent] = coefficient * other
            return result
        else:
            raise TypeError("Unsupported type for multiplication")

    def __truediv__(self, other: Union['Polynomial', int]) -> 'Polynomial':
        if isinstance(other, Polynomial):
            if len(other.terms) > 1:
                raise ValueError("Division by a polynomial with more than one term is not supported")
            divisor = list(other.terms.values())[0]
            if divisor == 0:
                raise ZeroDivisionError("Division by zero")
            result = Polynomial()
            for exponent, coefficient in self.terms.items():
                result.terms[exponent] = coefficient // divisor
            return result
        elif isinstance(other, int):
            result = Polynomial()
            for exponent, coefficient in self.terms.items():
                result.terms[exponent] = coefficient // other
            return result
        else:
            raise TypeError("Unsupported type for division")

    def evaluate(self, x: int) -> int:
        result = 0
        for exponent, coefficient in self.terms.items():
            result += coefficient * (x ** exponent)
        return result

    def __str__(self) -> str:
        terms = [f"{Term(coefficient, exponent)}" for exponent, coefficient in sorted(self.terms.items(), reverse=True) if coefficient != 0]
        return " + ".join(terms) if terms else "0"

    def __repr__(self) -> str:
        return self.__str__()

# Example usage
p1 = Polynomial([Term(3, 3), Term(4, 1), Term(-2, 0)])
p2 = Polynomial([Term(5, 3), Term(-10, 2), Term(1, 1), Term(1, 0)])

print("p1:", p1)
