import heapq
from collections import defaultdict

class Node:
    def __init__(self, char, freq):
        self.char = char
        self.freq = freq
        self.left = None
        self.right = None

    def __lt__(self, other):
        return self.freq < other.freq

def calculate_frequencies(data):
    freq = defaultdict(int)
    for char in data:
        freq[char] += 1
    return freq

def build_huffman_tree(freq):
    heap = [Node(char, freq) for char, freq in freq.items()]
    heapq.heapify(heap)

    while len(heap) > 1:
        node1 = heapq.heappop(heap)
        node2 = heapq.heappop(heap)
        merged = Node(None, node1.freq + node2.freq)
        merged.left = node1
        merged.right = node2
        heapq.heappush(heap, merged)

    return heap[0]

def generate_huffman_codes(node, code, codes):
    if node is None:
        return
    if node.char is not None:
        codes[node.char] = code
    generate_huffman_codes(node.left, code + "0", codes)
    generate_huffman_codes(node.right, code + "1", codes)

def huffman_encode(data, codes):
    encoded_data = ''.join(codes[char] for char in data)
    return encoded_data

def huffman_decode(encoded_data, root):
    decoded_data = []
    node = root
    for bit in encoded_data:
        if bit == '0':
            node = node.left
        else:
            node = node.right
        if node.char is not None:
            decoded_data.append(node.char)
            node = root
    return ''.join(decoded_data)

def huffman_compression(data):
    freq = calculate_frequencies(data)
    root = build_huffman_tree(freq)
    codes = {}
    generate_huffman_codes(root, "", codes)
    encoded_data = huffman_encode(data, codes)
    return encoded_data, root, codes

def huffman_decompression(encoded_data, root):
    return huffman_decode(encoded_data, root)

# Example usage
data = "this is an example for huffman encoding"
encoded_data, root, codes = huffman_compression(data)
print("Encoded Data:", encoded_data)
print("Huffman Codes:", codes)

decoded_data = huffman_decompression(encoded_data, root)
print("Decoded Data:", decoded_data)

