import concurrent.futures
import math

def extended_collatz_sequence(n):
    sequence = []
    while n != 1 and n != -1:
        sequence.append(n)
        if n % 2 == 0:
            n = n // 2
        else:
            if n > 0:
                n = 3 * n + 1
            else:
                n = 3 * n - 1
        if abs(n) > 10**18:  # Handle potential overflow
            raise OverflowError("Integer overflow detected")
    sequence.append(n)
    return sequence

def compute_collatz_sequences(inputs):
    results = {}
    with concurrent.futures.ThreadPoolExecutor() as executor:
        future_to_input = {executor.submit(extended_collatz_sequence, n): n for n in inputs}
        for future in concurrent.futures.as_completed(future_to_input):
            n = future_to_input[future]
            try:
                results[n] = future.result()
            except Exception as e:
                results[n] = str(e)
    return results

# Example usage
