from datetime import datetime

def is_leap_year(year):
    """Check if a year is a leap year."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def days_in_month(year, month):
    """Return the number of days in a given month of a given year."""
    if month == 2:
        return 29 if is_leap_year(year) else 28
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 31

def calculate_age_difference(date1, date2):
    """Calculate the age difference between two dates."""
    if date1 > date2:
        date1, date2 = date2, date1  # Ensure date1 is the earlier date

    years = date2.year - date1.year
    months = date2.month - date1.month
    days = date2.day - date1.day

    if days < 0:
        # Borrow days from the previous month
        last_month = date2.month - 1 if date2.month > 1 else 12
        days_in_last_month = days_in_month(date2.year, last_month)
        days += days_in_last_month
        months -= 1

    if months < 0:
        # Borrow months from the previous year
        months += 12
        years -= 1

    return years, months, days

def main():
    # Input dates
    date1_str = input("Enter the first date (YYYY-MM-DD): ")
    date2_str = input("Enter the second date (YYYY-MM-DD): ")

    try:
        date1 = datetime.strptime(date1_str, "%Y-%m-%d")
        date2 = datetime.strptime(date2_str, "%Y-%m-%d")
    except ValueError:
        print("Invalid date format. Please use YYYY-MM-DD.")
        return

    if date1 > datetime.now() or date2 > datetime.now():
        print("One or both dates are in the future.")
    else:
        age_difference = calculate_age_difference(date1, date2)
        print(f"The age difference is {age_difference[0]} years, {age_difference[1]} months, and {age_difference[2]} days.")

if __name__ == "__main__":
    main()

import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def get_directory_size(path):
    total_size = 0
    with os.scandir(path) as it:
        for entry in it:
            if entry.is_file():
                total_size += entry.stat().st_size
            elif entry.is_dir():
                total_size += get_directory_size(entry.path)
    return total_size

def get_folder_size(path, max_workers=4):
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = []
        for root, dirs, _ in os.walk(path, topdown=True):
            for dir in dirs:
                dir_path = os.path.join(root, dir)
                futures.append(executor.submit(get_directory_size, dir_path))

        total_size = 0
        for future in as_completed(futures):
            total_size += future.result()

        # Add size of files in the top-level directory
        with os.scandir(path) as it:
            for entry in it:
                if entry.is_file():
                    total_size += entry.stat().st_size

    return total_size

if __name__ == "__main__":
    folder_path = "C:\\"
    folder_size = get_folder_size(folder_path)
    print(f"Total size: {folder_size / 1024 / 1024 / 1024:.2f} GB")

import asyncio
from typing import Type, Callable
from pydantic import BaseModel
import functools
from fastapi.encoders import jsonable_encoder

# Assuming redis_client and settings are defined elsewhere

class CacheResponse:
    def __init__(self, include_params: list[str] = None, exclude_params: list[str] = None):
        self.include_params = include_params or []
        self.exclude_params = exclude_params or []
        self.locks = {}  # A dictionary to hold locks for each unique key

    def __call__(self, schema: Type[BaseModel] = None, ttl: int = settings.REDIS_TIMEOUT,
                 include_params: list[str] = None, exclude_params: list[str] = None):
        def decorator(func: Callable):
            @functools.wraps(func)
            async def wrapper(*args, **kwargs):
                # generate the key for the function signature
                key = self.generate_key(
                    func,
                    include_params or self.include_params,
                    exclude_params or self.exclude_params,
                    *args, **kwargs,
                )

                # Get or create a lock for the key
                lock = self.locks.setdefault(key, asyncio.Lock())

                async with lock:
                    cached_response = await redis_client.get_by_key(key)
                    if cached_response:
                        cached_response = orjson.loads(cached_response)
                        if schema:
                            if isinstance(cached_response, list):
                                return [schema.parse_obj(r) for r in cached_response]
                            else:
                                return schema.parse_obj(cached_response)
                        else:
                            return cached_response
                    else:
                        if asyncio.iscoroutinefunction(func):
                            response = await func(*args, **kwargs)
                        else:
                            response = func(*args, **kwargs)
                        data = redis_client.RedisData(
                            key=key,
                            value=orjson.dumps(jsonable_encoder(response)),
                            ttl=ttl
                        )
                        await redis_client.set_redis_key(data)
                        return response

                # Clean up the lock if it's no longer needed
                if key in self.locks and not lock.locked():
                    del self.locks[key]

            return wrapper
        return decorator

    def generate_key(self, func: Callable, include_params: list[str], exclude_params: list[str], *args, **kwargs) -> str:
        params = {}
        for arg in args:
            params[arg] = kwargs.get(arg)
        for key, value in kwargs.items():
            if key not in params:
                params[key] = value

        filtered_params = {k: v for k, v in params.items() if k not in exclude_params}
        if include_params:
            filtered_params = {k: v for k, v in filtered_params.items() if k in include_params}

        sorted_params = sorted(filtered_params.items())
        params_str = "&".join(f"{k}={v}" for k, v in sorted_params)
        return f"{func.__module__}:{func.__name__}:{params_str}"

