def extract_text(soup):
    """Extracts text from the HTML content."""
    [script.extract() for script in soup(['script', 'style'])]  # Remove script and style elements
    text = soup.get_text()
    lines = (line.strip() for line in text.splitlines())
    chunks = (phrase.strip() for line in lines for phrase in line.split("  "))
    return '\n'.join(chunk for chunk in chunks if chunk)

def find_events(text, essential_events):
    """Finds and extracts historical events and their dates from the text."""
    events = {}
    for event, date in essential_events.items():
        pattern = re.compile(rf"{re.escape(event)}.*?(\d{{4}}\sBCE)", re.IGNORECASE | re.DOTALL)
        match = pattern.search(text)
        if match:
            events[event] = match.group(1).strip()
        else:
            events[event] = None
    return events

def verify_history(url, essential_events, reference_events):
    """Verifies the historical events in the given URL against the reference events."""
    response = requests.get(url)
    soup = BeautifulSoup(response.text, 'html.parser')
    text = extract_text(soup)
    events = find_events(text, essential_events)

    discrepancies = []
    for event, expected_date in essential_events.items():
        if events[event] != expected_date:
            discrepancies.append((event, events[event], expected_date))

    if discrepancies:
        print(f"Discrepancies found in {url}:")
        for event, actual_date, expected_date in discrepancies:
            print(f"  - {event}: Got {actual_date}, expected {expected_date}")
    else:
        print(f"No discrepancies found in {url}.")

