class DifferentDimensionsError(Exception):
    """Exception raised when attempting to add points with different dimensions."""
    def __init__(self, message="Cannot add points with different dimensions."):
        self.message = message
        super().__init__(self.message)

class Point:
    def __init__(self, *coordinates):
        self.coordinates = coordinates

    def __add__(self, other):
        if len(self.coordinates) != len(other.coordinates):
            raise DifferentDimensionsError()

        result_coordinates = tuple(a + b for a, b in zip(self.coordinates, other.coordinates))
        return Point(*result_coordinates)

    def __repr__(self):
        return f"Point({', '.join(map(str, self.coordinates))})"

