def is_empty_dict(d, visited=None):
    if visited is None:
        visited = set()

    if id(d) in visited:
        return True, 0  # Already visited, so it's not counted again

    visited.add(id(d))

    if not isinstance(d, (dict, list, tuple, set)):
        return False, 0  # Not an iterable, so it's not an empty dictionary

    if isinstance(d, dict) and not d:
        return True, 1  # Empty dictionary

    empty = True
    empty_count = 0

    if isinstance(d, dict):
        for value in d.values():
            is_empty, count = is_empty_dict(value, visited)
            empty_count += count
            if not is_empty:
                empty = False
    elif isinstance(d, (list, tuple, set)):
        for item in d:
            is_empty, count = is_empty_dict(item, visited)
            empty_count += count
            if not is_empty:
                empty = False

    return empty, empty_count

