class Animal(models.Model):
    TYPE_DOG = 'dog'
    TYPE_CAT = 'cat'
    TYPE_CHOICES = [
        (TYPE_DOG, 'Dog'),
        (TYPE_CAT, 'Cat'),
    ]
    type = models.CharField(max_length=255, choices=TYPE_CHOICES)

    def as_proxy(self):
        if self.type == self.TYPE_DOG:
            return self.__class__.objects.get_subclass(id=self.id).__class__(**self.__dict__)
        elif self.type == self.TYPE_CAT:
            return self.__class__.objects.get_subclass(id=self.id).__class__(**self.__dict__)
        return self

    class Meta:
        abstract = False  # Ensure the model is not abstract

