def parse_html(html_string):
    stack = []
    tag_content = []
    i = 0
    while i < len(html_string):
        if html_string[i] == '<':
            if html_string[i+1] == '/':  # Closing tag
                end = html_string.find('>', i)
                tag_name = html_string[i+2:end]
                if stack:
                    level = len(stack) - 1
                    print(f"{'  ' * level}Closing tag: {tag_name}")
                    stack.pop()
                i = end
            else:  # Opening tag
                end = html_string.find('>', i)
                tag_info = html_string[i+1:end].split()
                tag_name = tag_info[0]
                attributes = {}
                if len(tag_info) > 1:
                    for attr in tag_info[1:]:
                        key, value = attr.split('=')
                        attributes[key] = value.strip('"\'')
                stack.append(tag_name)
                level = len(stack) - 1
                print(f"{'  ' * level}Opening tag: {tag_name}")
                if attributes:
                    print(f"{'  ' * (level + 1)}Attributes: {attributes}")
                i = end
        else:  # Text content
            end = html_string.find('<', i)
            if end == -1:
                end = len(html_string)
            text = html_string[i:end].strip()
            if text:
                level = len(stack) - 1 if stack else 0
                print(f"{'  ' * level}Text: {text}")
                tag_content.append((stack[-1], text))
            i = end - 1
        i += 1

