import os
from datetime import datetime, timedelta
from azure.identity import DefaultAzureCredential
from azure.mgmt.resource import ResourceManagementClient
from azure.mgmt.web import WebSiteManagementClient
from azure.mgmt.web.models import UsageState

# Constants
SUBSCRIPTION_ID = 'your-subscription-id'
RESOURCE_GROUP_NAME = 'your-resource-group-name'
WEB_APP_NAME = 'your-web-app-name'  # Optional: if you want to target a specific web app
DAYS_THRESHOLD = 30

# Initialize Azure clients
credential = DefaultAzureCredential()
resource_client = ResourceManagementClient(credential, SUBSCRIPTION_ID)
web_client = WebSiteManagementClient(credential, SUBSCRIPTION_ID)

def get_web_apps(resource_group_name):
    web_apps = web_client.web_apps.list_by_resource_group(resource_group_name)
    return list(web_apps)

def get_web_app_metrics(web_app):
    end_time = datetime.utcnow()
    start_time = end_time - timedelta(days=DAYS_THRESHOLD)
    metrics = web_client.web_apps.list_metric_definitions(web_app.resource_group, web_app.name)
    for metric in metrics:
        if metric.name.value == 'Requests':
            data = web_client.web_apps.list_metrics(web_app.resource_group, web_app.name, metric.name.value, interval='PT1H', start_time=start_time, end_time=end_time)
            return data
    return None

def is_web_app_unused(web_app):
    metrics = get_web_app_metrics(web_app)
    if not metrics:
        return True
    for metric in metrics.value:
        if metric.timeseries and any(point for point in metric.timeseries[0].data if point.total):
            return False
    return True

def delete_web_app(web_app):
    print(f"Deleting Web App: {web_app.name}")
    web_client.web_apps.delete(web_app.resource_group, web_app.name)

def main():
    web_apps = get_web_apps(RESOURCE_GROUP_NAME)
    for web_app in web_apps:
        if is_web_app_unused(web_app):
            delete_web_app(web_app)

if __name__ == "__main__":
    main()

import random

def get_player_guess(player_name, min_num, max_num):
    while True:
        try:
            guess = int(input(f"{player_name}, guess a number between {min_num} and {max_num}: "))
            if min_num <= guess <= max_num:
                return guess
            else:
                print(f"Please enter a number between {min_num} and {max_num}.")
        except ValueError:
            print("Please enter a valid number.")

def play_game():
    min_num = 1
    max_num = 100
    max_tries = 10

    random_number = random.randint(min_num, max_num)
    player1_name = input("Enter Player 1's name: ")
    player2_name = input("Enter Player 2's name: ")

    player1_tries = 0
    player2_tries = 0

    while player1_tries < max_tries and player2_tries < max_tries:
        # Player 1's turn
        if player1_tries < max_tries:
            guess = get_player_guess(player1_name, min_num, max_num)
            player1_tries += 1
            if guess == random_number:
                print(f"{player1_name} wins! The number was {random_number}.")
                return
            else:
                print(f"Wrong guess, {player1_name}. Tries left: {max_tries - player1_tries}")

        # Player 2's turn
        if player2_tries < max_tries:
            guess = get_player_guess(player2_name, min_num, max_num)
            player2_tries += 1
            if guess == random_number:
                print(f"{player2_name} wins! The number was {random_number}.")
                return
            else:
                print(f"Wrong guess, {player2_name}. Tries left: {max_tries - player2_tries}")

    print("Both players have run out of tries. The number was {random_number}.")

if __name__ == "__main__":
    play_game()

from abc import ABC, abstractmethod

class Shape(ABC):
    def __init__(self, length, width, name):
        self.length = length
        self.width = width
        self._name = name

    @abstractmethod
    def calculateArea(self) -> float:
        pass

    def printArea(self):
        area = self.calculateArea()
        print(f"The area of the {self._name} is {area:.2f}")

    def getPerimeter(self) -> float:
        return 2 * (self.length + self.width)

    @staticmethod
    def compareAreas(shape1, shape2) -> float:
        return abs(shape1.calculateArea() - shape2.calculateArea())

    def printName(self):
        print(f"The shape is a {self._name}")

# Subclasses of Shape
class Rectangle(Shape):
    def __init__(self, length, width):
        super().__init__(length, width, "Rectangle")

    def calculateArea(self) -> float:
        return self.length * self.width

class Circle(Shape):
    def __init__(self, radius):
        super().__init__(radius, 0, "Circle")  # Width is not used for Circle
        self.radius = radius

    def calculateArea(self) -> float:
        return 3.14159 * self.radius * self.radius

    def getPerimeter(self) -> float:
        return 2 * 3.14159 * self.radius

class Triangle(Shape):
    def __init__(self, base, height):
        super().__init__(base, height, "Triangle")

    def calculateArea(self) -> float:
        return 0.5 * self.length * self.width

# Example usage
if __name__ == "__main__":
    rect = Rectangle(4, 5)
    rect.printName()
    rect.printArea()
    print(f"The perimeter of the {rect._name} is {rect.getPerimeter():.2f}")

    circle = Circle(3)
    circle.printName()
