class PhoneDirectory:
    def __init__(self):
        self.directory = {}

    def add_entry(self, name, phone_number, country, state, city):
        if country not in self.directory:
            self.directory[country] = {}
        if state not in self.directory[country]:
            self.directory[country][state] = {}
        if city not in self.directory[country][state]:
            self.directory[country][state][city] = []

        self.directory[country][state][city].append({
            'name': name,
            'phone_number': phone_number
        })

    def remove_entry(self, name, phone_number, country, state, city):
        if country in self.directory and state in self.directory[country] and city in self.directory[country][state]:
            entries = self.directory[country][state][city]
            for entry in entries:
                if entry['name'] == name and entry['phone_number'] == phone_number:
                    entries.remove(entry)
                    return True
        return False

    def search_entry(self, name=None, phone_number=None, country=None, state=None, city=None):
        results = []

        def search_recursive(current_dict, path):
            if not isinstance(current_dict, dict):
                return

            for key, value in current_dict.items():
                new_path = path + [key]
                if len(new_path) == 3:  # Country, State, City
                    for entry in value:
                        if (name is None or entry['name'] == name) and \
                           (phone_number is None or entry['phone_number'] == phone_number):
                            results.append({
                                'name': entry['name'],
                                'phone_number': entry['phone_number'],
                                'country': new_path[0],
                                'state': new_path[1],
                                'city': new_path[2]
                            })
                else:
                    search_recursive(value, new_path)

        search_recursive(self.directory, [])
        return results

    def display_directory(self):
        def display_recursive(current_dict, indent=0):
            if not isinstance(current_dict, dict):
                return

            for key, value in current_dict.items():
                print(' ' * indent + key)
                if isinstance(value, list):
                    for entry in value:
                        print(' ' * (indent + 4) + f"{entry['name']}: {entry['phone_number']}")
                else:
                    display_recursive(value, indent + 4)

        display_recursive(self.directory)

# Example usage
