def generate_username(keyword):
    """Generate a username with the given keyword and a random number."""
    return f"{keyword}{generate_random_number()}"

def ensure_uniqueness(usernames, keyword, count=4):
    """Ensure that the generated usernames are unique."""
    unique_usernames = set()
    while len(unique_usernames) < count:
        username = generate_username(keyword)
        if username not in unique_usernames:
            unique_usernames.add(username)
    return unique_usernames

