class UserDataStore:
    def __init__(self):
        self.users = {}  # Main storage for user data
        self.city_index = {}  # Index for searching by city
        self.book_index = {}  # Index for searching by books

    def add_user(self, user):
        if user.name in self.users:
            raise ValueError(f"User with name {user.name} already exists.")

        self.users[user.name] = user
        self._update_city_index(user, 'add')
        self._update_book_index(user, 'add')

    def update_user(self, user):
        if user.name not in self.users:
            raise ValueError(f"User with name {user.name} does not exist.")

        old_user = self.users[user.name]
        self.users[user.name] = user
        self._update_city_index(old_user, 'remove')
        self._update_book_index(old_user, 'remove')
        self._update_city_index(user, 'add')
        self._update_book_index(user, 'add')

    def delete_user(self, name):
        if name not in self.users:
            raise ValueError(f"User with name {name} does not exist.")

        user = self.users.pop(name)
        self._update_city_index(user, 'remove')
        self._update_book_index(user, 'remove')

    def search_users_by_city(self, city):
        return [self.users[name] for name in self.city_index.get(city, set())]

    def search_users_by_book(self, book):
        return [self.users[name] for name in self.book_index.get(book, set())]

    def _update_city_index(self, user, action):
        if action == 'add':
            if user.city not in self.city_index:
                self.city_index[user.city] = set()
            self.city_index[user.city].add(user.name)
        elif action == 'remove':
            if user.city in self.city_index:
                self.city_index[user.city].discard(user.name)
                if not self.city_index[user.city]:
                    del self.city_index[user.city]

    def _update_book_index(self, user, action):
        for book in user.favorite_books:
            if action == 'add':
                if book not in self.book_index:
                    self.book_index[book] = set()
                self.book_index[book].add(user.name)
            elif action == 'remove':
                if book in self.book_index:
                    self.book_index[book].discard(user.name)
                    if not self.book_index[book]:
                        del self.book_index[book]

