import threading
from queue import Queue

def sum_of_squares(n):
    """Calculate the sum of squares of digits of a number."""
    return sum(int(digit) ** 2 for digit in str(n))

def worker(queue, thread_id):
    """Worker function to process numbers from the queue."""
    while True:
        number = queue.get()
        if number is None:
            break
        sum_squares = sum_of_squares(number)
        if sum_squares % 17 == 0:
            print(f"Number: {number}, Sum of squares: {sum_squares}, Thread ID: {thread_id}")
        queue.task_done()

def main(numbers, num_threads):
    """Main function to set up and start the threads."""
    queue = Queue()
    threads = []

    # Create and start worker threads
    for i in range(num_threads):
        thread = threading.Thread(target=worker, args=(queue, i))
        thread.start()
        threads.append(thread)

    # Put numbers into the queue
    for number in numbers:
        queue.put(number)

    # Block until all tasks are done
    queue.join()

    # Stop workers
    for _ in range(num_threads):
        queue.put(None)
    for thread in threads:
        thread.join()

if __name__ == "__main__":
    numbers = [123, 456, 789, 1011, 1213, 1415, 1617, 1819, 2021, 2223]
    num_threads = 4
    main(numbers, num_threads)

import time

def factorial(n, indent=""):
    # Base case: if n is 0 or 1, return 1
    if n == 0 or n == 1:
        print(f"{indent}factorial({n}) = 1 (Base case)")
        return 1
    # Recursive case: n * factorial(n-1)
    else:
        print(f"{indent}factorial({n}) = {n} * factorial({n-1})")
        result = n * factorial(n-1, indent + "  ")
        print(f"{indent}factorial({n}) returns {result}")
        return result

def time_complexity_analysis(n):
    start_time = time.time()
    result = factorial(n)
    end_time = time.time()
    elapsed_time = end_time - start_time
    print(f"\nFactorial of {n} is {result}")
    print(f"Time taken: {elapsed_time:.6f} seconds")
    print(f"Time complexity: O(n) (where n is the input number)")

def main():
    try:
        n = int(input("Enter a non-negative integer: "))
        if n < 0:
            print("Factorial is not defined for negative numbers.")
        else:
            time_complexity_analysis(n)
    except ValueError:
        print("Please enter a valid non-negative integer.")

