from google.cloud import datastore

class User:
    def __init__(self, email, password_hash, verified=False):
        self.email = email
        self.password_hash = password_hash
        self.verified = verified

    @classmethod
    def get_by_email(cls, email):
        client = datastore.Client()
        query = client.query(kind='User')
        query.add_filter('email', '=', email)
        result = list(query.fetch(limit=1))
        return result[0] if result else None

    @classmethod
    def create(cls, email, password_hash, verified=False):
        client = datastore.Client()
        user_key = client.key('User', email)
        user = datastore.Entity(key=user_key)
        user.update({
            'email': email,
            'password_hash': password_hash,
            'verified': verified
        })
        client.put(user)
        return cls(email, password_hash, verified)

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def display(self):
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")

    def prepend(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def delete(self, key):
        current = self.head
        if current and current.data == key:
            self.head = current.next
            current = None
            return
        prev = None
        while current and current.data != key:
            prev = current
            current = current.next
        if current is None:
            return
        prev.next = current.next
        current = None

# Example usage
if __name__ == "__main__":
    linked_list = LinkedList()
    linked_list.append(1)
    linked_list.append(2)
    linked_list.append(3)
    linked_list.prepend(0)
    linked_list.display()  # Output: 0 -> 1 -> 2 -> 3 -> None
    linked_list.delete(2)
    linked_list.display()  # Output: 0 -> 1 -> 3 -> None

