import random

def get_user_selection():
    user_selection = input("Enter your choice (Rock, Paper, Scissors): ").strip().lower()
    while user_selection not in ['rock', 'paper', 'scissors']:
        print("Invalid choice. Please try again.")
        user_selection = input("Enter your choice (Rock, Paper, Scissors): ").strip().lower()
    return user_selection

def get_computer_selection():
    return random.choice(['rock', 'paper', 'scissors'])

def determine_winner(user_selection, computer_selection):
    if user_selection == computer_selection:
        return "It's a tie!"
    elif (user_selection == 'rock' and computer_selection == 'scissors') or \
         (user_selection == 'scissors' and computer_selection == 'paper') or \
         (user_selection == 'paper' and computer_selection == 'rock'):
        return "You win!"
    else:
        return "Computer wins!"

def play_game():
    print("Let's play Rock, Paper, Scissors!")
    user_score = 0
    computer_score = 0

    while True:
        user_selection = get_user_selection()
        computer_selection = get_computer_selection()
        print(f"Computer selected: {computer_selection}")
        result = determine_winner(user_selection, computer_selection)
        print(result)

        if result == "You win!":
            user_score += 1
        elif result == "Computer wins!":
            computer_score += 1

        print(f"Score: You {user_score}, Computer {computer_score}")

        play_again = input("Do you want to play again? (yes/no): ").strip().lower()
        if play_again != 'yes':
            break

    print(f"Final Score: You {user_score}, Computer {computer_score}")
    print("Thanks for playing!")

if __name__ == "__main__":
    play_game()

class Quaternion:
    def __init__(self, a=0, b=0, c=0, d=0):
        """
        Initialize a quaternion with real and imaginary parts.

        :param a: Real part
        :param b: i component
        :param c: j component
        :param d: k component
        """
        self.a = a
        self.b = b
        self.c = c
        self.d = d

    def __str__(self):
        """
        Return a string representation of the quaternion.

        :return: String representation
        """
        return f"{self.a} + {self.b}i + {self.c}j + {self.d}k"

    def conjugate(self):
        """
        Return the conjugate of the quaternion.

        :return: Conjugate quaternion
        """
        return Quaternion(self.a, -self.b, -self.c, -self.d)

    def norm(self):
        """
        Return the norm (or magnitude) of the quaternion.

        :return: Norm of the quaternion
        """
        return (self.a**2 + self.b**2 + self.c**2 + self.d**2)**0.5

    def normalize(self):
        """
        Return the normalized (unit) quaternion.

        :return: Normalized quaternion
        """
        norm = self.norm()
        if norm == 0:
            return Quaternion(0, 0, 0, 0)
        return Quaternion(self.a / norm, self.b / norm, self.c / norm, self.d / norm)

    def add(self, other):
        """
        Add another quaternion to this one.

        :param other: Quaternion to add
        :return: Resulting quaternion
        """
        return Quaternion(self.a + other.a, self.b + other.b, self.c + other.c, self.d + other.d)

    def subtract(self, other):
        """
        Subtract another quaternion from this one.

        :param other: Quaternion to subtract
        :return: Resulting quaternion
        """
        return Quaternion(self.a - other.a, self.b - other.b, self.c - other.c, self.d - other.d)

    def multiply(self, other):
        """
        Multiply this quaternion by another quaternion.

        :param other: Quaternion to multiply by
        :return: Resulting quaternion
        """
        a = self.a * other.a - self.b * other.b - self.c * other.c - self.d * other.d
        b = self.a * other.b + self.b * other.a + self.c * other.d - self.d * other.c
        c = self.a * other.c - self.b * other.d + self.c * other.a + self.d * other.b
        d = self.a * other.d + self.b * other.c - self.c * other.b + self.d * other.a
        return Quaternion(a, b, c, d)

    def inverse(self):
        """
        Return the inverse of the quaternion.

        :return: Inverse quaternion
        """
        norm_squared = self.norm() ** 2
        if norm_squared == 0:
            raise ValueError("Cannot compute the inverse of a zero quaternion")
        return self.conjugate() / norm_squared

    def __add__(self, other):
        return self.add(other)

    def __sub__(self, other):
        return self.subtract(other)

    def __mul__(self, other):
        if isinstance(other, (int, float)):
            return Quaternion(self.a * other, self.b * other, self.c * other, self.d * other)
        return self.multiply(other)

    def __truediv__(self, other):
        if isinstance(other, (int, float)):
            return Quaternion(self.a / other, self.b / other, self.c / other, self.d / other)
        return self * other.inverse()

