import unittest
import multiprocessing

class ParallelTestRunner:
    def __init__(self, test_loader, num_processes=None):
        self.test_loader = test_loader
        self.num_processes = num_processes or multiprocessing.cpu_count()

    def run(self, test_suite):
        test_cases = []
        for test in test_suite:
            test_cases.append(test)

        with multiprocessing.Pool(processes=self.num_processes) as pool:
            results = pool.map(self.run_test, test_cases)

        for result in results:
            if result.failures or result.errors:
                return result

    def run_test(self, test):
        result = unittest.TestResult()
        test.run(result)
        return result

if __name__ == "__main__":
    loader = unittest.TestLoader()
    suite = loader.discover('tests')  # Replace 'tests' with your test directory

    runner = ParallelTestRunner(loader)
    runner.run(suite)

import random
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def miller_rabin(n, k=5):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    r, s = 0, n - 1
    while s % 2 == 0:
        r += 1
        s //= 2

    for _ in range(k):
        a = random.randrange(2, n - 1)
        x = pow(a, s, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def pollard_brent(n):
    if n % 2 == 0:
        return 2
    y, c, m = random.randint(1, n-1), random.randint(1, n-1), random.randint(1, n-1)
    g, r, q = 1, 1, 1
    while g == 1:
        x = y
        for _ in range(r):
            y = (pow(y, 2, n) + c) % n
        k = 0
        while k < r and g == 1:
            ys = y
            for _ in range(min(m, r - k)):
                y = (pow(y, 2, n) + c) % n
                q = q * abs(x - y) % n
            g = gcd(q, n)
            k += m
        r *= 2
    if g == n:
        while True:
            ys = (pow(ys, 2, n) + c) % n
            g = gcd(abs(x - ys), n)
            if g > 1:
                break
    return g

def sieve_of_eratosthenes(limit):
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, limit + 1, i):
                sieve[j] = False
    return [i for i in range(2, limit + 1) if sieve[i]]

def prime_factors(n):
    factors = []
    if n <= 1:
        return factors

    # Optimized trial division
    small_primes = sieve_of_eratosthenes(1000)
    for p in small_primes:
        while n % p == 0:
            factors.append(p)
            n //= p
        if n == 1:
            break

    # Pollard-Brent for larger factors
    while n > 1:
        if miller_rabin(n):
            factors.append(n)
            break
        factor = pollard_brent(n)
        if factor == n:
            factors.append(n)
            break
        factors.append(factor)
        n //= factor

    return factors

# Example usage
n = 12345678901234567890  # A 20-digit number
print(f"Prime factors of {n}: {prime_factors(n)}")

import os
import filetype
from pyunpack import Archive

def detect_file_type(file_path):
    """Detect the file type based on its content."""
    kind = filetype.guess(file_path)
    if kind is None:
        raise ValueError(f"Could not determine the file type of {file_path}")
    return kind.mime

def decompress_file(file_path, output_dir):
    """Decompress the file based on its detected type."""
    file_type = detect_file_type(file_path)

    if file_type in ['application/zip', 'application/x-rar-compressed', 'application/x-7z-compressed', 'application/x-bzip2', 'application/gzip']:
        try:
            Archive(file_path).extractall(output_dir)
            print(f"File {file_path} decompressed successfully to {output_dir}")
        except Exception as e:
            print(f"Error decompressing {file_path}: {e}")
    else:
        raise ValueError(f"Unsupported file type: {file_type}")

