import json

def calculate_ages(json_data, output_file):
    # Extract ages of females
    female_ages = [person['age'] for person in json_data if person['gender'] == 'female']

    # Handle edge case where there are no females
    if not female_ages:
        result = {
            "average_age": None,
            "median_age": None
        }
        with open(output_file, 'w') as f:
            json.dump(result, f, indent=4)
        return result

    # Calculate average age
    average_age = sum(female_ages) / len(female_ages)

    # Calculate median age
    female_ages.sort()
    n = len(female_ages)
    if n % 2 == 1:
        median_age = female_ages[n // 2]
    else:
        median_age = (female_ages[n // 2 - 1] + female_ages[n // 2]) / 2

    # Prepare result
    result = {
        "average_age": average_age,
        "median_age": median_age
    }

    # Write result to JSON file
    with open(output_file, 'w') as f:
        json.dump(result, f, indent=4)

    return result

