import math

def add(a, b):
    """Add two numbers."""
    return a + b

def subtract(a, b):
    """Subtract b from a."""
    return a - b

def multiply(a, b):
    """Multiply two numbers."""
    return a * b

def divide(a, b):
    """Divide a by b. Returns a tuple (result, error) where error is None if no error occurs."""
    if b == 0:
        return None, "Division by zero is not allowed."
    return a / b, None

def exponentiate(base, exponent):
    """Raise base to the power of exponent."""
    return base ** exponent

def modulo(a, b):
    """Compute a modulo b. Returns a tuple (result, error) where error is None if no error occurs."""
    if b == 0:
        return None, "Modulo by zero is not allowed."
    return a % b, None

def nth_root(number, n):
    """Compute the nth root of a number."""
    if number < 0 and n % 2 == 0:
        return None, "Cannot compute even root of a negative number."
    return number ** (1/n), None

def print_result(operation, a, b, result, error=None):
    """Print the result of an operation."""
    if error:
        print(f"Error: {error}")
    else:
        print(f"Result of {a} {operation} {b} = {result}")

def main():
    operations = {
        "add": add,
        "subtract": subtract,
        "multiply": multiply,
        "divide": divide,
        "exponentiate": exponentiate,
        "modulo": modulo,
        "nth_root": nth_root
    }

    while True:
        print("\nAvailable operations:")
        print("1. Add")
        print("2. Subtract")
        print("3. Multiply")
        print("4. Divide")
        print("5. Exponentiate")
        print("6. Modulo")
        print("7. Nth Root")
        print("8. Exit")

        choice = input("Enter the number of the operation you want to perform (1-8): ")

        if choice == '8':
            print("Exiting the program.")
            break

        if choice not in ['1', '2', '3', '4', '5', '6', '7']:
            print("Invalid choice. Please enter a number between 1 and 8.")
            continue

        a = float(input("Enter the first number: "))
        b = float(input("Enter the second number: "))

        if choice == '7':
            result, error = nth_root(a, b)
        elif choice == '4':
            result, error = divide(a, b)
        elif choice == '6':
            result, error = modulo(a, b)
        else:
            operation = list(operations.keys())[int(choice) - 1]
            result = operations[operation](a, b)
            error = None

        if choice == '7':
            print_result("nth root", a, b, result, error)
        elif choice == '4':
            print_result("divide", a, b, result, error)
        elif choice == '6':
            print_result("modulo", a, b, result, error)
        else:
            print_result(operation, a, b, result)

