class Employee: 
    def __init__(self, name, age): 
        self.name = name
        self.age = age

    def __repr__(self):
        return f"{self.name} (Age: {self.age})"

class EmployeeManager:
    def __init__(self):
        self.employees = []

    def add_employee(self, name, age):
        if not name or not age:
            raise ValueError("Name and age are required.")
        if not isinstance(age, int) or age <= 0:
            raise ValueError("Age must be a positive integer.")
        self.employees.append(Employee(name, age))
        print(f"Employee {name} added successfully.")

    def remove_employee(self, name):
        for employee in self.employees:
            if employee.name == name:
                self.employees.remove(employee)
                print(f"Employee {name} removed successfully.")
                return
        raise ValueError(f"Employee {name} not found.")

    def update_age(self, name, new_age):
        if not new_age or not isinstance(new_age, int) or new_age <= 0:
            raise ValueError("New age must be a positive integer.")
        for employee in self.employees:
            if employee.name == name:
                employee.age = new_age
                print(f"Employee {name}'s age updated to {new_age}.")
                return
        raise ValueError(f"Employee {name} not found.")

    def list_employees(self):
        if not self.employees:
            print("No employees in the list.")
            return
        sorted_employees = sorted(self.employees, key=lambda x: x.name)
        for employee in sorted_employees:
            print(employee)

    def average_age(self):
        if not self.employees:
            print("No employees in the list.")
            return 0
        total_age = sum(employee.age for employee in self.employees)
        return total_age / len(self.employees)

def main():
    manager = EmployeeManager()
    while True:
        print("\nEmployee Management System")
        print("1. Add Employee")
        print("2. Remove Employee")
        print("3. Update Employee Age")
        print("4. List Employees")
        print("5. Average Age of Employees")
        print("6. Exit")
        choice = input("Enter your choice: ")

        try:
            choice = int(choice)
            if choice == 1:
                name = input("Enter employee name: ")
                age = int(input("Enter employee age: "))
                manager.add_employee(name, age)
            elif choice == 2:
                name = input("Enter employee name to remove: ")
                manager.remove_employee(name)
            elif choice == 3:
                name = input("Enter employee name to update age: ")
                new_age = int(input("Enter new age: "))
                manager.update_age(name, new_age)
            elif choice == 4:
                manager.list_employees()
            elif choice == 5:
                avg_age = manager.average_age()
                print(f"Average age of employees: {avg_age:.2f}")
            elif choice == 6:
                print("Exiting the program.")
                break
            else:
                print("Invalid choice. Please try again.")
