class MahJonggHand:
    def __init__(self, tiles):
        self.tiles = tiles
        self.standard_patterns = {'pungs': 0, 'kongs': 0, 'chows': 0, 'pairs': 0}
        self.special_hands = {
            'Thirteen Orphans': self.is_thirteen_orphans,
            'Seven Pairs': self.is_seven_pairs,
            'All Pungs': self.is_all_pungs,
            'All Chows': self.is_all_chows,
            'Mixed Shifted Chows': self.is_mixed_shifted_chows,
            'All Terminals and Honors': self.is_all_terminals_and_honors,
            'All Simples': self.is_all_simples,
            'Half Flush': self.is_half_flush,
            'Full Flush': self.is_full_flush
        }

    def is_thirteen_orphans(self):
        # Check for Thirteen Orphans
        required_tiles = ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B']
        return all(tile in self.tiles for tile in required_tiles) and self.tiles.count(self.tiles[0]) == 2

    def is_seven_pairs(self):
        # Check for Seven Pairs
        pairs = set([tile for tile in self.tiles if self.tiles.count(tile) == 2])
        return len(pairs) == 7

    def is_all_pungs(self):
        # Check for All Pungs
        return all(self.tiles.count(tile) == 3 for tile in self.tiles) and len(set(self.tiles)) == 4

    def is_all_chows(self):
        # Check for All Chows
        return all(self.tiles.count(tile) == 3 for tile in self.tiles) and len(set(self.tiles)) == 4

    def is_mixed_shifted_chows(self):
        # Check for Mixed Shifted Chows
        return False  # Placeholder for implementation

    def is_all_terminals_and_honors(self):
        # Check for All Terminals and Honors
        return all(tile in ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B'] for tile in self.tiles)

    def is_all_simples(self):
        # Check for All Simples
        return all(tile in ['2m', '3m', '4m', '5m', '6m', '7m', '8m', '2p', '3p', '4p', '5p', '6p', '7p', '8p', '2s', '3s', '4s', '5s', '6s', '7s', '8s'] for tile in self.tiles)

    def is_half_flush(self):
        # Check for Half Flush
        suits = set([tile[-1] for tile in self.tiles])
        return len(suits) == 2

    def is_full_flush(self):
        # Check for Full Flush
        suits = set([tile[-1] for tile in self.tiles])
        return len(suits) == 1

from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///chat.db'
db = SQLAlchemy(app)

class Chat(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    description = db.Column(db.String(255))
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

class Message(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    chat_id = db.Column(db.Integer, db.ForeignKey('chat.id'), nullable=False)
    user_id = db.Column(db.Integer, nullable=False)
    content = db.Column(db.Text, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(100), nullable=False)

class ChatParticipant(db.Model):
    chat_id = db.Column(db.Integer, db.ForeignKey('chat.id'), primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), primary_key=True)
    joined_at = db.Column(db.DateTime, default=datetime.utcnow)

@app.route('/chats', methods=['POST'])
def create_chat():
    data = request.json
    new_chat = Chat(name=data['name'], description=data['description'])
    db.session.add(new_chat)
    db.session.commit()
    return jsonify({
        "id": new_chat.id,
        "name": new_chat.name,
        "description": new_chat.description,
        "created_at": new_chat.created_at
    }), 201

@app.route('/chats', methods=['GET'])
def list_chats():
    page = request.args.get('page', 1, type=int)
    limit = request.args.get('limit', 10, type=int)
    chats = Chat.query.paginate(page, limit, error_out=False)
    return jsonify({
        "chats": [chat.to_dict() for chat in chats.items],
        "total": chats.total
    })

@app.route('/chats/<int:chat_id>/messages', methods=['POST'])
def send_message(chat_id):
    data = request.json
    new_message = Message(chat_id=chat_id, user_id=data['user_id'], content=data['content'])
    db.session.add(new_message)
    db.session.commit()
    return jsonify({
        "id": new_message.id,
        "chat_id": new_message.chat_id,
        "user_id": new_message.user_id,
        "content": new_message.content,
        "created_at": new_message.created_at
    }), 201

@app.route('/chats/<int:chat_id>/messages', methods=['GET'])
def list_messages(chat_id):
    page = request.args.get('page', 1, type=int)
    limit = request.args.get('limit', 10, type=int)
    messages = Message.query.filter_by(chat_id=chat_id).paginate(page, limit, error_out=False)
    return jsonify({
        "messages": [message.to_dict() for message in messages.items],
        "total": messages.total
    })

@app.route('/chats/<int:chat_id>/invitations', methods=['POST'])
def invite_participant(chat_id):
    data = request.json
    new_participant = ChatParticipant(chat_id=chat_id, user_id=data['user_id'])
    db.session.add(new_participant)
    db.session.commit()
    return jsonify({
        "chat_id": new_participant.chat_id,
