import csv
import sys

def read_csv_file(file_path, delimiter=','):
    try:
        with open(file_path, mode='r', encoding='utf-8') as file:
            reader = csv.reader(file, delimiter=delimiter)
            data = list(reader)
            return data
    except FileNotFoundError:
        print(f"Error: The file '{file_path}' was not found.")
        sys.exit(1)
    except Exception as e:
        print(f"Error: An unexpected error occurred while reading the file: {e}")
        sys.exit(1)

def process_data(data):
    if not data or not data[0]:
        print("Error: The table is empty.")
        sys.exit(1)

    first_column = [row[0] for row in data]
    first_column.sort(reverse=True)
    return first_column

def format_output(data, keywords):
    formatted_string = ""
    for value in data:
        formatted_value = value
        for keyword in keywords:
            if keyword in value:
                formatted_value = formatted_value.replace(keyword, f"\\textbf{{\\textit{{{keyword}}}}}")
        formatted_string += formatted_value + " "
    return formatted_string.strip()

def main():
    if len(sys.argv) < 3:
        print("Usage: python script.py <file_path> <delimiter> [keywords...]")
        sys.exit(1)

    file_path = sys.argv[1]
    delimiter = sys.argv[2]
    keywords = sys.argv[3:]

    data = read_csv_file(file_path, delimiter)
    processed_data = process_data(data)
    output = format_output(processed_data, keywords)

    print(f"\\documentclass{{article}}\n\\begin{{document}}\n{output}\n\\end{{document}}")

if __name__ == "__main__":
    main()

class Quadrilateral:
    def __init__(self, side1, side2, side3, side4):
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3
        self.side4 = side4

    def perimeter(self):
        return self.side1 + self.side2 + self.side3 + self.side4

    def area(self):
        raise NotImplementedError("Subclasses must implement the area method")

    def change_dimensions(self, side1, side2, side3, side4):
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3
        self.side4 = side4


class Rectangle(Quadrilateral):
    def __init__(self, width, height):
        if width <= 0 or height <= 0:
            raise ValueError("Width and height must be positive numbers")
        super().__init__(width, height, width, height)
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def change_dimensions(self, width, height):
        if width <= 0 or height <= 0:
            raise ValueError("Width and height must be positive numbers")
        super().change_dimensions(width, height, width, height)
        self.width = width
        self.height = height

    def verify_rectangle(self):
        return self.side1 == self.side3 and self.side2 == self.side4


class Square(Rectangle):
    def __init__(self, side):
        if side <= 0:
            raise ValueError("Side length must be a positive number")
        super().__init__(side, side)

    def change_dimensions(self, side):
        if side <= 0:
            raise ValueError("Side length must be a positive number")
        super().change_dimensions(side, side)

    def verify_square(self):
        return self.side1 == self.side2 == self.side3 == self.side4


# Test Cases
def test_quadrilaterals():
    # Test Rectangle
    rect = Rectangle(4, 5)
    assert rect.area() == 20
    assert rect.perimeter() == 18
    assert rect.verify_rectangle() == True

    rect.change_dimensions(6, 7)
    assert rect.area() == 42
    assert rect.perimeter() == 26
    assert rect.verify_rectangle() == True

    # Test Square
    square = Square(5)
    assert square.area() == 25
    assert square.perimeter() == 20
    assert square.verify_square() == True

    square.change_dimensions(7)
    assert square.area() == 49
    assert square.perimeter() == 28
    assert square.verify_square() == True

    # Test invalid dimensions
    try:
        Rectangle(-1, 5)
    except ValueError as e:
        assert str(e) == "Width and height must be positive numbers"

    try:
        Square(0)
    except ValueError as e:
        assert str(e) == "Side length must be a positive number"

    print("All tests passed!")

test_quadrilaterals()

import concurrent.futures
import math

def is_perfect_square(n):
    root = int(math.sqrt(n))
    return root * root == n

def process_number(n):
    cube = n ** 3
    if is_perfect_square(cube):
        return n, cube, int(math.sqrt(cube))
    return n, cube, None

def process_interval(start, end, num_threads=4):
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = {executor.submit(process_number, n): n for n in range(start, end + 1)}
        for future in concurrent.futures.as_completed(futures):
            n, cube, sqrt = future.result()
            results.append((n, cube, sqrt))
    return results

def main():
    start = 1
    end = 10000
    num_threads = 4
    results = process_interval(start, end, num_threads)
    for n, cube, sqrt in results:
        print(f"Number: {n}, Cube: {cube}, Square Root: {sqrt}")

if __name__ == "__main__":
    main()

