def extract_text(file_path, max_pages=None):
    try:
        doc = pymupdf.open(file_path)
        text = ""
        for i, page in enumerate(doc):
            if max_pages and i >= int(max_pages):
                break
            text += page.get_text() + "\n"
        return text
    except Exception as e:
        return f"Error: {str(e)}"
