from __future__ import annotations
_MAX_UVARINT = (1 << 64) - 1
def encode_uvarint(value: int) -> bytes:
    """Encode an unsigned integer as a canonical varint."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("value must be an int")
    if value < 0:
        raise ValueError("value must be non-negative")
    if value > _MAX_UVARINT:
        raise ValueError("value must be <= 2^64-1")
    out = bytearray()
    while True:
        byte = value & 0x7F
        value >>= 7
        if value:
            out.append(byte | 0x80)
        else:
            out.append(byte)
            break
    return bytes(out)
def decode_uvarint(data: bytes, start: int) -> tuple[int, int]:
    """Decode an unsigned varint and reject non-canonical encodings."""
    if start < 0:
        raise ValueError("start must be non-negative")
    value = 0
    shift = 0
    idx = start
    while True:
        if idx >= len(data):
            raise ValueError("truncated varint")
        byte = data[idx]
        payload = byte & 0x7F
        if shift == 63 and payload > 1:
            raise ValueError("varint too large")
        idx += 1
        value |= payload << shift
        if byte & 0x80 == 0:
            if data[start:idx] != encode_uvarint(value):
                raise ValueError("non-canonical varint")
            return value, idx
        shift += 7
        if shift > 63:
            raise ValueError("varint too large")

