import logging
import functools
from torch.utils.checkpoint import checkpoint
from mindspeed.fsdp.utils.log import print_rank
from mindspeed.fsdp.utils.str_match import module_name_match
logger = logging.getLogger(__name__)
def recompute_modules(model, plan):
    modules = get_recompute_modules(model, plan.apply_modules)
    for name, module in modules:
        print_rank(logger.info, f'Applying recompute to module: {name}')
        module.forward = recompute_wrapper(module.forward, plan.use_reentrant)
    return model
def get_recompute_modules(modules, plan):
    matched_modules = []
    for plan_name in plan:
        for name, module in modules.named_modules():
            if module_name_match(plan_name, name):
                matched_modules.append((name, module))
    if len(matched_modules) == 0:
        raise RuntimeError(f'[Recompute] No module named {plan}.')
    return matched_modules
def recompute_wrapper(function, use_reentrant):
    def wrapper(*args, **kwargs):
        kwargs['past_key_values'] = None  # transformers kv cache must be set None, or model use_cache=False
        if not use_reentrant:
            return checkpoint(function, *args, use_reentrant=use_reentrant, **kwargs)
        else:
            bound_function = functools.partial(function, **kwargs)
            return checkpoint(bound_function, *args, use_reentrant=use_reentrant)
    return wrapper

from enum import Enum, auto
from itertools import count
from ..layers.sampler import SamplingParams
class SequenceStatus(Enum):
    WAITING = auto()
    RUNNING = auto()
    FINISHED = auto()
class Sequence:
    block_size = 256
    counter = count()
    def __init__(self, token_ids: list[int], sampling_params = SamplingParams()):
        self.seq_id = next(Sequence.counter)
        self.status = SequenceStatus.WAITING
        self.token_ids = copy(token_ids)
        self.last_token = token_ids[-1]
        self.num_tokens = len(self.token_ids)
        self.num_prompt_tokens = len(token_ids)
        self.num_cached_tokens = 0
        self.block_table = []
        self.temperature = sampling_params.temperature
        self.max_tokens = sampling_params.max_tokens
        self.ignore_eos = sampling_params.ignore_eos
        self.pre_verify = True
        self.num_acc_tokens = []
        self.cur_acc_tokens = 0
    def __len__(self):
        return self.num_tokens
    def __getitem__(self, key):
        return self.token_ids[key]
    @property
    def is_finished(self):
        return self.status == SequenceStatus.FINISHED
    @property
    def num_completion_tokens(self):
        return self.num_tokens - self.num_prompt_tokens
    @property
    def prompt_token_ids(self):
        return self.token_ids[:self.num_prompt_tokens]
    @property
    def completion_token_ids(self):
        return self.token_ids[self.num_prompt_tokens:]
    @property
    def num_cached_blocks(self):
        return self.num_cached_tokens // self.block_size
    @property
    def num_blocks(self):
        return (self.num_tokens + self.block_size - 1) // self.block_size
    @property
    def last_block_num_tokens(self):
        return self.num_tokens - (self.num_blocks - 1) * self.block_size
    def block(self, i):
        assert 0 <= i < self.num_blocks
        return self.token_ids[i*self.block_size: (i+1)*self.block_size]
    def append_token(self, token_id: int):
        self.token_ids.append(token_id)
        self.last_token = token_id
        self.num_tokens += 1
    # PEARL KV cache Rollback
    def rollback_tokens(self, n: int):
        assert n > 0
        self.token_ids = self.token_ids[:-n]
        self.last_token = self.token_ids[-1]
        self.num_tokens -= n
    def token_to_slot(self, token_index: int):
        block_id = token_index // self.block_size
        block_offset = token_index % self.block_size
        slot = self.block_table[block_id] * self.block_size + block_offset
        return slot
    def __getstate__(self):
        return (self.num_tokens, self.num_prompt_tokens, self.num_cached_tokens, self.block_table,
                self.temperature, self.ignore_eos, self.max_tokens, self.seq_id, self.pre_verify, 
                self.num_acc_tokens, self.cur_acc_tokens,
                self.token_ids if self.num_completion_tokens == 0 else self.last_token)
    def __setstate__(self, state):
        self.num_tokens, self.num_prompt_tokens, self.num_cached_tokens, self.block_table, self.temperature, self.ignore_eos, self.max_tokens, self.seq_id, self.pre_verify, self.num_acc_tokens, self.cur_acc_tokens = state[:-1]
        if self.num_completion_tokens == 0:
            self.token_ids = state[-1]
        else:
            self.last_token = state[-1]

