from safetensors import safe_open
import torch
from diffusers.pipelines.stable_diffusion.convert_from_ckpt import convert_ldm_unet_checkpoint, convert_ldm_vae_checkpoint
def rand_name(length=8, suffix=''):
    name = binascii.b2a_hex(os.urandom(length)).decode('utf-8')
    if suffix:
        if not suffix.startswith('.'):
            suffix = '.' + suffix
        name += suffix
    return name
def cycle(dl):
    while True:
        for data in dl:
            yield data
def exists(x):
    return x is not None
def identity(x):
    return x
def load_dreambooth_lora(unet, vae=None, model_path=None, alpha=1.0, model_base=""):
    if model_path is None: return unet

    if model_path.endswith(".ckpt"):
        base_state_dict = torch.load(model_path)['state_dict']
    elif model_path.endswith(".safetensors"):
        state_dict = {}
        with safe_open(model_path, framework="pt", device="cpu") as f:
            for key in f.keys():
                state_dict[key] = f.get_tensor(key)

        is_lora = all("lora" in k for k in state_dict.keys())
        if not is_lora:
            base_state_dict = state_dict
        else:
            base_state_dict = {}
            with safe_open(model_base, framework="pt", device="cpu") as f:
                for key in f.keys():
                    base_state_dict[key] = f.get_tensor(key)

    converted_unet_checkpoint = convert_ldm_unet_checkpoint(base_state_dict, unet.config)
    unet_state_dict = unet.state_dict()
    for key in converted_unet_checkpoint:
        converted_unet_checkpoint[key] = alpha * converted_unet_checkpoint[key] + (1.0-alpha) * unet_state_dict[key]
    unet.load_state_dict(converted_unet_checkpoint, strict=False)
    if vae is not None:
        converted_vae_checkpoint = convert_ldm_vae_checkpoint(base_state_dict, vae.config)
        vae.load_state_dict(converted_vae_checkpoint)

    return unet, vae

import torch.fx as fx
from graph_net.torch.dim_gen_passes import DimensionGeneralizationPass
from collections import namedtuple
import os
class ConcretePass(DimensionGeneralizationPass):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
    def get_pass_name(cls) -> bool:
        return os.path.basename(__file__)[:-3]
    def need_rewrite(self, traced_module: fx.GraphModule) -> bool:
        # non batch
        if 0 in self.axes:
            return False
        return any(self._node_need_rewrite(node) for node in traced_module.graph.nodes)
    def node_target(self):
        return torch.arange
    def _node_need_rewrite(self, node) -> bool:
        if not (node.op == "call_function"):
            return False
        if not (node.target == self.node_target()):
            return False
        if len(node.args) == 1:
            return node.args[0] == self.dim
        elif len(node.args) == 2:
            return node.args[0] == 0 and node.args[1] == self.dim
        else:
            return False
    def rewrite(self, traced_module: fx.GraphModule) -> fx.GraphModule:
        # Create a new graph to hold the rewritten nodes
        new_graph = fx.Graph()
        # Create a map to link nodes from the old graph to nodes in the new graph
        val_map = {}
        NodeAxis = namedtuple("NodeAxis", ["node", "shape_axis"])
        last_node_axis = None
        def try_reset_last_node_axis(node, new_node):
            nonlocal last_node_axis
            node_meta = node.meta.get("tensor_meta")
            if node_meta is None:
                return
            if not hasattr(node_meta, "shape"):
                return
            for axis, dim in enumerate(node_meta.shape):
                if not (dim == self.dim and axis > 0):
                    continue
                last_node_axis = NodeAxis(node=new_node, shape_axis=axis)
                return
        def get_new_node_arg(i, arg, len_args):
            if not ((len_args == 2 and i == 1) or (len_args == 1 and i == 0)):
                return val_map[arg] if arg in val_map else arg
            # i == 1
            assert arg == self.dim
            # Use the size() method to retrieve the dynamic dimension
            size_node = new_graph.call_method(
                "size", args=(last_node_axis.node, last_node_axis.shape_axis)
            )
            return size_node
        def create_new_node(node):
            if not (self._node_need_rewrite(node) and last_node_axis is not None):
                # Copy other nodes to the new graph
                new_node = new_graph.node_copy(node, lambda x: val_map[x])
                try_reset_last_node_axis(node=node, new_node=new_node)
                return new_node
            new_node_args = tuple(
                get_new_node_arg(i, arg, len(node.args))
                for i, arg in enumerate(node.args)
            )
            new_node = new_graph.call_function(
                self.node_target(), args=new_node_args, kwargs=node.kwargs
            )
            return new_node
        for node in traced_module.graph.nodes:
            val_map[node] = create_new_node(node)
        # Replace the old graph with the new graph and return
        traced_module.graph = new_graph
        traced_module.recompile()
        return traced_module

def extract_turn_id(payload: Any) -> Optional[str]:
    if not isinstance(payload, dict):
        return None
    for key in ("turnId", "turn_id", "id"):
        value = payload.get(key)
        if isinstance(value, str):
            return value
    turn = payload.get("turn")
    if isinstance(turn, dict):
        for key in ("id", "turnId", "turn_id"):
            value = turn.get(key)
            if isinstance(value, str):
                return value
    item = payload.get("item")
    if isinstance(item, dict):
        for key in ("turnId", "turn_id", "id"):
            value = item.get(key)
            if isinstance(value, str):
                return value
    return None
def _extract_thread_id_from_container(payload: Any) -> Optional[str]:
    if not isinstance(payload, dict):
        return None
    for key in ("threadId", "thread_id"):
        value = payload.get(key)
        if isinstance(value, str):
            return value
    thread = payload.get("thread")
    if isinstance(thread, dict):
        for key in ("id", "threadId", "thread_id"):
            value = thread.get(key)
            if isinstance(value, str):
                return value
    return None
def extract_thread_id_for_turn(payload: Any) -> Optional[str]:
    if not isinstance(payload, dict):
        return None
    for candidate in (payload, payload.get("turn"), payload.get("item")):
        thread_id = _extract_thread_id_from_container(candidate)
        if thread_id:
            return thread_id
    return None
def extract_thread_id(payload: Any) -> Optional[str]:
