# Task scheduling system

class Task:
    def __init__(self, name, duration, priority):
        self.name = name
        # Duration in hours
        self.duration = duration  
        # Higher number means higher priority
        self.priority = priority  

    def __repr__(self):
        return f"Task(name={self.name}, duration={self.duration}, priority={self.priority})"


class Schedule:
    def __init__(self, free_hours):
        # Dictionary of free hours for each day
        self.free_hours = free_hours  
        # Initialize empty schedule
        self.schedule = {day: [] for day in free_hours}  

    def add_task(self, task, day):
        # Check if there's enough time available
        if self.free_hours[day] >= task.duration:
            self.schedule[day].append(task)
            self.free_hours[day] -= task.duration
            return True
        return False

    def optimize_schedule(self, tasks):
        # Sort tasks by priority (higher priority first)
        tasks.sort(key=lambda x: x.priority, reverse=True)

        # Try to fit each task into the schedule
        for task in tasks:
            for day in self.free_hours:
                if self.add_task(task, day):
                    break

    def print_schedule(self):
        # Display the schedule day by day
        for day, tasks in self.schedule.items():
            print(f"{day}:")
            for task in tasks:
                print(f"  - {task}")

