# Function to calculate average of values in a list
def sum_of_values(num_list):
    total = 0

    # Sum all values in the list
    for value in num_list:
        total += value

    # Return the average (sum divided by count)
    return total / len(num_list)

def custom_base_arithmetics(n, m, base, operation, step=1):
    """
    You are given two positive integers n and m, an integer (base) in the range [2, 16] (inclusive),
    a string operation which will be one of the following ["sum", "diff", "product", "average", "mod"],
    and an optional integer step (default is 1).

    Your task is to:
    1. First, perform the specified operation on the integers from n to m (inclusive) with the given step.
    2. Then, round the result to the nearest integer.
    3. Finally, convert that to the custom base system and return the result.

    If n is greater than m, return -1.
    If base is outside the allowed range, also return -1.
    If step is less than or equal to 0, return -1.

    Example:
    custom_base_arithmetics(1, 5, 2, "average") => "0b11"
    custom_base_arithmetics(7, 5, 2, "sum") => -1
    custom_base_arithmetics(10, 20, 2, "product", 2) => "0b11111111111100000"
    custom_base_arithmetics(20, 33, 2, "diff", 3) => "0b11010"
    custom_base_arithmetics(20, 33, 8, "average", 2) => "0o32"
    custom_base_arithmetics(10, 20, 16, "mod", 2) => "0xa"
    """

    # Input validation
    if n > m:
        return -1

    if base < 2 or base > 16:
        return -1

    if step <= 0:
        return -1

    # Generate the sequence
    numbers = list(range(n, m + 1, step))

    # Handle empty sequence case
    if not numbers:
        return -1

    # Perform the specified operation
    if operation == "sum":
        result = sum(numbers)
    elif operation == "diff":
        # Subtract consecutive numbers: n - (n+step) - (n+2*step) - ...
        result = numbers[0]
        for i in range(1, len(numbers)):
            result -= numbers[i]
    elif operation == "product":
        result = 1
        for num in numbers:
            result *= num
    elif operation == "average":
        result = sum(numbers) / len(numbers)
    elif operation == "mod":
        # Modulo chain: n % (n+step) % (n+2*step) % ...
        result = numbers[0]
        for i in range(1, len(numbers)):
            result %= numbers[i]
    else:
        return -1

    # Round to nearest integer
    result = round(result)

    # Convert to custom base representation
    if base == 2:
        return bin(result)
    elif base == 8:
        return oct(result)
    elif base == 16:
        return hex(result)
    else:
        # Custom base conversion for bases 2-16 (excluding standard ones handled above)
        if result == 0:
            return "0"

        digits = "0123456789ABCDEF"
        sign = ""

        if result < 0:
            sign = "-"
            result = -result

        converted = ""
        while result > 0:
            converted = digits[result % base] + converted
            result //= base

        # Add appropriate prefix based on base
        if base == 2:
            return "0b" + converted
        elif base == 8:
            return "0o" + converted
        elif base == 16:
            return "0x" + converted
        else:
            return sign + converted

# Import the IMDb module
import imdb

# Initialize the IMDb object
i = imdb.IMDb()


def get_person_id(name):
    """
    Fetch the IMDb ID of a person by their name.
    Returns the personID if found, otherwise None.
    """
    try:
        results = i.search_person(name)
        if results:
            return results[0].personID
        else:
            raise ValueError(f"No person found with the name {name}")
    except Exception as e:
        print(f"An error occurred: {e}")
        return None


def get_filmography(person_id):
    """
    Fetch the filmography of a person by their IMDb ID.
    Returns the filmography dictionary or an empty list on error.
    """
    try:
        person = i.get_person(person_id, info=['filmography'])
        return person.get('filmography', [])
    except Exception as e:
        print(f"An error occurred: {e}")
        return []


def average_movie_rating(filmography):
    """
    Calculate the average rating of movies in the filmography.
    Returns 0 if no rated movies are found.
    """
    total_ratings = 0
    num_movies = 0

    for category in filmography:
        for movie in filmography[category]:
            if 'rating' in movie and movie['rating']:
                total_ratings += movie['rating']
                num_movies += 1

    return total_ratings / num_movies if num_movies > 0 else 0


def list_co_actors(filmography):
    """
    Return a dictionary mapping movie titles to lists of co-actors,
    excluding Daniel Day-Lewis himself from the co-actor list.
    """
    co_actors = {}

    for category in filmography:
        for movie in filmography[category]:
            if 'cast' in movie:
                # Filter out Daniel Day-Lewis from the cast list
                co_actors[movie['title']] = [
                    cast['name'] 
                    for cast in movie['cast'] 
                    if cast['name'] != 'Daniel Day-Lewis'
                ]

    return co_actors


def count_directors(filmography):
    """
    Count how many times the actor has worked with each director.
    Returns a dictionary mapping director names to work counts.
    """
    directors = {}

    for category in filmography:
        for movie in filmography[category]:
            if 'director' in movie:
                for director in movie['director']:
                    director_name = director['name']
                    if director_name in directors:
                        directors[director_name] += 1
                    else:
                        directors[director_name] = 1

    return directors


# Main function to run the analysis
def analyze_actor_filmography(name):
    person_id = get_person_id(name)

    if person_id:
        filmography = get_filmography(person_id)

        if filmography:
            avg_rating = average_movie_rating(filmography)
            co_actors = list_co_actors(filmography)
            directors = count_directors(filmography)

            return {
                'average_rating': avg_rating,
                'co_actors': co_actors,
                'directors': directors
            }

    return None


