# Student class definition
class Student:
    def __init__(self, name, age, course):
        # Validate age
        if not (18 <= age <= 99):
            raise ValueError("Age must be between 18 and 99.")

        # Validate name length
        if len(name) > 100:
            raise ValueError("Name cannot exceed 100 characters.")

        # Validate course name length
        if len(course) > 50:
            raise ValueError("Course name cannot exceed 50 characters.")

        # Assign attributes
        self.name = name
        self.age = age
        self.course = course

    # Representation method
    def __repr__(self):
        return f"Student(Name={self.name}, Age={self.age}, Course={self.course})"


# StudentManager class for managing student records
class StudentManager:
    def __init__(self):
        self.students = []
        self.name_index = {}

    # Add a new student
    def add_student(self, name, age, course):
        student = Student(name, age, course)
        self.students.append(student)

        # Maintain index by name
        if name in self.name_index:
            self.name_index[name].append(student)
        else:
            self.name_index[name] = [student]

    # Remove the first occurrence of a student by name
    def remove_student(self, name):
        if name in self.name_index:
            student_to_remove = self.name_index[name].pop(0)
            self.students.remove(student_to_remove)

            # Clean up empty list in index
            if not self.name_index[name]:
                del self.name_index[name]

    # Search students by name
    def search_student(self, name):
        if name in self.name_index:
            return self.name_index[name]
        return []

    # Update student information
    def update_student(self, name, age=None, course=None):
        if name in self.name_index:
            student_to_update = self.name_index[name][0]

            # Update age if provided
            if age is not None:
                if not (18 <= age <= 99):
                    raise ValueError("Age must be between 18 and 99.")
                student_to_update.age = age

            # Update course if provided
            if course is not None:
                if len(course) > 50:
                    raise ValueError("Course name cannot exceed 50 characters.")
                student_to_update.course = course

    # Display students sorted alphabetically by name
    def display_students_sorted(self):
        sorted_students = sorted(self.students, key=lambda x: x.name)
        return sorted_students


