# Tic Tac Toe Game Implementation

def print_board(board):
    # Display the current state of the board
    print("-------------")
    for row in board:
        print("|", end=" ")
        for cell in row:
            print(cell, end=" | ")
        print("\n-------------")

def check_winner(board, player):
    # Check rows, columns, and diagonals for a win
    # Check each row
    for row in board:
        if all([cell == player for cell in row]):
            return True

    # Check each column
    for col in range(3):
        if all([board[row][col] == player for row in range(3)]):
            return True

    # Check main diagonal (top-left to bottom-right)
    if all([board[i][i] == player for i in range(3)]):
        return True

    # Check anti-diagonal (top-right to bottom-left)
    if all([board[i][2-i] == player for i in range(3)]):
        return True

    return False

def is_full(board):
    # Check if the board has no empty cells
    return all([cell != " " for row in board for cell in row])

def main():
    # Initialize the game board
    board = [[" " for _ in range(3)] for _ in range(3)]
    current_player = "X"

    # Main game loop
    while True:
        print_board(board)

        try:
            # Get player input
            move = int(input(f"Player {current_player}, enter your move (1-9): "))

            # Validate move range
            if move < 1 or move > 9:
                raise ValueError("Invalid move. Please choose a number between 1 and 9.")

            # Convert move to row and column indices
            row, col = (move-1) // 3, (move-1) % 3

            # Check if cell is already taken
            if board[row][col] != " ":
                raise ValueError("Cell already taken. Choose another one.")

            # Place the player's mark on the board
            board[row][col] = current_player

            # Check for winner
            if check_winner(board, current_player):
                print_board(board)
                print(f"Player {current_player} wins!")
                break

            # Check for tie
            if is_full(board):
                print_board(board)
                print("It's a tie!")
                break

            # Switch players
            current_player = "O" if current_player == "X" else "X"

        except ValueError as e:
            print(e)

# Run the game when script is executed directly
if __name__ == "__main__":
    main()

import sqlite3

def is_number_in_range(value, expected_type, lower, upper):
    # Check if value is of the expected type
    if not isinstance(value, expected_type):
        return f"not an {expected_type.__name__}"

    # Check if value is within the specified range
    if value < lower or value > upper:
        return f"{expected_type.__name__} out of range [{lower}-{upper}]."

    return "OK"

def not_default(value, expected_type, default_value):
    # Check if value is of the expected type
    if not isinstance(value, expected_type):
        return f"not an {expected_type.__name__}"

    # Check if value equals the default value
    if value == default_value:
        return f"default value of {default_value} - make sure this is what you want."

    return "OK"

