class Phone:
    def __init__(self, brand, model, os, battery_capacity, screen_size):
        # Initialize phone attributes
        self.brand = brand
        self.model = model
        self.os = os
        self.battery_capacity = battery_capacity
        self.screen_size = screen_size

        # Additional attributes
        self.battery_level = battery_capacity  # Initially fully charged
        self.is_powered_on = False

    def power_on(self):
        if not self.is_powered_on:
            self.is_powered_on = True
            print(f"{self.brand} {self.model} is powered on.")
        else:
            print(f"{self.brand} {self.model} is already powered on.")

    def power_off(self):
        if self.is_powered_on:
            self.is_powered_on = False
            print(f"{self.brand} {self.model} is powered off.")
        else:
            print(f"{self.brand} {self.model} is already powered off.")

    def use_battery(self, usage):
        if self.is_powered_on:
            if self.battery_level >= usage:
                self.battery_level -= usage
                print(f"Battery level: {self.battery_level} mAh")
            else:
                print("Not enough battery to perform this action.")
        else:
            print("The phone is powered off. Please power it on.")

    def charge_battery(self, amount):
        if self.battery_level + amount <= self.battery_capacity:
            self.battery_level += amount
            print(f"Battery level: {self.battery_level} mAh")
        else:
            self.battery_level = self.battery_capacity
            print("Battery is fully charged.")

# Import regular expressions module
import re

def find_repeated_word_and_unique_letter(text):
    # Initialize variables to store results
    repeated_word = None
    repeated_word_pos = None
    unique_letter = None
    unique_letter_pos = None

    # Split the text into words using regex
    words = re.findall(r'\b\w+\b', text)

    # Check for repeated words with at least 4 consecutive occurrences
    for i in range(len(words) - 3):
        if words[i] == words[i + 1] == words[i + 2] == words[i + 3]:
            repeated_word = words[i]
            repeated_word_pos = i
            break

    # Count letter occurrences and their positions
    letter_counts = {}
    for pos, char in enumerate(text):
        if char.isalpha():
            if char in letter_counts:
                letter_counts[char].append(pos)
            else:
                letter_counts[char] = [pos]

    # Find the first unique letter (appears exactly once)
    for letter, positions in letter_counts.items():
        if len(positions) == 1:
            unique_letter = letter
            unique_letter_pos = positions[0]
            break

    return repeated_word, repeated_word_pos, unique_letter, unique_letter_pos

