import psycopg2
import xml.etree.ElementTree as ET
from datetime import datetime

def connect_to_db():
    # Establish database connection
    try:
        connection = psycopg2.connect(
            host="your_host",
            database="your_database",
            user="your_user",
            password="REDACTED_CREDENTIAL"
        )
        return connection
    except Exception as e:
        print(f"Error connecting to the database: {e}")
        return None

def execute_query(connection):
    # Execute SQL query and fetch results
    try:
        cursor = connection.cursor()
        query = """
        SELECT * FROM customers 
        WHERE customer_city ILIKE '%New York%' 
        AND signup_date BETWEEN '2020-01-01' AND '2020-03-01'
        """
        cursor.execute(query)
        rows = cursor.fetchall()
        cursor.close()
        return rows
    except Exception as e:
        print(f"Error executing the query: {e}")
        return None

def generate_xml(rows):
    # Generate XML from query results
    if not rows:
        return "<customers></customers>"

    root = ET.Element("customers")
    for row in rows:
        customer = ET.SubElement(root, "customer")
        for i, column in enumerate(row):
            ET.SubElement(customer, f"column_{i}").text = str(column)

    return ET.tostring(root, encoding='utf-8').decode('utf-8')

def main():
    # Main function to orchestrate the workflow
    connection = connect_to_db()
    if connection:
        rows = execute_query(connection)
        if rows:
            xml_result = generate_xml(rows)
            print(xml_result)
        else:
            print("No rows returned from the query.")
        connection.close()
    else:
        print("Failed to connect to the database.")

