# Import necessary modules for thread and process safety
import threading
import multiprocessing
import functools


class SingletonMeta(type):
    # Class-level variables to store instances and locks
    _instances = {}
    _lock = threading.Lock()
    _multiprocessing_lock = multiprocessing.Lock()

    def __call__(cls, *args, **kwargs):
        # Thread-safe singleton creation (double-checked locking)
        with cls._lock:
            if cls not in cls._instances:
                # Ensure atomic and thread-safe instantiation
                if cls not in cls._instances:
                    cls._instances[cls] = super(SingletonMeta, cls).__call__(*args, **kwargs)

        # Multiprocessing-safe singleton creation
        with cls._multiprocessing_lock:
            if cls not in cls._instances:
                # Ensure atomic and multiprocessing-safe instantiation
                if cls not in cls._instances:
                    cls._instances[cls] = super(SingletonMeta, cls).__call__(*args, **kwargs)

        return cls._instances[cls]


class Singleton(metaclass=SingletonMeta):
    def __init__(self, value=None):
        self.value = value

    def some_method(self):
        print(f"Singleton instance with value: {self.value}")


# Example usage
if __name__ == "__main__":
    # Thread-safe singleton creation
    def thread_worker():
        singleton = Singleton(value="Thread")
        singleton.some_method()

    threads = []
    for _ in range(5):
        t = threading.Thread(target=thread_worker)
        t.start()
        threads.append(t)
    for t in threads:
        t.join()

    # Multiprocessing-safe singleton creation
    def process_worker():
        singleton = Singleton(value="Process")
        singleton.some_method()

    processes = []
    for _ in range(5):
        p = multiprocessing.Process(target=process_worker)
        p.start()
        processes.append(p)
    for p in processes:
        p.join()

# Import necessary modules
import re
import random
import string
import logging

# Configure logging
logging.basicConfig(
    level=logging.DEBUG,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


class URLManager:
    def __init__(self, protocol, subdomain, primary_domain, cc_tld, resource_path):
        self.protocol = protocol
        self.subdomain = subdomain
        self.primary_domain = primary_domain
        self.cc_tld = cc_tld
        self.resource_path = resource_path

    def construct_url(self):
        # Validate components before constructing URL
        if not self.validate_components():
            return None

        # Construct and return the full URL
        return f"{self.protocol}://{self.subdomain}.{self.primary_domain}{self.cc_tld}/{self.encode_resource_path()}"

    def deconstruct_url(self, url):
        # Regular expression pattern to parse URL components
        pattern = r'^(?P<protocol>[a-zA-Z]+)://(?P<subdomain>[a-zA-Z0-9-]+)\.(?P<primary_domain>[a-zA-Z0-9-]+)(?P<cc_tld>\.[a-zA-Z]{2,6})/(?P<resource_path>.+)$'

        match = re.match(pattern, url)

        if match:
            return match.groupdict()
        else:
            logging.error(f"Invalid URL format: {url}")
            return None

    def validate_components(self):
        # Check if all required components are provided
        if not self.protocol or not self.subdomain or not self.primary_domain or not self.cc_tld or not self.resource_path:
            logging.error("All URL components must be provided.")
            return False

        # Validate protocol
        if self.protocol not in ['http', 'https', 'ftp', 'sftp']:
            logging.error(f"Unsupported protocol: {self.protocol}")
            return False

        # Validate subdomain format
        if not re.match(r'^[a-zA-Z0-9-]+$', self.subdomain):
            logging.error(f"Invalid subdomain: {self.subdomain}")
            return False

        # Validate primary domain format
        if not re.match(r'^[a-zA-Z0-9-]+$', self.primary_domain):
            logging.error(f"Invalid primary domain: {self.primary_domain}")
            return False

        # Validate country code top-level domain format
        if not re.match(r'^\.[a-zA-Z]{2,6}$', self.cc_tld):
            logging.error(f"Invalid country code top-level domain: {self.cc_tld}")
            return False

        return True

    def encode_resource_path(self, random_encode=False):
        # Choose encoding method based on parameter
        if random_encode:
            return self.random_encode_resource_path()
        else:
            return self.sequential_encode_resource_path()

    def sequential_encode_resource_path(self):
        # Encode non-alphanumeric characters (except '/') using percent-encoding
        return re.sub(
            r'[^a-zA-Z0-9/]',
            lambda match: f"%{ord(match.group(0)):02X}",
            self.resource_path
        )

    def random_encode_resource_path(self):
        # Randomly decide whether to encode each special character
        encoded_path = ""
        for char in self.resource_path:
            if re.match(r'[^a-zA-Z0-9/]', char):
                if random.choice([True, False]):
                    encoded_path += f"%{ord(char):02X}"
                else:
                    encoded_path += char
            else:
                encoded_path += char
        return encoded_path

# Function to filter and sort students based on criteria
def filter_and_sort_students(students, min_height, min_weight, min_age, min_gPA):

    # Helper function to validate student data structure
    def is_valid_student_data(data):
        if not isinstance(data, tuple) or len(data) != 4:
            return False
        if not all(isinstance(x, (int, float)) for x in data):
            return False
        return True

    # Helper function to convert data to numeric values
    def convert_to_numeric(data):
        try:
            return tuple(float(x) for x in data)
        except ValueError:
            raise TypeError(f"Non-numeric value in student data: {data}")

    # List to store filtered students
    filtered_students = []

    # Iterate through all students
    for name, data in students.items():
        # Validate student data
        if not is_valid_student_data(data):
            raise ValueError(f"Invalid student data for {name}: {data}")

        # Convert and unpack data
        height, weight, age, gpa = convert_to_numeric(data)

        # Check against minimum thresholds
        if height >= min_height and weight >= min_weight and age >= min_age and gpa >= min_gPA:
            filtered_students.append((name, height, weight, age, gpa))

    # Sort by age (descending), then GPA (descending), then name (ascending)
    filtered_students.sort(key=lambda x: (-x[3], -x[4], x[0]))

    return filtered_students


