# Initialize a 3x3 board with zeros
def initialize_board():
    return [[0 for _ in range(3)] for _ in range(3)]

# Print the current state of the board
def print_board(board):
    for row in board:
        print(" ".join(["X" if cell == 1 else "O" if cell == 2 else "." for cell in row]))

# Check if a move is valid (cell is empty)
def is_valid_move(board, row, col):
    return board[row][col] == 0

# Make a move on the board if valid
def make_move(board, row, col, player):
    if is_valid_move(board, row, col):
        board[row][col] = player
        return True
    return False

# Check if the given player has won
def check_win(board, player):
    # Check rows and columns
    for i in range(3):
        if all(board[i][j] == player for j in range(3)) or \
           all(board[j][i] == player for j in range(3)):
            return True

    # Check diagonals
    if all(board[i][i] == player for i in range(3)) or \
       all(board[i][2-i] == player for i in range(3)):
        return True

    return False

# Check if the board is completely filled
def is_board_full(board):
    return all(cell != 0 for row in board for cell in row)

# Main game loop
def play_game():
    board = initialize_board()
    current_player = 1

    while True:
        print_board(board)
        row = int(input(f"Player {current_player}, enter row (0-2): "))
        col = int(input(f"Player {current_player}, enter column (0-2): "))

        if make_move(board, row, col, current_player):
            if check_win(board, current_player):
                print_board(board)
                print(f"Player {current_player} wins!")
                break
            elif is_board_full(board):
                print_board(board)
                print("It's a draw!")
                break
            current_player = 3 - current_player  # Switch player (1 -> 2, 2 -> 1)
        else:
            print("Invalid move. Try again.")

play_game()

import threading
from typing import List, Tuple

class Drone:
    def __init__(self, id: int, initial_position: Tuple[float, float, float] = (0, 0, 0)):
        self.id = id
        self.position = initial_position
        self.speed = 1.0  # Default speed in m/s
        self.altitude = initial_position[2]
        self.is_flying = False
        self.is_landed = True
        self.waypoints = []
        self.current_waypoint_index = 0
        self.lock = threading.Lock()
        self.sensors = {
            'collision': False,
            'battery': 100.0  # Percentage
        }

    def lift(self):
        with self.lock:
            if not self.is_flying:
                self.altitude = 10  # Lift to 10 meters
                self.is_flying = True
                self.is_landed = False
                print(f"Drone {self.id} lifted to {self.altitude} meters.")

    def move(self, position: Tuple[float, float, float]):
        with self.lock:
            if self.is_flying:
                self.position = position
                self.altitude = position[2]
                print(f"Drone {self.id} moved to {self.position}.")

    def land(self):
        with self.lock:
            if self.is_flying:
                self.altitude = 0
                self.is_flying = False
                self.is_landed = True
                print(f"Drone {self.id} landed.")

    def set_waypoints(self, waypoints: List[Tuple[float, float, float]]):
        with self.lock:
            self.waypoints = waypoints
            self.current_waypoint_index = 0
            print(f"Drone {self.id} waypoints set to {self.waypoints}.")

    def navigate_waypoints(self):
        with self.lock:
            if self.is_flying and self.current_waypoint_index < len(self.waypoints):
                next_waypoint = self.waypoints[self.current_waypoint_index]
                self.move(next_waypoint)
                self.current_waypoint_index += 1
                if self.current_waypoint_index == len(self.waypoints):
                    print(f"Drone {self.id} reached all waypoints.")
                else:
                    threading.Timer(1.0, self.navigate_waypoints).start()
            else:
                print(f"Drone {self.id} navigation completed or not flying.")

    def interpret_sensor_data(self):
        with self.lock:
            if self.sensors['collision']:
                print(f"Drone {self.id} detected collision. Stopping and landing.")
                self.land()
            if self.sensors['battery'] < 20:
                print(f"Drone {self.id} battery low. Returning to home.")
                self.move((0, 0, 10))
                self.land()

    def real_time_adjust(self, sensor_data: dict):
        with self.lock:
            self.sensors.update(sensor_data)
            self.interpret_sensor_data()

    def drop_off(self, position: Tuple[float, float, float]):
        with self.lock:
            if self.is_flying:
                self.move(position)
                print(f"Drone {self.id} dropped off at {position}.")

    def pick_up(self, position: Tuple[float, float, float]):
        with self.lock:
            if self.is_flying:
                self.move(position)
                print(f"Drone {self.id} picked up from {position}.")

class DroneControlSystem:
    def __init__(self):
        self.drones = {}
        self.lock = threading.Lock()

    def add_drone(self, drone: Drone):
        with self.lock:
            self.drones[drone.id] = drone
            print(f"Drone {drone.id} added to the system.")

    def control_drone(self, drone_id: int, command: str, *args, **kwargs):
        with self.lock:
            if drone_id in self.drones:
                drone = self.drones[drone_id]
                if command == 'lift':
                    drone.lift()
                elif command == 'move':
                    drone.move(*args)
                elif command == 'land':
                    drone.land()
                elif command == 'set_waypoints':
                    drone.set_waypoints(*args)
                elif command == 'navigate_waypoints':
                    drone.navigate_waypoints()
                elif command == 'real_time_adjust':
                    drone.real_time_adjust(*args)
                elif command == 'drop_off':
                    drone.drop_off(*args)
                elif command == 'pick_up':
                    drone.pick_up(*args)
                else:
                    print(f"Unknown command: {command}")
            else:
                print(f"Drone {drone_id} not found in the system.")

    def control_multiple_drones(self, commands: List[dict]):
        with self.lock:
            for command in commands:
                drone_id = command.get('drone_id')
                command_str = command.get('command')
                args = command.get('args', [])
                kwargs = command.get('kwargs', {})
                self.control_drone(drone_id, command_str, *args, **kwargs)

