import urllib2
import time
import random

def urlopen(url, max_retries=5, backoff_factor=2):
    response = None
    request = urllib2.Request(url=url)
    request.add_header('User-Agent', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3')

    for attempt in range(max_retries):
        try:
            response = urllib2.urlopen(request).read()
            break  # If the request is successful, break out of the loop

        except urllib2.HTTPError as err:
            print "HTTPError: {} ({})".format(url, err.code)
            if err.code != 429:  # If the error is not a rate limit error, break out of the loop
                break

        except urllib2.URLError as err:
            print "URLError: {} ({})".format(url, err.reason)

        except Exception as err:
            print "Unexpected error: {}".format(err)

        if attempt < max_retries - 1:
            wait_time = backoff_factor * (2 ** attempt) + random.uniform(0, 1)
            print "Retrying in {:.2f} seconds...".format(wait_time)
            time.sleep(wait_time)

    return response

