import numpy as np
import gym
import random
from collections import defaultdict

# Define the Connect 4 environment
class Connect4Env(gym.Env):
    def __init__(self, rows=6, cols=7, inarow=4):
        self.rows = rows
        self.cols = cols
        self.inarow = inarow
        self.board = np.zeros((rows, cols), dtype=int)
        self.current_player = 1
        self.done = False
        self.winner = None
        self.legal_moves = list(range(cols))

    def reset(self):
        # Reset board and game state
        self.board = np.zeros((self.rows, self.cols), dtype=int)
        self.current_player = 1
        self.done = False
        self.winner = None
        self.legal_moves = list(range(self.cols))
        return self.board

    def step(self, action):
        # Validate move
        if action not in self.legal_moves:
            return self.board, -10, True, {'winner': -1}

        # Drop piece in the selected column
        for row in range(self.rows - 1, -1, -1):
            if self.board[row, action] == 0:
                self.board[row, action] = self.current_player
                break

        # Check win condition
        if self.check_winner():
            self.done = True
            self.winner = self.current_player
            reward = 1
        elif len(self.legal_moves) == 0:
            self.done = True
            self.winner = 0
            reward = 0
        else:
            reward = 0

        # Switch turns
        self.current_player = 3 - self.current_player  # Switch player (1 -> 2, 2 -> 1)
        self.legal_moves = [col for col in range(self.cols) if self.board[0, col] == 0]

        return self.board, reward, self.done, {'winner': self.winner}

    def check_winner(self):
        # Check horizontal, vertical, and diagonal wins
        for row in range(self.rows):
            for col in range(self.cols):
                if self.board[row, col] != 0:
                    # Horizontal check
                    if col <= self.cols - self.inarow and np.all(self.board[row, col:col + self.inarow] == self.board[row, col]):
                        return True
                    # Vertical check
                    if row <= self.rows - self.inarow and np.all(self.board[row:row + self.inarow, col] == self.board[row, col]):
                        return True
                    # Diagonal (positive slope)
                    if row <= self.rows - self.inarow and col <= self.cols - self.inarow and np.all(self.board[row:row + self.inarow, col:col + self.inarow].diagonal() == self.board[row, col]):
                        return True
                    # Diagonal (negative slope)
                    if row <= self.rows - self.inarow and col >= self.inarow - 1 and np.all(np.fliplr(self.board[row:row + self.inarow, col - self.inarow + 1:col + 1]).diagonal() == self.board[row, col]):
                        return True
        return False

    def render(self):
        print(self.board)

# Q-Learning Agent
class QLearningAgent:
    def __init__(self, env, alpha=0.1, gamma=0.9, epsilon=0.1):
        self.env = env
        self.alpha = alpha
        self.gamma = gamma
        self.epsilon = epsilon
        # Initialize Q-table with default values
        self.q_table = defaultdict(lambda: np.zeros(env.action_space.n))

    def choose_action(self, state):
        # Epsilon-greedy policy
        if random.uniform(0, 1) < self.epsilon:
            return random.choice(self.env.legal_moves)
        else:
            q_values = self.q_table[state.tobytes()]
            return np.argmax(q_values)

    def learn(self, state, action, reward, next_state):
        # Q-learning update rule
        best_next_action = np.argmax(self.q_table[next_state.tobytes()])
        td_target = reward + self.gamma * self.q_table[next_state.tobytes()][best_next_action]
        td_error = td_target - self.q_table[state.tobytes()][action]
        self.q_table[state.tobytes()][action] += self.alpha * td_error

    def train(self, episodes):
        # Training loop
        for episode in range(episodes):
            state = self.env.reset()
            done = False
            while not done:
                action = self.choose_action(state)
                next_state, reward, done, info = self.env.step(action)
                self.learn(state, action, reward, next_state)
                state = next_state
            # Progress tracking
            if (episode + 1) % 100 == 0:
                print(f"Episode {episode + 1}/{episodes} completed")

    def play(self):
        # Play a single game
        state = self.env.reset()
        done = False
        while not done:
            action = self.choose_action(state)
            state, reward, done, info = self.env.step(action)
            self.env.render()
            if done:
                if info['winner'] == 1:
                    print("Player 1 wins!")
                elif info['winner'] == 2:
                    print("Player 2 wins!")
                else:
                    print("It's a draw!")
                break

# Initialize the environment and agent
env = Connect4Env()
agent = QLearningAgent(env)

# Train the agent
agent.train(10000)

# Play a game
