        print(f"{word} has {len(synonyms)} synonyms.")

# 2. List all synonyms for each word.
def list_synonyms(thesaurus):
    for word, synonyms in thesaurus.items():
        print(f"{word}: {', '.join(synonyms)}")

# 3. Find and display words that share at least one synonym.
def find_shared_synonyms(thesaurus):
    shared_synonyms = {}
    for word1, synonyms1 in thesaurus.items():
        for word2, synonyms2 in thesaurus.items():
            if word1 != word2 and set(synonyms1) & set(synonyms2):
                shared_synonyms.setdefault(word1, []).append(word2)

    for word, shared_words in shared_synonyms.items():
        print(f"{word} shares synonyms with: {', '.join(shared_words)}")

# 4. Find and display a 'synonym path' from a specified word to another specified word.
def find_synonym_path(thesaurus, start_word, end_word):
    # Create a graph from the thesaurus
    graph = {}
    for word, synonyms in thesaurus.items():
        graph[word] = set(synonyms)
        for synonym in synonyms:
            if synonym not in graph:
                graph[synonym] = set()
            graph[synonym].add(word)

    # BFS to find the path
    from collections import deque
    queue = deque([(start_word, [start_word])])
    visited = set([start_word])

    while queue:
        current_word, path = queue.popleft()
        if current_word == end_word:
            return path
        for neighbor in graph.get(current_word, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))

    return None

