# FCFS Scheduler Implementation

class Process:
    def __init__(self, pid, arrival_time, burst_time):
        self.pid = pid
        self.arrival_time = arrival_time
        self.burst_time = burst_time
        self.remaining_time = burst_time
        self.start_time = None
        self.end_time = None

    def __repr__(self):
        return f"Process({self.pid}, arrival_time={self.arrival_time}, burst_time={self.burst_time})"


class FCFS_Scheduler:
    def __init__(self):
        self.processes = []

    def add_process(self, process):
        self.processes.append(process)

    def schedule(self):
        # Sort processes based on arrival time
        self.processes.sort(key=lambda x: x.arrival_time)

        current_time = 0
        for process in self.processes:
            if process.arrival_time > current_time:
                current_time = process.arrival_time
            process.start_time = current_time
            current_time += process.burst_time
            process.end_time = current_time

    def get_gantt_chart(self):
        gantt_chart = []
        for process in self.processes:
            gantt_chart.append((process.start_time, process.end_time, process.pid))
        return gantt_chart

    def get_average_waiting_time(self):
        total_waiting_time = 0
        for process in self.processes:
            if process.start_time is not None:
                total_waiting_time += process.start_time - process.arrival_time
        return total_waiting_time / len(self.processes)

    def get_average_turnaround_time(self):
        total_turnaround_time = 0
        for process in self.processes:
            if process.end_time is not None:
                total_turnaround_time += process.end_time - process.arrival_time
        return total_turnaround_time / len(self.processes)


# Example usage
if __name__ == "__main__":
    scheduler = FCFS_Scheduler()

    # Add processes
    scheduler.add_process(Process(1, 0, 24))
    scheduler.add_process(Process(2, 4, 3))
    scheduler.add_process(Process(3, 5, 3))

    # Schedule processes
    scheduler.schedule()

    # Output results
    gantt_chart = scheduler.get_gantt_chart()
    print("Gantt Chart:")
    for start, end, pid in gantt_chart:
        print(f"Process {pid} from {start} to {end}")

    print(f"Average Waiting Time: {scheduler.get_average_waiting_time():.2f}")
    print(f"Average Turnaround Time: {scheduler.get_average_turnaround_time():.2f}")

