# Fibonacci Heap implementation

class FibonacciHeapNode:
    def __init__(self, key):
        self.key = key
        self.parent = None
        self.child = None
        self.left = self
        self.right = self
        self.degree = 0
        self.mark = False


class FibonacciHeap:
    def __init__(self):
        self.min = None
        self.num_nodes = 0
        self.max = None

    def insert(self, key):
        node = FibonacciHeapNode(key)
        if self.min is None:
            self.min = node
        else:
            self._link(node, self.min)
            if node.key < self.min.key:
                self.min = node
        self.num_nodes += 1

    def _link(self, node1, node2):
        # Link node1 as a child of node2
        node1.left.right = node1.right
        node1.right.left = node1.left
        node1.parent = node2
        if node2.child is None:
            node2.child = node1
        else:
            node1.right = node2.child
            node1.left = node2.child.left
            node2.child.left.right = node1
            node2.child.left = node1
        node2.degree += 1
        node1.mark = False

    def extract_min(self):
        z = self.min
        if z is not None:
            if z.child is not None:
                # Add all children of z to the root list
                child = z.child
                while True:
                    next_child = child.right
                    child.left.right = child.right
                    child.right.left = child.left
                    self._link(child, self.min)
                    if next_child == z.child:
                        break
                    child = next_child
            z.left.right = z.right
            z.right.left = z.left
            if z == z.right:
                self.min = None
            else:
                self.min = z.right
                self._consolidate()
            self.num_nodes -= 1
        if z == self.max:
            self.max = self._find_max()
        return z.key

    def _consolidate(self):
        A = [None] * (self.num_nodes.bit_length() + 1)
        w = self.min
        if w is not None:
            nodes = []
            while True:
                nodes.append(w)
                w = w.right
                if w == self.min:
                    break
            for w in nodes:
                x = w
                d = x.degree
                while A[d] is not None:
                    y = A[d]
                    if x.key > y.key:
                        x, y = y, x
                    self._link(y, x)
                    A[d] = None
                    d += 1
                A[d] = x
            self.min = None
            for i in range(len(A)):
                if A[i] is not None:
                    if self.min is None:
                        self.min = A[i]
                    else:
                        self._link(A[i], self.min)
                        if A[i].key < self.min.key:
                            self.min = A[i]

    def decrease_key(self, node, new_key):
        if new_key > node.key:
            raise ValueError("new key is greater than current key")
        node.key = new_key
        parent = node.parent
        if parent is not None and node.key < parent.key:
            self._cut(node, parent)
            self._cascading_cut(parent)
        if node.key < self.min.key:
            self.min = node

    def _cut(self, node, parent):
        node.left.right = node.right
        node.right.left = node.left
        parent.degree -= 1
        if parent.child == node:
            parent.child = node.right
        node.left = node.right = node
        self._link(node, self.min)
        node.parent = None
        node.mark = False

    def _cascading_cut(self, node):
        parent = node.parent
        if parent is not None:
            if not node.mark:
                node.mark = True
            else:
                self._cut(node, parent)
                self._cascading_cut(parent)

    def delete(self, node):
        self.decrease_key(node, float('-inf'))
        self.extract_min()

    def find_min(self):
        return self.min.key if self.min is not None else None

    def _find_max(self):
        max_node = None
        if self.min is not None:
            max_node = self.min
            w = self.min.right
            while w != self.min:
                if w.key > max_node.key:
                    max_node = w
                w = w.right
        return max_node

    def find_max(self):
        if self.max is None:
            self.max = self._find_max()
        return self.max.key if self.max is not None else None

    def increase_key(self, node, new_key):
        if new_key < node.key:
            raise ValueError("new key is less than current key")
        node.key = new_key
        if node == self.min:
            self.min = self._find_min()
        if node == self.max:
            self.max = self._find_max()

    def merge(self, other_heap):
        if self.min is None:
            self.min = other_heap.min
        elif other_heap.min is not None:
            self.min.right.left = other_heap.min.left
            other_heap.min.left.right = self.min.right
            self.min.right = other_heap.min
            other_heap.min.left = self.min
            if other_heap.min.key < self.min.key:
                self.min = other_heap.min
        self.num_nodes += other_heap.num_nodes
        self.max = self._find_max()

    def delete_max(self):
        if self.max is not None:
            max_key = self.max.key
            self.decrease_key(self.max, float('-inf'))
            self.extract_min()
            return max_key
        return None

    def _find_min(self):
        min_node = None
        if self.min is not None:
            min_node = self.min
            w = self.min.right
            while w != self.min:
                if w.key < min_node.key:
                    min_node = w
                w = w.right
        return min_node

# Converts RGB to HSV color space
def rgb_to_hsv(r, g, b):
    # Validate input values
    if not (0 <= r <= 255 and 0 <= g <= 255 and 0 <= b <= 255):
        raise ValueError("RGB values must be in the range 0-255")

    # Normalize RGB values to [0, 1]
    r, g, b = r / 255.0, g / 255.0, b / 255.0

    # Calculate max, min and difference
    max_val = max(r, g, b)
    min_val = min(r, g, b)
    diff = max_val - min_val

    # Calculate Hue (h)
    if max_val == min_val:
        h = 0
    elif max_val == r:
        h = (60 * ((g - b) / diff) + 360) % 360
    elif max_val == g:
        h = (60 * ((b - r) / diff) + 120) % 360
    elif max_val == b:
        h = (60 * ((r - g) / diff) + 240) % 360

    # Calculate Saturation (s)
    if max_val == 0:
        s = 0
    else:
        s = (diff / max_val) * 100

    # Calculate Value (v)
    v = max_val * 100

    return h, s, v


# Converts HSV to RGB color space
def hsv_to_rgb(h, s, v):
    # Validate input values
    if not (0 <= h <= 360 and 0 <= s <= 100 and 0 <= v <= 100):
        raise ValueError("HSV values must be in the range 0-360 for H and 0-100 for S and V")

    # Normalize saturation and value to [0, 1]
    s, v = s / 100.0, v / 100.0

    # Calculate intermediate values
    c = v * s
    x = c * (1 - abs((h / 60) % 2 - 1))
    m = v - c

    # Determine RGB components based on hue sector
    if 0 <= h < 60:
        r, g, b = c, x, 0
    elif 60 <= h < 120:
        r, g, b = x, c, 0
    elif 120 <= h < 180:
        r, g, b = 0, c, x
    elif 180 <= h < 240:
        r, g, b = 0, x, c
    elif 240 <= h < 300:
        r, g, b = x, 0, c
    else:
        r, g, b = c, 0, x

    # Convert back to [0, 255] range and round to integers
    r, g, b = (r + m) * 255, (g + m) * 255, (b + m) * 255
    return int(round(r)), int(round(g)), int(round(b))

# Process a single instruction to update wire values
def process_instruction(instruction, wires):
    # Split the instruction into tokens
    tokens = instruction.split()

    # Handle AND operation
    if 'AND' in tokens:
        left, _, right, _, dest = tokens
        if left.isdigit() and right in wires:
            wires[dest] = int(left) & wires[right]
        elif left in wires and right in wires:
            wires[dest] = wires[left] & wires[right]

    # Handle OR operation
    elif 'OR' in tokens:
        left, _, right, _, dest = tokens
        if left in wires and right in wires:
            wires[dest] = wires[left] | wires[right]

    # Handle left shift
    elif 'LSHIFT' in tokens:
        src, _, value, _, dest = tokens
        if src in wires:
            wires[dest] = wires[src] << int(value)

    # Handle right shift
    elif 'RSHIFT' in tokens:
        src, _, value, _, dest = tokens
        if src in wires:
            wires[dest] = wires[src] >> int(value)

    # Handle NOT operation
    elif 'NOT' in tokens:
        _, src, _, dest = tokens
        if src in wires:
            wires[dest] = ~wires[src] & 0xFFFF

    # Handle direct assignment
    else:
        src, _, dest = tokens
        if src.isdigit():
            wires[dest] = int(src)
        elif src in wires:
            wires[dest] = wires[src]

# Assemble and evaluate the entire circuit
def assemble_circuit(instructions):
    wires = {}

    # Keep processing until all instructions are completed
    while instructions:
        instruction = instructions.pop(0)

        # Try to process the instruction
        process_instruction(instruction, wires)

        # Check if any part of the instruction depends on unknown wires
        if not set(instruction.split()) & set(wires.keys()) == set(instruction.split()):
            # If dependencies aren't met, put instruction back at end
            instructions.append(instruction)

    # Return the final signal on wire 'a'
    return wires['a']

