# Podcast episode management system

class PodcastEpisode:
    def __init__(self, episode_id, title, description, duration, release_date):
        self.episode_id = episode_id
        self.title = title
        self.description = description
        self.duration = duration
        self.release_date = release_date


class Podcast:
    def __init__(self):
        self.episodes = {}
        self.next_episode_id = 1

    def add_episode(self, title, description, duration, release_date):
        # Add a new episode to the podcast
        episode_id = self.next_episode_id
        new_episode = PodcastEpisode(episode_id, title, description, duration, release_date)
        self.episodes[episode_id] = new_episode
        self.next_episode_id += 1
        return episode_id

    def update_episode(self, episode_id, title=None, description=None, duration=None, release_date=None):
        # Update an existing episode's details
        if episode_id not in self.episodes:
            raise ValueError(f"Episode with ID {episode_id} does not exist.")

        episode = self.episodes[episode_id]
        if title is not None:
            episode.title = title
        if description is not None:
            episode.description = description
        if duration is not None:
            episode.duration = duration
        if release_date is not None:
            episode.release_date = release_date

    def delete_episode(self, episode_id):
        # Remove an episode from the podcast
        if episode_id not in self.episodes:
            raise ValueError(f"Episode with ID {episode_id} does not exist.")

        del self.episodes[episode_id]

    def get_episode(self, episode_id):
        # Retrieve a specific episode by ID
        if episode_id not in self.episodes:
            raise ValueError(f"Episode with ID {episode_id} does not exist.")

        return self.episodes[episode_id]

    def list_episodes(self):
        # List all episodes in the podcast
        return list(self.episodes.values())


# Example usage
podcast = Podcast()

# Add episodes
