episode2_id = podcast.add_episode("Episode 2", "Description of Episode 2", 45, "2023-01-08")

# Update an episode
podcast.update_episode(episode1_id, title="Updated Episode 1", duration=35)

# Delete an episode
podcast.delete_episode(episode2_id)

# List all episodes
for episode in podcast.list_episodes():
    print(f"ID: {episode.episode_id}, Title: {episode.title}, Description: {episode.description}, Duration: {episode.duration}, Release Date: {episode.release_date}")

