# Import required modules
import math
from abc import ABC, abstractmethod


class Shape(ABC):
    # Abstract method for area calculation
    @abstractmethod
    def area(self):
        pass

    # Abstract method for perimeter calculation
    @abstractmethod
    def perimeter(self):
        pass

    # Compare shapes by area and perimeter
    def equals(self, other):
        if not isinstance(other, self.__class__):
            return False
        return self.area() == other.area() and self.perimeter() == other.perimeter()

    # Abstract method for distance to another shape
    @abstractmethod
    def distance_to(self, other):
        pass

    # Abstract method for rotation
    @abstractmethod
    def rotate(self, angle):
        pass

    # Abstract method for bounding rectangle
    @abstractmethod
    def bounding_rectangle(self):
        pass


class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def distance_to(self, other):
        if not isinstance(other, Point):
            raise ValueError("Other must be a Point")
        return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2)


class Rectangle(Shape):
    def __init__(self, width, height, center=Point(0, 0)):
        if width <= 0 or height <= 0:
            raise ValueError("Width and height must be positive")
        self.width = width
        self.height = height
        self.center = center

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

    def distance_to(self, other):
        if not isinstance(other, Shape):
            raise ValueError("Other must be a Shape")
        return self.center.distance_to(other.center)

    def rotate(self, angle):
        # For a rectangle, rotation does not change its area or perimeter
        pass

    def bounding_rectangle(self):
        return self


class Circle(Shape):
    def __init__(self, radius, center=Point(0, 0)):
        if radius <= 0:
            raise ValueError("Radius must be positive")
        self.radius = radius
        self.center = center

    def area(self):
        return math.pi * (self.radius ** 2)

    def perimeter(self):
        return 2 * math.pi * self.radius

    def distance_to(self, other):
        if not isinstance(other, Shape):
            raise ValueError("Other must be a Shape")
        return self.center.distance_to(other.center)

    def rotate(self, angle):
        # For a circle, rotation does not change its area or perimeter
        pass

    def bounding_rectangle(self):
        return Rectangle(2 * self.radius, 2 * self.radius, self.center)


class Triangle(Shape):
    def __init__(self, a, b, c, center=Point(0, 0)):
        if a <= 0 or b <= 0 or c <= 0 or not self.is_valid_triangle(a, b, c):
            raise ValueError("Invalid triangle dimensions")
        self.a = a
        self.b = b
        self.c = c
        self.center = center

    @staticmethod
    def is_valid_triangle(a, b, c):
        return a + b > c and a + c > b and b + c > a

    def area(self):
        s = (self.a + self.b + self.c) / 2
        return math.sqrt(s * (s - self.a) * (s - self.b) * (s - self.c))

    def perimeter(self):
        return self.a + self.b + self.c

    def distance_to(self, other):
        if not isinstance(other, Shape):
            raise ValueError("Other must be a Shape")
        return self.center.distance_to(other.center)

    def rotate(self, angle):
        # For a triangle, rotation can be complex and may require additional logic
        pass

    def bounding_rectangle(self):
        # Simplified bounding rectangle for a triangle
        max_side = max(self.a, self.b, self.c)
        return Rectangle(max_side, max_side, self.center)


# Example usage
rect1 = Rectangle(4, 5, Point(1, 1))
rect2 = Rectangle(4, 5, Point(2, 2))

print(rect1.area())  # 20
print(rect1.perimeter())  # 18
print(rect1.equals(rect2))  # True
print(rect1.distance_to(rect2))  # 1.4142135623730951

rect1.rotate(45)  # No change for rectangle
print(rect1.bounding_rectangle())  # Rectangle object

circle1 = Circle(3, Point(0, 0))
