print(circle1.area())  # 28.274333882308138
print(circle1.perimeter())  # 18.849555921538755
print(circle1.equals(circle2))  # True
print(circle1.distance_to(circle2))  # 7.0710678118654755

circle1.rotate(90)  # No change for circle
print(circle1.bounding_rectangle())  # Rectangle object

triangle1 = Triangle(3, 4, 5, Point(0, 0))
triangle2 = Triangle(3, 4, 5, Point(3, 3))

print(triangle1.area())  # 6.0
print(triangle1.perimeter())  # 12
