# Import necessary PyQt5 modules
from PyQt5.QtWidgets import QStyledItemDelegate, QStyleOptionViewItem, QApplication, QWidget, QVBoxLayout, QTableView
from PyQt5.QtGui import QPainter, QCursor, QDesktopServices
from PyQt5.QtCore import Qt, QEvent, QModelIndex, QUrl
import sys


class HyperlinkDelegate(QStyledItemDelegate):
    def __init__(self, parent=None):
        # Initialize the parent class
        super(HyperlinkDelegate, self).__init__(parent)
        # Store links dictionary
        self._links = {}

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex):
        # Check if current column is the hyperlink column (column 1)
        if index.column() == 1:
            # Get display text and link data
            text = index.data(Qt.DisplayRole)
            links = index.data(Qt.UserRole)

            if links:
                # Store links for this index
                self._links[index] = links

                # Draw background
                painter.save()
                painter.setRenderHint(QPainter.Antialiasing, True)

                # Highlight if selected
                if option.state & QStyle.State_Selected:
                    painter.fillRect(option.rect, option.palette.highlight())

                painter.restore()

                # Draw each hyperlink
                for link in links:
                    # Calculate text bounding rectangle
                    text_rect = painter.fontMetrics().boundingRect(
                        option.rect, Qt.TextWordWrap, link['text']
                    )

                    # Adjust rectangle for link position
                    link_rect = option.rect.adjusted(
                        0, 0, -option.rect.width() + text_rect.width(), 0
                    )

                    # Set pen color to blue for hyperlink
                    painter.setPen(Qt.blue)
                    painter.drawText(link_rect, Qt.TextWordWrap, link['text'])

                    # Underline the text
                    painter.setPen(Qt.blue)
                    painter.drawLine(link_rect.bottomLeft(), link_rect.bottomRight())

                painter.restore()
            else:
                # Fallback to default painting if no links
                super().paint(painter, option, index)
        else:
            # Default painting for other columns
            super().paint(painter, option, index)

    def editorEvent(self, event: QEvent, model, option: QStyleOptionViewItem, index: QModelIndex):
        # Handle mouse click events on hyperlinks
        if event.type() == QEvent.MouseButtonRelease and index.column() == 1:
            if index in self._links:
                links = self._links[index]
                for link in links:
                    # Calculate text rectangle for hit testing
                    text_rect = self.style().itemTextRect(
                        option.fontMetrics, option.rect, Qt.AlignLeft, True, link['text']
                    )

                    # Check if click is within the link area
                    if text_rect.contains(event.pos()):
                        # Open URL in default browser
                        QDesktopServices.openUrl(QUrl(link['url']))
                        return True

        # Call parent handler if not handled
        return super().editorEvent(event, model, option, index)

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex):
        # Provide appropriate size for cells with hyperlinks
        if index.column() == 1:
            links = index.data(Qt.UserRole)
            if links:
                # Calculate maximum height needed for all links
                max_height = max(
                    self.style().itemTextRect(
                        option.fontMetrics, option.rect, Qt.AlignLeft, True, link['text']
                    ).height() 
                    for link in links
                )
                return QSize(option.rect.width(), max_height)

        # Use default size hint for other cases
        return super().sizeHint(option, index)

