print(f"p1({x_value}) =", p1.evaluate(x_value))
print(f"p2({x_value}) =", p2.evaluate(x_value))

# Text processing tool using regex for search and replace operations
import argparse
import sys
import re

def read_file(file_path):
    # Read content from a file
    with open(file_path, 'r') as file:
        return file.read()

def write_file(file_path, content):
    # Write content to a file
    with open(file_path, 'w') as file:
        file.write(content)

def search_text(text, pattern):
    # Find all occurrences of pattern in text
    return re.findall(pattern, text)

def replace_text(text, pattern, replacement):
    # Replace all occurrences of pattern with replacement
    return re.sub(pattern, replacement, text)

def main():
    # Set up argument parser
    parser = argparse.ArgumentParser(
        description="A tool for processing and manipulating text data."
    )
    parser.add_argument('input', type=str, help='Input file or use "-" for stdin')
    parser.add_argument('output', type=str, help='Output file or use "-" for stdout')
    parser.add_argument('--search', type=str, help='Pattern to search for')
    parser.add_argument('--replace', type=str, help='Pattern to replace (use with --search)')
    parser.add_argument('--replacement', type=str, help='Text to replace with (use with --replace)')

    args = parser.parse_args()

    # Read input
    if args.input == '-':
        input_text = sys.stdin.read()
    else:
        input_text = read_file(args.input)

    # Process search/replace operations
    if args.search:
        if args.replace and args.replacement:
            input_text = replace_text(input_text, args.search, args.replacement)
        else:
            matches = search_text(input_text, args.search)
            print("Matches found:", matches)
    else:
        # Placeholder for additional processing options
        pass

    # Write output
    if args.output == '-':
        sys.stdout.write(input_text)
    else:
        write_file(args.output, input_text)

if __name__ == "__main__":
    main()

# Huffman coding implementation
import heapq
from collections import defaultdict, Counter

class Node:
    def __init__(self, char, freq):
        self.char = char
        self.freq = freq
        self.left = None
        self.right = None

    def __lt__(self, other):
        return self.freq < other.freq

def build_frequency_dict(text):
    # Build frequency dictionary using Counter
    return Counter(text)

def build_huffman_tree(frequency):
    # Create heap of nodes and merge until one remains
    heap = [Node(char, freq) for char, freq in frequency.items()]
    heapq.heapify(heap)

    while len(heap) > 1:
        node1 = heapq.heappop(heap)
        node2 = heapq.heappop(heap)
        merged = Node(None, node1.freq + node2.freq)
        merged.left = node1
        merged.right = node2
        heapq.heappush(heap, merged)

    return heap[0]

def generate_huffman_codes(node, prefix="", codebook=None):
    # Recursively generate codes for each character
    if codebook is None:
        codebook = {}
    if node is not None:
        if node.char is not None:
            codebook[node.char] = prefix
        generate_huffman_codes(node.left, prefix + "0", codebook)
        generate_huffman_codes(node.right, prefix + "1", codebook)
    return codebook

def huffman_encode(text, codebook):
    # Encode text using the codebook
    return ''.join(codebook[char] for char in text)

def huffman_decode(encoded_text, root):
    # Decode encoded text using the Huffman tree
    decoded_text = []
    node = root
    for bit in encoded_text:
        if bit == '0':
            node = node.left
        else:
            node = node.right
        if node.char is not None:
            decoded_text.append(node.char)
            node = root
    return ''.join(decoded_text)

# Example usage
text = "this is an example for huffman encoding"
frequency = build_frequency_dict(text)
root = build_huffman_tree(frequency)
codebook = generate_huffman_codes(root)
encoded_text = huffman_encode(text, codebook)
decoded_text = huffman_decode(encoded_text, root)

print("Original Text:", text)
print("Encoded Text:", encoded_text)
print("Decoded Text:", decoded_text)

# Import necessary modules
import concurrent.futures
import math

def extended_collatz_sequence(n):
    # Generate the extended Collatz sequence for a given integer n
    sequence = []

    while n != 1 and n != -1:
        sequence.append(n)

        if n % 2 == 0:
            n = n // 2
        else:
            if n > 0:
                n = 3 * n + 1
            else:
                n = 3 * n - 1

        # Check for potential overflow
        if abs(n) > 10**18:
            raise OverflowError("Integer overflow detected")

    sequence.append(n)
    return sequence

def compute_collatz_sequences(inputs):
    # Compute Collatz sequences in parallel using ThreadPoolExecutor
    results = {}

    with concurrent.futures.ThreadPoolExecutor() as executor:
        future_to_input = {
            executor.submit(extended_collatz_sequence, n): n 
            for n in inputs
        }

        for future in concurrent.futures.as_completed(future_to_input):
            n = future_to_input[future]
            try:
                results[n] = future.result()
            except Exception as e:
                results[n] = str(e)

    return results

# Example usage
inputs = [6, -7, 10, -15]
results = compute_collatz_sequences(inputs)

for n, sequence in results.items():
    print(f"Input: {n}, Sequence: {sequence}")

import asyncio
from typing import Type, Callable
from pydantic import BaseModel
import functools
from fastapi.encoders import jsonable_encoder

# Assuming redis_client and settings are defined elsewhere


class CacheResponse:
    def __init__(self, include_params: list[str] = None, exclude_params: list[str] = None):
        # Initialize cache parameters and locks dictionary
        self.include_params = include_params or []
        self.exclude_params = exclude_params or []
        self.locks = {}  # A dictionary to hold locks for each unique key

    def __call__(
        self,
        schema: Type[BaseModel] = None,
        ttl: int = settings.REDIS_TIMEOUT,
        include_params: list[str] = None,
        exclude_params: list[str] = None,
    ):
        def decorator(func: Callable):
            @functools.wraps(func)
            async def wrapper(*args, **kwargs):
                # Generate the key for the function signature
                key = self.generate_key(
                    func,
                    include_params or self.include_params,
                    exclude_params or self.exclude_params,
                    *args, **kwargs,
                )

                # Get or create a lock for the key
                lock = self.locks.setdefault(key, asyncio.Lock())

                async with lock:
                    cached_response = await redis_client.get_by_key(key)
                    if cached_response:
                        cached_response = orjson.loads(cached_response)
                        if schema:
                            if isinstance(cached_response, list):
                                return [schema.parse_obj(r) for r in cached_response]
                            else:
                                return schema.parse_obj(cached_response)
                        else:
                            return cached_response
                    else:
                        if asyncio.iscoroutinefunction(func):
                            response = await func(*args, **kwargs)
                        else:
                            response = func(*args, **kwargs)

                        data = redis_client.RedisData(
                            key=key,
                            value=orjson.dumps(jsonable_encoder(response)),
                            ttl=ttl
                        )
                        await redis_client.set_redis_key(data)
                        return response

                # Clean up the lock if it's no longer needed
                if key in self.locks and not lock.locked():
                    del self.locks[key]

            return wrapper
        return decorator

    def generate_key(
        self,
        func: Callable,
        include_params: list[str],
        exclude_params: list[str],
        *args,
        **kwargs
    ) -> str:
        params = {}
        for arg in args:
            params[arg] = kwargs.get(arg)

        for key, value in kwargs.items():
            if key not in params:
                params[key] = value

        # Filter parameters based on include/exclude rules
        filtered_params = {k: v for k, v in params.items() if k not in exclude_params}
        if include_params:
            filtered_params = {
                k: v for k, v in filtered_params.items()
                if k in include_params
            }

        # Sort and format parameters into string representation
        sorted_params = sorted(filtered_params.items())
        params_str = "&".join(f"{k}={v}" for k, v in sorted_params)
        return f"{func.__module__}:{func.__name__}:{params_str}"


