# Import necessary types from typing module
from typing import Tuple, Dict

def advanced_string_manipulation(string: str) -> Tuple[str, Dict[str, int]]:
    # Initialize list for transformed characters and dictionary for counting
    transformed_string = []
    char_count = {}

    # Process each character in the input string
    for char in string:
        if char.isalpha():
            # Swap case for alphabetic characters
            new_char = char.swapcase()
        elif char.isdigit():
            # Convert odd digits to next even digit (e.g., '5' becomes '6')
            new_char = str(int(char) + 1) if int(char) % 2 != 0 else char
        else:
            # Double special characters (non-alphanumeric, non-digit)
            new_char = char * 2

        # Add the transformed character(s) to the result list
        transformed_string.append(new_char)

        # Count occurrences of each character in new_char
        for c in new_char:
            if c in char_count:
                char_count[c] += 1
            else:
                char_count[c] = 1

    # Return the joined transformed string and the character count dictionary
    return ''.join(transformed_string), char_count

