# Huffman coding implementation
import heapq
from collections import defaultdict, Counter

class Node:
    def __init__(self, char, freq):
        self.char = char
        self.freq = freq
        self.left = None
        self.right = None

    # For heap comparison
    def __lt__(self, other):
        return self.freq < other.freq

def build_frequency_dict(text):
    # Count character frequencies
    return Counter(text)

def build_huffman_tree(frequency):
    # Initialize heap with leaf nodes
    heap = [Node(char, freq) for char, freq in frequency.items()]
    heapq.heapify(heap)

    # Build tree by merging two smallest nodes
    while len(heap) > 1:
        node1 = heapq.heappop(heap)
        node2 = heapq.heappop(heap)
        merged = Node(None, node1.freq + node2.freq)
        merged.left = node1
        merged.right = node2
        heapq.heappush(heap, merged)

    return heap[0]  # Return root node

def build_huffman_codes(node, prefix="", codebook=None):
    if codebook is None:
        codebook = {}

    if node is not None:
        # Leaf node: store code
        if node.char is not None:
            codebook[node.char] = prefix

        # Recurse on children
        build_huffman_codes(node.left, prefix + "0", codebook)
        build_huffman_codes(node.right, prefix + "1", codebook)

    return codebook

def huffman_encode(text, codebook):
    # Encode text using Huffman codes
    return ''.join(codebook[char] for char in text)

def huffman_decode(encoded_text, root):
    decoded_text = []
    node = root

    # Traverse tree according to bits
    for bit in encoded_text:
        if bit == '0':
            node = node.left
        else:
            node = node.right

        # When reaching a leaf, add character and reset
        if node.char is not None:
            decoded_text.append(node.char)
            node = root

    return ''.join(decoded_text)

# Example usage:
text = "this is an example for huffman encoding"
frequency = build_frequency_dict(text)
huffman_tree = build_huffman_tree(frequency)
codebook = build_huffman_codes(huffman_tree)
encoded_text = huffman_encode(text, codebook)
decoded_text = huffman_decode(encoded_text, huffman_tree)

print("Original text:", text)
print("Encoded text:", encoded_text)
print("Decoded text:", decoded_text)

