# Function to count vowels in a sentence
def count_vowels(sentence):
    vowels = "aeiouAEIOU"
    return sum(1 for char in sentence if char in vowels)

# Function to process multiple sentences
def process_sentences(sentences):
    # Handle empty input
    if not sentences:
        return {
            "total_vowel_counts": [],
            "sentence_with_most_vowels": None,
            "error": "No sentences provided"
        }

    max_vowel_count = 0
    sentence_with_most_vowels = None
    total_vowel_counts = []

    # Process each sentence
    for sentence in sentences:
        # Check sentence length limit
        if len(sentence) > 200:
            return {
                "total_vowel_counts": [],
                "sentence_with_most_vowels": None,
                "error": f"Error: Sentence exceeds 200 characters: '{sentence[:50]}...'"
            }

        # Count vowels in current sentence
        vowel_count = count_vowels(sentence)
        total_vowel_counts.append(vowel_count)

        # Update maximum if needed
        if vowel_count > max_vowel_count:
            max_vowel_count = vowel_count
            sentence_with_most_vowels = sentence

    # Return results
    return {
        "total_vowel_counts": total_vowel_counts,
        "sentence_with_most_vowels": sentence_with_most_vowels,
        "error": None
    }

