# Function to check if a dictionary (and its nested structures) are empty
def is_empty_dict(d, visited=None):
    # Initialize visited set to track already processed objects
    if visited is None:
        visited = set()

    # Avoid infinite recursion by checking for cycles
    if id(d) in visited:
        return True, 0  # Already visited, skip counting

    visited.add(id(d))

    # Check if the object is not a container type
    if not isinstance(d, (dict, list, tuple, set)):
        return False, 0  # Not an iterable container

    # Check if it's an empty dictionary
    if isinstance(d, dict) and not d:
        return True, 1  # Empty dictionary found

    empty = True
    empty_count = 0

    # Process dictionary values
    if isinstance(d, dict):
        for value in d.values():
            is_empty, count = is_empty_dict(value, visited)
            empty_count += count
            if not is_empty:
                empty = False
    # Process list, tuple, or set items
    elif isinstance(d, (list, tuple, set)):
        for item in d:
            is_empty, count = is_empty_dict(item, visited)
            empty_count += count
            if not is_empty:
                empty = False

    return empty, empty_count


