    player1_name = input("Enter Player 1's name: ")
    player2_name = input("Enter Player 2's name: ")

    # Initialize tries counters
    player1_tries = 0
    player2_tries = 0

    # Main game loop
    while player1_tries < max_tries and player2_tries < max_tries:
        # Player 1's turn
        if player1_tries < max_tries:
            guess = get_player_guess(player1_name, min_num, max_num)
            player1_tries += 1
            if guess == random_number:
                print(f"{player1_name} wins! The number was {random_number}.")
                return
            else:
                print(f"Wrong guess, {player1_name}. Tries left: {max_tries - player1_tries}")

        # Player 2's turn
        if player2_tries < max_tries:
            guess = get_player_guess(player2_name, min_num, max_num)
            player2_tries += 1
            if guess == random_number:
                print(f"{player2_name} wins! The number was {random_number}.")
                return
            else:
                print(f"Wrong guess, {player2_name}. Tries left: {max_tries - player2_tries}")

    # Handle case when both players run out of tries
    print(f"Both players have run out of tries. The number was {random_number}.")

if __name__ == "__main__":
    play_game()

# Import required modules for abstract base class
from abc import ABC, abstractmethod


class Shape(ABC):
    def __init__(self, length, width, name):
        self.length = length
        self.width = width
        self._name = name

    @abstractmethod
    def calculateArea(self) -> float:
        pass

    def printArea(self):
        area = self.calculateArea()
        print(f"The area of the {self._name} is {area:.2f}")

    def getPerimeter(self) -> float:
        return 2 * (self.length + self.width)

    @staticmethod
    def compareAreas(shape1, shape2) -> float:
        return abs(shape1.calculateArea() - shape2.calculateArea())

    def printName(self):
        print(f"The shape is a {self._name}")


# Subclasses of Shape
class Rectangle(Shape):
    def __init__(self, length, width):
        super().__init__(length, width, "Rectangle")

    def calculateArea(self) -> float:
        return self.length * self.width


class Circle(Shape):
    def __init__(self, radius):
        super().__init__(radius, 0, "Circle")  # Width is not used for Circle
        self.radius = radius

    def calculateArea(self) -> float:
        return 3.14159 * self.radius * self.radius

    def getPerimeter(self) -> float:
        return 2 * 3.14159 * self.radius


class Triangle(Shape):
    def __init__(self, base, height):
        super().__init__(base, height, "Triangle")

    def calculateArea(self) -> float:
        return 0.5 * self.length * self.width


# Example usage
if __name__ == "__main__":
    rect = Rectangle(4, 5)
    rect.printName()
    rect.printArea()
    print(f"The perimeter of the {rect._name} is {rect.getPerimeter():.2f}")

    circle = Circle(3)
    circle.printName()
    circle.printArea()
    print(f"The perimeter of the {circle._name} is {circle.getPerimeter():.2f}")

    triangle = Triangle(3, 4)
    triangle.printName()
    triangle.printArea()
    print(f"The perimeter of the {triangle._name} is {triangle.getPerimeter():.2f}")

    area_diff = Shape.compareAreas(rect, circle)
    print(f"The difference in area between the {rect._name} and the {circle._name} is {area_diff:.2f}")

# Phone Directory Management System

class PhoneDirectory:
    def __init__(self):
        self.directory = {}

    def add_entry(self, name, phone_number, country, state, city):
        # Add a new entry to the directory
        if country not in self.directory:
            self.directory[country] = {}
        if state not in self.directory[country]:
            self.directory[country][state] = {}
        if city not in self.directory[country][state]:
            self.directory[country][state][city] = []

        self.directory[country][state][city].append({
            'name': name,
            'phone_number': phone_number
        })

    def remove_entry(self, name, phone_number, country, state, city):
        # Remove an existing entry from the directory
        if country in self.directory and state in self.directory[country] and city in self.directory[country][state]:
            entries = self.directory[country][state][city]
            for entry in entries:
                if entry['name'] == name and entry['phone_number'] == phone_number:
                    entries.remove(entry)
                    return True
        return False

    def search_entry(self, name=None, phone_number=None, country=None, state=None, city=None):
        # Search for entries matching given criteria
        results = []

        def search_recursive(current_dict, path):
            if not isinstance(current_dict, dict):
                return

            for key, value in current_dict.items():
                new_path = path + [key]
                if len(new_path) == 3:  # Country, State, City
                    for entry in value:
                        if (name is None or entry['name'] == name) and \
                           (phone_number is None or entry['phone_number'] == phone_number):
                            results.append({
                                'name': entry['name'],
                                'phone_number': entry['phone_number'],
                                'country': new_path[0],
                                'state': new_path[1],
                                'city': new_path[2]
                            })
                else:
                    search_recursive(value, new_path)

        search_recursive(self.directory, [])
        return results

    def display_directory(self):
        # Display the entire directory structure
        def display_recursive(current_dict, indent=0):
            if not isinstance(current_dict, dict):
                return

            for key, value in current_dict.items():
                print(' ' * indent + key)
                if isinstance(value, list):
                    for entry in value:
                        print(' ' * (indent + 4) + f"{entry['name']}: {entry['phone_number']}")
                else:
                    display_recursive(value, indent + 4)

        display_recursive(self.directory)


