# Lichess bot script for managing challenges and playing games
import requests
import time
import logging

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Define API endpoints
BASE_URL = "https://lichess.org/api"
CHALLENGE_URL = f"{BASE_URL}/challenge"
ACCEPT_URL = f"{BASE_URL}/challenge/{challenge_id}/accept"
DECLINE_URL = f"{BASE_URL}/challenge/{challenge_id}/decline"
BOT_PLAY_URL = f"{BASE_URL}/bot/game/stream/{game_id}"
MOVE_URL = f"{BASE_URL}/bot/game/{game_id}/move"

# Bot authentication token (replace with actual token)
BOT_TOKEN = "your_bot_token_here"

# Set up request headers
headers = {
    "Authorization": f"Bearer {BOT_TOKEN}"
}

def create_challenge(username, time_limit):
    """
    Create a challenge for a specific opponent with given time control.
    """
    # Validate time limit range
    if not 1 <= time_limit <= 30:
        raise ValueError("Time limit must be between 1 and 30 minutes.")

    # Prepare challenge data
    data = {
        "rated": True,
        "clock.limit": time_limit * 60,
        "clock.increment": 0,
        "color": "random",
        "variant": "standard"
    }

    # Send challenge request
    response = requests.post(CHALLENGE_URL, headers=headers, data=data)

    if response.status_code == 200:
        challenge = response.json()
        logging.info(f"Challenge created: {challenge['challenge']['id']}")
        return challenge['challenge']['id']
    else:
        logging.error(f"Failed to create challenge: {response.status_code} - {response.text}")
        return None

def accept_challenge(challenge_id):
    """
    Accept an incoming challenge using its ID.
    """
    response = requests.post(
        ACCEPT_URL.format(challenge_id=challenge_id),
        headers=headers
    )

    if response.status_code == 200:
        game = response.json()
        logging.info(f"Challenge accepted: {game['challenge']['id']}")
        return game['game']['id']
    else:
        logging.error(f"Failed to accept challenge: {response.status_code} - {response.text}")
        return None

def decline_challenge(challenge_id):
    """
    Decline an incoming challenge by its ID.
    """
    response = requests.post(
        DECLINE_URL.format(challenge_id=challenge_id),
        headers=headers
    )

    if response.status_code == 200:
        logging.info(f"Challenge declined: {challenge_id}")
    else:
        logging.error(f"Failed to decline challenge: {response.status_code} - {response.text}")

def adjust_bot_strength(time_limit):
    """
    Determine bot strength setting based on time control.
    """
    if time_limit <= 5:
        return "ultraBullet"
    elif time_limit <= 10:
        return "bullet"
    elif time_limit <= 15:
        return "blitz"
    else:
        return "rapid"

def make_move(game_id, move):
    """
    Submit a move in the active game.
    """
    response = requests.post(
        MOVE_URL.format(game_id=game_id),
        headers=headers,
        data={"move": move}
    )

    if response.status_code == 200:
        logging.info(f"Move made: {move}")
    else:
        logging.error(f"Failed to make move: {response.status_code} - {response.text}")

def handle_game(game_id):
    """
    Monitor game stream and respond to events by making moves.
    """
    while True:
        try:
            # Connect to game stream
            response = requests.get(
                BOT_PLAY_URL.format(game_id=game_id),
                headers=headers,
                stream=True
            )

            if response.status_code == 200:
                for line in response.iter_lines():
                    if line:
                        event = line.decode('utf-8')

                        # Handle initial game setup
                        if "gameFull" in event:
                            game_data = event
                            make_move(game_id, "e2e4")

                        # Handle state updates
                        elif "state" in event:
                            state = event
                            make_move(game_id, "e2e4")
            else:
                logging.error(f"Failed to get game stream: {response.status_code} - {response.text}")
                break

        except requests.exceptions.RequestException as e:
            logging.error(f"Network error: {e}")
            time.sleep(5)  # Wait before retrying

def main():
    # Get user input for challenge parameters
    username = input("Enter the username to challenge: ")
    time_limit = int(input("Enter the time limit (1-30 minutes): "))

    # Create and accept challenge
    challenge_id = create_challenge(username, time_limit)
    if challenge_id:
        game_id = accept_challenge(challenge_id)
        if game_id:
            handle_game(game_id)

if __name__ == "__main__":
    main()

# User data management system with indexing by city and favorite books

class User:
    def __init__(self, name, age, city, occupation, favorite_books):
        self.name = name
        self.age = age
        self.city = city
        self.occupation = occupation
        # Using a set to avoid duplicate favorite books
        self.favorite_books = set(favorite_books)

    def __repr__(self):
        return (f"User(name={self.name}, age={self.age}, city={self.city}, "
                f"occupation={self.occupation}, favorite_books={self.favorite_books})")


class UserDataStore:
    def __init__(self):
        # Main storage for user data
        self.users = {}
        # Index for searching by city
        self.city_index = {}
        # Index for searching by books
        self.book_index = {}

    def add_user(self, user):
        if user.name in self.users:
            raise ValueError(f"User with name {user.name} already exists.")

        self.users[user.name] = user
        self._update_city_index(user, 'add')
        self._update_book_index(user, 'add')

    def update_user(self, user):
        if user.name not in self.users:
            raise ValueError(f"User with name {user.name} does not exist.")

        old_user = self.users[user.name]
        self.users[user.name] = user
        self._update_city_index(old_user, 'remove')
        self._update_book_index(old_user, 'remove')
        self._update_city_index(user, 'add')
        self._update_book_index(user, 'add')

    def delete_user(self, name):
        if name not in self.users:
            raise ValueError(f"User with name {name} does not exist.")

        user = self.users.pop(name)
        self._update_city_index(user, 'remove')
        self._update_book_index(user, 'remove')

    def search_users_by_city(self, city):
        return [self.users[name] for name in self.city_index.get(city, set())]

    def search_users_by_book(self, book):
        return [self.users[name] for name in self.book_index.get(book, set())]

    def _update_city_index(self, user, action):
        if action == 'add':
            if user.city not in self.city_index:
                self.city_index[user.city] = set()
            self.city_index[user.city].add(user.name)
        elif action == 'remove':
            if user.city in self.city_index:
                self.city_index[user.city].discard(user.name)
                if not self.city_index[user.city]:
                    del self.city_index[user.city]

    def _update_book_index(self, user, action):
        for book in user.favorite_books:
            if action == 'add':
                if book not in self.book_index:
                    self.book_index[book] = set()
                self.book_index[book].add(user.name)
            elif action == 'remove':
                if book in self.book_index:
                    self.book_index[book].discard(user.name)
                    if not self.book_index[book]:
                        del self.book_index[book]


# Example usage:
