# Import time module for performance measurement
import time

def factorial(n, indent=""):
    # Base case: if n is 0 or 1, return 1
    if n == 0 or n == 1:
        print(f"{indent}factorial({n}) = 1 (Base case)")
        return 1

    # Recursive case: n * factorial(n-1)
    else:
        print(f"{indent}factorial({n}) = {n} * factorial({n-1})")
        result = n * factorial(n-1, indent + "  ")
        print(f"{indent}factorial({n}) returns {result}")
        return result

def time_complexity_analysis(n):
    start_time = time.time()
    result = factorial(n)
    end_time = time.time()
    elapsed_time = end_time - start_time

    print(f"\nFactorial of {n} is {result}")
    print(f"Time taken: {elapsed_time:.6f} seconds")
    print(f"Time complexity: O(n) (where n is the input number)")

def main():
    try:
        n = int(input("Enter a non-negative integer: "))

        if n < 0:
            print("Factorial is not defined for negative numbers.")
        else:
            time_complexity_analysis(n)

    except ValueError:
        print("Please enter a valid non-negative integer.")

if __name__ == "__main__":
    main()

# Binary Search Tree implementation with various operations

from typing import List, Optional


class TreeNode:
    def __init__(self, value: int):
        self.value = value
        self.left: Optional[TreeNode] = None
        self.right: Optional[TreeNode] = None


class BinarySearchTree:
    def __init__(self):
        self.root: Optional[TreeNode] = None

    def add_node(self, value: int) -> None:
        # Add a node with given value to the BST
        if self.root is None:
            self.root = TreeNode(value)
        else:
            self._add_node(self.root, value)

    def _add_node(self, node: TreeNode, value: int) -> None:
        # Helper method to recursively add a node
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._add_node(node.left, value)
        else:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._add_node(node.right, value)

    def remove_node(self, value: int) -> bool:
        # Remove a node with given value from the BST
        self.root, removed = self._remove_node(self.root, value)
        return removed

    def _remove_node(self, node: Optional[TreeNode], value: int) -> (Optional[TreeNode], bool):
        # Helper method to recursively remove a node
        if node is None:
            return None, False

        if value < node.value:
            node.left, removed = self._remove_node(node.left, value)
        elif value > node.value:
            node.right, removed = self._remove_node(node.right, value)
        else:
            # Node found - handle deletion cases
            if node.left is None and node.right is None:
                return None, True
            elif node.left is None:
                return node.right, True
            elif node.right is None:
                return node.left, True
            else:
                # Two children: replace with in-order successor (minimum in right subtree)
                min_larger_node = self._get_min(node.right)
                node.value = min_larger_node.value
                node.right, _ = self._remove_node(node.right, min_larger_node.value)
                removed = True

        return node, removed

    def _get_min(self, node: TreeNode) -> TreeNode:
        # Find the minimum value node in a subtree
        while node.left is not None:
            node = node.left
        return node

    def search(self, value: int) -> bool:
        # Search for a value in the BST
        return self._search(self.root, value)

    def _search(self, node: Optional[TreeNode], value: int) -> bool:
        # Helper method to recursively search for a value
        if node is None:
            return False

        if value < node.value:
            return self._search(node.left, value)
        elif value > node.value:
            return self._search(node.right, value)
        else:
            return True

    def get_in_order_traversal(self) -> List[int]:
        # Returns values in ascending order (left-root-right)
        return self._get_in_order_traversal(self.root, [])

    def _get_in_order_traversal(self, node: Optional[TreeNode], values: List[int]) -> List[int]:
        # Helper method for in-order traversal
        if node is not None:
            self._get_in_order_traversal(node.left, values)
            values.append(node.value)
            self._get_in_order_traversal(node.right, values)
        return values

    def get_pre_order_traversal(self) -> List[int]:
        # Returns values in pre-order (root-left-right)
        return self._get_pre_order_traversal(self.root, [])

    def _get_pre_order_traversal(self, node: Optional[TreeNode], values: List[int]) -> List[int]:
        # Helper method for pre-order traversal
        if node is not None:
            values.append(node.value)
            self._get_pre_order_traversal(node.left, values)
            self._get_pre_order_traversal(node.right, values)
        return values

    def get_post_order_traversal(self) -> List[int]:
        # Returns values in post-order (left-right-root)
        return self._get_post_order_traversal(self.root, [])

    def _get_post_order_traversal(self, node: Optional[TreeNode], values: List[int]) -> List[int]:
        # Helper method for post-order traversal
        if node is not None:
            self._get_post_order_traversal(node.left, values)
            self._get_post_order_traversal(node.right, values)
            values.append(node.value)
        return values

    def get_level_order_traversal(self) -> List[int]:
        # Returns values in level-order (breadth-first)
        if not self.root:
            return []

        result = []
        queue = [self.root]

        while queue:
            current = queue.pop(0)
            result.append(current.value)

            if current.left:
                queue.append(current.left)
            if current.right:
                queue.append(current.right)

        return result

# Rectangle class definition
class Rectangle:
    def __init__(self, length, width):
        self.set_length(length)
        self.set_width(width)

    def set_length(self, length):
        # Validate length parameter
        if not isinstance(length, (int, float)) or length <= 0:
            raise ValueError("Length must be a positive non-zero number.")
        self._length = length

    def get_length(self):
        return self._length

    def set_width(self, width):
        # Validate width parameter
        if not isinstance(width, (int, float)) or width <= 0:
            raise ValueError("Width must be a positive non-zero number.")
        self._width = width

    def get_width(self):
        return self._width

    def area(self):
        try:
            return self._length * self._width
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the area.") from e

    def perimeter(self):
        try:
            return 2 * (self._length + self._width)
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the perimeter.") from e

    def is_same_area(self, other):
        # Validate other parameter type
        if not isinstance(other, Rectangle):
            raise TypeError("The 'other' parameter must be an instance of Rectangle.")
        return self.area() == other.area()


