# Database setup
DATABASE_URL = 'sqlite:///weather.db'
engine = create_engine(DATABASE_URL)
Base = declarative_base()

class WeatherData(Base):
    __tablename__ = 'weather_data'
    id = Column(Integer, primary_key=True)
    city = Column(String, nullable=False)
    timestamp = Column(DateTime, nullable=False)
    temperature = Column(Float, nullable=False)
    rainfall = Column(Float, nullable=False)

# Create database tables
Base.metadata.create_all(engine)
Session = sessionmaker(bind=engine)

class WeatherAPI:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = 'http://api.openweathermap.org/data/2.5/'

    def get_current_weather(self, city):
        url = f"{self.base_url}weather?q={city}&appid={self.api_key}&units=metric"
        response = requests.get(url)
        if response.status_code == 200:
            data = response.json()
            return {
                'temperature': data['main']['temp'],
                'rainfall': data.get('rain', {}).get('1h', 0.0)
            }
        elif response.status_code == 404:
            raise ValueError("City not found")
        else:
            raise Exception(f"API request failed with status code {response.status_code}")

    def get_historical_weather(self, city, start_date, end_date):
        # Note: This implementation assumes city is a dict with lat/lon
        url = f"{self.base_url}onecall/timemachine?lat={city['lat']}&lon={city['lon']}&dt={start_date}&appid={self.api_key}&units=metric"
        response = requests.get(url)
        if response.status_code == 200:
            data = response.json()
            return data['hourly']
        else:
            raise Exception(f"API request failed with status code {response.status_code}")

    def analyze_historical_weather(self, city, days=30):
        current_weather = self.get_current_weather(city)
        session = Session()
        try:
            # Check if data is already in the cache
            cached_data = session.query(WeatherData).filter_by(city=city).all()
            if cached_data:
                return self._calculate_averages(cached_data)
            else:
                # Fetch historical data
                end_date = int(datetime.now().timestamp())
                start_date = int((datetime.now() - timedelta(days=days)).timestamp())
                historical_data = self.get_historical_weather(city, start_date, end_date)

                # Store each entry in the database
                for entry in historical_data:
                    session.add(WeatherData(
                        city=city,
                        timestamp=datetime.fromtimestamp(entry['dt']),
                        temperature=entry['temp'],
                        rainfall=entry.get('rain', {}).get('1h', 0.0)
                    ))
                session.commit()
                return self._calculate_averages(historical_data)
        except Exception as e:
            session.rollback()
            raise e
        finally:
            session.close()

    def _calculate_averages(self, data):
        total_temperature = 0.0
        total_rainfall = 0.0
        for entry in data:
            total_temperature += entry.temperature
            total_rainfall += entry.rainfall

        average_temperature = total_temperature / len(data)
        average_rainfall = total_rainfall / len(data)

        return {
            'average_temperature': average_temperature,
            'average_rainfall': average_rainfall
        }

weather_api = WeatherAPI(API_KEY)

@app.route('/weather', methods=['GET'])
def get_weather():
    city = request.args.get('city')
    if not city:
        return jsonify({"error": "City parameter is required"}), 400

    try:
        current_weather = weather_api.get_current_weather(city)
        historical_weather = weather_api.analyze_historical_weather(city)
        return jsonify({
            'current_weather': current_weather,
            'historical_weather': historical_weather
        })
    except ValueError as ve:
        return jsonify({"error": str(ve)}), 404
    except Exception as e:
        return jsonify({"error": str(e)}), 500

