# Function to recommend a dish based on available ingredients
def recommend_dish(available_ingredients, dishes):
    # Convert the available ingredients to a dictionary for easier manipulation
    available_dict = {item[0]: item[1] for item in available_ingredients}

    # Initialize variables to store the best dish and its remaining ingredients
    best_dish = None
    remaining_ingredients = {}

    # Iterate through each dish to check if it can be made
    for dish_name, required_ingredients in dishes.items():
        can_make = True
        temp_remaining = available_dict.copy()

        # Check if all required ingredients are available in sufficient quantity
        for ingredient, quantity in required_ingredients.items():
            if ingredient not in temp_remaining or temp_remaining[ingredient] < quantity:
                can_make = False
                break
            else:
                temp_remaining[ingredient] -= quantity

        # If dish can be made, select it and compute remaining ingredients
        if can_make:
            best_dish = dish_name
            remaining_ingredients = {k: v for k, v in temp_remaining.items() if v > 0}
            break

    return best_dish, remaining_ingredients

