# Function to dynamically populate a complex data structure
def populate_data_structure(data):
    # Initialize the complex data structure
    complex_data_structure = {
        "users": {},
        "posts": {},
        "comments": {}
    }

    # Process each document
    for document in data:
        if document['type'] == 'user':
            user_id = document['user_id']
            complex_data_structure['users'][user_id] = {
                "name": document['name'],
                "email": document['email'],
                "created_at": document['created_at']
            }

        elif document['type'] == 'post':
            post_id = document['post_id']
            user_id = document['user_id']

            # Add post information
            complex_data_structure['posts'][post_id] = {
                "user_id": user_id,
                "title": document['title'],
                "content": document['content'],
                "created_at": document['created_at']
            }

            # Ensure user exists for this post
            if user_id not in complex_data_structure['users']:
                complex_data_structure['users'][user_id] = {
                    "name": document['user_name'],
                    "email": document['user_email'],
                    "created_at": document['user_created_at']
                }

        elif document['type'] == 'comment':
            comment_id = document['comment_id']
            post_id = document['post_id']
            user_id = document['user_id']

            # Add comment information
            complex_data_structure['comments'][comment_id] = {
                "post_id": post_id,
                "user_id": user_id,
                "content": document['content'],
                "created_at": document['created_at']
            }

            # Ensure post exists for this comment
