# Diary class to manage personal entries
class Diary:
    def __init__(self):
        # Initialize with an empty list of entries
        self.entries = []

    def add_entry(self, date, title, text, mood, weather, location):
        # Check for duplicate entries by date and title
        for entry in self.entries:
            if entry['date'] == date and entry['title'] == title:
                raise ValueError("An entry with the same date and title already exists.")

        # Add new entry to the diary
        self.entries.append({
            'date': date,
            'title': title,
            'text': text,
            'mood': mood,
            'weather': weather,
            'location': location
        })

    def delete_entry(self, date, title):
        # Remove entries matching the given date and title
        self.entries = [entry for entry in self.entries 
                        if not (entry['date'] == date and entry['title'] == title)]

    def edit_entry(self, date, title, new_text=None, new_mood=None, new_weather=None, new_location=None):
        # Find and update the specified entry
        for entry in self.entries:
            if entry['date'] == date and entry['title'] == title:
                if new_text is not None:
                    entry['text'] = new_text
                if new_mood is not None:
                    entry['mood'] = new_mood
                if new_weather is not None:
                    entry['weather'] = new_weather
                if new_location is not None:
                    entry['location'] = new_location
                break

    def retrieve_entries(self, start_date, end_date):
        # Return entries within the specified date range (inclusive)
        return [entry for entry in self.entries 
                if start_date <= entry['date'] <= end_date]

