# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def getTargetCopy(self, original: TreeNode, cloned: TreeNode, target: TreeNode) -> TreeNode:
    # Depth-first search helper function
    def dfs(original_node, cloned_node):
        # Base case: if original_node is None, return None
        if original_node is None:
            return None

        # If we found the target node in original, return corresponding cloned node
        if original_node == target:
            return cloned_node

        # Search in left subtree
        left_result = dfs(original_node.left, cloned_node.left)
        if left_result:
            return left_result

        # If not found in left subtree, search in right subtree
        return dfs(original_node.right, cloned_node.right)

    # Start DFS from root nodes
    return dfs(original, cloned)

