import threading
from collections.abc import Mapping, Iterable

# Placeholder for complex data types
class ComplexDataType:
    pass

def is_complex(value):
    # Check if value is a complex type
    return isinstance(value, (type, types.ModuleType, types.FunctionType, threading.Thread, ComplexDataType))

def count_keys_and_voids(d, seen=None):
    # Initialize seen set if not provided
    if seen is None:
        seen = set()

    # Handle circular references
    if id(d) in seen:
        return (True, 0, 0, 0)  # (is_all_void, void_dicts, total_keys, complex_types)

    seen.add(id(d))

    # Initialize counters
    is_all_void = True
    void_dicts = 0
    total_keys = 0
    complex_types = 0

    # Process mapping types (dict-like)
    if isinstance(d, Mapping):
        if len(d) == 0:
            void_dicts += 1
        else:
            is_all_void = False
            for key, value in d.items():
                total_keys += 1
                if is_complex(value):
                    complex_types += 1
                else:
                    sub_result = count_keys_and_voids(value, seen)
                    is_all_void &= sub_result[0]
                    void_dicts += sub_result[1]
                    total_keys += sub_result[2]
                    complex_types += sub_result[3]
    # Process other iterables (lists, tuples, etc.)
    elif isinstance(d, Iterable) and not isinstance(d, (str, bytes)):
        for item in d:
            sub_result = count_keys_and_voids(item, seen)
            is_all_void &= sub_result[0]
            void_dicts += sub_result[1]
            total_keys += sub_result[2]
            complex_types += sub_result[3]

    return (is_all_void, void_dicts, total_keys, complex_types)

def authenticate_dictionary_state(d):
    try:
        result = count_keys_and_voids(d)
        return (result[0], result[1], result[2], result[3])
    except Exception as e:
        return f"Error: {str(e)}"

