import math

def add(a, b):
    """Add two numbers."""
    return a + b

def subtract(a, b):
    """Subtract b from a."""
    return a - b

def multiply(a, b):
    """Multiply two numbers."""
    return a * b

def divide(a, b):
    """Divide a by b. Returns a tuple (result, error) where error is None if no error occurs."""
    if b == 0:
        return None, "Division by zero is not allowed."
    return a / b, None

def exponentiate(base, exponent):
    """Raise base to the power of exponent."""
    return base ** exponent

def modulo(a, b):
    """Compute a modulo b. Returns a tuple (result, error) where error is None if no error occurs."""
    if b == 0:
        return None, "Modulo by zero is not allowed."
    return a % b, None

def nth_root(number, n):
    """Compute the nth root of a number."""
    if number < 0 and n % 2 == 0:
        return None, "Cannot compute even root of a negative number."
    return number ** (1/n), None

def print_result(operation, a, b, result, error=None):
    """Print the result of an operation."""
    if error:
        print(f"Error: {error}")
    else:
        print(f"Result of {a} {operation} {b} = {result}")

def main():
    # Dictionary mapping operation names to functions
    operations = {
        "add": add,
        "subtract": subtract,
        "multiply": multiply,
        "divide": divide,
        "exponentiate": exponentiate,
        "modulo": modulo,
        "nth_root": nth_root
    }

    while True:
        # Display menu
        print("\nAvailable operations:")
        print("1. Add")
        print("2. Subtract")
        print("3. Multiply")
        print("4. Divide")
