# Function to validate shoe data
def validate_shoe(shoe):
    if not isinstance(shoe, dict):
        return False

    required_keys = ["name", "color", "size", "brand", "reviews"]
    if not all(key in shoe for key in required_keys):
        return False

    # Validate name
    if not isinstance(shoe["name"], str) or len(shoe["name"]) > 50:
        return False

    # Validate color
    if not isinstance(shoe["color"], str) or len(shoe["color"]) > 20:
        return False

    # Validate size
    if not isinstance(shoe["size"], (int, float)) or not (5 <= shoe["size"] <= 15):
        return False

    # Validate brand
    if not isinstance(shoe["brand"], str) or len(shoe["brand"]) > 30:
        return False

    # Validate reviews list
    if not isinstance(shoe["reviews"], list) or len(shoe["reviews"]) < 3:
        return False

    # Validate each review
    for review in shoe["reviews"]:
        if not isinstance(review, dict):
            return False

        review_keys = ["rating", "comment", "date"]
        if not all(key in review for key in review_keys):
            return False

        # Validate rating
        if not isinstance(review["rating"], (int, float)) or not (1 <= review["rating"] <= 5):
            return False

        # Validate comment
        if not isinstance(review["comment"], str) or len(review["comment"]) > 100:
            return False

        # Validate date
        if not isinstance(review["date"], str) or not is_valid_date(review["date"]):
            return False

    return True

# Function to calculate average rating
def calculate_average_rating(shoes):
    total_ratings = 0
    total_reviews = 0

    for shoe in shoes:
        for review in shoe["reviews"]:
            total_ratings += review["rating"]
            total_reviews += 1

    return total_ratings / total_reviews if total_reviews > 0 else 0

