# Employee Management System

class Employee:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def __repr__(self):
        return f"{self.name} (Age: {self.age})"


class EmployeeManager:
    def __init__(self):
        self.employees = []

    def add_employee(self, name, age):
        # Validate input
        if not name or not age:
            raise ValueError("Name and age are required.")
        if not isinstance(age, int) or age <= 0:
            raise ValueError("Age must be a positive integer.")

        # Add new employee
        self.employees.append(Employee(name, age))
        print(f"Employee {name} added successfully.")

    def remove_employee(self, name):
        # Search for employee by name
        for employee in self.employees:
            if employee.name == name:
                self.employees.remove(employee)
                print(f"Employee {name} removed successfully.")
                return

        # If not found
        raise ValueError(f"Employee {name} not found.")

    def update_age(self, name, new_age):
        # Validate new age
        if not new_age or not isinstance(new_age, int) or new_age <= 0:
            raise ValueError("New age must be a positive integer.")

        # Update employee's age
        for employee in self.employees:
            if employee.name == name:
                employee.age = new_age
                print(f"Employee {name}'s age updated to {new_age}.")
                return

        # If not found
        raise ValueError(f"Employee {name} not found.")

    def list_employees(self):
        # Check if no employees exist
        if not self.employees:
            print("No employees in the list.")
            return

        # Sort and display employees
        sorted_employees = sorted(self.employees, key=lambda x: x.name)
        for employee in sorted_employees:
            print(employee)

    def average_age(self):
        # Handle empty list case
        if not self.employees:
            print("No employees in the list.")
            return 0

        # Calculate average age
        total_age = sum(employee.age for employee in self.employees)
        return total_age / len(self.employees)


def main():
    manager = EmployeeManager()

    while True:
        print("\nEmployee Management System")
        print("1. Add Employee")
        print("2. Remove Employee")
        print("3. Update Employee Age")
        print("4. List Employees")
        print("5. Average Age of Employees")
        print("6. Exit")

        choice = input("Enter your choice: ")

        try:
            choice = int(choice)

            if choice == 1:
                name = input("Enter employee name: ")
                age = int(input("Enter employee age: "))
                manager.add_employee(name, age)

            elif choice == 2:
                name = input("Enter employee name to remove: ")
                manager.remove_employee(name)

            elif choice == 3:
                name = input("Enter employee name to update age: ")
                new_age = int(input("Enter new age: "))
                manager.update_age(name, new_age)

            elif choice == 4:
                manager.list_employees()

            elif choice == 5:
                avg_age = manager.average_age()
                print(f"Average age of employees: {avg_age:.2f}")

            elif choice == 6:
                print("Exiting the program.")
                break

            else:
                print("Invalid choice. Please try again.")

        except ValueError as e:
            print(f"Error: {e}")


if __name__ == "__main__":
    main()

# MahJonggHand class for checking hand patterns
class MahJonggHand:
    def __init__(self, tiles):
        self.tiles = tiles
        # Standard pattern counts
        self.standard_patterns = {'pungs': 0, 'kongs': 0, 'chows': 0, 'pairs': 0}

        # Special hands dictionary mapping names to methods
        self.special_hands = {
            'Thirteen Orphans': self.is_thirteen_orphans,
            'Seven Pairs': self.is_seven_pairs,
            'All Pungs': self.is_all_pungs,
            'All Chows': self.is_all_chows,
            'Mixed Shifted Chows': self.is_mixed_shifted_chows,
            'All Terminals and Honors': self.is_all_terminals_and_honors,
            'All Simples': self.is_all_simples,
            'Half Flush': self.is_half_flush,
            'Full Flush': self.is_full_flush
        }

    def is_thirteen_orphans(self):
        # Check for Thirteen Orphans
        required_tiles = ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B']
        return all(tile in self.tiles for tile in required_tiles) and self.tiles.count(self.tiles[0]) == 2

    def is_seven_pairs(self):
        # Check for Seven Pairs
        pairs = set([tile for tile in self.tiles if self.tiles.count(tile) == 2])
        return len(pairs) == 7

    def is_all_pungs(self):
        # Check for All Pungs
        return all(self.tiles.count(tile) == 3 for tile in self.tiles) and len(set(self.tiles)) == 4

    def is_all_chows(self):
        # Check for All Chows
        return all(self.tiles.count(tile) == 3 for tile in self.tiles) and len(set(self.tiles)) == 4

    def is_mixed_shifted_chows(self):
        # Check for Mixed Shifted Chows
        return False  # Placeholder for implementation

    def is_all_terminals_and_honors(self):
        # Check for All Terminals and Honors
        terminals_and_honors = ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B']
        return all(tile in terminals_and_honors for tile in self.tiles)

    def is_all_simples(self):
        # Check for All Simples
        simples = ['2m', '3m', '4m', '5m', '6m', '7m', '8m', 
                   '2p', '3p', '4p', '5p', '6p', '7p', '8p', 
                   '2s', '3s', '4s', '5s', '6s', '7s', '8s']
        return all(tile in simples for tile in self.tiles)

    def is_half_flush(self):
        # Check for Half Flush
        suits = set([tile[-1] for tile in self.tiles])
        return len(suits) == 2

    def is_full_flush(self):
        # Check for Full Flush
        suits = set([tile[-1] for tile in self.tiles])
        return len(suits) == 1

# Online Class Platform Implementation

class OnlineClassPlatform:
    def __init__(self):
        # Dictionary to store student data
        self.students = {}
        # Dictionary to store course data
        self.courses = {}

    # Student Management Functions
    def add_student(self, student_id, name):
        if student_id in self.students:
            raise ValueError(f"Student with ID {student_id} already exists.")

        self.students[student_id] = {
            'name': name,
            'courses': {},
            'average_score': 0.0
        }

    def remove_student(self, student_id):
        if student_id not in self.students:
            raise ValueError(f"Student with ID {student_id} does not exist.")

        for course_id, course_data in self.courses.items():
            if student_id in course_data['students']:
                course_data['students'].remove(student_id)
                self._update_course_performance(course_id)

        del self.students[student_id]

    def update_student_course(self, student_id, course_id, performance_metrics):
        if student_id not in self.students:
            raise ValueError(f"Student with ID {student_id} does not exist.")

        if course_id not in self.courses:
            raise ValueError(f"Course with ID {course_id} does not exist.")

        self.students[student_id]['courses'][course_id] = performance_metrics
        self._update_student_performance(student_id)
        self._update_course_performance(course_id)

    def list_students_above_average(self, average_score):
        return [student for student in self.students.values() 
                if student['average_score'] > average_score]

    # Course Management Functions
    def add_course(self, course_id, name):
        if course_id in self.courses:
            raise ValueError(f"Course with ID {course_id} already exists.")

        self.courses[course_id] = {
            'name': name,
            'students': [],
            'average_performance': 0.0
        }

    def remove_course(self, course_id):
        if course_id not in self.courses:
            raise ValueError(f"Course with ID {course_id} does not exist.")

        for student_id in self.courses[course_id]['students']:
            if course_id in self.students[student_id]['courses']:
                del self.students[student_id]['courses'][course_id]
                self._update_student_performance(student_id)

        del self.courses[course_id]

    def add_student_to_course(self, student_id, course_id):
        if student_id not in self.students:
            raise ValueError(f"Student with ID {student_id} does not exist.")

        if course_id not in self.courses:
            raise ValueError(f"Course with ID {course_id} does not exist.")

        if student_id in self.courses[course_id]['students']:
            raise ValueError(f"Student with ID {student_id} is already enrolled in the course {course_id}.")

        self.courses[course_id]['students'].append(student_id)
        self.students[student_id]['courses'][course_id] = {}
        self._update_course_performance(course_id)

    def remove_student_from_course(self, student_id, course_id):
        if student_id not in self.students:
            raise ValueError(f"Student with ID {student_id} does not exist.")

        if course_id not in self.courses:
            raise ValueError(f"Course with ID {course_id} does not exist.")

        if student_id not in self.courses[course_id]['students']:
            raise ValueError(f"Student with ID {student_id} is not enrolled in the course {course_id}.")

        self.courses[course_id]['students'].remove(student_id)
        if course_id in self.students[student_id]['courses']:
            del self.students[student_id]['courses'][course_id]
            self._update_student_performance(student_id)

        self._update_course_performance(course_id)

    def find_highest_scoring_student(self, course_id):
        if course_id not in self.courses:
            raise ValueError(f"Course with ID {course_id} does not exist.")

        highest_score = -1
        highest_student = None

        for student_id in self.courses[course_id]['students']:
            if course_id in self.students[student_id]['courses']:
                score = sum(self.students[student_id]['courses'][course_id].values()) / \
                        len(self.students[student_id]['courses'][course_id])

                if score > highest_score:
                    highest_score = score
                    highest_student = student_id

        return highest_student, highest_score

    # Helper Functions
    def _update_student_performance(self, student_id):
        if not self.students[student_id]['courses']:
            self.students[student_id]['average_score'] = 0.0
            return

        total_scores = 0
        total_metrics = 0

        for course_id, metrics in self.students[student_id]['courses'].items():
            total_scores += sum(metrics.values())
            total_metrics += len(metrics)

        self.students[student_id]['average_score'] = total_scores / total_metrics

    def _update_course_performance(self, course_id):
        if not self.courses[course_id]['students']:
            self.courses[course_id]['average_performance'] = 0.0
            return

        total_scores = 0
        total_metrics = 0

        for student_id in self.courses[course_id]['students']:
            if course_id in self.students[student_id]['courses']:
                total_scores += sum(self.students[student_id]['courses'][course_id].values())
                total_metrics += len(self.students[student_id]['courses'][course_id])

        self.courses[course_id]['average_performance'] = total_scores / total_metrics


