from megatron.training import get_args


def is_enable_lora():
    """
    Check if LoRA is enabled based on target modules configuration.
    """
    args = get_args()
    # Check if lora_target_modules attribute exists and is non-empty
    if hasattr(args, 'lora_target_modules') and args.lora_target_modules:
        return True
    return False


def is_save_full_weight():
    """
    Determine whether to save full weights instead of LoRA adapters.
    """
    args = get_args()
    mm_model = args.mm_model
    # Get lora_save_full_weight attribute with default False
    save_full_weight = getattr(mm_model, 'lora_save_full_weight', False)
    return save_full_weight


def merge_dicts(statedict1, statedict2):
    """
    Recursively merge two dictionaries.
    Nested dictionaries are merged recursively; other values from statedict2 overwrite those in statedict1.
    """
    result = statedict1.copy()  # Create a copy to avoid modifying original
    for key, value in statedict2.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge_dicts(result[key], value)
        else:
            result[key] = value
    return result


def modify_keys_with_dict(dictionary, exclude_words):
    """
    Modify keys in the dictionary by replacing 'weight'/'bias' with 'base_layer.weight'/'base_layer.bias'
    for target modules, excluding specified words.
    """
    args = get_args()
    modified_dict = {}

    for key, value in dictionary.items():
        key_str = str(key)

        # Check if key contains any excluded word
        not_exclude_word = not any(exclude_word in key_str for exclude_word in exclude_words)

        # Check if key corresponds to a trainable target module's bias or weight
        is_target_module_bias = any(
            key_str == target_module + '.bias' 
            for target_module in args.lora_trainable_target_modules
        )
        is_target_module_weight = any(
            key_str == target_module + '.weight' 
            for target_module in args.lora_trainable_target_modules
        )

        new_key = key_str

        # Apply transformation if conditions are met
        if not_exclude_word and (is_target_module_bias or is_target_module_weight):
            if 'weight' in key_str:
                new_key = key_str.replace('weight', 'base_layer.weight')
            elif 'bias' in key_str:
                new_key = key_str.replace('bias', 'base_layer.bias')

        modified_dict[new_key] = value

    return modified_dict


def remove_base_layer_keys(state_dict):
    """
    Remove '.base_layer' suffix from keys in state_dict.
    Returns a mapping of old keys to new keys.
    """
    if state_dict is None or not isinstance(state_dict, dict):
        return {}

    key_mapping = {}
    original_keys = list(state_dict.keys())

    for old_key in original_keys:
        if '.base_layer' in old_key:
            new_key = old_key.replace('.base_layer', '')
            key_mapping[old_key] = new_key
            state_dict[new_key] = state_dict.pop(old_key)

    return key_mapping


def restore_base_layer_keys(modified_state_dict, key_mapping):
    """
    Restore original keys in modified_state_dict using the provided key_mapping.
    """
    if modified_state_dict is None or not isinstance(modified_state_dict, dict):
        return
    if key_mapping is None or not isinstance(key_mapping, dict):
        return

    reverse_mapping = {new_key: orig_key for orig_key, new_key in key_mapping.items()}
    modified_keys = list(modified_state_dict.keys())

    for key in modified_keys:
        original_key = reverse_mapping.get(key, key)
        if original_key != key:
            modified_state_dict[original_key] = modified_state_dict.pop(key)

