# Base UI page class
class UIPage():
    parent = None

    def __init__(self, check_icon: Union[ImgIcon, Text, List]):
        self.links = {}
        self.name = get_name_from_caller(depth=2)
        self.check_icon_list = []

        # Handle different types of check icons
        if isinstance(check_icon, List):
            self.check_icon_list = check_icon
        elif isinstance(check_icon, ImgIcon):
            self.check_icon_list.append(check_icon)
        elif isinstance(check_icon, Text):
            self.check_icon_list.append(check_icon)

    # Equality comparison based on name
    def __eq__(self, other):
        return self.name == other.name

    # Hash based on name for use in sets/dicts
    def __hash__(self):
        return hash(self.name)

    # String representation
    def __str__(self):
        return self.name

    # Link a button to a destination page
    def link(self, button, destination):
        """
        Links a button to a destination page.

        button: Button/Str
        """
        self.links[destination] = button

    # Check if this is the current page by verifying icons/text presence
    def is_current_page(self, itt):
        for imgicon in self.check_icon_list:
            ret = False
            if isinstance(imgicon, ImgIcon):
                ret = itt.get_img_existence(imgicon)
            elif isinstance(imgicon, Text):
                ret = itt.get_text_existence(imgicon)

            if ret:
                return True

        return False

    # Add additional check icon
    def add_check_icon(self, check_icon: ImgIcon):
        self.check_icon_list.append(check_icon)

