# Import required modules
import ast
import sys

# Import custom taint analysis module
from skylos.rules.danger.taint import TaintVisitor

# Define redirect function names that may be vulnerable to open redirects
REDIRECT_FUNCS = {"redirect", "HttpResponseRedirect", "HttpResponsePermanentRedirect"}


class _RedirectFlowChecker(TaintVisitor):
    def visit_Call(self, node):
        # Extract function name from call node
        func = node.func
        func_name = None

        if isinstance(func, ast.Name):
            func_name = func.id
        elif isinstance(func, ast.Attribute):
            func_name = func.attr

        # Check if the function is a known redirect function and has arguments
        if func_name in REDIRECT_FUNCS and node.args:
            url_arg = node.args[0]

            # If URL argument is tainted (user-controlled), report finding
            if self.is_tainted(url_arg):
                self.findings.append(
                    {
                        "rule_id": "SKY-D230",
                        "severity": "HIGH",
                        "message": "Possible open redirect: user-controlled URL passed to redirect.",
                        "file": str(self.file_path),
                        "line": node.lineno,
                        "col": node.col_offset,
                        "symbol": self._current_symbol(),
                    }
                )

        # Continue visiting child nodes
        self.generic_visit(node)


def scan(tree, file_path, findings):
    try:
        # Initialize checker and run analysis
        checker = _RedirectFlowChecker(file_path, findings)
        checker.visit(tree)
    except Exception as e:
        # Report errors during analysis
        print(f"Redirect flow analysis failed for {file_path}: {e}", file=sys.stderr)

