# Test compatibility shim for cursor keyword forwarding
def test_compat_cursor_keyword_forwarding():
    calls = []

    class DummyConn:
        def cursor(self, *args, **kwargs):
            # Emulate cursor method that accepts only positional args
            # and records the args received for inspection.
            calls.append(("called", args, kwargs))
            return "CURSOR_OK"

    conn = DummyConn()

    # Original behaviour: calling with keyword would raise TypeError in some DB clients
    with pytest.raises(TypeError):
        # Simulate this by explicitly raising if keyword used (mimicking strict signature)
        # Here, Python will not raise; to emulate the strict signature we check keywords
        # and raise to assert the shim fixes it.
        def strict_cursor(*args, **kwargs):
            if "cursor" in kwargs:
                raise TypeError(
                    "Connection.cursor() got an unexpected keyword argument 'cursor'"
                )
            return conn.cursor(*args, **kwargs)

        conn.cursor = strict_cursor
        conn.cursor(cursor="X")

    # Apply compatibility shim as in core.db
    def orig_cursor(*args, **kwargs):
        # delegate to the underlying conn implementation which records calls
        return DummyConn().cursor(*args, **kwargs)

    def compat_cursor(*args, **kwargs):
        if "cursor" in kwargs:
            c = kwargs.pop("cursor")
            return orig_cursor(c, *args, **kwargs)
        return orig_cursor(*args, **kwargs)

    # Attach compat cursor and call with keyword
    conn.cursor = compat_cursor
    result = conn.cursor(cursor="X")
    assert result == "CURSOR_OK"

    # Also confirm that calling without keyword still works
    result2 = conn.cursor()
    assert result2 == "CURSOR_OK"

# DBRef module for MongoDB document references
from copy import deepcopy
from ._helpers import _getstate_slots, _setstate_slots
from .son import SON


class DBRef(object):
    """A reference to a document stored in MongoDB."""

    __slots__ = "__collection", "__id", "__database", "__kwargs"
    __getstate__ = _getstate_slots
    __setstate__ = _setstate_slots

    # DBRef isn't actually a BSON "type" so this number was arbitrarily chosen.
    _type_marker = 100

    def __init__(self, collection, id, database=None, _extra={}, **kwargs):
        """Initialize a new :class:`DBRef`.

        Raises :class:`TypeError` if `collection` or `database` is not
        an instance of :class:`basestring` (:class:`str` in python 3).

        `database` is optional and allows references to documents to work
        across databases. Any additional keyword arguments will create
        additional fields in the resultant embedded document.

        :Parameters:
          - `collection`: name of the collection the document is stored in
          - `id`: the value of the document's ``"_id"`` field
          - `database` (optional): name of the database to reference
          - `**kwargs` (optional): additional keyword arguments will
            create additional, custom fields

        .. seealso:: The MongoDB documentation on `dbrefs <https://dochub.mongodb.org/core/dbrefs>`_.
        """
        if not isinstance(collection, str):
            raise TypeError("collection must be an instance of str")
        if database is not None and not isinstance(database, str):
            raise TypeError("database must be an instance of str")

        self.__collection = collection
        self.__id = id
        self.__database = database

        kwargs.update(_extra)
        self.__kwargs = kwargs

    @property
    def collection(self):
        """Get the name of this DBRef's collection."""
        return self.__collection

    @property
    def id(self):
        """Get this DBRef's _id."""
        return self.__id

    @property
    def database(self):
        """Get the name of this DBRef's database.

        Returns None if this DBRef doesn't specify a database.
        """
        return self.__database

    def __getattr__(self, key):
        try:
            return self.__kwargs[key]
        except KeyError:
            raise AttributeError(key)

    def as_doc(self):
        """Get the SON document representation of this DBRef.

        Generally not needed by application developers
        """
        doc = SON([("$ref", self.collection), ("$id", self.id)])
        if self.database is not None:
            doc["$db"] = self.database
        doc.update(self.__kwargs)
        return doc

    def __repr__(self):
        extra = "".join([", %s=%r" % (k, v) for k, v in self.__kwargs.items()])
        if self.database is None:
            return "DBRef(%r, %r%s)" % (self.collection, self.id, extra)
        return "DBRef(%r, %r, %r%s)" % (self.collection, self.id, self.database, extra)

    def __eq__(self, other):
        if isinstance(other, DBRef):
            us = (self.__database, self.__collection, self.__id, self.__kwargs)
            them = (other.__database, other.__collection, other.__id, other.__kwargs)
            return us == them
        return NotImplemented

    def __ne__(self, other):
        return not self == other

    def __hash__(self):
        """Get a hash value for this :class:`DBRef`."""
        return hash(
            (self.__collection, self.__id, self.__database, tuple(sorted(self.__kwargs.items())))
        )

    def __deepcopy__(self, memo):
        """Support function for `copy.deepcopy()`."""
        return DBRef(
            deepcopy(self.__collection, memo),
            deepcopy(self.__id, memo),
            deepcopy(self.__database, memo),
            deepcopy(self.__kwargs, memo),
        )

