if n <= 0:
    return 0

elif n == 1:
    return 1

else:
    # Initialize first two Fibonacci numbers
    a, b = 0, 1

    # Calculate Fibonacci number iteratively
    for _ in range(2, n + 1):
        a, b = b, a + b

    # Return the nth Fibonacci number
    return b

