# Parses page ranges from a string specification
def parse_page_ranges(spec: str | None, total_pages: int) -> list[int]:
    # Handle empty or None spec
    if spec is None or spec.strip() == "":
        return list(range(total_pages))

    # Normalize the spec
    spec = spec.strip().lower()

    # Handle special cases
    if spec in {"all", "*"}:
        return list(range(total_pages))

    if spec == "odd":
        return [i for i in range(total_pages) if (i + 1) % 2 == 1]

    if spec == "even":
        return [i for i in range(total_pages) if (i + 1) % 2 == 0]

    # Parse comma-separated ranges
    indices: set[int] = set()
    for part in spec.split(","):
        part = part.strip()
        if not part:
            continue

        if "-" in part:
            start_s, end_s = part.split("-", 1)
            start = int(start_s)
            end = int(end_s)
        else:
            start = end = int(part)

        # Validate bounds
        if start < 1 or end < 1 or start > total_pages or end > total_pages:
            raise ValueError(f"Page range out of bounds: {start}-{end} of {total_pages}")

        if end < start:
            raise ValueError(f"Invalid page range: {start}-{end}")

        # Add all pages in the range
        for i in range(start - 1, end):
            indices.add(i)

    # Ensure at least one valid range was provided
    if not indices:
        raise ValueError("No valid ranges provided")

    return sorted(indices)

# Cache class for storing reusable arguments to speed up inference
class Cache:
    """Caching reusable args for faster inference"""

    def __init__(self, disable=False, prefix="", cache=None):
        # Initialize cache dictionary if none provided
        self.cache = cache if cache is not None else {}
        self.disable = disable
        self.prefix = prefix

    def __call__(self, key: str, fn: Callable):
        # If caching is disabled, just execute the function
        if self.disable:
            return fn()

        # Apply prefix to key
        key = self.prefix + key

        try:
            # Return cached result if available
            result = self.cache[key]
        except KeyError:
            # Compute and store result if not cached
            result = fn()
            self.cache[key] = result

        return result

    def namespace(self, namespace: str):
        # Create a new cache instance with updated prefix
        return Cache(
            disable=self.disable,
            prefix=self.prefix + namespace + ".",
            cache=self.cache,
        )

    def get(self, key: str):
        # Retrieve value from cache using prefixed key
        key = self.prefix + key
        return self.cache[key]

import threading
import asyncio

__all__ = ["get_async_loop", "run"]

# Create a background event loop thread
class AsyncLoopThread:
    def __init__(self):
        self.loop = asyncio.new_event_loop()
        self._thread = threading.Thread(target=self._start_loop, daemon=True)
        self._thread.start()

    def _start_loop(self):
        asyncio.set_event_loop(self.loop)
        self.loop.run_forever()

    def run(self, coro):
        # Schedule a coroutine onto the loop and block until it's done
        return asyncio.run_coroutine_threadsafe(coro, self.loop).result()

# Create one global instance
async_loop = None

def get_async_loop():
    global async_loop
    if async_loop is None:
        async_loop = AsyncLoopThread()
    return async_loop

def run(coro):
    """Run a coroutine in the background event loop."""
    return get_async_loop().run(coro)

