# Define a class to represent a task with name, duration, and priority
class Assignment:
    def __init__(self, title, hours, importance):
        self.title = title
        self.hours = hours  # time required in hours
        self.importance = importance  # higher value indicates higher importance

    def __str__(self):
        return f"Assignment(title={self.title}, hours={self.hours}, importance={self.importance})"

class Planner:
    def __init__(self, available_time):
        self.available_time = available_time  # dictionary mapping days to available hours
        self.plan = {day: [] for day in available_time}  # create empty plan for each day

    def assign_task(self, assignment, day):
        if self.available_time[day] >= assignment.hours:
            self.plan[day].append(assignment)
            self.available_time[day] -= assignment.hours
            return True
        return False

    def arrange_tasks(self, assignments):
        # Sort assignments by importance (most important first)
        assignments.sort(key=lambda x: x.importance, reverse=True)

        for assignment in assignments:
            for day in self.available_time:
                if self.assign_task(assignment, day):
                    break

    def display_plan(self):
        for day, assignments in self.plan.items():
            print(f"{day}:")
            for assignment in assignments:
                print(f"  - {assignment}")

# Convert numbers to words and generate LaTeX table
from num2words import num2words

def convert_number_to_text(value, language='en'):
    if language == 'en':
        return num2words(value, lang='en').replace('-', ' ').replace(',', '')
    elif language == 'fr':
        return num2words(value, lang='fr').replace('-', ' ').replace(',', '')
    else:
        raise ValueError("Language not supported")

def produce_latex_table(number_sequence):
    if not all(1 <= num <= 100 for num in number_sequence):
        raise ValueError("All numbers must be between 1 and 100")

    latex_output = "\\begin{tabular}{|c|c|c|}\n"
    latex_output += "\\hline\n"
    latex_output += "Number & English & French \\\\\n"
    latex_output += "\\hline\n"

    for value in number_sequence:
        english_text = convert_number_to_text(value, 'en')
        french_text = convert_number_to_text(value, 'fr')
        latex_output += f"{value} & {english_text} & {french_text} \\\\\n"
        latex_output += "\\hline\n"

    latex_output += "\\end{tabular}\n"
    return latex_output

