# Modified version of the original code with Type I clone transformations
from typing import List
import heapq

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.height = [0] * size

    def find_root(self, node):
        if self.parent[node] != node:
            self.parent[node] = self.find_root(self.parent[node])
        return self.parent[node]

    def merge(self, a, b):
        rootA = self.find_root(a)
        rootB = self.find_root(b)
        if rootA != rootB:
            if self.height[rootA] > self.height[rootB]:
                self.parent[rootB] = rootA
            elif self.height[rootA] < self.height[rootB]:
                self.parent[rootA] = rootB
            else:
                self.parent[rootB] = rootA
                self.height[rootA] += 1
            return True
        return False

def minimum_spanning_tree_weight(node_count, edge_list, skip_index=None, force_edge=None):
    uf = UnionFind(node_count)
    mst_cost = 0

    # Force include specific edge if provided
    if force_edge is not None:
        u, v, weight = force_edge
        if uf.merge(u, v):
            mst_cost += weight

    # Process remaining edges
    for idx, (u, v, weight) in enumerate(edge_list):
        if skip_index is not None and idx == skip_index:
            continue
        if uf.merge(u, v):
            mst_cost += weight

    # Check if all nodes are connected
    if all(uf.find_root(i) == uf.find_root(0) for i in range(node_count)):
        return mst_cost
    return float('inf')

def identify_mst_edges(node_count: int, raw_edges: List[List[int]]) -> List[List[int]]:
    # Add original index to edges for tracking
    indexed_edges = [(u, v, w, i) for i, (u, v, w) in enumerate(raw_edges)]
    # Sort edges by weight
    indexed_edges.sort(key=lambda x: x[2])

    # Calculate base MST weight
    base_weight = minimum_spanning_tree_weight(
        node_count, 
        [(u, v, w) for u, v, w, _ in indexed_edges]
    )

    critical = []
    pseudo_critical = []

    # Analyze each edge
    for pos, (u, v, w, original_idx) in enumerate(indexed_edges):
        # Test exclusion
        excluded_weight = minimum_spanning_tree_weight(
            node_count,
            [(u, v, w) for u, v, w, _ in indexed_edges],
            skip_index=pos
        )

        if excluded_weight > base_weight:
            critical.append(original_idx)
        else:
            # Test inclusion
            included_weight = minimum_spanning_tree_weight(
                node_count,
                [(u, v, w) for u, v, w, _ in indexed_edges],
                force_edge=(u, v, w)
            )

            if included_weight == base_weight:
                pseudo_critical.append(original_idx)

    return [critical, pseudo_critical, base_weight]

