def calculate_geometric_mean(x, y, z):
    try:
        # Compute the geometric mean of three numbers
        return (x * y * z) ** (1/3)
    except ZeroDivisionError:
        print("Error: One or more inputs are zero, which is invalid for geometric mean calculation.")
        sys.exit(1)
    except Exception as err:
        print(f"Error: An unexpected error occurred: {err}")
        sys.exit(1)

def obtain_user_input():
    try:
        # Prompt user for input values
        x = float(input("Enter the first number: "))
        y = float(input("Enter the second number: "))
        z = float(input("Enter the third number: "))

        # Ensure all numbers are distinct
        if len({x, y, z}) < 3:
            print("Error: All three numbers must be distinct.")
            sys.exit(1)

        return x, y, z
    except ValueError:
        print("Error: Invalid input. Please enter numerical values.")
        sys.exit(1)

