# Calculate the average of a list of numbers
def calculate_average(values):
    accumulator = 0
    for number in values:
        accumulator += number
    return accumulator / len(values)

def custom_base_arithmetics(n, m, base, operation, step=1):
    """
    You are given two positive integers n and m, an integer (base) in the range [2, 16] (inclusive),
    a string operation which will be one of the following ["sum", "diff", "product", "average", "mod"],
    and an optional integer step (default is 1).

    Your task is to:
    1. First, perform the specified operation on the integers from n to m (inclusive) with the given step.
    2. Then, round the result to the nearest integer.
    3. Finally, convert that to the custom base system and return the result.

    If n is greater than m, return -1.
    If base is outside the allowed range, also return -1.
    If step is less than or equal to 0, return -1.

    Example:
    custom_base_arithmetics(1, 5, 2, "average") => "0b11"
    custom_base_arithmetics(7, 5, 2, "sum") => -1
    custom_base_arithmetics(10, 20, 2, "product", 2) => "0b11111111111100000"
    custom_base_arithmetics(20, 33, 2, "diff", 3) => "0b11010"
    custom_base_arithmetics(20, 33, 8, "average", 2) => "0o32"
    custom_base_arithmetics(10, 20, 16, "mod", 2) => "0xa"
    """

    # Input validation
    if n > m:
        return -1
    if base < 2 or base > 16:
        return -1
    if step <= 0:
        return -1

    # Generate the sequence
    numbers = list(range(n, m + 1, step))

    # Perform the specified operation
    if operation == "sum":
        result = sum(numbers)
    elif operation == "diff":
        result = numbers[0]
        for i in range(1, len(numbers)):
            result -= numbers[i]
    elif operation == "product":
        result = 1
        for num in numbers:
            result *= num
    elif operation == "average":
        result = sum(numbers) / len(numbers) if numbers else 0
    elif operation == "mod":
        if not numbers:
            return -1
        result = numbers[0]
        for i in range(1, len(numbers)):
            if numbers[i] != 0:
                result %= numbers[i]
            else:
                return -1
    else:
        return -1

    # Round to nearest integer
    rounded_result = round(result)

    # Convert to custom base representation
    if rounded_result == 0:
        if base == 2:
            return "0b0"
        elif base == 8:
            return "0o0"
        elif base == 16:
            return "0x0"
        else:
            return str(rounded_result)

    # Handle negative numbers
    sign = ""
    if rounded_result < 0:
        sign = "-"
        rounded_result = abs(rounded_result)

    # Convert to the specified base
    digits = "0123456789abcdef"
    converted = ""
    temp = rounded_result

    while temp > 0:
        converted = digits[temp % base] + converted
        temp //= base

    # Add appropriate prefix based on base
    if base == 2:
        return f"{sign}0b{converted}"
    elif base == 8:
        return f"{sign}0o{converted}"
    elif base == 16:
        return f"{sign}0x{converted}"
    else:
        return f"{sign}{converted}"

import imdb

# Initialize the IMDb object
db = imdb.IMDb()

def fetch_person_identifier(name):
    """Retrieve the IMDb ID of a person using their name."""
    try:
        search_results = db.search_person(name)
        if search_results:
            return search_results[0].personID
        else:
            raise ValueError(f"No individual found with the name {name}")
    except Exception as err:
        print(f"An error occurred: {err}")
        return None

def retrieve_filmography(person_id):
    """Obtain the filmography of a person by their IMDb ID."""
    try:
        individual = db.get_person(person_id, info=['filmography'])
        return individual.get('filmography', [])
    except Exception as err:
        print(f"An error occurred: {err}")
        return []

def compute_average_rating(filmography):
    """Determine the mean rating of movies in the filmography."""
    sum_ratings = 0
    movie_count = 0
    for section in filmography:
        for entry in filmography[section]:
            if 'rating' in entry and entry['rating']:
                sum_ratings += entry['rating']
                movie_count += 1
    return sum_ratings / movie_count if movie_count > 0 else 0

def extract_supporting_actors(filmography):
    """Generate a list of all supporting actors in each movie."""
    ensemble = {}
    for section in filmography:
        for entry in filmography[section]:
            if 'cast' in entry:
                ensemble[entry['title']] = [actor['name'] for actor in entry['cast'] if actor['name'] != 'Daniel Day-Lewis']
    return ensemble

def tally_directors(filmography):
    """Determine how frequently the actor collaborated with each director."""
    collaboration_counts = {}
    for section in filmography:
        for entry in filmography[section]:
            if 'director' in entry:
                for director in entry['director']:
                    director_name = director['name']
                    if director_name in collaboration_counts:
                        collaboration_counts[director_name] += 1
                    else:
                        collaboration_counts[director_name] = 1
    return collaboration_counts

# Primary function to execute the analysis
def perform_analysis(name):
    person_id = fetch_person_identifier(name)
    if person_id:
        filmography = retrieve_filmography(person_id)
        if filmography:
            mean_rating = compute_average_rating(filmography)
            supporting_cast = extract_supporting_actors(filmography)
            director_stats = tally_directors(filmography)
            return {
                'average_rating': mean_rating,
                'supporting_cast': supporting_cast,
                'director_stats': director_stats
            }
    return None

# Demonstration usage
