# Define a class to represent a student with validation
class Learner:
    def __init__(self, full_name, years, subject):
        if not (18 <= years <= 99):
            raise ValueError("Age must be between 18 and 99.")
        if len(full_name) > 100:
            raise ValueError("Name cannot exceed 100 characters.")
        if len(subject) > 50:
            raise ValueError("Subject name cannot exceed 50 characters.")

        self.full_name = full_name
        self.years = years
        self.subject = subject

    def __repr__(self):
        return f"Learner(Name={self.full_name}, Age={self.years}, Subject={self.subject})"

# Class to manage multiple learners
class LearnerRegistry:
    def __init__(self):
        self.learners = []
        self.name_index = {}

    def register_learner(self, full_name, years, subject):
        learner = Learner(full_name, years, subject)
        self.learners.append(learner)
        if full_name in self.name_index:
            self.name_index[full_name].append(learner)
        else:
            self.name_index[full_name] = [learner]

    def unregister_learner(self, full_name):
        if full_name in self.name_index:
            learner_to_remove = self.name_index[full_name].pop(0)
            self.learners.remove(learner_to_remove)
            if not self.name_index[full_name]:
                del self.name_index[full_name]

    def find_learner(self, full_name):
        if full_name in self.name_index:
            return self.name_index[full_name]
        return []

    def modify_learner(self, full_name, years=None, subject=None):
        if full_name in self.name_index:
            learner_to_modify = self.name_index[full_name][0]
            if years is not None:
                if not (18 <= years <= 99):
                    raise ValueError("Age must be between 18 and 99.")
                learner_to_modify.years = years
            if subject is not None:
                if len(subject) > 50:
                    raise ValueError("Subject name cannot exceed 50 characters.")
                learner_to_modify.subject = subject

    def list_learners_sorted(self):
        sorted_learners = sorted(self.learners, key=lambda x: x.full_name)
        return sorted_learners

