# Display the current state of the Tic-Tac-Toe board
def display_grid(grid):
    print("-------------")
    for line in grid:
        print("|", end=" ")
        for square in line:
            print(square, end=" | ")
        print("\n-------------")

# Determine if a player has won the game
def has_won(grid, marker):
    # Check all rows
    for row in grid:
        if all([cell == marker for cell in row]):
            return True
    # Check all columns
    for col in range(3):
        if all([grid[row][col] == marker for row in range(3)]):
            return True
    # Check diagonals
    if all([grid[i][i] == marker for i in range(3)]) or all([grid[i][2-i] == marker for i in range(3)]):
        return True
    return False

# Check if the board is completely filled
def board_filled(grid):
    return all([cell != " " for row in grid for cell in row])

# Main game loop
def run_game():
    grid = [[" " for _ in range(3)] for _ in range(3)]
    turn = "X"
    while True:
        display_grid(grid)
        try:
            position = int(input(f"Player {turn}, enter your move (1-9): "))
            if position < 1 or position > 9:
                raise ValueError("Invalid move. Please choose a number between 1 and 9.")
            x, y = (position-1) // 3, (position-1) % 3
            if grid[x][y] != " ":
                raise ValueError("Cell already taken. Choose another one.")
            grid[x][y] = turn
            if has_won(grid, turn):
                display_grid(grid)
                print(f"Player {turn} wins!")
                break
            if board_filled(grid):
                display_grid(grid)
                print("It's a tie!")
                break
            turn = "O" if turn == "X" else "X"
