import sqlite3

def check_value_in_bounds(val, val_type, min_val, max_val):
    # Check if the value matches the expected type
    if not isinstance(val, val_type):
        return f"not an {val_type.__name__}"
    # Check if the value is within the specified range
    if val < min_val or val > max_val:
        return f"{val_type.__name__} out of range [{min_val}-{max_val}]."
    return "OK"

def ensure_non_default(val, val_type, default_val):
    # Verify the value is of the correct type
    if not isinstance(val, val_type):
        return f"not an {val_type.__name__}"
    # Check if the value equals the default (and warn if so)
    if val == default_val:
        return f"default value of {default_val} - make sure this is what you want."
    return "OK"

