# Mobile device class definition
class Smartphone:
    def __init__(self, manufacturer, device_name, operating_system, battery_size, display_dimension):
        self.manufacturer = manufacturer
        self.device_name = device_name
        self.operating_system = operating_system
        self.battery_size = battery_size
        self.display_dimension = display_dimension
        self.charge_level = battery_size  # Start with full charge
        self.is_switched_on = False

    def turn_on(self):
        if not self.is_switched_on:
            self.is_switched_on = True
            print(f"{self.manufacturer} {self.device_name} is now switched on.")
        else:
            print(f"{self.manufacturer} {self.device_name} is already switched on.")

    def turn_off(self):
        if self.is_switched_on:
            self.is_switched_on = False
            print(f"{self.manufacturer} {self.device_name} is now switched off.")
        else:
            print(f"{self.manufacturer} {self.device_name} is already switched off.")

    def consume_power(self, drain_amount):
        if self.is_switched_on:
            if self.charge_level >= drain_amount:
                self.charge_level -= drain_amount
                print(f"Current battery: {self.charge_level} mAh")
            else:
                print("Insufficient battery for this operation.")
        else:
            print("Device is switched off. Please switch it on first.")

    def replenish_battery(self, charge_amount):
        if self.charge_level + charge_amount <= self.battery_size:
            self.charge_level += charge_amount
            print(f"Current battery: {self.charge_level} mAh")
        else:
            self.charge_level = self.battery_size
            print("Battery is now fully charged.")

# Calculate various statistics for a list of numbers 
def get_max_value(values):
    if not values:
        return "Error: The list is empty."
    max_val = values[0]
    for val in values[1:]:
        if val > max_val:
            max_val = val
    return max_val

def get_min_value(values):
    if not values:
        return "Error: The list is empty."
    min_val = values[0]
    for val in values[1:]:
        if val < min_val:
            min_val = val
    return min_val

def compute_mean(values):
    if not values:
        return "Error: The list is empty."
    sum_total = sum(values)
    return sum_total / len(values)

def compute_middle_value(values):
    if not values:
        return "Error: The list is empty."
    sorted_values = sorted(values)
    length = len(sorted_values)
    if length % 2 == 1:
        return sorted_values[length // 2]
    else:
        return (sorted_values[length // 2 - 1] + sorted_values[length // 2]) / 2

def compute_most_frequent(values):
    if not values:
        return "Error: The list is empty."
    frequency_map = {}
    for value in values:
        if value in frequency_map:
            frequency_map[value] += 1
        else:
            frequency_map[value] = 1
    highest_frequency = max(frequency_map.values())
    most_frequent = [value for value, freq in frequency_map.items() if freq == highest_frequency]
    return most_frequent[0] if len(most_frequent) == 1 else most_frequent

