print(f"Smallest number: {minimum}")
print(f"Average: {mean}")
print(f"Median: {median}")
print(f"Mode: {mode}")

# Modified version with renamed variables and restructured logic
import re

def locate_duplicate_term_and_singular_char(content):
    # Locate duplicate terms with minimum 4 consecutive repetitions
    dup_term = None
    dup_term_index = None
    singular_char = None
    singular_char_index = None

    # Extract words from the content
    tokens = re.findall(r'\b\w+\b', content)

    # Search for duplicate terms with at least 4 consecutive occurrences
    for idx in range(len(tokens) - 3):
        if tokens[idx] == tokens[idx + 1] == tokens[idx + 2] == tokens[idx + 3]:
            dup_term = tokens[idx]
            dup_term_index = idx
            break

    # Analyze character frequencies
    char_occurrences = {}
    for index, symbol in enumerate(content):
        if symbol.isalpha():
            if symbol in char_occurrences:
                char_occurrences[symbol].append(index)
            else:
                char_occurrences[symbol] = [index]

    # Identify the singular character (appears exactly once)
    for char, indices in char_occurrences.items():
        if len(indices) == 1:
            singular_char = char
            singular_char_index = indices[0]
            break

    return dup_term, dup_term_index, singular_char, singular_char_index

