# Date reminder system with validation and custom reminders
from datetime import datetime
import calendar

class InvalidDateError(Exception):
    """Exception raised for invalid date inputs."""
    pass

class NoReminderError(Exception):
    """Exception raised when no reminder is defined for a month."""
    pass

# Pre-defined reminders for certain months
PRE_DEFINED_REMINDERS = {
    "January": "New Year's resolutions!",
    "February": "Valentine's Day is coming up!",
    "March": "Spring is here!",
    "April": "Easter is around the corner!",
    "May": "Mother's Day is coming up!",
    "June": "Summer is here!",
    "July": "Independence Day in the USA!",
    "August": "Back to school!",
    "September": "Fall is coming!",
    "October": "Halloween is coming up!",
    "November": "Thanksgiving is around the corner!",
    "December": "Christmas is coming up!"
}

# Custom reminders added by the user
CUSTOM_REMINDERS = {}

def check_leap_year(year):
    """Determine if a year is a leap year."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def verify_date(date_str):
    """Validate the date string and return the date object."""
    try:
        date = datetime.strptime(date_str, "%d %B")
        current_year = datetime.now().year
        if date.month == 2 and date.day > 29:
            raise InvalidDateError("February can have at most 29 days in a leap year.")
        if date.month == 2 and date.day > 28 and not check_leap_year(current_year):
            raise InvalidDateError("February can have at most 28 days in a non-leap year.")
        if date.day > calendar.monthrange(current_year, date.month)[1]:
            raise InvalidDateError(f"Invalid day for the month of {date.strftime('%B')}.")
        return date
    except ValueError:
        raise InvalidDateError("Invalid date format. Please use 'DD Month' format.")

def fetch_reminder(date):
    """Retrieve the reminder for the given date."""
    month_name = date.strftime("%B")
    if month_name in PRE_DEFINED_REMINDERS:
        return PRE_DEFINED_REMINDERS[month_name]
    if (date.day, month_name) in CUSTOM_REMINDERS:
        return CUSTOM_REMINDERS[(date.day, month_name)]
    raise NoReminderError(f"No reminder defined for {date.strftime('%d %B')}.")

def set_custom_reminder(date, message):
    """Add a custom reminder for a specific date."""
    CUSTOM_REMINDERS[(date.day, date.strftime("%B"))] = message

def run_app():
    while True:
        date_input = input("Enter the date (DD Month) or 'quit' to exit: ")
        if date_input.lower() == 'quit':
            break
        try:
            date_obj = verify_date(date_input)
            try:
                reminder_text = fetch_reminder(date_obj)
                print(f"Reminder for {date_input}: {reminder_text}")
            except NoReminderError as err:
                print(err)
                add_choice = input("Would you like to add a custom reminder for this date? (yes/no): ")
                if add_choice.lower() == 'yes':
                    custom_message = input("Enter your custom reminder: ")
                    set_custom_reminder(date_obj, custom_message)
                    print(f"Custom reminder added for {date_input}: {custom_message}")
        except InvalidDateError as error:
            print(error)

if __name__ == "__main__":
    run_app()

# Calculate and store Fibonacci-like sequence values with caching and expiration
import os
import pickle
from typing import List, Tuple
from collections import defaultdict
from datetime import datetime, timedelta

# Cache file path
CACHE_FILE = 'fibfib_cached_data.pkl'
# Expiration duration for cached results
EXPIRY_DURATION = timedelta(hours=24)

def retrieve_cache():
    if os.path.exists(CACHE_FILE):
        with open(CACHE_FILE, 'rb') as f:
            return pickle.load(f)
    return defaultdict(lambda: {})

def persist_cache(cache):
    with open(CACHE_FILE, 'wb') as f:
        pickle.dump(cache, f)

def compute_fibfib_with_param(n: int, param: int):
    if n < 0 or param < 0:
        raise ValueError("n and param must be non-negative integers")

    cache = retrieve_cache()
    if (n, param) in cache:
        value, timestamp = cache[(n, param)]
        if datetime.now() - timestamp < EXPIRY_DURATION:
            return value

    if n == 0:
        outcome = 0
    elif n == 1:
        outcome = 1
    else:
        outcome = compute_fibfib_with_param(n - 1, param) + compute_fibfib_with_param(n - 2, param)

    cache[(n, param)] = (outcome, datetime.now())
    persist_cache(cache)
    return outcome

def process_multiple_fibfib(requests: List[Tuple[int, int]]) -> List[int]:
    if not all(len(req) == 2 and all(isinstance(x, int) and x >= 0 for x in req) for req in requests):
        raise ValueError("Each request must be a tuple of two non-negative integers")

    cache = retrieve_cache()
    outputs = []

    for x, y in requests:
        if (x, y) in cache:
            value, timestamp = cache[(x, y)]
            if datetime.now() - timestamp < EXPIRY_DURATION:
                outputs.append(value)
                continue

        result = compute_fibfib_with_param(x, y)
        outputs.append(result)

    return outputs

def refresh_cache():
    cache = retrieve_cache()
    current_time = datetime.now()
    stale_keys = []

    for key, (value, timestamp) in cache.items():
        if current_time - timestamp > EXPIRY_DURATION:
            stale_keys.append(key)

    for key in stale_keys:
        del cache[key]

    persist_cache(cache)

# Demonstration usage
if __name__ == "__main__":
    # Compute fibfib(5, 0)
    print(compute_fibfib_with_param(5, 0))  # Expected output: 5

    # Process multiple queries
    requests = [(5, 0), (6, 0), (7, 0)]
    outputs = process_multiple_fibfib(requests)
    print(outputs)  # Expected output: [5, 8, 13]

    # Refresh cache entries
    refresh_cache()

