# User authentication and management system using FastAPI
from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import OAuth2PasswordBearer
from pydantic import BaseModel
from passlib.context import CryptContext
from jose import JWTError, jwt
import datetime

# User credentials and roles storage
user_credentials = {
    "David": {"password": "REDACTED_CREDENTIAL", "role": "admin"},
    "Sara": {"password": "REDACTED_CREDENTIAL", "role": "user"}
}

# Initialize FastAPI application
app = FastAPI()

# OAuth2 scheme for token handling
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

# Password hashing context
pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")

# JWT configuration
SECRET_KEY = "REDACTED_CREDENTIAL"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 30

# Pydantic models for request/response validation
class TokenData(BaseModel):
    username: str
    role: str

class User(BaseModel):
    username: str
    password: str

class UserInDB(User):
    role: str

# Utility functions
def check_password(plain_password, hashed_password):
    return pwd_context.verify(plain_password, hashed_password)

def hash_password(password):
    return pwd_context.hash(password)

def fetch_user(username: str):
    if username in user_credentials:
        user_dict = user_credentials[username]
        return UserInDB(**user_dict, username=username)

def validate_user(username: str, password: str):
    user = fetch_user(username)
    if not user:
        return False
    if not check_password(password, user.password):
        return False
    return user

def generate_access_token(data: dict, expires_delta: datetime.timedelta):
    payload = data.copy()
    expiration = datetime.datetime.utcnow() + expires_delta
    payload.update({"exp": expiration})
    token = jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)
    return token

# Dependency to retrieve authenticated user
async def fetch_current_user(token: str = Depends(oauth2_scheme)):
    auth_exception = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Could not validate credentials",
        headers={"WWW-Authenticate": "Bearer"},
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username: str = payload.get("sub")
        role: str = payload.get("role")
        if username is None or role is None:
            raise auth_exception
        token_info = TokenData(username=username, role=role)
    except JWTError:
        raise auth_exception
    user = fetch_user(username=token_info.username)
    if user is None:
        raise auth_exception
    return user

async def fetch_active_user(current_user: UserInDB = Depends(fetch_current_user)):
    return current_user

# API endpoints
@app.post("/token")
async def obtain_access_token(user: User):
    user_record = validate_user(user.username, user.password)
    if not user_record:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"},
        )
    token_duration = datetime.timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    access_token = generate_access_token(
        data={"sub": user_record.username, "role": user_record.role}, 
        expires_delta=token_duration
    )
    return {"access_token": access_token, "token_type": "bearer"}

@app.get("/users/me")
async def get_user_profile(current_user: UserInDB = Depends(fetch_active_user)):
    return current_user

@app.get("/users")
async def list_users(current_user: UserInDB = Depends(fetch_active_user)):
    if current_user.role != "admin":
        raise HTTPException(status_code=403, detail="You do not have permission to access this resource")
    return user_credentials

@app.post("/users")
async def register_user(user: UserInDB, current_user: UserInDB = Depends(fetch_active_user)):
    if current_user.role != "admin":
        raise HTTPException(status_code=403, detail="You do not have permission to create users")
    if user.username in user_credentials:
        raise HTTPException(status_code=400, detail="User already exists")
    user_credentials[user.username] = {"password": hash_password(user.password), "role": user.role}
    return {"message": "User created successfully"}

@app.put("/users/{username}")
async def modify_user(username: str, user: UserInDB, current_user: UserInDB = Depends(fetch_active_user)):
    if current_user.role != "admin":
        raise HTTPException(status_code=403, detail="You do not have permission to update users")
    if username not in user_credentials:
        raise HTTPException(status_code=404, detail="User not found")
    user_credentials[username] = {"password": hash_password(user.password), "role": user.role}
    return {"message": "User updated successfully"}

@app.delete("/users/{username}")
async def remove_user(username: str, current_user: UserInDB = Depends(fetch_active_user)):
    if current_user.role != "admin":
        raise HTTPException(status_code=403, detail="You do not have permission to delete users")
    if username not in user_credentials:
        raise HTTPException(status_code=404, detail="User not found")
    del user_credentials[username]
    return {"message": "User deleted successfully"}

