# Thread-safe computation with conditional logic and locking
from threading import Thread, Lock
from concurrent.futures import ThreadPoolExecutor

a, b, c = 100, 0, 50
b_lock = Lock()

def compute_condition_one(val, b_val, c_val):
    if val > c_val:
        b_val = val + 20
    else:
        b_val = val**2 + c_val
    return b_val

def compute_condition_two(a_val, b_val, c_val):
    if a_val == c_val:
        b_val = a_val - 20
    else:
        b_val = c_val * 2
    return b_val

def handle_compute_one(val, b_val, c_val):
    with b_lock:
        b_val = compute_condition_one(val, b_val, c_val)
        print(f"Worker {val}: b = {b_val}")

def handle_compute_two(a_val, b_val, c_val):
    with b_lock:
        b_val = compute_condition_two(a_val, b_val, c_val)
        print(f"Worker {a_val//10}: b = {b_val}")

def run_main():
    global b
    if a > c:
        with ThreadPoolExecutor(max_workers=10) as pool:
            for j in range(a):
                pool.submit(handle_compute_one, j, b, c)
    else:
        with ThreadPoolExecutor(max_workers=10) as pool:
            while a >= 0:
                pool.submit(handle_compute_two, a, b, c)
                a -= 10

if __name__ == "__main__":
    run_main()

# ISBN validation utility class
class BookNumberChecker:
    def __init__(self, number):
        self.number = number.strip().replace('-', '')
        self.size = len(self.number)
        self.validity = False
        self.problem_description = None

    def check(self):
        if self.size == 10:
            self.validity = self._check_isbn10()
        elif self.size == 13:
            self.validity = self._check_isbn13()
        else:
            self.problem_description = f"Incorrect size: Book number must be either 10 or 13 digits, got {self.size}"
        return self.validity

    def _check_isbn10(self):
        if not self.number[:-1].isdigit() or not (self.number[-1].isdigit() or self.number[-1] == 'X'):
            self.problem_description = "Improper format: ISBN-10 should only have digits and optionally 'X' as final character"
            return False

        values = [int(c) if c != 'X' else 10 for c in self.number]
        multipliers = list(range(10, 0, -1))
        total = sum(v * m for v, m in zip(values, multipliers)) % 11

        if total != 0:
            self.problem_description = "Checksum failure: ISBN-10 verification failed"
            return False

        return True

    def _check_isbn13(self):
        if not self.number.isdigit():
            self.problem_description = "Improper format: ISBN-13 must consist solely of digits"
            return False

        values = [int(c) for c in self.number]
        multipliers = [1 if idx % 2 == 0 else 3 for idx in range(13)]
        total = sum(v * m for v, m in zip(values, multipliers)) % 10

        if total != 0:
            self.problem_description = "Checksum failure: ISBN-13 verification failed"
            return False

        return True

    def get_problem_description(self):
        return self.problem_description


# Demonstration usage
if __name__ == "__main__":
    book_numbers = [
        "0-306-40615-2",  # Correct ISBN-10
        "978-0-306-40615-7",  # Correct ISBN-13
        "0-306-40615-3",  # Incorrect ISBN-10
        "978-0-306-40615-8",  # Incorrect ISBN-13
        "12345678901234",  # Wrong length
        "0-306-4061X-2"  # Invalid symbols
    ]

    for num in book_numbers:
        checker = BookNumberChecker(num)
        if checker.check():
            print(f"{num} is a correct book number")
        else:
            print(f"{num} is an incorrect book number: {checker.get_problem_description()}")

# Modified version: renamed variables, reordered logic, and adjusted comments
import threading
import multiprocessing
import functools

class SingletonMeta(type):
    _instances = {}
    _thread_lock = threading.Lock()
    _process_lock = multiprocessing.Lock()

    def __call__(cls, *args, **kwargs):
        # Multiprocessing-safe singleton creation (moved before thread lock for demonstration)
        with cls._process_lock:
            if cls not in cls._instances:
                if cls not in cls._instances:
                    cls._instances[cls] = super(SingletonMeta, cls).__call__(*args, **kwargs)

        # Thread-safe singleton creation
        with cls._thread_lock:
            if cls not in cls._instances:
                if cls not in cls._instances:
                    cls._instances[cls] = super(SingletonMeta, cls).__call__(*args, **kwargs)

        return cls._instances[cls]

class Singleton(metaclass=SingletonMeta):
    def __init__(self, data=None):
        self.data = data

    def display(self):
        print(f"Singleton instance with value: {self.data}")

# Example usage
if __name__ == "__main__":
    # Thread-safe singleton creation
    def worker_thread():
        instance = Singleton(data="Thread")
        instance.display()

    threads = []
    for _ in range(5):
        t = threading.Thread(target=worker_thread)
        t.start()
        threads.append(t)
    for t in threads:
        t.join()

    # Multiprocessing-safe singleton creation
    def worker_process():
        instance = Singleton(data="Process")
        instance.display()

    processes = []
    for _ in range(5):
        p = multiprocessing.Process(target=worker_process)
        p.start()
        processes.append(p)
    for p in processes:
        p.join()

# URL management utilities with encoding options
import re
import random
import string
import logging

# Set up logging configuration
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

class WebAddressHandler:
    def __init__(self, scheme, subpart, main_domain, country_code_tld, resource_segment):
        self.scheme = scheme
        self.subpart = subpart
        self.main_domain = main_domain
        self.country_code_tld = country_code_tld
        self.resource_segment = resource_segment

    def build_url(self):
        if not self.check_components():
            return None
        return f"{self.scheme}://{self.subpart}.{self.main_domain}{self.country_code_tld}/{self.encode_resource_segment()}"

    def parse_url(self, url_string):
        regex_pattern = r'^(?P<scheme>[a-zA-Z]+)://(?P<subpart>[a-zA-Z0-9-]+)\.(?P<main_domain>[a-zA-Z0-9-]+)(?P<country_code_tld>\.[a-zA-Z]{2,6})/(?P<resource_segment>.+)$'
        result = re.match(regex_pattern, url_string)
        if result:
            return result.groupdict()
        else:
            logging.error(f"Malformed URL: {url_string}")
            return None

    def check_components(self):
        if not self.scheme or not self.subpart or not self.main_domain or not self.country_code_tld or not self.resource_segment:
            logging.error("All URL parts must be specified.")
            return False
        if self.scheme not in ['http', 'https', 'ftp', 'sftp']:
            logging.error(f"Unsupported scheme: {self.scheme}")
            return False
        if not re.match(r'^[a-zA-Z0-9-]+$', self.subpart):
            logging.error(f"Invalid subdomain part: {self.subpart}")
            return False
        if not re.match(r'^[a-zA-Z0-9-]+$', self.main_domain):
            logging.error(f"Invalid main domain: {self.main_domain}")
            return False
        if not re.match(r'^\.[a-zA-Z]{2,6}$', self.country_code_tld):
            logging.error(f"Invalid country code TLD: {self.country_code_tld}")
            return False
        return True

    def encode_resource_segment(self, use_random_encoding=False):
        if use_random_encoding:
            return self.apply_random_encoding()
        else:
            return self.apply_sequential_encoding()

    def apply_sequential_encoding(self):
        return re.sub(r'[^a-zA-Z0-9/]', lambda match: f"%{ord(match.group(0)):02X}", self.resource_segment)

    def apply_random_encoding(self):
        encoded_result = ""
        for symbol in self.resource_segment:
            if re.match(r'[^a-zA-Z0-9/]', symbol):
                if random.choice([True, False]):
                    encoded_result += f"%{ord(symbol):02X}"
                else:
                    encoded_result += symbol
            else:
                encoded_result += symbol
        return encoded_result

# Filter and sort students based on criteria
def process_students(student_data, min_height, min_weight, min_age, min_gpa):
    def validate_student_info(info):
        if not isinstance(info, tuple) or len(info) != 4:
            return False
        if not all(isinstance(val, (int, float)) for val in info):
            return False
        return True

    def transform_to_numbers(info):
        try:
            return tuple(float(val) for val in info)
        except ValueError:
            raise TypeError(f"Non-numeric entry in student record: {info}")

    qualified_students = []
    for name, info in student_data.items():
        if not validate_student_info(info):
            raise ValueError(f"Malformed student information for {name}: {info}")
        height, weight, age, gpa = transform_to_numbers(info)
        if height >= min_height and weight >= min_weight and age >= min_age and gpa >= min_gpa:
            qualified_students.append((name, height, weight, age, gpa))

    # Order by age (descending), then GPA (descending), then name (ascending)
    qualified_students.sort(key=lambda x: (-x[3], -x[4], x[0]))

    return qualified_students

