# OCaml server implementation for inter-process communication
import socket
import json
import threading

class RemoteCommandHandler:
    def __init__(self, ip='localhost', port=65432):
        self.ip_address = ip
        self.port_number = port
        self.listener_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.listener_socket.bind((self.ip_address, self.port_number))
        self.listener_socket.listen()
        print(f"Listening on {self.ip_address}:{self.port_number}")

    def run(self):
        while True:
            conn, addr = self.listener_socket.accept()
            print(f"New connection from {addr}")
            worker_thread = threading.Thread(target=self.process_request, args=(conn,))
            worker_thread.start()

    def process_request(self, connection):
        with connection:
            while True:
                data = connection.recv(1024)
                if not data:
                    break
                self.dispatch_command(data)

    def dispatch_command(self, payload):
        try:
            parsed = json.loads(payload)
            if parsed['category'] == 'command':
                exec(parsed['payload'])
            else:
                print("Unrecognized command category")
        except Exception as error:
            print(f"Command processing failed: {error}")

if __name__ == "__main__":
    handler = RemoteCommandHandler()
    handler.run()

# Define abstract base class and imports
from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class Vessel(ABC):
    def __init__(self, vessel_name, hull_length, max_passengers):
        self.vessel_name = vessel_name
        self.hull_length = hull_length
        self.max_passengers = max_passengers

    def drop_anchor(self):
        current_time = datetime.now().strftime("%H:%M:%S")
        print(f"Vessel {self.vessel_name} is anchored at {current_time}")

    def navigate(self, target_port, sea_distance):
        # Assume constant cruising speed of 10 nautical miles per hour
        cruising_speed = 10  # knots
        travel_duration = sea_distance / cruising_speed
        arrival_time = datetime.now() + timedelta(hours=travel_duration)
        arrival_formatted = arrival_time.strftime("%H:%M:%S")
        print(f"Vessel {self.vessel_name} is navigating to {target_port} and is expected to arrive at {arrival_formatted}")

    @abstractmethod
    def special_capability(self):
        pass

class PowerBoat(Vessel):
    def __init__(self, vessel_name, hull_length, max_passengers, fuel_tank_size, motor_output):
        super().__init__(vessel_name, hull_length, max_passengers)
        self.fuel_tank_size = fuel_tank_size
        self.motor_output = motor_output

    def ignite_engine(self):
