# Initialize a 3x3 game board with zeros
def setup_grid():
    return [[0 for _ in range(3)] for _ in range(3)]

# Display the current state of the board
def show_grid(grid):
    for line in grid:
        print(" ".join(["X" if cell == 1 else "O" if cell == 2 else "." for cell in line]))

# Check if a move is valid (cell is empty)
def is_valid_position(grid, row, col):
    return grid[row][col] == 0

# Place a player's mark on the board if the move is valid
def place_mark(grid, row, col, player):
    if is_valid_position(grid, row, col):
        grid[row][col] = player
        return True
    return False

# Check if the current player has won
def check_victory(grid, player):
    # Check rows, columns, and diagonals
    for i in range(3):
        if all(grid[i][j] == player for j in range(3)) or all(grid[j][i] == player for j in range(3)):
            return True
    if all(grid[i][i] == player for i in range(3)) or all(grid[i][2-i] == player for i in range(3)):
        return True
    return False

# Check if the board is completely filled
def is_grid_full(grid):
    return all(cell != 0 for line in grid for cell in line)

# Main game loop
def run_game():
    grid = setup_grid()
    active_player = 1

    while True:
        show_grid(grid)
        row = int(input(f"Player {active_player}, enter row (0-2): "))
        col = int(input(f"Player {active_player}, enter column (0-2): "))

        if place_mark(grid, row, col, active_player):
            if check_victory(grid, active_player):
                show_grid(grid)
                print(f"Player {active_player} wins!")
                break
            elif is_grid_full(grid):
                show_grid(grid)
                print("It's a draw!")
                break
            active_player = 3 - active_player  # Switch player (1 -> 2, 2 -> 1)
        else:
            print("Invalid move. Try again.")

run_game()

import threading
from typing import List, Tuple

class UAV:
    def __init__(self, identifier: int, start_location: Tuple[float, float, float] = (0, 0, 0)):
        self.identifier = identifier
        self.location = start_location
        self.velocity = 1.0  # Default speed in m/s
        self.height = start_location[2]
        self.is_airborne = False
        self.is_on_ground = True
        self.path_points = []
        self.current_path_index = 0
        self.mutex = threading.Lock()
        self.instrumentation = {
            'obstacle': False,
            'charge': 100.0  # Percentage
        }

    def ascend(self):
        with self.mutex:
            if not self.is_airborne:
                self.height = 10  # Ascend to 10 meters
                self.is_airborne = True
                self.is_on_ground = False
                print(f"UAV {self.identifier} ascended to {self.height} meters.")

    def fly_to(self, location: Tuple[float, float, float]):
        with self.mutex:
            if self.is_airborne:
                self.location = location
                self.height = location[2]
                print(f"UAV {self.identifier} flew to {self.location}.")

    def descend(self):
        with self.mutex:
            if self.is_airborne:
                self.height = 0
                self.is_airborne = False
                self.is_on_ground = True
                print(f"UAV {self.identifier} descended.")

    def assign_path(self, path_points: List[Tuple[float, float, float]]):
        with self.mutex:
            self.path_points = path_points
            self.current_path_index = 0
            print(f"UAV {self.identifier} path assigned to {self.path_points}.")

    def follow_path(self):
        with self.mutex:
            if self.is_airborne and self.current_path_index < len(self.path_points):
                next_point = self.path_points[self.current_path_index]
                self.fly_to(next_point)
                self.current_path_index += 1
                if self.current_path_index == len(self.path_points):
                    print(f"UAV {self.identifier} completed all path points.")
                else:
                    threading.Timer(1.0, self.follow_path).start()
            else:
                print(f"UAV {self.identifier} path following finished or not airborne.")

    def analyze_instrumentation(self):
        with self.mutex:
            if self.instrumentation['obstacle']:
                print(f"UAV {self.identifier} detected obstacle. Halting and descending.")
                self.descend()
            if self.instrumentation['charge'] < 20:
                print(f"UAV {self.identifier} charge low. Returning to base.")
                self.fly_to((0, 0, 10))
                self.descend()

    def update_sensor_info(self, sensor_info: dict):
        with self.mutex:
            self.instrumentation.update(sensor_info)
            self.analyze_instrumentation()

    def deliver(self, location: Tuple[float, float, float]):
        with self.mutex:
            if self.is_airborne:
                self.fly_to(location)
                print(f"UAV {self.identifier} delivered at {location}.")

    def collect(self, location: Tuple[float, float, float]):
        with self.mutex:
            if self.is_airborne:
                self.fly_to(location)
                print(f"UAV {self.identifier} collected from {location}.")

class UAVManagementSystem:
    def __init__(self):
        self.uavs = {}
        self.mutex = threading.Lock()

    def register_uav(self, uav: UAV):
        with self.mutex:
            self.uavs[uav.identifier] = uav
            print(f"UAV {uav.identifier} registered in the system.")

    def manage_uav(self, uav_id: int, action: str, *parameters, **options):
        with self.mutex:
            if uav_id in self.uavs:
                uav = self.uavs[uav_id]
                if action == 'ascend':
                    uav.ascend()
                elif action == 'fly_to':
                    uav.fly_to(*parameters)
                elif action == 'descend':
                    uav.descend()
                elif action == 'assign_path':
                    uav.assign_path(*parameters)
                elif action == 'follow_path':
                    uav.follow_path()
                elif action == 'update_sensor_info':
                    uav.update_sensor_info(*parameters)
                elif action == 'deliver':
                    uav.deliver(*parameters)
                elif action == 'collect':
                    uav.collect(*parameters)
                else:
                    print(f"Unknown action: {action}")
            else:
                print(f"UAV {uav_id} not found in the system.")

    def coordinate_multiple_uavs(self, actions: List[dict]):
        with self.mutex:
            for action in actions:
                uav_id = action.get('uav_id')
                action_str = action.get('action')
                params = action.get('params', [])
                options = action.get('options', {})
                self.manage_uav(uav_id, action_str, *params, **options)

# Example usage
if __name__ == "__main__":
    management_system = UAVManagementSystem()
    uav1 = UAV(1)
    uav2 = UAV(2)
    management_system.register_uav(uav1)
    management_system.register_uav(uav2)

    management_system.manage_uav(1, 'ascend')
    management_system.manage_uav(1, 'assign_path', [(15, 15, 10), (25, 25, 10)])
    management_system.manage_uav(1, 'follow_path')
    management_system.manage_uav(1, 'update_sensor_info', {'obstacle': False, 'charge': 60.0})
    management_system.manage_uav(1, 'deliver', (35, 35, 10))
    management_system.manage_uav(1, 'descend')

    management_system.coordinate_multiple_uavs([
        {'uav_id': 2, 'action': 'ascend'},
        {'uav_id': 2, 'action': 'fly_to', 'params': [(50, 50, 10)]},
        {'uav_id': 2, 'action': 'descend'}
    ])

