# Abstract base class for library books
from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class LibraryItem(ABC):
    def __init__(self, name, creator, publication_year, category):
        self.title = name
        self.author = creator
        self.year = publication_year
        self.item_type = category
        self.license_rights = "Not specified"
        self.checked_out = False
        self.return_by = None

    @abstractmethod
    def display_details(self):
        pass

