        if not self.checked_out:
            self.checked_out = True
            self.return_by = datetime.now() + timedelta(days=loan_period)
            print(f"{self.title} has been checked out and is due on {self.return_by}")
        else:
            print(f"{self.title} is already checked out.")

    def check_in(self):
        if self.checked_out:
            self.checked_out = False
            self.return_by = None
            print(f"{self.title} has been returned.")
        else:
            print(f"{self.title} is not currently checked out.")

    def overdue_check(self):
        if self.checked_out and self.return_by < datetime.now():
            print(f"{self.title} is overdue.")
        else:
            print(f"{self.title} is not overdue.")

