import urllib2
import time
import random

def fetch_url(url, max_attempts=5, delay_multiplier=2):
    result = None
    req = urllib2.Request(url=url)
    req.add_header('User-Agent', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3')
    for trial in range(max_attempts):
        try:
            result = urllib2.urlopen(req).read()
            break  # Exit loop on successful request
        except urllib2.HTTPError as exc:
            print "HTTPError: {} ({})".format(url, exc.code)
            if exc.code != 429:  # Stop retrying if not a rate limiting issue
                break
        except urllib2.URLError as exc:
            print "URLError: {} ({})".format(url, exc.reason)
        except Exception as exc:
            print "Unexpected error: {}".format(exc)
        if trial < max_attempts - 1:
            delay = delay_multiplier * (2 ** trial) + random.uniform(0, 1)
            print "Waiting for {:.2f} seconds before retry...".format(delay)
            time.sleep(delay)
    return result

