# Modified version of the original code with renamed variables and restructured logic
import numpy as np
import gym
import random
from collections import defaultdict

# Define the Connect 4 environment with modified structure
class Connect4Game(gym.Env):
    def __init__(self, height=6, width=7, streak=4):
        self.height = height
        self.width = width
        self.streak = streak
        self.grid = np.zeros((height, width), dtype=int)
        self.turn = 1
        self.game_over = False
        self.outcome = None
        self.valid_actions = list(range(width))

    def restart(self):
        self.grid = np.zeros((self.height, self.width), dtype=int)
        self.turn = 1
        self.game_over = False
        self.outcome = None
        self.valid_actions = list(range(self.width))
        return self.grid

    def execute_move(self, move):
        if move not in self.valid_actions:
            return self.grid, -10, True, {'result': -1}

        # Drop piece in the lowest available row
        for r in range(self.height - 1, -1, -1):
            if self.grid[r, move] == 0:
                self.grid[r, move] = self.turn
                break

        # Check win condition
        if self.has_won():
            self.game_over = True
            self.outcome = self.turn
            reward = 1
        elif len(self.valid_actions) == 0:
            self.game_over = True
            self.outcome = 0
            reward = 0
        else:
            reward = 0

        # Switch turns (1 -> 2, 2 -> 1)
        self.turn = 3 - self.turn
        self.valid_actions = [col for col in range(self.width) if self.grid[0, col] == 0]

        return self.grid, reward, self.game_over, {'result': self.outcome}

    def has_won(self):
        # Check all directions for winning streak
        for r in range(self.height):
            for c in range(self.width):
                if self.grid[r, c] != 0:
                    # Horizontal check
                    if c <= self.width - self.streak and np.all(self.grid[r, c:c + self.streak] == self.grid[r, c]):
                        return True
                    # Vertical check
                    if r <= self.height - self.streak and np.all(self.grid[r:r + self.streak, c] == self.grid[r, c]):
                        return True
                    # Diagonal (positive slope)
                    if r <= self.height - self.streak and c <= self.width - self.streak and np.all(self.grid[r:r + self.streak, c:c + self.streak].diagonal() == self.grid[r, c]):
                        return True
                    # Diagonal (negative slope)
                    if r <= self.height - self.streak and c >= self.streak - 1 and np.all(np.fliplr(self.grid[r:r + self.streak, c - self.streak + 1:c + 1]).diagonal() == self.grid[r, c]):
                        return True
        return False

    def display(self):
        print(self.grid)

# Q-Learning Agent with adjusted parameters and naming
class QAgent:
    def __init__(self, game, learning_rate=0.1, discount=0.9, exploration=0.1):
        self.game = game
        self.learning_rate = learning_rate
        self.discount = discount
        self.exploration = exploration
        self.q_values = defaultdict(lambda: np.zeros(game.action_space.n))

    def select_action(self, current_state):
        if random.uniform(0, 1) < self.exploration:
            return random.choice(self.game.valid_actions)
        else:
            q_vals = self.q_values[current_state.tobytes()]
            return np.argmax(q_vals)

    def update(self, prev_state, move, reward, new_state):
        optimal_next_move = np.argmax(self.q_values[new_state.tobytes()])
        target = reward + self.discount * self.q_values[new_state.tobytes()][optimal_next_move]
        error = target - self.q_values[prev_state.tobytes()][move]
        self.q_values[prev_state.tobytes()][move] += self.learning_rate * error

    def fit(self, iterations):
        for ep in range(iterations):
            state = self.game.restart()
            finished = False
            while not finished:
                action = self.select_action(state)
                next_state, reward, finished, info = self.game.execute_move(action)
                self.update(state, action, reward, next_state)
                state = next_state
            if (ep + 1) % 100 == 0:
                print(f"Training iteration {ep + 1}/{iterations} done")

    def demo(self):
        state = self.game.restart()
        finished = False
        while not finished:
            action = self.select_action(state)
            state, reward, finished, info = self.game.execute_move(action)
            self.game.display()
            if finished:
                if info['result'] == 1:
                    print("First player wins!")
                elif info['result'] == 2:
                    print("Second player wins!")
                else:
                    print("Draw!")
                break

# Setup and execution
