# Vehicle class definition with various car-related calculations
class Automobile:
    def __init__(self, manufacturer, variant, production_year, paint_color, top_velocity, cylinder_capacity):
        self.manufacturer = manufacturer
        self.variant = variant
        self.production_year = production_year
        self.paint_color = paint_color
        self.top_velocity = top_velocity
        self.cylinder_capacity = cylinder_capacity
        self.economy_kpl = 0.0  # kilometers per liter
        self.fuel_quantity = 0.0  # liters
        self.mileage = 0.0  # kilometers
        self.cumulative_distance = 0.0  # kilometers

    def compute_economy(self, distance_covered, fuel_used):
        if fuel_used > 0:
            self.economy_kpl = distance_covered / fuel_used
        else:
            self.economy_kpl = 0.0

    def estimate_travel_duration(self, distance):
        if self.top_velocity > 0:
            return distance / self.top_velocity
        else:
            return float('inf')  # Infinite time if top velocity is 0

    def compute_mean_speed(self, distance, duration):
        if duration > 0:
            return distance / duration
        else:
            return 0.0

    def verify_fuel_availability(self, distance):
        if self.economy_kpl > 0:
            needed_fuel = distance / self.economy_kpl
            return self.fuel_quantity >= needed_fuel
        else:
            return False

    def adjust_mileage(self, distance):
        self.mileage += distance
        self.cumulative_distance += distance

    def compute_fuel_usage(self, distance):
        if self.economy_kpl > 0:
            return distance / self.economy_kpl
        else:
            return float('inf')  # Infinite usage if economy is 0

    def compute_fuel_usage_l_per_100km(self):
        if self.economy_kpl > 0:
            return 100 / self.economy_kpl
        else:
            return float('inf')  # Infinite usage if economy is 0

    def compute_energy_efficiency_l_kWh(self, distance):
        if self.cylinder_capacity > 0 and distance > 0:
            # Assuming a constant power output for simplicity
            power_output = self.cylinder_capacity * 0.001  # kW (simplified conversion)
            energy_consumed = distance * self.compute_fuel_usage(distance)  # liters
            return energy_consumed / (distance * power_output)
        else:
            return float('inf')  # Infinite efficiency if capacity or distance is 0

