# Custom exception classes for discount calculation errors
class DiscountCalculationException(Exception):
    """Base class for all discount calculation exceptions."""
    pass

class PriceNotValidError(DiscountCalculationException):
    """Raised when the price is not a non-negative number."""
    def __init__(self, price_value):
        self.price_value = price_value
        super().__init__(f"Price is invalid: {price_value}. Please provide a non-negative numeric value.")

class CouponNotValidError(DiscountCalculationException):
    """Raised when the cash coupon is not a non-negative number."""
    def __init__(self, coupon_value):
        self.coupon_value = coupon_value
        super().__init__(f"Cash coupon is invalid: {coupon_value}. Must be a non-negative number.")

class PercentCouponNotValidError(DiscountCalculationException):
    """Raised when the percentage coupon is out of valid range."""
    def __init__(self, percent_value):
        self.percent_value = percent_value
        super().__init__(f"Percentage coupon is invalid: {percent_value}. Must be between 0 and 100 inclusive.")

class PriceAdjuster:
    def __init__(self, original_price, flat_coupon, rate_coupon):
        self.check_arguments(original_price, flat_coupon, rate_coupon)
        self.original_price = original_price
        self.flat_coupon = flat_coupon
        self.rate_coupon = rate_coupon

    def check_arguments(self, original_price, flat_coupon, rate_coupon):
        try:
            original_price = float(original_price)
            flat_coupon = float(flat_coupon)
            rate_coupon = float(rate_coupon)
        except (TypeError, ValueError):
            raise TypeError("All input values must be convertible to numbers.")

        if original_price < 0:
            raise PriceNotValidError(original_price)
        if flat_coupon < 0:
            raise CouponNotValidError(flat_coupon)
        if not (0 <= rate_coupon <= 100):
            raise PercentCouponNotValidError(rate_coupon)

    def compute_adjusted_price(self):
        intermediate_price = max(0.0, self.original_price - self.flat_coupon)
        final_price = intermediate_price * (100 - self.rate_coupon) / 100.0
        return final_price

