# Modified version of advanced_median function with Type I clone techniques applied
def modified_median(data: list, comparison_func: callable):
    """
    Compute median of elements in the list data without full sorting,
    supporting mixed datatypes via custom comparison function.
    Manages tuples of varying lengths, duplicate values, and relies on comparison_func for ordering.
    """
    def split_partition(sequence, start, end):
        pivot_val = sequence[end]
        left_ptr = start - 1
        for mid_idx in range(start, end):
            if comparison_func(sequence[mid_idx], pivot_val) < 0:
                left_ptr += 1
                sequence[left_ptr], sequence[mid_idx] = sequence[mid_idx], sequence[left_ptr]
        sequence[left_ptr + 1], sequence[end] = sequence[end], sequence[left_ptr + 1]
        return left_ptr + 1

    def find_kth_element(sequence, target_index, begin, finish):
        if begin == finish:
            return sequence[begin]

        partition_idx = split_partition(sequence, begin, finish)

        if target_index == partition_idx:
            return sequence[target_index]
        elif target_index < partition_idx:
            return find_kth_element(sequence, target_index, begin, partition_idx - 1)
        else:
            return find_kth_element(sequence, target_index, partition_idx + 1, finish)

    def check_compatibility(val1, val2):
        try:
            comparison_func(val1, val2)
            return True
        except TypeError:
            return False

    # Remove elements that cannot be compared consistently
    valid_items = [item for idx, item in enumerate(data) if all(check_compatibility(item, other) for other in data if idx != data.index(other))]

    if not valid_items:
        return None

    count = len(valid_items)
    if count % 2 == 1:
        return find_kth_element(valid_items, count // 2, 0, count - 1)
    else:
        lower_mid = find_kth_element(valid_items, count // 2 - 1, 0, count - 1)
        upper_mid = find_kth_element(valid_items, count // 2, 0, count - 1)
        return (lower_mid + upper_mid) / 2

# Demonstration examples
print(modified_median([3, 1, 2, 4, 5], lambda x, y: x - y))  # => 3
print(modified_median([-10, 4, 6, 1000, 10, 20], lambda x, y: x - y))  # => 15.0
print(modified_median([1, 2, 2, 4, 5], lambda x, y: x - y))  # => 2
print(modified_median(['a', 'b', 1, 2], lambda x, y: x - y))  # => None

# Calculate median without sorting or using built-in functions
def find_median(values: list):
    """Compute the median of a list of numbers without sorting it or using built-in functions.
    Works with lists containing negative numbers.
    >>> find_median([3, 1, 2, 4, 5])
    3
    >>> find_median([-10, 4, 6, 1000, 10, 20])
    15.0
    >>> find_median([-5, -1, -3, -4, -2])
    -3
    >>> find_median([1, 2, 3, 4, 5, 6])
    3.5
    """
    def split_array(arr, start, end):
        pivot_val = arr[end]
        left_pos = start - 1
        for right_pos in range(start, end):
            if arr[right_pos] <= pivot_val:
                left_pos += 1
                arr[left_pos], arr[right_pos] = arr[right_pos], arr[left_pos]
        arr[left_pos + 1], arr[end] = arr[end], arr[left_pos + 1]
        return left_pos + 1

    def find_kth_element(arr, k, start, end):
        if start == end:
            return arr[start]
        pivot_position = split_array(arr, start, end)
        if k == pivot_position:
            return arr[k]
        elif k < pivot_position:
            return find_kth_element(arr, k, start, pivot_position - 1)
        else:
            return find_kth_element(arr, k, pivot_position + 1, end)

    count = len(values)
    if count % 2 == 1:
        return find_kth_element(values, count // 2, 0, count - 1)
    else:
        return 0.5 * (find_kth_element(values, count // 2 - 1, 0, count - 1) + find_kth_element(values, count // 2, 0, count - 1))

