# 1. Display the count of related terms for each term in the collection.
def display_term_counts(word_collection):
    for term, related_terms in word_collection.items():
        print(f"{term} has {len(related_terms)} related terms.")

# 2. Present all related terms for each term.
def present_related_terms(word_collection):
    for term, related_terms in word_collection.items():
        print(f"{term}: {', '.join(related_terms)}")

# 3. Identify and show terms that have at least one related term in common.
def identify_common_terms(word_collection):
    common_terms = {}
    for term1, related1 in word_collection.items():
        for term2, related2 in word_collection.items():
            if term1 != term2 and set(related1) & set(related2):
                common_terms.setdefault(term1, []).append(term2)

    for term, shared_terms in common_terms.items():
        print(f"{term} shares related terms with: {', '.join(shared_terms)}")

# 4. Locate and present a 'related term chain' from a given starting term to a target term.
def locate_related_chain(word_collection, origin_term, destination_term):
    # Build a graph from the word collection
    network = {}
    for term, related in word_collection.items():
        network[term] = set(related)
        for related_term in related:
            if related_term not in network:
                network[related_term] = set()
            network[related_term].add(term)

    # BFS to find the chain
    from collections import deque
    queue = deque([(origin_term, [origin_term])])
    explored = set([origin_term])

    while queue:
        current_term, route = queue.popleft()
        if current_term == destination_term:
            return route
        for adjacent in network.get(current_term, []):
            if adjacent not in explored:
                explored.add(adjacent)
                queue.append((adjacent, route + [adjacent]))

    return None

