# Web scraper to find and rank URLs containing a specific keyword
import requests
from bs4 import BeautifulSoup
from collections import Counter
import re

def get_page_content(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.RequestException as error:
        print(f"Failed to retrieve webpage: {error}")
        return None

def gather_links(html, target_word, blacklist_term):
    parsed_html = BeautifulSoup(html, 'html.parser')
    links = []
    for anchor in parsed_html.find_all('a', href=True):
        link_url = anchor['href']
        if target_word in link_url and blacklist_term not in link_url:
            links.append(link_url)
    return links

def tally_keyword_matches(links, search_term):
    frequency_counter = Counter()
    for link in links:
        matches = len(re.findall(re.escape(search_term), link, re.IGNORECASE))
        if matches > 0:
            frequency_counter[link] = matches
    return frequency_counter

def refine_and_rank_links(link_frequencies, threshold):
    selected_links = {link: freq for link, freq in link_frequencies.items() if freq > threshold}
    ranked_links = sorted(selected_links.items(), key=lambda item: item[1], reverse=True)
    return ranked_links

def run_analysis():
    base_url = 'http://www.example.com'
    search_keyword = 'innovation'
    exclusion_filter = 'promo'
    minimum_count = 3

    page_source = get_page_content(base_url)
    if page_source:
        found_links = gather_links(page_source, search_keyword, exclusion_filter)
        keyword_stats = tally_keyword_matches(found_links, search_keyword)
        final_ranking = refine_and_sort_links(keyword_stats, minimum_count)

        for link, occurrences in final_ranking:
            print(f"Link: {link}, Matches: {occurrences}")

if __name__ == "__main__":
    run_analysis()

