# Flask application setup with SQLAlchemy and Marshmallow for item management
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_marshmallow import Marshmallow

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///products.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db = SQLAlchemy(app)
ma = Marshmallow(app)

class Product(db.Model):
    product_id = db.Column(db.Integer, primary_key=True)
    product_name = db.Column(db.String(100), unique=True, nullable=False)
    product_description = db.Column(db.String(200))

    def __init__(self, product_name, product_description):
        self.product_name = product_name
        self.product_description = product_description

class ProductSchema(ma.Schema):
    class Meta:
        fields = ('product_id', 'product_name', 'product_description')

product_schema = ProductSchema()
products_schema = ProductSchema(many=True)

@app.route('/products', methods=['POST'])
def add_product():
    name = request.json['product_name']
    description = request.json['product_description']
    new_product = Product(name, description)
    db.session.add(new_product)
    db.session.commit()
    return product_schema.jsonify(new_product), 201

@app.route('/products', methods=['GET'])
def get_products():
    all_products = Product.query.all()
    result = products_schema.dump(all_products)
    return jsonify(result)

@app.route('/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({'message': 'Product not found'}), 404
    return product_schema.jsonify(product)

@app.route('/products/<int:product_id>', methods=['PUT'])
def update_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({'message': 'Product not found'}), 404
    name = request.json['product_name']
    description = request.json['product_description']
    product.product_name = name
    product.product_description = description
    db.session.commit()
    return product_schema.jsonify(product)

@app.route('/products/<int:product_id>', methods=['DELETE'])
def delete_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({'message': 'Product not found'}), 404
    db.session.delete(product)
    db.session.commit()
    return product_schema.jsonify(product)

if __name__ == '__main__':
