    app.run(debug=True)

# Triangle class implementation with validation and utility methods
import math
from contextlib import contextmanager

class Triangle:
    count = 0  # Class variable to track number of Triangle instances created

    def __init__(self, a, b, c):
        if not self._check_validity(a, b, c):
            raise ValueError("Invalid triangle sides provided")
        self.a = a
        self.b = b
        self.c = c
        Triangle.count += 1

    def _check_validity(self, x, y, z):
        return x > 0 and y > 0 and z > 0 and \
               x + y > z and x + z > y and y + z > x

    def perimeter(self):
        return self.a + self.b + self.c

    def area(self):
        return self._compute_area(self.a, self.b, self.c)

    def _compute_area(self, side_a, side_b, side_c, level=0):
        if level > 100:  # Safety check against excessive recursion
            raise RecursionError("Maximum recursion depth reached")
        semi_perimeter = (side_a + side_b + side_c) / 2
        if semi_perimeter - side_a <= 0 or semi_perimeter - side_b <= 0 or semi_perimeter - side_c <= 0:
            return 0.0
        calculated_area = math.sqrt(semi_perimeter * 
                                   (semi_perimeter - side_a) * 
                                   (semi_perimeter - side_b) * 
                                   (semi_perimeter - side_c))
        return calculated_area

    @property
    def equilateral_check(self):
        return self.a == self.b == self.c

    @property
    def isosceles_check(self):
        return self.a == self.b or self.a == self.c or self.b == self.c

    @contextmanager
    def modify_dimensions(self, new_a, new_b, new_c):
        if not self._check_validity(new_a, new_b, new_c):
            print("Modification failed: New dimensions do not form a valid triangle")
            yield False
        else:
            previous_sides = (self.a, self.b, self.c)
            self.a, self.b, self.c = new_a, new_b, new_c
            yield True
            self.a, self.b, self.c = previous_sides

# Demonstration usage:
try:
    triangle1 = Triangle(3, 4, 5)
    print(f"Perimeter: {triangle1.perimeter()}")
    print(f"Area: {triangle1.area()}")
    print(f"Equilateral? {triangle1.equilateral_check}")
    print(f"Isosceles? {triangle1.isosceles_check}")

    with triangle1.modify_dimensions(5, 5, 5) as modified:
        if modified:
            print(f"Successfully resized to equilateral: {triangle1.equilateral_check}")
        else:
            print("Resize operation unsuccessful")

    print(f"Current side lengths: {triangle1.a}, {triangle1.b}, {triangle1.c}")

    with triangle1.modify_dimensions(1, 2, 3) as modified:
        if modified:
            print(f"Resized to: {triangle1.a}, {triangle1.b}, {triangle1.c}")
        else:
            print("Resize operation unsuccessful")

    print(f"Current side lengths: {triangle1.a}, {triangle1.b}, {triangle1.c}")
except ValueError as error_message:
    print(error_message)

