# Implementation of First-Come-First-Serve (FCFS) scheduling algorithm
class Task:
    def __init__(self, task_id, arrival, duration):
        self.task_id = task_id
        self.arrival = arrival
        self.duration = duration
        self.remaining = duration
        self.start = None
        self.finish = None

    def __str__(self):
        return f"Task({self.task_id}, arrival={self.arrival}, duration={self.duration})"

class FCFS_Algorithm:
    def __init__(self):
        self.tasks = []

    def add_task(self, task):
        self.tasks.append(task)

    def execute(self):
        # Order tasks by their arrival times
        self.tasks.sort(key=lambda t: t.arrival)

        current_time = 0
        for task in self.tasks:
            if task.arrival > current_time:
                current_time = task.arrival
            task.start = current_time
            current_time += task.duration
            task.finish = current_time

    def display_schedule(self):
        schedule = []
        for task in self.tasks:
            schedule.append((task.start, task.finish, task.task_id))
        return schedule

    def compute_avg_wait_time(self):
        total_wait = 0
        for task in self.tasks:
            if task.start is not None:
                total_wait += task.start - task.arrival
        return total_wait / len(self.tasks)

    def compute_avg_turnaround_time(self):
        total_turnaround = 0
        for task in self.tasks:
            if task.finish is not None:
                total_turnaround += task.finish - task.arrival
        return total_turnaround / len(self.tasks)

# Demonstration
if __name__ == "__main__":
    scheduler = FCFS_Algorithm()

    # Insert tasks
    scheduler.add_task(Task(1, 0, 24))
    scheduler.add_task(Task(2, 4, 3))
    scheduler.add_task(Task(3, 5, 3))

    # Run the scheduling
    scheduler.execute()

    # Show results
    schedule = scheduler.display_schedule()
    print("Execution Timeline:")
    for start, end, tid in schedule:
        print(f"Task {tid} runs from {start} to {end}")

    print(f"Mean Waiting Time: {scheduler.compute_avg_wait_time():.2f}")
    print(f"Mean Turnaround Time: {scheduler.compute_avg_turnaround_time():.2f}")

