# Spotify API integration script for song classification
import requests
import json

# Spotify API authentication details
client_identifier = 'YOUR_CLIENT_ID'
client_secret_key = 'YOUR_CLIENT_SECRET'

# Retrieve OAuth access token using client credentials flow
def fetch_access_token(client_id, client_secret):
    auth_url = 'https://accounts.spotify.com/api/token'
    request_headers = {
        'Content-Type': 'application/x-www-form-urlencoded'
    }
    payload = {
        'grant_type': 'client_credentials',
        'client_id': client_id,
        'client_secret': client_secret
    }
    api_response = requests.post(auth_url, headers=request_headers, data=payload)
    if api_response.status_code == 200:
        return api_response.json()['access_token']
    else:
        raise Exception('Failed to obtain access token: {}'.format(api_response.text))

# Search for a track on Spotify
def find_track(access_token, track_title, performer_name):
    search_endpoint = 'https://api.spotify.com/v1/search'
    authorization_headers = {
        'Authorization': 'Bearer {}'.format(access_token)
    }
    query_params = {
        'q': 'track:{} artist:{}'.format(track_title, performer_name),
        'type': 'track',
        'limit': 1
    }
    api_response = requests.get(search_endpoint, headers=authorization_headers, params=query_params)
    if api_response.status_code == 200:
        return api_response.json()
    else:
        raise Exception('Track search failed: {}'.format(api_response.text))

# Fetch audio features for a specific track
def retrieve_audio_characteristics(access_token, track_identifier):
    features_url = 'https://api.spotify.com/v1/audio-features/{}'.format(track_identifier)
    bearer_headers = {
        'Authorization': 'Bearer {}'.format(access_token)
    }
    api_response = requests.get(features_url, headers=bearer_headers)
    if api_response.status_code == 200:
        return api_response.json()
    else:
        raise Exception('Audio features retrieval failed: {}'.format(api_response.text))

# Determine music genre using audio feature heuristics
def determine_genre(audio_characteristics):
    # Heuristic classification based on common genre characteristics
    if audio_characteristics['energy'] > 0.8 and audio_characteristics['loudness'] > -6.0:
        return 'rock'
    elif audio_characteristics['acousticness'] > 0.5 and audio_characteristics['instrumentalness'] > 0.5:
        return 'country'
    elif audio_characteristics['speechiness'] > 0.3 and audio_characteristics['tempo'] > 100:
        return 'hip-hop'
    else:
        return 'pop'

# Main execution function
def execute():
    # Obtain authentication token
    token = fetch_access_token(client_identifier, client_secret_key)

    # Define search parameters
    track_title = 'Lose You to Love Me'
    performer_name = 'Selena Gomez'
    search_response = find_track(token, track_title, performer_name)

    # Extract track identifier from search results
    track_identifier = search_response['tracks']['items'][0]['id']

    # Retrieve audio features
    audio_characteristics = retrieve_audio_characteristics(token, track_identifier)

    # Classify the track
    music_genre = determine_genre(audio_characteristics)

    print(f"The track '{track_title}' by {performer_name} is categorized as: {music_genre}")
    print("Audio Characteristics:", json.dumps(audio_characteristics, indent=2))

if __name__ == "__main__":
