# Modified Fibonacci Heap implementation with renamed variables and reordered logic
class FibNode:
    def __init__(self, value):
        self.value = value
        self.parent_node = None
        self.children_list = None
        self.prev_sibling = self
        self.next_sibling = self
        self.rank = 0
        self.cut_flag = False

class FibHeap:
    def __init__(self):
        self.minimum = None
        self.node_count = 0
        self.maximum = None

    def add(self, value):
        new_node = FibNode(value)
        if self.minimum is None:
            self.minimum = new_node
        else:
            self._attach(new_node, self.minimum)
            if new_node.value < self.minimum.value:
                self.minimum = new_node
        self.node_count += 1

    def _attach(self, node_a, node_b):
        # Connect node_a as child of node_b
        node_a.prev_sibling.next_sibling = node_a.next_sibling
        node_a.next_sibling.prev_sibling = node_a.prev_sibling
        node_a.parent_node = node_b
        if node_b.children_list is None:
            node_b.children_list = node_a
        else:
            node_a.next_sibling = node_b.children_list
            node_a.prev_sibling = node_b.children_list.prev_sibling
            node_b.children_list.prev_sibling.next_sibling = node_a
            node_b.children_list.prev_sibling = node_a
        node_b.rank += 1
        node_a.cut_flag = False

    def remove_min(self):
        min_node = self.minimum
        if min_node is not None:
            if min_node.children_list is not None:
                # Move all children to root list
                current_child = min_node.children_list
                while True:
                    next_child = current_child.next_sibling
                    current_child.prev_sibling.next_sibling = current_child.next_sibling
                    current_child.next_sibling.prev_sibling = current_child.prev_sibling
                    self._attach(current_child, self.minimum)
                    if next_child == min_node.children_list:
                        break
                    current_child = next_child
            min_node.prev_sibling.next_sibling = min_node.next_sibling
            min_node.next_sibling.prev_sibling = min_node.prev_sibling
            if min_node == min_node.next_sibling:
                self.minimum = None
            else:
                self.minimum = min_node.next_sibling
                self._rebalance()
            self.node_count -= 1
        if min_node == self.maximum:
            self.maximum = self._search_max()
        return min_node.value

    def _rebalance(self):
        degree_table = [None] * (self.node_count.bit_length() + 1)
        start = self.minimum
        if start is not None:
            nodes_list = []
            while True:
                nodes_list.append(start)
                start = start.next_sibling
                if start == self.minimum:
                    break
            for start in nodes_list:
                current = start
                d = current.rank
                while degree_table[d] is not None:
                    other = degree_table[d]
                    if current.value < other.value:
                        current, other = other, current
                    self._attach(other, current)
                    degree_table[d] = None
                    d += 1
                degree_table[d] = current
            self.minimum = None
            for i in range(len(degree_table)):
                if degree_table[i] is not None:
                    if self.minimum is None:
                        self.minimum = degree_table[i]
                    else:
                        self._attach(degree_table[i], self.minimum)
                        if degree_table[i].value < self.minimum.value:
                            self.minimum = degree_table[i]

    def update_key(self, target_node, new_value):
        if new_value > target_node.value:
            raise ValueError("new value is greater than current value")
        target_node.value = new_value
        parent = target_node.parent_node
        if parent is not None and target_node.value < parent.value:
            self._separate(target_node, parent)
            self._propagate_cut(parent)
        if target_node.value < self.minimum.value:
            self.minimum = target_node

    def _separate(self, node, parent):
        node.prev_sibling.next_sibling = node.next_sibling
        node.next_sibling.prev_sibling = node.prev_sibling
        parent.rank -= 1
        if parent.children_list == node:
            parent.children_list = node.next_sibling
        node.prev_sibling = node.next_sibling = node
        self._attach(node, self.minimum)
        node.parent_node = None
        node.cut_flag = False

    def _propagate_cut(self, node):
        parent = node.parent_node
        if parent is not None:
            if not node.cut_flag:
                node.cut_flag = True
            else:
                self._separate(node, parent)
                self._propagate_cut(parent)

    def remove_node(self, node):
        self.update_key(node, float('-inf'))
        self.remove_min()

    def get_min(self):
        return self.minimum.value if self.minimum is not None else None

    def _search_max(self):
        max_node = None
        if self.minimum is not None:
            max_node = self.minimum
            current = self.minimum.next_sibling
            while current != self.minimum:
                if current.value > max_node.value:
                    max_node = current
                current = current.next_sibling
        return max_node

    def get_max(self):
        if self.maximum is None:
            self.maximum = self._search_max()
        return self.maximum.value if self.maximum is not None else None

    def increase_value(self, target_node, new_value):
        if new_value < target_node.value:
            raise ValueError("new value is less than current value")
        target_node.value = new_value
        if target_node == self.minimum:
            self.minimum = self._search_min()
        if target_node == self.maximum:
            self.maximum = self._search_max()

    def combine(self, other_heap):
        if self.minimum is None:
            self.minimum = other_heap.minimum
        elif other_heap.minimum is not None:
            self.minimum.next_sibling.prev_sibling = other_heap.minimum.prev_sibling
            other_heap.minimum.prev_sibling.next_sibling = self.minimum.next_sibling
            self.minimum.next_sibling = other_heap.minimum
            other_heap.minimum.prev_sibling = self.minimum
            if other_heap.minimum.value < self.minimum.value:
                self.minimum = other_heap.minimum
        self.node_count += other_heap.node_count
        self.maximum = self._search_max()

    def remove_max(self):
        if self.maximum is not None:
            max_value = self.maximum.value
            self.update_key(self.maximum, float('-inf'))
            self.remove_min()
            return max_value
        return None

    def _search_min(self):
        min_node = None
        if self.minimum is not None:
            min_node = self.minimum
            current = self.minimum.next_sibling
            while current != self.minimum:
                if current.value < min_node.value:
                    min_node = current
                current = current.next_sibling
        return min_node

# Convert RGB to HSV color space
def convert_rgb_to_hsv(red, green, blue):
    if not (0 <= red <= 255 and 0 <= green <= 255 and 0 <= blue <= 255):
        raise ValueError("RGB values must be in the range 0-255")

    # Normalize RGB values to [0, 1]
    red_norm, green_norm, blue_norm = red / 255.0, green / 255.0, blue / 255.0
    max_component = max(red_norm, green_norm, blue_norm)
    min_component = min(red_norm, green_norm, blue_norm)
    delta = max_component - min_component

    # Calculate hue
    if max_component == min_component:
        hue = 0
    elif max_component == red_norm:
        hue = (60 * ((green_norm - blue_norm) / delta) + 360) % 360
    elif max_component == green_norm:
        hue = (60 * ((blue_norm - red_norm) / delta) + 120) % 360
    elif max_component == blue_norm:
        hue = (60 * ((red_norm - green_norm) / delta) + 240) % 360

    # Calculate saturation
    if max_component == 0:
        saturation = 0
    else:
        saturation = (delta / max_component) * 100

    # Calculate value
    brightness = max_component * 100
    return hue, saturation, brightness

# Convert HSV to RGB color space
def convert_hsv_to_rgb(hue, saturation, brightness):
    if not (0 <= hue <= 360 and 0 <= saturation <= 100 and 0 <= brightness <= 100):
        raise ValueError("HSV values must be in the range 0-360 for H and 0-100 for S and V")

    # Normalize saturation and brightness to [0, 1]
    saturation_norm, brightness_norm = saturation / 100.0, brightness / 100.0
    chroma = brightness_norm * saturation_norm
    x_val = chroma * (1 - abs((hue / 60) % 2 - 1))
    m_val = brightness_norm - chroma

    # Calculate RGB components based on hue sector
    if 0 <= hue < 60:
        red_norm, green_norm, blue_norm = chroma, x_val, 0
    elif 60 <= hue < 120:
        red_norm, green_norm, blue_norm = x_val, chroma, 0
    elif 120 <= hue < 180:
        red_norm, green_norm, blue_norm = 0, chroma, x_val
    elif 180 <= hue < 240:
        red_norm, green_norm, blue_norm = 0, x_val, chroma
    elif 240 <= hue < 300:
        red_norm, green_norm, blue_norm = x_val, 0, chroma
    else:
        red_norm, green_norm, blue_norm = chroma, 0, x_val

    # Convert back to [0, 255] range and round to integers
    red_final = int(round((red_norm + m_val) * 255))
    green_final = int(round((green_norm + m_val) * 255))
    blue_final = int(round((blue_norm + m_val) * 255))
    return red_final, green_final, blue_final

# Compute the circuit output based on bitwise operations
def execute_command(cmd, registers):
    parts = cmd.split()
    if 'AND' in parts:
        operand1, _, operand2, _, target = parts
        if operand1.isdigit() and operand2 in registers:
            registers[target] = int(operand1) & registers[operand2]
        elif operand1 in registers and operand2 in registers:
            registers[target] = registers[operand1] & registers[operand2]
    elif 'OR' in parts:
        operand1, _, operand2, _, target = parts
        if operand1 in registers and operand2 in registers:
            registers[target] = registers[operand1] | registers[operand2]
    elif 'LSHIFT' in parts:
        source, _, shift_val, _, target = parts
        if source in registers:
            registers[target] = registers[source] << int(shift_val)
    elif 'RSHIFT' in parts:
        source, _, shift_val, _, target = parts
        if source in registers:
            registers[target] = registers[source] >> int(shift_val)
    elif 'NOT' in parts:
        _, source, _, target = parts
        if source in registers:
            registers[target] = ~registers[source] & 0xFFFF
    else:
        source, _, target = parts
        if source.isdigit():
            registers[target] = int(source)
        elif source in registers:
            registers[target] = registers[source]

def run_circuit(commands):
    registers = {}
    while commands:
        command = commands.pop(0)
        execute_command(command, registers)
        # Check if any part of the command depends on undefined registers
        if not set(command.split()) & set(registers.keys()) == set(command.split()):
            commands.append(command)
    return registers['a']

commands_list = [
    '123 -> x',
    '456 -> y',
    'x AND y -> d',
    'x OR y -> e',
    'x LSHIFT 2 -> f',
    'y RSHIFT 2 -> g',
    'NOT x -> h',
    'NOT y -> i'
]
result_signal = run_circuit(commands_list)
print(f"Resulting signal on wire a: {result_signal}")

# Module for customer data validation and management
import re
from typing import List

class Client:
    def __init__(self, full_name: str, contact_email: str, mobile: str):
        self._full_name = None
        self._contact_email = None
        self._mobile = None
        self.assign_name(full_name)
        self.assign_email(contact_email)
        self.assign_mobile(mobile)

    def retrieve_name(self) -> str:
        return self._full_name

    def assign_name(self, full_name: str):
        if not full_name.isalpha():
            raise ValueError("Name should only contain alphabetical characters.")
        self._full_name = full_name

    def retrieve_email(self) -> str:
        return self._contact_email

    def assign_email(self, contact_email: str):
        if not re.match(r"[^@]+@[^@]+\.[^@]+", contact_email):
            raise ValueError("Invalid email address format.")
        self._contact_email = contact_email

    def retrieve_mobile(self) -> str:
        return self._mobile

    def assign_mobile(self, mobile: str):
        if not re.match(r"^\+?\d{10,15}$", mobile):
            raise ValueError("Invalid phone number format.")
        self._mobile = mobile

    def show_details(self):
        print(f"Name: {self._full_name}")
        print(f"Email: {self._contact_email}")
        print(f"Phone: {self._mobile}")

    @staticmethod
    def arrange_clients(clients: List['Client']) -> List['Client']:
        return sorted(clients, key=lambda client: client.retrieve_name())

    @staticmethod
    def select_by_provider(clients: List['Client'], provider: str) -> List['Client']:
        return [client for client in clients if client.retrieve_email().endswith(f"@{provider}")]

