class RadioShowSegment:
    def __init__(self, segment_id, name, summary, length, air_date):
        self.segment_id = segment_id
        self.name = name
        self.summary = summary
        self.length = length
        self.air_date = air_date

# Define a class to manage a collection of radio show segments
class RadioCollection:
    def __init__(self):
        self.segments = {}
        self.next_segment_id = 1

    def add_segment(self, name, summary, length, air_date):
        segment_id = self.next_segment_id
        new_segment = RadioShowSegment(segment_id, name, summary, length, air_date)
        self.segments[segment_id] = new_segment
        self.next_segment_id += 1
        return segment_id

    def modify_segment(self, segment_id, name=None, summary=None, length=None, air_date=None):
        if segment_id not in self.segments:
            raise KeyError(f"Segment with ID {segment_id} is not found.")

        segment = self.segments[segment_id]
        if name is not None:
            segment.name = name
        if summary is not None:
            segment.summary = summary
        if length is not None:
            segment.length = length
        if air_date is not None:
            segment.air_date = air_date

    def remove_segment(self, segment_id):
        if segment_id not in self.segments:
            raise KeyError(f"Segment with ID {segment_id} is not found.")

        del self.segments[segment_id]

    def retrieve_segment(self, segment_id):
        if segment_id not in self.segments:
            raise KeyError(f"Segment with ID {segment_id} is not found.")

        return self.segments[segment_id]

    def get_all_segments(self):
        return list(self.segments.values())

