# Calculate total area and perimeter for various shapes
import math
from abc import ABC, abstractmethod

class GeometryObject(ABC):
    @abstractmethod
    def surface_area(self):
        pass

    @abstractmethod
    def boundary_length(self):
        pass

    def is_equal(self, other_obj):
        if not isinstance(other_obj, self.__class__):
            return False
        return self.surface_area() == other_obj.surface_area() and self.boundary_length() == other_obj.boundary_length()

    @abstractmethod
    def separation_distance(self, other_obj):
        pass

    @abstractmethod
    def spin(self, degrees):
        pass

    @abstractmethod
    def enclosing_box(self):
        pass

class Coordinate:
    def __init__(self, horizontal, vertical):
        self.horizontal = horizontal
        self.vertical = vertical

    def separation_distance(self, other_coord):
        if not isinstance(other_coord, Coordinate):
            raise ValueError("Other must be a Coordinate")
        return math.sqrt((self.horizontal - other_coord.horizontal) ** 2 + (self.vertical - other_coord.vertical) ** 2)

class Box(GeometryObject):
    def __init__(self, length, breadth, midpoint=Coordinate(0, 0)):
        if length <= 0 or breadth <= 0:
            raise ValueError("Length and breadth must be positive")
        self.length = length
        self.breadth = breadth
        self.midpoint = midpoint

    def surface_area(self):
        return self.length * self.breadth

    def boundary_length(self):
        return 2 * (self.length + self.breadth)

    def separation_distance(self, other_obj):
        if not isinstance(other_obj, GeometryObject):
            raise ValueError("Other must be a GeometryObject")
        return self.midpoint.separation_distance(other_obj.midpoint)

    def spin(self, degrees):
        # For a box, rotation does not change its surface area or boundary length
        pass

    def enclosing_box(self):
        return self

class Disk(GeometryObject):
    def __init__(self, radius, midpoint=Coordinate(0, 0)):
        if radius <= 0:
            raise ValueError("Radius must be positive")
        self.radius = radius
        self.midpoint = midpoint

    def surface_area(self):
        return math.pi * (self.radius ** 2)

    def boundary_length(self):
        return 2 * math.pi * self.radius

    def separation_distance(self, other_obj):
        if not isinstance(other_obj, GeometryObject):
            raise ValueError("Other must be a GeometryObject")
        return self.midpoint.separation_distance(other_obj.midpoint)

    def spin(self, degrees):
        # For a disk, rotation does not change its surface area or boundary length
        pass

    def enclosing_box(self):
        return Box(2 * self.radius, 2 * self.radius, self.midpoint)

class Polygon(GeometryObject):
    def __init__(self, side1, side2, side3, midpoint=Coordinate(0, 0)):
        if side1 <= 0 or side2 <= 0 or side3 <= 0 or not self.check_validity(side1, side2, side3):
            raise ValueError("Invalid polygon dimensions")
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3
        self.midpoint = midpoint

    @staticmethod
    def check_validity(s1, s2, s3):
        return s1 + s2 > s3 and s1 + s3 > s2 and s2 + s3 > s1

    def surface_area(self):
        semi_perimeter = (self.side1 + self.side2 + self.side3) / 2
        return math.sqrt(semi_perimeter * (semi_perimeter - self.side1) * (semi_perimeter - self.side2) * (semi_perimeter - self.side3))

    def boundary_length(self):
        return self.side1 + self.side2 + self.side3

    def separation_distance(self, other_obj):
        if not isinstance(other_obj, GeometryObject):
            raise ValueError("Other must be a GeometryObject")
        return self.midpoint.separation_distance(other_obj.midpoint)

    def spin(self, degrees):
        # For a polygon, rotation can be complex and may require additional logic
        pass

    def enclosing_box(self):
        # Simplified enclosing box for a polygon
        longest_side = max(self.side1, self.side2, self.side3)
        return Box(longest_side, longest_side, self.midpoint)

# Example usage
box_a = Box(4, 5, Coordinate(1, 1))
box_b = Box(4, 5, Coordinate(2, 2))
print(box_a.surface_area())  # 20
print(box_a.boundary_length())  # 18
print(box_a.is_equal(box_b))  # True
print(box_a.separation_distance(box_b))  # 1.4142135623730951
box_a.spin(45)  # No change for box
print(box_a.enclosing_box())  # Box object

disk_x = Disk(3, Coordinate(0, 0))
disk_y = Disk(3, Coordinate(5, 5))
print(disk_x.surface_area())  # 28.274333882308138
print(disk_x.boundary_length())  # 18.849555921538755
print(disk_x.is_equal(disk_y))  # True
print(disk_x.separation_distance(disk_y))  # 7.0710678118654755
disk_x.spin(90)  # No change for disk
print(disk_x.enclosing_box())  # Box object

poly_p = Polygon(3, 4, 5, Coordinate(0, 0))
poly_q = Polygon(3, 4, 5, Coordinate(3, 3))
