# Perform cyclic character shifting for encoding and decoding
def transform_text(input_str: str, shift_amount: int = 5, char_set: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    Applies a cyclic shift transformation to groups of characters.
    Supports non-alphabetic characters by leaving them unchanged,
    and ensures efficient processing even for large inputs.
    """
    if not input_str:
        return ""

    # Validate that the character set contains unique elements
    if len(set(char_set)) != len(char_set):
        raise ValueError("Character set must contain unique characters")

    # Create mapping from character to its position in the set
    char_position_map = {char: pos for pos, char in enumerate(char_set)}

    # Process the string in chunks
    result_parts = []
    for start_idx in range(0, len(input_str), shift_amount):
        chunk = input_str[start_idx:start_idx + shift_amount]
        transformed_chunk = ""
        for symbol in chunk:
            if symbol in char_position_map:
                new_pos = (char_position_map[symbol] + shift_amount) % len(char_set)
                transformed_chunk += char_set[new_pos]
            else:
                transformed_chunk += symbol  # Keep non-mapped symbols as-is
        result_parts.append(transformed_chunk)

    return "".join(result_parts)


def reverse_transform_text(encoded_str: str, shift_amount: int = 5, char_set: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    Reverses the cyclic shift applied by transform_text to recover the original string.
    Maintains support for non-alphabetic characters and handles large inputs efficiently.
    """
    if not encoded_str:
        return ""

    # Validate uniqueness of character set
    if len(set(char_set)) != len(char_set):
        raise ValueError("Character set must contain unique characters")

    # Build reverse mapping
    char_position_map = {char: pos for pos, char in enumerate(char_set)}

    # Decode by reversing the shift
    decoded_parts = []
    for start_idx in range(0, len(encoded_str), shift_amount):
        chunk = encoded_str[start_idx:start_idx + shift_amount]
        restored_chunk = ""
        for symbol in chunk:
            if symbol in char_position_map:
                new_pos = (char_position_map[symbol] - shift_amount) % len(char_set)
                restored_chunk += char_set[new_pos]
            else:
                restored_chunk += symbol  # Preserve unmapped symbols
        decoded_parts.append(restored_chunk)

    return "".join(decoded_parts)


# Demonstration
if __name__ == "__main__":
    sample_text = "Hello, World! This is a test."
    transformed = transform_text(sample_text, shift_amount=5, char_set="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    print(f"Transformed: {transformed}")

    original = reverse_transform_text(transformed, shift_amount=5, char_set="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    print(f"Restored: {original}")

