# Count the number of perfect squares in a 2D list
import math

def count_perfect_squares(grid):
    def is_square_number(value):
        root = math.isqrt(value)
        return root * root == value

    counter = 0
    for line in grid:
        for item in line:
            if is_square_number(item):
                counter += 1
    return counter

