# Oracle database connection and DDL execution script
import cx_Oracle
import sys

def establish_db_connection(user, passwd, service):
    try:
        connection = cx_Oracle.connect(user, passwd, service)
        print("Successfully connected to the Oracle database")
        return connection
    except cx_Oracle.DatabaseError as error:
        err_obj, = error.args
        if err_obj.code == 1017:
            print('Invalid username or password. Please verify your credentials.')
        else:
            print(f'Database connection failed: {error}')
        sys.exit(1)  # Exit program on connection failure

def run_ddl_commands(connection, ddl_text):
    cursor = connection.cursor()
    try:
        cursor.execute(ddl_text)
    except cx_Oracle.DatabaseError as error:
        err_obj, = error.args
        if err_obj.code == 955:
            print('Table already exists')
        elif err_obj.code == 1031:
            print("Privilege issue - ensure you're using the correct owner account")
        else:
            print(f"Database operation error: {err_obj.code} - {err_obj.message}")
        cursor.close()
        connection.rollback()  # Undo changes if an error occurs
        raise  # Propagate exception for higher-level handling
    cursor.close()
    connection.commit()

