# Custom exception for invalid input values
class InvalidArgumentError(Exception):
    def __init__(self, message="Invalid argument provided. Only positive integers greater than 10 are allowed."):
        self.message = message
        super().__init__(self.message)

def compute_mean(*values):
    running_sum = 0
    valid_count = 0

    for value in values:
        if not isinstance(value, int) or value <= 0:
            raise InvalidArgumentError(f"Invalid argument: {value}")
        if value > 10:
            running_sum += value
            valid_count += 1

    if valid_count == 0:
        return 0
    mean_value = running_sum / valid_count
    return mean_value

# Find the best dish that can be prepared with available ingredients
def suggest_meal(stock, menu):
    # Transform stock into a dictionary with numeric quantities for processing
    inventory = {item: int(amount.split()[0]) for item, amount in stock.items()}

    # Prepare variables to track the optimal selection and leftover items
    selected_dish = None
    leftover_ingredients = {}

    for meal_name, needed_items in menu.items():
        feasible = True
        temp_stock = inventory.copy()

        for component, needed_amount in needed_items.items():
            if component not in inventory or inventory[component] < needed_amount:
                feasible = False
                break
            else:
                temp_stock[component] -= needed_amount

        if feasible:
            selected_dish = meal_name
            leftover_ingredients = {k: v for k, v in temp_stock.items() if v > 0}
            break

    return selected_dish, leftover_ingredients

