# Calculate the difference between two dates in years, months, and days
from datetime import datetime

def check_leap_year(yr):
    """Determine if a given year is a leap year."""
    return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)

def get_days_in_month(yr, mth):
    """Get the number of days in a specific month of a given year."""
    if mth == 2:
        return 29 if check_leap_year(yr) else 28
    elif mth in [4, 6, 9, 11]:
        return 30
    else:
        return 31

def compute_date_diff(dt1, dt2):
    """Compute the difference between two dates in years, months, and days."""
    if dt1 > dt2:
        dt1, dt2 = dt2, dt1  # Ensure dt1 is the earlier date

    diff_years = dt2.year - dt1.year
    diff_months = dt2.month - dt1.month
    diff_days = dt2.day - dt1.day

    if diff_days < 0:
        # Borrow days from the previous month
        prev_month = dt2.month - 1 if dt2.month > 1 else 12
        days_in_prev_month = get_days_in_month(dt2.year, prev_month)
        diff_days += days_in_prev_month
        diff_months -= 1

    if diff_months < 0:
        # Borrow months from the previous year
        diff_months += 12
        diff_years -= 1

    return diff_years, diff_months, diff_days

def run_program():
    # Prompt for input dates
    first_date_input = input("Enter the first date (YYYY-MM-DD): ")
    second_date_input = input("Enter the second date (YYYY-MM-DD): ")

    try:
        first_date = datetime.strptime(first_date_input, "%Y-%m-%d")
        second_date = datetime.strptime(second_date_input, "%Y-%m-%d")
    except ValueError:
        print("Invalid date format. Please use YYYY-MM-DD.")
        return

    if first_date > datetime.now() or second_date > datetime.now():
        print("One or both dates are in the future.")
    else:
        result = compute_date_diff(first_date, second_date)
        print(f"The age difference is {result[0]} years, {result[1]} months, and {result[2]} days.")

if __name__ == "__main__":
    run_program()

# Compute total storage usage of a directory tree using parallel processing
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def calculate_dir_size(directory):
    size = 0
    with os.scandir(directory) as entries:
        for item in entries:
            if item.is_file():
                size += item.stat().st_size
            elif item.is_dir():
                size += calculate_dir_size(item.path)
    return size

def compute_folder_storage(root_path, threads=4):
    with ThreadPoolExecutor(max_workers=threads) as pool:
        pending_tasks = []
        for current_dir, subdirs, _ in os.walk(root_path, topdown=True):
            for subdir in subdirs:
                subdir_full_path = os.path.join(current_dir, subdir)
                pending_tasks.append(pool.submit(calculate_dir_size, subdir_full_path))

        accumulated_size = 0
        for task in as_completed(pending_tasks):
            accumulated_size += task.result()

        # Include size of files directly under the root directory
        with os.scandir(root_path) as entries:
            for entry in entries:
                if entry.is_file():
                    accumulated_size += entry.stat().st_size

    return accumulated_size

if __name__ == "__main__":
    target_directory = "C:\\"
    storage_amount = compute_folder_storage(target_directory)
    print(f"Total size: {storage_amount / 1024 / 1024 / 1024:.2f} GB")

import asyncio
from typing import Type, Callable
from pydantic import BaseModel
import functools
from fastapi.encoders import jsonable_encoder

# Assuming redis_client and settings are defined elsewhere

class CacheResponse:
    def __init__(self, include_fields: list[str] = None, exclude_fields: list[str] = None):
        self.include_fields = include_fields or []
        self.exclude_fields = exclude_fields or []
        self._locks = {}  # A dictionary to hold locks for each unique key

    def __call__(self, model: Type[BaseModel] = None, expire_time: int = settings.REDIS_TIMEOUT,
                 include_fields: list[str] = None, exclude_fields: list[str] = None):
        def decorator(fn: Callable):
            @functools.wraps(fn)
            async def wrapper(*args, **kwargs):
                # generate the key for the function signature
                cache_key = self._create_key(
                    fn,
                    include_fields or self.include_fields,
                    exclude_fields or self.exclude_fields,
                    *args, **kwargs,
                )

                # Get or create a lock for the key
                lock = self._locks.setdefault(cache_key, asyncio.Lock())

                async with lock:
                    cached_data = await redis_client.get_by_key(cache_key)
                    if cached_data:
                        cached_data = orjson.loads(cached_data)
                        if model:
                            if isinstance(cached_data, list):
                                return [model.parse_obj(item) for item in cached_data]
                            else:
                                return model.parse_obj(cached_data)
                        else:
                            return cached_data
                    else:
                        if asyncio.iscoroutinefunction(fn):
                            result = await fn(*args, **kwargs)
                        else:
                            result = fn(*args, **kwargs)
                        payload = redis_client.RedisData(
                            key=cache_key,
                            value=orjson.dumps(jsonable_encoder(result)),
                            ttl=expire_time
                        )
                        await redis_client.set_redis_key(payload)
                        return result

                # Clean up the lock if it's no longer needed
                if cache_key in self._locks and not lock.locked():
                    del self._locks[cache_key]

            return wrapper
        return decorator

    def _create_key(self, func: Callable, include_fields: list[str], exclude_fields: list[str], *args, **kwargs) -> str:
        param_values = {}
        for arg in args:
            param_values[arg] = kwargs.get(arg)
        for key, value in kwargs.items():
            if key not in param_values:
                param_values[key] = value

        filtered_params = {k: v for k, v in param_values.items() if k not in exclude_fields}
        if include_fields:
            filtered_params = {k: v for k, v in filtered_params.items() if k in include_fields}

        sorted_items = sorted(filtered_params.items())
        params_str = "&".join(f"{k}={v}" for k, v in sorted_items)
        return f"{func.__module__}:{func.__name__}:{params_str}"

