        regex_pattern = re.compile(rf"{re.escape(event_name)}.*?(\d{{4}}\sBCE)", re.IGNORECASE | re.DOTALL)
        search_result = regex_pattern.search(content)
        if search_result:
            found_events[event_name] = search_result.group(1).strip()
        else:
            found_events[event_name] = None
    return found_events

def check_consistency(page_url, target_events, baseline_events):
    """Compares historical events on a page against baseline values."""
    page_response = requests.get(page_url)
    page_soup = BeautifulSoup(page_response.text, 'html.parser')
    page_content = clean_html_content(page_soup)
    detected_events = locate_events(page_content, target_events)

    mismatches = []
    for event_name, expected_date in target_events.items():
        if detected_events[event_name] != expected_date:
            mismatches.append((event_name, detected_events[event_name], expected_date))

    if mismatches:
        print(f"Mismatches detected in {page_url}:")
        for event_name, actual_date, expected_date in mismatches:
            print(f"  - {event_name}: Found '{actual_date}', expected '{expected_date}'")
    else:
        print(f"All events consistent in {page_url}.")

def main():
