# Cyclic encoding/decoding utility for strings with mixed character types
import string

def transform_cyclic(s: str, encode: bool = True) -> str:
    """
    Applies cyclic transformation to the input string based on character type and position.
    Supports letters, digits, punctuation, and spaces.
    """
    def shift_char(c: str, shift: int, char_set: str) -> str:
        if c in char_set:
            idx = char_set.index(c)
            if encode:
                new_idx = (idx + shift) % len(char_set)
            else:
                new_idx = (idx - shift) % len(char_set)
            return char_set[new_idx]
        return c

    # Define character sets
    alpha_chars = string.ascii_letters
    numeric_chars = string.digits
    special_chars = string.punctuation
    space_chars = ' '

    result = []
    for pos, symbol in enumerate(s):
        if symbol in alpha_chars:
            shift_amount = (pos * 3 + 1) % len(alpha_chars)
            result.append(shift_char(symbol, shift_amount, alpha_chars))
        elif symbol in numeric_chars:
            shift_amount = (pos * 2 + 1) % len(numeric_chars)
            result.append(shift_char(symbol, shift_amount, numeric_chars))
        elif symbol in special_chars:
            shift_amount = (pos * 5 + 1) % len(special_chars)
            result.append(shift_char(symbol, shift_amount, special_chars))
        elif symbol in space_chars:
            result.append(shift_char(symbol, 0, space_chars))
        else:
            result.append(symbol)

    return ''.join(result)

def encode_cyclic(s: str) -> str:
    """Encodes the input string using cyclic transformation."""
    return transform_cyclic(s, encode=True)

def decode_cyclic(s: str) -> str:
    """Decodes the input string that was encoded with cyclic transformation."""
    return transform_cyclic(s, encode=False)

# Example usage
test_input = "Hello, World! 123"
encoded_text = encode_cyclic(test_input)
decoded_text = decode_cyclic(encoded_text)

print(f"Original: {test_input}")
print(f"Encoded: {encoded_text}")
print(f"Decoded: {decoded_text}")

