# Modified Fibonacci Heap implementation with renamed variables and restructured logic
class TreeNode:
    def __init__(self, value):
        self.value = value
        self.rank = 0
        self.ancestor = None
        self.descendant = None
        self.prev_sibling = self
        self.next_sibling = self
        self.visited = False

class PriorityTreeHeap:
    def __init__(self):
        self.minimum_element = None
        self.total_elements = 0

    def add(self, value):
        new_node = TreeNode(value)
        if self.minimum_element is None:
            self.minimum_element = new_node
        else:
            new_node.next_sibling = self.minimum_element
            new_node.prev_sibling = self.minimum_element.prev_sibling
            self.minimum_element.prev_sibling.next_sibling = new_node
            self.minimum_element.prev_sibling = new_node
            if value < self.minimum_element.value:
                self.minimum_element = new_node
        self.total_elements += 1

    def merge(self, other_heap):
        if self.minimum_element is None:
            self.minimum_element = other_heap.minimum_element
        elif other_heap.minimum_element is not None:
            self.minimum_element.next_sibling.prev_sibling = other_heap.minimum_element.prev_sibling
            other_heap.minimum_element.prev_sibling.next_sibling = self.minimum_element.next_sibling
            self.minimum_element.next_sibling = other_heap.minimum_element
            other_heap.minimum_element.prev_sibling = self.minimum_element
            if other_heap.minimum_element.value < self.minimum_element.value:
                self.minimum_element = other_heap.minimum_element
        self.total_elements += other_heap.total_elements

    def get_min(self):
        return self.minimum_element.value if self.minimum_element else None

    def remove_min(self):
        min_node = self.minimum_element
        if min_node is not None:
            if min_node.descendant:
                current_child = min_node.descendant
                while True:
                    current_child.ancestor = None
                    current_child = current_child.next_sibling
                    if current_child == min_node.descendant:
                        break
                min_node.descendant.prev_sibling.next_sibling = min_node.next_sibling
                min_node.descendant.next_sibling.prev_sibling = min_node.prev_sibling
                min_node.next_sibling.prev_sibling = min_node.descendant
                min_node.prev_sibling.next_sibling = min_node.descendant
            min_node.prev_sibling.next_sibling = min_node.next_sibling
            min_node.next_sibling.prev_sibling = min_node.prev_sibling
            if min_node == min_node.next_sibling:
                self.minimum_element = None
            else:
                self.minimum_element = min_node.next_sibling
                self.rebalance()
            self.total_elements -= 1
        return min_node.value if min_node else None

    def rebalance(self):
        max_rank = int(self.total_elements**0.5) + 1
        rank_map = [None] * max_rank

        current = self.minimum_element
        nodes_list = []
        while True:
            nodes_list.append(current)
            current = current.next_sibling
            if current == self.minimum_element:
                break

        for node in nodes_list:
            r = node.rank
            while rank_map[r] is not None:
                other_node = rank_map[r]
                if node.value > other_node.value:
                    node, other_node = other_node, node
                self.connect(other_node, node)
                rank_map[r] = None
                r += 1
            rank_map[r] = node

        self.minimum_element = None
        for i in range(max_rank):
            if rank_map[i] is not None:
                if self.minimum_element is None:
                    self.minimum_element = rank_map[i]
                else:
                    rank_map[i].next_sibling = self.minimum_element
                    rank_map[i].prev_sibling = self.minimum_element.prev_sibling
                    self.minimum_element.prev_sibling.next_sibling = rank_map[i]
                    self.minimum_element.prev_sibling = rank_map[i]
                    if rank_map[i].value < self.minimum_element.value:
                        self.minimum_element = rank_map[i]

    def connect(self, y, x):
        y.prev_sibling.next_sibling = y.next_sibling
        y.next_sibling.prev_sibling = y.prev_sibling
        y.ancestor = x
        if x.descendant is None:
            x.descendant = y
            y.next_sibling = y
            y.prev_sibling = y
        else:
            y.next_sibling = x.descendant
            y.prev_sibling = x.descendant.prev_sibling
            x.descendant.prev_sibling.next_sibling = y
            x.descendant.prev_sibling = y
        x.rank += 1
        y.visited = False

    def update_value(self, node, new_value):
        if new_value > node.value:
            raise ValueError("New value is greater than current value")
        node.value = new_value
        ancestor = node.ancestor
        if ancestor is not None and node.value < ancestor.value:
            self.sever(node, ancestor)
            self.propagate_sever(ancestor)
        if node.value < self.minimum_element.value:
            self.minimum_element = node

    def sever(self, node, parent):
        node.prev_sibling.next_sibling = node.next_sibling
        node.next_sibling.prev_sibling = node.prev_sibling
        parent.rank -= 1
        if parent.descendant == node:
            parent.descendant = node.next_sibling if node.next_sibling != node else None
        node.next_sibling = self.minimum_element
        node.prev_sibling = self.minimum_element.prev_sibling
        self.minimum_element.prev_sibling.next_sibling = node
        self.minimum_element.prev_sibling = node
        node.ancestor = None
        node.visited = False

    def propagate_sever(self, node):
        ancestor = node.ancestor
        if ancestor is not None:
            if not node.visited:
                node.visited = True
            else:
                self.sever(node, ancestor)
                self.propagate_sever(ancestor)

    def erase(self, node):
        self.update_value(node, float('-inf'))
        self.remove_min()

    def __str__(self):
        if self.minimum_element is None:
            return "Empty Heap"
        output = []
        current = self.minimum_element
        while True:
            output.append(f"TreeNode({current.value}, rank={current.rank})")
            current = current.next_sibling
            if current == self.minimum_element:
                break
        return " <-> ".join(output)

# Demonstration of usage
if __name__ == "__main__":
    heap = PriorityTreeHeap()
    heap.add(3)
    heap.add(1)
    heap.add(4)
    heap.add(2)
    print("Initial Heap:", heap)
    print("Minimum value:", heap.get_min())
    print("Removed Minimum:", heap.remove_min())
    print("Heap after removal:", heap)
    node = heap.minimum_element
    heap.update_value(node, 0)
    print("Heap after value update:", heap)
    heap.erase(node)
    print("Heap after node deletion:", heap)

