# Analyze CSS file for valid and invalid hex color codes
import re
from collections import Counter

def check_hex_color_format(color_code):
    """Determine whether the provided string is a valid hex color code."""
    hex_regex = re.compile(r'^#([A-Fa-f0-9]{3}){1,2}$')
    return bool(hex_regex.match(color_code))

def process_and_tally_colors(css_text):
    """Extract, validate, and count occurrences of hex color codes in CSS text."""
    color_regex = re.compile(r'#([A-Fa-f0-9]{3}){1,2}')
    found_matches = color_regex.findall(css_text)

    correct_colors = []
    incorrect_colors = []

    for fragment in found_matches:
        complete_code = f"#{fragment}"
        if check_hex_color_format(complete_code):
            correct_colors.append(complete_code)
        else:
            incorrect_colors.append(complete_code)

    frequency_map = Counter(correct_colors)

    return frequency_map, incorrect_colors

def execute_analysis(css_file_path):
    try:
        with open(css_file_path, 'r') as input_file:
            css_data = input_file.read()

        color_frequencies, bad_colors = process_and_tally_colors(css_data)

        if color_frequencies:
            print("Detected color frequencies (valid entries):")
            for color_entry, occurrence in color_frequencies.most_common():
                print(f"{color_entry}: {occurrence}")
        else:
            print("No valid hexadecimal color codes detected.")

        if bad_colors:
            print("\nInvalid hexadecimal codes encountered:")
            for code in bad_colors:
                print(code)
        else:
            print("\nNo invalid hexadecimal color codes detected.")

    except FileNotFoundError:
        print(f"Error: File '{css_file_path}' could not be located.")
    except Exception as error:
        print(f"An unexpected issue occurred: {error}")

if __name__ == "__main__":
    css_file_path = 'styles.css'  # Update with the actual path to your CSS file
    execute_analysis(css_file_path)

# Process string with case swapping, digit adjustment, and special char repetition
from typing import Tuple, Dict

def modified_text_processing(text: str) -> Tuple[str, Dict[str, int]]:
    result_chars = []
    frequency_map = {}

    for symbol in text:
        if symbol.isalpha():
            # Toggle letter case
            updated_char = symbol.swapcase()
        elif symbol.isdigit():
            # Increment odd digits by 1
            updated_char = str(int(symbol) + 1) if int(symbol) % 2 != 0 else symbol
        else:
            # Duplicate non-alphanumeric characters
            updated_char = symbol * 2

        result_chars.append(updated_char)

        # Track character frequencies
        for ch in updated_char:
            if ch in frequency_map:
                frequency_map[ch] += 1
            else:
                frequency_map[ch] = 1

    return ''.join(result_chars), frequency_map

