# Transpose a square matrix in-place 
def invert_matrix(matrix_data: list[list[int]]) -> None:
    size = len(matrix_data)
    for row in range(size):
        for col in range(row + 1, size):
            matrix_data[row][col], matrix_data[col][row] = matrix_data[col][row], matrix_data[row][col]

