# Custom exception for mismatched point dimensions
class DimensionMismatchError(Exception):
    """Exception raised when trying to combine points of unequal dimensionality."""
    def __init__(self, msg="Unable to combine points with different dimensions."):
        self.msg = msg
        super().__init__(self.msg)

class CoordinatePoint:
    def __init__(self, *values):
        self.values = values

    def __add__(self, other_point):
        if len(self.values) != len(other_point.values):
            raise DimensionMismatchError()

        combined_values = tuple(x + y for x, y in zip(self.values, other_point.values))
        return CoordinatePoint(*combined_values)

    def __str__(self):
        return f"CoordinatePoint({', '.join(map(str, self.values))})"

