# Huffman coding implementation with heap-based tree construction
import heapq
from collections import Counter

class TreeNode:
    def __init__(self, character, count):
        self.char = character
        self.count = count
        self.left = None
        self.right = None

    def __lt__(self, other):
        return self.count < other.count

def create_frequency_map(data):
    return Counter(data)

def construct_huffman_tree(freq_map):
    priority_queue = [TreeNode(char, count) for char, count in freq_map.items()]
    heapq.heapify(priority_queue)

    while len(priority_queue) > 1:
        left_child = heapq.heappop(priority_queue)
        right_child = heapq.heappop(priority_queue)
        combined_node = TreeNode(None, left_child.count + right_child.count)
        combined_node.left = left_child
        combined_node.right = right_child
        heapq.heappush(priority_queue, combined_node)

    return priority_queue[0]  # root of the Huffman tree

def generate_code_table(tree_node, current_code="", mapping=None):
    if mapping is None:
        mapping = {}
    if tree_node is not None:
        if tree_node.char is not None:
            mapping[tree_node.char] = current_code
        generate_code_table(tree_node.left, current_code + "0", mapping)
        generate_code_table(tree_node.right, current_code + "1", mapping)
    return mapping

def encode_data(text_data, code_mapping):
    return ''.join(code_mapping[char] for char in text_data)

def decode_data(encoded_data, tree_root):
    decoded_chars = []
    current_node = tree_root
    for digit in encoded_data:
        if digit == '0':
            current_node = current_node.left
        else:
            current_node = current_node.right
        if current_node.char is not None:
            decoded_chars.append(current_node.char)
            current_node = tree_root
    return ''.join(decoded_chars)

