# Function to count vowels in a given string
def tally_vowels(text):
    vowel_set = "aeiouAEIOU"
    return sum(1 for letter in text if letter in vowel_set)

# Function to analyze multiple sentences for vowel statistics
def analyze_sentences(sentence_list):
    if not sentence_list:
        return {"vowel_counts": [], "longest_vowel_sentence": None, "issue": "No sentences provided"}

    highest_count = 0
    longest_vowel_sentence = None
    vowel_counts = []

    for text in sentence_list:
        if len(text) > 200:
            return {"vowel_counts": [], "longest_vowel_sentence": None, "issue": f"Error: Sentence exceeds 200 characters: '{text[:50]}...'"}

        count = tally_vowels(text)
        vowel_counts.append(count)

        if count > highest_count:
            highest_count = count
            longest_vowel_sentence = text

    return {
        "vowel_counts": vowel_counts,
        "longest_vowel_sentence": longest_vowel_sentence,
        "issue": None
    }

