# Determine if nested structures are empty and count empty containers
def check_empty_containers(container, seen=None):
    if seen is None:
        seen = set()

    if id(container) in seen:
        return True, 0  # Already processed, avoid infinite recursion

    seen.add(id(container))

    # Check if the container is a basic non-iterable type
    if not isinstance(container, (dict, list, tuple, set)):
        return False, 0  # Not a container type

    # Check for empty dictionary
    if isinstance(container, dict) and not container:
        return True, 1

    all_empty = True
    empty_count = 0

    # Process dictionary values
    if isinstance(container, dict):
        for val in container.values():
            is_empty, cnt = check_empty_containers(val, seen)
            empty_count += cnt
            if not is_empty:
                all_empty = False
    # Process list/tuple/set items
    elif isinstance(container, (list, tuple, set)):
        for item in container:
            is_empty, cnt = check_empty_containers(item, seen)
            empty_count += cnt
            if not is_empty:
                all_empty = False

    return all_empty, empty_count

