import phonenumbers
from phonenumbers import carrier, geocoder, timezone
from django.core.exceptions import ValidationError
from django.db import models

class CustomPhoneNumberField(models.CharField):
    def __init__(self, *args, **kwargs):
        kwargs['max_length'] = 25  # Increased max length for international formats
        super().__init__(*args, **kwargs)

    def validate(self, value, model_instance):
        super().validate(value, model_instance)
        try:
            parsed_number = phonenumbers.parse(value, None)
            if not phonenumbers.is_valid_number(parsed_number):
                raise ValidationError('Phone number format is invalid.')
        except phonenumbers.NumberParseException as error:
            raise ValidationError(f'Invalid phone number format: {error}')

    def pre_save(self, model_instance, add):
        value = super().pre_save(model_instance, add)
        if value:
            try:
                parsed_number = phonenumbers.parse(value, None)
                if phonenumbers.is_valid_number(parsed_number):
                    return phonenumbers.format_number(parsed_number, phonenumbers.PhoneNumberFormat.E164)
            except phonenumbers.NumberParseException:
                pass
        return value

class CustomerModel(models.Model):
    contact_number = CustomPhoneNumberField()

