# Script to identify and delete unused Azure Web Apps based on request metrics
import os
from datetime import datetime, timedelta
from azure.identity import DefaultAzureCredential
from azure.mgmt.resource import ResourceManagementClient
from azure.mgmt.web import WebSiteManagementClient
from azure.mgmt.web.models import UsageState

# Configuration values
SUBSCRIPTION_ID = 'your-subscription-id'
RESOURCE_GROUP_NAME = 'your-resource-group-name'
WEB_APP_NAME = 'your-web-app-name'  # Optional: if you want to target a specific web app
DAYS_THRESHOLD = 30

# Setup Azure management clients
credential = DefaultAzureCredential()
resource_client = ResourceManagementClient(credential, SUBSCRIPTION_ID)
web_client = WebSiteManagementClient(credential, SUBSCRIPTION_ID)

def list_web_apps_in_group(resource_group):
    web_apps_list = web_client.web_apps.list_by_resource_group(resource_group)
    return list(web_apps_list)

def fetch_web_app_usage_data(web_app):
    end_time = datetime.utcnow()
    start_time = end_time - timedelta(days=DAYS_THRESHOLD)
    metric_definitions = web_client.web_apps.list_metric_definitions(web_app.resource_group, web_app.name)

    for metric_def in metric_definitions:
        if metric_def.name.value == 'Requests':
            usage_data = web_client.web_apps.list_metrics(
                web_app.resource_group, 
                web_app.name, 
                metric_def.name.value, 
                interval='PT1H', 
                start_time=start_time, 
                end_time=end_time
            )
            return usage_data
    return None

def check_if_unused(web_app):
    usage_data = fetch_web_app_usage_data(web_app)
    if not usage_data:
        return True

    for series in usage_data.value:
        if series.timeseries:
            for data_point in series.timeseries[0].data:
                if data_point.total:
                    return False
    return True

def remove_web_app(web_app):
    print(f"Removing Web App: {web_app.name}")
    web_client.web_apps.delete(web_app.resource_group, web_app.name)

def execute_cleanup():
    web_apps = list_web_apps_in_group(RESOURCE_GROUP_NAME)
    for app in web_apps:
        if check_if_unused(app):
            remove_web_app(app)

if __name__ == "__main__":
    execute_cleanup()

