            attempt = int(input(f"{player_name}, pick a number between {low_limit} and {high_limit}: "))
            if low_limit <= attempt <= high_limit:
                return attempt
            else:
                print(f"Kindly choose a number within the range {low_limit} to {high_limit}.")
        except ValueError:
            print("Input must be a valid integer.")

