# Abstract base class for geometric shapes
from abc import ABC, abstractmethod

class GeometricFigure(ABC):
    def __init__(self, dim1, dim2, figure_name):
        self.dimension1 = dim1
        self.dimension2 = dim2
        self._figure_type = figure_name

    @abstractmethod
    def computeSurfaceArea(self) -> float:
        pass

    def displaySurfaceArea(self):
        surface_area = self.computeSurfaceArea()
        print(f"The surface area of the {self._figure_type} is {surface_area:.2f}")

    def calculateBoundaryLength(self) -> float:
        return 2 * (self.dimension1 + self.dimension2)

    @staticmethod
    def compareSurfaceAreas(shape_a, shape_b) -> float:
        return abs(shape_a.computeSurfaceArea() - shape_b.computeSurfaceArea())

    def showType(self):
        print(f"This figure is a {self._figure_type}")

# Concrete implementations of GeometricFigure
class Quadrilateral(GeometricFigure):
    def __init__(self, side_a, side_b):
        super().__init__(side_a, side_b, "Quadrilateral")

    def computeSurfaceArea(self) -> float:
        return self.dimension1 * self.dimension2

class Ellipse(GeometricFigure):
    def __init__(self, semi_major):
        super().__init__(semi_major, 0, "Ellipse")  # dimension2 unused for ellipse
        self.semi_major_axis = semi_major

    def computeSurfaceArea(self) -> float:
        return 3.14159 * self.semi_major_axis * self.semi_major_axis

    def calculateBoundaryLength(self) -> float:
        return 2 * 3.14159 * self.semi_major_axis

class Polygon(GeometricFigure):
    def __init__(self, base_length, altitude):
        super().__init__(base_length, altitude, "Polygon")

    def computeSurfaceArea(self) -> float:
        return 0.5 * self.dimension1 * self.dimension2

# Demonstration
if __name__ == "__main__":
    quad = Quadrilateral(4, 5)
    quad.showType()
    quad.displaySurfaceArea()
    print(f"The boundary length of the {quad._figure_type} is {quad.calculateBoundaryLength():.2f}")

    ell = Ellipse(3)
    ell.showType()
    ell.displaySurfaceArea()
    print(f"The boundary length of the {ell._figure_type} is {ell.calculateBoundaryLength():.2f}")

    poly = Polygon(3, 4)
    poly.showType()
    poly.displaySurfaceArea()
    print(f"The boundary length of the {poly._figure_type} is {poly.calculateBoundaryLength():.2f}")

    surface_diff = GeometricFigure.compareSurfaceAreas(quad, ell)
    print(f"The difference in surface area between the {quad._figure_type} and the {ell._figure_type} is {surface_diff:.2f}")

# A phone directory management system with hierarchical organization by location
class ContactDirectory:
    def __init__(self):
        self.contacts = {}

    def add_contact(self, person_name, contact_number, nation, region, urban_area):
        if nation not in self.contacts:
            self.contacts[nation] = {}
        if region not in self.contacts[nation]:
            self.contacts[nation][region] = {}
        if urban_area not in self.contacts[nation][region]:
            self.contacts[nation][region][urban_area] = []

        self.contacts[nation][region][urban_area].append({
            'person': person_name,
            'contact': contact_number
        })

    def delete_contact(self, person_name, contact_number, nation, region, urban_area):
        if nation in self.contacts and region in self.contacts[nation] and urban_area in self.contacts[nation][region]:
            records = self.contacts[nation][region][urban_area]
            for record in records:
                if record['person'] == person_name and record['contact'] == contact_number:
                    records.remove(record)
                    return True
        return False

    def find_contact(self, person_name=None, contact_number=None, nation=None, region=None, urban_area=None):
        matches = []

        def traverse(current_dict, path):
            if not isinstance(current_dict, dict):
                return

            for key, value in current_dict.items():
                updated_path = path + [key]
                if len(updated_path) == 3:  # Nation, Region, Urban area
                    for record in value:
                        if (person_name is None or record['person'] == person_name) and \
                           (contact_number is None or record['contact'] == contact_number):
                            matches.append({
                                'person': record['person'],
                                'contact': record['contact'],
                                'nation': updated_path[0],
                                'region': updated_path[1],
                                'urban_area': updated_path[2]
                            })
                else:
                    traverse(value, updated_path)

        traverse(self.contacts, [])
        return matches

    def show_directory(self):
        def show_recursive(current_dict, spacing=0):
            if not isinstance(current_dict, dict):
                return

            for key, value in current_dict.items():
                print(' ' * spacing + key)
                if isinstance(value, list):
                    for record in value:
                        print(' ' * (spacing + 4) + f"{record['person']}: {record['contact']}")
                else:
                    show_recursive(value, spacing + 4)

        show_recursive(self.contacts)

