def fetch_exchange_rates(api_token):
    query_params = {'app_id': api_token}
    result = requests.get(ENDPOINT_URL, params=query_params)

    if result.status_code == 200:
        json_data = result.json()
        return json_data['rates']
    else:
        raise Exception(f"Error retrieving exchange rates: {result.status_code}")

def transform_currency(value, source_currency, target_currency, exchange_rates):
    if source_currency != 'USD':
        value = value / exchange_rates[source_currency]

    final_value = value * exchange_rates[target_currency]
    return final_value

