# AWS Lambda function to retrieve a user by ID from DynamoDB
import boto3
import json
import os

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ['USERS_TABLE'])

def lambda_handler(event, context):
    try:
        user_identifier = event['pathParameters']['userId']
        response = table.get_item(Key={'userId': user_identifier})
        user_data = response.get('Item')
        if user_data:
            return {
                'statusCode': 200,
                'body': json.dumps(user_data)
            }
        else:
            return {
                'statusCode': 404,
                'body': json.dumps({'message': 'User not found'})
            }
    except Exception as error:
        return {
            'statusCode': 500,
            'body': json.dumps({'message': str(error)})
