CREATE_CHALLENGE = f"{API_BASE}/challenge"
ACCEPT_CHALLENGE = f"{API_BASE}/challenge/{challenge_id}/accept"
REJECT_CHALLENGE = f"{API_BASE}/challenge/{challenge_id}/decline"
GAME_STREAM = f"{API_BASE}/bot/game/stream/{game_id}"
SEND_MOVE = f"{API_BASE}/bot/game/{game_id}/move"

# Authentication token for the bot (replace with actual token)
BOT_API_KEY = "your_bot_token_here"

# HTTP headers for authentication
auth_headers = {
    "Authorization": f"Bearer {BOT_API_KEY}"
}

def initiate_challenge(target_user, time_control):
    """
    Send a challenge request to another user with specified time settings.
    """
    if not 1 <= time_control <= 30:
        raise ValueError("Time control must be between 1 and 30 minutes.")

    payload = {
        "rated": True,
        "clock.limit": time_control * 60,
        "clock.increment": 0,
        "color": "random",
        "variant": "standard"
    }

    response = requests.post(CREATE_CHALLENGE, headers=auth_headers, data=payload)
    if response.status_code == 200:
        result = response.json()
        logging.info(f"Challenge sent: {result['challenge']['id']}")
        return result['challenge']['id']
    else:
        logging.error(f"Challenge creation failed: {response.status_code} - {response.text}")
        return None

def respond_to_challenge(challenge_identifier):
    """
    Accept an incoming challenge using its ID.
    """
    response = requests.post(ACCEPT_CHALLENGE.format(challenge_id=challenge_identifier), headers=auth_headers)
    if response.status_code == 200:
        game_info = response.json()
        logging.info(f"Challenge accepted: {game_info['challenge']['id']}")
        return game_info['game']['id']
    else:
        logging.error(f"Failed to accept challenge: {response.status_code} - {response.text}")
        return None

def reject_challenge(challenge_identifier):
    """
    Decline an incoming challenge by its ID.
    """
    response = requests.post(REJECT_CHALLENGE.format(challenge_id=challenge_identifier), headers=auth_headers)
    if response.status_code == 200:
        logging.info(f"Challenge declined: {challenge_identifier}")
    else:
        logging.error(f"Failed to decline challenge: {response.status_code} - {response.text}")

