    elif time_control <= 10:
        return "bullet"
    elif time_control <= 15:
        return "blitz"
    else:
        return "rapid"

def execute_move(game_identifier, move_command):
    """
    Submit a move in an active game.
    """
    response = requests.post(SEND_MOVE.format(game_id=game_identifier), headers=auth_headers, data={"move": move_command})
    if response.status_code == 200:
        logging.info(f"Move played: {move_command}")
    else:
        logging.error(f"Move submission failed: {response.status_code} - {response.text}")

def manage_game(game_identifier):
    """
    Monitor and interact with an ongoing game.
    """
    while True:
        try:
            stream_response = requests.get(GAME_STREAM.format(game_id=game_identifier), headers=auth_headers, stream=True)
            if stream_response.status_code == 200:
                for line in stream_response.iter_lines():
                    if line:
