# Class to manage a collection of users with indexing capabilities
class UserDirectory:
    def __init__(self):
        self.people = {}  # Main storage for person data
        self.location_index = {}  # Index for searching by location
        self.reading_index = {}  # Index for searching by books

    def register_person(self, person):
        if person.full_name in self.people:
            raise ValueError(f"Person with name {person.full_name} already registered.")

        self.people[person.full_name] = person
        self._reindex_location(person, 'insert')
        self._reindex_reading(person, 'insert')

    def modify_person(self, person):
        if person.full_name not in self.people:
            raise ValueError(f"Person with name {person.full_name} does not exist.")

        previous_person = self.people[person.full_name]
        self.people[person.full_name] = person
        self._reindex_location(previous_person, 'delete')
        self._reindex_reading(previous_person, 'delete')
        self._reindex_location(person, 'insert')
        self._reindex_reading(person, 'insert')

    def deregister_person(self, full_name):
        if full_name not in self.people:
            raise ValueError(f"Person with name {full_name} does not exist.")

        person = self.people.pop(full_name)
        self._reindex_location(person, 'delete')
        self._reindex_reading(person, 'delete')

    def find_by_location(self, location):
        return [self.people[name] for name in self.location_index.get(location, set())]

    def find_by_book(self, book_title):
        return [self.people[name] for name in self.reading_index.get(book_title, set())]

    def _reindex_location(self, person, operation):
        if operation == 'insert':
            if person.location not in self.location_index:
                self.location_index[person.location] = set()
            self.location_index[person.location].add(person.full_name)
        elif operation == 'delete':
            if person.location in self.location_index:
                self.location_index[person.location].discard(person.full_name)
                if not self.location_index[person.location]:
                    del self.location_index[person.location]

    def _reindex_reading(self, person, operation):
        for title in person.preferred_reads:
            if operation == 'insert':
                if title not in self.reading_index:
                    self.reading_index[title] = set()
                self.reading_index[title].add(person.full_name)
            elif operation == 'delete':
                if title in self.reading_index:
                    self.reading_index[title].discard(person.full_name)
                    if not self.reading_index[title]:
                        del self.reading_index[title]

