# Multi-threaded program to find numbers whose sum of squares of digits is divisible by 17
import threading
from queue import Queue

def calculate_digit_square_sum(value):
    """Compute the sum of squares of each digit in the given number."""
    return sum(int(digit) ** 2 for digit in str(value))

def process_items(item_queue, worker_id):
    """Thread worker that processes numbers from the shared queue."""
    while True:
        current_value = item_queue.get()
        if current_value is None:
            break
        squared_sum = calculate_digit_square_sum(current_value)
        if squared_sum % 17 == 0:
            print(f"Value: {current_value}, Digit square sum: {squared_sum}, Worker: {worker_id}")
        item_queue.task_done()

def run_parallel_processing(values, thread_count):
    """Initialize and manage threads for parallel processing."""
    shared_queue = Queue()
    active_threads = []

    # Launch worker threads
    for idx in range(thread_count):
        worker_thread = threading.Thread(target=process_items, args=(shared_queue, idx))
        worker_thread.start()
        active_threads.append(worker_thread)

    # Add all input values to the queue
    for val in values:
        shared_queue.put(val)

    # Wait for all items to be processed
    shared_queue.join()

    # Signal workers to exit
    for _ in range(thread_count):
        shared_queue.put(None)

    # Wait for all threads to finish
    for worker in active_threads:
        worker.join()

