    num_workers = 4
    run_parallel_processing(input_values, num_workers)

# Calculate factorial with recursive tracing and time measurement
import time

def compute_factorial(value, spacing=""):
    # Base case: if value is 0 or 1, return 1
    if value == 0 or value == 1:
        print(f"{spacing}compute_factorial({value}) = 1 (Base case)")
        return 1
    # Recursive case: value * compute_factorial(value-1)
    else:
        print(f"{spacing}compute_factorial({value}) = {value} * compute_factorial({value-1})")
        output = value * compute_factorial(value-1, spacing + "  ")
        print(f"{spacing}compute_factorial({value}) returns {output}")
        return output

def measure_execution_time(n):
    begin = time.time()
    answer = compute_factorial(n)
    finish = time.time()
    duration = finish - begin
    print(f"\nFactorial of {n} is {answer}")
    print(f"Time taken: {duration:.6f} seconds")
    print(f"Time complexity: O(n) (where n is the input number)")

def run_program():
    try:
        number = int(input("Enter a non-negative integer: "))
        if number < 0:
            print("Factorial is not defined for negative numbers.")
        else:
            measure_execution_time(number)
    except ValueError:
        print("Please enter a valid non-negative integer.")

if __name__ == "__main__":
    run_program()

# Splay a node to the root of the tree
def move_to_root(current_node, tree_root):
    if current_node is None or current_node == tree_root:
        return current_node

    current_parent = tree_root
    grandparent_node = None
    dummy_root = Node()  # Temporary sentinel node to simplify rotation logic
    dummy_root.left = tree_root
    tree_root.parent = dummy_root

    while current_node.parent != dummy_root:
        current_parent = current_node.parent
        grandparent_node = current_parent.parent

        if current_parent.left == current_node:
            if grandparent_node.left == current_parent:
                # Zig-Zig case
                rotate_right(grandparent_node)
                rotate_right(current_parent)
            else:
                # Zig-Zag case
                rotate_right(current_parent)
                rotate_left(current_node)
        else:
            if grandparent_node.right == current_parent:
                # Zig-Zig case
                rotate_left(grandparent_node)
                rotate_left(current_parent)
            else:
                # Zig-Zag case
                rotate_left(current_parent)
                rotate_right(current_node)

    # Finalize the new root assignment
    dummy_root.left.parent = None
    return dummy_root.left

def rotate_right(node_x):
    node_y = node_x.left
    node_x.left = node_y.right
    if node_y.right:
        node_y.right.parent = node_x
    node_y.parent = node_x.parent
    if node_x.parent is None:
        tree_root = node_y
    elif node_x == node_x.parent.right:
        node_x.parent.right = node_y
    else:
        node_x.parent.left = node_y
    node_y.right = node_x
    node_x.parent = node_y

def rotate_left(node_x):
    node_y = node_x.right
    node_x.right = node_y.left
    if node_y.left:
        node_y.left.parent = node_x
    node_y.parent = node_x.parent
    if node_x.parent is None:
        tree_root = node_y
    elif node_x == node_x.parent.left:
        node_x.parent.left = node_y
    else:
        node_x.parent.right = node_y
    node_y.left = node_x
    node_x.parent = node_y

# Parse SQL to extract column and table names
import sqlparse

def get_selected_fields_and_sources(sql_statement):
    parsed_result = sqlparse.parse(sql_statement)
    query_statement = parsed_result[0]

    field_list = []
    source_list = []

    # Identify columns in the SELECT part
    for token_item in query_statement.tokens:
        if isinstance(token_item, sqlparse.sql.IdentifierList):
            for identifier_item in token_item.get_identifiers():
                if '.' in identifier_item.value:
                    field_list.append(identifier_item.value)
        elif isinstance(token_item, sqlparse.sql.Identifier):
            if '.' in token_item.value:
                field_list.append(token_item.value)

    # Identify tables in the FROM part
    from_found = False
    for token_item in query_statement.tokens:
        if isinstance(token_item, sqlparse.sql.Token) and token_item.ttype == sqlparse.tokens.Keyword and token_item.value.upper() == 'FROM':
            from_found = True
        elif from_found and isinstance(token_item, sqlparse.sql.IdentifierList):
            for identifier_item in token_item.get_identifiers():
                source_list.append(identifier_item.value)
            from_found = False
        elif from_found and isinstance(token_item, sqlparse.sql.Identifier):
            source_list.append(token_item.value)
            from_found = False

    return field_list, source_list

