# Implementation of a Binary Search Tree with various operations
from typing import List, Optional

class Node:
    def __init__(self, data: int):
        self.data = data
        self.left_child: Optional['Node'] = None
        self.right_child: Optional['Node'] = None

class BST:
    def __init__(self):
        self._root: Optional[Node] = None

    def insert(self, value: int) -> None:
        if self._root is None:
            self._root = Node(value)
        else:
            self._insert_recursive(self._root, value)

    def _insert_recursive(self, current_node: Node, value: int) -> None:
        if value < current_node.data:
            if current_node.left_child is None:
                current_node.left_child = Node(value)
            else:
                self._insert_recursive(current_node.left_child, value)
        else:
            if current_node.right_child is None:
                current_node.right_child = Node(value)
            else:
                self._insert_recursive(current_node.right_child, value)

    def delete(self, value: int) -> bool:
        self._root, was_deleted = self._delete_recursive(self._root, value)
        return was_deleted

    def _delete_recursive(self, node: Optional[Node], value: int) -> (Optional[Node], bool):
        if node is None:
            return None, False

        if value < node.data:
            node.left_child, deleted = self._delete_recursive(node.left_child, value)
        elif value > node.data:
            node.right_child, deleted = self._delete_recursive(node.right_child, value)
        else:
            # Node found
            if node.left_child is None and node.right_child is None:
                return None, True
            elif node.left_child is None:
                return node.right_child, True
            elif node.right_child is None:
                return node.left_child, True
            else:
                # Two children: find in-order successor (minimum in right subtree)
                successor = self._find_minimum(node.right_child)
                node.data = successor.data
                node.right_child, _ = self._delete_recursive(node.right_child, successor.data)
                deleted = True

        return node, deleted

    def _find_minimum(self, start_node: Node) -> Node:
        current = start_node
        while current.left_child is not None:
            current = current.left_child
        return current

    def contains(self, value: int) -> bool:
        return self._search_recursive(self._root, value)

    def _search_recursive(self, node: Optional[Node], value: int) -> bool:
        if node is None:
            return False

        if value < node.data:
            return self._search_recursive(node.left_child, value)
        elif value > node.data:
            return self._search_recursive(node.right_child, value)
        else:
            return True

    def get_inorder(self) -> List[int]:
        result = []
        self._inorder_traversal(self._root, result)
        return result

    def _inorder_traversal(self, node: Optional[Node], values: List[int]) -> None:
        if node is not None:
            self._inorder_traversal(node.left_child, values)
            values.append(node.data)
            self._inorder_traversal(node.right_child, values)

    def get_preorder(self) -> List[int]:
        result = []
        self._preorder_traversal(self._root, result)
        return result

    def _preorder_traversal(self, node: Optional[Node], values: List[int]) -> None:
        if node is not None:
            values.append(node.data)
            self._preorder_traversal(node.left_child, values)
            self._preorder_traversal(node.right_child, values)

    def get_postorder(self) -> List[int]:
        result = []
        self._postorder_traversal(self._root, result)
        return result

    def _postorder_traversal(self, node: Optional[Node], values: List[int]) -> None:
        if node is not None:
            self._postorder_traversal(node.left_child, values)
            self._postorder_traversal(node.right_child, values)
            values.append(node.data)

    def get_level_order(self) -> List[int]:
        if not self._root:
            return []

        output = []
        queue = [self._root]

        while queue:
            current_node = queue.pop(0)
            output.append(current_node.data)

            if current_node.left_child:
                queue.append(current_node.left_child)
            if current_node.right_child:
                queue.append(current_node.right_child)

        return output

# Define a class for rectangular shapes
class Rect:
    def __init__(self, len_val, wid_val):
        self.set_len(len_val)
        self.set_wid(wid_val)

    def set_len(self, len_val):
        if not isinstance(len_val, (int, float)) or len_val <= 0:
            raise ValueError("Length must be a positive non-zero number.")
        self._len = len_val

    def get_len(self):
        return self._len

    def set_wid(self, wid_val):
        if not isinstance(wid_val, (int, float)) or wid_val <= 0:
            raise ValueError("Width must be a positive non-zero number.")
        self._wid = wid_val

    def get_wid(self):
        return self._wid

    def calc_area(self):
        try:
            return self._len * self._wid
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the area.") from e

    def calc_perimeter(self):
        try:
            return 2 * (self._len + self._wid)
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the perimeter.") from e

    def has_same_area(self, other_shape):
        if not isinstance(other_shape, Rect):
            raise TypeError("The 'other' parameter must be an instance of Rect.")
        return self.calc_area() == other_shape.calc_area()

# Unit tests
