# Process employee data: validate, sort, and export to CSV
import json
import csv
from typing import List, Dict

def check_employee_data(employee: Dict) -> Dict:
    """
    Ensure employee records have valid entries, applying defaults where needed.
    """
    fallback_values = {
        "Name": "",
        "Years": 0,
        "Income": 0,
        "Team": ""
    }

    for field, default_val in fallback_values.items():
        if field not in employee or employee[field] is None:
            employee[field] = default_val
        elif field == "Years" and not isinstance(employee[field], int):
            try:
                employee[field] = int(employee[field])
            except (ValueError, TypeError):
                employee[field] = default_val
        elif field == "Income" and not isinstance(employee[field], (int, float)):
            try:
                employee[field] = float(employee[field])
            except (ValueError, TypeError):
                employee[field] = default_val
    return employee

def order_employees(employees: List[Dict]) -> List[Dict]:
    """
    Arrange employees by age (ascending) and income (ascending).
    """
    return sorted(employees, key=lambda x: (x["Years"], x["Income"]))

def convert_json_to_csv(json_content: str, target_file: str) -> None:
    """
    Transform JSON-formatted employee data into a structured CSV file.
    """
    try:
        employees = json.loads(json_content)
        if not isinstance(employees, list) or not all(isinstance(emp, dict) for emp in employees):
            raise ValueError("Invalid JSON structure. Expected a list of employee dictionaries.")

        # Apply validation and correction to each record
        employees = [check_employee_data(emp) for emp in employees]

        # Sort the employee list
        employees = order_employees(employees)

        # Export to CSV
        with open(target_file, 'w', newline='') as csvfile:
            headers = ["Name", "Years", "Income", "Team"]
            writer = csv.DictWriter(csvfile, fieldnames=headers)
            writer.writeheader()
            for person in employees:
                writer.writerow(person)
    except json.JSONDecodeError as err:
        print(f"JSON parsing failed: {err}")
    except Exception as ex:
        print(f"Processing error: {ex}")

