import requests

# Define the API base URL
API_ENDPOINT = "http://api.example.com"

def execute_api_request(operation, operand1, operand2):
    """Execute the API request for the specified operation with given operands."""
    data = {"a": operand1, "b": operand2}
    endpoint_url = f"{API_ENDPOINT}/{operation}"

    try:
        response = requests.post(endpoint_url, json=data)
        response.raise_for_status()  # Raise an error for bad status codes
        output = response.json()
        return output['result']
    except requests.exceptions.RequestException as err:
        print(f"Network issue: {err}")
        return None
    except (KeyError, ValueError) as err:
        print(f"API problem: {err}")
        return None

def compute_postfix_notation(expression):
    """Compute the postfix expression using an API for each operation."""
    stack = []
    items = expression.split()

    for item in items:
        if item.isdigit():
            stack.append(int(item))
        else:
            if len(stack) < 2:
                print("Error: Insufficient operands for the operation.")
                return None

            second_operand = stack.pop()
            first_operand = stack.pop()

            if item == '+':
                outcome = execute_api_request('add', first_operand, second_operand)
            elif item == '-':
                outcome = execute_api_request('subtract', first_operand, second_operand)
            elif item == '*':
                outcome = execute_api_request('multiply', first_operand, second_operand)
            elif item == '/':
                if second_operand == 0:
                    print("Error: Division by zero.")
                    return None
                outcome = execute_api_request('divide', first_operand, second_operand)
            else:
                print(f"Error: Unknown operator {item}")
                return None

            if outcome is None:
                return None

            stack.append(outcome)

    if len(stack) != 1:
        print("Error: Malformed expression.")
        return None

    return stack[0]

