# Weather data collection and analysis application using Flask and OpenWeatherMap API
import requests
from datetime import datetime, timedelta
from flask import Flask, request, jsonify
from sqlalchemy import create_engine, Column, Integer, String, Float, DateTime
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
from sqlalchemy.exc import SQLAlchemyError

app = Flask(__name__)

# API configuration for OpenWeatherMap
API_KEY = 'REDACTED_CREDENTIAL'

# Database setup
DB_PATH = 'sqlite:///weather.db'
db_engine = create_engine(DB_PATH)
Base = declarative_base()

class WeatherRecord(Base):
    __tablename__ = 'weather_data'
    record_id = Column(Integer, primary_key=True)
    location = Column(String, nullable=False)
    record_time = Column(DateTime, nullable=False)
    temp_value = Column(Float, nullable=False)
    rain_amount = Column(Float, nullable=False)

Base.metadata.create_all(db_engine)
SessionLocal = sessionmaker(bind=db_engine)

class WeatherService:
    def __init__(self, api_key):
        self.api_key = api_key
        self.api_base_url = 'http://api.openweathermap.org/data/2.5/'

    def fetch_current_conditions(self, city_name):
        endpoint_url = f"{self.api_base_url}weather?q={city_name}&appid={self.api_key}&units=metric"
        response = requests.get(endpoint_url)
        if response.status_code == 200:
            weather_info = response.json()
            return {
                'temp': weather_info['main']['temp'],
                'precipitation': weather_info.get('rain', {}).get('1h', 0.0)
            }
        elif response.status_code == 404:
            raise ValueError("City not found")
        else:
            raise Exception(f"Request failed with status code {response.status_code}")

    def fetch_past_weather(self, city_coords, start_timestamp, end_timestamp):
        endpoint_url = f"{self.api_base_url}onecall/timemachine?lat={city_coords['lat']}&lon={city_coords['lon']}&dt={start_timestamp}&appid={self.api_key}&units=metric"
        response = requests.get(endpoint_url)
        if response.status_code == 200:
            weather_data = response.json()
            return weather_data['hourly']
        else:
            raise Exception(f"Request failed with status code {response.status_code}")

    def process_historical_records(self, city_name, period_days=30):
        current_conditions = self.fetch_current_conditions(city_name)
        db_session = SessionLocal()
        try:
            # Check cache for existing data
            existing_records = db_session.query(WeatherRecord).filter_by(location=city_name).all()
            if existing_records:
                return self._compute_statistics(existing_records)
            else:
                # Retrieve historical data
                end_time = int(datetime.now().timestamp())
                start_time = int((datetime.now() - timedelta(days=period_days)).timestamp())
                past_weather = self.fetch_past_weather(city_name, start_time, end_time)

                for record in past_weather:
                    new_entry = WeatherRecord(
                        location=city_name,
                        record_time=datetime.fromtimestamp(record['dt']),
                        temp_value=record['temp'],
                        rain_amount=record.get('rain', {}).get('1h', 0.0)
                    )
                    db_session.add(new_entry)
                db_session.commit()
                return self._compute_statistics(past_weather)
        except Exception as error:
            db_session.rollback()
            raise error
        finally:
            db_session.close()

    def _compute_statistics(self, records):
        sum_temp = 0.0
        sum_rain = 0.0
        for item in records:
            sum_temp += item.temp_value
