# Function to suggest a meal based on available items and menu options
def suggest_meal(stock_items, menu_options):
    # Transform the stock items into a dictionary for efficient access
    stock_dict = {item[0]: item[1] for item in stock_items}

    # Variables to track the selected meal and leftover ingredients
    selected_meal = None
    leftover_ingredients = {}

    for meal_name, needed_ingredients in menu_options.items():
        can_prepare = True
        temp_stock = stock_dict.copy()

        for component, amount in needed_ingredients.items():
            if component not in temp_stock or temp_stock[component] < amount:
                can_prepare = False
                break
            else:
                temp_stock[component] -= amount

        if can_prepare:
            selected_meal = meal_name
            leftover_ingredients = {k: v for k, v in temp_stock.items() if v > 0}
            break

    return selected_meal, leftover_ingredients

