# Calculate various date-related information
from datetime import datetime

def check_leap_year(yr):
    return (yr % 4 == 0 and yr % 100 != 0) or (yr % 400 == 0)

def verify_date(d, m, y):
    if y < 1600 or y > 2100:
        return False
    if m < 1 or m > 12:
        return False
    if d < 1:
        return False
    if m in [4, 6, 9, 11] and d > 30:
        return False
    if m == 2:
        if check_leap_year(y) and d > 29:
            return False
        if not check_leap_year(y) and d > 28:
            return False
    if d > 31:
        return False
    return True

def calculate_weekday(d, m, y):
    if m < 3:
        m += 12
        y -= 1
    k = y % 100
    j = y // 100
    weekday_index = (d + 13 * (m + 1) // 5 + k + k // 4 + j // 4 + 5 * j) % 7
    weekdays = ["Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
    return weekdays[weekday_index]

def day_number_in_year(d, m, y):
    if check_leap_year(y):
        days_per_month = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    else:
        days_per_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    total_days = d
    for idx in range(m - 1):
        total_days += days_per_month[idx]
    return total_days

def process_date(date_input):
    if len(date_input) != 8 or not date_input.isdigit():
        return "Invalid date format. Please use DDMMYYYY."

    day = int(date_input[:2])
    month = int(date_input[2:4])
    year = int(date_input[4:])

    if not verify_date(day, month, year):
        return "Invalid date."

    weekday_name = calculate_weekday(day, month, year)
    day_count = day_number_in_year(day, month, year)

    return f"Day of the week: {weekday_name}, Julian date: {day_count}"

