        "posts": {},
        "comments": {}
    }

    for record in records:
        if record['type'] == 'user':
            user_key = record['user_id']
            structured_model['users'][user_key] = {
                "name": record['name'],
                "email": record['email'],
                "created_at": record['created_at']
            }
        elif record['type'] == 'post':
            post_key = record['post_id']
            user_key = record['user_id']
            structured_model['posts'][post_key] = {
                "user_id": user_key,
                "title": record['title'],
                "content": record['content'],
                "created_at": record['created_at']
            }
            if user_key not in structured_model['users']:
                structured_model['users'][user_key] = {
                    "name": record['user_name'],
                    "email": record['user_email'],
                    "created_at": record['user_created_at']
                }
        elif record['type'] == 'comment':
            comment_key = record['comment_id']
            post_key = record['post_id']
            user_key = record['user_id']
            structured_model['comments'][comment_key] = {
                "post_id": post_key,
