# Journal management system 
class Journal:
    def __init__(self):
        self.logs = []

    def add_log(self, day, heading, content, feeling, condition, place):
        for log in self.logs:
            if log['day'] == day and log['heading'] == heading:
                raise ValueError("A log with the same day and heading already exists.")
        self.logs.append({
            'day': day,
            'heading': heading,
            'content': content,
            'feeling': feeling,
            'condition': condition,
            'place': place
        })

    def remove_log(self, day, heading):
        self.logs = [log for log in self.logs if not (log['day'] == day and log['heading'] == heading)]

    def update_log(self, day, heading, new_content=None, new_feeling=None, new_condition=None, new_place=None):
        for log in self.logs:
            if log['day'] == day and log['heading'] == heading:
                if new_content is not None:
                    log['content'] = new_content
                if new_feeling is not None:
                    log['feeling'] = new_feeling
                if new_condition is not None:
                    log['condition'] = new_condition
                if new_place is not None:
                    log['place'] = new_place
                break

    def get_logs(self, from_date, to_date):
        return [log for log in self.logs if from_date <= log['day'] <= to_date]

