# Calculate minimum number of semesters needed to complete all courses
from collections import defaultdict, deque
from itertools import combinations
from functools import lru_cache

def minNumberOfSemesters(num_courses, prerequisites, max_courses_per_semester):
    # Build adjacency list and in-degree count for each course
    adjacency_list = defaultdict(list)
    in_degree_count = [0] * (num_courses + 1)
    for pre, course in prerequisites:
        adjacency_list[pre].append(course)
        in_degree_count[course] += 1

    # Detect cycles using Kahn's algorithm for topological sorting
    available_courses = deque([course for course in range(1, num_courses + 1) if in_degree_count[course] == 0])
    processed_count = 0
    while available_courses:
        current_course = available_courses.popleft()
        processed_count += 1
        for dependent_course in adjacency_list[current_course]:
            in_degree_count[dependent_course] -= 1
            if in_degree_count[dependent_course] == 0:
                available_courses.append(dependent_course)

    if processed_count < num_courses:
        return -1  # Cycle detected, impossible to complete all courses

    # Dynamic Programming with memoization
    @lru_cache(None)
    def solve(state_mask):
        if state_mask == 0:
            return 0

        result = float('inf')
        # Get all available courses in current state
        available = [course for course in range(1, num_courses + 1) if state_mask & (1 << (course - 1))]

        # Try all possible subsets of available courses up to max_courses_per_semester
        for selected_courses in combinations(available, min(max_courses_per_semester, len(available))):
            # Check if all selected courses have zero in-degree (prerequisites met)
            can_take_all = True
            for course in selected_courses:
                if in_degree_count[course] > 0:
                    can_take_all = False
                    break

            if can_take_all:
                # Update mask and in-degrees after taking these courses
                updated_mask = state_mask
                for course in selected_courses:
                    updated_mask ^= (1 << (course - 1))
                    for next_course in adjacency_list[course]:
                        in_degree_count[next_course] -= 1

                # Recursively solve for remaining courses
                result = min(result, 1 + solve(updated_mask))

                # Backtrack: restore in-degrees
                for course in selected_courses:
                    for next_course in adjacency_list[course]:
                        in_degree_count[next_course] += 1

        return result

    # Start with all courses remaining (all bits set)
    return solve((1 << num_courses) - 1)

# Example usage
print(minNumberOfSemesters(4, [[1, 2], [2, 3], [3, 4]], 2))  # Output: 2
print(minNumberOfSemesters(4, [[1, 2], [2, 3], [3, 4]], 1))  # Output: 4
print(minNumberOfSemesters(3, [[1, 2], [2, 3], [3, 1]], 2))  # Output: -1

