import threading
import time

# Function to be executed by each worker thread
def worker_function(worker_id):
    print(f"Worker {worker_id} is starting")
    # Simulate some processing
    while True:
        # Simulate activity
        print(f"Worker {worker_id} is active")
        time.sleep(5)  # Simulate work by sleeping for 5 seconds

        # Check if the worker should terminate
        if shutdown_workers[worker_id]:
            print(f"Worker {worker_id} is terminating")
            break

# Function to watch over threads and shut them down if idle for more than 30 seconds
def watch_threads(thread_list, shutdown_workers):
    while True:
        for worker_id, thread in enumerate(thread_list):
            if not thread.is_alive():
                continue
            if time.time() - last_active_time[worker_id] > 30:
                print(f"Worker {worker_id} has been idle for more than 30 seconds, shutting it down")
                shutdown_workers[worker_id] = True
                thread.join()
        time.sleep(1)  # Perform checks every second

# Main function to launch the workers and the watchdog
def main():
    num_workers = 100
    thread_list = []
    shutdown_workers = [False] * num_workers
    last_active_time = [time.time()] * num_workers

    # Create and start the worker threads
    for idx in range(num_workers):
        thread = threading.Thread(target=worker_function, args=(idx,))
        thread_list.append(thread)
        thread.start()

    # Start the watchdog thread
    watchdog_thread = threading.Thread(target=watch_threads, args=(thread_list, shutdown_workers))
    watchdog_thread.start()

    # Keep the main thread running
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Main thread interrupted, shutting down all workers")
        for idx in range(num_workers):
            shutdown_workers[idx] = True
        for thread in thread_list:
            thread.join()
        watchdog_thread.join()

if __name__ == "__main__":
    main()

# Determine if a sequence is arithmetic or geometric
def check_arithmetic_progression(seq):
    if len(seq) < 2:
        return False, None
    diff = seq[1] - seq[0]
    for idx in range(2, len(seq)):
        if seq[idx] - seq[idx - 1] != diff:
            return False, None
    return True, diff

def check_geometric_progression(seq):
    if len(seq) < 2 or 0 in seq:
        return False, None
    ratio = seq[1] / seq[0]
    for idx in range(2, len(seq)):
        if seq[idx] / seq[idx - 1] != ratio:
            return False, None
    return True, ratio

def classify_sequence(seq):
    arithmetic, diff = check_arithmetic_progression(seq)
    geometric, ratio = check_geometric_progression(seq)

    if arithmetic:
        return "Arithmetic", diff
    elif geometric:
        return "Geometric", ratio
    else:
        return "Neither", None

