            'hashed_password': hashed_password,
            'is_verified': is_verified
        })
        db_client.put(new_account)
        return cls(email_address, hashed_password, is_verified)

# Definition for a node in a singly linked list
class ListNode:
    def __init__(self, value):
        self.value = value
        self.next = None

class SinglyLinkedList:
    def __init__(self):
        self.start = None

    def add_to_end(self, value):
        new_node = ListNode(value)
        if self.start is None:
            self.start = new_node
        else:
            current_node = self.start
            while current_node.next:
                current_node = current_node.next
            current_node.next = new_node

    def show(self):
        current_node = self.start
        while current_node:
            print(current_node.value, end=" -> ")
            current_node = current_node.next
        print("None")

    def add_to_front(self, value):
        new_node = ListNode(value)
        new_node.next = self.start
        self.start = new_node

    def remove(self, target_value):
        current_node = self.start
        if current_node and current_node.value == target_value:
            self.start = current_node.next
            current_node = None
            return
        previous_node = None
        while current_node and current_node.value != target_value:
            previous_node = current_node
            current_node = current_node.next
        if current_node is None:
            return
        previous_node.next = current_node.next
        current_node = None

# Demonstration of usage
if __name__ == "__main__":
    sll = SinglyLinkedList()
    sll.add_to_end(1)
    sll.add_to_end(2)
    sll.add_to_end(3)
    sll.add_to_front(0)
    sll.show()  # Output: 0 -> 1 -> 2 -> 3 -> None
    sll.remove(2)
    sll.show()  # Output: 0 -> 1 -> 3 -> None

# Define a node for the binary search tree
class TreeNode:
    def __init__(self, value):
        self.left_child = None
        self.right_child = None
        self.data = value

class BinarySearchTreeImplementation:
    def __init__(self):
        self.head = None

    def add(self, value):
        if self.head is None:
            self.head = TreeNode(value)
        else:
            self._add(self.head, value)

    def _add(self, current_node, value):
        if value < current_node.data:
            if current_node.left_child is None:
                current_node.left_child = TreeNode(value)
            else:
                self._add(current_node.left_child, value)
        elif value > current_node.data:
            if current_node.right_child is None:
                current_node.right_child = TreeNode(value)
            else:
                self._add(current_node.right_child, value)
        # Skip insertion if value already exists (avoid duplicates)

    def find(self, value):
        return self._find(self.head, value)

    def _find(self, current_node, value):
        if current_node is None or current_node.data == value:
            return current_node
        if value < current_node.data:
            return self._find(current_node.left_child, value)
        return self._find(current_node.right_child, value)

    def in_order(self):
        return self._in_order(self.head, [])

    def _in_order(self, current_node, output_list):
        if current_node:
            self._in_order(current_node.left_child, output_list)
            output_list.append(current_node.data)
            self._in_order(current_node.right_child, output_list)
        return output_list

    def pre_order(self):
        return self._pre_order(self.head, [])

    def _pre_order(self, current_node, output_list):
        if current_node:
            output_list.append(current_node.data)
            self._pre_order(current_node.left_child, output_list)
            self._pre_order(current_node.right_child, output_list)
        return output_list

    def post_order(self):
        return self._post_order(self.head, [])

    def _post_order(self, current_node, output_list):
        if current_node:
            self._post_order(current_node.left_child, output_list)
            self._post_order(current_node.right_child, output_list)
            output_list.append(current_node.data)
        return output_list

