def pull_out_chars(text_list):
    output = {}
    fallback_value = 'N/A'

    for text in text_list:
        if not isinstance(text, str):
            output[text] = "Error: Input must be a string."
            continue

        # Get the 9th, 10th, and 11th characters
        char_list = []
        for pos in [8, 9, 10]:  # Python uses 0-based indexing
            if pos < len(text):
                char_list.append(text[pos])
            else:
                char_list.append(fallback_value)

        output[text] = char_list

    return output

