# Calculate lateral surface area and volume for various frustum types
import numpy as np
from scipy.integrate import quad
from concurrent.futures import ThreadPoolExecutor
from functools import partial

def check_input(r1, r2, h, slant_height, major_r1=None, minor_r1=None, major_r2=None, minor_r2=None):
    if r1 < 0 or r2 < 0 or h < 0 or slant_height < 0:
        raise ValueError("All radii, height, and slant height must be non-negative.")
    if major_r1 is not None and minor_r1 is not None and major_r2 is not None and minor_r2 is not None:
        if major_r1 < 0 or minor_r1 < 0 or major_r2 < 0 or minor_r2 < 0:
            raise ValueError("All elliptical radii must be non-negative.")

def lateral_area_circular(r1, r2, slant_height):
    return np.pi * (r1 + r2) * slant_height

def volume_circular(r1, r2, h):
    return (1/3) * np.pi * h * (r1**2 + r2**2 + r1*r2)

def lateral_area_elliptical(major_r1, minor_r1, major_r2, minor_r2, slant_height):
    a = (major_r1 + major_r2) / 2
    b = (minor_r1 + minor_r2) / 2
    return 2 * np.pi * (a + b) * slant_height

def volume_elliptical(major_r1, minor_r1, major_r2, minor_r2, h):
    A1 = np.pi * major_r1 * minor_r1
    A2 = np.pi * major_r2 * minor_r2
    return (1/3) * h * (A1 + A2 + np.sqrt(A1 * A2))

def lateral_area_variable(base_shape_func, slant_height, h, n=1000):
    def integrand(z):
        r = base_shape_func(z)
        return 2 * np.pi * r * np.sqrt(1 + (base_shape_func(z + h/n) - base_shape_func(z - h/n))**2)
    return quad(integrand, 0, h)[0]

def volume_variable(base_shape_func, h, n=1000):
    def integrand(z):
        r = base_shape_func(z)
        return np.pi * r**2
    return quad(integrand, 0, h)[0]

def handle_frustum(frustum_data):
    r1, r2, h, slant_height, major_r1, minor_r1, major_r2, minor_r2, base_shape_func = frustum_data
    check_input(r1, r2, h, slant_height, major_r1, minor_r1, major_r2, minor_r2)

    if base_shape_func is None:
        if major_r1 is None and minor_r1 is None and major_r2 is None and minor_r2 is None:
            # Circular frustum
            lateral_surface_area = lateral_area_circular(r1, r2, slant_height)
            volume = volume_circular(r1, r2, h)
        else:
            # Elliptical frustum
            lateral_surface_area = lateral_area_elliptical(major_r1, minor_r1, major_r2, minor_r2, slant_height)
            volume = volume_elliptical(major_r1, minor_r1, major_r2, minor_r2, h)
    else:
        # Non-uniform frustum
        lateral_surface_area = lateral_area_variable(base_shape_func, slant_height, h)
        volume = volume_variable(base_shape_func, h)

    return lateral_surface_area, volume

def process_multiple_frustums(frustum_list, max_workers=10):
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        results = list(executor.map(handle_frustum, frustum_list))
    return results

# Example usage
