import heapq

def shortest_path(graph, source, target):
    # Priority queue to store (distance, node) pairs
    heap = [(0, source)]
    # Dictionary to store the shortest distances from the source node
    dist = {node: float('infinity') for node in graph}
    dist[source] = 0
    # Dictionary to store the path
    prev = {node: None for node in graph}

    while heap:
        current_dist, current_node = heapq.heappop(heap)

        # If we've reached the target node, we can stop
        if current_node == target:
            route = []
            while current_node is not None:
                route.append(current_node)
                current_node = prev[current_node]
            return route[::-1], dist[target]

        # If the current distance is greater than the known shortest distance, skip
        if current_dist > dist[current_node]:
            continue

        for adjacent, cost in graph[current_node].items():
            new_distance = current_dist + cost

            # Only consider this new path if it's better
            if new_distance < dist[adjacent]:
                dist[adjacent] = new_distance
                prev[adjacent] = current_node
                heapq.heappush(heap, (new_distance, adjacent))

    return None, float('infinity')

