# Import necessary libraries
import numpy as np

def initialize_grid():
    return np.zeros((6, 7))

def can_place(board, column):
    return board[5][column] == 0

def place_piece(board, column, piece):
    for row in range(6):
        if board[row][column] == 0:
            board[row][column] = piece
            break

def has_won(board, piece):
    # Check horizontal locations for win
    for c in range(4):
        for r in range(6):
            if board[r][c] == piece and board[r][c+1] == piece and board[r][c+2] == piece and board[r][c+3] == piece:
                return True
    # Check vertical locations for win
    for c in range(7):
        for r in range(3):
            if board[r][c] == piece and board[r+1][c] == piece and board[r+2][c] == piece and board[r+3][c] == piece:
                return True
    # Check positively sloped diagonals
    for c in range(4):
        for r in range(3):
            if board[r][c] == piece and board[r+1][c+1] == piece and board[r+2][c+2] == piece and board[r+3][c+3] == piece:
                return True
    # Check negatively sloped diagonals
    for c in range(4):
        for r in range(3, 6):
            if board[r][c] == piece and board[r-1][c+1] == piece and board[r-2][c+2] == piece and board[r-3][c+3] == piece:
                return True
    return False

def is_board_full(board):
    return np.all(board != 0)

def computer_move(board, piece):
    for i in range(7):
        temp_board = board.copy()
        if can_place(temp_board, i):
            place_piece(temp_board, i, piece)
            if has_won(temp_board, piece):
                place_piece(board, i, piece)
                return
    for i in range(7):
        temp_board = board.copy()
        if can_place(temp_board, i):
            place_piece(temp_board, i, 3 - piece)  # 3 - piece is the opponent
            if has_won(temp_board, 3 - piece):
                place_piece(board, i, piece)
                return
    while True:
        col = np.random.choice(7)
        if can_place(board, col):
            place_piece(board, col, piece)
            break

# Game setup
grid = initialize_grid()
current_player = 1
end_game = False

# Main game loop
while not end_game:
    if current_player == 1:
        move = int(input("Player 1, make your move (0-6): "))
        if can_place(grid, move):
            place_piece(grid, move, current_player)
            if has_won(grid, current_player):
                print("Player 1 wins!")
                end_game = True
        else:
            print("Invalid move, try again.")
    else:
        print("Computer is thinking...")
        computer_move(grid, current_player)
        if has_won(grid, current_player):
            print("Computer wins!")
            end_game = True

    if is_board_full(grid):
        print("The game is a draw!")
        end_game = True

    current_player = 3 - current_player  # Switch player
    print(grid)

# Import required modules for date parsing and manipulation
from dateutil import parser
from dateutil.relativedelta import relativedelta
from datetime import datetime

def extract_year(date_string):
    """
    Extract the year from a date string, supporting various calendar formats.
    """
    try:
        parsed_date = parser.parse(date_string)
        return parsed_date.year
    except ValueError:
        return None

def determine_initial_publication_year(book_editions):
    """
    Identify the earliest publication year from a collection of book editions.
    """
    valid_years = [extract_year(edition['year']) for edition in book_editions if extract_year(edition['year']) is not None]
    return min(valid_years) if valid_years else None

def select_books_by_release_year(books_collection, cutoff_year=1980):
    """
    Select books released after a specified year, based on their first publication date.
    """
    selected_books = []
    for book in books_collection:
        initial_year = determine_initial_publication_year(book['editions'])
        if initial_year and initial_year > cutoff_year:
            selected_books.append(book)
    return selected_books

