# Function to find the maximum and second maximum values along with their indices
def locate_largest_and_next_largest(sequence):
    if len(sequence) < 2:
        return None, None  # Insufficient elements to determine both largest and second largest

    # Set initial largest and second largest values and positions
    if sequence[0] > sequence[1]:
        largest_val, next_largest_val = sequence[0], sequence[1]
        largest_pos, next_largest_pos = 0, 1
    else:
        largest_val, next_largest_val = sequence[1], sequence[0]
        largest_pos, next_largest_pos = 1, 0

    # Process remaining elements starting from index 2
    for idx in range(2, len(sequence)):
        if sequence[idx] > largest_val:
            next_largest_val, next_largest_pos = largest_val, largest_pos
            largest_val, largest_pos = sequence[idx], idx
        elif sequence[idx] > next_largest_val:
            next_largest_val, next_largest_pos = sequence[idx], idx

    return (largest_val, largest_pos), (next_largest_val, next_largest_pos)

