# Parallel unit test execution using multiprocessing
import unittest
import multiprocessing

class DistributedTestExecutor:
    def __init__(self, test_discoverer, worker_count=None):
        self.test_discoverer = test_discoverer
        self.worker_count = worker_count or multiprocessing.cpu_count()

    def execute(self, test_collection):
        individual_tests = []
        for single_test in test_collection:
            individual_tests.append(single_test)

        with multiprocessing.Pool(processes=self.worker_count) as pool:
            outcomes = pool.map(self.execute_single_test, individual_tests)

        for outcome in outcomes:
            if outcome.failures or outcome.errors:
                return outcome

    def execute_single_test(self, test_case):
        outcome = unittest.TestResult()
        test_case.run(outcome)
        return outcome

if __name__ == "__main__":
    discoverer = unittest.TestLoader()
    collection = discoverer.discover('test_cases')  # Replace 'test_cases' with your test directory

    executor = DistributedTestExecutor(discoverer)
    executor.execute(collection)

# Calculate prime factorization using optimized methods
import random
import math

def compute_gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_prime_miller_rabin(num, iterations=5):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0:
        return False

    r, s = 0, num - 1
    while s % 2 == 0:
        r += 1
        s //= 2

    for _ in range(iterations):
        base = random.randrange(2, num - 1)
        x = pow(base, s, num)
        if x == 1 or x == num - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, num)
            if x == num - 1:
                break
        else:
            return False
    return True

def pollard_brent_factor(n):
    if n % 2 == 0:
        return 2
    y, c, m = random.randint(1, n-1), random.randint(1, n-1), random.randint(1, n-1)
    g, r, q_val = 1, 1, 1
    while g == 1:
        x = y
        for _ in range(r):
            y = (pow(y, 2, n) + c) % n
        k = 0
        while k < r and g == 1:
            ys = y
            for _ in range(min(m, r - k)):
                y = (pow(y, 2, n) + c) % n
                q_val = q_val * abs(x - y) % n
            g = compute_gcd(q_val, n)
            k += m
        r *= 2
    if g == n:
        while True:
            ys = (pow(ys, 2, n) + c) % n
            g = compute_gcd(abs(x - ys), n)
            if g > 1:
                break
    return g

def generate_primes(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.sqrt(limit)) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False
    return [i for i in range(2, limit + 1) if is_prime[i]]

def get_prime_factors(number):
    factors_list = []
    if number <= 1:
        return factors_list

    # Use precomputed small primes for trial division
    small_primes = generate_primes(1000)
    for p in small_primes:
        while number % p == 0:
            factors_list.append(p)
            number //= p
        if number == 1:
            break

    # Apply Pollard-Brent for larger remaining factors
    while number > 1:
        if is_prime_miller_rabin(number):
            factors_list.append(number)
            break
        divisor = pollard_brent_factor(number)
        if divisor == number:
            factors_list.append(number)
            break
        factors_list.append(divisor)
        number //= divisor

    return factors_list

