# Process JSON data to compute statistics for female ages
import json

def process_female_ages(json_input, result_filename):
    # Collect ages of individuals identified as female
    female_years = [individual['age'] for individual in json_input if individual['gender'] == 'female']

    # Handle scenario with no female entries
    if not female_years:
        output = {
            "mean_age": None,
            "middle_age": None
        }
        with open(result_filename, 'w') as file:
            json.dump(output, file, indent=4)
        return output

    # Compute average (mean) age
    mean_age = sum(female_years) / len(female_years)

    # Determine median age
    female_years.sort()
    count = len(female_years)
    if count % 2 == 1:
        middle_age = female_years[count // 2]
    else:
        middle_age = (female_years[count // 2 - 1] + female_years[count // 2]) / 2

    # Compile final results
    output = {
        "mean_age": mean_age,
        "middle_age": middle_age
    }

    # Save results to specified file
    with open(result_filename, 'w') as file:
        json.dump(output, file, indent=4)

    return output

