# Modified version with renamed variables and reordered logic
import threading
import types
from collections.abc import Mapping, Iterable

class CustomDataType:
    pass  # Placeholder for custom data types

def is_custom_type(value):
    return isinstance(value, (type, types.ModuleType, types.FunctionType, threading.Thread, CustomDataType))

def analyze_structure(obj, visited=None):
    if visited is None:
        visited = set()

    obj_id = id(obj)
    if obj_id in visited:
        return (True, 0, 0, 0)  # (is_empty, empty_containers, total_elements, special_types)

    visited.add(obj_id)

    is_completely_empty = True
    empty_containers = 0
    total_elements = 0
    special_types_count = 0

    if isinstance(obj, Mapping):
        if len(obj) == 0:
            empty_containers += 1
        else:
            is_completely_empty = False
            for k, v in obj.items():
                total_elements += 1
                if is_custom_type(v):
                    special_types_count += 1
                else:
                    sub_analysis = analyze_structure(v, visited)
                    is_completely_empty &= sub_analysis[0]
                    empty_containers += sub_analysis[1]
                    total_elements += sub_analysis[2]
                    special_types_count += sub_analysis[3]
    elif isinstance(obj, Iterable) and not isinstance(obj, (str, bytes)):
        for element in obj:
            sub_analysis = analyze_structure(element, visited)
            is_completely_empty &= sub_analysis[0]
            empty_containers += sub_analysis[1]
            total_elements += sub_analysis[2]
            special_types_count += sub_analysis[3]

    return (is_completely_empty, empty_containers, total_elements, special_types_count)

def validate_container_state(container):
    try:
        outcome = analyze_structure(container)
        return (outcome[0], outcome[1], outcome[2], outcome[3])
    except Exception as error:
        return f"Error: {str(error)}"

