# Import the math module for potential future use
import math

def perform_addition(x, y):
    """Compute the sum of two numbers."""
    return x + y

def perform_subtraction(x, y):
    """Subtract the second number from the first."""
    return x - y

def perform_multiplication(x, y):
    """Multiply two numbers together."""
    return x * y

def perform_division(x, y):
    """Divide the first number by the second. Returns a tuple (result, error) where error is None if no error occurs."""
    if y == 0:
        return None, "Division by zero is not permitted."
    return x / y, None

def perform_power(base, exp):
    """Raise base to the power of exp."""
    return base ** exp

def perform_modulus(x, y):
    """Compute x modulo y. Returns a tuple (result, error) where error is None if no error occurs."""
    if y == 0:
        return None, "Modulo by zero is not permitted."
    return x % y, None

def compute_nth_root(value, degree):
    """Calculate the nth root of a number."""
    if value < 0 and degree % 2 == 0:
        return None, "Cannot compute even root of a negative number."
    return value ** (1/degree), None

def display_output(action, first, second, output, err=None):
    """Display the outcome of a calculation."""
    if err:
        print(f"Error: {err}")
    else:
        print(f"Outcome of {first} {action} {second} = {output}")

def run_calculator():
    calc_functions = {
        "addition": perform_addition,
        "subtraction": perform_subtraction,
        "multiplication": perform_multiplication,
        "division": perform_division,
        "power": perform_power,
        "modulus": perform_modulus,
        "nth_root": compute_nth_root
    }

    while True:
        print("\nAvailable operations:")
        print("1. Addition")
        print("2. Subtraction")
        print("3. Multiplication")
        print("4. Division")
        print("5. Power")
        print("6. Modulus")
        print("7. Nth Root")
        print("8. Quit")

        selection = input("Enter the number corresponding to the operation you want to execute (1-8): ")

        if selection == '8':
            print("Terminating the application.")
            break

        if selection not in ['1', '2', '3', '4', '5', '6', '7']:
            print("Invalid selection. Please choose a number between 1 and 8.")
            continue

        num1 = float(input("Input the first value: "))
        num2 = float(input("Input the second value: "))

        if selection == '7':
            res, msg = compute_nth_root(num1, num2)
        elif selection == '4':
            res, msg = perform_division(num1, num2)
        elif selection == '6':
            res, msg = perform_modulus(num1, num2)
        else:
            selected_op = list(calc_functions.keys())[int(selection) - 1]
            res = calc_functions[selected_op](num1, num2)
            msg = None

        if selection == '7':
            display_output("nth root", num1, num2, res, msg)
        elif selection == '4':
            display_output("division", num1, num2, res, msg)
        elif selection == '6':
            display_output("modulo", num1, num2, res, msg)
        else:
            display_output(selected_op, num1, num2, res)

