# Employee management system implementation
class StaffMember: 
    def __init__(self, full_name, years): 
        self.full_name = full_name
        self.years = years

    def __str__(self):
        return f"{self.full_name} (Years: {self.years})"

class StaffManager:
    def __init__(self):
        self.staff_members = []

    def add_staff(self, full_name, years):
        if not full_name or not years:
            raise ValueError("Full name and years are required.")
        if not isinstance(years, int) or years <= 0:
            raise ValueError("Years must be a positive integer.")
        self.staff_members.append(StaffMember(full_name, years))
        print(f"Staff member {full_name} added successfully.")

    def remove_staff(self, full_name):
        for staff in self.staff_members:
            if staff.full_name == full_name:
                self.staff_members.remove(staff)
                print(f"Staff member {full_name} removed successfully.")
                return
        raise ValueError(f"Staff member {full_name} not found.")

    def update_years(self, full_name, new_years):
        if not new_years or not isinstance(new_years, int) or new_years <= 0:
            raise ValueError("New years must be a positive integer.")
        for staff in self.staff_members:
            if staff.full_name == full_name:
                staff.years = new_years
                print(f"Staff member {full_name}'s years updated to {new_years}.")
                return
        raise ValueError(f"Staff member {full_name} not found.")

    def list_staff(self):
        if not self.staff_members:
            print("No staff members in the list.")
            return
        sorted_staff = sorted(self.staff_members, key=lambda x: x.full_name)
        for staff in sorted_staff:
            print(staff)

    def average_years(self):
        if not self.staff_members:
            print("No staff members in the list.")
            return 0
        total_years = sum(staff.years for staff in self.staff_members)
        return total_years / len(self.staff_members)

def main():
    manager = StaffManager()
    while True:
        print("\nStaff Management System")
        print("1. Add Staff Member")
        print("2. Remove Staff Member")
        print("3. Update Staff Member Years")
        print("4. List Staff Members")
        print("5. Average Years of Staff Members")
        print("6. Exit")
        option = input("Enter your option: ")

        try:
            option = int(option)
            if option == 1:
                full_name = input("Enter staff member full name: ")
                years = int(input("Enter staff member years: "))
                manager.add_staff(full_name, years)
            elif option == 2:
                full_name = input("Enter staff member full name to remove: ")
                manager.remove_staff(full_name)
            elif option == 3:
                full_name = input("Enter staff member full name to update years: ")
                new_years = int(input("Enter new years: "))
                manager.update_years(full_name, new_years)
            elif option == 4:
                manager.list_staff()
            elif option == 5:
                avg_years = manager.average_years()
                print(f"Average years of staff members: {avg_years:.2f}")
            elif option == 6:
                print("Exiting the program.")
                break
            else:
