# Function to count non-nested occurrences of a character
def count_non_nested_chars(text, target):
    def within_ignored_zone(pos):
        # Determine if position is inside parentheses, brackets, or quotes
        for begin, finish in exclusion_zones:
            if begin <= pos <= finish:
                return True
        return False

    exclusion_zones = []
    bracket_stack = []
    inside_quotes = False
    quote_symbol = None

    # Initial scan: locate excluded regions (brackets, parentheses, and string literals)
    for idx, symbol in enumerate(text):
        if symbol in '([':
            bracket_stack.append((idx, symbol))
        elif symbol in ')]':
            if bracket_stack and ((symbol == ')' and bracket_stack[-1][1] == '(') or 
                                  (symbol == ']' and bracket_stack[-1][1] == '[')):
                start_idx, _ = bracket_stack.pop()
                exclusion_zones.append((start_idx, idx))
        elif symbol in '"\'':
            if inside_quotes and symbol == quote_symbol:
                inside_quotes = False
                exclusion_zones.append((start_quote_pos, idx))
            elif not inside_quotes:
                inside_quotes = True
                start_quote_pos = idx
                quote_symbol = symbol

    occurrence_count = 0
    previous_char = None

    # Second scan: tally valid character instances
    for idx, symbol in enumerate(text):
        if within_ignored_zone(idx):
            continue

        if symbol == target and previous_char != target and (idx == len(text) - 1 or text[idx + 1] != target):
            occurrence_count += 1

        previous_char = symbol

    return occurrence_count

