# Mahjong hand evaluation logic
class MahJonggHand:
    def __init__(self, card_list):
        self.tiles = card_list
        self.score_categories = {'pungs': 0, 'kongs': 0, 'chows': 0, 'pairs': 0}
        self.hand_types = {
            'Thirteen Orphans': self.check_thirteen_orphans,
            'Seven Pairs': self.check_seven_pairs,
            'All Pungs': self.check_all_pungs,
            'All Chows': self.check_all_chows,
            'Mixed Shifted Chows': self.check_mixed_shifted_chows,
            'All Terminals and Honors': self.check_all_terminals_and_honors,
            'All Simples': self.check_all_simples,
            'Half Flush': self.check_half_flush,
            'Full Flush': self.check_full_flush
        }

    def check_thirteen_orphans(self):
        # Verify Thirteen Orphans pattern
        needed_tiles = ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B']
        has_all = all(card in self.tiles for card in needed_tiles)
        first_tile_count = self.tiles.count(self.tiles[0])
        return has_all and first_tile_count == 2

    def check_seven_pairs(self):
        # Verify Seven Pairs pattern
        unique_pairs = set([tile for tile in self.tiles if self.tiles.count(tile) == 2])
        return len(unique_pairs) == 7

    def check_all_pungs(self):
        # Verify All Pungs pattern
        return all(self.tiles.count(tile) == 3 for tile in self.tiles) and len(set(self.tiles)) == 4

    def check_all_chows(self):
        # Verify All Chows pattern
        return all(self.tiles.count(tile) == 3 for tile in self.tiles) and len(set(self.tiles)) == 4

    def check_mixed_shifted_chows(self):
        # Verify Mixed Shifted Chows pattern
        return False  # Placeholder for implementation

    def check_all_terminals_and_honors(self):
        # Verify All Terminals and Honors pattern
        terminal_honor_set = ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B']
        return all(tile in terminal_honor_set for tile in self.tiles)

    def check_all_simples(self):
        # Verify All Simples pattern
        simple_tiles = ['2m', '3m', '4m', '5m', '6m', '7m', '8m', '2p', '3p', '4p', '5p', '6p', '7p', '8p', '2s', '3s', '4s', '5s', '6s', '7s', '8s']
        return all(tile in simple_tiles for tile in self.tiles)

    def check_half_flush(self):
        # Verify Half Flush pattern
        suit_list = set([tile[-1] for tile in self.tiles])
        return len(suit_list) == 2

    def check_full_flush(self):
        # Verify Full Flush pattern
        suit_list = set([tile[-1] for tile in self.tiles])
        return len(suit_list) == 1

# Chat application using Flask and SQLite database
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///chat_app.db'
database = SQLAlchemy(app)

class Conversation(database.Model):
    id = database.Column(database.Integer, primary_key=True)
    title = database.Column(database.String(100), nullable=False)
    summary = database.Column(database.String(255))
    created_on = database.Column(database.DateTime, default=datetime.utcnow)

class ChatMessage(database.Model):
    id = database.Column(database.Integer, primary_key=True)
    conversation_id = database.Column(database.Integer, database.ForeignKey('conversation.id'), nullable=False)
    author_id = database.Column(database.Integer, nullable=False)
    text = database.Column(database.Text, nullable=False)
    timestamp = database.Column(database.DateTime, default=datetime.utcnow)

class Participant(database.Model):
    id = database.Column(database.Integer, primary_key=True)
    handle = database.Column(database.String(100), nullable=False)

class ConversationMember(database.Model):
    conversation_id = database.Column(database.Integer, database.ForeignKey('conversation.id'), primary_key=True)
    participant_id = database.Column(database.Integer, database.ForeignKey('participant.id'), primary_key=True)
    added_at = database.Column(database.DateTime, default=datetime.utcnow)

@app.route('/conversations', methods=['POST'])
def create_conversation():
    payload = request.json
    new_conversation = Conversation(title=payload['title'], summary=payload['summary'])
    database.session.add(new_conversation)
    database.session.commit()
    return jsonify({
        "id": new_conversation.id,
        "title": new_conversation.title,
        "summary": new_conversation.summary,
        "created_on": new_conversation.created_on
    }), 201

@app.route('/conversations', methods=['GET'])
def get_conversations():
    current_page = request.args.get('page', 1, type=int)
    items_per_page = request.args.get('limit', 10, type=int)
    conversations = Conversation.query.paginate(current_page, items_per_page, error_out=False)
    return jsonify({
        "conversations": [conv.to_dict() for conv in conversations.items],
        "total": conversations.total
    })

@app.route('/conversations/<int:conversation_id>/messages', methods=['POST'])
def post_message(conversation_id):
    payload = request.json
    new_message = ChatMessage(conversation_id=conversation_id, author_id=payload['author_id'], text=payload['text'])
    database.session.add(new_message)
    database.session.commit()
    return jsonify({
        "id": new_message.id,
        "conversation_id": new_message.conversation_id,
        "author_id": new_message.author_id,
        "text": new_message.text,
        "timestamp": new_message.timestamp
    }), 201

@app.route('/conversations/<int:conversation_id>/messages', methods=['GET'])
def retrieve_messages(conversation_id):
    current_page = request.args.get('page', 1, type=int)
    items_per_page = request.args.get('limit', 10, type=int)
    messages = ChatMessage.query.filter_by(conversation_id=conversation_id).paginate(current_page, items_per_page, error_out=False)
    return jsonify({
        "messages": [msg.to_dict() for msg in messages.items],
        "total": messages.total
    })

@app.route('/conversations/<int:conversation_id>/memberships', methods=['POST'])
def add_member(conversation_id):
    payload = request.json
    new_membership = ConversationMember(conversation_id=conversation_id, participant_id=payload['participant_id'])
    database.session.add(new_membership)
    database.session.commit()
    return jsonify({
        "conversation_id": new_membership.conversation_id,
        "participant_id": new_membership.participant_id,
        "added_at": new_membership.added_at
    }), 201

@app.route('/conversations/<int:conversation_id>/members', methods=['GET'])
def get_members(conversation_id):
    members = ConversationMember.query.filter_by(conversation_id=conversation_id).all()
    return jsonify({
        "members": [member.to_dict() for member in members]
    })

if __name__ == '__main__':
    database.create_all()
    app.run(debug=True)

# Educational Management System Implementation
class VirtualLearningEnvironment:
    def __init__(self):
        self.enrollees = {}  # Dictionary to store student data
        self.subjects = {}   # Dictionary to store course data

    # Student Management Functions
    def register_student(self, student_identifier, full_name):
        if student_identifier in self.enrollees:
            raise ValueError(f"Student with ID {student_identifier} already exists.")
        self.enrollees[student_identifier] = {
            'name': full_name,
            'subjects': {},
            'overall_grade': 0.0
        }

    def deregister_student(self, student_identifier):
        if student_identifier not in self.enrollees:
            raise ValueError(f"Student with ID {student_identifier} does not exist.")
        for subject_id, subject_data in self.subjects.items():
            if student_identifier in subject_data['enrollees']:
                subject_data['enrollees'].remove(student_identifier)
                self._adjust_subject_metrics(subject_id)
        del self.enrollees[student_identifier]

    def modify_student_subject(self, student_identifier, subject_identifier, assessment_data):
        if student_identifier not in self.enrollees:
            raise ValueError(f"Student with ID {student_identifier} does not exist.")
        if subject_identifier not in self.subjects:
            raise ValueError(f"Subject with ID {subject_identifier} does not exist.")

        self.enrollees[student_identifier]['subjects'][subject_identifier] = assessment_data
        self._recalculate_student_grades(student_identifier)
        self._adjust_subject_metrics(subject_identifier)

    def get_high_performers(self, threshold_grade):
        return [student for student in self.enrollees.values() if student['overall_grade'] > threshold_grade]

    # Course Management Functions
    def register_subject(self, subject_identifier, title):
        if subject_identifier in self.subjects:
            raise ValueError(f"Subject with ID {subject_identifier} already exists.")
        self.subjects[subject_identifier] = {
            'name': title,
            'enrollees': [],
            'average_score': 0.0
        }

    def unregister_subject(self, subject_identifier):
        if subject_identifier not in self.subjects:
            raise ValueError(f"Subject with ID {subject_identifier} does not exist.")
        for student_identifier in self.subjects[subject_identifier]['enrollees']:
            if subject_identifier in self.enrollees[student_identifier]['subjects']:
                del self.enrollees[student_identifier]['subjects'][subject_identifier]
                self._recalculate_student_grades(student_identifier)
        del self.subjects[subject_identifier]

    def enroll_in_subject(self, student_identifier, subject_identifier):
        if student_identifier not in self.enrollees:
            raise ValueError(f"Student with ID {student_identifier} does not exist.")
        if subject_identifier not in self.subjects:
            raise ValueError(f"Subject with ID {subject_identifier} does not exist.")
        if student_identifier in self.subjects[subject_identifier]['enrollees']:
            raise ValueError(f"Student with ID {student_identifier} is already enrolled in the subject {subject_identifier}.")

        self.subjects[subject_identifier]['enrollees'].append(student_identifier)
        self.enrollees[student_identifier]['subjects'][subject_identifier] = {}
        self._adjust_subject_metrics(subject_identifier)

    def withdraw_from_subject(self, student_identifier, subject_identifier):
        if student_identifier not in self.enrollees:
            raise ValueError(f"Student with ID {student_identifier} does not exist.")
        if subject_identifier not in self.subjects:
            raise ValueError(f"Subject with ID {subject_identifier} does not exist.")
        if student_identifier not in self.subjects[subject_identifier]['enrollees']:
            raise ValueError(f"Student with ID {student_identifier} is not enrolled in the subject {subject_identifier}.")

        self.subjects[subject_identifier]['enrollees'].remove(student_identifier)
        if subject_identifier in self.enrollees[student_identifier]['subjects']:
            del self.enrollees[student_identifier]['subjects'][subject_identifier]
            self._recalculate_student_grades(student_identifier)
        self._adjust_subject_metrics(subject_identifier)

    def top_performer_in_subject(self, subject_identifier):
        if subject_identifier not in self.subjects:
            raise ValueError(f"Subject with ID {subject_identifier} does not exist.")

        best_score = -1
        top_student = None
        for student_identifier in self.subjects[subject_identifier]['enrollees']:
            if subject_identifier in self.enrollees[student_identifier]['subjects']:
                score = sum(self.enrollees[student_identifier]['subjects'][subject_identifier].values()) / len(self.enrollees[student_identifier]['subjects'][subject_identifier])
                if score > best_score:
                    best_score = score
                    top_student = student_identifier

        return top_student, best_score

    # Helper Functions
    def _recalculate_student_grades(self, student_identifier):
        if not self.enrollees[student_identifier]['subjects']:
            self.enrollees[student_identifier]['overall_grade'] = 0.0
            return

        total_points = 0
        total_assessments = 0
        for subject_id, assessments in self.enrollees[student_identifier]['subjects'].items():
            total_points += sum(assessments.values())
            total_assessments += len(assessments)

        self.enrollees[student_identifier]['overall_grade'] = total_points / total_assessments

    def _adjust_subject_metrics(self, subject_identifier):
        if not self.subjects[subject_identifier]['enrollees']:
            self.subjects[subject_identifier]['average_score'] = 0.0
            return

        total_points = 0
        total_assessments = 0
        for student_identifier in self.subjects[subject_identifier]['enrollees']:
            if subject_identifier in self.enrollees[student_identifier]['subjects']:
                total_points += sum(self.enrollees[student_identifier]['subjects'][subject_identifier].values())
                total_assessments += len(self.enrollees[student_identifier]['subjects'][subject_identifier])

        self.subjects[subject_identifier]['average_score'] = total_points / total_assessments

# Example Usage
system = VirtualLearningEnvironment()

# Register students
system.register_student(1, "Alice")
system.register_student(2, "Bob")
