# Process a CSV file and generate formatted LaTeX output
import csv
import sys

def load_csv_data(file_name, sep=','):
    try:
        with open(file_name, mode='r', encoding='utf-8') as f:
            reader = csv.reader(f, delimiter=sep)
            rows = list(reader)
            return rows
    except FileNotFoundError:
        print(f"Error: The file '{file_name}' was not found.")
        sys.exit(1)
    except Exception as err:
        print(f"Error: An unexpected error occurred while reading the file: {err}")
        sys.exit(1)

def extract_and_sort_first_column(table):
    if not table or not table[0]:
        print("Error: The table is empty.")
        sys.exit(1)

    first_entries = [row[0] for row in table]
    first_entries.sort(reverse=True)
    return first_entries

def apply_formatting(items, highlight_terms):
    result = ""
    for item in items:
        modified_item = item
        for term in highlight_terms:
            if term in item:
                modified_item = modified_item.replace(term, f"\\textbf{{\\textit{{{term}}}}}")
        result += modified_item + " "
    return result.strip()

def main():
    if len(sys.argv) < 3:
        print("Usage: python script.py <file_path> <delimiter> [keywords...]")
        sys.exit(1)

    input_file = sys.argv[1]
    field_separator = sys.argv[2]
    search_terms = sys.argv[3:]

    raw_data = load_csv_data(input_file, field_separator)
    sorted_first_col = extract_and_sort_first_column(raw_data)
    formatted_result = apply_formatting(sorted_first_col, search_terms)

    print(f"\\documentclass{{article}}\n\\begin{{document}}\n{formatted_result}\n\\end{{document}}")

if __name__ == "__main__":
    main()

# Find numbers whose cubes are perfect squares in a given range
import concurrent.futures
import math

def check_perfect_square(value):
    root = int(math.sqrt(value))
    return root * root == value

def compute_cube_info(number):
    cubed = number ** 3
    if check_perfect_square(cubed):
        return number, cubed, int(math.sqrt(cubed))
    return number, cubed, None

def handle_range(min_val, max_val, thread_count=4):
    output = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=thread_count) as pool:
        tasks = {pool.submit(compute_cube_info, num): num for num in range(min_val, max_val + 1)}
        for completed_task in concurrent.futures.as_completed(tasks):
            number, cube, square_root = completed_task.result()
            output.append((number, cube, square_root))
    return output

def execute():
    min_number = 1
    max_number = 10000
    threads = 4
    data = handle_range(min_number, max_number, threads)
    for n, c, s in data:
        print(f"Value: {n}, Cube: {c}, Root: {s}")

if __name__ == "__main__":
    execute()

