# PDF utility script for text extraction and metadata retrieval
import argparse
import json
import pymupdf

def get_pdf_content(file_path, limit_pages=None):
    try:
        document = pymupdf.open(file_path)
        content = ""
        for idx, page in enumerate(document):
            if limit_pages and idx >= int(limit_pages):
                break
            content += page.get_text() + "\n"
        return content
    except Exception as error:
        return f"Error: {str(error)}"

def retrieve_document_info(file_path):
    try:
        document = pymupdf.open(file_path)
        return document.metadata
    except Exception as error:
        return {"error": str(error)}

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Process PDF files")
    parser.add_argument("action", choices=["extract", "metadata"])
    parser.add_argument("source_file")
    parser.add_argument("--limit", type=int, default=None)

    arguments = parser.parse_args()

    if arguments.action == "extract":
        print(get_pdf_content(arguments.source_file, arguments.limit))
    elif arguments.action == "metadata":
        print(json.dumps(retrieve_document_info(arguments.source_file), indent=2))

# Merge suggestions API router -- face merge group analysis.
"""
from fastapi import APIRouter, Depends, HTTPException, Query
from api.auth import CurrentUser, require_authenticated
from api.config import VIEWER_CONFIG
from db import DEFAULT_DB_PATH

router = APIRouter(tags=["merge_suggestions"])

@router.get("/api/merge_suggestions")
async def fetch_merge_proposals(
    similarity_threshold: float = Query(0.6, ge=0.0, le=1.0),
    user: CurrentUser = Depends(require_authenticated),
):
    """Return merge suggestions as pairwise person comparisons."""
    # Check if feature is enabled
    if not VIEWER_CONFIG.get("features", {}).get("show_merge_suggestions", True):
        raise HTTPException(status_code=403, detail="Merge suggestions feature is disabled")

    # Lazy import only when feature is used
    from faces import get_merge_groups

    groups = get_merge_groups(DEFAULT_DB_PATH, similarity_threshold)

    # Convert groups to pairwise suggestions for the Angular component
    proposals = []
    for cluster in groups:
        individuals = cluster.get("persons", [])
        avg_similarity = cluster.get("avg_similarity", 0.0)

        # Create a pairwise suggestion for each adjacent pair in the group
        for idx in range(len(individuals) - 1):
            proposals.append({
                "person1": {
                    "id": individuals[idx]["id"],
                    "name": individuals[idx].get("name"),
                    "face_count": individuals[idx].get("face_count", 0),
                },
                "person2": {
                    "id": individuals[idx + 1]["id"],
                    "name": individuals[idx + 1].get("name"),
                    "face_count": individuals[idx + 1].get("face_count", 0),
                },
                "similarity": avg_similarity,
            })

    return {"suggestions": proposals}

