import json
import sys
# Script to verify that the `fields.json` file generated by Claude during PDF analysis
# contains no overlapping bounding boxes. Refer to forms.md for details.
from dataclasses import dataclass

@dataclass
class BoundingBoxAndField:
    bbox: list[float]
    bbox_type: str
    field: dict

# Returns a list of status messages printed to stdout for Claude to process.
def validate_bounding_boxes(fields_json_stream) -> list[str]:
    output_messages = []
    fields_data = json.load(fields_json_stream)
    output_messages.append(f"Loaded {len(fields_data['form_fields'])} form fields")

    def boxes_overlap(b1, b2):
        non_overlapping_x = b1[0] >= b2[2] or b1[2] <= b2[0]
        non_overlapping_y = b1[1] >= b2[3] or b1[3] <= b2[1]
        return not (non_overlapping_x or non_overlapping_y)

    bounding_boxes = []
    for field in fields_data["form_fields"]:
        bounding_boxes.append(BoundingBoxAndField(field["label_bounding_box"], "label", field))
        bounding_boxes.append(BoundingBoxAndField(field["entry_bounding_box"], "entry", field))

    found_issues = False
    for idx, box_i in enumerate(bounding_boxes):
        # Quadratic time complexity; can be optimized if performance becomes an issue.
        for jdx in range(idx + 1, len(bounding_boxes)):
            box_j = bounding_boxes[jdx]
            if (box_i.field["page_number"] == box_j.field["page_number"] and 
                boxes_overlap(box_i.bbox, box_j.bbox)):
                found_issues = True
                if box_i.field is box_j.field:
                    output_messages.append(
                        f"ERROR: Overlap between label and entry bounding boxes for `{box_i.field['description']}` "
                        f"({box_i.bbox}, {box_j.bbox})"
                    )
                else:
                    output_messages.append(
                        f"ERROR: Overlap between {box_i.bbox_type} bounding box for `{box_i.field['description']}` "
                        f"({box_i.bbox}) and {box_j.bbox_type} bounding box for `{box_j.field['description']}` ({box_j.bbox})"
                    )
                if len(output_messages) >= 20:
                    output_messages.append("Stopping further validation; correct bounding boxes and re-run")
                    return output_messages

        # Check entry bounding box height against font size
        if box_i.bbox_type == "entry":
            if "entry_text" in box_i.field:
                text_info = box_i.field["entry_text"]
                font_size = text_info.get("font_size", 14)
                bbox_height = box_i.bbox[3] - box_i.bbox[1]
                if bbox_height < font_size:
                    found_issues = True
                    output_messages.append(
                        f"ERROR: Entry bounding box height ({bbox_height}) for `{box_i.field['description']}` "
                        f"is insufficient for text content (font size: {font_size}). "
                        f"Either increase the box height or reduce the font size."
                    )
                    if len(output_messages) >= 20:
                        output_messages.append("Stopping further validation; correct bounding boxes and re-run")
                        return output_messages

    if not found_issues:
        output_messages.append("OK: All bounding boxes are properly sized and non-overlapping")
    return output_messages

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: validate_bounding_boxes.py [fields.json]")
        sys.exit(1)

    # Input file should follow the `fields.json` format specified in forms.md.
    with open(sys.argv[1]) as input_file:
        results = validate_bounding_boxes(input_file)
    for line in results:
        print(line)

