# Analyze emotional tone of stressor reports
def evaluate_emotional_patterns(input_data):
    """
    Evaluates the emotional tone of user-reported stressors.
    """
    sentiment_sum = 0
    entries_count = len(input_data)

    for item in input_data:
        blob_analysis = TextBlob(item['text'])
        sentiment_sum += blob_analysis.sentiment.polarity

    average_sentiment = sentiment_sum / entries_count if entries_count > 0 else 0

    # Classify based on polarity thresholds
    if average_sentiment > 0.1:
        classification = "Positive/Coping Well"
    elif average_sentiment < -0.1:
        classification = "High Stress/Overwhelmed"
    else:
        classification = "Neutral/Stable"

    return {
        "average_sentiment": round(average_sentiment, 2),
        "classification": classification,
        "entries_count": entries_count
    }

# Encode and decode unsigned varints according to the canonical format
_MAX_UNSIGNED_VARINT = (1 << 64) - 1

def encode_unsigned_varint(number: int) -> bytes:
    """Encode a non-negative integer into its canonical varint representation."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise ValueError("input must be an integer")
    if number < 0:
        raise ValueError("input must be non-negative")
    if number > _MAX_UNSIGNED_VARINT:
        raise ValueError("input must be <= 2^64-1")

    result = bytearray()
    while True:
        segment = number & 0x7F
        number >>= 7
        if number:
            result.append(segment | 0x80)
        else:
            result.append(segment)
            break
    return bytes(result)

def decode_unsigned_varint(buffer: bytes, offset: int) -> tuple[int, int]:
    """Decode a varint from buffer starting at given offset, enforcing canonical encoding."""
    if offset < 0:
        raise ValueError("offset must be non-negative")

    decoded_value = 0
    bit_position = 0
    current_index = offset

    while True:
        if current_index >= len(buffer):
            raise ValueError("varint data is truncated")

        current_byte = buffer[current_index]
        data_bits = current_byte & 0x7F

        # Check for overflow in the final byte (bit 63)
        if bit_position == 63 and data_bits > 1:
            raise ValueError("varint exceeds 64-bit limit")

        current_index += 1
        decoded_value |= data_bits << bit_position

        # Check continuation bit
        if current_byte & 0x80 == 0:
            # Verify canonical form by re-encoding and comparing
            if buffer[offset:current_index] != encode_unsigned_varint(decoded_value):
                raise ValueError("non-canonical varint encoding detected")
            return decoded_value, current_index

        bit_position += 7
        if bit_position > 63:
            raise ValueError("varint too large")

# WebSocket notification system for managing user connections and sending messages
from typing import Dict, List
import json
import asyncio

class ConnectionHandler:
    def __init__(self):
        self.connected_users: Dict[str, List[WebSocket]] = {}

    async def add_connection(self, websocket: WebSocket, user_identifier: str):
        await websocket.accept()
        if user_identifier not in self.connected_users:
            self.connected_users[user_identifier] = []
        self.connected_users[user_identifier].append(websocket)

    def remove_connection(self, websocket: WebSocket, user_identifier: str):
        if user_identifier in self.connected_users:
            if websocket in self.connected_users[user_identifier]:
                self.connected_users[user_identifier].remove(websocket)

    async def send_to_user(self, message: dict, user_identifier: str):
        if user_identifier in self.connected_users:
            for connection in self.connected_users[user_identifier]:
                await connection.send_json(message)

    async def send_to_all(self, message: dict):
        for user_identifier in self.connected_users:
            for connection in self.connected_users[user_identifier]:
                await connection.send_json(message)

handler = ConnectionHandler()

MESSAGE_TEMPLATES = {
    "exam_results": "Exam results are available",
    "achievement_unlocked": "New achievement unlocked!",
    "journal_reminder": "Time for journal reflection",
    "profile_changed": "Your profile has been updated",
}

async def handle_websocket(websocket: WebSocket, user_id: str):
    await handler.add_connection(websocket, user_id)
    try:
        while True:
            incoming_data = await websocket.receive_text()
            parsed_message = json.loads(incoming_data)
            if parsed_message.get("type") == "ping":
                await websocket.send_json({"type": "pong"})
    except WebSocketDisconnect:
        handler.remove_connection(websocket, user_id)

async def deliver_notification(user_id: str, notification_kind: str, payload: dict = None):
    response = {
        "type": notification_kind,
        "message": MESSAGE_TEMPLATES.get(notification_kind, "Notification"),
        "data": payload or {},
        "timestamp": asyncio.get_event_loop().time(),
    }
    await handler.send_to_user(response, user_id)

async def announce_notification(notification_kind: str, payload: dict = None):
    response = {
        "type": notification_kind,
        "message": MESSAGE_TEMPLATES.get(notification_kind, "Notification"),
        "data": payload or {},
    }
    await handler.send_to_all(response)

import pyudev
from PyQt5.QtCore import QObject, pyqtSignal

class UsbDeviceWatcher(QObject):
    device_connected = pyqtSignal(str)
    device_disconnected = pyqtSignal(str)
    device_inventory_changed = pyqtSignal(dict)

    def __init__(self):
        super().__init__()
        self.context = pyudev.Context()
        self.event_monitor = pyudev.Monitor.from_netlink(self.context)
        self.event_monitor.filter_by(subsystem='block')
        self.usb_devices = {}

        self._initialize_device_list()

        self.observer_thread = pyudev.MonitorObserver(
            self.event_monitor,
            callback=self._handle_event
        )
        self.observer_thread.start()

    def _initialize_device_list(self):
        for dev in self.context.list_devices(subsystem='block', DEVTYPE='disk'):
            if dev.get('ID_BUS') == 'usb':
                device_path = dev.device_node
                self.usb_devices[device_path] = device_path

        self.device_inventory_changed.emit(self.usb_devices)

    def _handle_event(self, device):
        event_type = device.action
        if device.get('DEVTYPE') != 'disk':
            return
        if device.get('ID_BUS') != 'usb':
            return

        device_path = device.device_node

        if event_type == "add":
            self.usb_devices[device_path] = device_path
            self.device_connected.emit(device_path)
        elif event_type == "remove":
            if device_path in self.usb_devices:
                del self.usb_devices[device_path]
                self.device_disconnected.emit(device_path)

        self.device_inventory_changed.emit(self.usb_devices)

