# Recursively list public symbols in a module and its submodules
import importlib
import inspect

def get_public_names(module) -> list[str]:
    """Extract the list of public identifiers from *module* (respects ``__all__`` if present)."""
    if hasattr(module, "__all__") and isinstance(module.__all__, (list, tuple)):
        return list(module.__all__)

    def is_exported(name: str) -> bool:
        if name.startswith("_"):
            return False
        obj = getattr(module, name)
        return not inspect.ismodule(obj)

    return sorted(filter(is_exported, dir(module)))

def collect_module_items(module_path: str):
    current_module = importlib.import_module(module_path)
    public_items = get_public_names(current_module)
    nested_list = []
    for identifier in public_items:
        value = getattr(current_module, identifier)
        if inspect.ismodule(value):
            nested_list.append(collect_module_items(f"{module_path}.{identifier}"))
        else:
            nested_list.append(identifier)
    return (module_path.split(".")[-1], nested_list)

def display_hierarchy(tree_node, level=0):
    label, branches = tree_node[0], tree_node[1]
    print(f"{'   ' * level}{label}:")
    leaf_nodes = []
    branch_nodes = []
    for item in branches:
        if isinstance(item, str):
            leaf_nodes.append(item)
        else:
            branch_nodes.append(item)
    # organize alphabetically
    leaf_nodes.sort()
    branch_nodes.sort(key=lambda x: x[0])
    for leaf in leaf_nodes:
        print(f"{'   ' * (level + 1)}{leaf}")
    print()
    for branch in branch_nodes:
        display_hierarchy(branch, level=level + 1)

