# Custom pipeline for video generation using diffusion models
from diffusers.utils.torch_utils import randn_tensor
from diffusers.pipelines import DiffusionPipeline

class VideoDiffusionPipeline(DiffusionPipeline):
    def prepare_latents(self, batch_shape, rng_generator, target_device, tensor_dtype, latent_input=None):
        if latent_input is None:
            latent_input = randn_tensor(batch_shape, generator=rng_generator, device=target_device, dtype=tensor_dtype)
        else:
            latent_input = latent_input.to(target_device)
        if hasattr(self.scheduler, "init_noise_sigma"):
            # scale the initial noise by the standard deviation required by the scheduler
            latent_input = latent_input * self.scheduler.init_noise_sigma
        return latent_input

    def decode_latents(self, latent_vectors, value_bounds=(-1, 1), apply_normalization=True, **extra_kwargs):
        decoded_video = self.vae.decode(latent_vectors, **extra_kwargs)  # [b, c, t, h, w]
        if apply_normalization:
            min_val, max_val = value_bounds
            decoded_video.clamp_(min=min_val, max=max_val)
            decoded_video.sub_(min_val).div_(max(max_val - min_val, 1e-5))
        # [b, c, t, h, w] --> [b, t, h, w, c]
        decoded_video = decoded_video.mul(255).add_(0.5).clamp_(0, 255).permute(0, 2, 3, 4, 1).to("cpu", torch.uint8)
        return decoded_video

