    "https://www.coindesk.com/arc/outboundfeeds/rss/"
]

def retrieve_rss_articles(feed_url, max_items=5):
    articles = []
    try:
        response = requests.get(feed_url, timeout=10)
        if response.status_code == 200:
            root = ET.fromstring(response.content)
            counter = 0
            for entry in root.findall('.//item'):
                if counter >= max_items:
                    break

                headline = entry.find('title').text if entry.find('title') is not None else "No Title"
                summary = entry.find('description').text if entry.find('description') is not None else ""

                articles.append({
                    "origin": feed_url,
                    "headline": headline,
                    "summary": summary[:200] + "..." if len(summary) > 200 else summary
                })
                counter += 1
    except Exception as e:
        print(f"Failed to fetch {feed_url}: {e}", file=sys.stderr)
    return articles

def determine_sentiment(text):
    blob = TextBlob(text)
    return blob.sentiment.polarity

def main():
    parser = argparse.ArgumentParser(description='Gather cryptocurrency news and perform sentiment analysis.')
    args = parser.parse_args()
    combined_articles = []
    for source in RSS_SOURCES:
        combined_articles.extend(retrieve_rss_articles(source))

    analyzed_articles = []
    for article in combined_articles:
        score = determine_sentiment(article['headline'] + " " + article['summary'])
        label = "NEUTRAL"
        if score > 0.1:
            label = "POSITIVE"
        elif score < -0.1:
            label = "NEGATIVE"

        analyzed_articles.append({
            "headline": article['headline'],
            "sentiment_value": round(score, 2),
            "sentiment_category": label
        })

    print(json.dumps(analyzed_articles, indent=2))

if __name__ == "__main__":
    import sys
    main()

