import ast
import sys
from skylos.rules.danger.taint import TaintVisitor

# Set of functions that perform HTTP redirects
REDIRECT_FUNCS = {"redirect", "HttpResponseRedirect", "HttpResponsePermanentRedirect"}

class _RedirectFlowAnalyzer(TaintVisitor):
    def visit_Call(self, node):
        func_node = node.func
        func_identifier = None

        # Determine function name based on AST node type
        if isinstance(func_node, ast.Name):
            func_identifier = func_node.id
        elif isinstance(func_node, ast.Attribute):
            func_identifier = func_node.attr

        # Check if the function is a redirect function and has arguments
        if func_identifier in REDIRECT_FUNCS and node.args:
            first_arg = node.args[0]

            # If the URL argument is tainted (user-controlled), report finding
            if self.is_tainted(first_arg):
                self.findings.append(
                    {
                        "rule_id": "SKY-D230",
                        "severity": "HIGH",
                        "message": "Possible open redirect: user-controlled URL passed to redirect.",
                        "file": str(self.file_path),
                        "line": node.lineno,
                        "col": node.col_offset,
                        "symbol": self._current_symbol(),
                    }
                )

        self.generic_visit(node)

def analyze(tree, file_path, findings):
    try:
        analyzer = _RedirectFlowAnalyzer(file_path, findings)
        analyzer.visit(tree)
    except Exception as error:
        print(f"Redirect flow analysis failed for {file_path}: {error}", file=sys.stderr)

