# Apply gradient checkpointing to specified modules
import logging
import functools
from torch.utils.checkpoint import checkpoint
from mindspeed.fsdp.utils.log import print_rank
from mindspeed.fsdp.utils.str_match import module_name_match

logger = logging.getLogger(__name__)

def apply_recompute_to_modules(model, config):
    target_modules = find_recompute_target_modules(model, config.target_module_names)
    for layer_name, layer_module in target_modules:
        print_rank(logger.info, f'Enabling recompute for layer: {layer_name}')
        layer_module.forward = create_recompute_wrapper(layer_module.forward, config.use_reentrant_mode)
    return model

def find_recompute_target_modules(layers, target_names):
    selected_layers = []
    for pattern in target_names:
        for name, layer in layers.named_modules():
            if module_name_match(pattern, name):
                selected_layers.append((name, layer))
    if len(selected_layers) == 0:
        raise RuntimeError(f'[Recompute] No layers matched the specification: {target_names}.')
    return selected_layers

def create_recompute_wrapper(func, is_reentrant):
    def wrapped_forward(*args, **kwargs):
        kwargs['past_key_values'] = None  # Clear KV cache for transformers or ensure use_cache=False
        if not is_reentrant:
            return checkpoint(func, *args, use_reentrant=is_reentrant, **kwargs)
        else:
            partial_func = functools.partial(func, **kwargs)
            return checkpoint(partial_func, *args, use_reentrant=is_reentrant)
    return wrapped_forward

# Import necessary modules
from enum import Enum, auto
from itertools import count
from copy import copy
from ..layers.sampler import SamplingParams

class SequenceState(Enum):
    PENDING = auto()
    ACTIVE = auto()
    COMPLETED = auto()

class Sequence:
    block_size = 256
    _id_counter = count()

    def __init__(self, tokens: list[int], params: SamplingParams = SamplingParams()):
        self.sequence_id = next(Sequence._id_counter)
        self.state = SequenceState.PENDING
        self.tokens = copy(tokens)
        self.final_token = tokens[-1]
        self.total_tokens = len(self.tokens)
        self.prompt_length = len(tokens)
        self.cached_tokens = 0
        self.block_mapping = []
        self.temperature = params.temperature
        self.max_new_tokens = params.max_tokens
        self.skip_eos_check = params.ignore_eos
        self.enable_verification = True
        self.accumulated_token_counts = []
        self.current_accumulated = 0

    def __len__(self):
        return self.total_tokens

    def __getitem__(self, index):
        return self.tokens[index]

    @property
    def is_complete(self):
        return self.state == SequenceState.COMPLETED

    @property
    def generated_token_count(self):
        return self.total_tokens - self.prompt_length

    @property
    def prompt_ids(self):
        return self.tokens[:self.prompt_length]

    @property
    def generated_ids(self):
        return self.tokens[self.prompt_length:]

    @property
    def cached_block_count(self):
        return self.cached_tokens // self.block_size

    @property
    def total_blocks(self):
        return (self.total_tokens + self.block_size - 1) // self.block_size

    @property
    def final_block_token_count(self):
        return self.total_tokens - (self.total_blocks - 1) * self.block_size

    def get_block(self, idx: int):
        assert 0 <= idx < self.total_blocks
        return self.tokens[idx*self.block_size: (idx+1)*self.block_size]

    def add_token(self, token_id: int):
        self.tokens.append(token_id)
        self.final_token = token_id
        self.total_tokens += 1

    # PEARL KV cache Rollback
    def revert_tokens(self, n: int):
        assert n > 0
        self.tokens = self.tokens[:-n]
        self.final_token = self.tokens[-1]
        self.total_tokens -= n

    def map_token_to_slot(self, token_pos: int):
        block_idx = token_pos // self.block_size
        offset_in_block = token_pos % self.block_size
        slot_position = self.block_mapping[block_idx] * self.block_size + offset_in_block
        return slot_position

    def __getstate__(self):
        return (self.total_tokens, self.prompt_length, self.cached_tokens, self.block_mapping,
                self.temperature, self.skip_eos_check, self.max_new_tokens, self.sequence_id, 
                self.enable_verification, self.accumulated_token_counts, self.current_accumulated,
                self.tokens if self.generated_token_count == 0 else self.final_token)

    def __setstate__(self, state_data):
        (self.total_tokens, self.prompt_length, self.cached_tokens, self.block_mapping,
         self.temperature, self.skip_eos_check, self.max_new_tokens, self.sequence_id,
         self.enable_verification, self.accumulated_token_counts, self.current_accumulated) = state_data[:-1]

        if self.generated_token_count == 0:
            self.tokens = state_data[-1]
        else:
            self.final_token = state_data[-1]

