# Modified version of StickyActionEnv with renamed variables and reordering
import numpy as np

class StickyActionWrapper(gym.Wrapper):
    def __init__(self, environment, probability=0.25):
        super().__init__(environment)
        self.stickiness = probability
        self.previous_action = 0

    def step(self, chosen_action):
        if np.random.uniform() < self.stickiness:
            chosen_action = self.previous_action
        self.previous_action = chosen_action
        observation, reward, terminated, metadata = self.env.step(chosen_action)
        return observation, reward, terminated, metadata

# MongoDB internal MinKey type implementation
class MinimumKey(object):
    __slots__ = ()
    _type_code = 255

    def __getstate__(self):
        return {}

    def __setstate__(self, state):
        pass

    def __eq__(self, other):
        return isinstance(other, MinimumKey)

    def __hash__(self):
        return hash(self._type_code)

    def __ne__(self, other):
        return not self == other

    def __le__(self, dummy_value):
        return True

    def __lt__(self, other):
        return not isinstance(other, MinimumKey)

    def __ge__(self, other):
        return isinstance(other, MinimumKey)

    def __gt__(self, dummy_param):
        return False

    def __repr__(self):
        return "MinimumKey()"

