class BaseTrait(Service):
    def __init__(self, config=None):
        if config is None:
            config = {}
        self.config = config
        region = config.get('region', REGION_CN_NORTH1)
        service_map = config.get('service_info_map', {})
        self.service_info = BaseTrait._fetch_service_info(region, service_map)
        self.api_data = BaseTrait._fetch_api_info()
        if config.get('ak', None) and config.get('sk', None):
            self.set_access_key(config['ak'])
            self.set_secret_key(config['sk'])
        super(BaseTrait, self).__init__(self.service_info, self.api_data)

    @staticmethod
    def _fetch_service_info(region, service_map):
        service_info = service_map.get(region, None)
        if not service_info:
            raise Exception('BaseService does not support region %s' % region)
        return service_info

    @staticmethod
    def _fetch_api_info():
        return api_data

    def update_api_info(self, additional_api_info):
        self.api_data = {**self.api_data, **additional_api_info}
        return

    def execute_get_request(self, action, parameters={}, doseq=0):
        response = self.get(action, parameters, doseq)
        if response == '':
            raise Exception("%s: empty response" % action)
        response_json = json.loads(json.dumps(response))
        return response_json

    def execute_post_request(self, action, parameters={}, body={}):
        response = self.json(action, parameters, body)
        if response == '':
            raise Exception("%s: empty response" % action)
        response_json = json.loads(json.dumps(response))
        return response_json

