def local_multi_tensor_applier(operation, flag_buffer, tensor_groups, *extra_args):
    return operation(2048 * 32, flag_buffer, tensor_groups, *extra_args)

# Computes L2 norm for a list of contiguous tensors
# Serves as a drop-in replacement for amp_C.multi_tensor_l2norm
def local_multi_tensor_l2_norm(chunk_size, ignore_flag, tensor_lists, per_tensor, *args):
    l2_values = [
        [(torch.norm(tensor)) for tensor in tensor_list] for tensor_list in tensor_lists
    ]
    combined_l2 = torch.norm(torch.tensor(l2_values))
    l2_on_device = torch.tensor(
        [float(combined_l2)], dtype=torch.float32, device=current_platform.device_type
    )
    return l2_on_device, None

# Acts as a drop-in replacement for amp_C.multi_tensor_scale
def local_multi_tensor_scale(chunk_size, ignore_flag, tensor_pairs, scaling_factor):
    for source, destination in zip(tensor_pairs[0], tensor_pairs[1]):
        destination.copy_(source * scaling_factor)

