def upgrade(conn):
    """Add missing columns to users table for v2.0"""
    # Retrieve current column information
    cursor = conn.execute("PRAGMA table_info(users)")
    existing_columns = {row[1] for row in cursor.fetchall()}

    # Define new columns with their SQL definitions
    columns_to_add = [
        ("totp_secret", "TEXT"),
        ("totp_confirmed", "INTEGER DEFAULT 0"),
        ("backup_codes", "TEXT"),
        ("login_count", "INTEGER DEFAULT 0"),
        ("failed_logins", "INTEGER DEFAULT 0"),
        ("locked_until", "DATETIME"),
    ]

    # Add each new column if it doesn't already exist
    for col_name, col_def in columns_to_add:
        if col_name not in existing_columns:
            try:
                conn.execute(f"ALTER TABLE users ADD COLUMN {col_name} {col_def}")
                print(f"    Added column: {col_name}")
            except Exception as e:
                if "duplicate column" not in str(e).lower():
                    raise

    conn.commit()

