import json
import sys
# Script to verify that the `fields.json` file generated by Claude during PDF analysis
# contains no overlapping bounding boxes. Refer to forms.md for details.
@dataclass
class BoxAndField:
    box: list[float]
    box_type: str
    field: dict

# Returns a list of status messages printed to stdout for Claude to process.
def validate_bounding_boxes(fields_json_stream) -> list[str]:
    output_lines = []
    fields_data = json.load(fields_json_stream)
    output_lines.append(f"Loaded {len(fields_data['form_fields'])} fields")

    def boxes_overlap(b1, b2):
        non_overlapping_x = b1[0] >= b2[2] or b1[2] <= b2[0]
        non_overlapping_y = b1[1] >= b2[3] or b1[3] <= b2[1]
        return not (non_overlapping_x or non_overlapping_y)

    boxes_and_fields = []
    for field in fields_data["form_fields"]:
        boxes_and_fields.append(BoxAndField(field["label_bounding_box"], "label", field))
        boxes_and_fields.append(BoxAndField(field["entry_bounding_box"], "entry", field))

    found_issues = False
    for idx, current_box in enumerate(boxes_and_fields):
        # Quadratic complexity; can be optimized if performance becomes an issue.
        for k in range(idx + 1, len(boxes_and_fields)):
            next_box = boxes_and_fields[k]
            if (current_box.field["page_number"] == next_box.field["page_number"] and 
                boxes_overlap(current_box.box, next_box.box)):
                found_issues = True
                if current_box.field is next_box.field:
                    output_lines.append(f"ERROR: overlapping label and entry bounding boxes for `{current_box.field['description']}` ({current_box.box}, {next_box.box})")
                else:
                    output_lines.append(f"ERROR: overlapping {current_box.box_type} bounding box for `{current_box.field['description']}` ({current_box.box}) and {next_box.box_type} bounding box for `{next_box.field['description']}` ({next_box.box})")

                if len(output_lines) >= 20:
                    output_lines.append("Stopping further checks; correct bounding boxes and re-run")
                    return output_lines

        if current_box.box_type == "entry":
            if "entry_text" in current_box.field:
                font_size_val = current_box.field["entry_text"].get("font_size", 14)
                box_height = current_box.box[3] - current_box.box[1]
                if box_height < font_size_val:
                    found_issues = True
                    output_lines.append(f"ERROR: entry bounding box height ({box_height}) for `{current_box.field['description']}` is insufficient for text content (font size: {font_size_val}). Enlarge the box or reduce font size.")
                    if len(output_lines) >= 20:
                        output_lines.append("Stopping further checks; correct bounding boxes and re-run")
                        return output_lines

    if not found_issues:
        output_lines.append("OK: All bounding boxes are properly spaced")
    return output_lines

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: validate_bounding_boxes.py [fields.json]")
        sys.exit(1)

    # Expected input format follows the `fields.json` schema outlined in forms.md.
    with open(sys.argv[1]) as file:
        results = validate_bounding_boxes(file)
    for line in results:
        print(line)

