# Environment variables for API configuration
AGENT_ID = os.environ.get("ELEVENLABS_AGENT_ID", "")
API_KEY = os.environ.get("ELEVENLABS_API_KEY", "")
PHONE_NUMBER_ID = os.environ.get("ELEVENLABS_PHONE_NUMBER_ID", "")

# API endpoint for outbound calls
API_URL = "https://api.elevenlabs.io/v1/convai/twilio/outbound-call"

def place_outbound_call(target_number: str, initial_greeting: str = "", additional_context: str = "") -> dict:
    """Initiate an outbound voice call via ElevenLabs API.

    Args:
        target_number: Destination phone number in E.164 format (+1XXXXXXXXXX).
        initial_greeting: Optional custom first message from the agent.
        additional_context: Optional dynamic context variable for the conversation.
    """
    # Validate required credentials
    if not API_KEY:
        return {"error": "ELEVENLABS_API_KEY not configured. Please set it in your environment."}
    if not AGENT_ID:
        return {"error": "ELEVENLABS_AGENT_ID not configured. Please set it in your environment."}
    if not PHONE_NUMBER_ID:
        return {"error": "ELEVENLABS_PHONE_NUMBER_ID not configured. Please set it in your environment."}

    # Validate US phone number format (E.164)
    if not re.match(r'^\+1\d{10}$', target_number):
        return {"error": f"Invalid US phone number: {target_number}. Expected format: +1XXXXXXXXXX"}

    # Build request payload
    request_body = {
        "agent_id": AGENT_ID,
        "agent_phone_number_id": PHONE_NUMBER_ID,
        "to_number": target_number,
    }

    # Add optional client data overrides
    client_data = {}
    if initial_greeting:
        client_data["conversation_config_override"] = {
            "agent": {"first_message": initial_greeting}
        }
    if additional_context:
        client_data["dynamic_variables"] = {"call_context": additional_context}

    if client_data:
        request_body["conversation_initiation_client_data"] = client_data

    # Prepare and send HTTP request
    encoded_data = json.dumps(request_body).encode()
    request = urllib.request.Request(
        API_URL, 
        data=encoded_data, 
        headers={
            "xi-api-key": API_KEY,
            "Content-Type": "application/json",
        }
    )

    try:
        with urllib.request.urlopen(request) as response:
            api_response = json.loads(response.read())

            # Handle API errors even on successful HTTP status
            if not api_response.get("success", True) or "error" in api_response:
                error_msg = api_response.get("error", api_response.get("message", "Unknown API issue"))
                return {"error": error_msg}

            return {
                "success": True,
                "conversation_id": api_response.get("conversation_id", ""),
                "call_sid": api_response.get("callSid", ""),
                "message": api_response.get("message", "Call started successfully"),
            }

    except urllib.error.HTTPError as http_err:
        error_body = http_err.read().decode()
        return {"error": f"ElevenLabs API error (HTTP {http_err.code}): {error_body}"}
    except urllib.error.URLError as url_err:
        return {"error": f"Network connectivity issue: {url_err.reason}"}

if __name__ == "__main__":
    # Command-line argument validation
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Usage: call.py <phone_number> [initial_greeting] [additional_context]"}))
        sys.exit(1)

    # Parse command-line arguments
    destination = sys.argv[1]
    greeting = sys.argv[2] if len(sys.argv) > 2 else ""
    context = sys.argv[3] if len(sys.argv) > 3 else ""

    # Execute call and output result
    outcome = place_outbound_call(destination, greeting, context)
    print(json.dumps(outcome, indent=2))
    sys.exit(0 if outcome.get("success") else 1)

