# Test compatibility shim for cursor keyword argument handling
def test_compat_cursor_keyword_forwarding():
    call_log = []
    class MockConnection:
        def cursor(self, *args, **kwargs):
            # Record the arguments passed to simulate strict behavior
            call_log.append(("invoked", args, kwargs))
            return "CURSOR_SUCCESS"

    mock_conn = MockConnection()

    # Simulate strict cursor method that rejects keyword arguments
    with pytest.raises(TypeError):
        def strict_impl(*args, **kwargs):
            if "cursor" in kwargs:
                raise TypeError(
                    "Connection.cursor() received unexpected keyword argument 'cursor'"
                )
            return mock_conn.cursor(*args, **kwargs)

        mock_conn.cursor = strict_impl
        mock_conn.cursor(cursor="Y")

    # Implement compatibility layer
    def original_cursor(*args, **kwargs):
        # Forward to a fresh mock connection instance to capture calls
        return MockConnection().cursor(*args, **kwargs)

    def compatible_cursor(*args, **kwargs):
        if "cursor" in kwargs:
            val = kwargs.pop("cursor")
            return original_cursor(val, *args, **kwargs)
        return original_cursor(*args, **kwargs)

    # Apply the compatibility wrapper
    mock_conn.cursor = compatible_cursor

    # Test with keyword argument
    outcome1 = mock_conn.cursor(cursor="Z")
    assert outcome1 == "CURSOR_SUCCESS"

    # Test without keyword argument (ensure backward compatibility)
    outcome2 = mock_conn.cursor()
    assert outcome2 == "CURSOR_SUCCESS"

# Module for database reference handling in MongoDB
from copy import deepcopy
from ._helpers import _getstate_slots, _setstate_slots
from .son import SON

class DBRef(object):
    """Represents a reference to a document stored in MongoDB."""
    __slots__ = "_collection", "_doc_id", "_db_name", "_extra_fields"
    __getstate__ = _getstate_slots
    __setstate__ = _setstate_slots
    # Arbitrary type marker for DBRef (not a native BSON type)
    _type_marker = 100

    def __init__(self, collection, doc_id, db_name=None, _extra={}, **kwargs):
        """Initialize a new :class:`DBRef`.

        Raises :class:`TypeError` if `collection` or `db_name` is not
        an instance of :class:`basestring` (:class:`str` in python 3).

        :Parameters:
          - `collection`: name of the collection containing the document
          - `doc_id`: value of the document's ``"_id"`` field
          - `db_name` (optional): name of the target database
          - `**kwargs` (optional): extra fields to include in the reference
        """
        if not isinstance(collection, str):
            raise TypeError("collection must be an instance of str")
        if db_name is not None and not isinstance(db_name, str):
            raise TypeError("database must be an instance of str")

        self._collection = collection
        self._doc_id = doc_id
        self._db_name = db_name
        kwargs.update(_extra)
        self._extra_fields = kwargs

    @property
    def collection(self):
        """Get the name of this DBRef's collection."""
        return self._collection

    @property
    def id(self):
        """Get this DBRef's document ID."""
        return self._doc_id

    @property
    def database(self):
        """Get the name of this DBRef's database.
        Returns None if no database was specified.
        """
        return self._db_name

    def __getattr__(self, key):
        try:
            return self._extra_fields[key]
        except KeyError:
            raise AttributeError(key)

    def as_doc(self):
        """Convert to SON document representation.
        Typically not used directly by application developers.
        """
        doc = SON([("$ref", self.collection), ("$id", self.id)])
        if self.database is not None:
            doc["$db"] = self.database
        doc.update(self._extra_fields)
        return doc

    def __repr__(self):
        extra = "".join([", %s=%r" % (k, v) for k, v in self._extra_fields.items()])
        if self.database is None:
            return "DBRef(%r, %r%s)" % (self.collection, self.id, extra)
        return "DBRef(%r, %r, %r%s)" % (self.collection, self.id, self.database, extra)

    def __eq__(self, other):
        if isinstance(other, DBRef):
            left = (self._db_name, self._collection, self._doc_id, self._extra_fields)
            right = (other._db_name, other._collection, other._doc_id, other._extra_fields)
            return left == right
        return NotImplemented

    def __ne__(self, other):
        return not self == other

    def __hash__(self):
        """Compute hash value for this DBRef."""
        return hash(
            (self._collection, self._doc_id, self._db_name, tuple(sorted(self._extra_fields.items())))
        )

    def __deepcopy__(self, memo):
        """Support function for `copy.deepcopy()`."""
        return DBRef(
            deepcopy(self._collection, memo),
            deepcopy(self._doc_id, memo),
            deepcopy(self._db_name, memo),
            deepcopy(self._extra_fields, memo),
        )

