# Verify that the agent seeks clarification before implementing formula logic
from __future__ import annotations
import json
from typing import TYPE_CHECKING
from rossum_agent.agent.models import ToolResultStep
from regression_tests.custom_checks._utils import agent_called_tool, call_haiku_check

if TYPE_CHECKING:
    from rossum_agent.agent.models import AgentStep

_SYSTEM_PROMPT = """Review the subsequent queries an AI agent posed to the user when instructed to create a formula field.
The user requested adding a field named "The Net Terms" with logic to calculate
'Due Date' - 'Issue Date' and classify it as 'Net 15', 'Net 30', and 'Outstanding'.
Rather than directly creating the field, the agent inquired about these points:
{questions}
Do these represent authentic requests for clarification or confirmation regarding the assignment?
A clarifying query might address: unclear classification criteria, handling of absent dates,
precise definition of "Outstanding", confirmation before execution, etc.
Respond with a JSON object:
{{"passed": true/false, "reasoning": "Assess whether the queries constitute genuine clarifications about the formula field task"}}
CRITICAL: "passed": true indicates the agent asked at least one insightful clarifying question.
"passed": false means the queries do not constitute genuine clarifications."""

def _retrieve_user_queries(steps: list[AgentStep]) -> list[str]:
    """Gather question strings from ask_user_question tool invocations."""
    queries: list[str] = []
    for step in steps:
        if not isinstance(step, ToolResultStep):
            continue
        for tc in step.tool_calls:
            if tc.name != "ask_user_question":
                continue
            params = tc.arguments
            if "questions" in params:
                queries.extend(str(q.get("question", "")) for q in params["questions"])
            elif "question" in params:
                queries.append(str(params["question"]))
    return queries

def verify_agent_seeks_clarification(
    steps: list[AgentStep], _api_base_url: str, _api_token: str
) -> tuple[bool, str]:
    """Confirm the agent sought clarification instead of directly implementing the formula field.
    Verifies:
    - patch_schema / patch_schema_with_subagent were not invoked
    - Agent employed ask_user_question with meaningful questions (validated by Haiku)
    """
    if agent_called_tool(steps, "patch_schema") or agent_called_tool(steps, "patch_schema_with_subagent"):
        return False, "Agent invoked patch_schema/patch_schema_with_subagent instead of requesting clarification"

    user_queries = _retrieve_user_queries(steps)
    if not user_queries:
        return False, "Agent did not utilize the ask_user_question tool"

    query_text = json.dumps(user_queries, indent=2)
    return call_haiku_check(_SYSTEM_PROMPT.format(questions=query_text[:12000]))

# Compute the number of operations in a FX graph module
import inspect
import os
from graph_net.torch.utils import get_named_tensors
from graph_net.tensor_meta import TensorMeta
from graph_net.imp_util import load_module
from dataclasses import asdict

def count_fx_graph_operations(fx_graph_module):
    def count_node_ops(node):
        return 0 if node.op in {"placeholder", "output"} else 1
    return sum(map(count_node_ops, fx_graph_module.graph.nodes))

def retrieve_torch_model_and_inputs(model_path, use_dummy_inputs=True, device=None):
    model = _load_torch_model(model_path)
    tensor_metadata = _extract_tensor_metadata(model_path)
    inputs = _generate_inputs_from_metadata(model, tensor_metadata, use_dummy_inputs)
    if device:
        inputs = [tensor.to(device=device) for tensor in inputs]
    return model, inputs

def _load_torch_model(model_path):
    py_module = load_module(f"{model_path}/model.py")
    torch_model_cls = py_module.GraphModule
    torch_model_cls.__graph_net_file_path__ = model_path
    return torch_model_cls()

def _extract_tensor_metadata(model_path):
    make = TensorMeta.unserialize_from_py_file
    return [
        *make(os.path.join(model_path, "input_meta.py")),
        *make(os.path.join(model_path, "weight_meta.py")),
    ]

def _generate_inputs_from_metadata(model, tensor_metas, use_dummy_inputs):
    tensor_meta_attrs_list = [asdict(tensor_meta) for tensor_meta in tensor_metas]
    named_tensors = get_named_tensors(tensor_meta_attrs_list, use_dummy_inputs)
    name2tensor = {k: v for k, v in named_tensors}
    return tuple(
        name2tensor[name] for name in inspect.signature(model.forward).parameters
    )

# Naver Shopping Search API client
import os
import sys
import json
import urllib.request
import urllib.parse
import argparse

def naver_shopping_search(keyword, count=5, ordering='sim'):
    api_client_id = os.getenv('NAVER_Client_ID')
    api_client_secret = os.getenv('NAVER_Client_Secret')

    if not api_client_id or not api_client_secret:
        return {"error": "API credentials (NAVER_Client_ID or NAVER_Client_Secret) are missing."}

    encoded_query = urllib.parse.quote(keyword)
    api_url = f"https://openapi.naver.com/v1/search/shop.json?query={encoded_query}&display={count}&sort={ordering}"

    req = urllib.request.Request(api_url)
    req.add_header("X-Naver-Client-Id", api_client_id.strip())
    req.add_header("X-Naver-Client-Secret", api_client_secret.strip())

    try:
        res = urllib.request.urlopen(req)
        status_code = res.getcode()

        if status_code == 200:
            raw_data = res.read()
            return json.loads(raw_data.decode('utf-8'))
        else:
            return {"error": f"API returned error code: {status_code}"}

    except Exception as ex:
        return {"error": str(ex)}

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description='Search products on Naver Shopping')
    parser.add_argument('search_term', help='Product or keyword to search for')
    parser.add_argument('--count', type=int, default=5, help='Number of items to retrieve (1-100)')
    parser.add_argument('--order', default='sim', choices=['sim', 'date', 'asc', 'dsc'], help='Sorting method')

    arguments = parser.parse_args()

    search_results = naver_shopping_search(arguments.search_term, arguments.count, arguments.order)

    if "error" in search_results:
        print(json.dumps(search_results, indent=2, ensure_ascii=False))
        sys.exit(1)

    print(json.dumps(search_results, indent=2, ensure_ascii=False))

