# Custom attribute manager class with restricted attributes
class RestrictedAttr:
    def __init__(self, permitted_fields=[]):
        # Initialize using __dict__ to bypass custom __setattr__
        self.__dict__['permitted_fields'] = permitted_fields
        self.__dict__['storage'] = {}

    def __getattr__(self, key):
        if key in self.permitted_fields:
            return self.storage.get(key)
        else:
            raise ValueError(f"Field '{key}' is not permitted.")

    def __setattr__(self, key, value):
        if key in self.permitted_fields:
            # Store value using __dict__ to prevent infinite recursion
            self.__dict__['storage'][key] = value
        elif key in ('permitted_fields', 'storage'):
            # Permit direct assignment of internal attributes
            self.__dict__[key] = value
        else:
            raise ValueError(f"Field '{key}' is not permitted.")

# Context manager to integrate tqdm progress bar with joblib
import contextlib
import joblib
from tqdm.autonotebook import tqdm

@contextlib.contextmanager
def tqdm_joblib_patch(*args, **kwargs):
    """Context manager to patch joblib to report into tqdm progress bar"""
    progress_bar = tqdm(*args, **kwargs)

    class TqdmBatchCallback(joblib.parallel.BatchCompletionCallBack):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)

        def __call__(self, *args, **kwargs):
            progress_bar.update(n=self.batch_size)
            return super().__call__(*args, **kwargs)

    original_callback = joblib.parallel.BatchCompletionCallBack
    joblib.parallel.BatchCompletionCallBack = TqdmBatchCallback

    try:
        yield progress_bar
    finally:
        joblib.parallel.BatchCompletionCallBack = original_callback
        progress_bar.close()

def create_parallel_with_progress(desc=None, **tqdm_options):
    """Factory function to create a Parallel class with tqdm progress bar support"""
    class CustomParallel(joblib.Parallel):
        def __call__(self, iterable):
            items = list(iterable)
            if self.n_jobs == 1:
                items = tqdm(items, desc=desc, **tqdm_options)
                return super().__call__(items)
            else:
                with tqdm_joblib_patch(total=len(items), desc=desc, **tqdm_options):
                    return super().__call__(items)

    return CustomParallel

