# Import required libraries for blockchain interaction and API communication
import os
from web3 import Web3
import requests

def connect_to_clob_with_auth(private_key):
    # Initialize Web3 connection to Polygon network
    w3 = Web3(Web3.HTTPProvider('https://polygon-rpc.com'))
    account = w3.eth.account.from_key(private_key)

    # Prepare EIP-712 typed data structure (adjust according to Polymarket specifications)
    typed_data = {
        "domain": {},  # Domain separator fields as per Polymarket documentation
        "message": {},  # Message payload fields
        "primaryType": "AuthenticationMessage"
    }

    # Sign the typed data using the private key
    signature = w3.eth.account.signTypedData(typed_data, private_key=private_key)

    # Request API credentials from CLOB endpoint
    api_endpoint = "https://clob.polymarket.com/api-keys"
    try:
        response = requests.post(api_endpoint, json={"signed_message": signature})
        if response.status_code == 200:
            result = response.json()
            return result  # Contains API key, secret, and passphrase
        else:
            raise Exception(f"HTTP {response.status_code}: Authentication unsuccessful")
    except requests.RequestException as e:
        raise Exception(f"Network error during authentication: {e}")

# Main execution block
if __name__ == "__main__":
    # Retrieve private key from environment variable securely
    secret_key = os.getenv('POLY_PRIVATE_KEY')

    if secret_key:
        try:
            credentials = connect_to_clob_with_auth(secret_key)
            print("Successfully obtained credentials:", credentials)
        except Exception as error:
            print(f"Operation failed: {error}")
    else:
        print("Environment variable POLY_PRIVATE_KEY must be set.")

# Convert a list of strings into a markdown-formatted list
def convert_to_markdown_list(
    items: list[str], style: t.Literal["unordered", "ordered"] = "unordered"
) -> str:
    """
    Transform a list of strings into a markdown list representation.
    :param items: list of strings to be formatted
    :param style: type of markdown list (either 'unordered' or 'ordered')
    :return: string containing the markdown-formatted list
    """
    if style == "unordered":
        return "\n".join([f"- {element}" for element in items])
    elif style == "ordered":
        return "\n".join([f"{idx}. {element}" for idx, element in enumerate(items, start=1)])
    else:
        raise ValueError("style must be either 'unordered' or 'ordered'")

