# Quran database module for searching and matching verses
from pathlib import Path
from Levenshtein import ratio
from offline_tarteel.normalizer import normalize_arabic
import json

DATA_FILE = Path(__file__).parent.parent.parent / "data" / "quran.json"

class QuranDatabase:
    def __init__(self, file_path: Path = DATA_FILE):
        with open(file_path) as file:
            self.verses = json.load(file)
        self._index_by_reference = {}
        self._index_by_chapter = {}
        for verse in self.verses:
            self._index_by_reference[(verse["surah"], verse["ayah"])] = verse
            self._index_by_chapter.setdefault(verse["surah"], []).append(verse)

    @property
    def total_verses_count(self):
        return len(self.verses)

    @property
    def chapter_count(self):
        return len(self._index_by_chapter)

    def find_verse(self, chapter: int, verse_num: int):
        return self._index_by_reference.get((chapter, verse_num))

    def find_chapter_verses(self, chapter: int):
        return self._index_by_chapter.get(chapter, [])

    def search_verses(self, query: str, limit: int = 5) -> list[dict]:
        query = normalize_arabic(query)
        results_with_scores = []
        for verse in self.verses:
            similarity = ratio(query, verse["text_clean"])
            results_with_scores.append({**verse, "similarity": similarity, "original_text": verse["text_uthmani"]})
        results_with_scores.sort(key=lambda x: x["similarity"], reverse=True)
        return results_with_scores[:limit]

    def find_best_match(self, query: str, min_similarity: float = 0.3, max_length: int = 3) -> dict | None:
        """Locate the most similar verse or consecutive verse sequence.
        Uses a two-stage approach: first identifies top single-verse matches (efficient),
        then explores multi-ayah sequences only near promising candidates.
        """
        query = normalize_arabic(query)
        if not query.strip():
            return None

        # Stage 1: Evaluate all individual verses
        scored_verses = []
        for verse in self.verses:
            match_score = ratio(query, verse["text_clean"])
            scored_verses.append((verse, match_score))
        scored_verses.sort(key=lambda x: x[1], reverse=True)

        current_best = {**scored_verses[0][0], "similarity": scored_verses[0][1]}
        best_score = scored_verses[0][1]

        # Stage 2: Examine multi-verse spans around top 20 candidates
        processed_chapters = set()
        for verse, _ in scored_verses[:20]:
            chapter = verse["surah"]
            if chapter in processed_chapters:
                continue
            processed_chapters.add(chapter)

            chapter_verses = self._index_by_chapter[chapter]
            for start_idx, sv in enumerate(chapter_verses):
                for span_size in range(2, max_length + 1):
                    if start_idx + span_size > len(chapter_verses):
                        break

                    selected_verses = chapter_verses[start_idx:start_idx + span_size]
                    merged_text = " ".join(cv["text_clean"] for cv in selected_verses)
                    match_score = ratio(query, merged_text)

                    if match_score > best_score:
                        best_score = match_score
                        current_best = {
                            "surah": chapter,
                            "ayah": selected_verses[0]["ayah"],
                            "ayah_end": selected_verses[-1]["ayah"],
                            "text": " ".join(cv["text_uthmani"] for cv in selected_verses),
                            "text_clean": merged_text,
                            "similarity": match_score,
                        }

        if best_score >= min_similarity:
            return current_best
        return None

