# Custom exceptions for the ChemAudit API client
class ChemAuditBaseException(Exception):
    """Base exception class for all ChemAudit client-related errors."""
    pass

class ServerCommunicationError(ChemAuditBaseException):
    """Raised when the server returns an error response."""
    def __init__(
        self, description: str, http_status: int = None, payload: dict = None
    ):
        super().__init__(description)
        self.http_status = http_status
        self.payload = payload or {}

    def __str__(self):
        if self.http_status:
            return f"Server Error {self.http_status}: {super().__str__()}"
        return super().__str__()

class ThrottlingError(ServerCommunicationError):
    """Raised when the request rate exceeds the allowed limit."""
    def __init__(self, description: str, wait_time: int = None):
        super().__init__(description, http_status=429)
        self.wait_time = wait_time

    def __str__(self):
        if self.wait_time:
            return f"Request throttled. Please wait {self.wait_time} seconds before retrying."
        return "Request throttled due to rate limiting."

class AuthorizationFailure(ServerCommunicationError):
    """Raised when API authentication fails."""
    def __init__(self, description: str = "Invalid or missing API credentials"):
        super().__init__(description, http_status=401)

class InputValidationException(ChemAuditBaseException):
    """Raised when input data validation fails."""
    pass

class JobNotFoundException(ServerCommunicationError):
    """Raised when a requested batch job cannot be located."""
    def __init__(self, job_identifier: str):
        super().__init__(f"Batch job not found: {job_identifier}", http_status=404)
        self.job_identifier = job_identifier

class ExecutionTimeoutException(ChemAuditBaseException):
    """Raised when a batch job execution exceeds the time limit."""
    pass

