import json
import sys
# Script to validate that the `fields.json` file generated by Claude during PDF analysis
# contains non-overlapping bounding boxes. Refer to forms.md for details.
from dataclasses import dataclass

@dataclass
class BoundingBoxAndField:
    bbox: list[float]
    box_type: str
    field: dict

# Returns a list of diagnostic messages printed to stdout for Claude to process.
def validate_bounding_boxes(fields_json_stream) -> list[str]:
    diagnostics = []
    fields_data = json.load(fields_json_stream)
    diagnostics.append(f"Processed {len(fields_data['form_fields'])} form fields")

    def boxes_overlap(b1, b2):
        no_horizontal_overlap = b1[0] >= b2[2] or b1[2] <= b2[0]
        no_vertical_overlap = b1[1] >= b2[3] or b1[3] <= b2[1]
        return not (no_horizontal_overlap or no_vertical_overlap)

    boxes_and_fields = []
    for field in fields_data["form_fields"]:
        boxes_and_fields.append(BoundingBoxAndField(field["label_bounding_box"], "label", field))
        boxes_and_fields.append(BoundingBoxAndField(field["entry_bounding_box"], "entry", field))

    found_issues = False
    for idx, current_box in enumerate(boxes_and_fields):
        # Quadratic complexity; can be optimized if performance becomes an issue.
        for jdx in range(idx + 1, len(boxes_and_fields)):
            other_box = boxes_and_fields[jdx]
            if (current_box.field["page_number"] == other_box.field["page_number"] and 
                boxes_overlap(current_box.bbox, other_box.bbox)):
                found_issues = True
                if current_box.field is other_box.field:
                    diagnostics.append(f"ERROR: overlapping label and entry bounding boxes for `{current_box.field['description']}` ({current_box.bbox}, {other_box.bbox})")
                else:
                    diagnostics.append(f"ERROR: overlapping {current_box.box_type} bounding box for `{current_box.field['description']}` ({current_box.bbox}) and {other_box.box_type} bounding box for `{other_box.field['description']}` ({other_box.bbox})")
                if len(diagnostics) >= 20:
                    diagnostics.append("Stopping further checks; resolve bounding box issues and re-run")
                    return diagnostics

        if current_box.box_type == "entry":
            if "entry_text" in current_box.field:
                font_size = current_box.field["entry_text"].get("font_size", 14)
                box_height = current_box.bbox[3] - current_box.bbox[1]
                if box_height < font_size:
                    found_issues = True
                    diagnostics.append(f"ERROR: entry bounding box height ({box_height}) for `{current_box.field['description']}` is insufficient for text content (font size: {font_size}). Enlarge the box or reduce font size.")
                    if len(diagnostics) >= 20:
                        diagnostics.append("Stopping further checks; resolve bounding box issues and re-run")
                        return diagnostics

    if not found_issues:
        diagnostics.append("OK: All bounding boxes are properly spaced")
    return diagnostics

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: validate_bounding_boxes.py [fields.json]")
        sys.exit(1)
    # Expected input format matches `fields.json` as specified in forms.md.
    with open(sys.argv[1]) as input_file:
        output_messages = validate_bounding_boxes(input_file)
    for line in output_messages:
        print(line)

