# Modified version of PyTorch's ImageFolder to support images from current directory and subdirectories
import numpy as np
import torch.utils.data as data
from PIL import Image
import os
import os.path

# Supported image file extensions
IMAGE_EXTENSIONS = [
    '.jpg', '.JPG', '.jpeg', '.JPEG',
    '.png', '.PNG', '.ppm', '.PPM', '.bmp', '.BMP',
    '.tif', '.TIF', '.tiff', '.TIFF',
]

def has_image_extension(filename):
    return any(filename.endswith(ext) for ext in IMAGE_EXTENSIONS)

def collect_image_paths(directory, max_count=float("inf")):
    image_list = []
    assert os.path.isdir(directory) or os.path.islink(directory), '%s is not a valid directory' % directory

    for dirpath, _, filenames in sorted(os.walk(directory, followlinks=True)):
        for filename in filenames:
            if has_image_extension(filename):
                full_path = os.path.join(dirpath, filename)
                image_list.append(full_path)

    return image_list[:min(max_count, len(image_list))]

def default_image_loader(filepath):
    return Image.open(filepath).convert('RGB')

class FlexibleImageDataset(data.Dataset):
    def __init__(self, root_dir, transform=None, include_paths=False,
                 image_loader=default_image_loader):
        image_files = collect_image_paths(root_dir)

        if len(image_files) == 0:
            raise(RuntimeError("No images found in: " + root_dir + "\n"
                               "Supported formats: " + ",".join(IMAGE_EXTENSIONS)))

        self.base_dir = root_dir
        self.image_paths = image_files
        self.transform = transform
        self.include_paths = include_paths
        self.load_func = image_loader

    def __getitem__(self, idx):
        img_path = self.image_paths[idx]
        image = self.load_func(img_path)

        if self.transform is not None:
            image = self.transform(image)

        if self.include_paths:
            return image, img_path
        else:
            return image

    def __len__(self):
        return len(self.image_paths)

