@observe(as_type="generation")
def perform_search(tier: str, query_text: str, search_focus: str = "internet"):
    if not API_KEY:
        print(json.dumps({"error": "No Perplexity API key found."}))
        return

    selected_tier = SEARCH_TIERS.get(tier)
    if not selected_tier:
        print(json.dumps({"error": f"Unknown tier: {tier}. Valid options: quick, pro, deep"}))
        return

    # Update Langfuse trace with session/user context
    if TRACING_ENABLED:
        try:
            lf_client = get_client()
            lf_client.update_current_trace(
                session_id=generate_session_id(),
                user_id=DEFAULT_USER_IDENTIFIER,
                tags=[f"search-{tier}", f"focus-{search_focus}"],
                metadata={"tier": tier, "focus": search_focus}
            )
        except Exception:
            pass

    request_headers = {
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json"
    }

    request_payload = {
        "model": selected_tier["model_name"],
        "messages": [
            {"role": "system", "content": selected_tier["system_message"]},
            {"role": "user", "content": query_text}
        ],
        "search_domain_filter": [],
        "return_citations": True,
        "return_related_questions": tier == "deep"
    }

    if search_focus != "internet":
        request_payload["search_focus"] = search_focus

    start_time = datetime.now()

    try:
        response = requests.post(
            f"{BASE_SERVER_URL}/chat/completions",
            headers=request_headers,
            json=request_payload,
            timeout=60
        )
        response.raise_for_status()
        response_data = response.json()

        duration_seconds = (datetime.now() - start_time).total_seconds()

        output_result = {
            "tier": tier,
            "model": selected_tier["model_name"],
            "query": query_text,
            "elapsed_seconds": round(duration_seconds, 1),
            "answer": response_data["choices"][0]["message"]["content"],
            "citations": response_data.get("citations", []),
        }

        if response_data.get("related_questions"):
            output_result["related_questions"] = response_data["related_questions"]

        if response_data.get("usage"):
            output_result["tokens"] = {
                "prompt": response_data["usage"].get("prompt_tokens"),
                "completion": response_data["usage"].get("completion_tokens"),
                "total": response_data["usage"].get("total_tokens")
            }

        if TRACING_ENABLED:
            try:
                lf_client = get_client()
                lf_client.update_current_generation(
                    model=selected_tier["model_name"],
                    input=query_text,
                    output=output_result.get("answer", ""),
                    usage_details={
                        "input": output_result.get("tokens", {}).get("prompt", 0),
                        "output": output_result.get("tokens", {}).get("completion", 0),
                    },
                    metadata={
                        "tier": tier,
                        "focus": search_focus,
                        "citations": output_result.get("citations", []),
                        "elapsed_seconds": output_result.get("elapsed_seconds"),
                    }
                )
            except Exception:
                pass

        print(json.dumps(output_result, indent=2))
        return output_result

    except requests.exceptions.HTTPError as http_error:
        print(json.dumps({
            "error": f"HTTP {http_error.response.status_code}",
            "detail": http_error.response.text[:500] if http_error.response else str(http_error)
        }))
    except Exception as general_error:
        print(json.dumps({"error": str(general_error)}))

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="AgxntSix Deep Search (Perplexity)")
    parser.add_argument("tier", choices=["quick", "pro", "deep"], 
                        help="Search depth: quick (sonar), pro (sonar-pro), deep (sonar-reasoning-pro)")
    parser.add_argument("query", help="Search query text")
    parser.add_argument("--focus", default="internet", 
                        help="Search focus area (internet, academic, news, youtube, reddit)")

    arguments = parser.parse_args()
    perform_search(arguments.tier, arguments.query, arguments.focus)

    if TRACING_ENABLED:
        try:
            get_client().flush()
        except Exception:
            pass

