class BaseTrait(Service):
    def __init__(self, config=None):
        if config is None:
            config = {}
        self.config = config
        region = config.get('region', REGION_CN_NORTH1)
        service_info_dict = config.get('service_info_map', {})
        self.service_info = BaseTrait.get_service_info(region, service_info_dict)
        self.api_info_map = BaseTrait.get_api_info()
        if config.get('ak', None) and config.get('sk', None):
            self.set_ak(config['ak'])
            self.set_sk(config['sk'])
        super(BaseTrait, self).__init__(self.service_info, self.api_info_map)

    @staticmethod
    def get_service_info(region, service_info_dict):
        service_info = service_info_dict.get(region, None)
        if not service_info:
            raise Exception('BaseService does not support region %s' % region)
        return service_info

    @staticmethod
    def get_api_info():
        return api_info_map

    def set_api_info(self, additional_api_info):
        self.api_info_map = {**self.api_info_map, **additional_api_info}
        return

    def mcp_get(self, action, parameters={}, doseq=0):
        response = self.get(action, parameters, doseq)
        if response == '':
            raise Exception("%s: empty response" % action)
        response_json = json.loads(json.dumps(response))
        return response_json

    def mcp_post(self, action, parameters={}, body={}):
        response = self.json(action, parameters, body)
        if response == '':
            raise Exception("%s: empty response" % action)
        response_json = json.loads(json.dumps(response))
        return response_json

