# Custom error codes for character loading operations
from enum import IntEnum

class StatusCode(IntEnum):
    OK = 0
    CONNECTION_ISSUE = 10
    PROCESSING_FAILURE = 20
    INPUT_CHECK_FAILED = 30
    STORAGE_PROBLEM = 40

class CharacterLoadException(Exception):
    status_code = StatusCode.PROCESSING_FAILURE

class ConnectionException(CharacterLoadException):
    status_code = StatusCode.CONNECTION_ISSUE

class ProcessingException(CharacterLoadException):
    status_code = StatusCode.PROCESSING_FAILURE

class InputCheckException(CharacterLoadException):
    status_code = StatusCode.INPUT_CHECK_FAILED

class StorageException(CharacterLoadException):
    status_code = StatusCode.STORAGE_PROBLEM

