import gym
import numpy as np
from .common import TimeStep

class EpisodeMonitor(gym.ActionWrapper):
    """A wrapper to track and compute episode returns and durations."""
    def __init__(self, env: gym.Env):
        super().__init__(env)
        self._clear_stats()
        self.all_timesteps = 0

    def _clear_stats(self):
        self.episode_reward = 0.0
        self.step_count_in_episode = 0
        self.start_timestamp = time.time()

    def step(self, action: np.ndarray) -> TimeStep:
        obs, reward, done, info = self.env.step(action)
        self.episode_reward += reward
        self.step_count_in_episode += 1
        self.all_timesteps += 1
        info['cumulative'] = {'timesteps': self.all_timesteps}

        if done:
            info['episode_stats'] = {}
            info['episode_stats']['return'] = self.episode_reward
            info['episode_stats']['length'] = self.step_count_in_episode
            info['episode_stats']['duration'] = time.time() - self.start_timestamp

            if hasattr(self.env, 'get_normalized_score'):
                normalized_return = self.env.get_normalized_score(
                    info['episode_stats']['return']) * 100.0
                info['episode_stats']['return'] = normalized_return

        return obs, reward, done, info

    def reset(self, **kwargs) -> np.ndarray:
        self._clear_stats()
        return self.env.reset(**kwargs)

import json
import os

def convert_severity_to_sarif_level(severity):
    severity_str = (severity or "").upper()
    if severity_str in {"CRITICAL", "HIGH"}:
        return "error"
    if severity_str == "MEDIUM":
        return "warning"
    return "note"

def sanitize_file_path_for_sarif(file_path=None):
    raw_input = str(file_path or "")
    sanitized = raw_input.replace("\\", "/").strip()
    if sanitized.lower().startswith("file://"):
        sanitized = sanitized[7:]
    try:
        base_dir = os.getcwd().replace("\\", "/").rstrip("/") + "/"
        if sanitized.startswith(base_dir):
            sanitized = sanitized[len(base_dir):]
    except Exception:
        pass
    sanitized = sanitized.lstrip("/")
    return sanitized or "unknown"

class SarifReportGenerator:
    def __init__(self, issues, tool_name="Skylos", version="1.0.0"):
        self.issues = issues
        self.tool_name = tool_name
        self.version = version

    def produce(self):
        sarif_output = {
            "version": "2.1.0",
            "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
            "runs": [
                {
                    "tool": {
                        "driver": {
                            "name": self.tool_name,
                            "version": self.version,
                            "rules": self._collect_unique_rules(),
                        }
                    },
                    "results": self._collect_results(),
                }
            ],
        }
        return sarif_output

    def export(self, destination):
        with open(destination, "w", encoding="utf-8") as file:
            json.dump(self.produce(), file, indent=2)

    def _collect_unique_rules(self):
        rule_dict = {}
        for issue in self.issues:
            rule_key = str(issue.get("rule_id") or "UNKNOWN")
            if rule_key in rule_dict:
                continue
            message_body = str(issue.get("message") or "")
            default_title = message_body.splitlines()[0] if message_body.strip() else rule_key
            title_candidate = (
                issue.get("title") or issue.get("rule_name") or default_title
            )
            formatted_title = str(title_candidate).strip()
            if len(formatted_title) > 120:
                formatted_title = formatted_title[:117] + "..."
            level = convert_severity_to_sarif_level(issue.get("severity"))
            category = str(issue.get("category") or "").upper()
            tag_list = []
            if category:
                tag_list.append(category.lower())
            if category == "SECURITY":
                tag_list.append("security")
            rule_dict[rule_key] = {
                "id": rule_key,
                "shortDescription": {"text": formatted_title or rule_key},
                "defaultConfiguration": {"level": level},
                "properties": {"tags": tag_list},
                "helpUri": f"https://docs.skylos.dev/rules/{rule_key}",
            }
        return list(rule_dict.values())

    def _collect_results(self):
        result_list = []
        for issue in self.issues:
            rule_key = str(issue.get("rule_id") or "UNKNOWN")
            level = convert_severity_to_sarif_level(issue.get("severity"))
            message_text = str(issue.get("message") or "(no message)")
            file_location = sanitize_file_path_for_sarif(
                issue.get("file_path") or issue.get("file")
            )
            line_num = int(issue.get("line_number") or issue.get("line") or 1)
            col_num = int(issue.get("col_number") or issue.get("col") or 1)
            if line_num < 1:
                line_num = 1
            if col_num < 1:
                col_num = 1
            snippet_content = issue.get("snippet")
            if snippet_content is not None:
                snippet_content = str(snippet_content)[:2000]
            category_label = str(issue.get("category") or "QUALITY").upper()
            result_entry = {
                "ruleId": rule_key,
                "level": level,
                "message": {"text": message_text},
                "properties": {"category": category_label},
                "locations": [
                    {
                        "physicalLocation": {
                            "artifactLocation": {"uri": file_location},
                            "region": {
                                "startLine": line_num,
                                "startColumn": col_num,
                            },
                        }
                    }
                ],
            }
            if snippet_content:
                result_entry["locations"][0]["physicalLocation"]["region"]["snippet"] = {
                    "text": snippet_content
                }
            result_list.append(result_entry)
        return result_list

# Upgrade function to add smtp_auth column if not exists
def upgrade(connection):
    cursor = connection.execute("PRAGMA table_info(smtp_config)")
    existing_columns = [row[1] for row in cursor.fetchall()]
    if 'smtp_auth' not in existing_columns:
        connection.execute("ALTER TABLE smtp_config ADD COLUMN smtp_auth BOOLEAN DEFAULT 1")
        connection.commit()

