# Convert GPA values to letter grades based on a custom grading scale
def convert_to_letter_grades(gpa_list):
    """Converts a list of GPA scores into corresponding letter grades.

    The grading scale is as follows:
             GPA       |    Letter grade
              4.0                A+
            > 3.7                A 
            > 3.3                A- 
            > 3.0                B+
            > 2.7                B 
            > 2.3                B-
            > 2.0                C+
            > 1.7                C
            > 1.3                C-
            > 1.0                D+ 
            > 0.7                D 
            > 0.0                D-
              0.0                E

    Example:
    convert_to_letter_grades([4.0, 3, 1.7, 2, 3.5]) ==> ['A+', 'B', 'C-', 'C', 'A-']
    """
    result = []

    for score in gpa_list:
        if score == 4.0:
            result.append('A+')
        elif score > 3.7:
            result.append('A')
        elif score > 3.3:
            result.append('A-')
        elif score > 3.0:
            result.append('B+')
        elif score > 2.7:
            result.append('B')
        elif score > 2.3:
            result.append('B-')
        elif score > 2.0:
            result.append('C+')
        elif score > 1.7:
            result.append('C')
        elif score > 1.3:
            result.append('C-')
        elif score > 1.0:
            result.append('D+')
        elif score > 0.7:
            result.append('D')
        elif score > 0.0:
            result.append('D-')
        else:
            result.append('E')

    return result

