# Process prompt file and analyze project dependencies 
from pathlib import Path
from pdd.auto_deps_main import auto_deps_main
from pdd import DEFAULT_STRENGTH
import click

@click.command('auto-deps')
@click.option('--overwrite', is_flag=True, help='Overwrite existing files if present')
@click.option('--silent', is_flag=True, help='Suppress informational messages')
@click.option('--confidence', default=DEFAULT_STRENGTH, help='Confidence level for dependency inference')
@click.option('--randomness', default=0.0, help='Randomness factor for dependency generation')
@click.option('--prompt-input', default='prompts/get_extension_python.prompt', help='Location of the input prompt template')
@click.option('--source-dir', default='context/*_example.py', help='Directory with example source files to scan')
@click.option('--deps-csv', default='./project_dependencies.csv', help='Path to CSV storing dependency metadata')
@click.option('--dest-dir', default='./', help='Directory where modified prompt will be saved')
@click.option('--reanalyze', is_flag=True, help='Force re-scanning of source directory')
def entry_point(overwrite, silent, confidence, randomness, prompt_input, source_dir, deps_csv, dest_dir, reanalyze):
    """Analyze code dependencies and update prompt accordingly."""
    # Set up Click context with provided options
    ctx = click.get_current_context()
    ctx.params['force'] = overwrite
    ctx.params['quiet'] = silent
    ctx.obj = {
        'strength': confidence,
        'temperature': randomness
    }
    try:
        updated_prompt, cost_sum, llm_name = auto_deps_main(
            ctx=ctx,
            prompt_file=prompt_input,
            directory_path=source_dir,
            auto_deps_csv_path=deps_csv,
            output=dest_dir,
            force_scan=reanalyze
        )
        # Output analysis results
        print("Updated Prompt:")
        print(updated_prompt)
        print(f"Total Cost: ${cost_sum:.6f}")
        print(f"Model Used: {llm_name}")
    except Exception as err:
        print(f"Error occurred: {err}")
        raise click.Abort()

if __name__ == "__main__":
    entry_point()

