import json
import sys
import urllib.request

SERVER_ADDRESS = "http://127.0.0.1:9501"

def make_rpc_call(method_name: str, parameters: dict = None, request_id=None):
    payload = json.dumps({
        "jsonrpc": "2.0",
        "id": request_id,
        "method": method_name,
        "params": parameters or {},
    }).encode()

    request = urllib.request.Request(
        f"{SERVER_ADDRESS}/message",
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.loads(response.read())
    except Exception as error:
        return {"jsonrpc": "2.0", "id": request_id, "error": {"code": -1, "message": str(error)}}

def process_input():
    for input_line in sys.stdin:
        input_line = input_line.strip()
        if not input_line:
            continue
        try:
            message = json.loads(input_line)
        except json.JSONDecodeError:
            continue

        method = message.get("method", "")
        req_id = message.get("id")
        params = message.get("params", {})

        if method == "notifications/initialized":
            continue

        result = make_rpc_call(method, params, req_id)
        sys.stdout.write(json.dumps(result) + "\n")
        sys.stdout.flush()

if __name__ == "__main__":
    process_input()

