# Modified version with renamed variables and reordered statements
import torch.nn as nn
import re

class IdentityMapping(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x, *args, **kwargs):
        return x

    @property
    def config(self):
        return {"mm_projector_type": 'identity'}

class SimpleResidualBlock(nn.Module):
    def __init__(self, num_channels):
        super().__init__()
        self.norm_before = nn.LayerNorm(num_channels)
        self.network = nn.Sequential(
            nn.Linear(num_channels, num_channels),
            nn.GELU(),
            nn.Linear(num_channels, num_channels)
        )

    def forward(self, x):
        x = self.norm_before(x)
        return x + self.network(x)

def construct_vision_projector(model_config, delay_loading=False, **kwargs):
    proj_type = getattr(model_config, 'mm_projector_type', 'linear')

    if proj_type == 'linear':
        return nn.Linear(model_config.mm_hidden_size, model_config.hidden_size)

    mlp_gelu_pattern = re.match(r'^mlp(\d+)x_gelu$', proj_type)
    if mlp_gelu_pattern:
        depth_mlp = int(mlp_gelu_pattern.group(1))
        layers = [nn.Linear(model_config.mm_hidden_size, model_config.hidden_size)]

        for _ in range(1, depth_mlp):
            layers.append(nn.GELU())
            layers.append(nn.Linear(model_config.hidden_size, model_config.hidden_size))

        return nn.Sequential(*layers)

    if proj_type == 'identity':
        return IdentityMapping()

    raise ValueError(f'Unknown projector type: {proj_type}')

