def merge_lora_weights(unet_model, vae_model=None, checkpoint_path=None, blend_factor=1.0, base_model_path=""):
    if checkpoint_path is None:
        return unet_model

    if checkpoint_path.endswith(".ckpt"):
        loaded_state = torch.load(checkpoint_path)['state_dict']
    elif checkpoint_path.endswith(".safetensors"):
        temp_state_dict = {}
        with safe_open(checkpoint_path, framework="pt", device="cpu") as f:
            for tensor_key in f.keys():
                temp_state_dict[tensor_key] = f.get_tensor(tensor_key)

        has_lora = all("lora" in k for k in temp_state_dict.keys())
        if not has_lora:
            loaded_state = temp_state_dict
        else:
            loaded_state = {}
            with safe_open(base_model_path, framework="pt", device="cpu") as f:
                for tensor_key in f.keys():
                    loaded_state[tensor_key] = f.get_tensor(tensor_key)

    updated_unet = convert_ldm_unet_checkpoint(loaded_state, unet_model.config)
    current_unet_state = unet_model.state_dict()
    for param_name in updated_unet:
        updated_unet[param_name] = blend_factor * updated_unet[param_name] + (1.0 - blend_factor) * current_unet_state[param_name]
    unet_model.load_state_dict(updated_unet, strict=False)

    if vae_model is not None:
        updated_vae = convert_ldm_vae_checkpoint(loaded_state, vae_model.config)
        vae_model.load_state_dict(updated_vae)

    return unet_model, vae_model

# Modified version of ConcretePass with renamed variables and reordered logic
import torch.fx as fx
from graph_net.torch.dim_gen_passes import DimensionGeneralizationPass
from collections import namedtuple
import os

class CustomDimensionPass(DimensionGeneralizationPass):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    @classmethod
    def get_pass_name(cls) -> str:
        return os.path.basename(__file__)[:-3]

    def should_transform(self, traced_module: fx.GraphModule) -> bool:
        # Skip if batch dimension (axis 0) is involved
        if 0 in self.axes:
            return False
        return any(self._requires_transformation(node) for node in traced_module.graph.nodes)

    def target_function(self):
        return torch.arange

    def _requires_transformation(self, node) -> bool:
        # Check if node needs rewriting based on structure and arguments
        if node.op != "call_function":
            return False
        if node.target != self.target_function():
            return False

        args = node.args
        if len(args) == 1:
            return args[0] == self.dim
        elif len(args) == 2:
            return args[0] == 0 and args[1] == self.dim
        else:
            return False

    def transform(self, traced_module: fx.GraphModule) -> fx.GraphModule:
        # Build a new graph with transformed nodes
        updated_graph = fx.Graph()
        node_mapping = {}

        NodeShapeInfo = namedtuple("NodeShapeInfo", ["node", "dim_axis"])
        current_shape_info = None

        def update_current_shape_info(original_node, new_node):
            nonlocal current_shape_info
            tensor_meta = original_node.meta.get("tensor_meta")
            if tensor_meta is None:
                return
            if not hasattr(tensor_meta, "shape"):
                return

            shape = tensor_meta.shape
            for idx, dim_size in enumerate(shape):
                if dim_size == self.dim and idx > 0:
                    current_shape_info = NodeShapeInfo(node=new_node, dim_axis=idx)
                    return

        def resolve_argument(index, arg, total_args):
            # Only replace specific argument positions (last arg in 2-arg case, or only arg in 1-arg case)
            if not ((total_args == 2 and index == 1) or (total_args == 1 and index == 0)):
                return node_mapping[arg] if arg in node_mapping else arg

            # Replace with dynamic size lookup
            assert arg == self.dim
            size_call = updated_graph.call_method(
                "size", args=(current_shape_info.node, current_shape_info.dim_axis)
            )
            return size_call

        def process_node(original_node):
            # Handle nodes that don't need transformation
            if not (self._requires_transformation(original_node) and current_shape_info is not None):
                new_node = updated_graph.node_copy(original_node, lambda x: node_mapping[x])
                update_current_shape_info(original_node, new_node)
                return new_node

            # Transform the node with dynamic dimension replacement
            transformed_args = tuple(
                resolve_argument(i, arg, len(original_node.args))
                for i, arg in enumerate(original_node.args)
            )

            new_node = updated_graph.call_function(
                self.target_function(),
                args=transformed_args,
                kwargs=original_node.kwargs
            )
            return new_node

        # Process all nodes from original graph
        for node in traced_module.graph.nodes:
            node_mapping[node] = process_node(node)

        # Apply new graph and recompile
        traced_module.graph = updated_graph
        traced_module.recompile()
        return traced_module

# Helper functions to extract identifiers from payload dictionaries
def get_turn_identifier(data: Any) -> Optional[str]:
    if not isinstance(data, dict):
        return None
    for field in ("turnId", "turn_id", "id"):
        candidate = data.get(field)
        if isinstance(candidate, str):
            return candidate
    nested_turn = data.get("turn")
    if isinstance(nested_turn, dict):
        for field in ("id", "turnId", "turn_id"):
            candidate = nested_turn.get(field)
            if isinstance(candidate, str):
                return candidate
    nested_item = data.get("item")
    if isinstance(nested_item, dict):
        for field in ("turnId", "turn_id", "id"):
            candidate = nested_item.get(field)
            if isinstance(candidate, str):
                return candidate
    return None

def _get_thread_identifier_from_container(data: Any) -> Optional[str]:
    if not isinstance(data, dict):
        return None
    for field in ("threadId", "thread_id"):
        candidate = data.get(field)
        if isinstance(candidate, str):
            return candidate
    nested_thread = data.get("thread")
    if isinstance(nested_thread, dict):
        for field in ("id", "threadId", "thread_id"):
            candidate = nested_thread.get(field)
            if isinstance(candidate, str):
                return candidate
    return None

def get_thread_id_for_turn(payload: Any) -> Optional[str]:
    if not isinstance(payload, dict):
        return None
    for source in (payload, payload.get("turn"), payload.get("item")):
        thread_id = _get_thread_identifier_from_container(source)
        if thread_id:
            return thread_id
    return None

def get_thread_identifier(payload: Any) -> Optional[str]:
    if not isinstance(payload, dict):
        return None
    for field in ("threadId", "thread_id", "id"):
        candidate = payload.get(field)
        if isinstance(candidate, str):
            return candidate
    nested_thread = payload.get("thread")
    if isinstance(nested_thread, dict):
        for field in ("id", "threadId", "thread_id"):
            candidate = nested_thread.get(field)
            if isinstance(candidate, str):
                return candidate
    return None

