def char_frequency(text):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the highest frequency and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    char_frequency('x y z') == {'x': 1, 'y': 1, 'z': 1}
    char_frequency('x y y x') == {'x': 2, 'y': 2}
    char_frequency('x y z x y') == {'x': 2, 'y': 2}
    char_frequency('y y y y x') == {'y': 4}
    char_frequency('') == {}
    """
    if not text or not text.strip():
        return {}

    characters = text.split()
    frequencies = {}

    for char in characters:
        if char:
            frequencies[char] = frequencies.get(char, 0) + 1

    if not frequencies:
        return {}

    max_frequency = max(frequencies.values())

    return {char: freq for char, freq in frequencies.items() if freq == max_frequency}

# Modified version of fill_fillable_fields.py with Type I clone transformations
import sys
import json
from extract_form_field_info import get_field_info
from pypdf import PdfReader, PdfWriter

def populate_pdf_fields(input_file: str, json_data_path: str, output_file: str):
    with open(json_data_path) as file:
        data = json.load(file)

    fields_by_page = {}
    for item in data:
        if "value" in item:
            field_identifier = item["field_id"]
            page_num = item["page"]
            if page_num not in fields_by_page:
                fields_by_page[page_num] = {}
            fields_by_page[page_num][field_identifier] = item["value"]

    reader = PdfReader(input_file)
    has_error = False
    field_metadata = get_field_info(reader)
    fields_by_ids = {f["field_id"]: f for f in field_metadata}

    for item in data:
        existing_field = fields_by_ids.get(item["field_id"])
        if not existing_field:
            has_error = True
            print(f"ERROR: `{item['field_id']}` is not a valid field ID")
        elif item["page"] != existing_field["page"]:
            has_error = True
            print(
                f"ERROR: Incorrect page number for `{item['field_id']}` (got {item['page']}, expected {existing_field['page']})"
            )
        else:
            if "value" in item:
                err = validate_field_value(existing_field, item["value"])
                if err:
                    print(err)
                    has_error = True

    if has_error:
        sys.exit(1)

    writer = PdfWriter(clone_from=reader)
    for page, field_values in fields_by_page.items():
        writer.update_page_form_field_values(writer.pages[page - 1], field_values, auto_regenerate=False)

    writer.set_need_appearances_writer(True)
    with open(output_file, "wb") as file:
        writer.write(file)

def validate_field_value(field_info, field_value):
    field_type = field_info["type"]
    field_id = field_info["field_id"]

    if field_type == "checkbox":
        checked_val = field_info["checked_value"]
        unchecked_val = field_info["unchecked_value"]
        if field_value != checked_val and field_value != unchecked_val:
            return f'ERROR: Invalid value "{field_value}" for checkbox field "{field_id}". The checked value is "{checked_val}" and the unchecked value is "{unchecked_val}"'

    elif field_type == "radio_group":
        option_values = [opt["value"] for opt in field_info["radio_options"]]
        if field_value not in option_values:
            return f'ERROR: Invalid value "{field_value}" for radio group field "{field_id}". Valid values are: {option_values}'

    elif field_type == "choice":
        choice_values = [opt["value"] for opt in field_info["choice_options"]]
        if field_value not in choice_values:
            return (
                f'ERROR: Invalid value "{field_value}" for choice field "{field_id}". Valid values are: {choice_values}'
            )

    return None

def apply_pypdf_patch():
    from pypdf.constants import FieldDictionaryAttributes
    from pypdf.generic import DictionaryObject

    original_get_inherited = DictionaryObject.get_inherited

    def patched_get_inherited(self, key: str, default=None):
        result = original_get_inherited(self, key, default)
        if (
            key == FieldDictionaryAttributes.Opt
            and isinstance(result, list)
            and all(isinstance(v, list) and len(v) == 2 for v in result)
        ):
            result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = patched_get_inherited

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    apply_pypdf_patch()
    input_pdf = sys.argv[1]
    fields_json = sys.argv[2]
    output_pdf = sys.argv[3]
    populate_pdf_fields(input_pdf, fields_json, output_pdf)

