import re

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    def replace_spaces(match):
        space_chars = match.group(0)
        if len(space_chars) > 2:
            return '-'
        else:
            return '_' * len(space_chars)

    return re.sub(r' +', replace_spaces, text)

# A picklable class for initializing device configuration
import torch
from .tensor_operations import Operation

class DeviceConfigurator:
    """A class to configure and initialize device settings."""
    def __init__(self, gpu_count, gpu_ids=None):
        self.gpu_count = gpu_count
        self.gpu_ids = gpu_ids

    def __call__(self):
        """Set up the device for the current process."""
        import multiprocessing as mp
        proc_name = mp.current_process().name
        proc_id = int(proc_name.split("-")[-1]) - 1
        Operation.local_idx = proc_id

        if self.gpu_count > 0:
            if self.gpu_ids is not None:
                selected_gpu = self.gpu_ids[proc_id % self.gpu_count]
            else:
                selected_gpu = proc_id % self.gpu_count
            torch.cuda.set_device(selected_gpu)
            Operation.global_device = f"cuda:{selected_gpu}"
        else:
            Operation.global_device = "cpu"

        torch.set_grad_enabled(False)

def create_device_configurator(config):
    """Provides a device configurator instance suitable for serialization."""
    return DeviceConfigurator(config.gpu_count, config.gpu_ids)

def single_process_setup(config):
    """Configure device in single-process mode."""
    if config.gpu_count > 0:
        if config.gpu_ids is not None:
            Operation.global_device = f"cuda:{config.gpu_ids[0]}"
        else:
            Operation.global_device = "cuda"
    else:
        Operation.global_device = "cpu"

    torch.set_grad_enabled(False)

