# Extract text content from an Excel file 
import pandas as pd
import sys
import os

def pull_text_from_excel(excel_filepath):
    collected_data = []
    try:
        excel_file = pd.ExcelFile(excel_filepath)
        for sheet in excel_file.sheet_names:
            dataframe = excel_file.parse(sheet)
            collected_data.append(f"--- Sheet: {sheet} ---\n")
            # Transform DataFrame into a readable string format (e.g., tabular view)
            collected_data.append(dataframe.to_string(index=False))
            collected_data.append("\n\n")
        return "".join(collected_data)
    except Exception as error:
        return f"Error pulling text from Excel: {error}"

