import sys
import platform

def check_linux_kernel_version():
    if sys.platform != "linux":
        return False
    kernel_release = platform.release()  # e.g., '6.11.0-24-generic'
    version_components = kernel_release.split(".")
    try:
        major_version = int(version_components[0])
        minor_version = int(version_components[1])
        return major_version == 6 and minor_version == 11
    except (IndexError, ValueError):
        return False

