# Lightweight utility to search the codebase for typical OS-specific patterns
# and produce a concise summary. Designed for maintainers to execute locally or in CI.
# Command:
#     python tools/scan_platform_issues.py
# Looks for:
#  - Shell scripts containing shebangs (bash/sh)
#  - Instructions that alter Unix file permissions (chown/chmod/id)
#  - Audio/X server/pulseaudio-related tools (pactl, pulseaudio)
#  - s6/supervisord container orchestration helpers
#  - Docker-compose or Dockerfile references
"""
import re
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parents[1]

REGEX_PATTERNS = {
    "shebang_bash": re.compile(r"^#!.*\b(bash|sh)\b"),
    "permission_ops": re.compile(r"\b(chown|chmod|id -u|id -g)\b"),
    "audio_pulse": re.compile(r"\b(pulseaudio|pactl)\b"),
    "s6_helpers": re.compile(r"\bs6-"),
    "unix_socket_ref": re.compile(r"unix:"),
    "docker_refs": re.compile(
        r"docker[- ]?compose|Dockerfile|docker-compose.yml", re.IGNORECASE
    ),
}

FINDINGS = []

for item in BASE_DIR.rglob("*"):
    if item.is_file() and item.suffix in (".sh", ".py", ""):
        try:
            content = item.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue

        for key, pattern in REGEX_PATTERNS.items():
            if pattern.search(content):
                FINDINGS.append((key, str(item)))

if not FINDINGS:
    print("No platform-specific constructs detected.")
else:
    print("Platform-specific detection report:")
    grouped = {}
    for tag, filepath in FINDINGS:
        grouped.setdefault(tag, []).append(filepath)

    for tag, files in grouped.items():
        print(f"\n[{tag}]")
        for f in files[:30]:
            print(" -", f)
        if len(files) > 30:
            print("  ... additional entries omitted")

print("\nDetection process finished.")

# Handle file knowledge creation via API endpoint
from django.http import JsonResponse
from rest_framework.decorators import action
from apps.core.decorators.api_permission import HasPermission
from apps.core.logger import opspilot_logger as logger
from apps.core.utils.viewset_utils import LanguageViewSet
from apps.opspilot.models import FileKnowledge, KnowledgeDocument, ContentFile
from apps.opspilot.serializers import FileKnowledgeSerializer

class FileKnowledgeViewSet(LanguageViewSet):
    queryset = FileKnowledge.objects.all()
    serializer_class = FileKnowledgeSerializer
    ordering = ("-id",)
    search_fields = ("name",)

    @action(methods=["POST"], detail=False)
    @HasPermission("knowledge_document-Add")
    def create_file_knowledge(self, request):
        data = request.data
        uploaded_files = request.FILES.getlist("files")
        response_data = self.process_file_upload(uploaded_files, data, request.user.username, request.user.domain)
        return JsonResponse(response_data)

    def process_file_upload(self, files, kwargs, username, domain):
        file_knowledge_objects = []
        try:
            for file in files:
                filename = file.name
                if not filename:
                    logger.warning(f"Encountered file with no name: {filename}")
                    continue

                kwargs["name"] = filename
                kwargs["knowledge_source_type"] = "file"

                created_doc = KnowledgeDocument.create_new_document(kwargs, username, domain)
                file_content = ContentFile(file.read(), name=filename)

                file_knowledge_objects.append(
                    FileKnowledge(file=file_content, knowledge_document_id=created_doc.id)
                )

            created_records = FileKnowledge.objects.bulk_create(file_knowledge_objects, batch_size=10)
            return {"result": True, "data": [record.knowledge_document_id for record in created_records]}

        except Exception as error:
            logger.exception(f"Error during file import: {error}")
            error_msg = self.loader.get("error.file_import_failed") or "File import operation failed."
            return {"result": False, "message": error_msg}

