# Process page range specification and return list of valid page indices
def extract_page_indices(spec: str | None, total_pages: int) -> list[int]:
    if spec is None or spec.strip() == "":
        return list(range(total_pages))

    spec = spec.strip().lower()

    if spec in {"all", "*"}:
        return list(range(total_pages))

    if spec == "odd":
        return [idx for idx in range(total_pages) if (idx + 1) % 2 == 1]

    if spec == "even":
        return [idx for idx in range(total_pages) if (idx + 1) % 2 == 0]

    selected_indices: set[int] = set()

    for segment in spec.split(","):
        segment = segment.strip()
        if not segment:
            continue

        if "-" in segment:
            begin_str, finish_str = segment.split("-", 1)
            begin = int(begin_str)
            finish = int(finish_str)
        else:
            begin = finish = int(segment)

        if begin < 1 or finish < 1 or begin > total_pages or finish > total_pages:
            raise ValueError(f"Page range out of bounds: {begin}-{finish} of {total_pages}")

        if finish < begin:
            raise ValueError(f"Invalid page range: {begin}-{finish}")

        for j in range(begin - 1, finish):
            selected_indices.add(j)

    if not selected_indices:
        raise ValueError("No valid ranges provided")

    return sorted(selected_indices)

# Memory store for reusing computed arguments to speed up inference
class MemoryStore:
    def __init__(self, enabled=True, prefix="", storage=None):
        self.storage = storage if storage is not None else {}
        self.enabled = enabled
        self.prefix = prefix

    def __call__(self, identifier: str, func: Callable):
        if self.enabled is False:
            return func()

        identifier = self.prefix + identifier

        try:
            value = self.storage[identifier]
        except KeyError:
            value = func()
            self.storage[identifier] = value

        return value

    def with_prefix(self, segment: str):
        return MemoryStore(
            enabled=self.enabled,
            prefix=self.prefix + segment + ".",
            storage=self.storage,
        )

    def fetch(self, identifier: str):
        identifier = self.prefix + identifier
        return self.storage[identifier]

