import threading
import asyncio

__all__ = ["get_async_loop", "run"]

# Create a background event loop thread
class BackgroundEventLoop:
    def __init__(self):
        self._loop = asyncio.new_event_loop()
        self._thread = threading.Thread(target=self._run_loop, daemon=True)
        self._thread.start()

    def _run_loop(self):
        asyncio.set_event_loop(self._loop)
        self._loop.run_forever()

    def execute(self, async_task):
        # Schedule an async task onto the loop and block until it completes
        return asyncio.run_coroutine_threadsafe(async_task, self._loop).result()

# Create one global instance
_global_loop = None

def get_async_loop():
    global _global_loop
    if _global_loop is None:
        _global_loop = BackgroundEventLoop()
    return _global_loop

def run(async_task):
    """Execute an asynchronous function in the background event loop."""
    return get_async_loop().execute(async_task)

