# Module for handling event hooks in the Requests library
# Available hook points:
# `response`: Triggered after a response is received from a Request
"""
HOOK_EVENTS = ["response"]

def initialize_hooks():
    return {event: [] for event in HOOK_EVENTS}

# TODO: response is currently the only supported hook
def trigger_hook(event_name, registered_hooks, data, **additional_kwargs):
    """Executes all registered hooks for a specific event."""
    registered_hooks = registered_hooks or {}
    hooks_to_execute = registered_hooks.get(event_name)

    if hooks_to_execute:
        # Ensure hooks is always iterable (wrap single callable in list)
        if callable(hooks_to_execute):
            hooks_to_execute = [hooks_to_execute]

        for hook_function in hooks_to_execute:
            updated_data = hook_function(data, **additional_kwargs)
            if updated_data is not None:
                data = updated_data

    return data

