def test_nccl_broadcast(free_port):
    host = "127.0.0.1"
    port = free_port()

    def sender():
        cuda_device = torch.device("cuda:0")
        sender_obj = NCCLWeightBroadcastSender(
            host=host, 
            port=port, 
            rank=0, 
            world_size=2, 
            device=cuda_device, 
            timeout=15
        )

        class InnerModule(torch.nn.Module):
            def __init__(self):
                super().__init__()
                self.blocks = torch.nn.ModuleList([torch.nn.Linear(8, 8) for _ in range(5)])

            def forward(self, x):
                for block in self.blocks:
                    x = block(x)
                return x

        class OuterModule(torch.nn.Module):
            def __init__(self):
                super().__init__()
                self.inner = InnerModule()

            def forward(self, x):
                return self.inner(x)

        model = OuterModule().to(cuda_device)
        for param in model.parameters():
            param.data.fill_(1.0)

        sender_obj.broadcast_weights(model, step=1)

    def receiver():
        cuda_device = torch.device("cuda:1")
        receiver_obj = NCCLWeightBroadcastReceiver(
            host=host, 
            port=port, 
            rank=1, 
            world_size=2, 
