# Modified version with renamed variables and reordered logic
def __init__(self, settings):
    self.settings = settings

def __call__(self, trace: list[tuple[int, float]], upper_bound: int):
    from pprint import pprint
    pprint(trace)
    return binary_search_terminator(trace, upper_bound)

def binary_search_terminator(trace: list[tuple[int, float]], upper_bound: int):
    """Stops when the search interval converges (range is 0 or 1)."""
    # Handle edge cases first
    if len(trace) == 1 and trace[0][0] == upper_bound and not trace[0][1]:
        return True

    if len(trace) < 2:
        return False

    last_position, is_broken = trace[-1]

    # Check termination conditions
    if last_position == 1 and is_broken:
        return True
    if last_position == upper_bound and not is_broken:
        return True

    # Convergence check based on position difference
    return abs(trace[-1][0] - trace[-2][0]) <= 1

