# Reorganized task scheduling system with priority-based optimization

class Assignment:
    def __init__(self, title, time_required, importance):
        self.title = title
        self.time_required = time_required  # in hours
        self.importance = importance  # higher value indicates higher importance

    def __str__(self):
        return f"Assignment(title={self.title}, time_required={self.time_required}, importance={self.importance})"

class Planner:
    def __init__(self, available_time):
        self.available_time = available_time  # dictionary of available hours per day
        self.plans = {day: [] for day in available_time}  # create empty daily plans

    def assign_task(self, assignment, day):
        if self.available_time[day] >= assignment.time_required:
            self.plans[day].append(assignment)
            self.available_time[day] -= assignment.time_required
            return True
        return False

    def arrange_tasks(self, assignments):
        # Sort assignments by importance (most important first)
        assignments.sort(key=lambda x: x.importance, reverse=True)

        for assignment in assignments:
            for day in self.available_time:
                if self.assign_task(assignment, day):
                    break

    def display_schedule(self):
        for day, assignments in self.plans.items():
            print(f"{day}:")
            for assignment in assignments:
                print(f"  - {assignment}")

# Convert numbers to words and generate LaTeX table

def convert_number_to_text(n, language):
    # Import required module locally
    from num2words import num2words

    # Validate input range
    if not (1 <= n <= 100):
        raise ValueError("Number must be between 1 and 100")

    # Handle different languages
    if language == 'en':
        words = num2words(n, lang='en')
    elif language == 'fr':
        words = num2words(n, lang='fr')
    else:
        raise ValueError("Unsupported language")

    # Clean up formatting: replace hyphens and commas with spaces
    return words.replace('-', ' ').replace(',', '')

def create_latex_content(values):
    # Verify all values are within acceptable range
    for val in values:
        if not (1 <= val <= 100):
            raise ValueError("All numbers must be between 1 and 100")

    # Start building LaTeX table structure
    latex_output = "\\begin{tabular}{|c|c|c|}\n"
    latex_output += "\\hline\n"
    latex_output += "Number & English & French \\\\\n"
    latex_output += "\\hline\n"

    # Process each number in the list
    for value in values:
        english_text = convert_number_to_text(value, 'en')
        french_text = convert_number_to_text(value, 'fr')
        latex_output += f"{value} & {english_text} & {french_text} \\\\\n"
        latex_output += "\\hline\n"

    latex_output += "\\end{tabular}\n"
    return latex_output

def process_command_line():
    import sys

    # Check command line arguments
    if len(sys.argv) < 2:
        print("Usage: python script.py <comma-separated-list-of-numbers>")
        sys.exit(1)

    try:
        # Parse comma-separated integers
        numbers = [int(x) for x in sys.argv[1].split(',')]
    except ValueError:
        print("All inputs must be valid integers.")
        sys.exit(1)

    # Limit maximum number of entries
    if len(numbers) > 1000:
        print("Maximum allowed entries is 1000.")
        sys.exit(1)

    try:
        # Generate and output LaTeX table
        result = create_latex_content(numbers)
        print(result)
    except ValueError as error:
        print(str(error))
        sys.exit(1)

