from typing import List

class DisjointSet:
    def __init__(self, size):
        self.root = [i for i in range(size)]
        self.height = [0] * size

    def find(self, node):
        if self.root[node] != node:
            self.root[node] = self.find(self.root[node])
        return self.root[node]

    def merge(self, a, b):
        rootA = self.find(a)
        rootB = self.find(b)

        if rootA == rootB:
            return False

        if self.height[rootA] > self.height[rootB]:
            self.root[rootB] = rootA
        elif self.height[rootA] < self.height[rootB]:
            self.root[rootA] = rootB
        else:
            self.root[rootB] = rootA
            self.height[rootA] += 1

        return True

def build_mst_weight(node_count, edge_list, skip_index=None, force_edge=None):
    dsu = DisjointSet(node_count)
    total_weight = 0

    # Force include an edge if specified
    if force_edge is not None:
        u, v, w = force_edge
        if dsu.merge(u, v):
            total_weight += w

    # Process remaining edges
    for idx, (u, v, w) in enumerate(edge_list):
        if skip_index is not None and idx == skip_index:
            continue
        if dsu.merge(u, v):
            total_weight += w

    # Check if all nodes are connected
    if all(dsu.find(i) == dsu.find(0) for i in range(node_count)):
        return total_weight
    else:
        return float('inf')

def identify_mst_edges(num_nodes: int, raw_edges: List[List[int]]) -> List[List[int]]:
    # Attach original indices to edges
    indexed_edges = [(u, v, weight, idx) for idx, (u, v, weight) in enumerate(raw_edges)]
    # Sort by weight
    indexed_edges.sort(key=lambda x: x[2])

    # Compute base MST weight
    base_edges = [(u, v, w) for u, v, w, _ in indexed_edges]
    optimal_weight = build_mst_weight(num_nodes, base_edges)

    critical = []
    pseudo_critical = []

    # Analyze each edge
    for idx, (u, v, w, original_idx) in enumerate(indexed_edges):
        # Test exclusion
        excluded_weight = build_mst_weight(num_nodes, base_edges, skip_index=idx)

        if excluded_weight > optimal_weight:
            critical.append(original_idx)
        else:
            # Test inclusion
            forced_weight = build_mst_weight(num_nodes, base_edges, force_edge=(u, v, w))

            if forced_weight == optimal_weight:
                pseudo_critical.append(original_idx)

    return [critical, pseudo_critical, optimal_weight]

