# Calculate the geometric mean of three distinct numbers

import sys

def compute_geometric_mean(x, y, z):
    # Validate inputs are non-zero and distinct
    if x == 0 or y == 0 or z == 0:
        print("Error: One or more inputs are zero, which is invalid for geometric mean calculation.")
        sys.exit(1)

    if len({x, y, z}) != 3:
        print("Error: All three numbers must be distinct.")
        sys.exit(1)

    # Compute using logarithmic approach to avoid potential overflow
    try:
        import math
        log_sum = math.log(abs(x)) + math.log(abs(y)) + math.log(abs(z))
        result = math.exp(log_sum / 3)

        # Preserve sign based on product of inputs
        if (x * y * z) < 0:
            return -result
        return result
    except Exception as e:
        print(f"Error: An unexpected error occurred: {e}")
        sys.exit(1)

def collect_inputs():
    try:
        # Prompt user for input values
        first_val = float(input("Enter the first number: "))
        second_val = float(input("Enter the second number: "))
        third_val = float(input("Enter the third number: "))

        return first_val, second_val, third_val
    except ValueError:
        print("Error: Invalid input. Please enter numerical values.")
        sys.exit(1)

def main():
    # Handle command line arguments or interactive input
    if len(sys.argv) == 4:
        try:
            args = [float(arg) for arg in sys.argv[1:]]
            first_val, second_val, third_val = args

            # Check distinctness
            if len(set(args)) != 3:
                print("Error: All three numbers must be distinct.")
                sys.exit(1)
        except ValueError:
            print("Error: Invalid input. Please provide three numerical values as command line arguments.")
            sys.exit(1)
    else:
        first_val, second_val, third_val = collect_inputs()

    # Compute and display result
    final_result = compute_geometric_mean(first_val, second_val, third_val)
    print(f"The geometric mean of {first_val}, {second_val}, and {third_val} is: {final_result}")

if __name__ == "__main__":
    main()

