def fetch_person_identifier(actor_name):
    """Retrieve the IMDb ID for a person using their full name."""
    try:
        search_results = imdb_api.search_for_person(actor_name)
        if search_results:
            return search_results[0].personID
        else:
            raise ValueError(f"Could not locate any individual named {actor_name}")
    except Exception as error:
        print(f"An issue arose during lookup: {error}")
        return None

def obtain_movie_credits(identifier):
    """Acquire the complete filmography for a given person identifier."""
    try:
        individual = imdb_api.get_person_data(identifier, queries=['filmography'])
        return individual.get('filmography', {})
    except Exception as error:
        print(f"An issue arose while fetching credits: {error}")
        return {}

def compute_mean_score(credits):
    """Determine the mean rating across all listed films."""
    cumulative_score = 0.0
    film_count = 0
    for section in credits:
        for entry in credits[section]:
            if 'rating' in entry and entry['rating'] is not None:
                cumulative_score += entry['rating']
                film_count += 1
    return cumulative_score / film_count if film_count > 0 else 0.0

def extract_supporting_cast(credits):
    """Gather all co-stars per film, excluding the primary subject."""
    ensemble_members = {}
    for section in credits:
        for entry in credits[section]:
            if 'cast' in entry:
                ensemble_members[entry['title']] = [
                    member['name'] for member in entry['cast'] 
                    if member['name'] != 'Daniel Day-Lewis'
                ]
    return ensemble_members

def tally_collaborators(credits):
    """Count how frequently the actor has partnered with each director."""
    collaboration_log = {}
    for section in credits:
        for entry in credits[section]:
            if 'director' in entry:
                for lead in entry['director']:
                    director_name = lead['name']
                    if director_name in collaboration_log:
                        collaboration_log[director_name] += 1
                    else:
                        collaboration_log[director_name] = 1
    return collaboration_log

# Orchestrated analysis function
def conduct_filmography_study(subject_name):
    identifier = fetch_person_identifier(subject_name)
    if identifier:
        credits = obtain_movie_credits(identifier)
        if credits:
            average_score = compute_mean_score(credits)
            supporting_actors = extract_supporting_cast(credits)
            directors_list = tally_collaborators(credits)
            return {
                'mean_rating': average_score,
                'supporting_cast': supporting_actors,
                'directors': directors_list
            }
    return None

