# Enhanced file content analyzer for keyword detection and encryption assessment

import os
import re
from collections import defaultdict

def compute_information_measure(text_data):
    """Estimate the randomness of input byte sequences."""
    if not text_data:
        return 0.0

    total_chars = len(text_data)
    char_frequencies = defaultdict(int)

    for char in text_data:
        char_frequencies[char] += 1

    entropy_value = 0.0
    for count in char_frequencies.values():
        probability = count / total_chars
        if probability > 0:
            entropy_value -= probability * (probability.bit_length() - 1)  # Approximation using bit_length

    return entropy_value

def detect_encryption_status(byte_sequence, limit=7.0):
    """Determine if data appears encrypted based on entropy threshold."""
    return compute_information_measure(byte_sequence) >= limit

def scan_directory(path, search_terms, buffer_size=1024*1024):
    """Traverse directory structure looking for specified terms while filtering encrypted files."""
    compiled_patterns = [re.compile(re.escape(term), re.IGNORECASE) for term in search_terms]
    found_items = []

    for current_dir, _, filenames in os.walk(path):
        for filename in filenames:
            full_path = os.path.join(current_dir, filename)
            try:
                with open(full_path, 'rb') as handler:
                    accumulated_content = b''
                    is_secure = False
                    term_occurrences = defaultdict(int)
                    line_index = 0

                    while True:
                        segment = handler.read(buffer_size)
                        if not segment:
                            break
                        accumulated_content += segment

                        # Skip processing if encryption detected
                        if not is_secure and detect_encryption_status(segment):
                            is_secure = True
                            break

                        # Process complete lines only
                        segments = accumulated_content.splitlines(True)
                        accumulated_content = segments[-1] if segments else b''

                        for segment_line in segments[:-1]:
                            line_index += 1
                            decoded_line = segment_line.decode('utf-8', errors='replace')

                            for pattern in compiled_patterns:
                                found_matches = pattern.findall(decoded_line)
                                if found_matches:
                                    term_occurrences[pattern.pattern] += len(found_matches)

                    if is_secure:
                        continue

                    # Compute relevance metric
                    relevance = sum(term_occurrences.values())
                    if relevance > 0:
                        found_items.append((full_path, relevance, dict(term_occurrences)))

            except (IOError, OSError) as error:
                print(f"Access issue with {full_path}: {error}")

    # Rank results by importance
    found_items.sort(key=lambda item: item[1], reverse=True)
    return found_items

def present_findings(findings):
    """Show organized output of search outcomes."""
    for path, metric, occurrences in findings:
        print(f"Location: {path}")
        print(f"Relevance: {metric}")
        print(f"Term Statistics: {occurrences}")
        print("-" * 60)

if __name__ == "__main__":
    target_directory = input("Specify directory to investigate: ").strip()
    query_terms = input("Enter search terms (space-separated): ").split()

    if not target_directory or not query_terms:
        print("Please provide both a directory and search terms.")
    else:
        search_results = scan_directory(target_directory, query_terms)
        present_findings(search_results)

# Modified Student Management System with equivalent functionality but different implementation logic

class Learner:
    def __init__(self, full_name, years, subject):
        # Validate age using different comparison approach
        if years < 18 or years > 99:
            raise ValueError("Age must be between 18 and 99.")

        # Validate name length using alternative condition check
        if not (len(full_name) <= 100):
            raise ValueError("Name cannot exceed 100 characters.")

        # Validate course length using inverted condition
        if len(subject) > 50:
            raise ValueError("Course name cannot exceed 50 characters.")

        self.full_name = full_name
        self.years = years
        self.subject = subject

    def __repr__(self):
        return f"Learner(Name={self.full_name}, Age={self.years}, Subject={self.subject})"


class AcademicRegistry:
    def __init__(self):
        self.learners = []
        self.name_catalog = {}

    def enroll(self, full_name, years, subject):
        learner = Learner(full_name, years, subject)
        self.learners.append(learner)

        # Use get() method for dictionary access instead of direct key check
        existing_group = self.name_catalog.get(full_name, [])
        existing_group.append(learner)
        self.name_catalog[full_name] = existing_group

    def expel(self, full_name):
        if full_name in self.name_catalog:
            # Remove first occurrence using pop(0)
            learner_to_remove = self.name_catalog[full_name].pop(0)

            # Find and remove from main list using index search
            for i, learner in enumerate(self.learners):
                if learner is learner_to_remove:
                    self.learners.pop(i)
                    break

            # Clean up empty catalog entries
            if not self.name_catalog[full_name]:
                del self.name_catalog[full_name]

    def lookup(self, full_name):
        # Return copy of list to avoid external modification
        return list(self.name_catalog.get(full_name, []))

    def modify(self, full_name, years=None, subject=None):
        if full_name in self.name_catalog:
            learner_to_modify = self.name_catalog[full_name][0]

            # Update age with different validation structure
            if years is not None:
                try:
                    assert 18 <= years <= 99
                    learner_to_modify.years = years
                except AssertionError:
                    raise ValueError("Age must be between 18 and 99.")

            # Update subject with alternative length check
            if subject is not None:
                if len(subject) > 50:
                    raise ValueError("Course name cannot exceed 50 characters.")
                learner_to_modify.subject = subject

    def list_sorted(self):
        # Use reverse=False explicitly and different sorting key
        sorted_learners = sorted(self.learners, key=lambda x: x.full_name, reverse=False)
        return sorted_learners


