import requests

def fetch_internal_txs(wallet_address, api_token):
    endpoint = f"https://api.bscscan.com/api?module=account&action=txlistinternal&address={wallet_address}&apikey={api_token}"

    try:
        response = requests.get(endpoint)
        result = response.json()

        if result.get("status") != "1":
            return []

        tx_list = []

        for item in result.get("result", []):
            if item.get("type") == "create":
                tx_list.append({
                    "transaction_hash": item["hash"],
                    "contract_address": item["to"],
                    "amount_wei": int(item["value"]),
                    "calldata": item["input"]
                })

        return tx_list

