# Tic-Tac-Toe Game Implementation

def display_grid(grid):
    print("+---+---+---+")
    for line in grid:
        print("|", end="")
        for item in line:
            print(f" {item} |", end="")
        print("\n+---+---+---+")

def has_won(grid, symbol):
    # Check all rows
    for r in range(3):
        if grid[r][0] == symbol and grid[r][1] == symbol and grid[r][2] == symbol:
            return True

    # Check all columns
    for c in range(3):
        if grid[0][c] == symbol and grid[1][c] == symbol and grid[2][c] == symbol:
            return True

    # Check diagonals
    if grid[0][0] == symbol and grid[1][1] == symbol and grid[2][2] == symbol:
        return True
    if grid[0][2] == symbol and grid[1][1] == symbol and grid[2][0] == symbol:
        return True

    return False

def is_filled(grid):
    for row in grid:
        for cell in row:
            if cell == " ":
                return False
    return True

def main():
    game_board = [[" " for _ in range(3)] for _ in range(3)]
    turn = "X"

    while True:
        display_grid(game_board)

        try:
            position = int(input(f"Player {turn}, enter your move (1-9): "))

            if not (1 <= position <= 9):
                raise ValueError("Invalid input. Please select a number from 1 to 9.")

            row_index = (position - 1) // 3
            col_index = (position - 1) % 3

            if game_board[row_index][col_index] != " ":
                raise ValueError("That spot is already taken. Try another location.")

            game_board[row_index][col_index] = turn

            if has_won(game_board, turn):
                display_grid(game_board)
                print(f"Congratulations! Player {turn} has won the game!")
                break

            if is_filled(game_board):
                display_grid(game_board)
                print("The game ends in a draw!")
                break

            turn = "O" if turn == "X" else "X"

        except ValueError as error:
            print(f"Error: {error}")

if __name__ == "__main__":
    main()

