# Calculate the sum of two fractions and analyze their denominators' prime factorizations

def compute_gcd(x, y):
    while y != 0:
        x, y = y, x % y
    return x

def compute_lcm(x, y):
    return (x * y) // compute_gcd(x, y)

def reduce_fraction(num, den):
    divisor = compute_gcd(num, den)
    return (num // divisor, den // divisor)

def convert_mixed_to_improper(mixed_form):
    if isinstance(mixed_form, tuple) and len(mixed_form) == 3:
        whole_part, top, bottom = mixed_form
        return (whole_part * bottom + top, bottom)
    return mixed_form

def add_two_fractions(fraction_a, fraction_b):
    fraction_a = convert_mixed_to_improper(fraction_a)
    fraction_b = convert_mixed_to_improper(fraction_b)

    num1, den1 = fraction_a
    num2, den2 = fraction_b

    lcm_denominator = compute_lcm(den1, den2)

    adjusted_num1 = num1 * (lcm_denominator // den1)
    adjusted_num2 = num2 * (lcm_denominator // den2)

    final_numerator = adjusted_num1 + adjusted_num2
    final_denominator = lcm_denominator

    return reduce_fraction(final_numerator, final_denominator)

def get_prime_decomposition(number):
    primes = []
    test_divisor = 2
    temp_number = number
    while temp_number > 1:
        while temp_number % test_divisor == 0:
            primes.append(test_divisor)
            temp_number //= test_divisor
        test_divisor += 1
    return primes

def analyze_denominators(frac_a, frac_b):
    frac_a = convert_mixed_to_improper(frac_a)
    frac_b = convert_mixed_to_improper(frac_b)

    d1 = frac_a[1]
    d2 = frac_b[1]

    decomposition1 = get_prime_decomposition(d1)
    decomposition2 = get_prime_decomposition(d2)

    # Count occurrences of each prime factor
    counts1 = {}
    counts2 = {}

    for p in decomposition1:
        counts1[p] = counts1.get(p, 0) + 1
    for p in decomposition2:
        counts2[p] = counts2.get(p, 0) + 1

    # Find common and unique factors
    shared = {}
    for prime in counts1:
        if prime in counts2:
            shared[prime] = min(counts1[prime], counts2[prime])

    unique1 = {}
    for prime in counts1:
        if prime not in counts2:
            unique1[prime] = counts1[prime]
        elif counts1[prime] > shared.get(prime, 0):
            unique1[prime] = counts1[prime] - shared[prime]

    unique2 = {}
    for prime in counts2:
        if prime not in counts1:
            unique2[prime] = counts2[prime]
        elif counts2[prime] > shared.get(prime, 0):
            unique2[prime] = counts2[prime] - shared[prime]

    print(f"Prime decomposition of {d1}: {decomposition1}")
    print(f"Prime decomposition of {d2}: {decomposition2}")
    print("Shared prime factors:", [k for k, v in shared.items() for _ in range(v)])
    print("Unique to first denominator:", [k for k, v in unique1.items() for _ in range(v)])
    print("Unique to second denominator:", [k for k, v in unique2.items() for _ in range(v)])

