class Smartphone:
    def __init__(self, manufacturer,型号, operating_system, max_battery, display_size):
        self.manufacturer = manufacturer
        self.型号 = 型号
        self.operating_system = operating_system
        self.max_battery = max_battery
        self.display_size = display_size
        self.current_charge = max_battery  # Start with full charge
        self.is_on = False

    def turn_on(self):
        if not self.is_on:
            self.is_on = True
            print(f"{self.manufacturer} {self.型号} has been turned on.")
        else:
            print(f"{self.manufacturer} {self.型号} is already running.")

    def turn_off(self):
        if self.is_on:
            self.is_on = False
            print(f"{self.manufacturer} {self.型号} has been shut down.")
        else:
            print(f"{self.manufacturer} {self.型号} is already off.")

    def consume_power(self, drain_amount):
        if self.is_on:
            if self.current_charge >= drain_amount:
                self.current_charge -= drain_amount
                print(f"Remaining battery: {self.current_charge} mAh")
            else:
                print("Insufficient battery for this operation.")
        else:
            print("Device is powered down. Please switch it on first.")

    def recharge(self, charge_amount):
        if self.current_charge + charge_amount <= self.max_battery:
            self.current_charge += charge_amount
            print(f"Current battery level: {self.current_charge} mAh")
        else:
            self.current_charge = self.max_battery
            print("Battery is now fully charged.")

# Alternative implementation for statistical calculations

def get_max_value(values):
    if len(values) == 0:
        return "Error: The list is empty."
    max_val = values[0]
    idx = 1
    while idx < len(values):
        if values[idx] > max_val:
            max_val = values[idx]
        idx += 1
    return max_val

def get_min_value(values):
    if len(values) == 0:
        return "Error: The list is empty."
    min_val = values[0]
    idx = 1
    while idx < len(values):
        if values[idx] < min_val:
            min_val = values[idx]
        idx += 1
    return min_val

def compute_mean(values):
    if len(values) == 0:
        return "Error: The list is empty."
    accumulator = 0
    for val in values:
        accumulator += val
    return accumulator / len(values)

def determine_middle_value(values):
    if len(values) == 0:
        return "Error: The list is empty."
    ordered = sorted(values)
    length = len(ordered)
    mid_index = length // 2
    if length % 2 == 1:
        return ordered[mid_index]
    else:
        return (ordered[mid_index - 1] + ordered[mid_index]) / 2.0

def identify_frequent_value(values):
    if len(values) == 0:
        return "Error: The list is empty."
    frequency_map = {}
    for item in values:
        if item in frequency_map:
            frequency_map[item] += 1
        else:
            frequency_map[item] = 1

    highest_frequency = max(frequency_map.values())
    candidates = [key for key, freq in frequency_map.items() if freq == highest_frequency]

    return candidates[0] if len(candidates) == 1 else candidates

