import re

def locate_consecutive_repetition_and_unique_char(text):
    # Initialize variables to store results
    repeated_token = None
    repeated_token_index = None
    unique_char = None
    unique_char_index = None

    # Extract words using regex (alphanumeric sequences)
    tokens = re.findall(r'\b\w+\b', text)

    # Look for a word that repeats at least 4 times consecutively
    for idx in range(len(tokens) - 3):
        if (tokens[idx] == tokens[idx + 1] == 
            tokens[idx + 2] == tokens[idx + 3]):
            repeated_token = tokens[idx]
            repeated_token_index = idx
            break

    # Track positions of each alphabetic character
    char_occurrences = {}
    for index, symbol in enumerate(text):
        if symbol.isalpha():
            if symbol not in char_occurrences:
                char_occurrences[symbol] = []
            char_occurrences[symbol].append(index)

    # Identify the first character appearing exactly once
    for char, indices in char_occurrences.items():
        if len(indices) == 1:
            unique_char = char
            unique_char_index = indices[0]
            break

    return (repeated_token, repeated_token_index, 
            unique_char, unique_char_index)

# Demonstration usage
sample_text = "This is a test test test test to see if the script works. Unique letter z."
repeated_token, repeated_token_index, unique_char, unique_char_index = locate_consecutive_repetition_and_unique_char(sample_text)

if repeated_token:
    print(f"Repeated token: '{repeated_token}' at position {repeated_token_index}")
else:
    print("No token repeated four or more times consecutively.")

if unique_char:
    print(f"Unique character: '{unique_char}' at position {unique_char_index}")
else:
    print("No unique character found.")

# Date reminder system with custom and pre-defined messages

from datetime import datetime
import calendar

class InvalidDateError(Exception):
    """Raised when the provided date is not valid."""
    pass

class MissingReminderError(Exception):
    """Raised when no reminder exists for a specific date."""
    pass

# Fixed reminders for months
MONTHLY_MESSAGES = {
    "January": "New Year's resolutions!",
    "February": "Valentine's Day is coming up!",
    "March": "Spring is here!",
    "April": "Easter is around the corner!",
    "May": "Mother's Day is coming up!",
    "June": "Summer is here!",
    "July": "Independence Day in the USA!",
    "August": "Back to school!",
    "September": "Fall is coming!",
    "October": "Halloween is coming up!",
    "November": "Thanksgiving is around the corner!",
    "December": "Christmas is coming up!"
}

# User-defined reminders stored as (day, month_name) -> message
USER_REMINDERS = {}

def check_leap(year):
    """Determine whether a year is a leap year."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def verify_date(date_input):
    """Parse and validate the date string."""
    try:
        parsed_date = datetime.strptime(date_input, "%d %B")
        current_year = datetime.now().year

        # Validate February days
        if parsed_date.month == 2 and parsed_date.day > 29:
            raise InvalidDateError("February cannot have more than 29 days.")
        if parsed_date.month == 2 and parsed_date.day == 29 and not check_leap(current_year):
            raise InvalidDateError("February has only 28 days this year (not a leap year).")

        # Validate day against actual month length
        max_day = calendar.monthrange(current_year, parsed_date.month)[1]
        if parsed_date.day > max_day:
            raise InvalidDateError(f"{parsed_date.strftime('%B')} only has {max_day} days.")

        return parsed_date
    except ValueError:
        raise InvalidDateError("Incorrect format. Use 'DD Month' (e.g., '05 March').")

def fetch_reminder(parsed_date):
    """Retrieve the appropriate reminder for the given date."""
    month_name = parsed_date.strftime("%B")

    # Check pre-defined reminders first
    if month_name in MONTHLY_MESSAGES:
        return MONTHLY_MESSAGES[month_name]

    # Then check user-defined reminders
    key = (parsed_date.day, month_name)
    if key in USER_REMINDERS:
        return USER_REMINDERS[key]

    raise MissingReminderError(f"No reminder set for {parsed_date.strftime('%d %B')}.")

def set_user_reminder(parsed_date, message):
    """Store a new user-defined reminder."""
    key = (parsed_date.day, parsed_date.strftime("%B"))
    USER_REMINDERS[key] = message

def run_app():
    while True:
        date_input = input("Enter the date (DD Month) or 'quit' to exit: ")
        if date_input.lower() == 'quit':
            break

        try:
            validated_date = verify_date(date_input)
            try:
                reminder_text = fetch_reminder(validated_date)
                print(f"Reminder for {date_input}: {reminder_text}")
            except MissingReminderError as err:
                print(err)
                add_choice = input("Would you like to create a custom reminder? (yes/no): ")
                if add_choice.lower() == 'yes':
                    user_message = input("Type your custom reminder: ")
                    set_user_reminder(validated_date, user_message)
                    print(f"Custom reminder saved for {date_input}: {user_message}")
        except InvalidDateError as error:
            print(error)

if __name__ == "__main__":
    run_app()

import os
import pickle
from typing import List, Tuple
from collections import defaultdict
from datetime import datetime, timedelta

# Storage configuration
DATA_FILE = 'fibfib_cached_data.pkl'
CACHE_DURATION = timedelta(hours=24)

def retrieve_cache():
    if os.path.isfile(DATA_FILE):
        try:
            with open(DATA_FILE, 'rb') as file:
                return pickle.load(file)
        except (pickle.PickleError, EOFError):
            return defaultdict(dict)
    return defaultdict(dict)

def store_cache(cache):
    with open(DATA_FILE, 'wb') as file:
        pickle.dump(cache, file)

def compute_fibfib(n: int, base: int) -> int:
    if n < 0 or base < 0:
        raise ValueError("Arguments must be non-negative integers")

    cache = retrieve_cache()
    key = (n, base)

    # Check if valid cached result exists
    if key in cache:
        stored_value, stored_time = cache[key]
        if datetime.now() - stored_time < CACHE_DURATION:
            return stored_value

    # Compute value recursively
    if n == 0:
        computed = 0
    elif n == 1:
        computed = 1
    else:
        computed = compute_fibfib(n - 1, base) + compute_fibfib(n - 2, base)

    # Update cache with new result
    cache[key] = (computed, datetime.now())
    store_cache(cache)
    return computed

def process_multiple_fibfib(requests: List[Tuple[int, int]]) -> List[int]:
    if not all(isinstance(q, tuple) and len(q) == 2 and 
               isinstance(q[0], int) and isinstance(q[1], int) and 
               q[0] >= 0 and q[1] >= 0 for q in requests):
        raise ValueError("Each request must be a tuple of two non-negative integers")

    cache = retrieve_cache()
    outputs = []

    for first, second in requests:
        lookup_key = (first, second)

        # Use cached value if available and fresh
        if lookup_key in cache:
            cached_val, cached_time = cache[lookup_key]
            if datetime.now() - cached_time < CACHE_DURATION:
                outputs.append(cached_val)
                continue

        # Calculate new value
        new_val = compute_fibfib(first, second)
        outputs.append(new_val)

    return outputs

def refresh_cache():
    cache = retrieve_cache()
    now = datetime.now()
    expired_keys = []

    for entry_key, (entry_val, entry_time) in cache.items():
        if now - entry_time > CACHE_DURATION:
            expired_keys.append(entry_key)

    for expired_key in expired_keys:
        del cache[expired_key]

    store_cache(cache)

# Demonstration section
if __name__ == "__main__":
    # Single computation example
    print(compute_fibfib(5, 0))  # Expected output: 5

    # Batch processing example
    task_list = [(5, 0), (6, 0), (7, 0)]
    batch_results = process_multiple_fibfib(task_list)
    print(batch_results)  # Expected output: [5, 8, 13]

    # Clear outdated entries
    refresh_cache()

