from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from pydantic import BaseModel
from passlib.context import CryptContext
from jose import jwt, JWTError
import datetime

# User data storage (restructured for clarity)
users_db = {
    "David": {"hash": "$2b$12$...", "role": "admin"},
    "Sara": {"hash": "$2b$12$...", "role": "user"}
}

# Initialize app
app = FastAPI(title="User Management API")

# Security components
security_scheme = OAuth2PasswordBearer(tokenUrl="auth/token")
pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")

# JWT configuration
JWT_SECRET = "your_secret_key"
JWT_ALGO = "HS256"
TOKEN_EXPIRY_MINUTES = 30

# Data models
class TokenPayload(BaseModel):
    user_id: str
    access_level: str

class LoginCredentials(BaseModel):
    name: str
    secret: str

class RegisteredUser(BaseModel):
    name: str
    secret: str
    access_level: str

# Utility functions
def check_credentials(plain_text, stored_hash):
    return pwd_context.verify(plain_text, stored_hash)

def hash_secret(secret):
    return pwd_context.hash(secret)

def find_user(username):
    if username in users_db:
        return RegisteredUser(
            name=username,
            secret=users_db[username]["hash"],
            access_level=users_db[username]["role"]
        )
    return None

def validate_login(name, password):
    user = find_user(name)
    if not user or not check_credentials(password, user.secret):
        return None
    return user

def generate_token(payload_data, duration):
    payload = payload_data.copy()
    expiry = datetime.datetime.utcnow() + datetime.timedelta(minutes=duration)
    payload["exp"] = expiry
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGO)

# Dependency chain for authentication
async def verify_auth(token: str = Depends(security_scheme)):
    unauthorized = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Authentication failed",
        headers={"WWW-Authenticate": "Bearer"}
    )
    try:
        decoded = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGO])
        user_name = decoded.get("uid")
        role = decoded.get("lvl")
        if not user_name or not role:
            raise unauthorized
        return TokenPayload(user_id=user_name, access_level=role)
    except JWTError:
        raise unauthorized

async def require_active_user(authenticated: TokenPayload = Depends(verify_auth)):
    return authenticated

# Authentication endpoint
@app.post("/auth/token")
async def obtain_access_token(credentials: LoginCredentials):
    user = validate_login(credentials.name, credentials.secret)
    if not user:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid login credentials",
            headers={"WWW-Authenticate": "Bearer"}
        )

    token_duration = datetime.timedelta(minutes=TOKEN_EXPIRY_MINUTES)
    token_payload = {"uid": user.name, "lvl": user.access_level}
    token = generate_token(token_payload, token_duration)

    return {"token": token, "type": "Bearer"}

# Protected endpoints
@app.get("/profile")
async def view_profile(user: TokenPayload = Depends(require_active_user)):
    return {"name": user.user_id, "role": user.access_level}

@app.get("/directory")
async def list_all_users(user: TokenPayload = Depends(require_active_user)):
    if user.access_level != "admin":
        raise HTTPException(status_code=403, detail="Access denied")
    return {name: {"role": info["role"]} for name, info in users_db.items()}

@app.post("/directory")
async def register_new_user(new_user: RegisteredUser, user: TokenPayload = Depends(require_active_user)):
    if user.access_level != "admin":
        raise HTTPException(status_code=403, detail="Permission denied")
    if new_user.name in users_db:
        raise HTTPException(status_code=409, detail="Username already taken")

    users_db[new_user.name] = {
        "hash": hash_secret(new_user.secret),
        "role": new_user.access_level
    }
    return {"status": "User created"}

@app.put("/directory/{username}")
async def modify_user(username: str, updated: RegisteredUser, user: TokenPayload = Depends(require_active_user)):
    if user.access_level != "admin":
        raise HTTPException(status_code=403, detail="Unauthorized action")
    if username not in users_db:
        raise HTTPException(status_code=404, detail="User not found")

    users_db[username] = {
        "hash": hash_secret(updated.secret),
        "role": updated.access_level
    }
    return {"status": "User updated"}

@app.delete("/directory/{username}")
async def remove_user(username: str, user: TokenPayload = Depends(require_active_user)):
    if user.access_level != "admin":
        raise HTTPException(status_code=403, detail="Forbidden operation")
    if username not in users_db:
        raise HTTPException(status_code=404, detail="User not found")

    del users_db[username]
    return {"status": "User removed"}

