# Calculate combined results using thread-safe operations

from threading import Thread, Lock
from concurrent.futures import ThreadPoolExecutor

# Initialize global variables
a, b, c = 100, 0, 50
b_lock = Lock()

def compute_condition_one(idx, b_val, c_val):
    if idx > c_val:
        result = idx + 20
    else:
        result = idx * idx + c_val
    return result

def compute_condition_two(a_val, b_val, c_val):
    if a_val == c_val:
        result = a_val - 20
    else:
        result = c_val << 1  # equivalent to c_val * 2
    return result

def execute_thread_safe_one(idx, b_val, c_val):
    with b_lock:
        updated_b = compute_condition_one(idx, b_val, c_val)
        print(f"Worker {idx}: b = {updated_b}")

def execute_thread_safe_two(a_val, b_val, c_val):
    with b_lock:
        updated_b = compute_condition_two(a_val, b_val, c_val)
        print(f"Worker {a_val // 10}: b = {updated_b}")

def run_main_logic():
    global b
    if a > c:
        with ThreadPoolExecutor(max_workers=8) as pool:
            for index in range(a):
                pool.submit(execute_thread_safe_one, index, b, c)
    else:
        with ThreadPoolExecutor(max_workers=8) as pool:
            temp_a = a
            while temp_a >= 0:
                pool.submit(execute_thread_safe_two, temp_a, b, c)
                temp_a -= 10

if __name__ == "__main__":
    run_main_logic()

# ISBN Checker - Alternative Implementation

def check_isbn_format(isbn_str):
    # Clean the input: remove hyphens and whitespace
    cleaned = isbn_str.strip().replace('-', '')
    return cleaned, len(cleaned)

def verify_isbn_10(digits_str):
    # Check for invalid characters
    if not digits_str[:-1].isdigit() or not (digits_str[-1].isdigit() or digits_str[-1] == 'X'):
        return False, "Invalid characters: ISBN-10 must contain digits and an 'X' as the last character if applicable"

    # Convert characters to numeric values
    values = []
    for idx, char in enumerate(digits_str):
        if char == 'X':
            values.append(10)
        else:
            values.append(int(char))

    # Apply weights from 10 down to 1
    total = 0
    for i in range(len(values)):
        weight = 10 - i
        total += values[i] * weight

    # Validate checksum
    if total % 11 != 0:
        return False, "Invalid checksum: ISBN-10 checksum is incorrect"

    return True, None

def verify_isbn_13(digits_str):
    # Ensure all characters are digits
    if not digits_str.isdigit():
        return False, "Invalid characters: ISBN-13 must contain only digits"

    # Convert to list of integers
    numbers = [int(d) for d in digits_str]

    # Apply alternating weights: 1, 3, 1, 3...
    weighted_sum = 0
    for pos, num in enumerate(numbers):
        if pos % 2 == 0:
            weighted_sum += num * 1
        else:
            weighted_sum += num * 3

    # Validate checksum
    if weighted_sum % 10 != 0:
        return False, "Invalid checksum: ISBN-13 checksum is incorrect"

    return True, None

class ISBNValidator:
    def __init__(self, isbn_input):
        self.original = isbn_input
        self.processed, self.size = check_isbn_format(isbn_input)
        self.validity = False
        self.problem = None

    def run_check(self):
        if self.size == 10:
            self.validity, self.problem = verify_isbn_10(self.processed)
        elif self.size == 13:
            self.validity, self.problem = verify_isbn_13(self.processed)
        else:
            self.problem = f"Invalid length: ISBN must be 10 or 13 characters, not {self.size}"
        return self.validity

    def get_issue(self):
        return self.problem


# Test cases
if __name__ == "__main__":
    test_cases = [
        "0-306-40615-2",  # Valid ISBN-10
        "978-0-306-40615-7",  # Valid ISBN-13
        "0-306-40615-3",  # Invalid ISBN-10
        "978-0-306-40615-8",  # Invalid ISBN-13
        "12345678901234",  # Invalid length
        "0-306-4061X-2"  # Invalid characters
    ]

    for code in test_cases:
        checker = ISBNValidator(code)
        if checker.run_check():
            print(f"{code} is a valid ISBN")
        else:
            print(f"{code} is an invalid ISBN: {checker.get_issue()}")

# Implementation of a thread- and process-safe singleton pattern using metaclass

import threading
import multiprocessing
from functools import wraps

class ThreadSafeSingleton(type):
    _instances = {}
    _thread_lock = threading.Lock()
    _process_lock = multiprocessing.Lock()

    def __call__(cls, *args, **kwargs):
        # First check if instance already exists (fast path)
        if cls in cls._instances:
            return cls._instances[cls]

        # Thread-safe creation
        with cls._thread_lock:
            # Double-check after acquiring lock
            if cls not in cls._instances:
                # Create instance only if still not present
                cls._instances[cls] = super().__call__(*args, **kwargs)

        # Process-safe creation (for multiprocessing scenarios)
        with cls._process_lock:
            # Recheck in case of race condition across processes
            if cls not in cls._instances:
                cls._instances[cls] = super().__call__(*args, **kwargs)

        return cls._instances[cls]

class Singleton(metaclass=ThreadSafeSingleton):
    def __init__(self, data=None):
        self.data = data

    def display(self):
        print(f"Singleton instance with data: {self.data}")

# Demonstration code
if __name__ == "__main__":
    # Test thread safety
    def worker_thread():
        instance = Singleton(data="Thread")
        instance.display()

    threads_list = []
    for _ in range(5):
        t = threading.Thread(target=worker_thread)
        t.start()
        threads_list.append(t)

    for t in threads_list:
        t.join()

    # Test process safety
    def worker_process():
        instance = Singleton(data="Process")
        instance.display()

    processes_list = []
    for _ in range(5):
        p = multiprocessing.Process(target=worker_process)
        p.start()
        processes_list.append(p)

    for p in processes_list:
        p.join()

import re
import random
import string
import logging

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

class URLHandler:
    def __init__(self, scheme, prefix, main_domain, tld_suffix, path_segment):
        self.scheme = scheme
        self.prefix = prefix
        self.main_domain = main_domain
        self.tld_suffix = tld_suffix
        self.path_segment = path_segment

    def build_url(self):
        if not self.check_integrity():
            return None
        return f"{self.scheme}://{self.prefix}.{self.main_domain}{self.tld_suffix}/{self.transform_path()}"

    def parse_url(self, url_string):
        regex_pattern = r'^(?P<scheme>[a-zA-Z]+)://(?P<prefix>[a-zA-Z0-9-]+)\.(?P<main_domain>[a-zA-Z0-9-]+)(?P<tld_suffix>\.[a-zA-Z]{2,6})/(?P<path_segment>.+)$'
        result = re.match(regex_pattern, url_string)
        if result:
            return result.groupdict()
        else:
            logging.error(f"Malformed URL detected: {url_string}")
            return None

    def check_integrity(self):
        # Verify all components are present
        if not all([self.scheme, self.prefix, self.main_domain, self.tld_suffix, self.path_segment]):
            logging.error("Missing required URL components.")
            return False

        # Validate protocol/scheme
        valid_schemes = ['http', 'https', 'ftp', 'sftp']
        if self.scheme.lower() not in valid_schemes:
            logging.error(f"Unsupported scheme: {self.scheme}")
            return False

        # Validate subdomain/prefix
        if not re.match(r'^[a-zA-Z0-9-]+$', self.prefix):
            logging.error(f"Invalid prefix: {self.prefix}")
            return False

        # Validate main domain
        if not re.match(r'^[a-zA-Z0-9-]+$', self.main_domain):
            logging.error(f"Invalid main domain: {self.main_domain}")
            return False

        # Validate TLD suffix
        if not re.match(r'^\.[a-zA-Z]{2,6}$', self.tld_suffix):
            logging.error(f"Invalid TLD suffix: {self.tld_suffix}")
            return False

        return True

    def transform_path(self, use_random_encoding=False):
        if use_random_encoding:
            return self.apply_random_encoding()
        else:
            return self.apply_standard_encoding()

    def apply_standard_encoding(self):
        def replace_special(match):
            char = match.group(0)
            return f"%{ord(char):02X}"
        return re.sub(r'[^a-zA-Z0-9/]', replace_special, self.path_segment)

    def apply_random_encoding(self):
        encoded_result = ""
        for character in self.path_segment:
            if re.match(r'[^a-zA-Z0-9/]', character):
                # Randomly decide whether to encode or leave as-is
                if random.random() > 0.5:
                    encoded_result += f"%{ord(character):02X}"
                else:
                    encoded_result += character
            else:
                encoded_result += character
        return encoded_result

# Filter and sort students based on criteria

def process_student_records(student_dict, height_threshold, weight_threshold, age_threshold, gpa_threshold):
    def validate_entry(record):
        if not isinstance(record, tuple) or len(record) != 4:
            return False
        for value in record:
            if not isinstance(value, (int, float)):
                return False
        return True

    def transform_to_floats(record):
        try:
            return tuple(map(float, record))
        except (TypeError, ValueError):
            raise TypeError(f"Non-numeric data found in student record: {record}")

    qualified_students = []
    for student_name, student_info in student_dict.items():
        if not validate_entry(student_info):
            raise ValueError(f"Malformed student entry for {student_name}: {student_info}")
