# Determine if at least one string can be rearranged to form a palindrome

def has_palindromic_permutation(text):
    # Count character frequencies
    freq = {}
    for char in text:
        freq[char] = freq.get(char, 0) + 1

    # Count how many characters have odd frequency
    odd_frequency_chars = 0
    for count in freq.values():
        if count % 2 == 1:
            odd_frequency_chars += 1

    # A string can form a palindrome if at most one character has odd count
    return odd_frequency_chars <= 1

def evaluate_string_pairs(first_str, second_str):
    # Check first string for palindromic possibility
    if has_palindromic_permutation(first_str):
        return 1
    # Check second string if first fails
    elif has_palindromic_permutation(second_str):
        return -1
    # Neither can form a palindrome
    else:
        return 0

