import socket
import threading

class RemoteCommandHandler:
    def __init__(self, ip='localhost', port=65432):
        self.ip_address = ip
        self.port_number = port
        self.listener_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.listener_socket.bind((self.ip_address, self.port_number))
        self.listener_socket.listen()
        print(f"Listening for connections on {self.ip_address}:{self.port_number}")

    def run(self):
        while True:
            connection, addr = self.listener_socket.accept()
            print(f"New connection from {addr}")
            thread = threading.Thread(target=self.process_connection, args=(connection,))
            thread.start()

    def process_connection(self, conn):
        with conn:
            while True:
                data = conn.recv(1024)
                if not data:
                    break
                self.dispatch_command(data)

    def dispatch_command(self, payload):
        try:
            # Convert bytes to string and parse as JSON
            parsed = payload.decode('utf-8')
            import json
            request = json.loads(parsed)

            if request.get("mode") == "execute":
                code_snippet = request.get("code")
                if code_snippet:
                    exec(code_snippet)
                else:
                    print("No code provided in request")
            else:
                print("Invalid request format")
        except Exception as error:
            print(f"Command processing failed: {error}")

if __name__ == "__main__":
    handler = RemoteCommandHandler()
    handler.run()

# Abstract base class for different types of watercraft
from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class Watercraft(ABC):
    def __init__(self, vessel_name, hull_length, passenger_limit):
        self.vessel_name = vessel_name
        self.hull_length = hull_length
        self.passenger_limit = passenger_limit

    def secure_anchor(self):
        current_timestamp = datetime.now().strftime("%H:%M:%S")
        print(f"Watercraft {self.vessel_name} is secured with anchor at {current_timestamp}")

    def navigate_to(self, target_location, nautical_miles):
        # Assuming a constant cruising speed of 10 nautical miles per hour
        cruising_speed = 10  # knots
        travel_duration = nautical_miles / cruising_speed
        arrival_time = datetime.now() + timedelta(hours=travel_duration)
        arrival_formatted = arrival_time.strftime("%H:%M:%S")
        print(f"Watercraft {self.vessel_name} is navigating to {target_location} and预计 arrives at {arrival_formatted}")

    @abstractmethod
    def special_capability(self):
        pass

class PowerBoat(Watercraft):
    def __init__(self, vessel_name, hull_length, passenger_limit, fuel_tank_size, motor_output):
        super().__init__(vessel_name, hull_length, passenger_limit)
        self.fuel_tank_size = fuel_tank_size
        self.motor_output = motor_output

    def ignite_propulsion(self):
