# Create a 3x3 Tic-Tac-Toe game board

def setup_grid():
    return [[0 for _ in range(3)] for _ in range(3)]

def display_grid(grid):
    for line in grid:
        print(" ".join(["X" if cell == 1 else "O" if cell == 2 else "." for cell in line]))

def is_legal_move(grid, r, c):
    return grid[r][c] == 0

def apply_move(grid, r, c, player):
    if is_legal_move(grid, r, c):
        grid[r][c] = player
        return True
    return False

def has_won(grid, player):
    # Check rows, columns, and diagonals
    for i in range(3):
        if all(grid[i][j] == player for j in range(3)) or all(grid[j][i] == player for j in range(3)):
            return True
    if all(grid[i][i] == player for i in range(3)) or all(grid[i][2-i] == player for i in range(3)):
        return True
    return False

def grid_complete(grid):
    return all(cell != 0 for row in grid for cell in row)

def run_game():
    grid = setup_grid()
    turn = 1

    while True:
        display_grid(grid)
        r = int(input(f"Player {turn}, enter row (0-2): "))
        c = int(input(f"Player {turn}, enter column (0-2): "))

        if apply_move(grid, r, c, turn):
            if has_won(grid, turn):
                display_grid(grid)
                print(f"Player {turn} wins!")
                break
            elif grid_complete(grid):
                display_grid(grid)
                print("It's a draw!")
                break
            turn = 3 - turn  # Switch player (1 -> 2, 2 -> 1)
        else:
            print("Invalid move. Try again.")

run_game()

import threading
from typing import List, Tuple

class UAV:
    def __init__(self, identifier: int, start_coords: Tuple[float, float, float] = (0.0, 0.0, 0.0)):
        self.identifier = identifier
        self.coords = list(start_coords)
        self.velocity = 1.0  # Default speed in m/s
        self.height = start_coords[2]
        self.airborne = False
        self.grounded = True
        self.patrol_points = []
        self.patrol_index = 0
        self.mutex = threading.Lock()
        self.instrumentation = {
            'obstacle': False,
            'charge': 100.0  # Percentage
        }

    def ascend(self):
        with self.mutex:
            if not self.airborne:
                self.height = 10  # Ascend to 10 meters
                self.airborne = True
                self.grounded = False
                print(f"UAV {self.identifier} ascended to {self.height} meters.")

    def reposition(self, new_coords: Tuple[float, float, float]):
        with self.mutex:
            if self.airborne:
                self.coords = list(new_coords)
                self.height = new_coords[2]
                print(f"UAV {self.identifier} repositioned to {tuple(self.coords)}.")

    def descend(self):
        with self.mutex:
            if self.airborne:
                self.height = 0
                self.airborne = False
                self.grounded = True
                print(f"UAV {self.identifier} descended.")

    def assign_patrol_route(self, route: List[Tuple[float, float, float]]):
        with self.mutex:
            self.patrol_points = [list(p) for p in route]
            self.patrol_index = 0
            print(f"UAV {self.identifier} patrol route assigned to {[tuple(p) for p in self.patrol_points]}.")

    def execute_patrol(self):
        with self.mutex:
            if self.airborne and self.patrol_index < len(self.patrol_points):
                next_point = tuple(self.patrol_points[self.patrol_index])
                self.reposition(next_point)
                self.patrol_index += 1
                if self.patrol_index == len(self.patrol_points):
                    print(f"UAV {self.identifier} completed all patrol points.")
                else:
                    threading.Timer(1.0, self.execute_patrol).start()
            else:
                print(f"UAV {self.identifier} patrol sequence finished or not airborne.")

    def process_instrumentation(self):
        with self.mutex:
            if self.instrumentation['obstacle']:
                print(f"UAV {self.identifier} obstacle detected. Descending and halting.")
                self.descend()
            if self.instrumentation['charge'] < 20:
                print(f"UAV {self.identifier} low battery. Returning to base.")
                self.reposition((0, 0, 10))
                self.descend()

    def update_instrumentation(self, data: dict):
        with self.mutex:
            self.instrumentation.update(data)
            self.process_instrumentation()

    def deliver_payload(self, location: Tuple[float, float, float]):
        with self.mutex:
            if self.airborne:
                self.reposition(location)
                print(f"UAV {self.identifier} delivered payload at {location}.")

    def collect_payload(self, location: Tuple[float, float, float]):
        with self.mutex:
            if self.airborne:
                self.reposition(location)
                print(f"UAV {self.identifier} collected payload from {location}.")

class UAVManagementSystem:
    def __init__(self):
        self.uavs = {}
        self.global_mutex = threading.Lock()

    def register_uav(self, uav: UAV):
        with self.global_mutex:
            self.uavs[uav.identifier] = uav
            print(f"UAV {uav.identifier} registered in the system.")

    def issue_command(self, uav_id: int, action: str, *parameters, **options):
        with self.global_mutex:
            if uav_id in self.uavs:
                uav = self.uavs[uav_id]
                if action == 'ascend':
                    uav.ascend()
                elif action == 'reposition':
                    uav.reposition(*parameters)
                elif action == 'descend':
                    uav.descend()
                elif action == 'assign_patrol_route':
                    uav.assign_patrol_route(*parameters)
                elif action == 'execute_patrol':
                    uav.execute_patrol()
                elif action == 'update_instrumentation':
                    uav.update_instrumentation(*parameters)
                elif action == 'deliver_payload':
                    uav.deliver_payload(*parameters)
                elif action == 'collect_payload':
                    uav.collect_payload(*parameters)
                else:
                    print(f"Unrecognized command: {action}")
            else:
                print(f"UAV {uav_id} not found in the system.")

    def coordinate_multiple_uavs(self, directives: List[dict]):
        with self.global_mutex:
            for directive in directives:
                uav_id = directive.get('uav_id')
                action = directive.get('action')
                args = directive.get('args', [])
                opts = directive.get('kwargs', {})
                self.issue_command(uav_id, action, *args, **opts)

