import urllib2
import time
import random

def fetch_url(url, retry_limit=5, delay_multiplier=2):
    result = None
    req = urllib2.Request(url=url)
    req.add_header('User-Agent', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3')

    for trial in range(retry_limit):
        try:
            result = urllib2.urlopen(req).read()
            break  # Exit loop on success
        except urllib2.HTTPError as http_err:
            print "HTTPError: {} ({})".format(url, http_err.code)
            if http_err.code != 429:  # Don't retry on non-rate-limit errors
                break
        except urllib2.URLError as url_err:
            print "URLError: {} ({})".format(url, url_err.reason)
        except Exception as exc:
            print "Unexpected error: {}".format(exc)

        # Prepare for next retry with exponential backoff + jitter
        if trial < retry_limit - 1:
            delay = delay_multiplier * (2 ** trial) + random.uniform(0, 1)
            print "Waiting {:.2f} seconds before retry...".format(delay)
            time.sleep(delay)

    return result

def exchange_rate(base="EUR", target="USD"):
