# Determine if list of bracket strings can be rearranged to form valid nested structure

def check_bracket_arrangement(strings):
    """
    Check if the given list of bracket strings can be reordered to form a valid,
    properly nested bracket sequence. Returns ('Yes', max_depth) if possible,
    otherwise ('No', 0).
    """

    def validate_sequence(combined):
        """Check if a combined string forms valid bracket structure and compute max depth."""
        stack = []
        current_level = 0
        peak_level = 0

        for symbol in combined:
            if symbol in '([{':
                stack.append(symbol)
                current_level += 1
                peak_level = max(peak_level, current_level)
            elif symbol == ')':
                if not stack or stack[-1] != '(':
                    return False, 0
                stack.pop()
                current_level -= 1
            elif symbol == ']':
                if not stack or stack[-1] != '[':
                    return False, 0
                stack.pop()
                current_level -= 1
            elif symbol == '}':
                if not stack or stack[-1] != '{':
                    return False, 0
                stack.pop()
                current_level -= 1
            else:
                # Invalid character encountered
                return False, 0

        return len(stack) == 0, peak_level

    def all_orderings(items):
        """Generate all possible orderings of input items."""
        if len(items) <= 1:
            yield items
        else:
            for i in range(len(items)):
                remaining = items[:i] + items[i+1:]
                for perm in all_orderings(remaining):
                    yield [items[i]] + perm

    # Validate input type
    if not isinstance(strings, list) or not all(isinstance(s, str) for s in strings):
        return "Error: Input must be a list of strings", 0

    # Try all permutations until valid arrangement is found
    for arrangement in all_orderings(strings):
        combined = ''.join(arrangement)
        success, depth = validate_sequence(combined)
        if success:
            return "Yes", depth

    return "No", 0

