)
vehicle.fuel_tank_volume_remaining = 50  # liters

# Compute fuel efficiency
vehicle.compute_efficiency(distance_covered=500, fuel_used=30)
print(f"Fuel Efficiency (KPL): {vehicle.efficiency_kilometers_per_liter}")

# Estimate time to travel 100 km
estimated_duration = vehicle.estimate_travel_duration(100)
print(f"Estimated Travel Time for 100 km: {estimated_duration} hours")

# Determine average speed over 100 km in 1 hour
average_velocity = vehicle.determine_mean_speed(total_distance=100, elapsed_time=1)
print(f"Average Velocity: {average_velocity} km/h")

# Assess fuel sufficiency for 150 km journey
fuel_check_result = vehicle.assess_fuel_sufficiency(150)
print(f"Is fuel sufficient for 150 km? {'Yes' if fuel_check_result else 'No'}")

# Record mileage after completing 100 km segment
vehicle.record_mileage(100)
print(f"Odometer Reading: {vehicle.trip_mileage} km")

# Estimate fuel consumption for 100 km
projected_fuel_use = vehicle.estimate_fuel_usage(100)
print(f"Projected Fuel Consumption for 100 km: {projected_fuel_use} liters")

# Convert to standard L/100km metric
standard_metric = vehicle.convert_to_standard_consumption_metric()
print(f"Standard Fuel Consumption (L/100km): {standard_metric}")

