# Simulate banking operations with thread-safe accounts and transaction validation

from typing import List, Tuple, Union, Dict
from threading import Lock
import time

class BankAccount:
    def __init__(self, acc_id: int):
        self.acc_id = acc_id
        self.current_balance = 0
        self.sync_lock = Lock()

    def add_funds(self, value: int) -> bool:
        if value <= 0:
            return False
        with self.sync_lock:
            self.current_balance += value
        return True

    def remove_funds(self, value: int) -> bool:
        if value <= 0 or value > self.current_balance:
            return False
        with self.sync_lock:
            self.current_balance -= value
        return True

class FinancialInstitution:
    def __init__(self):
        self.customer_accounts: Dict[int, BankAccount] = {}
        self.global_lock = Lock()

    def retrieve_account(self, acc_id: int) -> Union[BankAccount, None]:
        with self.global_lock:
            return self.customer_accounts.get(acc_id)

    def open_account(self, acc_id: int) -> BankAccount:
        with self.global_lock:
            if acc_id not in self.customer_accounts:
                self.customer_accounts[acc_id] = BankAccount(acc_id)
            return self.customer_accounts[acc_id]

def process_transactions(transaction_list: List[Tuple[int, str, int]]) -> Union[bool, str, List[int]]:
    financial_system = FinancialInstitution()
    failed_indices = []
    failure_reasons = []

    for position, (account_identifier, action, transaction_value) in enumerate(transaction_list):
        target_account = financial_system.retrieve_account(account_identifier)
        if target_account is None:
            target_account = financial_system.open_account(account_identifier)

        if action == 'Credit':
            if not target_account.add_funds(transaction_value):
                failed_indices.append(position)
                failure_reasons.append(f"Failed credit operation for account {account_identifier}.")
        elif action == 'Debit':
            if not target_account.remove_funds(transaction_value):
                failed_indices.append(position)
                failure_reasons.append(f"Failed debit operation for account {account_identifier}.")
        else:
            failed_indices.append(position)
            failure_reasons.append(f"Unknown action '{action}' for account {account_identifier}.")

    if failed_indices:
        return f"Problems detected: {'; '.join(failure_reasons)}", failed_indices

    for account in financial_system.customer_accounts.values():
        if account.current_balance < 0:
            return True

    return False

# Test cases
print(process_transactions([(1, 'Credit', 1), (2, 'Credit', 2), (1, 'Credit', 3), (2, 'Debit', 4)]))
print(process_transactions([(1, 'Credit', 5), (1, 'Debit', 6), (1, 'Credit', 1), (1, 'Debit', 2)]))
print(process_transactions([(3, 'Credit', -10), (4, 'Credit', -5)]))

# Custom exception hierarchy for discount calculation errors
class DiscountError(Exception):
    """Base exception class for discount-related issues."""
    pass

class PriceIssue(DiscountError):
    """Raised when the price is invalid (non-numeric or negative)."""
    def __init__(self, value):
        self.value = value
        super().__init__(f"Price must be a non-negative number. Received: {value}")

class CouponIssue(DiscountError):
    """Raised when a coupon value is invalid (non-numeric or negative)."""
    def __init__(self, coupon_type, value):
        self.coupon_type = coupon_type
        self.value = value
        super().__init__(f"{coupon_type} coupon must be a non-negative number. Received: {value}")

class RateIssue(DiscountError):
    """Raised when a percentage rate is invalid (out of range 0-100)."""
    def __init__(self, rate):
        self.rate = rate
        super().__init__(f"Percentage rate must be between 0 and 100. Received: {rate}")

class PricingEngine:
    def __init__(self, base_price, flat_discount, percent_discount):
        self.check_validity(base_price, flat_discount, percent_discount)
        self.base_price = float(base_price)
        self.flat_discount = float(flat_discount)
        self.percent_discount = float(percent_discount)

    def check_validity(self, base_price, flat_discount, percent_discount):
        # Attempt to convert inputs to float
        try:
            bp = float(base_price)
            fd = float(flat_discount)
            pd = float(percent_discount)
        except (TypeError, ValueError):
            raise TypeError("All pricing parameters must be numeric values.")

        # Validate each parameter individually
        if bp < 0:
            raise PriceIssue(base_price)
        if fd < 0:
            raise CouponIssue("Cash", flat_discount)
        if not (0 <= pd <= 100):
            raise RateIssue(percent_discount)

    def compute_final_cost(self):
        # Apply flat discount first, ensuring non-negative result
        intermediate_price = max(0.0, self.base_price - self.flat_discount)
        # Apply percentage discount
        final_amount = intermediate_price * (100 - self.percent_discount) / 100
        return final_amount

# Demonstration with test scenarios
if __name__ == "__main__":
    # Test valid scenario
    try:
        engine = PricingEngine(100, 20, 10)
        print(f"Final cost: {engine.compute_final_cost()}")  # Expected: 63.0
    except DiscountError as err:
        print(err)

    # Test invalid base price
    try:
        engine = PricingEngine(-50, 20, 10)
        print(f"Final cost: {engine.compute_final_cost()}")
    except DiscountError as err:
        print(err)

    # Test invalid cash coupon
    try:
        engine = PricingEngine(100, -15, 10)
        print(f"Final cost: {engine.compute_final_cost()}")
    except DiscountError as err:
        print(err)

    # Test invalid percentage rate
    try:
        engine = PricingEngine(100, 20, 120)
        print(f"Final cost: {engine.compute_final_cost()}")
    except DiscountError as err:
        print(err)

    # Test non-numeric input
    try:
        engine = PricingEngine("abc", "20", "ten")
        print(f"Final cost: {engine.compute_final_cost()}")
    except (TypeError, DiscountError) as err:
        print(err)

# Modified version using different logic to compute median without full sorting

def advanced_median(l: list, cmp_func: callable):
    """
    Return median of elements in the list l without sorting it and handles mixed datatypes.
    Handles tuples with variable sizes, duplicates, and uses cmp_func for comparisons.
    """
    def compare(a, b):
        try:
            return cmp_func(a, b)
        except Exception:
            return None

    # Filter elements that can be compared with all others
    filtered = []
    for i, item in enumerate(l):
        is_valid = True
        for j, other in enumerate(l):
            if i != j:
                result = compare(item, other)
                if result is None:
                    is_valid = False
                    break
        if is_valid:
            filtered.append(item)

    if not filtered:
        return None

    n = len(filtered)

    # Use selection algorithm to find median elements
    def select_kth(arr, k):
        # Quickselect implementation with random pivot for better average performance
        left, right = 0, len(arr) - 1
        while True:
            if left == right:
                return arr[left]

            # Choose middle element as pivot (deterministic approach)
            pivot_index = (left + right) // 2
            pivot_value = arr[pivot_index]

            # Partition around pivot
            i = left
            for j in range(left, right + 1):
                if compare(arr[j], pivot_value) < 0:
                    arr[i], arr[j] = arr[j], arr[i]
                    i += 1

            # Place pivot in correct position
            pivot_final_index = i
            arr[pivot_index], arr[pivot_final_index] = arr[pivot_final_index], arr[pivot_index]

            if k == pivot_final_index:
                return arr[k]
            elif k < pivot_final_index:
                right = pivot_final_index - 1
            else:
                left = pivot_final_index + 1

    if n % 2 == 1:
        return select_kth(filtered[:], n // 2)
    else:
        # Find both middle elements for even-length lists
        left_idx = n // 2 - 1
        right_idx = n // 2

        # Get left median
        left_median = select_kth(filtered[:], left_idx)

        # Get right median by selecting from remaining elements
        # Create a copy and remove elements less than or equal to left_median
        temp_arr = filtered[:]
        right_median = select_kth(temp_arr, right_idx)

        # Calculate average for numeric values
        try:
            return (left_median + right_median) / 2
        except TypeError:
            # If addition fails, return both medians as tuple
            return (left_median, right_median)

# Examples
print(advanced_median([3, 1, 2, 4, 5], lambda a, b: a - b))  # => 3
print(advanced_median([-10, 4, 6, 1000, 10, 20], lambda a, b: a - b))  # => 15.0
print(advanced_median([1, 2, 2, 4, 5], lambda a, b: a - b))  # => 2
print(advanced_median(['a', 'b', 1, 2], lambda a, b: a - b))  # => None

import tkinter as tk
from tkinter import ttk, messagebox
import json
import os


class MRIProtocolManager(tk.Tk):
    def __init__(self):
        super().__init__()

        self.data_file = "protocols.json"

        self.title("MRI Protocol Manager")
        self.geometry("800x600")

        self._setup_interface()

        self.refresh_protocol_list()

    def _setup_interface(self):
        self.protocol_listbox = tk.Listbox(self)
        self.protocol_listbox.grid(row=0, column=0, rowspan=10, padx=15, pady=15)

        btn_create = tk.Button(self, text="Create New Protocol", command=self.add_new_protocol)
        btn_create.grid(row=0, column=1, padx=15)

        btn_remove = tk.Button(self, text="Remove Protocol", command=self.remove_existing_protocol)
        btn_remove.grid(row=0, column=2, padx=15)

        self.editor_frame = tk.Frame(self)
        self.editor_frame.grid(row=1, column=1, columnspan=2, padx=15, pady=15)

        self.update_editor_area()

    def refresh_protocol_list(self):
        if os.path.exists(self.data_file):
            with open(self.data_file, "r") as file:
                self.protocols = json.load(file)
        else:
            self.protocols = {}

        self.protocol_listbox.delete(0, tk.END)
        for name in self.protocols:
            self.protocol_listbox.insert(tk.END, name)

    def store_protocols(self):
        with open(self.data_file, "w") as file:
            json.dump(self.protocols, file)

    def add_sequence_to_protocol(self):
        pass

    def add_new_protocol(self):
        protocol_name = tk.simpledialog.askstring("New Protocol", "Enter Protocol Name:")
        if protocol_name and protocol_name not in self.protocols:
            self.protocols[protocol_name] = []
            self.refresh_protocol_list()
            self.store_protocols()

    def update_editor_area(self):
        pass

    def remove_existing_protocol(self):
        selected = self.protocol_listbox.get(tk.ACTIVE)
        if selected and messagebox.askyesno("Confirm Deletion", f"Delete protocol '{selected}'?"):
            del self.protocols[selected]
            self.refresh_protocol_list()
            self.store_protocols()


if __name__ == "__main__":
    app = MRIProtocolManager()
    app.mainloop()

# Define the synonym dictionary
synonyms_dict = {
    'happy': ['joyful', 'content', 'pleased'],
    'sad': ['unhappy', 'miserable', 'sorrowful'],
    'pleased': ['satisfied'],
    'unhappy': ['miserable']
}

# 1. Display how many synonyms each term has in the dictionary
def display_synonym_quantity(synonyms_dict):
    for term, alternatives in synonyms_dict.items():
        print(f"{term} has {len(alternatives)} alternatives.")

# 2. Print all alternative words for each term
def print_alternatives(synonyms_dict):
    for term, alternatives in synonyms_dict.items():
        print(f"{term}: {', '.join(alternatives)}")

# 3. Identify and show terms that have overlapping alternative words
def detect_overlapping_alternatives(synonyms_dict):
    overlapping_terms = {}
    for term_a, alts_a in synonyms_dict.items():
        for term_b, alts_b in synonyms_dict.items():
            if term_a != term_b and set(alts_a) & set(alts_b):
                overlapping_terms.setdefault(term_a, []).append(term_b)

    for term, related_terms in overlapping_terms.items():
        print(f"{term} shares alternatives with: {', '.join(related_terms)}")

# 4. Determine a chain of connected terms linking two specified words
def discover_term_chain(synonyms_dict, origin_term, destination_term):
    # Build an undirected graph from the dictionary
    connection_graph = {}
    for term, alternatives in synonyms_dict.items():
        connection_graph[term] = set(alternatives)
        for alt in alternatives:
            if alt not in connection_graph:
                connection_graph[alt] = set()
            connection_graph[alt].add(term)

    # BFS traversal to locate shortest path
    from collections import deque
    search_queue = deque([(origin_term, [origin_term])])
    explored = set([origin_term])

    while search_queue:
        current_term, route = search_queue.popleft()
        if current_term == destination_term:
            return route
        for adjacent in connection_graph.get(current_term, []):
            if adjacent not in explored:
                explored.add(adjacent)
                search_queue.append((adjacent, route + [adjacent]))

    return None

# Demonstration
if __name__ == "__main__":
    # 1. Show how many alternatives each term has
    print("Alternative count per term:")
    display_synonym_quantity(synonyms_dict)
    print()

    # 2. List all alternatives for each term
    print("Alternatives for each term:")
    print_alternatives(synonyms_dict)
    print()

    # 3. Find terms sharing at least one alternative
    print("Terms with overlapping alternatives:")
    detect_overlapping_alternatives(synonyms_dict)
    print()

    # 4. Find a chain connecting two specific terms
    origin = 'happy'
    target = 'sorrowful'
    chain = discover_term_chain(synonyms_dict, origin, target)
    if chain:
        print(f"Term chain from '{origin}' to '{target}': {', '.join(chain)}")
    else:
        print(f"No term chain found from '{origin}' to '{target}'")

# Web scraper to find and rank URLs containing a specific keyword

import requests
from bs4 import BeautifulSoup
import re

def get_page_content(target_url):
    try:
        response = requests.get(target_url)
        response.raise_for_status()
        return response.text
    except requests.RequestException as error:
        print(f"Failed to retrieve page: {error}")
        return None

def collect_links(page_html, search_term, filter_out):
    parsed_html = BeautifulSoup(page_html, 'html.parser')
    matching_links = []
    for anchor in parsed_html.find_all('a', href=True):
        link_url = anchor['href']
        if search_term.lower() in link_url.lower() and filter_out not in link_url.lower():
            matching_links.append(link_url)
    return matching_links

def tally_keyword_matches(link_list, target_word):
    keyword_frequency = {}
    pattern = re.compile(re.escape(target_word), re.IGNORECASE)
    for link in link_list:
        matches = pattern.findall(link)
        if matches:
            keyword_frequency[link] = len(matches)
    return keyword_frequency

def refine_and_rank(keyword_data, threshold):
    significant_entries = {
        url: frequency 
        for url, frequency in keyword_data.items() 
        if frequency > threshold
    }
    ranked_list = sorted(
        significant_entries.items(), 
        key=lambda item: item[1], 
        reverse=True
    )
    return ranked_list

def process_web_analysis():
    base_url = 'http://www.example.com'
    search_keyword = 'technology'
    exclusion_term = 'advertisement'
    minimum_count = 5

    page_source = get_page_content(base_url)
    if page_source:
        found_links = collect_links(page_source, search_keyword, exclusion_term)
        keyword_stats = tally_keyword_matches(found_links, search_keyword)
        final_ranking = refine_and_rank(keyword_stats, minimum_count)

        for link, match_count in final_ranking:
            print(f"URL: {link}, Matches: {match_count}")

if __name__ == "__main__":
    process_web_analysis()

# Process user data with validation and status updates

import json
import re
from datetime import datetime, timedelta

# Input JSON string
json_input = '''
{
    "users": [
        {
            "name": "John Doe",
            "code": "Abc123",
            "used": true,
            "last_active": "2023-10-01T12:00:00Z"
        },
        {
            "name": "Jane Smith",
            "code": "Def456",
            "used": false,
            "last_active": "2023-09-01T12:00:00Z"
        },
        {
            "name": "Alice Johnson",
            "code": "Ghi789",
            "used": true,
            "last_active": "2023-11-01T12:00:00Z"
        }
    ]
}
'''

# Parse the JSON input
parsed_data = json.loads(json_input)

# Define special characters for code validation
special_chars_set = {'!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '-', '+', '=', '{', '}', '[', ']', '|', '\\', ':', ';', '<', '>', '?', '/', '.', ',', '~', '`'}

# Validate name format using regex
def check_name_format(name_str):
    return bool(re.fullmatch(r'[A-Za-z\s]+', name_str))

# Check if code contains any special character
def has_special_in_code(code_val, special_chars):
    for char in code_val:
        if char in special_chars:
            return True
    return False

# Determine activity status based on last active date
def is_currently_active(timestamp_str):
    # Convert ISO format to datetime object
    dt_obj = datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))
    # Calculate cutoff date (30 days ago)
    cutoff_date = datetime.now() - timedelta(days=30)
    return dt_obj > cutoff_date

# Iterate through each user record
for user_record in parsed_data['users']:
    # Add email if name is valid
    if check_name_format(user_record['name']):
        email_part = user_record['name'].replace(' ', '').lower()
        user_record['email'] = f"{email_part}@example.com"
    else:
        print(f"Invalid name format detected for: {user_record['name']}")

    # Verify code contains at least one special character
    if not has_special_in_code(user_record['code'], special_chars_set):
        print(f"Warning: Code for {user_record['name']} lacks special characters.")

    # Update status field and remove old 'used' field
    user_record['status'] = 'active' if is_currently_active(user_record['last_active']) else 'inactive'
    user_record.pop('used', None)  # Safely remove 'used' key

# Print final processed JSON output
print(json.dumps(parsed_data, indent=4))

# Flask REST API for managing items using SQLite database

from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_marshmallow import Marshmallow

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///items.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db = SQLAlchemy(app)
ma = Marshmallow(app)

class Product(db.Model):
    product_id = db.Column(db.Integer, primary_key=True)
    product_name = db.Column(db.String(100), unique=True, nullable=False)
    product_desc = db.Column(db.String(200))

    def __init__(self, name, description):
        self.product_name = name
        self.product_desc = description

class ProductSchema(ma.Schema):
    class Meta:
        fields = ('product_id', 'product_name', 'product_desc')

product_schema = ProductSchema()
products_schema = ProductSchema(many=True)

@app.route('/products', methods=['POST'])
def create_product():
    name = request.json['name']
    description = request.json['description']
    new_product = Product(name, description)
    db.session.add(new_product)
    db.session.commit()
    return product_schema.jsonify(new_product), 201

@app.route('/products', methods=['GET'])
def list_products():
    all_products = Product.query.all()
    result = products_schema.dump(all_products)
    return jsonify(result)

@app.route('/products/<int:product_id>', methods=['GET'])
def retrieve_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({'error': 'Product not found'}), 404
    return product_schema.jsonify(product)

@app.route('/products/<int:product_id>', methods=['PUT'])
def modify_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({'error': 'Product not found'}), 404
    product.product_name = request.json['name']
    product.product_desc = request.json['description']
    db.session.commit()
    return product_schema.jsonify(product)

@app.route('/products/<int:product_id>', methods=['DELETE'])
def remove_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({'error': 'Product not found'}), 404
    db.session.delete(product)
    db.session.commit()
    return product_schema.jsonify(product)

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=True)

# Triangle class implementation with validation and helper methods

import math

class Triangle:
    total_instances = 0  # Class variable to count created instances

    def __init__(self, a, b, c):
        if not self._check_sides_validity(a, b, c):
            raise ValueError("Triangle sides must be positive and satisfy triangle inequality")
        self.a = a
        self.b = b
        self.c = c
        Triangle.total_instances += 1

    def _check_sides_validity(self, x, y, z):
        return all(side > 0 for side in [x, y, z]) and \
               x + y > z and x + z > y and y + z > x

    def perimeter(self):
        return self.a + self.b + self.c

    def area(self):
        return self._compute_area_heron(self.a, self.b, self.c)

    def _compute_area_heron(self, s1, s2, s3):
        semi_perimeter = (s1 + s2 + s3) / 2
        if any(semi_perimeter - side <= 0 for side in [s1, s2, s3]):
            return 0.0
        return math.sqrt(semi_perimeter * 
                        (semi_perimeter - s1) * 
                        (semi_perimeter - s2) * 
                        (semi_perimeter - s3))

    @property
    def equilateral_check(self):
        return self.a == self.b == self.c

    @property
    def isosceles_check(self):
        return self.a == self.b or self.b == self.c or self.a == self.c

    def temporary_resize(self, new_a, new_b, new_c):
        if not self._check_sides_validity(new_a, new_b, new_c):
            print("Cannot resize: invalid triangle dimensions")
            return False

        original = (self.a, self.b, self.c)
        self.a, self.b, self.c = new_a, new_b, new_c
        result = True
        try:
            yield result
        finally:
            self.a, self.b, self.c = original

# Demonstration code
try:
    tri1 = Triangle(3, 4, 5)
    print(f"Perimeter: {tri1.perimeter()}")
    print(f"Area: {tri1.area()}")
    print(f"Equilateral? {tri1.equilateral_check}")
    print(f"Isosceles? {tri1.isosceles_check}")

    # Resize to equilateral triangle temporarily
    with tri1.temporary_resize(5, 5, 5) as resized:
        if resized:
            print(f"Temporarily resized to equilateral: {tri1.equilateral_check}")
        else:
            print("Resize operation failed")

    print(f"After resize attempt: sides are {tri1.a}, {tri1.b}, {tri1.c}")

    # Attempt invalid resize
    with tri1.temporary_resize(1, 2, 3) as resized:
        if resized:
            print(f"Resized to {tri1.a}, {tri1.b}, {tri1.c}")
        else:
            print("Resize operation failed due to invalid dimensions")

    print(f"Final sides: {tri1.a}, {tri1.b}, {tri1.c}")
except ValueError as error_msg:
    print(error_msg)

