# Simulate First-Come-First-Serve (FCFS) CPU scheduling algorithm

class Job:
    def __init__(self, identifier, entry_time, execution_duration):
        self.identifier = identifier
        self.entry_time = entry_time
        self.execution_duration = execution_duration
        self.remaining_duration = execution_duration
        self.completion_time = None
        self.start_execution_time = None

    def __str__(self):
        return f"Job(id={self.identifier}, arrival={self.entry_time}, duration={self.execution_duration})"

class FCFS_Controller:
    def __init__(self):
        self.jobs = []

    def enqueue_job(self, job):
        self.jobs.append(job)

    def execute_schedule(self):
        # Order jobs by their arrival time
        self.jobs.sort(key=lambda j: j.entry_time)

        current_clock = 0
        for job in self.jobs:
            if job.entry_time > current_clock:
                current_clock = job.entry_time
            job.start_execution_time = current_clock
            current_clock += job.execution_duration
            job.completion_time = current_clock

    def generate_execution_timeline(self):
        timeline = []
        for job in self.jobs:
            timeline.append((job.start_execution_time, job.completion_time, job.identifier))
        return timeline

    def compute_mean_wait_time(self):
        cumulative_wait = 0
        for job in self.jobs:
            if job.start_execution_time is not None:
                cumulative_wait += job.start_execution_time - job.entry_time
        return cumulative_wait / len(self.jobs) if self.jobs else 0

    def compute_mean_response_time(self):
        cumulative_turnaround = 0
        for job in self.jobs:
            if job.completion_time is not None:
                cumulative_turnaround += job.completion_time - job.entry_time
        return cumulative_turnaround / len(self.jobs) if self.jobs else 0

# Demonstration
if __name__ == "__main__":
    controller = FCFS_Controller()

    # Add sample jobs
    controller.enqueue_job(Job(1, 0, 24))
    controller.enqueue_job(Job(2, 4, 3))
    controller.enqueue_job(Job(3, 5, 3))

    # Run the scheduler
    controller.execute_schedule()

    # Display results
    timeline = controller.generate_execution_timeline()
    print("Execution Timeline:")
    for start, end, pid in timeline:
        print(f"Job {pid} runs from {start} to {end}")

    print(f"Mean Waiting Time: {controller.compute_mean_wait_time():.2f}")
    print(f"Mean Response Time: {controller.compute_mean_response_time():.2f}")

# Chatbot with greeting and question handling capabilities

def acknowledge_greeting(text):
    known_greetings = ['hello', 'hi', 'hey', 'hola']
    for token in text.split():
        if token.lower() in known_greetings:
            return "Hello! How can I assist you today?"
    return None

def handle_inquiry(text):
    if "how are you" in text.lower():
        return "I'm just a computer program, but thanks for asking! How can I help you?"
    return None

def generate_response(input_text):
    # First check for greetings
    reply = acknowledge_greeting(input_text)
    if reply is not None:
        return reply

    # Then check for questions/inquiries
    reply = handle_inquiry(input_text)
    if reply is not None:
        return reply

    # Default response if no match found
    return "I'm not sure how to respond to that. Could you please rephrase or ask another question?"

