import requests
import json

# Spotify API configuration
client_identifier = 'YOUR_CLIENT_ID'
client_secret_key = 'YOUR_CLIENT_SECRET'

# Function to authenticate and retrieve access token
def fetch_access_token(client_id, client_secret):
    endpoint = 'https://accounts.spotify.com/api/token'
    request_headers = {
        'Content-Type': 'application/x-www-form-urlencoded'
    }
    payload = {
        'grant_type': 'client_credentials',
        'client_id': client_id,
        'client_secret': client_secret
    }
    api_response = requests.post(endpoint, headers=request_headers, data=payload)
    if api_response.status_code == 200:
        return api_response.json()['access_token']
    else:
        raise RuntimeError('Failed to obtain access token: {}'.format(api_response.text))

# Function to look up a track using search criteria
def find_track(access_token, track_title, performer_name):
    endpoint = 'https://api.spotify.com/v1/search'
    request_headers = {
        'Authorization': 'Bearer {}'.format(access_token)
    }
    query_params = {
        'q': 'track:{} artist:{}'.format(track_title, performer_name),
        'type': 'track',
        'limit': 1
    }
    api_response = requests.get(endpoint, headers=request_headers, params=query_params)
    if api_response.status_code == 200:
        return api_response.json()
    else:
        raise RuntimeError('Track search failed: {}'.format(api_response.text))

# Function to retrieve detailed audio analysis for a track
def obtain_audio_metrics(access_token, track_identifier):
    endpoint = 'https://api.spotify.com/v1/audio-features/{}'.format(track_identifier)
    request_headers = {
        'Authorization': 'Bearer {}'.format(access_token)
    }
    api_response = requests.get(endpoint, headers=request_headers)
    if api_response.status_code == 200:
        return api_response.json()
    else:
        raise RuntimeError('Audio metrics retrieval failed: {}'.format(api_response.text))

# Function to categorize the track based on audio characteristics
def categorize_track(audio_metrics):
    # Apply rule-based classification using audio feature thresholds
    if audio_metrics['energy'] > 0.8 and audio_metrics['loudness'] > -6.0:
        return 'rock'
    elif audio_metrics['acousticness'] > 0.5 and audio_metrics['instrumentalness'] > 0.5:
        return 'country'
    elif audio_metrics['speechiness'] > 0.3 and audio_metrics['tempo'] > 100:
        return 'hip-hop'
    else:
        return 'pop'

# Entry point of the application
if __name__ == "__main__":
