    # Extract unique identifier for the track
    track_id = search_response['tracks']['items'][0]['id']

    # Fetch audio features
    audio_data = obtain_audio_metrics(token, track_id)

    # Determine genre category
    category = categorize_track(audio_data)

    print(f"The track '{track_title}' by {performer_name} is categorized as: {category}")
    print("Audio Features:", json.dumps(audio_data, indent=2))

class FibonacciHeapNode:
    def __init__(self, value):
        self.value = value
        self.parent = None
        self.children = None
        self.prev = self
        self.next = self
        self.level = 0
        self.is_cut = False

class FibonacciHeap:
    def __init__(self):
        self.minimum = None
        self.total_items = 0
        self.maximum = None

    def add(self, value):
        new_node = FibonacciHeapNode(value)
        if self.minimum is None:
            self.minimum = new_node
        else:
            self._attach(new_node, self.minimum)
            if new_node.value < self.minimum.value:
                self.minimum = new_node
        self.total_items += 1

    def _attach(self, first, second):
        # Remove first from its current list
        first.prev.next = first.next
        first.next.prev = first.prev

        # Make first a child of second
        first.parent = second
        if second.children is None:
            second.children = first
        else:
            first.next = second.children
            first.prev = second.children.prev
            second.children.prev.next = first
            second.children.prev = first
        second.level += 1
        first.is_cut = False

    def remove_min(self):
        z = self.minimum
        if z is not None:
            if z.children is not None:
                # Promote all children to root level
                child = z.children
                while True:
                    next_child = child.next
                    child.prev.next = child.next
                    child.next.prev = child.prev
                    self._attach(child, self.minimum)
                    if next_child == z.children:
                        break
                    child = next_child

            # Remove z from root list
            z.prev.next = z.next
            z.next.prev = z.prev

            if z == z.next:
                self.minimum = None
            else:
                self.minimum = z.next
                self._rebalance()

            self.total_items -= 1

        if z == self.maximum:
            self.maximum = self._locate_max()

        return z.value if z else None

    def _rebalance(self):
        degree_table = [None] * (self.total_items.bit_length() + 2)
        current = self.minimum
        nodes_list = []

        # Collect all root nodes
        if current is not None:
            start = current
            while True:
                nodes_list.append(current)
                current = current.next
                if current == start:
                    break

        for current in nodes_list:
            x = current
            d = x.level

            while degree_table[d] is not None:
                y = degree_table[d]
                if x.value > y.value:
                    x, y = y, x
                self._attach(y, x)
                degree_table[d] = None
                d += 1

            degree_table[d] = x

        self.minimum = None
        for node in degree_table:
            if node is not None:
                if self.minimum is None:
                    self.minimum = node
                else:
                    self._attach(node, self.minimum)
                    if node.value < self.minimum.value:
                        self.minimum = node

    def update_value(self, node, new_val):
        if new_val > node.value:
            raise ValueError("new value is larger than current value")

        node.value = new_val
        parent = node.parent

        if parent is not None and node.value < parent.value:
            self._separate(node, parent)
            self._cascade(parent)

        if node.value < self.minimum.value:
            self.minimum = node

    def _separate(self, node, parent):
        node.prev.next = node.next
        node.next.prev = node.prev
        parent.level -= 1

        if parent.children == node:
            parent.children = node.next

        node.prev = node.next = node
        self._attach(node, self.minimum)
        node.parent = None
        node.is_cut = False

    def _cascade(self, node):
        parent = node.parent
        if parent is not None:
            if not node.is_cut:
                node.is_cut = True
            else:
                self._separate(node, parent)
                self._cascade(parent)

    def remove_node(self, node):
        self.update_value(node, float('-inf'))
        self.remove_min()

    def get_min(self):
        return self.minimum.value if self.minimum else None

    def _locate_max(self):
        max_node = None
        if self.minimum is not None:
            max_node = self.minimum
            current = self.minimum.next
            while current != self.minimum:
                if current.value > max_node.value:
                    max_node = current
                current = current.next
        return max_node

    def get_max(self):
        if self.maximum is None:
            self.maximum = self._locate_max()
        return self.maximum.value if self.maximum else None

    def increase_value(self, node, new_val):
        if new_val < node.value:
            raise ValueError("new value is smaller than current value")

        node.value = new_val
        if node == self.minimum:
            self.minimum = self._find_minimum()
        if node == self.maximum:
            self.maximum = self._locate_max()

    def combine(self, other_heap):
        if self.minimum is None:
            self.minimum = other_heap.minimum
        elif other_heap.minimum is not None:
            self.minimum.next.prev = other_heap.minimum.prev
            other_heap.minimum.prev.next = self.minimum.next
            self.minimum.next = other_heap.minimum
            other_heap.minimum.prev = self.minimum

            if other_heap.minimum.value < self.minimum.value:
                self.minimum = other_heap.minimum

        self.total_items += other_heap.total_items
        self.maximum = self._locate_max()

    def remove_max(self):
        if self.maximum is not None:
            max_value = self.maximum.value
            self.update_value(self.maximum, float('-inf'))
            self.remove_min()
            return max_value
        return None

    def _find_minimum(self):
        min_node = None
        if self.minimum is not None:
            min_node = self.minimum
            current = self.minimum.next
            while current != self.minimum:
                if current.value < min_node.value:
                    min_node = current
                current = current.next
        return min_node

