# Simulate digital circuit with bitwise operations

def execute_command(cmd, components):
    parts = cmd.split()

    # Handle AND operation
    if 'AND' in parts:
        operand1, _, operand2, _, target = parts
        val1 = int(operand1) if operand1.isdigit() else (components[operand1] if operand1 in components else None)
        val2 = components.get(operand2)
        if val1 is not None and val2 is not None:
            components[target] = val1 & val2

    # Handle OR operation
    elif 'OR' in parts:
        operand1, _, operand2, _, target = parts
        if operand1 in components and operand2 in components:
            components[target] = components[operand1] | components[operand2]

    # Handle left shift
    elif 'LSHIFT' in parts:
        source, _, shift_val, _, target = parts
        if source in components:
            components[target] = components[source] << int(shift_val)

    # Handle right shift
    elif 'RSHIFT' in parts:
        source, _, shift_val, _, target = parts
        if source in components:
            components[target] = components[source] >> int(shift_val)

    # Handle NOT operation
    elif 'NOT' in parts:
        _, source, _, target = parts
        if source in components:
            components[target] = ~components[source] & 0xFFFF

    # Handle direct assignment
    else:
        value, _, target = parts
        if value.isdigit():
            components[target] = int(value)
        elif value in components:
            components[target] = components[value]

def run_circuit(commands_list):
    component_values = {}
    pending_commands = commands_list.copy()

    while pending_commands:
        current_cmd = pending_commands.pop(0)
        initial_len = len(component_values)

        execute_command(current_cmd, component_values)

        # Check if any new wire was assigned a value
        if len(component_values) == initial_len:
            # If no progress made, requeue the command
            pending_commands.append(current_cmd)

    return component_values['a']

# Circuit instructions
circuit_instructions = [
