class RadioStation:
    def __init__(self):
        self.shows = {}
        self.next_show_id = 1

    def register_show(self, name, info, length, air_date):
        show_id = self.next_show_id
        new_show = RadioShow(show_id, name, info, length, air_date)
        self.shows[show_id] = new_show
        self.next_show_id += 1
        return show_id

    def modify_show(self, show_id, name=None, info=None, length=None, air_date=None):
        if show_id not in self.shows:
            raise ValueError(f"Show with ID {show_id} is not registered.")

        program = self.shows[show_id]
        if name is not None:
            program.name = name
        if info is not None:
            program.info = info
        if length is not None:
            program.length = length
        if air_date is not None:
            program.air_date = air_date

    def remove_show(self, show_id):
        if show_id not in self.shows:
            raise ValueError(f"Show with ID {show_id} is not registered.")

        del self.shows[show_id]

    def retrieve_show(self, show_id):
        if show_id not in self.shows:
            raise ValueError(f"Show with ID {show_id} is not registered.")

        return self.shows[show_id]

    def display_all_shows(self):
        return list(self.shows.values())

