import math

class Point:
    def __init__(self, x_coord, y_coord):
        self.x = x_coord
        self.y = y_coord

    def get_distance(self, other_point):
        if not isinstance(other_point, Point):
            raise TypeError("Expected a Point object")
        return math.sqrt((self.x - other_point.x) ** 2 + (self.y - other_point.y) ** 2)

class ShapeInterface:
    def compute_area(self):
        raise NotImplementedError

    def compute_perimeter(self):
        raise NotImplementedError

    def compare_with(self, other_shape):
        if not isinstance(other_shape, self.__class__.__bases__[0]):
            return False
        return (self.compute_area() == other_shape.compute_area() and 
                self.compute_perimeter() == other_shape.compute_perimeter())

    def get_separation(self, other_shape):
        raise NotImplementedError

    def transform(self, rotation_degrees):
        pass

    def get_enclosing_box(self):
        raise NotImplementedError

class Rectangle(ShapeInterface):
    def __init__(self, rect_width, rect_height, mid_point=Point(0, 0)):
        if rect_width <= 0 or rect_height <= 0:
            raise ValueError("Dimensions must be positive")
        self.width = rect_width
        self.height = rect_height
        self.midpoint = mid_point

    def compute_area(self):
        return self.width * self.height

    def compute_perimeter(self):
        return 2 * (self.width + self.height)

    def get_separation(self, other_shape):
        if not isinstance(other_shape, ShapeInterface):
            raise TypeError("Other shape must implement ShapeInterface")
        return self.midpoint.get_distance(other_shape.midpoint)

    def transform(self, rotation_degrees):
        # Rotation doesn't affect rectangle's dimensions
        pass

    def get_enclosing_box(self):
        return self

class Circle(ShapeInterface):
    def __init__(self, circle_radius, mid_point=Point(0, 0)):
        if circle_radius <= 0:
            raise ValueError("Radius must be positive")
        self.radius = circle_radius
        self.midpoint = mid_point

    def compute_area(self):
        return math.pi * (self.radius ** 2)

    def compute_perimeter(self):
        return 2 * math.pi * self.radius

    def get_separation(self, other_shape):
        if not isinstance(other_shape, ShapeInterface):
            raise TypeError("Other shape must implement ShapeInterface")
        return self.midpoint.get_distance(other_shape.midpoint)

    def transform(self, rotation_degrees):
        # Circle remains unchanged after rotation
        pass

    def get_enclosing_box(self):
        diameter = 2 * self.radius
        return Rectangle(diameter, diameter, self.midpoint)

class Triangle(ShapeInterface):
    def __init__(self, side_a, side_b, side_c, mid_point=Point(0, 0)):
        if (side_a <= 0 or side_b <= 0 or side_c <= 0 or 
            not self.validate_triangle(side_a, side_b, side_c)):
            raise ValueError("Invalid triangle parameters")
        self.side_a = side_a
        self.side_b = side_b
        self.side_c = side_c
        self.midpoint = mid_point

    @staticmethod
    def validate_triangle(a, b, c):
        return (a + b > c and a + c > b and b + c > a)

    def compute_area(self):
        semi_perimeter = (self.side_a + self.side_b + self.side_c) / 2
        return math.sqrt(semi_perimeter * 
                         (semi_perimeter - self.side_a) * 
                         (semi_perimeter - self.side_b) * 
                         (semi_perimeter - self.side_c))

    def compute_perimeter(self):
        return self.side_a + self.side_b + self.side_c

    def get_separation(self, other_shape):
        if not isinstance(other_shape, ShapeInterface):
            raise TypeError("Other shape must implement ShapeInterface")
        return self.midpoint.get_distance(other_shape.midpoint)

    def transform(self, rotation_degrees):
        # Placeholder for rotation logic
        pass

    def get_enclosing_box(self):
        longest_side = max(self.side_a, self.side_b, self.side_c)
        return Rectangle(longest_side, longest_side, self.midpoint)

