import re

# Normalize VAT ID by removing non-alphanumeric characters and converting to uppercase
def normalize_vat_id(vat_id):
    return re.sub(r'\W', '', vat_id).upper()

# Compute weighted checksum for validation
def compute_weighted_checksum(digits, weights, mod=97):
    total = sum(weight * digit for weight, digit in zip(weights, digits))
    return total % mod

# Validate European VAT IDs based on country-specific rules
