        if len(vat_input) != 9 or not vat_input.startswith('AT'):
            return False
        numeric_part = [int(d) for d in vat_input[2:]]
        weights = [3, 7, 1, 3, 7, 1, 3, 7]
        computed_check = (10 - compute_weighted_checksum(numeric_part[:8], weights, 10)) % 10
        return numeric_part[-1] == computed_check

    # Belgium (BE)
    elif country_code == 'BE':
        if len(vat_input) != 10 or not vat_input.startswith('BE'):
            return False
        number = int(vat_input[2:])
