        self.sync_lock = threading.Lock()

    def initiate_countdown(self, seconds, completion_handler=None):
        if not isinstance(seconds, int) or seconds <= 0:
            raise ValueError("Time must be a positive integer greater than zero")

        unique_id = str(uuid.uuid4())
        countdown = Countdown(seconds, completion_handler, self._timer_finished, unique_id)
        countdown.launch()

        with self.sync_lock:
            self.active_timers[unique_id] = countdown

        return unique_id

    def _timer_finished(self, timer_key):
        with self.sync_lock:
            timer = self.active_timers.pop(timer_key, None)
            if timer and timer.on_complete:
                timer.on_complete()

    def suspend_timer(self, timer_key):
        with self.sync_lock:
            timer = self.active_timers.get(timer_key)
            if timer:
                timer.suspend()

    def reactivate_timer(self, timer_key):
        with self.sync_lock:
            timer = self.active_timers.get(timer_key)
            if timer:
                timer.reactivate()

    def abort_timer(self, timer_key):
        with self.sync_lock:
            timer = self.active_timers.pop(timer_key, None)
            if timer:
                timer.terminate()

class Countdown:
    def __init__(self, total_time, on_complete, finish_callback, identifier):
        self.total_time = total_time
        self.on_complete = on_complete
        self.finish_callback = finish_callback
        self.identifier = identifier
        self.worker_thread = None
        self.is_active = False
        self.is_suspended = False
        self.time_left = total_time

    def launch(self):
        if not self.is_active:
            self.is_active = True
            self.worker_thread = threading.Thread(target=self._execute)
            self.worker_thread.start()

    def _execute(self):
        initial_timestamp = time.time()
        while self.time_left > 0 and not self.is_suspended:
            current_timestamp = time.time()
            elapsed = current_timestamp - initial_timestamp
            self.time_left = max(0, self.total_time - elapsed)
            time.sleep(0.1)  # Minimize CPU consumption

        if self.time_left == 0:
            self.finish_callback(self.identifier)

    def suspend(self):
        if self.is_active and not self.is_suspended:
            self.is_suspended = True

    def reactivate(self):
        if self.is_active and self.is_suspended:
            self.is_suspended = False
            self.worker_thread = threading.Thread(target=self._execute)
            self.worker_thread.start()

    def terminate(self):
        self.is_active = False
        self.is_suspended = False
        if self.worker_thread and self.worker_thread.is_alive():
            self.worker_thread.join()

