# Custom delegate for rendering clickable hyperlinks in a table view

from PyQt5.QtWidgets import QStyledItemDelegate, QStyleOptionViewItem, QApplication, QWidget, QVBoxLayout, QTableView
from PyQt5.QtGui import QPainter, QCursor, QDesktopServices, QFontMetrics
from PyQt5.QtCore import Qt, QEvent, QModelIndex, QUrl, QSize
import sys

class LinkTableDelegate(QStyledItemDelegate):
    def __init__(self, parent=None):
        super(LinkTableDelegate, self).__init__(parent)
        self._hyperlink_data = {}

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex):
        # Only handle hyperlink column (column index 1)
        if index.column() == 1:
            text_content = index.data(Qt.DisplayRole)
            url_data = index.data(Qt.UserRole)

            if url_data and isinstance(url_data, list):
                self._hyperlink_data[index] = url_data

                # Render background with selection highlight if needed
                painter.save()
                painter.setRenderHint(QPainter.Antialiasing, True)

                if option.state & QStyle.State_Selected:
                    painter.fillRect(option.rect, option.palette.highlight())

                painter.restore()

                # Draw each hyperlink text and underline
                for idx, link_item in enumerate(url_data):
                    link_text = link_item['text']
                    text_bounds = painter.fontMetrics().boundingRect(option.rect, Qt.TextWordWrap, link_text)

                    # Calculate position for this specific link
                    link_rect = option.rect.adjusted(0, idx * text_bounds.height(), 0, 0)
                    painter.setPen(Qt.blue)
                    painter.drawText(link_rect, Qt.TextWordWrap, link_text)

                    # Underline the link text
                    text_height = painter.fontMetrics().height()
                    line_y = link_rect.bottom() - int(text_height * 0.2)
                    painter.setPen(Qt.blue)
                    painter.drawLine(link_rect.left(), line_y, link_rect.right(), line_y)

                painter.restore()
            else:
                # Fallback to default painting if no links
                super().paint(painter, option, index)
        else:
            # Default painting for other columns
            super().paint(painter, option, index)

    def editorEvent(self, event: QEvent, model: QAbstractItemModel, option: QStyleOptionViewItem, index: QModelIndex):
        # Handle mouse click events on hyperlink column
        if event.type() == QEvent.MouseButtonRelease and index.column() == 1:
            if index in self._hyperlink_data:
                url_list = self._hyperlink_data[index]
                current_row = 0

                for link_item in url_list:
                    link_text = link_item['text']
                    text_rect = self.style().itemTextRect(option.fontMetrics, option.rect, Qt.AlignLeft, True, link_text)

                    # Adjust rectangle for multiple links in same cell
                    adjusted_rect = text_rect.adjusted(0, current_row * text_rect.height(), 0, current_row * text_rect.height())

                    if adjusted_rect.contains(event.pos()):
                        QDesktopServices.openUrl(QUrl(link_item['url']))
                        return True

                    current_row += 1

        return super().editorEvent(event, model, option, index)

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex):
        if index.column() == 1:
            url_info = index.data(Qt.UserRole)
            if url_info and isinstance(url_info, list):
                total_height = 0
                for link_item in url_info:
                    text_metrics = QFontMetrics(option.font)
                    text_height = text_metrics.boundingRect(link_item['text']).height()
                    total_height += text_height + 4  # Add small padding

                return QSize(option.rect.width(), total_height)

        return super().sizeHint(option, index)

# Display the current state of the Tic-Tac-Toe board
def show_grid(grid):
    for line in grid:
        print(" | ".join(line))
        print("-" * 5)

# Determine if a player has won the game
def has_won(grid, marker):
    # Check horizontal lines
    for line in grid:
        if all([cell == marker for cell in line]):
            return True

    # Check vertical lines
    for col in range(3):
        if all([grid[row][col] == marker for row in range(3)]):
            return True

    # Check diagonals
    if all([grid[idx][idx] == marker for idx in range(3)]) or \
       all([grid[idx][2 - idx] == marker for idx in range(3)]):
        return True

    return False

# Check if the board is completely filled
def is_filled(grid):
    return all([cell != ' ' for line in grid for cell in line])

# Main game loop
def play_game():
    grid = [[' ' for _ in range(3)] for _ in range(3)]
    turn = 'X'

    while True:
        show_grid(grid)
        print(f"Player {turn}'s move")

        try:
            r = int(input("Enter row (0, 1, or 2): "))
            c = int(input("Enter column (0, 1, or 2): "))
        except ValueError:
            print("Invalid input. Please enter numbers only.")
            continue

        if grid[r][c] != ' ':
            print("That spot is already taken! Choose another.")
            continue

        grid[r][c] = turn

        if has_won(grid, turn):
            show_grid(grid)
            print(f"Player {turn} takes the victory!")
            break

        if is_filled(grid):
            show_grid(grid)
            print("It's a tie!")
            break

        # Switch players
        turn = 'O' if turn == 'X' else 'X'

if __name__ == "__main__":
    play_game()

# Determine if a number can be expressed as base^exponent where base >= 2 and exponent >= 2

import math

def find_power_representation(number):
    # Handle edge cases: numbers less than 4 cannot be represented as base^exponent with both >= 2
    if number < 4:
        return None

    # Check possible bases from 2 up to sqrt(number) + 1
    max_base = int(math.sqrt(number)) + 2

    for base in range(2, max_base):
        # Calculate approximate exponent using logarithm
        approx_exp = int(math.log(number, base))

        # Check nearby exponents (approximation might be off by 1)
        for exp in [approx_exp - 1, approx_exp, approx_exp + 1]:
            if exp >= 2 and base ** exp == number:
                return (base, exp)

    return None

