# Oracle database connection and DDL execution script

import cx_Oracle
import sys

def establish_db_connection(user, passwd, conn_str):
    try:
        connection = cx_Oracle.connect(user, passwd, conn_str)
        print("Successfully connected to Oracle database")
        return connection
    except cx_Oracle.DatabaseError as err:
        error_obj, = err.args
        if error_obj.code == 1017:
            print('Invalid username or password.')
        else:
            print(f'Connection failed: {error_obj.message}')
        sys.exit(1)  # Exit program on connection failure

def run_ddl_commands(connection, ddl_text):
    cursor = connection.cursor()
    try:
        cursor.execute(ddl_text)
    except cx_Oracle.DatabaseError as err:
        error_obj, = err.args
        if error_obj.code == 955:
            print('Table already exists')
        elif error_obj.code == 1031:
            print("Privilege issue - ensure you're using the correct schema owner account")
        else:
            print(f"Database operation error [{error_obj.code}]: {error_obj.message}")
        cursor.close()
        connection.rollback()  # Undo changes if an error occurs
        raise  # Propagate exception for higher-level handling
    finally:
        cursor.close()
        connection.commit()

def main():
    user = 'username'
    passwd = 'password'
    conn_str = 'hostname:port/SERVICENAME'
    create_table_sql = 'CREATE TABLE example (id NUMBER PRIMARY KEY, name VARCHAR2(100))'

    db_conn = establish_db_connection(user, passwd, conn_str)
    try:
        run_ddl_commands(db_conn, create_table_sql)
    finally:
        db_conn.close()

