# Custom exception for invalid input values
class InvalidInputException(Exception):
    def __init__(self, value):
        self.value = value
        self.message = f"Invalid argument: {value}. Only positive integers greater than 10 are allowed."
        super().__init__(self.message)

def compute_mean(*values):
    running_sum = 0
    valid_count = 0

    for item in values:
        # Check if the item is an integer and meets the criteria
        if not isinstance(item, int) or item <= 0:
            raise InvalidInputException(item)

        # Only include values greater than 10 in the calculation
        if item > 10:
            running_sum += item
            valid_count += 1

    # Handle case where no valid values were found
    if valid_count == 0:
        return 0

    # Compute and return the mean
    result = running_sum / valid_count
    return result

