def find_best_meal(stock, menu):
    # Normalize stock quantities into a dictionary with integer values
    inventory = {item: int(qty.split()[0]) for item, qty in stock.items()}

    # Variables to track the optimal choice and leftover items
    selected_meal = None
    leftover_items = {}

    for meal_name, needed_ingredients in menu.items():
        feasible = True
        temp_stock = inventory.copy()

        for ingredient, needed_amount in needed_ingredients.items():
            if ingredient not in inventory or inventory[ingredient] < needed_amount:
                feasible = False
                break
            else:
                temp_stock[ingredient] -= needed_amount

        if feasible:
            selected_meal = meal_name
            leftover_items = {k: v for k, v in temp_stock.items() if v > 0}
            break

    return selected_meal, leftover_items

