# Calculate the difference between two dates in years, months, and days

def is_leap_year(year):
    """Determine if a year is a leap year."""
    return (year % 4 == 0) and (year % 100 != 0 or year % 400 == 0)

def get_days_in_month(year, month):
    """Get the number of days in a specific month of a given year."""
    if month == 2:
        return 29 if is_leap_year(year) else 28
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 31

def compute_date_gap(earlier_date, later_date):
    """Compute the time gap between two dates."""
    # Ensure earlier_date is indeed earlier
    if earlier_date > later_date:
        earlier_date, later_date = later_date, earlier_date

    # Initial differences
    diff_years = later_date.year - earlier_date.year
    diff_months = later_date.month - earlier_date.month
    diff_days = later_date.day - earlier_date.day

    # Adjust for negative days by borrowing from previous month
    if diff_days < 0:
        prev_month = later_date.month - 1 if later_date.month > 1 else 12
        days_in_prev_month = get_days_in_month(later_date.year, prev_month)
        diff_days += days_in_prev_month
        diff_months -= 1

    # Adjust for negative months by borrowing from previous year
    if diff_months < 0:
        diff_months += 12
        diff_years -= 1

    return diff_years, diff_months, diff_days

def main():
    # Prompt user for input dates
    first_input = input("Enter the first date (YYYY-MM-DD): ")
    second_input = input("Enter the second date (YYYY-MM-DD): ")

    try:
        from datetime import datetime
        first_date = datetime.strptime(first_input, "%Y-%m-%d")
        second_date = datetime.strptime(second_input, "%Y-%m-%d")
    except ValueError:
        print("Invalid date format. Please use YYYY-MM-DD.")
        return

    # Check for future dates
    current_date = datetime.now()
    if first_date > current_date or second_date > current_date:
        print("One or both dates are in the future.")
    else:
        result = compute_date_gap(first_date, second_date)
        print(f"The age difference is {result[0]} years, {result[1]} months, and {result[2]} days.")

if __name__ == "__main__":
    main()

import os
from concurrent.futures import ProcessPoolExecutor, as_completed

def calculate_directory_size(directory_path):
    size = 0
    try:
        with os.scandir(directory_path) as entries:
            for item in entries:
                try:
                    if item.is_file():
                        size += item.stat().st_size
                    elif item.is_dir():
                        size += calculate_directory_size(item.path)
                except (OSError, PermissionError):
                    continue
    except (OSError, PermissionError):
        pass
    return size

def compute_folder_size(base_path, num_workers=4):
    total_size = 0

    # First, add sizes of files directly in the base directory
    try:
        with os.scandir(base_path) as entries:
            for entry in entries:
                if entry.is_file():
                    try:
                        total_size += entry.stat().st_size
                    except (OSError, PermissionError):
                        continue
    except (OSError, PermissionError):
        pass

    # Collect subdirectories to process in parallel
    subdirs = []
    try:
        for root, dirs, _ in os.walk(base_path, topdown=True):
            for d in dirs:
                subdir_path = os.path.join(root, d)
                subdirs.append(subdir_path)
    except (OSError, PermissionError):
        pass

    # Process subdirectories concurrently using processes instead of threads
    if subdirs:
        with ProcessPoolExecutor(max_workers=num_workers) as pool:
            futures = [pool.submit(calculate_directory_size, path) for path in subdirs]

            for future in as_completed(futures):
                try:
                    total_size += future.result()
                except Exception:
                    continue

    return total_size

if __name__ == "__main__":
    target_directory = "C:\\"
    computed_size = compute_folder_size(target_directory)
    print(f"Total size: {computed_size / 1024 / 1024 / 1024:.2f} GB")

import asyncio
from typing import Type, Callable, Optional
from pydantic import BaseModel
import functools
import orjson
from fastapi.encoders import jsonable_encoder

# Assuming redis_client and settings are defined elsewhere

class ResponseCache:
    def __init__(self, include: list[str] = None, exclude: list[str] = None):
        self.include_list = include or []
        self.exclude_list = exclude or []
        self._locks = {}  # Dictionary to store locks per cache key

    def __call__(self, model: Type[BaseModel] = None, expire: int = settings.REDIS_TIMEOUT,
                 include: list[str] = None, exclude: list[str] = None):
        def decorator(handler: Callable):
            @functools.wraps(handler)
            async def wrapper(*arguments, **keyword_args):
                # Construct the cache key based on function signature
                cache_key = self._build_cache_key(
                    handler,
                    include or self.include_list,
                    exclude or self.exclude_list,
                    *arguments, **keyword_args,
                )

                # Retrieve or create an asyncio lock for this key
                lock = self._locks.setdefault(cache_key, asyncio.Lock())

                async with lock:
                    # Try to fetch cached data
                    cached_data = await redis_client.get_by_key(cache_key)
                    if cached_data:
                        parsed_data = orjson.loads(cached_data)
                        if model:
                            if isinstance(parsed_data, list):
                                return [model.parse_obj(item) for item in parsed_data]
                            else:
                                return model.parse_obj(parsed_data)
                        else:
                            return parsed_data
                    else:
                        # Execute the original function
                        if asyncio.iscoroutinefunction(handler):
                            result = await handler(*arguments, **keyword_args)
                        else:
                            result = handler(*arguments, **keyword_args)

                        # Store the result in Redis
                        cache_entry = redis_client.RedisData(
                            key=cache_key,
                            value=orjson.dumps(jsonable_encoder(result)),
                            ttl=expire
                        )
                        await redis_client.set_redis_key(cache_entry)
                        return result

                # Remove stale lock if no longer needed
                if cache_key in self._locks and not lock.locked():
                    del self._locks[cache_key]

            return wrapper
        return decorator

    def _build_cache_key(self, func: Callable, include: list[str], exclude: list[str], *args, **kwargs) -> str:
        param_dict = {}

        # Map positional arguments by name (if available)
        for idx, arg in enumerate(args):
            param_name = list(func.__code__.co_varnames)[:len(args)][idx] if idx < len(func.__code__.co_varnames) else f"arg{idx}"
            param_dict[param_name] = arg

        # Merge keyword arguments
        for key, value in kwargs.items():
            if key not in param_dict:
                param_dict[key] = value

        # Apply inclusion/exclusion filters
        filtered = {k: v for k, v in param_dict.items() if k not in exclude}
        if include:
            filtered = {k: v for k, v in filtered.items() if k in include}

        # Sort and format parameters into a string
        sorted_items = sorted(filtered.items())
        param_str = "&".join(f"{key}={value}" for key, value in sorted_items)
        return f"{func.__module__}:{func.__name__}:{param_str}"

# Global instance of the cache decorator
response_cache = ResponseCache()

