def clean_html_content(soup):
    """Processes HTML to extract clean, readable text."""
    # Remove non-content elements (scripts, styles)
    for tag in soup(['script', 'style']):
        tag.decompose()

    # Extract and normalize text
    raw_text = soup.get_text(separator='\n')
    lines = [line.strip() for line in raw_text.splitlines()]
    cleaned_lines = []

    for line in lines:
        if line:
            # Split on double spaces and filter empty phrases
            phrases = [phrase.strip() for phrase in line.split('  ') if phrase.strip()]
            cleaned_lines.extend(phrases)

    return '\n'.join(cleaned_lines)

def locate_historical_events(content, markers):
    """Searches for historical events in the text using regex patterns."""
    found_events = {}

    for event_name, expected_date in markers.items():
        # Build regex pattern to find event name followed by date
        pattern = re.compile(
            rf"{re.escape(event_name)}.*?(\d{{4}}\s+BCE)",
            re.IGNORECASE | re.DOTALL
        )

        match = pattern.search(content)
        if match:
            found_events[event_name] = match.group(1).strip()
        else:
            found_events[event_name] = None

    return found_events

