# Analyze CSS file for hexadecimal color codes and validate them

import re
from collections import Counter

def check_hex_format(color_code):
    """Determine if the given string is a properly formatted hex color."""
    # Pattern allows 3 or 6 hex digits after '#'
    pattern = r'^#[0-9A-Fa-f]{3}(?:[0-9A-Fa-f]{3})?$'
    return bool(re.match(pattern, color_code))

def process_css_colors(css_text):
    """Extract and categorize hex color codes from CSS content."""
    # Find all potential hex color candidates
    raw_matches = re.findall(r'#[0-9A-Fa-f]+', css_text)

    categorized = {
        'valid': [],
        'invalid': []
    }

    for candidate in raw_matches:
        if check_hex_format(candidate):
            categorized['valid'].append(candidate)
        else:
            categorized['invalid'].append(candidate)

    # Count occurrences of valid colors
    frequency = Counter(categorized['valid'])

    return frequency, categorized['invalid']

def main(file_path='styles.css'):
    try:
        with open(file_path, 'r') as source_file:
            css_data = source_file.read()

        color_stats, bad_colors = process_css_colors(css_data)

        if color_stats:
            print("Valid Hex Color Frequencies:")
            for color, occurrences in color_stats.most_common():
                print(f"{color}: {occurrences}")
        else:
            print("No valid hex color codes detected.")

        if bad_colors:
            print("\nInvalid Hex Color Codes:")
            for code in bad_colors:
