# Modified parser with equivalent functionality but different implementation approach

import re
from typing import Union, List, Dict, Any

class Token:
    def __init__(self, category: str, content: str):
        self.category = category
        self.content = content

class ExpressionParser:
    def __init__(self, formula: str):
        self.formula = formula
        self.token_sequence = self.lexical_analysis(formula)
        self.position = 0

    def lexical_analysis(self, formula: str) -> List[Token]:
        token_patterns = [
            ('NUMERIC',   r'\d+(\.\d*)?'),       # Numbers (integer or decimal)
            ('VARIABLE',  r'[a-zA-Z_][a-zA-Z_0-9]*'),  # Variable names
            ('SYMBOL',    r'[\+\-\*/=\!\&\|\<\>\~\^]'), # Operators and symbols
            ('QUANTIFIER', r'\b(forall|exists)\b'),     # Quantifiers
            ('BRACKET',   r'[\(\)]'),                  # Parentheses
            ('SPACE',     r'\s+'),                     # Whitespace
            ('ERROR',     r'.'),                       # Invalid characters
        ]
        combined_pattern = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_patterns)
        result_tokens = []

        for match in re.finditer(combined_pattern, formula):
            token_type = match.lastgroup
            token_text = match.group(token_type)

            if token_type == 'SPACE':
                continue
            elif token_type == 'ERROR':
                raise ValueError(f"Unrecognized symbol encountered: '{token_text}'")

            result_tokens.append(Token(token_type, token_text))

        return result_tokens

    def analyze(self) -> Dict[str, Any]:
        return self.process_expression()

    def process_expression(self) -> Dict[str, Any]:
        current = self.token_sequence[self.position]

        if current.category == 'VARIABLE':
            self.position += 1
            return {'kind': 'variable', 'name': current.content}

        elif current.category == 'NUMERIC':
            self.position += 1
            return {'kind': 'number', 'value': float(current.content)}

        elif current.category == 'BRACKET' and current.content == '(':
            self.position += 1

            if self.position >= len(self.token_sequence):
                raise ValueError("Missing closing parenthesis")

            inner_expr = self.process_expression()

            if (self.position < len(self.token_sequence) and 
                self.token_sequence[self.position].category == 'BRACKET' and 
                self.token_sequence[self.position].content == ')'):
                self.position += 1
                return inner_expr
            else:
                raise ValueError("Mismatched parentheses")

        elif current.category == 'SYMBOL':
            self.position += 1

            if self.position >= len(self.token_sequence):
                raise ValueError("Incomplete expression after operator")

            operand_a = self.process_expression()

            if self.position >= len(self.token_sequence):
                raise ValueError("Missing right operand")

            operand_b = self.process_expression()

            return {
                'kind': 'operation',
                'operator': current.content,
                'left': operand_a,
                'right': operand_b
            }

        elif current.category == 'QUANTIFIER':
            self.position += 1

            if self.position >= len(self.token_sequence):
                raise ValueError("Quantifier requires a variable")

            var_expr = self.process_expression()

            if self.position >= len(self.token_sequence):
                raise ValueError("Quantifier requires a sub-expression")

            body_expr = self.process_expression()

            return {
                'kind': 'quantification',
                'type': current.content,
                'variable': var_expr,
                'body': body_expr
            }

        else:
            raise ValueError(f"Unexpected element at position {self.position}: '{current.content}'")

