# Enhanced validation function with adjusted thresholds for height and weight
def validate_physical_parameters(years, centimeters, kilograms):
    # Basic sanity checks
    if years < 0 or centimeters <= 0 or kilograms <= 0:
        return False

    # Age-specific realistic value constraints
    if years < 2:
        if centimeters > 90 or kilograms > 15:
            return False
    elif years < 10:
        if centimeters > 160 or kilograms > 60:
            return False
    elif years < 20:
        if centimeters > 200 or kilograms > 120:
            return False
    elif years < 40:
        if centimeters > 220 or kilograms > 180:
            return False
    elif years < 60:
        if centimeters > 230 or kilograms > 200:
            return False
    elif years < 80:
        if centimeters > 240 or kilograms > 250:
            return False
    else:  # age >= 80
        if centimeters > 230 or kilograms > 230:
            return False

    return True

# Function to create structured XML representation of people data
def build_people_xml(individuals):
    # Root element for the XML document
    root_element = ET.Element("Individuals")

    # Organize individuals by their country of origin
    grouped_by_nation = {}
    for person in individuals:
        gender, stature, iris_color, nation, lifespan, mass = person
        # Skip entries with physically implausible measurements
        if not validate_physical_parameters(lifespan, stature, mass):
            print(f"Warning: Invalid parameters detected for {person}", file=sys.stderr)
            continue

        # Group by nation
        if nation not in grouped_by_nation:
            grouped_by_nation[nation] = []
        grouped_by_nation[nation].append(person)

    # Sort each group by age (descending order)
    for nation, members in grouped_by_nation.items():
        members.sort(key=lambda x: x[4], reverse=True)

    # Build XML hierarchy
    for nation, members in grouped_by_nation.items():
        nation_node = ET.SubElement(root_element, "Nation", name=nation)
        for member in members:
            person_node = ET.SubElement(nation_node, "Citizen")
            ET.SubElement(person_node, "Sex").text = str(member[0])
            ET.SubElement(person_node, "Stature").text = str(member[1])
            ET.SubElement(person_node, "IrisColor").text = str(member[2])
            ET.SubElement(person_node, "Lifespan").text = str(member[4])
            ET.SubElement(person_node, "Mass").text = str(member[5])
            ET.SubElement(person_node, "Timestamp").text = datetime.now().isoformat()

    # Format output with proper indentation
    raw_xml = ET.tostring(root_element)
    parsed_xml = minidom.parseString(raw_xml)
    return parsed_xml.toprettyxml(indent="  ")

