# Country class with diplomatic and economic capabilities

class Nation:
    def __init__(self, title, wealth, force_capacity):
        self.title = title
        self.wealth = wealth
        self.force_capacity = force_capacity
        self.friendly_nations = []
        self.covert_trading_allies = []

    def establish_diplomatic_ties(self, nation):
        if nation not in self.friendly_nations:
            self.friendly_nations.append(nation)
            nation.establish_diplomatic_ties(self)

    def set_up_covert_trade(self, partner):
        if partner not in self.covert_trading_allies:
            self.covert_trading_allies.append(partner)
            partner.set_up_covert_trade(self)

    def reinforce_defense(self, investment):
        if self.wealth >= investment:
            self.force_capacity += investment
            self.wealth -= investment
            print(f"{self.title} has bolstered its defense capability by {investment}.")
        else:
            print(f"{self.title} lacks sufficient wealth to invest {investment} in defense.")

    def covert_exchange(self, ally, transfer_amount):
        if ally in self.covert_trading_allies:
            if self.wealth >= transfer_amount:
                self.wealth -= transfer_amount
                ally.wealth += transfer_amount
                print(f"{self.title} has covertly transferred {transfer_amount} resources to {ally.title}.")
            else:
                print(f"{self.title} does not have enough wealth to conduct this trade.")
        else:
            print(f"{self.title} cannot engage in covert trade with {ally.title} without established partnership.")

    def __str__(self):
        return f"Nation: {self.title}, Wealth: {self.wealth}, Force Capacity: {self.force_capacity}, Friendly Nations: {', '.join([n.title for n in self.friendly_nations])}, Covert Trading Allies: {', '.join([a.title for a in self.covert_trading_allies])}"

# Custom exception for mismatched point dimensions
class DimensionMismatchError(Exception):
    """Raised when trying to combine points of incompatible dimensionality."""
    def __init__(self, msg="Dimension mismatch: points must have equal number of coordinates."):
        self.msg = msg
        super().__init__(self.msg)

class CoordinatePoint:
    def __init__(self, *values):
        self.values = values

    def __add__(self, other_point):
        # Verify both points have same number of coordinates
        if len(self.values) != len(other_point.values):
            raise DimensionMismatchError()

        # Compute element-wise sum using list comprehension
        new_coords = []
        for idx in range(len(self.values)):
            new_coords.append(self.values[idx] + other_point.values[idx])

        return CoordinatePoint(*new_coords)

    def __str__(self):
        coord_str = ', '.join(str(val) for val in self.values)
