import json

def lambda_handler(event, context):
    # Extract numbers from the input
    try:
        # Retrieve values using .get() to avoid KeyError
        num1 = event.get('num1')
        num2 = event.get('num2')

        # Validate that both parameters are present
        if num1 is None or num2 is None:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Missing required parameters'})
            }

        # Perform multiplication
        result = num1 * num2

        # Return the result
        return {
            'statusCode': 200,
            'body': json.dumps({'result': result})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': str(e)})
        }

# Function to count vowels in a given string (case-insensitive)
def tally_vowels(text):
    vowel_chars = "aeiouAEIOU"
    return sum(1 for symbol in text if symbol in vowel_chars)

# Function to analyze multiple sentences for vowel statistics
def analyze_text_blocks(text_list):
    # Handle empty input case
    if not text_list:
        return {
            "vowel_counts_per_sentence": [],
            "sentence_with_highest_vowel_score": None,
            "issue": "No text blocks were provided for analysis"
        }

    highest_count = 0
    leading_sentence = None
    all_counts = []

    for block in text_list:
        # Validate sentence length constraint
        if len(block) > 200:
            return {
                "vowel_counts_per_sentence": [],
                "sentence_with_highest_vowel_score": None,
                "issue": f"Validation failed: Block too long — '{block[:50]}...'"
            }

        current_vowel_total = tally_vowels(block)
        all_counts.append(current_vowel_total)

        # Update maximum if current has more vowels
        if current_vowel_total > highest_count:
            highest_count = current_vowel_total
            leading_sentence = block

    return {
        "vowel_counts_per_sentence": all_counts,
        "sentence_with_highest_vowel_score": leading_sentence,
        "issue": None
    }

