# Determine if nested structures are empty and count empty containers

def check_empty_containers(container, seen=None):
    if seen is None:
        seen = set()

    # Avoid infinite recursion for circular references
    container_id = id(container)
    if container_id in seen:
        return True, 0

    seen.add(container_id)

    # Check if the current item is a container type
    if not isinstance(container, (dict, list, tuple, set)):
        return False, 0  # Not a container type

    # Handle empty dictionary case
    if isinstance(container, dict) and len(container) == 0:
        return True, 1

    # Track whether all sub-elements are empty and count empty containers
    all_empty = True
    total_empty_count = 0

    # Process based on container type
    if isinstance(container, dict):
        for value in container.values():
            is_empty, count = check_empty_containers(value, seen)
            total_empty_count += count
            if not is_empty:
                all_empty = False
    else:  # list, tuple, or set
        for item in container:
            is_empty, count = check_empty_containers(item, seen)
            total_empty_count += count
            if not is_empty:
                all_empty = False

    return all_empty, total_empty_count

