import phonenumbers
from phonenumbers import carrier, geocoder, timezone
from django.core.exceptions import ValidationError
from django.db import models

class CustomPhoneNumberField(models.CharField):
    def __init__(self, *args, **kwargs):
        # Set a reasonable max length for phone numbers
        kwargs.setdefault('max_length', 20)
        super().__init__(*args, **kwargs)

    def clean(self, value, model_instance):
        # Run base validation first
        value = super().clean(value, model_instance)

        if value:
            try:
                # Parse the phone number without assuming a region
                parsed = phonenumbers.parse(value, None)

                # Validate the parsed number
                if not phonenumbers.is_valid_number(parsed):
                    raise ValidationError("The provided phone number is not valid.")

            except phonenumbers.NumberParseException as error:
                raise ValidationError(f"Phone number parsing failed: {error}")

        return value

    def pre_save(self, model_instance, add):
        # Get the raw value before saving
        raw_value = super().pre_save(model_instance, add)

        if raw_value:
            try:
                # Attempt to parse and format only if valid
                parsed = phonenumbers.parse(raw_value, None)
                if phonenumbers.is_valid_number(parsed):
                    return phonenumbers.format_number(
                        parsed, 
                        phonenumbers.PhoneNumberFormat.E164
                    )
            except phonenumbers.NumberParseException:
                # If parsing fails, return original value unchanged
                pass

        return raw_value

