# Define base animal model with type-specific proxy conversion

from django.db import models

class Animal(models.Model):
    DOG_TYPE = 'dog'
    CAT_TYPE = 'cat'
    ANIMAL_TYPES = [
        (DOG_TYPE, 'Dog'),
        (CAT_TYPE, 'Cat'),
    ]
    kind = models.CharField(max_length=255, choices=ANIMAL_TYPES)

    def to_specific_proxy(self):
        if self.kind == self.DOG_TYPE:
            return Dog.objects.get(id=self.id)
        elif self.kind == self.CAT_TYPE:
            return Cat.objects.get(id=self.id)
        return self

    class Meta:
        abstract = False  # Ensure the model is not abstract

class Dog(Animal):
    def vocalize(self):
        print("Woof!")

    class Meta:
        proxy = True

class Cat(Animal):
    def vocalize(self):
        print("Meow!")

    class Meta:
        proxy = True

# Retrieve all animals from database
all_animals = Animal.objects.all()

# Convert each animal to its specific proxy and invoke appropriate sound method
for pet in all_animals:
    specific_pet = pet.to_specific_proxy()
    specific_pet.vocalize()

import os
import json
import uuid

class StorageManager:
    def __init__(self, config):
        self.storage_root = config.get('storagePath')
        if not self.storage_root:
            raise ValueError("Configuration 'storagePath' is mandatory.")
        os.makedirs(self.storage_root, exist_ok=True)

    def _construct_item_path(self, item_key):
        return os.path.join(self.storage_root, item_key)

    def store_item(self, item_data):
        if 'identifier' not in item_data:
            item_data['identifier'] = str(uuid.uuid4())
        item_key = item_data['identifier']
        item_dir = self._construct_item_path(item_key)
        os.makedirs(item_dir, exist_ok=True)
        data_file = os.path.join(item_dir, 'data.json')
        with open(data_file, 'w') as file:
            json.dump(item_data, file)
        return item_data

    def remove_item(self, item_key):
        item_dir = self._construct_item_path(item_key)
        if os.path.exists(item_dir):
            os.rmdir(item_dir)
        else:
            raise FileNotFoundError(f"Item identified by {item_key} could not be located.")

    def retrieve_by_key(self, item_key):
        item_dir = self._construct_item_path(item_key)
        data_file = os.path.join(item_dir, 'data.json')
        if os.path.exists(data_file):
            with open(data_file, 'r') as file:
                return json.load(file)
        else:
            raise FileNotFoundError(f"Item identified by {item_key} does not exist.")

    def retrieve_multiple(self, item_keys):
        return [self.retrieve_by_key(key) for key in item_keys]

    def list_all_items(self, sorting='ascending'):
        directories = [d for d in os.listdir(self.storage_root) 
                      if os.path.isdir(os.path.join(self.storage_root, d))]
        items_list = [self.retrieve_by_key(d) for d in directories]
        items_list.sort(key=lambda x: x['identifier'], reverse=(sorting == 'descending'))
        return items_list

    def fetch_item(self, item_key):
        try:
            return self.retrieve_by_key(item_key)
        except FileNotFoundError:
            return None

# Example usage:
