# Process HTML string to extract and display tags and content

def process_html(html):
    tag_stack = []
    text_segments = []
    index = 0

    while index < len(html):
        if html[index] == '<':
            # Check for closing tag
            if index + 1 < len(html) and html[index + 1] == '/':
                close_pos = html.find('>', index)
                if close_pos != -1:
                    tag_name = html[index + 2:close_pos].strip()
                    if tag_stack:
                        depth = len(tag_stack) - 1
                        print(f"{'  ' * depth}Closing tag: {tag_name}")
                        tag_stack.pop()
                    index = close_pos
            else:
                # Handle opening tag
                close_pos = html.find('>', index)
                if close_pos != -1:
                    tag_part = html[index + 1:close_pos].strip()
                    parts = tag_part.split()
                    tag_name = parts[0]
                    attrs = {}

                    if len(parts) > 1:
                        for attr in parts[1:]:
                            if '=' in attr:
                                key, val = attr.split('=', 1)
                                attrs[key.strip()] = val.strip('"\'')

                    tag_stack.append(tag_name)
                    depth = len(tag_stack) - 1
                    print(f"{'  ' * depth}Opening tag: {tag_name}")

                    if attrs:
                        print(f"{'  ' * (depth + 1)}Attributes: {attrs}")

                    index = close_pos
        else:
            # Handle text content
            next_tag = html.find('<', index)
            if next_tag == -1:
                next_tag = len(html)

            text = html[index:next_tag].strip()
            if text:
                depth = len(tag_stack) - 1 if tag_stack else 0
                print(f"{'  ' * depth}Text: {text}")
                if tag_stack:
                    text_segments.append((tag_stack[-1], text))

            index = next_tag - 1

        index += 1

