from typing import List
import bisect

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for divisor in range(3, int(n**0.5) + 1, 2):
        if n % divisor == 0:
            return False
    return True

def find_next_prime(start: int) -> int:
    candidate = start + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

def closest_fibonacci(value: int) -> int:
    # Generate Fibonacci sequence up to sufficient limit
    fib_sequence = [0, 1]
    while fib_sequence[-1] < 200:
        fib_sequence.append(fib_sequence[-2] + fib_sequence[-1])

    # Find insertion point using binary search
    position = bisect.bisect_left(fib_sequence, value)

    # Handle edge cases
    if position == 0:
        return fib_sequence[0]
    if position >= len(fib_sequence):
        return fib_sequence[-1]

    # Choose closer Fibonacci number
    prev_fib = fib_sequence[position - 1]
    curr_fib = fib_sequence[position]

    if abs(value - prev_fib) <= abs(curr_fib - value):
        return prev_fib
    else:
        return curr_fib

def switch_character_case(char: str) -> str:
    if char.isalpha():
        if char.islower():
            return char.upper()
        else:
            return char.lower()
    return char

def transform_text(text: str) -> str:
    # Phase 1: Invert letter casing
    case_swapped = ''.join(switch_character_case(ch) for ch in text)

    # Phase 2: Replace odd digits with nearest Fibonacci numbers
    digit_replaced = ''
    for char in case_swapped:
        if char.isdigit() and int(char) % 2 == 1:
            digit_replaced += str(closest_fibonacci(int(char)))
        else:
            digit_replaced += char

    # Phase 3: Expand special characters according to prime rule
    special_chars = [ch for ch in digit_replaced if not ch.isalnum()]
    special_frequency = len(special_chars)
    expansion_factor = find_next_prime(special_frequency)

    expanded_text = ''
    for char in digit_replaced:
        if not char.isalnum():
            expanded_text += char * expansion_factor
        else:
            expanded_text += char

    # Phase 4: Sort characters using BST structure
    class BSTNode:
        def __init__(self, ascii_val):
            self.value = ascii_val
            self.left_child = None
            self.right_child = None

    def add_to_bst(node, ascii_code):
        if node is None:
            return BSTNode(ascii_code)
        if ascii_code < node.value:
            node.left_child = add_to_bst(node.left_child, ascii_code)
        else:
            node.right_child = add_to_bst(node.right_child, ascii_code)
        return node

    def collect_in_order(node):
        if node is None:
            return []
        return collect_in_order(node.left_child) + [node.value] + collect_in_order(node.right_child)

    bst_root = None
    for character in expanded_text:
        bst_root = add_to_bst(bst_root, ord(character))

    sorted_values = collect_in_order(bst_root)
    final_output = ''.join(chr(code) for code in sorted_values)

    return final_output

# Example usage
print(transform_text('Greet5!'))

