from playwright.sync_api import sync_playwright

def modify_canvas_behavior():
    return """
    {
      // Store the original toDataURL method
      const originalToDataURL = HTMLCanvasElement.prototype.toDataURL;

      // Override the toDataURL method to alter canvas content
      HTMLCanvasElement.prototype.toDataURL = function(type) {
        const width = this.width;
        const height = this.height;

        // Get 2D context for manipulation
        const ctx = this.getContext('2d');
        const imageData = ctx.getImageData(0, 0, width, height);

        // Apply XOR operation on each pixel's red channel
        for (let y = 0; y < height; y++) {
          for (let x = 0; x < width; x++) {
            const pos = (y * width + x) * 4;
            if (pos < imageData.data.length) {
              imageData.data[pos] ^= 1;
            }
          }
        }

        // Put modified data back and return original result
        ctx.putImageData(imageData, 0, 0);
        return originalToDataURL.call(this, type);
      };
    }
    """

def update_fingerprint(page):
    # Navigate to the test page first
    with page.expect_navigation():
        page.goto("https://browserleaks.com/canvas#p1")
        page.wait_for_load_state("networkidle")

    # Inject our script to override canvas behavior
    injected_script = page.add_script_tag(content=modify_canvas_behavior())

    # Reload the page to apply changes
    page.reload()
    page.wait_for_load_state("networkidle")

    # Clean up the injected script
    injected_script.dispose()

