import random

def get_user_input(player_name, low_limit, high_limit):
    while True:
        try:
            attempt = int(input(f"{player_name}, pick a number from {low_limit} to {high_limit}: "))
            if low_limit <= attempt <= high_limit:
                return attempt
            else:
                print(f"Enter a value within the range {low_limit} to {high_limit}.")
        except ValueError:
            print("Provide a numeric input.")

def start_match():
    lower_bound = 1
    upper_bound = 100
    max_attempts = 10

    target_value = random.randint(lower_bound, upper_bound)
    player_a = input("Enter Player A's name: ")
    player_b = input("Enter Player B's name: ")

    attempts_a = 0
    attempts_b = 0

    while attempts_a < max_attempts and attempts_b < max_attempts:
        # Player A's round
        if attempts_a < max_attempts:
            choice = get_user_input(player_a, lower_bound, upper_bound)
            attempts_a += 1
            if choice == target_value:
                print(f"{player_a} triumphs! The hidden number was {target_value}.")
                return
            else:
                print(f"Incorrect, {player_a}. Remaining tries: {max_attempts - attempts_a}")

        # Player B's round
        if attempts_b < max_attempts:
