            attempts_b += 1
            if choice == target_value:
                print(f"{player_b} triumphs! The hidden number was {target_value}.")
                return
            else:
                print(f"Incorrect, {player_b}. Remaining tries: {max_attempts - attempts_b}")

    print(f"No winner this time. The number was {target_value}.")

if __name__ == "__main__":
    start_match()

from abc import ABC, abstractmethod

class GeometryFigure(ABC):
    def __init__(self, dim1, dim2, figure_name):
        self.dimension1 = dim1
        self.dimension2 = dim2
        self._figure_name = figure_name

    @abstractmethod
    def computeSurfaceArea(self) -> float:
        pass

    def displaySurfaceArea(self):
        surface_area = self.computeSurfaceArea()
        print(f"The surface area of the {self._figure_name} is {surface_area:.2f}")

    def calculateBoundaryLength(self) -> float:
        return 2 * (self.dimension1 + self.dimension2)

    @staticmethod
    def evaluateAreaDifference(fig1, fig2) -> float:
        return abs(fig1.computeSurfaceArea() - fig2.computeSurfaceArea())

    def revealName(self):
        print(f"This geometric figure is a {self._figure_name}")

# Derived classes of GeometryFigure
class Quadrilateral(GeometryFigure):
    def __init__(self, length, breadth):
        super().__init__(length, breadth, "Quadrilateral")

    def computeSurfaceArea(self) -> float:
        return self.dimension1 * self.dimension2

class Ellipse(GeometryFigure):
    def __init__(self, semi_major_axis):
        super().__init__(semi_major_axis, 0, "Ellipse")  # dimension2 unused for ellipse
        self.semi_major_axis = semi_major_axis

    def computeSurfaceArea(self) -> float:
        return 3.14159 * self.semi_major_axis * self.semi_major_axis

    def calculateBoundaryLength(self) -> float:
        return 2 * 3.14159 * self.semi_major_axis

class Polygon(GeometryFigure):
    def __init__(self, base_edge, altitude):
        super().__init__(base_edge, altitude, "Polygon")

    def computeSurfaceArea(self) -> float:
        return 0.5 * self.dimension1 * self.dimension2

# Demonstration usage
if __name__ == "__main__":
    quad = Quadrilateral(4, 5)
    quad.revealName()
    quad.displaySurfaceArea()
    print(f"The boundary length of the {quad._figure_name} is {quad.calculateBoundaryLength():.2f}")

    ell = Ellipse(3)
    ell.revealName()
    ell.displaySurfaceArea()
    print(f"The boundary length of the {ell._figure_name} is {ell.calculateBoundaryLength():.2f}")

    poly = Polygon(3, 4)
    poly.revealName()
    poly.displaySurfaceArea()
    print(f"The boundary length of the {poly._figure_name} is {poly.calculateBoundaryLength():.2f}")

    area_gap = GeometryFigure.evaluateAreaDifference(quad, ell)
    print(f"The absolute difference in surface area between the {quad._figure_name} and the {ell._figure_name} is {area_gap:.2f}")

# A phone directory system that organizes contacts by geographic hierarchy

class ContactManager:
    def __init__(self):
        self.contacts = {}

    def register_contact(self, full_name, contact_number, region, province, urban_area):
        if region not in self.contacts:
            self.contacts[region] = {}
        if province not in self.contacts[region]:
            self.contacts[region][province] = {}
        if urban_area not in self.contacts[region][province]:
            self.contacts[region][province][urban_area] = []

        self.contacts[region][province][urban_area].append({
            'full_name': full_name,
            'contact_number': contact_number
        })

    def delete_contact(self, full_name, contact_number, region, province, urban_area):
        if region in self.contacts and province in self.contacts[region] and urban_area in self.contacts[region][province]:
            records = self.contacts[region][province][urban_area]
            for record in records:
                if record['full_name'] == full_name and record['contact_number'] == contact_number:
                    records.remove(record)
                    return True
        return False

    def find_contact(self, full_name=None, contact_number=None, region=None, province=None, urban_area=None):
        matches = []

        def traverse_hierarchy(current_data, location_path):
            if not isinstance(current_data, dict):
                return

            for label, data in current_data.items():
                updated_path = location_path + [label]
                if len(updated_path) == 3:  # Region, Province, Urban Area
                    for record in data:
                        if (full_name is None or record['full_name'] == full_name) and \
                           (contact_number is None or record['contact_number'] == contact_number):
                            matches.append({
                                'full_name': record['full_name'],
                                'contact_number': record['contact_number'],
                                'region': updated_path[0],
                                'province': updated_path[1],
                                'urban_area': updated_path[2]
                            })
                else:
                    traverse_hierarchy(data, updated_path)

        traverse_hierarchy(self.contacts, [])
        return matches

    def show_all_contacts(self):
        def print_hierarchy(current_data, spacing=0):
            if not isinstance(current_data, dict):
                return

            for label, data in current_data.items():
                print(' ' * spacing + label)
                if isinstance(data, list):
                    for record in data:
                        print(' ' * (spacing + 4) + f"{record['full_name']}: {record['contact_number']}")
                else:
                    print_hierarchy(data, spacing + 4)

        print_hierarchy(self.contacts)

