            logger.info(f"Challenge accepted: {game_id}")
            return game_id
        else:
            logger.error(f"Acceptance failed: {response.status_code} - {response.text}")
            return None

    except requests.exceptions.RequestException as exc:
        logger.error(f"Network issue during acceptance: {exc}")
        return None

def reject_challenge(challenge_identifier):
