# Type III Clone: Refactored user data management with alternative logic

class PersonProfile:
    def __init__(self, full_name, years_old, location, profession, reading_list):
        self.full_name = full_name
        self.years_old = years_old
        self.location = location
        self.profession = profession
        self.reading_list = set(reading_list)  # Using set to prevent duplicate entries

    def __str__(self):
        return (f"PersonProfile(full_name='{self.full_name}', years_old={self.years_old}, "
                f"location='{self.location}', profession='{self.profession}', "
                f"reading_list={self.reading_list})")

class ProfileManager:
    def __init__(self):
        self.profiles = {}  # Primary storage for person profiles
        self.location_index = {}  # Index for quick location-based searches
        self.genre_index = {}     # Index for quick book-based searches

    def register_profile(self, profile):
        if profile.full_name in self.profiles:
            raise ValueError(f"Profile already exists for {profile.full_name}")

        self.profiles[profile.full_name] = profile
        self._reindex_location(profile, 'insert')
        self._reindex_genre(profile, 'insert')

    def modify_profile(self, profile):
        if profile.full_name not in self.profiles:
            raise ValueError(f"No profile found for {profile.full_name}")

        previous_profile = self.profiles[profile.full_name]
        self.profiles[profile.full_name] = profile
        self._reindex_location(previous_profile, 'remove')
        self._reindex_genre(previous_profile, 'remove')
        self._reindex_location(profile, 'insert')
        self._reindex_genre(profile, 'insert')

    def remove_profile(self, name):
        if name not in self.profiles:
            raise ValueError(f"No profile found for {name}")

        profile = self.profiles.pop(name)
        self._reindex_location(profile, 'remove')
        self._reindex_genre(profile, 'remove')

    def find_by_location(self, location):
        return [self.profiles[name] for name in self.location_index.get(location, set())]

    def find_by_book(self, title):
        return [self.profiles[name] for name in self.genre_index.get(title, set())]

    def _reindex_location(self, profile, operation):
        if operation == 'insert':
            if profile.location not in self.location_index:
                self.location_index[profile.location] = set()
            self.location_index[profile.location].add(profile.full_name)
        elif operation == 'remove':
            if profile.location in self.location_index:
                self.location_index[profile.location].discard(profile.full_name)
                if len(self.location_index[profile.location]) == 0:
                    del self.location_index[profile.location]

    def _reindex_genre(self, profile, operation):
        for title in profile.reading_list:
            if operation == 'insert':
                if title not in self.genre_index:
                    self.genre_index[title] = set()
                self.genre_index[title].add(profile.full_name)
            elif operation == 'remove':
                if title in self.genre_index:
                    self.genre_index[title].discard(profile.full_name)
                    if len(self.genre_index[title]) == 0:
                        del self.genre_index[title]

