# Calculate factorial with recursive trace and time measurement

import time

def compute_factorial(value, level=""):
    # Handle base cases: 0! = 1 and 1! = 1
    if value == 0 or value == 1:
        print(f"{level}factorial({value}) = 1 (Base case)")
        return 1

    # Recursive computation: n! = n * (n-1)!
    else:
        print(f"{level}factorial({value}) = {value} * factorial({value-1})")
        sub_result = compute_factorial(value - 1, level + "  ")
        final_result = value * sub_result
        print(f"{level}factorial({value}) returns {final_result}")
        return final_result

def measure_execution(n):
    start = time.time()
    answer = compute_factorial(n)
    finish = time.time()
    duration = finish - start

    print(f"\nFactorial of {n} equals {answer}")
    print(f"Execution time: {duration:.6f} seconds")
    print(f"Time complexity: O(n) (linear in the input value)")

def main():
    try:
        number = int(input("Enter a non-negative integer: "))
        if number < 0:
            print("Factorial is undefined for negative values.")
        else:
            measure_execution(number)
    except ValueError:
        print("Invalid input. Please enter a valid non-negative integer.")

if __name__ == "__main__":
    main()

# Parse SQL to extract selected fields and source tables

import sqlparse

def retrieve_selected_fields_and_sources(sql_text):
    parsed_queries = sqlparse.parse(sql_text)
    query_statement = parsed_queries[0]

    selected_fields = []
    source_tables = []

    # Identify selected columns (fields) in the SELECT part
    for token in query_statement.tokens:
        if isinstance(token, sqlparse.sql.IdentifierList):
            for item in token.get_identifiers():
                field_value = str(item)
                if '.' in field_value:
                    selected_fields.append(field_value)
        elif isinstance(token, sqlparse.sql.Identifier):
            field_value = str(token)
            if '.' in field_value:
                selected_fields.append(field_value)

    # Locate tables listed after FROM keyword
    found_from = False
    for token in query_statement.tokens:
        if isinstance(token, sqlparse.sql.Token):
            if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'FROM':
                found_from = True
                continue
        if found_from:
            if isinstance(token, sqlparse.sql.IdentifierList):
                for item in token.get_identifiers():
                    table_name = str(item)
                    source_tables.append(table_name)
                found_from = False
            elif isinstance(token, sqlparse.sql.Identifier):
                table_name = str(token)
                source_tables.append(table_name)
                found_from = False

    return selected_fields, source_tables

# Sample SQL input
sql_input = """
select TABLE1.Id, TABLE2.Name, TABLE3.Observations, TABLE3.Address, --and more 70 fields
from TABLE1, TABLE2, TABLE3, TABLE4
"""

selected_fields, source_tables = retrieve_selected_fields_and_sources(sql_input)
print("Selected Fields:", selected_fields)
print("Source Tables:", source_tables)

# Implementation of a Binary Search Tree with standard operations

from typing import List, Optional, Tuple

class Node:
    def __init__(self, data: int):
        self.data = data
        self.left_child: Optional['Node'] = None
        self.right_child: Optional['Node'] = None

class BST:
    def __init__(self):
        self.head: Optional[Node] = None

    def insert(self, value: int) -> None:
        if self.head is None:
            self.head = Node(value)
        else:
            self._insert_recursive(self.head, value)

    def _insert_recursive(self, current: Node, value: int) -> None:
        if value < current.data:
            if current.left_child is None:
                current.left_child = Node(value)
            else:
                self._insert_recursive(current.left_child, value)
        else:
            if current.right_child is None:
                current.right_child = Node(value)
            else:
                self._insert_recursive(current.right_child, value)

    def delete(self, target: int) -> bool:
        self.head, found = self._delete_node(self.head, target)
        return found

    def _delete_node(self, node: Optional[Node], target: int) -> Tuple[Optional[Node], bool]:
        if node is None:
            return None, False

        if target < node.data:
            node.left_child, deleted = self._delete_node(node.left_child, target)
            return node, deleted
        elif target > node.data:
            node.right_child, deleted = self._delete_node(node.right_child, target)
            return node, deleted
        else:
            # Node to delete found
            if node.left_child is None and node.right_child is None:
                return None, True
            elif node.left_child is None:
                return node.right_child, True
            elif node.right_child is None:
                return node.left_child, True
            else:
                # Find in-order successor (minimum in right subtree)
                successor = self._find_minimum(node.right_child)
                node.data = successor.data
                node.right_child, _ = self._delete_node(node.right_child, successor.data)
                return node, True

    def _find_minimum(self, start: Node) -> Node:
        while start.left_child is not None:
            start = start.left_child
        return start

    def contains(self, key: int) -> bool:
        return self._search_tree(self.head, key)

    def _search_tree(self, current: Optional[Node], key: int) -> bool:
        if current is None:
            return False
        if key < current.data:
            return self._search_tree(current.left_child, key)
        elif key > current.data:
            return self._search_tree(current.right_child, key)
        else:
            return True

    def in_order(self) -> List[int]:
        result = []
        self._in_order_traversal(self.head, result)
        return result

    def _in_order_traversal(self, node: Optional[Node], values: List[int]) -> None:
        if node is not None:
            self._in_order_traversal(node.left_child, values)
            values.append(node.data)
            self._in_order_traversal(node.right_child, values)

    def pre_order(self) -> List[int]:
        result = []
        self._pre_order_traversal(self.head, result)
        return result

    def _pre_order_traversal(self, node: Optional[Node], values: List[int]) -> None:
        if node is not None:
            values.append(node.data)
            self._pre_order_traversal(node.left_child, values)
            self._pre_order_traversal(node.right_child, values)

    def post_order(self) -> List[int]:
        result = []
        self._post_order_traversal(self.head, result)
        return result

    def _post_order_traversal(self, node: Optional[Node], values: List[int]) -> None:
        if node is not None:
            self._post_order_traversal(node.left_child, values)
            self._post_order_traversal(node.right_child, values)
            values.append(node.data)

    def level_order(self) -> List[int]:
        if not self.head:
            return []
        output = []
        queue = [self.head]
        while queue:
            current_node = queue.pop(0)
            output.append(current_node.data)
            if current_node.left_child:
                queue.append(current_node.left_child)
            if current_node.right_child:
                queue.append(current_node.right_child)
        return output

# Redefine rectangle functionality with alternative implementation approach

class RectangularShape:
    def __init__(self, h, w):
        self._validate_dimension(h, "height")
        self._validate_dimension(w, "width")
        self.height = h
        self.width = w

    def _validate_dimension(self, value, name):
        if not isinstance(value, (int, float)):
            raise ValueError(f"{name.capitalize()} must be a numeric value.")
        if value <= 0:
            raise ValueError(f"{name.capitalize()} must be greater than zero.")

    def update_height(self, new_h):
        self._validate_dimension(new_h, "height")
        self.height = new_h

    def update_width(self, new_w):
        self._validate_dimension(new_w, "width")
        self.width = new_w

    def retrieve_height(self):
        return self.height

    def retrieve_width(self):
        return self.width

    def compute_surface_area(self):
        try:
            return self.height * self.width
        except Exception as exc:
            raise RuntimeError("Failed to compute surface area due to internal error.") from exc

    def compute_boundary_length(self):
        try:
            return 2 * (self.height + self.width)
        except Exception as exc:
            raise RuntimeError("Failed to compute boundary length due to internal error.") from exc

    def matches_surface_area(self, candidate):
        if not isinstance(candidate, RectangularShape):
            raise TypeError("Candidate object must be an instance of RectangularShape.")
        return self.compute_surface_area() == candidate.compute_surface_area()


