import json
import csv
from typing import List, Dict, Any

def process_employee_record(record: Dict[str, Any]) -> Dict[str, Any]:
    """
    Process and sanitize employee data by filling missing fields and converting types.
    """
    defaults = {
        "Name": "",
        "Age": 0,
        "Salary": 0.0,
        "Department": ""
    }

    processed = {}
    for field in defaults.keys():
        value = record.get(field)

        if value is None or field not in record:
            processed[field] = defaults[field]
        elif field == "Age":
            if isinstance(value, int):
                processed[field] = value
            else:
                try:
                    processed[field] = int(value)
                except (ValueError, TypeError):
                    processed[field] = defaults[field]
        elif field == "Salary":
            if isinstance(value, (int, float)):
                processed[field] = float(value)
            else:
                try:
                    processed[field] = float(value)
                except (ValueError, TypeError):
                    processed[field] = defaults[field]
        else:
            processed[field] = value if value is not None else defaults[field]

    return processed

def order_employees(data: List[Dict]) -> List[Dict]:
    """
    Order employees first by Age (ascending), then by Salary (ascending).
    """
    return sorted(data, key=lambda item: (item["Age"], item["Salary"]))

def transform_json_to_csv(json_input: str, output_path: str) -> None:
    """
    Transform JSON employee data into a sorted CSV file with proper validation.
    """
    try:
        # Parse JSON input
        raw_data = json.loads(json_input)

        # Validate structure
        if not isinstance(raw_data, list):
            raise ValueError("JSON must contain a list of employee records")
        if not all(isinstance(item, dict) for item in raw_data):
            raise ValueError("Each item in the JSON list must be an object/dictionary")

        # Process each employee record
        cleaned_data = [process_employee_record(emp) for emp in raw_data]

        # Sort the employee records
        ordered_data = order_employees(cleaned_data)

        # Write to CSV
        with open(output_path, 'w', newline='') as csv_file:
            headers = ["Name", "Age", "Salary", "Department"]
            writer = csv.DictWriter(csv_file, fieldnames=headers)
            writer.writeheader()
            writer.writerows(ordered_data)

    except json.JSONDecodeError as decode_err:
        print(f"JSON parsing error: {decode_err}")
    except Exception as general_err:
        print(f"Processing error: {general_err}")

