# Validate and process binomial tree structure

def validate_tree_structure(node):
    if node is None:
        return True
    if not isinstance(node, dict) or 'data' not in node:
        return False
    left_valid = True
    right_valid = True

    if 'left' in node:
        left_valid = validate_tree_structure(node['left'])
    if 'right' in node:
        right_valid = validate_tree_structure(node['right'])

    return left_valid and right_valid

def analyze_terminal_nodes(node):
    if not validate_tree_structure(node):
        raise ValueError("Invalid binomial tree")

    def explore_subtree(current_node):
        if current_node is None:
            return 0, 0, float('inf'), float('-inf')

        # Check if current node is a leaf (terminal node)
        has_left = 'left' in current_node
        has_right = 'right' in current_node

        if not has_left and not has_right:
            value = current_node['data']
            return 1, value, value, value

        # Process children recursively
        left_stats = explore_subtree(current_node.get('left'))
        right_stats = explore_subtree(current_node.get('right'))

        left_count, left_sum, left_min, left_max = left_stats
        right_count, right_sum, right_min, right_max = right_stats

        combined_count = left_count + right_count
        combined_sum = left_sum + right_sum
        combined_min = min(left_min, right_min)
        combined_max = max(left_max, right_max)

        return combined_count, combined_sum, combined_min, combined_max

    # Get statistics from the tree traversal
    terminal_count, total_value, smallest_value, largest_value = explore_subtree(node)

    avg_value = total_value / terminal_count if terminal_count > 0 else 0

    return {
        "count": terminal_count,
        "sum": total_value,
        "average": avg_value,
        "min_value": smallest_value,
        "max_value": largest_value
    }

