# Import necessary modules for HTTP requests
import requests

# Define the API endpoint configuration
API_ENDPOINT = "http://api.example.com"

def perform_operation(op_type, operand1, operand2):
    """Execute an arithmetic operation via API call."""
    data = {"a": operand1, "b": operand2}
    api_url = f"{API_ENDPOINT}/{op_type}"

    try:
        response = requests.post(api_url, json=data)
        response.raise_for_status()  # Ensure HTTP errors are caught

        json_data = response.json()
        return json_data['result']
    except requests.exceptions.RequestException as error:
        print(f"Connection issue: {error}")
        return None
    except (KeyError, ValueError) as error:
        print(f"Server response problem: {error}")
        return None

def compute_postfix_notation(expr):
    """Process a postfix expression by delegating operations to the API."""
    storage = []
    parts = expr.split()

    for part in parts:
        if part.isdigit():
            storage.append(int(part))
        else:
            if len(storage) < 2:
                print("Issue: Insufficient operands for computation.")
                return None

            second_val = storage.pop()
            first_val = storage.pop()

            if part == '+':
                outcome = perform_operation('add', first_val, second_val)
            elif part == '-':
                outcome = perform_operation('subtract', first_val, second_val)
            elif part == '*':
                outcome = perform_operation('multiply', first_val, second_val)
            elif part == '/':
                if second_val == 0:
                    print("Issue: Division by zero is not allowed.")
                    return None
                outcome = perform_operation('divide', first_val, second_val)
            else:
                print(f"Issue: Operator '{part}' is not recognized.")
                return None

            if outcome is None:
                return None

            storage.append(outcome)

    if len(storage) != 1:
        print("Issue: Expression format is incorrect.")
        return None

    return storage[0]

