# Weather data collection and analysis system using OpenWeatherMap API

import requests
from datetime import datetime, timedelta
from flask import Flask, request, jsonify
from sqlalchemy import create_engine, Column, Integer, String, Float, DateTime
from sqlalchemy.orm import declarative_base, sessionmaker
from sqlalchemy.exc import SQLAlchemyError

app = Flask(__name__)

# Configuration
API_KEY = 'REDACTED_CREDENTIAL'
DB_PATH = 'sqlite:///weather.db'

# Database setup
engine = create_engine(DB_PATH)
Base = declarative_base()

class WeatherRecord(Base):
    __tablename__ = 'weather_records'
    record_id = Column(Integer, primary_key=True)
    location = Column(String, nullable=False)
    recorded_at = Column(DateTime, nullable=False)
    temp_celsius = Column(Float, nullable=False)
    precipitation_mm = Column(Float, nullable=False)

Base.metadata.create_all(engine)
SessionLocal = sessionmaker(bind=engine)

class WeatherService:
    def __init__(self, key):
        self.key = key
        self.endpoint = 'http://api.openweathermap.org/data/2.5/'

    def fetch_current_conditions(self, city_name):
        api_url = f"{self.endpoint}weather?q={city_name}&appid={self.key}&units=metric"
        result = requests.get(api_url)
        if result.status_code == 200:
            info = result.json()
            return {
                'temp': info['main']['temp'],
                'precip': info.get('rain', {}).get('1h', 0.0)
            }
        elif result.status_code == 404:
            raise ValueError("City not found")
        else:
            raise RuntimeError(f"Request failed with status {result.status_code}")

    def fetch_past_weather(self, coordinates, start_time):
        api_url = f"{self.endpoint}onecall/timemachine?lat={coordinates['lat']}&lon={coordinates['lon']}&dt={start_time}&appid={self.key}&units=metric"
        response = requests.get(api_url)
        if response.status_code == 200:
            return response.json()['hourly']
        else:
            raise RuntimeError(f"Request failed with status {response.status_code}")

    def process_historical_data(self, city_name, period_days=30):
        current_info = self.fetch_current_conditions(city_name)
        db_session = SessionLocal()
        try:
            # Check cache first
            existing_entries = db_session.query(WeatherRecord).filter_by(location=city_name).all()
            if existing_entries:
                return self._compute_statistics(existing_entries)
            else:
                # Fetch and store new data
                end_timestamp = int(datetime.now().timestamp())
                start_timestamp = int((datetime.now() - timedelta(days=period_days)).timestamp())
                historical_records = self.fetch_past_weather({'lat': 0, 'lon': 0}, start_timestamp)  # Placeholder coordinates

                for item in historical_records:
                    db_session.add(WeatherRecord(
                        location=city_name,
                        recorded_at=datetime.fromtimestamp(item['dt']),
                        temp_celsius=item['temp'],
                        precipitation_mm=item.get('rain', {}).get('1h', 0.0)
                    ))
                db_session.commit()

                # Re-fetch after storing to ensure consistency
                updated_entries = db_session.query(WeatherRecord).filter_by(location=city_name).all()
                return self._compute_statistics(updated_entries)
        except Exception as error:
            db_session.rollback()
            raise error
        finally:
            db_session.close()

    def _compute_statistics(self, records):
        temp_sum = 0.0
        precip_sum = 0.0
        count = len(records)

        for record in records:
            temp_sum += record.temp_celsius
            precip_sum += record.precipitation_mm

        return {
            'avg_temp': temp_sum / count,
            'avg_precip': precip_sum / count
        }

weather_service = WeatherService(API_KEY)

@app.route('/weather-info', methods=['GET'])
def weather_endpoint():
    city_param = request.args.get('city')
    if not city_param:
        return jsonify({"error": "City parameter is required"}), 400

    try:
        current = weather_service.fetch_current_conditions(city_param)
        historical = weather_service.process_historical_data(city_param)
        return jsonify({
            'current': current,
            'historical': historical
        })
    except ValueError as ve:
        return jsonify({"error": str(ve)}), 404
    except Exception as e:
        return jsonify({"error": str(e)}), 500

