                "author_id": author_key,
                "headline": record['title'],
                "body": record['content'],
                "publish_date": record['created_at']
            }
            # Ensure author exists in users section if not already present
            if author_key not in organized_structure['individuals']:
                organized_structure['individuals'][author_key] = {
                    "full_name": record['user_name'],
                    "contact": record['user_email'],
                    "registration_date": record['user_created_at']
