class PersonalLog:
    def __init__(self):
        self.records = []

    def log_event(self, day, heading, content, feeling, conditions, place):
        # Check for duplicates using a different approach
        found = False
        for item in self.records:
            if item['day'] == day and item['heading'] == heading:
                found = True
                break

        if found:
            raise ValueError("Duplicate entry: an event with the same date and title already exists.")

        self.records.append({
            'day': day,
            'heading': heading,
            'content': content,
            'feeling': feeling,
            'conditions': conditions,
            'place': place
        })

    def remove_event(self, day, heading):
        # Use filter instead of list comprehension
        self.records = list(filter(
            lambda record: not (record['day'] == day and record['heading'] == heading),
            self.records
        ))

    def update_event(self, day, heading, new_content=None, new_feeling=None, 
                     new_conditions=None, new_place=None):
        # Iterate through records to find and update
        for record in self.records:
            if record['day'] == day and record['heading'] == heading:
                if new_content is not None:
                    record['content'] = new_content
                if new_feeling is not None:
                    record['feeling'] = new_feeling
                if new_conditions is not None:
                    record['conditions'] = new_conditions
                if new_place is not None:
                    record['place'] = new_place
                return  # Exit after first match

    def get_events_in_range(self, from_date, to_date):
        # Using filter and lambda for retrieval
        return list(filter(
            lambda record: from_date <= record['day'] <= to_date,
            self.records
        ))

