from collections import defaultdict, deque
from functools import lru_cache

def minNumberOfSemesters(n, relations, k):
    # Build adjacency list and in-degree count
    prereq = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for a, b in relations:
        prereq[b].append(a)  # b requires a as prerequisite
        in_degree[b] += 1

    # Cycle detection using Kahn's algorithm
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    processed = 0
    while queue:
        course = queue.popleft()
        processed += 1
        for dependent in range(1, n + 1):
            if course in prereq[dependent]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    queue.append(dependent)

    if processed < n:
        return -1  # Cycle detected

    # DP with memoization using bitmask
    @lru_cache(maxsize=None)
    def solve(available_mask):
        if available_mask == 0:
            return 0

        # Get current available courses (no pending prerequisites)
        available_courses = []
        for i in range(1, n + 1):
            if available_mask & (1 << (i - 1)):
                has_prereq = False
                for pre in prereq[i]:
                    if not (available_mask & (1 << (pre - 1))):
                        has_prereq = True
                        break
                if not has_prereq:
                    available_courses.append(i)

        # If no courses available, return infinity (shouldn't happen in valid case)
        if not available_courses:
            return float('inf')

        min_semesters = float('inf')

        # Try all possible combinations of up to k available courses
        from itertools import combinations
        for r in range(1, min(k, len(available_courses)) + 1):
            for combo in combinations(available_courses, r):
                # Calculate new mask after taking these courses
                new_mask = available_mask
                for course in combo:
                    new_mask &= ~(1 << (course - 1))

                # Recursively solve remaining courses
                result = 1 + solve(new_mask)
                min_semesters = min(min_semesters, result)

        return min_semesters

    full_mask = (1 << n) - 1
    return solve(full_mask)

# Example usage
print(minNumberOfSemesters(4, [[1, 2], [2, 3], [3, 4]], 2))  # Output: 2
print(minNumberOfSemesters(4, [[1, 2], [2, 3], [3, 4]], 1))  # Output: 4
print(minNumberOfSemesters(3, [[1, 2], [2, 3], [3, 1]], 2))  # Output: -1

