# Determine the type of progression and its defining parameter

def check_linear_progression(values):
    if len(values) < 2:
        return False, None
    step = values[1] - values[0]
    for idx in range(2, len(values)):
        if values[idx] - values[idx - 1] != step:
            return False, None
    return True, step

def check_exponential_progression(values):
    if len(values) < 2 or any(val == 0 for val in values):
        return False, None
    factor = values[1] / values[0]
    for idx in range(2, len(values)):
        if values[idx - 1] == 0 or values[idx] / values[idx - 1] != factor:
            return False, None
    return True, factor

def classify_sequence(values):
    linear, diff = check_linear_progression(values)
    exponential, ratio = check_exponential_progression(values)

    if linear:
        return "Arithmetic", diff
    elif exponential:
        return "Geometric", ratio
    else:
        return "Neither", None

