# Define a node class for linked list structure
class ListNode:
    def __init__(self, value):
        self.value = value
        self.pointer = None

class SinglyLinkedList:
    def __init__(self):
        self.start = None

    def add_to_end(self, value):
        new_node = ListNode(value)
        if self.start is None:
            self.start = new_node
        else:
            current_node = self.start
            while current_node.pointer:
                current_node = current_node.pointer
            current_node.pointer = new_node

    def show_list(self):
        current_node = self.start
        while current_node:
            print(current_node.value, end=" -> ")
            current_node = current_node.pointer
        print("None")

    def add_to_front(self, value):
        new_node = ListNode(value)
        new_node.pointer = self.start
        self.start = new_node

    def remove_node(self, target_value):
        current_node = self.start
        if current_node and current_node.value == target_value:
            self.start = current_node.pointer
            current_node = None
            return
        previous_node = None
        while current_node and current_node.value != target_value:
            previous_node = current_node
            current_node = current_node.pointer
        if current_node is None:
            return
        previous_node.pointer = current_node.pointer
        current_node = None

# Demonstration of functionality
