    sll.add_to_end(1)
    sll.add_to_end(2)
    sll.add_to_end(3)
    sll.add_to_front(0)
    sll.show_list()  # Output: 0 -> 1 -> 2 -> 3 -> None
    sll.remove_node(2)
    sll.show_list()  # Output: 0 -> 1 -> 3 -> None

# Binary Search Tree implementation using alternative logic and naming

class TreeNode:
    def __init__(self, data_value):
        self.left_child = None
        self.right_child = None
        self.data = data_value

class BSTree:
    def __init__(self):
        self.head_node = None

    def add(self, value):
        if self.head_node is None:
            self.head_node = TreeNode(value)
        else:
            self._add_to_tree(self.head_node, value)

    def _add_to_tree(self, current_node, value):
        if value < current_node.data:
            if current_node.left_child is None:
                current_node.left_child = TreeNode(value)
            else:
                self._add_to_tree(current_node.left_child, value)
        elif value > current_node.data:
            if current_node.right_child is None:
                current_node.right_child = TreeNode(value)
            # Skip duplicates (same as original behavior)
        # Note: No action taken when value == current_node.data

    def find(self, target):
        return self._find_in_tree(self.head_node, target)

    def _find_in_tree(self, current_node, target):
        if current_node is None or current_node.data == target:
            return current_node
        if target < current_node.data:
            return self._find_in_tree(current_node.left_child, target)
        else:
            return self._find_in_tree(current_node.right_child, target)

    def in_order_list(self):
        output = []
        self._in_order_visit(self.head_node, output)
        return output

    def _in_order_visit(self, node, result_list):
        if node is not None:
            self._in_order_visit(node.left_child, result_list)
            result_list.append(node.data)
            self._in_order_visit(node.right_child, result_list)

    def pre_order_list(self):
        output = []
        self._pre_order_visit(self.head_node, output)
        return output

    def _pre_order_visit(self, node, result_list):
        if node is not None:
            result_list.append(node.data)
            self._pre_order_visit(node.left_child, result_list)
            self._pre_order_visit(node.right_child, result_list)

    def post_order_list(self):
        output = []
        self._post_order_visit(self.head_node, output)
        return output

    def _post_order_visit(self, node, result_list):
        if node is not None:
            self._post_order_visit(node.left_child, result_list)
            self._post_order_visit(node.right_child, result_list)
            result_list.append(node.data)

