def get_char_triplets(strings_list):
    output_dict = {}
    placeholder = 'N/A'

    for text in strings_list:
        if not isinstance(text, str):
            output_dict[text] = "Error: Input must be a string."
            continue

        # Collect characters at positions 9, 10, and 11 (1-indexed)
        char_list = []
        for pos in [8, 9, 10]:  # Convert to 0-based indices
            if pos < len(text):
                char_list.append(text[pos])
            else:
                char_list.append(placeholder)

        output_dict[text] = char_list

    return output_dict

