# Alternative implementation of AdvancedAuthenticationManager with modified internal logic

from collections import deque

class AdvancedAuthenticationManager:
    def __init__(self, timeToLive: int, maxRenewals: int):
        self.timeToLive = timeToLive
        self.maxRenewals = maxRenewals
        self.tokenData = {}  # tokenId -> [expiryTime, renewCount]
        self.expiryList = deque()  # (expiryTime, tokenId) for efficient queue operations

    def generate(self, tokenId: str, currentTime: int) -> None:
        expiry = currentTime + self.timeToLive
        self.tokenData[tokenId] = [expiry, 0]
        self.expiryList.append((expiry, tokenId))

    def renew(self, tokenId: str, currentTime: int) -> None:
        if tokenId in self.tokenData:
            expiry, count = self.tokenData[tokenId]
            if currentTime < expiry and count < self.maxRenewals:
                newExpiry = currentTime + self.timeToLive
                self.tokenData[tokenId] = [newExpiry, count + 1]
                self.expiryList.append((newExpiry, tokenId))

    def countUnexpiredTokens(self, currentTime: int) -> int:
        # Process expired tokens from the front of the queue
        while self.expiryList and self.expiryList[0][0] <= currentTime:
            _, token = self.expiryList.popleft()
            # Verify token still exists and is actually expired
            if token in self.tokenData and self.tokenData[token][0] <= currentTime:
                del self.tokenData[token]
        return len(self.tokenData)

# Calculate lateral surface area and volume for various frustum types

import numpy as np
from scipy.integrate import quad
from concurrent.futures import ThreadPoolExecutor
from functools import partial

def check_parameters(r1, r2, h, slant_height, major_r1=None, minor_r1=None, major_r2=None, minor_r2=None):
    # Validate basic circular parameters
    if any(val < 0 for val in [r1, r2, h, slant_height]):
        raise ValueError("All radii, height, and slant height must be non-negative.")

    # Validate elliptical parameters if provided
    if all(param is not None for param in [major_r1, minor_r1, major_r2, minor_r2]):
        if any(val < 0 for val in [major_r1, minor_r1, major_r2, minor_r2]):
            raise ValueError("All elliptical radii must be non-negative.")

def circular_lateral_area(r_top, r_bottom, s):
    return np.pi * (r_top + r_bottom) * s

def circular_volume(r_top, r_bottom, height):
    return (np.pi * height / 3) * (r_top**2 + r_bottom**2 + r_top * r_bottom)

def elliptical_lateral_area(major1, minor1, major2, minor2, s):
    avg_major = (major1 + major2) / 2
    avg_minor = (minor1 + minor2) / 2
    return 2 * np.pi * (avg_major + avg_minor) * s

def elliptical_volume(major1, minor1, major2, minor2, height):
    area1 = np.pi * major1 * minor1
    area2 = np.pi * major2 * minor2
    return (height / 3) * (area1 + area2 + np.sqrt(area1 * area2))

def variable_profile_lateral_area(shape_func, s, h, steps=1000):
    def integrand(z):
        radius = shape_func(z)
        # Approximate derivative using central difference
        dz = h / steps
        dr_dz = (shape_func(z + dz) - shape_func(z - dz)) / (2 * dz) if 0 < z < h else 0
        return 2 * np.pi * radius * np.sqrt(1 + dr_dz**2)
    return quad(integrand, 0, h)[0]

def variable_profile_volume(shape_func, h, steps=1000):
    def integrand(z):
        radius = shape_func(z)
        return np.pi * radius**2
    return quad(integrand, 0, h)[0]

def compute_frustum_properties(frustum_data):
    r1, r2, h, s, major_r1, minor_r1, major_r2, minor_r2, shape_func = frustum_data
    check_parameters(r1, r2, h, s, major_r1, minor_r1, major_r2, minor_r2)

    if shape_func is None:
        if any(x is not None for x in [major_r1, minor_r1, major_r2, minor_r2]):
            # Elliptical cross-section
            lateral = elliptical_lateral_area(major_r1, minor_r1, major_r2, minor_r2, s)
            vol = elliptical_volume(major_r1, minor_r1, major_r2, minor_r2, h)
        else:
            # Circular cross-section
            lateral = circular_lateral_area(r1, r2, s)
            vol = circular_volume(r1, r2, h)
    else:
        # Variable profile
        lateral = variable_profile_lateral_area(shape_func, s, h)
        vol = variable_profile_volume(shape_func, h)

    return lateral, vol

def batch_compute(frustum_list, workers=10):
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return list(pool.map(compute_frustum_properties, frustum_list))

