    elif ((player_pick == 'rock' and computer_pick == 'scissors') or 
          (player_pick == 'scissors' and computer_pick == 'paper') or 
          (player_pick == 'paper' and computer_pick == 'rock')):
        return "Player wins!"
    else:
        return "Computer wins!"

