# Quaternion class implementation with alternative method names and logic

class Quaternion:
    def __init__(self, real=0, i_comp=0, j_comp=0, k_comp=0):
        """
        Initialize a quaternion with components.

        :param real: Real part (scalar component)
        :param i_comp: i component (first imaginary part)
        :param j_comp: j component (second imaginary part)
        :param k_comp: k component (third imaginary part)
        """
        self.real = real
        self.i = i_comp
        self.j = j_comp
        self.k = k_comp

    def __str__(self):
        """
        Return a string representation of the quaternion.

        :return: String representation
        """
        parts = []
        if self.real != 0 or (self.i == 0 and self.j == 0 and self.k == 0):
            parts.append(str(self.real))
        if self.i != 0:
            parts.append(f"{self.i}i")
        if self.j != 0:
            parts.append(f"{self.j}j")
        if self.k != 0:
            parts.append(f"{self.k}k")
        return " + ".join(parts) if parts else "0"

    def conjugate(self):
        """
        Compute and return the conjugate of the quaternion.

        :return: Conjugate quaternion
        """
        return Quaternion(self.real, -self.i, -self.j, -self.k)

    def magnitude_squared(self):
        """
        Return the squared magnitude of the quaternion.

        :return: Squared magnitude
        """
        return self.real**2 + self.i**2 + self.j**2 + self.k**2

    def magnitude(self):
        """
        Return the magnitude (norm) of the quaternion.

        :return: Magnitude of the quaternion
        """
        return self.magnitude_squared() ** 0.5

    def unit(self):
        """
        Return the unit quaternion (normalized version).

        :return: Unit quaternion
        """
        mag = self.magnitude()
        if mag == 0:
            return Quaternion(0, 0, 0, 0)
        return Quaternion(self.real / mag, self.i / mag, self.j / mag, self.k / mag)

    def plus(self, other):
        """
        Add another quaternion to this one.

        :param other: Quaternion to add
        :return: Resulting quaternion
        """
        return Quaternion(self.real + other.real, self.i + other.i, self.j + other.j, self.k + other.k)

    def minus(self, other):
        """
        Subtract another quaternion from this one.

        :param other: Quaternion to subtract
        :return: Resulting quaternion
        """
        return Quaternion(self.real - other.real, self.i - other.i, self.j - other.j, self.k - other.k)

    def times(self, other):
        """
        Multiply this quaternion by another quaternion.

        :param other: Quaternion to multiply by
        :return: Resulting quaternion
        """
        r = self.real * other.real - self.i * other.i - self.j * other.j - self.k * other.k
        i = self.real * other.i + self.i * other.real + self.j * other.k - self.k * other.j
        j = self.real * other.j - self.i * other.k + self.j * other.real + self.k * other.i
        k = self.real * other.k + self.i * other.j - self.j * other.i + self.k * other.real
        return Quaternion(r, i, j, k)

    def reciprocal(self):
        """
        Return the multiplicative inverse of the quaternion.

        :return: Inverse quaternion
        """
        mag_sq = self.magnitude_squared()
        if mag_sq == 0:
            raise ValueError("Zero quaternion has no inverse")
        conj = self.conjugate()
        return Quaternion(conj.real / mag_sq, conj.i / mag_sq, conj.j / mag_sq, conj.k / mag_sq)

    # Operator overloads
    def __add__(self, other):
        return self.plus(other)

    def __sub__(self, other):
        return self.minus(other)

    def __mul__(self, other):
        if isinstance(other, (int, float)):
            return Quaternion(self.real * other, self.i * other, self.j * other, self.k * other)
        return self.times(other)

    def __truediv__(self, other):
        if isinstance(other, (int, float)):
            return Quaternion(self.real / other, self.i / other, self.j / other, self.k / other)
        return self * other.reciprocal()

