# Clone of the original code with modified structure and logic

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def getTargetCopy(self, original: TreeNode, cloned: TreeNode, target: TreeNode) -> TreeNode:
    # Helper function to traverse both trees simultaneously
    def search_tree(orig_node, clone_node):
        # Base case: if we've reached a null node, return None
        if orig_node is None:
            return None

        # Check if current node matches the target
        if orig_node is target:
            return clone_node

        # Search in left subtree first
        found_in_left = search_tree(orig_node.left, clone_node.left)
        if found_in_left is not None:
            return found_in_left

        # If not found in left subtree, search right subtree
        return search_tree(orig_node.right, clone_node.right)

    # Start the search from root nodes
    return search_tree(original, cloned)

