import numpy as np

def initialize_grid():
    return np.zeros((6, 7))

def can_place(board, column):
    return board[0][column] == 0

def drop_piece(board, column, piece):
    for row in range(5, -1, -1):
        if board[row][column] == 0:
            board[row][column] = piece
            break

def has_won(board, piece):
    # Horizontal check
    for r in range(6):
        for c in range(4):
            if all(board[r][c+i] == piece for i in range(4)):
                return True

    # Vertical check
    for c in range(7):
        for r in range(3):
            if all(board[r+i][c] == piece for i in range(4)):
                return True

    # Diagonal (down-right)
    for r in range(3):
        for c in range(4):
            if all(board[r+i][c+i] == piece for i in range(4)):
                return True

    # Diagonal (up-right)
    for r in range(3, 6):
        for c in range(4):
            if all(board[r-i][c+i] == piece for i in range(4)):
                return True

    return False

def is_board_full(board):
    return not np.any(board == 0)

def computer_move(board, piece):
    # Try to win
    for col in range(7):
        temp = board.copy()
        if can_place(temp, col):
            drop_piece(temp, col, piece)
            if has_won(temp, piece):
                drop_piece(board, col, piece)
                return

    # Block opponent
    opponent = 3 - piece
    for col in range(7):
        temp = board.copy()
        if can_place(temp, col):
            drop_piece(temp, col, opponent)
            if has_won(temp, opponent):
                drop_piece(board, col, piece)
                return

    # Random valid move
    while True:
        col = np.random.randint(0, 7)
        if can_place(board, col):
            drop_piece(board, col, piece)
            break

# Game setup
grid = initialize_grid()
current_player = 1
finished = False

while not finished:
    print(grid)

    if current_player == 1:
        try:
            move = int(input("Player 1, enter your column choice (0-6): "))
            if 0 <= move <= 6 and can_place(grid, move):
                drop_piece(grid, move, current_player)
                if has_won(grid, current_player):
                    print("Player 1 wins!")
                    finished = True
            else:
                print("Invalid move. Please choose a valid column.")
                continue
        except ValueError:
            print("Please enter a number between 0 and 6.")
            continue
    else:
        print("AI is making a move...")
        computer_move(grid, current_player)
        if has_won(grid, current_player):
            print("AI wins!")
            finished = True

    if is_board_full(grid) and not finished:
        print("It's a draw!")
        finished = True

    current_player = 3 - current_player

import random
from typing import List

class WeightedPicker:
    def __init__(self, values: List[int]):
        self.values = values
        self.position_map = {}
        for idx, val in enumerate(values):
            if val not in self.position_map:
                self.position_map[val] = []
            self.position_map[val].append(idx)

    def select(self, key: int, left_bound: int, right_bound: int) -> int:
        if key not in self.position_map:
            return -1  # Key not found (shouldn't occur per problem constraints)

        # Filter indices within the specified range [left_bound, right_bound]
        candidates = [pos for pos in self.position_map[key] if left_bound <= pos <= right_bound]
        if not candidates:
            return -1  # No valid indices in range (shouldn't occur per problem constraints)

        # Compute weights proportional to frequency of the key in the entire array
        freq = sum(1 for v in self.values if v == key)
        weights = [freq for _ in candidates]

        # Normalize weights so they sum to 1.0
        weight_sum = sum(weights)
        prob_weights = [w / weight_sum for w in weights]

        # Select one index using weighted random sampling
        selected = random.choices(candidates, weights=prob_weights, k=1)[0]
        return selected

# Demonstration usage:
picker = WeightedPicker([1, 2, 3, 3, 3])
print(picker.select(3, 1, 4))  # Returns 2, 3, or 4 with equal probability (since weights are uniform)
print(picker.select(1, 0, 1))  # Returns 0
print(picker.select(3, 2, 4))  # Returns 2, 3, or 4 with equal probability

# Extract and compare publication years from book editions

from dateutil import parser as date_parser
from dateutil.relativedelta import relativedelta
from datetime import datetime

def extract_year(date_string):
    """
    Extract the year from a date string, with fallback for invalid dates.
    """
    try:
        parsed_date = date_parser.parse(date_string)
        return parsed_date.year
    except (ValueError, TypeError):
        return None

def determine_earliest_publication_year(edition_list):
    """
    Find the earliest valid publication year among multiple editions.
    """
    valid_years = []
    for edition in edition_list:
        year_value = extract_year(edition.get('year', ''))
        if year_value is not None:
            valid_years.append(year_value)

    return min(valid_years) if valid_years else None

def select_books_after_target_year(book_collection, cutoff_year=1980):
    """
    Select books whose earliest publication year exceeds the specified cutoff.
    """
    selected_books = []
    for book in book_collection:
        earliest_year = determine_earliest_publication_year(book.get('editions', []))
        if earliest_year is not None and earliest_year > cutoff_year:
            selected_books.append(book)
    return selected_books

