import unittest
import multiprocessing

class ParallelTestExecutor:
    def __init__(self, test_discoverer, worker_count=None):
        self.test_discoverer = test_discoverer
        self.worker_count = worker_count or multiprocessing.cpu_count()

    def execute(self, test_collection):
        individual_tests = []
        for test_group in test_collection:
            for single_test in test_group:
                individual_tests.append(single_test)

        with multiprocessing.Pool(processes=self.worker_count) as pool:
            outcomes = pool.map(self.execute_single_test, individual_tests)

        for outcome in outcomes:
            if not outcome.wasSuccessful():
                return outcome

    def execute_single_test(self, test_case):
        outcome = unittest.TestResult()
        test_case.run(outcome)
        return outcome

