# Alternative implementation with modified logic for counting keys and void structures

import threading
from collections.abc import Mapping, Iterable
import types

class ComplexDataType:
    pass  # Placeholder for complex data types

def is_complex_type(obj):
    # Check if object is a complex type that shouldn't be traversed
    return isinstance(obj, (type, types.ModuleType, types.FunctionType, 
                           threading.Thread, ComplexDataType))

def analyze_structure(data, visited=None):
    # Initialize visited set to prevent infinite recursion on circular references
    if visited is None:
        visited = set()

    obj_id = id(data)
    if obj_id in visited:
        return (True, 0, 0, 0)  # Already seen: all void, no new dicts/keys/types

    visited.add(obj_id)

    # Initialize counters
    all_void = True
    empty_dict_count = 0
    key_count = 0
    complex_count = 0

    # Handle mapping types (dict-like objects)
    if isinstance(data, Mapping):
        if len(data) == 0:
            # Empty dictionary counts as a void structure
            empty_dict_count += 1
        else:
            # Non-empty mapping means not all void
            all_void = False
            for k, v in data.items():
                key_count += 1
                if is_complex_type(v):
                    complex_count += 1
                else:
                    # Recursively analyze the value
                    sub_analysis = analyze_structure(v, visited)
                    all_void = all_void and sub_analysis[0]
                    empty_dict_count += sub_analysis[1]
                    key_count += sub_analysis[2]
                    complex_count += sub_analysis[3]

    # Handle iterable types (excluding strings and bytes)
    elif isinstance(data, Iterable) and not isinstance(data, (str, bytes)):
        for item in data:
            sub_analysis = analyze_structure(item, visited)
            all_void = all_void and sub_analysis[0]
            empty_dict_count += sub_analysis[1]
            key_count += sub_analysis[2]
            complex_count += sub_analysis[3]

    return (all_void, empty_dict_count, key_count, complex_count)

