# Calculator with basic arithmetic operations

def perform_addition(x, y):
    """Returns the sum of two numbers."""
    return x + y

def perform_subtraction(x, y):
    """Returns the difference when y is subtracted from x."""
    return x - y

def perform_multiplication(x, y):
    """Returns the product of two numbers."""
    return x * y

def perform_division(x, y):
    """Returns a tuple (quotient, error_message). If division by zero, returns (None, error_message)."""
    if y == 0:
        return None, "Cannot divide by zero."
    return x / y, None

def perform_power(base, exp):
    """Returns base raised to the power of exp."""
    return base ** exp

def perform_modulus(x, y):
    """Returns a tuple (remainder, error_message). If modulo by zero, returns (None, error_message)."""
    if y == 0:
        return None, "Cannot compute modulo with zero divisor."
    return x % y, None

def compute_root(value, degree):
    """Returns a tuple (root, error_message). Returns error for even root of negative number."""
    if value < 0 and degree % 2 == 0:
        return None, "Even root of negative number is not real."
    return value ** (1.0 / degree), None

def display_output(op_name, first, second, res, err=None):
    """Displays operation result or error message."""
    if err:
        print(f"Error: {err}")
    else:
        print(f"{first} {op_name} {second} = {res}")

def run_calculator():
    # Mapping operation names to functions
    calc_ops = {
        'add': perform_addition,
        'subtract': perform_subtraction,
        'multiply': perform_multiplication,
        'divide': perform_division,
        'power': perform_power,
        'modulo': perform_modulus,
        'root': compute_root
    }

    while True:
        print("\n--- Calculator Menu ---")
        print("1. Addition")
        print("2. Subtraction")
        print("3. Multiplication")
        print("4. Division")
        print("5. Exponentiation")
        print("6. Modulo")
        print("7. Nth Root")
        print("8. Quit")

        selection = input("Choose an operation (1-8): ")

        if selection == '8':
            print("Goodbye!")
            break

        if selection not in [str(i) for i in range(1, 9)]:
            print("Invalid option. Try again.")
            continue

        try:
            num1 = float(input("Enter first number: "))
            num2 = float(input("Enter second number: "))
        except ValueError:
            print("Please enter valid numeric values.")
            continue

        # Handle special cases that return tuples
        if selection == '4':
            output, problem = perform_division(num1, num2)
            display_output("division", num1, num2, output, problem)
        elif selection == '6':
            output, problem = perform_modulus(num1, num2)
            display_output("modulo", num1, num2, output, problem)
        elif selection == '7':
            output, problem = compute_root(num1, num2)
            display_output("nth root", num1, num2, output, problem)
        else:
            op_key = list(calc_ops.keys())[int(selection) - 1]
            result = calc_ops[op_key](num1, num2)
            display_output(op_key, num1, num2, result)

if __name__ == "__main__":
