# Secure API with role-based access control (refactored version)

from fastapi import FastAPI, Depends, HTTPException, status, Security
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm, SecurityScopes
from pydantic import BaseModel
from typing import List, Optional
from datetime import datetime, timedelta
from jose import jwt, JWTError
from passlib.context import CryptContext
import logging

# Configuration constants
APP_SECRET = "your_secret_key"
TOKEN_ALGO = "HS256"
TOKEN_VALIDITY_MINS = 30

# User definitions
USER_RECORDS = [
    {"username": "David", "password": "REDACTED_CREDENTIAL", "role": "Admin"},
    {"username": "Sara", "password": "REDACTED_CREDENTIAL", "role": "User"},
    {"username": "John", "password": "REDACTED_CREDENTIAL", "role": "Manager"}
]

# Permission mapping by role
ROLE_ACCESS_LEVELS = {
    "Admin": ["read", "write", "delete"],
    "Manager": ["read", "write"],
    "User": ["read"]
}

# Password hashing setup
hashing_context = CryptContext(schemes=["bcrypt"], deprecated="auto")

# In-memory user database
user_database = {user["username"]: user for user in USER_RECORDS}

# Initialize FastAPI app
app = FastAPI()

# OAuth2 configuration
oauth2_scheme = OAuth2PasswordBearer(
    tokenUrl="token",
    scopes={"read": "Read capability", "write": "Write capability", "delete": "Delete capability"}
)

# Data models
class AccessToken(BaseModel):
    access_token: str
    token_type: str

class TokenPayload(BaseModel):
    username: Optional[str] = None
    permissions: List[str] = []

class Person(BaseModel):
    username: str
    role: str

class PersonInDB(Person):
    hashed_password: str

# Utility functions
def check_password(plain_text, stored_hash):
    return hashing_context.verify(plain_text, stored_hash)

def hash_user_password(password):
    return hashing_context.hash(password)

def find_user(db, username: str):
    return db.get(username)

def validate_credentials(fake_db, username: str, password: str):
    user_record = find_user(fake_db, username)
    if not user_record:
        return False
    if not check_password(password, user_record.get("hashed_password", "")):
        return False
    return user_record

def generate_jwt(payload_data: dict, expiry_delta: Optional[timedelta] = None):
    payload_copy = payload_data.copy()
    expiration_time = datetime.utcnow() + (expiry_delta or timedelta(minutes=15))
    payload_copy["exp"] = expiration_time
    return jwt.encode(payload_copy, APP_SECRET, algorithm=TOKEN_ALGO)

def fetch_current_person(security_scopes: SecurityScopes, token: str = Depends(oauth2_scheme)):
    auth_header_value = (
        f'Bearer scope="{security_scopes.scope_str}"'
        if security_scopes.scopes else "Bearer"
    )

    unauthorized_error = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Authentication failed",
        headers={"WWW-Authenticate": auth_header_value},
    )

    try:
        decoded_payload = jwt.decode(token, APP_SECRET, algorithms=[TOKEN_ALGO])
        user_name: str = decoded_payload.get("sub")
        if not user_name:
            raise unauthorized_error

        granted_permissions = decoded_payload.get("permissions", [])
        token_info = TokenPayload(permissions=granted_permissions, username=user_name)
    except JWTError:
        raise unauthorized_error

    person_record = find_user(user_database, username=token_info.username)
    if not person_record:
        raise unauthorized_error

    for required_scope in security_scopes.scopes:
        if required_scope not in token_info.permissions:
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Insufficient privileges",
                headers={"WWW-Authenticate": auth_header_value},
            )

    return Person(**person_record)

def fetch_active_person(current_person: Person = Security(fetch_current_person, scopes=[])):
    return current_person

# API endpoints
@app.post("/token", response_model=AccessToken)
async def obtain_access_token(form_data: OAuth2PasswordRequestForm = Depends()):
    authenticated_user = validate_credentials(user_database, form_data.username, form_data.password)
    if not authenticated_user:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid login credentials",
            headers={"WWW-Authenticate": "Bearer"},
        )

    token_duration = timedelta(minutes=TOKEN_VALIDITY_MINS)
    jwt_token = generate_jwt(
        data={"sub": authenticated_user["username"], "permissions": ROLE_ACCESS_LEVELS[authenticated_user["role"]]},
        expiry_delta=token_duration
    )
    return {"access_token": jwt_token, "token_type": "bearer"}

@app.get("/profile", response_model=Person)
async def view_profile(current_person: Person = Depends(fetch_active_person)):
    return current_person

@app.get("/products", response_model=List[str])
async def list_products(current_person: Person = Security(fetch_active_person, scopes=["read"])):
    return ["Product A", "Product B", "Product C"]

@app.post("/products", response_model=str)
async def add_product(product_name: str, current_person: Person = Security(fetch_active_person, scopes=["write"])):
    return f"Product '{product_name}' added by {current_person.username}"

@app.delete("/products/{product_id}", response_model=str)
async def remove_product(product_id: int, current_person: Person = Security(fetch_active_person, scopes=["delete"])):
    return f"Product {product_id} removed by {current_person.username}"

