# Function to validate date format (YYYY-MM-DD)
def check_date_format(date_text):
    try:
        # Note: Using %Y-%m-%d instead of %Y-%M-%d for correct month formatting
        parts = date_text.split('-')
        if len(parts) != 3:
            return False
        year, month, day = map(int, parts)
        if not (1 <= month <= 12 and 1 <= day <= 31):
            return False
        return True
    except (ValueError, AttributeError):
        return False

# Function to validate individual shoe data
def verify_shoe(shoe_data):
    if not isinstance(shoe_data, dict):
        return False

    required_keys = ["name", "color", "size", "brand", "reviews"]
    if not all(key in shoe_data for key in required_keys):
        return False

    # Validate name field
    if not isinstance(shoe_data["name"], str) or len(shoe_data["name"]) > 50:
        return False

    # Validate color field
    if not isinstance(shoe_data["color"], str) or len(shoe_data["color"]) > 20:
        return False

    # Validate size field
    if not isinstance(shoe_data["size"], (int, float)) or not (5 <= shoe_data["size"] <= 15):
        return False

    # Validate brand field
    if not isinstance(shoe_data["brand"], str) or len(shoe_data["brand"]) > 30:
        return False

    # Validate reviews list
    if not isinstance(shoe_data["reviews"], list) or len(shoe_data["reviews"]) < 3:
        return False

    # Validate each review
    for review_item in shoe_data["reviews"]:
        if not isinstance(review_item, dict):
            return False

        review_keys = ["rating", "comment", "date"]
        if not all(key in review_item for key in review_keys):
            return False

        # Validate rating
        if not isinstance(review_item["rating"], (int, float)) or not (1 <= review_item["rating"] <= 5):
            return False

        # Validate comment
        if not isinstance(review_item["comment"], str) or len(review_item["comment"]) > 100:
            return False

        # Validate date
        if not isinstance(review_item["date"], str) or not check_date_format(review_item["date"]):
            return False

    return True

# Function to compute average rating across all shoes
def compute_avg_rating(all_shoes):
    sum_ratings = 0
    count_reviews = 0

    for shoe in all_shoes:
        for review in shoe["reviews"]:
            sum_ratings += review["rating"]
            count_reviews += 1

    return sum_ratings / count_reviews if count_reviews > 0 else 0.0

