# Employee Management System - Refactored Version

class StaffMember:
    def __init__(self, full_name, years):
        self.full_name = full_name
        self.years = years

    def __str__(self):
        return f"{self.full_name} (Years: {self.years})"

class StaffController:
    def __init__(self):
        self.staff_list = []

    def register_staff(self, full_name, years):
        if not full_name or not years:
            raise ValueError("Full name and years of age are required.")
        if not isinstance(years, int) or years <= 0:
            raise ValueError("Years must be a positive integer.")
        self.staff_list.append(StaffMember(full_name, years))
        print(f"Staff member {full_name} registered successfully.")

    def deregister_staff(self, full_name):
        for member in self.staff_list:
            if member.full_name == full_name:
                self.staff_list.remove(member)
                print(f"Staff member {full_name} deregistered successfully.")
                return
        raise ValueError(f"Staff member {full_name} not found.")

    def modify_years(self, full_name, updated_years):
        if not updated_years or not isinstance(updated_years, int) or updated_years <= 0:
            raise ValueError("Updated years must be a positive integer.")
        for member in self.staff_list:
            if member.full_name == full_name:
                member.years = updated_years
                print(f"Staff member {full_name}'s age updated to {updated_years}.")
                return
        raise ValueError(f"Staff member {full_name} not found.")

    def display_staff(self):
        if not self.staff_list:
            print("No staff members in the list.")
            return
        ordered_staff = sorted(self.staff_list, key=lambda x: x.full_name)
        for member in ordered_staff:
            print(member)

    def mean_age(self):
        if not self.staff_list:
            print("No staff members in the list.")
            return 0
        total_years = sum(member.years for member in self.staff_list)
        return total_years / len(self.staff_list)

def run_program():
    controller = StaffController()
    while True:
        print("\nStaff Management System")
        print("1. Register Staff Member")
        print("2. Deregister Staff Member")
        print("3. Update Staff Member Age")
        print("4. Display Staff Members")
        print("5. Mean Age of Staff Members")
        print("6. Quit")
        option = input("Enter your option: ")

        try:
            option = int(option)
            if option == 1:
                full_name = input("Enter staff member's full name: ")
                years = int(input("Enter staff member's age: "))
                controller.register_staff(full_name, years)
            elif option == 2:
                full_name = input("Enter staff member's full name to remove: ")
                controller.deregister_staff(full_name)
            elif option == 3:
                full_name = input("Enter staff member's full name to update age: ")
                updated_years = int(input("Enter new age: "))
                controller.modify_years(full_name, updated_years)
            elif option == 4:
                controller.display_staff()
            elif option == 5:
                avg_years = controller.mean_age()
                print(f"Mean age of staff members: {avg_years:.2f}")
            elif option == 6:
                print("Terminating the program.")
                break
            else:
                print("Invalid option. Please try again.")
        except ValueError as e:
            print(f"Exception: {e}")

if __name__ == "__main__":
    run_program()

# Process CSV file and generate formatted LaTeX output

import csv
import sys

def load_csv_content(file_location, separator=','):
    try:
        with open(file_location, 'r', encoding='utf-8') as input_file:
            parser = csv.reader(input_file, delimiter=separator)
            rows = [line for line in parser]
        return rows
    except FileNotFoundError:
        print(f"Error: File at '{file_location}' could not be located.")
        sys.exit(1)
    except Exception as error:
        print(f"Error: An unexpected issue arose during file processing: {error}")
        sys.exit(1)

def check_data_integrity(rows):
    if len(rows) == 0:
        print("Error: The provided CSV contains no data rows or is malformed.")
        sys.exit(1)

def prepare_latex_output(rows, highlight_terms):
    # Extract first column entries
    first_entries = [row[0] for row in rows]
    # Sort in descending order
    first_entries.sort(reverse=True)

    # Build formatted string with LaTeX commands
    result_parts = []
    for item in first_entries:
        if item in highlight_terms:
            result_parts.append(r'\textbf{\textit{' + item + r'}}')
        else:
            result_parts.append(item)

    latex_prefix = r'\textbf{\textit{Concatenated Values:}} '
    return latex_prefix + ' '.join(result_parts)

def execute():
    if len(sys.argv) < 3:
        print("Usage: python script.py <file_path> <delimiter> [keywords ...]")
        sys.exit(1)

    target_file = sys.argv[1]
    field_separator = sys.argv[2]
    emphasis_words = sys.argv[3:]

    raw_data = load_csv_content(target_file, field_separator)
    check_data_integrity(raw_data)

    final_output = prepare_latex_output(raw_data, emphasis_words)
    print(final_output)

if __name__ == "__main__":
    execute()

class MahJonggHand:
    def __init__(self, tiles):
        self.tiles = tiles
        self.pattern_counts = {'triplets': 0, 'quadruplets': 0, 'sequences': 0, 'doublets': 0}
        self.hand_types = {
            'Thirteen Orphans': self.check_thirteen_orphans,
            'Seven Pairs': self.check_seven_pairs,
            'Complete Triplets': self.check_complete_triplets,
            'Complete Sequences': self.check_complete_sequences,
            'Mixed Sequential Sets': self.check_mixed_sequential_sets,
            'Terminals_and_Honors_Only': self.check_terminals_and_honors_only,
            'Simple_Tiles_Only': self.check_simple_tiles_only,
            'Half_Suit_Flush': self.check_half_suit_flush,
            'Full_Suit_Flush': self.check_full_suit_flush
        }

    def check_thirteen_orphans(self):
        # Verify presence of all required orphan tiles and exactly one pair
        orphan_list = ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B']
        has_all_orphans = all(orph in self.tiles for orph in orphan_list)
        tile_counts = {tile: self.tiles.count(tile) for tile in set(self.tiles)}
        pair_count = sum(1 for count in tile_counts.values() if count == 2)
        return has_all_orphans and pair_count == 1

    def check_seven_pairs(self):
        # Confirm hand consists of exactly seven distinct pairs
        unique_tiles = list(set(self.tiles))
        pair_tiles = [tile for tile in unique_tiles if self.tiles.count(tile) == 2]
        return len(pair_tiles) == 7 and len(unique_tiles) == 7

    def check_complete_triplets(self):
        # Validate that all tiles form complete triplets (3 identical tiles)
        tile_frequency = {}
        for t in self.tiles:
            tile_frequency[t] = tile_frequency.get(t, 0) + 1
        counts = list(tile_frequency.values())
        return all(c == 3 for c in counts) and len(counts) == 4

    def check_complete_sequences(self):
        # Check if hand contains only sequences (note: original code had same logic as all_pungs)
        tile_frequency = {}
        for t in self.tiles:
            tile_frequency[t] = tile_frequency.get(t, 0) + 1
        counts = list(tile_frequency.values())
        return all(c == 3 for c in counts) and len(counts) == 4

    def check_mixed_sequential_sets(self):
        # Placeholder for mixed sequential chows implementation
        return False

    def check_terminals_and_honors_only(self):
        # Ensure every tile is either a terminal or honor tile
        valid_terminal_honor = {'1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B'}
        return all(tile in valid_terminal_honor for tile in self.tiles)

    def check_simple_tiles_only(self):
        # Verify all tiles are simple tiles (2-8 in any suit)
        simple_tiles = {f'{n}{s}' for n in range(2, 9) for s in ['m', 'p', 's']}
        return all(tile in simple_tiles for tile in self.tiles)

    def check_half_suit_flush(self):
        # Determine if hand uses exactly two suits
        suits = {tile[-1] for tile in self.tiles if len(tile) >= 2}
        return len(suits) == 2

    def check_full_suit_flush(self):
        # Determine if hand uses only one suit
        suits = {tile[-1] for tile in self.tiles if len(tile) >= 2}
        return len(suits) == 1

# Chat application backend using Flask and SQLite

from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///chat.db'
db = SQLAlchemy(app)

class Conversation(db.Model):
    __tablename__ = 'chat'
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    notes = db.Column(db.String(255))
    created_on = db.Column(db.DateTime, default=datetime.utcnow)

class Post(db.Model):
    __tablename__ = 'message'
    id = db.Column(db.Integer, primary_key=True)
    conversation_id = db.Column(db.Integer, db.ForeignKey('chat.id'), nullable=False)
    author_id = db.Column(db.Integer, nullable=False)
    text = db.Column(db.Text, nullable=False)
    posted_at = db.Column(db.DateTime, default=datetime.utcnow)

class Member(db.Model):
    __tablename__ = 'user'
    id = db.Column(db.Integer, primary_key=True)
    handle = db.Column(db.String(100), nullable=False)

class Membership(db.Model):
    __tablename__ = 'chat_participant'
    conversation_id = db.Column(db.Integer, db.ForeignKey('chat.id'), primary_key=True)
    member_id = db.Column(db.Integer, db.ForeignKey('user.id'), primary_key=True)
    joined_on = db.Column(db.DateTime, default=datetime.utcnow)

@app.route('/conversations', methods=['POST'])
def establish_conversation():
    payload = request.get_json()
    new_conversation = Conversation(
        title=payload['name'], 
        notes=payload['description']
    )
    db.session.add(new_conversation)
    db.session.commit()
    return jsonify({
        "id": new_conversation.id,
        "name": new_conversation.title,
        "description": new_conversation.notes,
        "created_at": new_conversation.created_on
    }), 201

@app.route('/conversations', methods=['GET'])
def retrieve_conversations():
    page_num = request.args.get('page', 1, type=int)
    items_per_page = request.args.get('limit', 10, type=int)
    conversations = Conversation.query.paginate(page=page_num, per_page=items_per_page, error_out=False)
    return jsonify({
        "chats": [conv.to_dict() for conv in conversations.items],
        "total": conversations.total
    })

@app.route('/conversations/<int:conversation_id>/posts', methods=['POST'])
def add_post(conversation_id):
    payload = request.get_json()
    new_post = Post(
        conversation_id=conversation_id, 
        author_id=payload['user_id'], 
        text=payload['content']
    )
    db.session.add(new_post)
    db.session.commit()
    return jsonify({
        "id": new_post.id,
        "chat_id": new_post.conversation_id,
        "user_id": new_post.author_id,
        "content": new_post.text,
        "created_at": new_post.posted_at
    }), 201

@app.route('/conversations/<int:conversation_id>/posts', methods=['GET'])
def fetch_posts(conversation_id):
    page_num = request.args.get('page', 1, type=int)
    items_per_page = request.args.get('limit', 10, type=int)
    posts = Post.query.filter_by(conversation_id=conversation_id).paginate(
        page=page_num, per_page=items_per_page, error_out=False
    )
    return jsonify({
        "messages": [post.to_dict() for post in posts.items],
        "total": posts.total
    })

@app.route('/conversations/<int:conversation_id>/memberships', methods=['POST'])
def add_member(conversation_id):
    payload = request.get_json()
    new_membership = Membership(
        conversation_id=conversation_id, 
        member_id=payload['user_id']
    )
