# Re-engineered version of the Online Class Platform with modified internal logic and data handling

class VirtualLearningSystem:
    def __init__(self):
        self.enrolled_students = {}  # Stores student records by ID
        self.active_courses = {}     # Stores course records by ID

    # Student-related operations
    def register_student(self, student_identifier, full_name):
        if student_identifier in self.enrolled_students:
            raise ValueError(f"Student {student_identifier} is already registered.")
        self.enrolled_students[student_identifier] = {
            'name': full_name,
            'enrollments': {},
            'overall_grade': 0.0
        }

    def deregister_student(self, student_identifier):
        if student_identifier not in self.enrolled_students:
            raise ValueError(f"Student {student_identifier} does not exist.")

        # Remove from all courses
        for course_id in list(self.active_courses.keys()):
            if student_identifier in self.active_courses[course_id]['participants']:
                self.active_courses[course_id]['participants'].remove(student_identifier)
                self._recalculate_course_metrics(course_id)

        del self.enrolled_students[student_identifier]

    def record_performance(self, student_identifier, course_identifier, assessment_results):
        if student_identifier not in self.enrolled_students:
            raise ValueError(f"Student {student_identifier} is not registered.")
        if course_identifier not in self.active_courses:
            raise ValueError(f"Course {course_identifier} does not exist.")

        self.enrolled_students[student_identifier]['enrollments'][course_identifier] = assessment_results
        self._refresh_student_metrics(student_identifier)
        self._recalculate_course_metrics(course_identifier)

    def get_high_performers(self, threshold):
        return [record for record in self.enrolled_students.values() 
                if record['overall_grade'] > threshold]

    # Course-related operations
    def create_course(self, course_identifier, title):
        if course_identifier in self.active_courses:
            raise ValueError(f"Course {course_identifier} already exists.")
        self.active_courses[course_identifier] = {
            'title': title,
            'participants': [],
            'class_average': 0.0
        }

    def delete_course(self, course_identifier):
        if course_identifier not in self.active_courses:
            raise ValueError(f"Course {course_identifier} does not exist.")

        # Remove course from all students' enrollments
        for student_id in list(self.enrolled_students.keys()):
            if course_identifier in self.enrolled_students[student_id]['enrollments']:
                del self.enrolled_students[student_id]['enrollments'][course_identifier]
                self._refresh_student_metrics(student_id)

        del self.active_courses[course_identifier]

    def enroll_in_course(self, student_identifier, course_identifier):
        if student_identifier not in self.enrolled_students:
            raise ValueError(f"Student {student_identifier} is not registered.")
        if course_identifier not in self.active_courses:
            raise ValueError(f"Course {course_identifier} does not exist.")
        if student_identifier in self.active_courses[course_identifier]['participants']:
            raise ValueError(f"Student {student_identifier} is already enrolled in {course_identifier}.")

        self.active_courses[course_identifier]['participants'].append(student_identifier)
        self.enrolled_students[student_identifier]['enrollments'][course_identifier] = {}
        self._recalculate_course_metrics(course_identifier)

    def withdraw_from_course(self, student_identifier, course_identifier):
        if student_identifier not in self.enrolled_students:
            raise ValueError(f"Student {student_identifier} is not registered.")
        if course_identifier not in self.active_courses:
            raise ValueError(f"Course {course_identifier} does not exist.")
        if student_identifier not in self.active_courses[course_identifier]['participants']:
            raise ValueError(f"Student {student_identifier} is not enrolled in {course_identifier}.")

        self.active_courses[course_identifier]['participants'].remove(student_identifier)
        if course_identifier in self.enrolled_students[student_identifier]['enrollments']:
            del self.enrolled_students[student_identifier]['enrollments'][course_identifier]
            self._refresh_student_metrics(student_identifier)
        self._recalculate_course_metrics(course_identifier)

    def top_performer_in_course(self, course_identifier):
        if course_identifier not in self.active_courses:
            raise ValueError(f"Course {course_identifier} does not exist.")

        best_score = float('-inf')
        best_student = None

        for participant_id in self.active_courses[course_identifier]['participants']:
            if course_identifier in self.enrolled_students[participant_id]['enrollments']:
                assessments = self.enrolled_students[participant_id]['enrollments'][course_identifier]
                if assessments:
                    current_score = sum(assessments.values()) / len(assessments)
                    if current_score > best_score:
                        best_score = current_score
                        best_student = participant_id

        return best_student, best_score

    # Internal calculation methods (restructured logic)
    def _refresh_student_metrics(self, student_identifier):
        enrollments = self.enrolled_students[student_identifier]['enrollments']
        if not enrollments:
            self.enrolled_students[student_identifier]['overall_grade'] = 0.0
            return

        total_points = 0
        total_assessments = 0
        for course_id, metrics in enrollments.items():
            total_points += sum(metrics.values())
            total_assessments += len(metrics) if metrics else 0

        self.enrolled_students[student_identifier]['overall_grade'] = (
            total_points / total_assessments if total_assessments else 0.0
        )

    def _recalculate_course_metrics(self, course_identifier):
        participants = self.active_courses[course_identifier]['participants']
        if not participants:
            self.active_courses[course_identifier]['class_average'] = 0.0
            return

        total_points = 0
        total_assessments = 0
        for student_id in participants:
            if course_identifier in self.enrolled_students[student_id]['enrollments']:
                assessments = self.enrolled_students[student_id]['enrollments'][course_identifier]
                total_points += sum(assessments.values())
                total_assessments += len(assessments) if assessments else 0

        self.active_courses[course_identifier]['class_average'] = (
            total_points / total_assessments if total_assessments else 0.0
        )


