import csv
import sys

def load_csv_content(file_name, sep=','):
    try:
        with open(file_name, 'r', encoding='utf-8') as f:
            reader = csv.reader(f, delimiter=sep)
            rows = [row for row in reader]
            return rows
    except FileNotFoundError:
        print(f"Error: File '{file_name}' could not be located.")
        sys.exit(1)
    except Exception as error:
        print(f"Error: Unexpected issue while reading file: {error}")
        sys.exit(1)

def extract_and_sort_first_column(table):
    if not table or len(table[0]) == 0:
        print("Error: Input table contains no data.")
        sys.exit(1)

    first_entries = [row[0] for row in table]
    first_entries.sort(reverse=True)
    return first_entries

def apply_formatting(items, highlight_terms):
    result = ""
    for item in items:
        modified_item = item
        for term in highlight_terms:
            if term in modified_item:
                modified_item = modified_item.replace(term, r"\textbf{\textit{" + term + r"}}")
        result += modified_item + " "
    return result.strip()

def main():
    if len(sys.argv) < 3:
        print("Usage: python script.py <file_path> <delimiter> [keywords...]")
        sys.exit(1)

    input_file = sys.argv[1]
    field_separator = sys.argv[2]
    emphasis_words = sys.argv[3:]

    raw_data = load_csv_content(input_file, field_separator)
    sorted_first_column = extract_and_sort_first_column(raw_data)
    formatted_text = apply_formatting(sorted_first_column, emphasis_words)

    print(r"\documentclass{article}" + "\n" + r"\begin{document}" + "\n" + formatted_text + "\n" + r"\end{document}")

if __name__ == "__main__":
    main()

# Type III Clone: Refactored Quadrilateral Class Hierarchy

class FourSidedShape:
    def __init__(self, a, b, c, d):
        self.a = a
        self.b = b
        self.c = c
        self.d = d

    def total_perimeter(self):
        return self.a + self.b + self.c + self.d

    def surface_area(self):
        raise NotImplementedError("Subclasses must define area calculation")

    def adjust_sides(self, a, b, c, d):
        self.a = a
        self.b = b
        self.c = c
        self.d = d


class Parallelogram(FourSidedShape):
    def __init__(self, length, breadth):
        if length <= 0 or breadth <= 0:
            raise ValueError("Length and breadth must be positive values")
        super().__init__(length, breadth, length, breadth)
        self.length = length
        self.breadth = breadth

    def surface_area(self):
        return self.length * self.breadth

    def adjust_sides(self, length, breadth):
        if length <= 0 or breadth <= 0:
            raise ValueError("Length and breadth must be positive values")
        super().adjust_sides(length, breadth, length, breadth)
        self.length = length
        self.breadth = breadth

    def check_parallelogram(self):
        return self.a == self.c and self.b == self.d


class Rhombus(Parallelogram):
    def __init__(self, edge):
        if edge <= 0:
            raise ValueError("Edge length must be a positive value")
        super().__init__(edge, edge)

    def adjust_sides(self, edge):
        if edge <= 0:
            raise ValueError("Edge length must be a positive value")
        super().adjust_sides(edge, edge)

    def check_rhombus(self):
        return self.a == self.b == self.c == self.d


# Verification Tests
def validate_shapes():
    # Validate Parallelogram (Rectangle)
    para = Parallelogram(4, 5)
    assert para.surface_area() == 20
    assert para.total_perimeter() == 18
    assert para.check_parallelogram() == True

    para.adjust_sides(6, 7)
    assert para.surface_area() == 42
    assert para.total_perimeter() == 26
    assert para.check_parallelogram() == True

    # Validate Rhombus (Square)
    rhom = Rhombus(5)
    assert rhom.surface_area() == 25
    assert rhom.total_perimeter() == 20
    assert rhom.check_rhombus() == True

    rhom.adjust_sides(7)
    assert rhom.surface_area() == 49
    assert rhom.total_perimeter() == 28
    assert rhom.check_rhombus() == True

    # Validate error handling
    try:
        Parallelogram(-1, 5)
    except ValueError as err:
        assert str(err) == "Length and breadth must be positive values"

    try:
        Rhombus(0)
    except ValueError as err:
        assert str(err) == "Edge length must be a positive value"

    print("All validations successful!")

validate_shapes()

# Find numbers from 1 to 10000 whose cubes are perfect squares

import math
from concurrent.futures import ThreadPoolExecutor

def check_perfect_square(value):
    integer_root = int(math.isqrt(value))
    return integer_root * integer_root == value

def compute_cube_and_check(n):
    cubed_value = n * n * n
    if check_perfect_square(cubed_value):
        square_root = int(math.isqrt(cubed_value))
        return (n, cubed_value, square_root)
    return (n, cubed_value, None)

def run_computation(start_num, end_num, thread_count=4):
    output_list = []
    with ThreadPoolExecutor(max_workers=thread_count) as pool:
        submitted_tasks = {pool.submit(compute_cube_and_check, i): i for i in range(start_num, end_num + 1)}
        for task in submitted_tasks:
            number, cube_val, root_val = task.result()
            output_list.append((number, cube_val, root_val))
    return output_list

def execute_program():
    begin_range = 1
    finish_range = 10000
    threads_used = 4
    computed_data = run_computation(begin_range, finish_range, threads_used)
    for num, cube, root in computed_data:
        print(f"Value: {num}, Cube: {cube}, Root: {root}")

if __name__ == "__main__":
    execute_program()

