# PDF utility script to extract text or retrieve metadata

import argparse
import json
import fitz  # Alternative import name for PyMuPDF

def get_document_content(file_path, page_limit=None):
    try:
        document = fitz.open(file_path)
        content = ""
        for idx, page in enumerate(document):
            if page_limit is not None and idx >= int(page_limit):
                break
            content += page.get_text() + "\n"
        return content.strip()
    except Exception as error:
        return f"Error: {str(error)}"

def fetch_pdf_info(file_path):
    try:
        document = fitz.open(file_path)
        return document.metadata
    except Exception as error:
        return {"error": str(error)}

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Process PDF files")
    parser.add_argument("action", choices=["extract", "metadata"])
    parser.add_argument("source_file")
    parser.add_argument("--limit_pages", type=int, default=None)

    parsed_args = parser.parse_args()

    if parsed_args.action == "extract":
        print(get_document_content(parsed_args.source_file, parsed_args.limit_pages))
    elif parsed_args.action == "metadata":
        print(json.dumps(fetch_pdf_info(parsed_args.source_file), indent=2))

# Merge suggestions API router -- cluster analysis for face grouping recommendations.
"""
from fastapi import APIRouter, Depends, HTTPException, Query
from api.auth import CurrentUser, require_authenticated
from api.config import VIEWER_CONFIG
from db import DEFAULT_DB_PATH

router = APIRouter(tags=["merge_suggestions"])

@router.get("/api/merge_suggestions")
async def fetch_merge_recommendations(
    min_confidence: float = Query(0.6, ge=0.0, le=1.0),
    authenticated_user: CurrentUser = Depends(require_authenticated),
):
    """Generate merge recommendations by analyzing clusters of similar faces."""

    # Verify if the feature is active
    if not VIEWER_CONFIG.get("features", {}).get("enable_face_clustering", True):
        raise HTTPException(status_code=403, detail="Face clustering feature is currently disabled")

    # Import only when needed (lazy loading)
    from faces import identify_cluster_groups
    clusters = identify_cluster_groups(DEFAULT_DB_PATH, min_confidence)

    # Transform clusters into pairwise comparison objects
    recommendations = []
    for cluster in clusters:
        individuals = cluster.get("members", [])
        confidence_score = cluster.get("mean_similarity", 0.0)

        # Generate pairwise comparisons between consecutive individuals in each cluster
        for idx in range(len(individuals) - 1):
            recommendations.append({
                "candidate_a": {
                    "identifier": individuals[idx]["id"],
                    "label": individuals[idx].get("name"),
                    "face_count": individuals[idx].get("face_count", 0),
                },
                "candidate_b": {
                    "identifier": individuals[idx + 1]["id"],
                    "label": individuals[idx + 1].get("name"),
                    "face_count": individuals[idx + 1].get("face_count", 0),
                },
                "confidence": confidence_score,
            })

    return {"recommendations": recommendations}

# Decorator to ensure only one instance of a class exists

_instance_cache = {}

def singleton_decorator(cls):
    def create_or_get(*parameters, **keyword_parameters):
        if cls not in _instance_cache:
            _instance_cache[cls] = cls(*parameters, **keyword_parameters)
        return _instance_cache[cls]
    return create_or_get

import re

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    def transform_spaces(match):
        space_sequence = match.group(0)
        if len(space_sequence) > 2:
            return '-'
        else:
            return '_' * len(space_sequence)

    pattern = r' +'
    return re.sub(pattern, transform_spaces, text)

