# Secure credential management module for API keys

import os

try:
    import keyring as _keyring
    KEYRING_ENABLED = True
except ImportError:
    KEYRING_ENABLED = False

SERVICE_IDENTIFIER = "skylos"
API_KEY_MAPPING = {
    "openai": "OPENAI_API_KEY",
    "anthropic": "ANTHROPIC_API_KEY",
    "google": "GEMINI_API_KEY",
    "mistral": "MISTRAL_API_KEY",
    "groq": "GROQ_API_KEY",
    "xai": "XAI_API_KEY",
    "together": "TOGETHER_API_KEY",
    "deepseek": "DEEPSEEK_API_KEY",
}

def store_credential(provider_name, api_key_value):
    if not KEYRING_ENABLED:
        print("[warning] 'keyring' library unavailable. Cannot securely store credentials.")
        return False

    try:
        _keyring.set_password(SERVICE_IDENTIFIER, provider_name, api_key_value)
        return True
    except Exception as error:
        print(f"[warning] Unable to save credential in keyring: {error}")
        return False

def retrieve_credential(provider_name):
    # First check environment variable
    env_key_name = API_KEY_MAPPING.get(provider_name)
    if env_key_name:
        env_value = os.environ.get(env_key_name)
        if env_value:
            return env_value

    # Then attempt keyring lookup if available
    if KEYRING_ENABLED:
        try:
            return _keyring.get_password(SERVICE_IDENTIFIER, provider_name)
        except Exception:
            pass

    return None

def remove_credential(provider_name):
    if not KEYRING_ENABLED:
        return False

    service_id = "skylos"
    user_label = str(provider_name)

    try:
        _keyring.delete_password(service_id, user_label)
        return True
    except Exception:
        return False

def available_providers():
    return list(API_KEY_MAPPING.keys())

import json
import sys
from dataclasses import dataclass

@dataclass
class BoundingBoxInfo:
    bounds: list[float]
    kind: str
    field_data: dict

def validate_bounding_boxes(json_input) -> list[str]:
    output_lines = []
    try:
        data = json.load(json_input)
    except json.JSONDecodeError as e:
        return [f"ERROR: Invalid JSON input - {e}"]

    form_fields = data.get("form_fields", [])
    output_lines.append(f"Parsed {len(form_fields)} form fields")

    def boxes_overlap(box_a, box_b):
        # Check if two axis-aligned rectangles do NOT overlap
        no_horizontal_overlap = box_a[0] >= box_b[2] or box_a[2] <= box_b[0]
        no_vertical_overlap = box_a[1] >= box_b[3] or box_a[3] <= box_b[1]
        return not (no_horizontal_overlap or no_vertical_overlap)

    # Collect all bounding boxes (labels and entries)
    collected_boxes = []
    for field in form_fields:
        label_box = field.get("label_bounding_box", [])
        entry_box = field.get("entry_bounding_box", [])
        collected_boxes.append(BoundingBoxInfo(label_box, "label", field))
        collected_boxes.append(BoundingBoxInfo(entry_box, "entry", field))

    encountered_issues = False
    total_checks = len(collected_boxes)

    # Compare each pair of boxes once
    for idx1 in range(total_checks):
        current = collected_boxes[idx1]

        for idx2 in range(idx1 + 1, total_checks):
            candidate = collected_boxes[idx2]

            # Only compare boxes on the same page
            if current.field_data.get("page_number") == candidate.field_data.get("page_number"):
                if boxes_overlap(current.bounds, candidate.bounds):
                    encountered_issues = True

                    # Distinguish same-field vs cross-field intersections
                    if current.field_data is candidate.field_data:
                        desc = current.field_data.get("description", "unknown")
                        output_lines.append(
                            f"FAILURE: Overlap between label and entry boxes for '{desc}' "
                            f"({current.bounds}, {candidate.bounds})"
                        )
                    else:
                        desc1 = current.field_data.get("description", "unknown")
                        desc2 = candidate.field_data.get("description", "unknown")
                        output_lines.append(
                            f"FAILURE: Overlap between {current.kind} box for '{desc1}' "
                            f"({current.bounds}) and {candidate.kind} box for '{desc2}' "
                            f"({candidate.bounds})"
                        )

                    # Limit number of reported errors to avoid overwhelming output
                    if len(output_lines) >= 20:
                        output_lines.append("Halting further analysis; resolve issues and re-run")
                        return output_lines

    # Additional validation: check entry box height against font size
    for box_info in collected_boxes:
        if box_info.kind == "entry":
            text_info = box_info.field_data.get("entry_text", {})
            font_size = text_info.get("font_size", 14)
            actual_height = box_info.bounds[3] - box_info.bounds[1]

            if actual_height < font_size:
                encountered_issues = True
                desc = box_info.field_data.get("description", "unknown")
                output_lines.append(
                    f"FAILURE: Entry box for '{desc}' has insufficient height ({actual_height:.2f}) "
                    f"for font size {font_size}. Please increase box height or reduce font size."
                )

                if len(output_lines) >= 20:
                    output_lines.append("Halting further analysis; resolve issues and re-run")
                    return output_lines

    if not encountered_issues:
        output_lines.append("SUCCESS: All bounding boxes meet requirements")

    return output_lines


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python validate_bounding_boxes.py fields.json")
        sys.exit(1)

    with open(sys.argv[1], 'r') as file_handle:
        results = validate_bounding_boxes(file_handle)

    for line in results:
        print(line)

