# Implementation of unsigned varint encoding and decoding

MAX_UVARINT = (1 << 64) - 1

def encode_unsigned_varint(number: int) -> bytes:
    """Encode a non-negative integer into its canonical varint representation."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("input must be an integer")
    if number < 0:
        raise ValueError("input must be non-negative")
    if number > MAX_UVARINT:
        raise ValueError("input must not exceed 2^64 - 1")

    result = bytearray()
    while True:
        segment = number & 0x7F
        number >>= 7
        if number > 0:
            result.append(segment | 0x80)
        else:
            result.append(segment)
            break
    return bytes(result)

def decode_unsigned_varint(buffer: bytes, offset: int) -> tuple[int, int]:
    """Decode a varint from the buffer starting at the given offset, validating canonical form."""
    if offset < 0:
        raise ValueError("offset must be non-negative")

    decoded_value = 0
    bit_position = 0
    current_index = offset

    while True:
        if current_index >= len(buffer):
            raise ValueError("insufficient data for varint")

        current_byte = buffer[current_index]
        data_bits = current_byte & 0x7F

        # Check for overflow in most significant bits
        if bit_position == 63 and data_bits > 1:
            raise ValueError("varint value exceeds 64-bit limit")

        current_index += 1
        decoded_value |= data_bits << bit_position

        # Check continuation bit
        if (current_byte & 0x80) == 0:
            # Verify canonical encoding by re-encoding and comparing
            expected_bytes = encode_unsigned_varint(decoded_value)
            actual_segment = buffer[offset:current_index]
            if expected_bytes != actual_segment:
                raise ValueError("non-canonical varint encoding detected")
            return decoded_value, current_index

        bit_position += 7
        if bit_position > 63:
            raise ValueError("varint too long (exceeds 64 bits)")

# WebSocket notification system with user-specific and global messaging

from typing import Dict, List, Any
import json
import asyncio

class ConnectionHandler:
    def __init__(self):
        self.user_connections: Dict[str, List[Any]] = {}

    async def add_connection(self, websocket: Any, user_identifier: str):
        await websocket.accept()
        if user_identifier not in self.user_connections:
            self.user_connections[user_identifier] = []
        self.user_connections[user_identifier].append(websocket)

    def remove_connection(self, websocket: Any, user_identifier: str):
        if user_identifier in self.user_connections:
            if websocket in self.user_connections[user_identifier]:
                self.user_connections[user_identifier].remove(websocket)

    async def deliver_to_user(self, payload: dict, user_identifier: str):
        if user_identifier in self.user_connections:
            for connection in self.user_connections[user_identifier]:
                await connection.send_json(payload)

    async def send_to_all(self, payload: dict):
        for user_identifier in self.user_connections:
            for connection in self.user_connections[user_identifier]:
                await connection.send_json(payload)

handler = ConnectionHandler()

MESSAGE_TEMPLATES = {
    "exam_result": "Exam results are available",
    "achievement": "New achievement unlocked!",
    "journal_reminder": "Time for journal reflection",
    "profile_update": "Your profile has been updated",
}

async def handle_websocket(websocket: Any, user_id: str):
    await handler.add_connection(websocket, user_id)
    try:
        while True:
            raw_data = await websocket.receive_text()
            parsed_message = json.loads(raw_data)
            if parsed_message.get("action") == "ping":
                await websocket.send_json({"action": "pong"})
    except Exception:
        handler.remove_connection(websocket, user_id)

async def notify_user(user_id: str, message_type: str, extra_data: dict = None):
    timestamp = asyncio.get_event_loop().time() if hasattr(asyncio.get_event_loop(), 'time') else 0
    payload = {
        "type": message_type,
        "content": MESSAGE_TEMPLATES.get(message_type, "Notification"),
        "metadata": extra_data or {},
        "timestamp": timestamp,
    }
    await handler.deliver_to_user(payload, user_id)

async def global_notify(message_type: str, extra_data: dict = None):
    payload = {
        "type": message_type,
        "content": MESSAGE_TEMPLATES.get(message_type, "Notification"),
        "metadata": extra_data or {},
    }
    await handler.send_to_all(payload)

# Alternative implementation with equivalent functionality but different structure

def check_lora_enabled():
    from megatron.training import get_args
    config = get_args()
    return hasattr(config, 'lora_target_modules') and bool(config.lora_target_modules)

def should_save_full_weights():
    from megatron.training import get_args
    config = get_args()
    model_config = getattr(config, 'mm_model', None)
    if model_config is None:
        return False
    return getattr(model_config, 'lora_save_full_weight', False)

def combine_dictionaries(dict_a, dict_b):
    combined = dict_a.copy()
    for key, val in dict_b.items():
        if (key in combined and 
            isinstance(combined[key], dict) and 
            isinstance(val, dict)):
            combined[key] = combine_dictionaries(combined[key], val)
        else:
            combined[key] = val
    return combined

def transform_state_dict_keys(state_dict, forbidden_terms):
    from megatron.training import get_args
    updated_dict = {}
    args = get_args()

    for original_key, value in state_dict.items():
        key_str = str(original_key)

        # Check if any forbidden term appears in the key
        has_forbidden_term = any(term in key_str for term in forbidden_terms)

        # Check if this key corresponds to a trainable target module's bias or weight
        is_trainable_bias = any(
            key_str == f"{module}.bias" 
            for module in args.lora_trainable_target_modules
        )
        is_trainable_weight = any(
            key_str == f"{module}.weight" 
            for module in args.lora_trainable_target_modules
        )

        new_key = key_str

        # Apply transformation only if key passes both conditions
        if not has_forbidden_term and (is_trainable_bias or is_trainable_weight):
            if '.weight' in key_str:
                new_key = key_str.replace('.weight', '.base_layer.weight')
            elif '.bias' in key_str:
                new_key = key_str.replace('.bias', '.base_layer.bias')

        updated_dict[new_key] = value

    return updated_dict

def strip_base_layer_prefix(state_dict):
    if not isinstance(state_dict, dict):
        return {}

    key_translations = {}
    keys_to_process = list(state_dict.keys())

    for current_key in keys_to_process:
        if '.base_layer.' in current_key:
            stripped_key = current_key.replace('.base_layer.', '.')
            key_translations[current_key] = stripped_key
            state_dict[stripped_key] = state_dict.pop(current_key)

    return key_translations

def reinstate_base_layer_prefix(transformed_dict, translation_map):
    if not isinstance(transformed_dict, dict) or not isinstance(translation_map, dict):
        return

    reverse_map = {v: k for k, v in translation_map.items()}
    current_keys = list(transformed_dict.keys())

    for current_key in current_keys:
        original_key = reverse_map.get(current_key, current_key)
        if original_key != current_key:
            transformed_dict[original_key] = transformed_dict.pop(current_key)

