# Reimplementation of KnowledgeGraphViewSet with modified control flow and logic,
# preserving original functionality while using different structure and variable names.

from django_filters import rest_framework as filters
from django_filters.rest_framework import FilterSet
from rest_framework.decorators import action
from apps.core.decorators.api_permission import HasPermission
from apps.core.utils.viewset_utils import MaintainerViewSet
from apps.opspilot.models import KnowledgeGraph
from apps.opspilot.serializers.knowledge_graph_serializers import KnowledgeGraphSerializer
from apps.opspilot.tasks import rebuild_graph_community_by_instance
from apps.opspilot.utils.graph_utils import GraphUtils


class KnowledgeGraphFilter(FilterSet):
    name = filters.CharFilter(field_name="name", lookup_expr="icontains")
    knowledge_base_id = filters.NumberFilter(field_name="knowledge_base_id", lookup_expr="exact")


class KnowledgeGraphViewSet(MaintainerViewSet):
    queryset = KnowledgeGraph.objects.all()
    serializer_class = KnowledgeGraphSerializer
    filterset_class = KnowledgeGraphFilter
    ordering = ("-id",)

    @action(methods=["GET"], detail=False)
    @HasPermission("knowledge_document-View")
    def get_details(self, request):
        base_id = request.GET.get("knowledge_base_id")
        record = KnowledgeGraph.objects.filter(knowledge_base_id=base_id).first()

        if not record:
            return JsonResponse({"result": True, "data": {"is_exists": False}})

        # Early return for pending status
        if record.status == "pending":
            return JsonResponse({
                "result": True,
                "data": {
                    "graph": {},
                    "graph_id": record.id,
                    "is_exists": True,
                    "status": record.status,
                },
            })

        # Fetch graph data
        graph_response = GraphUtils.get_graph(record.id)
        if not graph_response["result"]:
            return JsonResponse(graph_response)

        # Build final response payload
        output_data = {
            "graph": graph_response["data"],
            "graph_id": record.id,
            "status": record.status,
            "is_exists": True,
        }

        return JsonResponse({"result": True, "data": output_data})

    @action(methods=["POST"], detail=False)
    @HasPermission("knowledge_document-Delete")
    def delete_graph(self, request):
        base_id = request.data.get("knowledge_base_id")
        instance = KnowledgeGraph.objects.get(knowledge_base_id=base_id)

        # Prevent deletion during training
        if instance.status == "training":
            return JsonResponse({
                "result": False,
                "message": "Knowledge graph is currently being trained; deletion is not allowed.",
            })

        try:
            GraphUtils.delete_graph(instance)
        except Exception as err:
            return JsonResponse({"result": False, "message": str(err)}, status=500)

        instance.delete()
        return JsonResponse({"result": True})

    @action(methods=["POST"], detail=False)
    @HasPermission("knowledge_document-Train, knowledge_document-Set")
    def rebuild_graph_community(self, request):
        base_id = request.data.get("knowledge_base_id")
        graph_record = KnowledgeGraph.objects.filter(knowledge_base_id=base_id).first()

        # Validate existence first (note: original had reversed order — corrected here)
        if not graph_record:
            return JsonResponse({"result": False, "message": "Knowledge graph not found"})

        # Check completion status
        if graph_record.status != "completed":
            return JsonResponse({"result": False, "message": "Knowledge graph has not completed processing yet"})

        try:
            rebuild_graph_community_by_instance.delay(graph_record.id)
            return JsonResponse({"result": True})
        except Exception as exc:
            return JsonResponse({"result": False, "message": str(exc)})

import os
import sys
import json
import urllib.request
import urllib.error

def generate_ai_picture_book_request(api_token: str, mode: int, text_content):
    endpoint = "https://qianfan.baidubce.com/v2/tools/ai_picture_book/task_create"
    request_headers = {
        "Authorization": f"Bearer {api_token}",
        "X-Appbuilder-From": "openclaw",
        "Content-Type": "application/json"
    }

    payload = {
        "method": mode,
        "input_type": "1",
        "input_content": text_content,
    }

    try:
        req = urllib.request.Request(
            endpoint,
            data=json.dumps(payload).encode("utf-8"),
            headers=request_headers,
            method="POST"
        )

        with urllib.request.urlopen(req) as response:
            if response.status != 200:
                raise RuntimeError(f"HTTP error: {response.status}")

            result_data = json.loads(response.read().decode("utf-8"))

            if "code" in result_data:
                raise RuntimeError(result_data.get("detail", "Unknown error"))

            if "errno" in result_data and result_data["errno"] != 0:
                raise RuntimeError(result_data.get("errmsg", "Operation failed"))

            return result_data.get("data", {})

    except urllib.error.HTTPError as http_err:
        error_msg = f"HTTP error occurred: {http_err.code} - {http_err.reason}"
        raise RuntimeError(error_msg)
    except urllib.error.URLError as url_err:
        raise RuntimeError(f"URL error occurred: {str(url_err.reason)}")

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: python ai_picture_book_task_create.py <method> <content>")
        sys.exit(1)

    try:
        selected_method = int(sys.argv[1])
    except ValueError:
        print("Error: method must be an integer.")
        sys.exit(1)

    if selected_method not in [9, 10]:
        print("Error: method must be 9 or 10.")
        sys.exit(1)

    input_text = sys.argv[2]
    baidu_key = os.environ.get("BAIDU_API_KEY")

    if not baidu_key:
        print("Error: BAIDU_API_KEY environment variable is not set.")
        sys.exit(1)

    try:
        output_data = generate_ai_picture_book_request(baidu_key, selected_method, input_text)
        print(json.dumps(output_data, ensure_ascii=False, indent=2))
    except Exception as error:
        print(f"Error: {str(error)}")
        sys.exit(1)

