class UIPage:
    parent = None

    def __init__(self, icon_check: Union[ImgIcon, Text, List]):
        self.connections = {}
        self.identifier = get_name_from_caller(depth=2)
        self.validation_items = []

        if isinstance(icon_check, list):
            self.validation_items = icon_check
        elif isinstance(icon_check, (ImgIcon, Text)):
            self.validation_items.append(icon_check)

    def __eq__(self, other):
        return self.identifier == other.identifier

    def __hash__(self):
        return hash(self.identifier)

    def __str__(self):
        return self.identifier

    def connect(self, control, target_page):
        """

        control:Button/Str
        """
        self.connections[target_page] = control

    def is_active_page(self, interpreter):
        for item in self.validation_items:
            detected = False

            if isinstance(item, ImgIcon):
                detected = interpreter.check_image_presence(item)
            elif isinstance(item, Text):
                detected = interpreter.verify_text_presence(item)

            if detected:
                return True

        return False

    def append_validation_item(self, new_item: ImgIcon):
        self.validation_items.append(new_item)

class TitlePage(UIPage):
    def __init__(self, page_title: str):
        self.identifier = get_name_from_caller(depth=2)
        self.header = page_title
