import importlib
import inspect

def extract_public_names(module) -> list:
    """Extract public names from a module, respecting __all__ if present."""
    # Check for __all__ attribute and validate its type
    if hasattr(module, "__all__") and isinstance(module.__all__, (list, tuple)):
        return list(module.__all__)

    def is_public_identifier(name: str) -> bool:
        # Skip private names (starting with underscore)
        if name.startswith("_"):
            return False
        # Skip modules imported in the namespace
        try:
            return not inspect.ismodule(getattr(module, name))
        except AttributeError:
            return True

    # Filter and sort public identifiers
    return sorted(filter(is_public_identifier, dir(module)))

def collect_module_symbols(module_path: str):
    """Recursively collect symbols from a module and its submodules."""
    current_module = importlib.import_module(module_path)
    public_items = extract_public_names(current_module)

    result_list = []
    for item_name in public_items:
        item_obj = getattr(current_module, item_name)

        # If it's a submodule, recurse into it
        if inspect.ismodule(item_obj):
            submodule_result = collect_module_symbols(f"{module_path}.{item_name}")
            result_list.append(submodule_result)
        else:
            result_list.append(item_name)

    # Extract base module name
    base_name = module_path.split(".")[-1]
    return (base_name, result_list)

def display_hierarchy(symbol_tree, level=0):
    """Display the symbol hierarchy in an indented format."""
    module_name, contents = symbol_tree[0], symbol_tree[1]
    print(f"{'   ' * level}{module_name}:")

    # Separate symbols and submodules
    leaf_nodes = []
    branch_nodes = []

    for item in contents:
        if isinstance(item, str):
            leaf_nodes.append(item)
        else:
            branch_nodes.append(item)

    # Sort both lists
    leaf_nodes.sort()
    branch_nodes.sort(key=lambda x: x[0])

    # Print leaf nodes
    for leaf in leaf_nodes:
        print(f"{'   ' * (level + 1)}{leaf}")

    print()  # Blank line between sections

    # Recursively print branches
    for branch in branch_nodes:
        display_hierarchy(branch, level=level + 1)

# Start the process with the 'newton' module
display_hierarchy(collect_module_symbols("newton"))

# Custom rounding function with specific handling for .5 cases
def custom_round(value):
    number = float(value)

    if number >= 0:
        # For non-negative numbers
        integer_part = int(number)
        fractional_part = number - integer_part

        if abs(fractional_part - 0.5) < 1e-10:  # Check if fractional part is 0.5
            return integer_part + 1
        else:
            return round(number)
    else:
        # For negative numbers
        integer_part = int(number)
        fractional_part = number - integer_part

        # For negative numbers, check if we're exactly 0.5 above the next lower integer
        if abs(fractional_part + 0.5) < 1e-10:  # Equivalent to int(num) - num == 0.5 for negatives
            return integer_part - 1
        else:
            return round(number)

