import sys
import requests
import json
import argparse
from xml.etree import ElementTree as ET
from textblob import TextBlob

CRYPTO_FEEDS = [
    "https://cointelegraph.com/rss",
    "https://www.coindesk.com/arc/outboundfeeds/rss/"
]

def get_news_items(feed_url, max_count=5):
    articles = []
    try:
        response = requests.get(feed_url, timeout=10)
        if response.status_code == 200:
            tree = ET.fromstring(response.content)
            counter = 0
            for entry in tree.findall('.//item'):
                if counter >= max_count:
                    break

                title_elem = entry.find('title')
                desc_elem = entry.find('description')

                headline = title_elem.text.strip() if title_elem is not None and title_elem.text else "Untitled"
                summary = desc_elem.text.strip() if desc_elem is not None and desc_elem.text else ""

                articles.append({
                    "origin": feed_url,
                    "headline": headline,
                    "summary": (summary[:200] + "...") if len(summary) > 200 else summary
                })
                counter += 1
    except Exception as error:
        print(f"Failed to retrieve {feed_url}: {error}", file=sys.stderr)
    return articles

def determine_sentiment(text_content):
    analysis = TextBlob(text_content)
    return analysis.sentiment.polarity

def main():
    parser = argparse.ArgumentParser(description='Collect cryptocurrency updates and assess sentiment.')
    args = parser.parse_args()

    aggregated_articles = []
    for source in CRYPTO_FEEDS:
        aggregated_articles.extend(get_news_items(source))

    enriched_articles = []
    for article in aggregated_articles:
        polarity = determine_sentiment(article['headline'] + " " + article['summary'])

        if polarity > 0.1:
            classification = "POSITIVE"
        elif polarity < -0.1:
            classification = "NEGATIVE"
        else:
            classification = "NEUTRAL"

        enriched_articles.append({
            "headline": article['headline'],
            "sentiment_value": round(polarity, 2),
            "sentiment_category": classification
        })

    print(json.dumps(enriched_articles, indent=2))

if __name__ == "__main__":
    main()

import ast
import sys
from skylos.rules.danger.taint import TaintVisitor

# Define known redirect functions that may be vulnerable to open redirects
REDIRECT_FUNCTIONS = {"redirect", "HttpResponseRedirect", "HttpResponsePermanentRedirect"}

class _OpenRedirectAnalyzer(TaintVisitor):
    def visit_Call(self, node):
        # Determine the function name being called
        target_func = None
        if isinstance(node.func, ast.Name):
            target_func = node.func.id
        elif isinstance(node.func, ast.Attribute):
            target_func = node.func.attr

        # Check if this is a redirect call with arguments
        if target_func in REDIRECT_FUNCTIONS and len(node.args) > 0:
            url_param = node.args[0]

            # If the URL parameter is tainted (user-controlled), flag as potential vulnerability
            if self.is_tainted(url_param):
                self.findings.append({
                    "rule_id": "SKY-D230",
                    "severity": "HIGH",
                    "message": "Potential open redirect: untrusted URL input used in redirection.",
                    "file": str(self.file_path),
                    "line": node.lineno,
                    "col": node.col_offset,
                    "symbol": self._current_symbol(),
                })

        # Continue traversing the AST tree
        self.generic_visit(node)

def analyze_redirect_flow(tree, source_file, findings_list):
    try:
        analyzer = _OpenRedirectAnalyzer(source_file, findings_list)
        analyzer.visit(tree)
    except Exception as error:
        print(f"Open redirect analysis failed for {source_file}: {error}", file=sys.stderr)

import os
import sys
import json
import urllib.request
import urllib.error

def fetch_ai_note_data(api_token: str, task_identifier: str) -> dict:
    endpoint = "https://qianfan.baidubce.com/v2/tools/ai_note/query"
    request_headers = {
        "Authorization": f"Bearer {api_token}",
        "Content-Type": "application/json"
    }
    query_params = urllib.parse.urlencode({"task_id": task_identifier})
    full_url = f"{endpoint}?{query_params}"

    req = urllib.request.Request(full_url, headers=request_headers)
    try:
        with urllib.request.urlopen(req) as response:
            raw_data = response.read().decode('utf-8')
            parsed_result = json.loads(raw_data)
    except urllib.error.HTTPError as e:
        error_body = e.read().decode('utf-8')
        raise RuntimeError(f"HTTP error {e.code}: {error_body}")
    except urllib.error.URLError as e:
        raise RuntimeError(f"URL error: {e.reason}")

    if "code" in parsed_result:
        raise RuntimeError(parsed_result.get("detail", "Unknown error"))

    error_code = parsed_result.get("errno")
    if error_code == 10000:
        print(f"Task status code: {error_code}, message: {parsed_result.get('show_msg', '')}")
        return {}

    if error_code is not None and error_code != 0:
        raise RuntimeError(parsed_result.get("show_msg", "Unknown error occurred"))

    return parsed_result.get("data", {})

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python ai_notes_task_query.py <task_id>")
        sys.exit(1)

    target_task_id = sys.argv[1]
    baidu_api_key = os.getenv("BAIDU_API_KEY")

    if not baidu_api_key:
        print("Error: BAIDU_API_KEY must be set in environment variables.")
        sys.exit(1)

    try:
        task_data = fetch_ai_note_data(baidu_api_key, target_task_id)
        print(json.dumps(task_data, ensure_ascii=False, indent=2))
    except Exception as error:
        print(f"Error: {str(error)}")
        sys.exit(1)

def format_api_error(message: str) -> str:
    return f"API Error: {message}"

def process_volc_response(response_data: dict) -> str:
    # Check if response has error information by traversing nested attributes
    try:
        if response_data and hasattr(response_data, 'ResponseMetadata'):
            metadata = response_data.ResponseMetadata
            if metadata and hasattr(metadata, 'Error'):
                error_info = metadata.Error
                if error_info and hasattr(error_info, 'Message'):
                    return format_api_error(error_info.Message)
    except AttributeError:
        pass

    # Return string representation if no error found or access fails
    return str(response_data)

import logging
import functools
from torch.utils.checkpoint import checkpoint
from mindspeed.fsdp.utils.log import print_rank
from mindspeed.fsdp.utils.str_match import module_name_match

logger = logging.getLogger(__name__)

def apply_gradient_checkpointing(model, config):
    target_modules = collect_affected_modules(model, config.target_module_patterns)

    for module_path, layer in target_modules:
        print_rank(logger.info, f"Enabling gradient checkpointing for: {module_path}")
        layer.forward = create_checkpointed_forward(layer.forward, config.reentrant_mode)

    return model

def collect_affected_modules(root_module, patterns):
    found_layers = []

    for pattern in patterns:
        for path, layer in root_module.named_modules():
            if module_name_match(pattern, path):
                found_layers.append((path, layer))

    if not found_layers:
        raise RuntimeError(f'[GradientCheckpointing] No modules matched the specified patterns: {patterns}')

    return found_layers

def create_checkpointed_forward(original_func, use_reentrant_flag):
    def modified_forward(*args, **kwargs):
        # Clear KV cache to avoid checkpointing issues with transformers
        kwargs['past_key_values'] = None

        if not use_reentrant_flag:
            return checkpoint(original_func, *args, use_reentrant=False, **kwargs)
        else:
            partial_func = functools.partial(original_func, **kwargs)
            return checkpoint(partial_func, *args, use_reentrant=True)

    return modified_forward

import copy
from enum import Enum, auto
from typing import List, Optional, Any, Tuple

class SamplingParams:
    def __init__(self,
                 temperature: float = 1.0,
                 max_tokens: int = 128,
                 ignore_eos: bool = False):
        self.temperature = temperature
        self.max_tokens = max_tokens
        self.ignore_eos = ignore_eos


class SequenceState(Enum):
    PENDING = auto()
    ACTIVE = auto()
    TERMINATED = auto()


class TokenSequence:
    DEFAULT_BLOCK_SIZE = 256
    _id_counter: List[int] = [0]

    def __init__(self,
                 initial_tokens: List[int],
                 params: Optional[SamplingParams] = None):
        if params is None:
            params = SamplingParams()

        self._sequence_id = self._generate_unique_id()
        self._current_state = SequenceState.PENDING
        self._tokens = copy.copy(initial_tokens)
        self._last_token_id = self._tokens[-1] if self._tokens else None
        self._total_token_count = len(self._tokens)
        self._prompt_length = len(initial_tokens)
        self._cached_token_count = 0
        self._block_mapping = []
        self._sampling_temp = params.temperature
        self._max_gen_len = params.max_tokens
        self._skip_eos_check = params.ignore_eos
        self._enable_pre_verification = True
        self._accumulated_token_counts: List[int] = []
        self._current_accumulated = 0

    @classmethod
    def _generate_unique_id(cls) -> int:
        current_id = cls._id_counter[0]
        cls._id_counter[0] += 1
        return current_id

    def __len__(self) -> int:
        return self._total_token_count

    def __getitem__(self, index: int) -> int:
        return self._tokens[index]

    @property
    def is_complete(self) -> bool:
        return self._current_state == SequenceState.TERMINATED

    @property
    def generated_token_count(self) -> int:
        return self._total_token_count - self._prompt_length

    @property
    def prompt_ids(self) -> List[int]:
        return self._tokens[:self._prompt_length]

    @property
    def output_ids(self) -> List[int]:
        return self._tokens[self._prompt_length:]

    @property
    def cached_block_count(self) -> int:
        return self._cached_token_count // self.DEFAULT_BLOCK_SIZE

    @property
    def total_blocks_needed(self) -> int:
        return (self._total_token_count + self.DEFAULT_BLOCK_SIZE - 1) // self.DEFAULT_BLOCK_SIZE

    @property
    def tokens_in_last_block(self) -> int:
        full_blocks = (self.total_blocks_needed - 1) * self.DEFAULT_BLOCK_SIZE
        return self._total_token_count - full_blocks

    def get_block(self, block_index: int) -> List[int]:
        if not (0 <= block_index < self.total_blocks_needed):
            raise IndexError(f"Block index {block_index} out of range [0, {self.total_blocks_needed})")
        start = block_index * self.DEFAULT_BLOCK_SIZE
        end = start + self.DEFAULT_BLOCK_SIZE
        return self._tokens[start:end]

    def add_token(self, token_value: int) -> None:
        self._tokens.append(token_value)
        self._last_token_id = token_value
        self._total_token_count += 1

    def revert_tokens(self, count: int) -> None:
        if count <= 0:
            raise ValueError("Revert count must be positive.")
        if count > self._total_token_count:
            raise ValueError("Cannot revert more tokens than present.")
        self._tokens = self._tokens[:-count]
        self._last_token_id = self._tokens[-1]
        self._total_token_count -= count

    def map_token_to_slot(self, token_pos: int) -> int:
        block_idx = token_pos // self.DEFAULT_BLOCK_SIZE
        offset_in_block = token_pos % self.DEFAULT_BLOCK_SIZE
        base_block_address = self._block_mapping[block_idx]
        return base_block_address * self.DEFAULT_BLOCK_SIZE + offset_in_block

    def state_for_serialization(self) -> Tuple[Any, ...]:
        return (
            self._total_token_count,
            self._prompt_length,
            self._cached_token_count,
            tuple(self._block_mapping),
            self._sampling_temp,
            self._skip_eos_check,
            self._max_gen_len,
            self._sequence_id,
            self._enable_pre_verification,
            tuple(self._accumulated_token_counts),
            self._current_accumulated,
            tuple(self._tokens) if self.generated_token_count == 0 else self._last_token_id
        )

    def restore_from_state(self, serialized: Tuple[Any, ...]) -> None:
        (
            self._total_token_count,
            self._prompt_length,
            self._cached_token_count,
            self._block_mapping,
            self._sampling_temp,
            self._skip_eos_check,
            self._max_gen_len,
            self._sequence_id,
            self._enable_pre_verification,
            self._accumulated_token_counts,
            self._current_accumulated,
            last_or_full = serialized[-1]
        ) = serialized[:-1]

        if self.generated_token_count == 0:
            self._tokens = list(last_or_full)
        else:
            self._last_token_id = last_or_full

