def format_api_error(error_message: str) -> str:
    return f"API Error: {error_message}"

def process_volc_response(api_response: dict):
    # Check if response exists and contains error information
    if not api_response:
        return str(api_response)

    if not hasattr(api_response, "ResponseMetadata"):
        return str(api_response)

    metadata = getattr(api_response, "ResponseMetadata", None)
    if not metadata:
        return str(api_response)

    if not hasattr(metadata, "Error"):
        return str(api_response)

    error_obj = getattr(metadata, "Error", None)
    if not error_obj:
        return str(api_response)

    error_msg = getattr(error_obj, "Message", None)
    if error_msg:
        return Error(error_msg)

    return str(api_response)

