        """Execute GET request and parse JSON response"""
        if parameters is None:
            parameters = {}

        result = self.get(operation, parameters, expand_list)
        if not result:
            raise Exception(f"{operation}: empty response")

        # Convert response to JSON-serializable format
        result_json = json.loads(json.dumps(result))
        return result_json

    def mcp_post(self, operation, parameters=None, payload=None):
        """Execute POST request with JSON body and parse response"""
        if parameters is None:
            parameters = {}
        if payload is None:
            payload = {}

        result = self.json(operation, parameters, payload)
        if not result:
            raise Exception(f"{operation}: empty response")

        # Convert response to JSON-serializable format
        result_json = json.loads(json.dumps(result))
        return result_json

# Extract base RGB color from JSON file

import json
import sys

def extract_primary_rgb(file_path):
    """Load color data and return primary RGB values as a comma-separated string."""
    try:
        with open(file_path, 'r') as file:
            color_data = json.load(file)
    except (FileNotFoundError, json.JSONDecodeError):
        return "0,0,0"

    if not color_data or "rgb" not in color_data[0]:
        return "0,0,0"

    rgb_values = color_data[0]["rgb"]
    return f"{rgb_values[0]},{rgb_values[1]},{rgb_values[2]}"

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: get_base_rgb.py <sampled.json>", file=sys.stderr)
        sys.exit(1)

    result = extract_primary_rgb(sys.argv[1])
    print(result)

import json
import sys

def assess_market_sentiment(message):
    bullish_terms = ['moon', 'bull', 'growth', 'profit', 'buy', 'upgrade', 'success', 'stable']
    bearish_terms = ['dump', 'bear', 'crash', 'loss', 'sell', 'scam', 'fear', 'volatile']

    sentiment_score = 0.0
    tokens = message.lower().split()

    for token in tokens:
        if token in bullish_terms:
            sentiment_score += 0.2
        elif token in bearish_terms:
            sentiment_score -= 0.2

    # Clamp the score within [-1, 1]
    if sentiment_score > 1:
        sentiment_score = 1
    elif sentiment_score < -1:
        sentiment_score = -1

    mood_label = "Neutral"
    if sentiment_score > 0.3:
        mood_label = "Greedy / Bullish"
    elif sentiment_score < -0.3:
        mood_label = "Fearful / Bearish"

    return {
        "score": round(sentiment_score, 2),
        "status": mood_label,
        "narrative_drivers": ["Simulated social signals", "Keywords analysis"]
    }

if __name__ == "__main__":
    user_input = sys.argv[1] if len(sys.argv) > 1 else ""
    output = assess_market_sentiment(user_input)
    print(json.dumps(output, indent=2))

import json
import sys
from dataclasses import dataclass

@dataclass
class BoundingBoxInfo:
    bounds: list[float]
    box_type: str
    field_data: dict

def validate_bounding_boxes(json_input) -> list[str]:
    output_lines = []
    try:
        data = json.load(json_input)
    except json.JSONDecodeError:
        return ["ERROR: Invalid JSON format in input file"]

    form_fields = data.get("form_fields", [])
    output_lines.append(f"Processed {len(form_fields)} form fields")

    def boxes_overlap(box_a, box_b):
        # Check if two axis-aligned rectangles do NOT overlap
        no_horizontal_overlap = box_a[0] >= box_b[2] or box_a[2] <= box_b[0]
        no_vertical_overlap = box_a[1] >= box_b[3] or box_a[3] <= box_b[1]
        return not (no_horizontal_overlap or no_vertical_overlap)

    # Collect all bounding boxes with their metadata
    all_boxes = []
    for field in form_fields:
        label_box = field.get("label_bounding_box", [])
        entry_box = field.get("entry_bounding_box", [])

        if label_box:
            all_boxes.append(BoundingBoxInfo(label_box, "label", field))
        if entry_box:
            all_boxes.append(BoundingBoxInfo(entry_box, "entry", field))

    issues_found = False

    # Compare each pair of boxes
    total_boxes = len(all_boxes)
    for idx_a in range(total_boxes):
        box_a = all_boxes[idx_a]

        # Only compare same-page boxes
        for idx_b in range(idx_a + 1, total_boxes):
            box_b = all_boxes[idx_b]

            # Skip if on different pages
            if box_a.field_data.get("page_number") != box_b.field_data.get("page_number"):
                continue

            # Check for intersection
            if boxes_overlap(box_a.bounds, box_b.bounds):
                issues_found = True
                desc_a = box_a.field_data.get("description", "unknown")
                desc_b = box_b.field_data.get("description", "unknown")

                if box_a.field_data is box_b.field_data:
                    output_lines.append(
                        f"CRITICAL: Overlap between label and entry boxes for '{desc_a}' "
                        f"(label: {box_a.bounds}, entry: {box_b.bounds})"
                    )
                else:
                    output_lines.append(
                        f"CRITICAL: Overlap between {box_a.box_type} box for '{desc_a}' "
                        f"({box_a.bounds}) and {box_b.box_type} box for '{desc_b}' ({box_b.bounds})"
                    )

                # Limit number of error messages to prevent overwhelming output
                if len(output_lines) >= 20:
                    output_lines.append("Stopping validation after 20 errors; please fix issues and re-run")
                    return output_lines

    # Validate entry box height against font size
    for box in all_boxes:
        if box.box_type == "entry":
            field = box.field_data
            if "entry_text" in field:
                text_info = field["entry_text"]
                font_size = text_info.get("font_size", 14)
                actual_height = box.bounds[3] - box.bounds[1]

                if actual_height < font_size:
                    issues_found = True
                    description = field.get("description", "unnamed field")
                    output_lines.append(
                        f"CRITICAL: Entry box for '{description}' has insufficient height "
                        f"({actual_height:.1f}px) for font size {font_size}px. "
                        f"Please increase the box or reduce font size."
                    )

                    if len(output_lines) >= 20:
                        output_lines.append("Stopping validation after 20 errors; please fix issues and re-run")
                        return output_lines

    if not issues_found:
        output_lines.append("VALIDATION PASSED: All bounding boxes meet requirements")

    return output_lines

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python validate_bounding_boxes.py [fields.json]")
        sys.exit(1)

    try:
        with open(sys.argv[1], 'r') as file:
            results = validate_bounding_boxes(file)
    except FileNotFoundError:
        print(f"ERROR: File '{sys.argv[1]}' not found")
        sys.exit(1)
    except Exception as e:
        print(f"ERROR: Failed to process file: {e}")
        sys.exit(1)

    for line in results:
        print(line)

# Twilio Outbound Call Integration using ElevenLabs API
import sys
import os
import json
import re
import urllib.request
import urllib.error

# Load configuration from environment variables
AGENT_ID = os.environ.get("ELEVENLABS_AGENT_ID", "")
API_KEY = os.environ.get("ELEVENLABS_API_KEY", "")
PHONE_NUMBER_ID = os.environ.get("ELEVENLABS_PHONE_NUMBER_ID", "")

# Define the API endpoint for outbound calls
API_ENDPOINT = "https://api.elevenlabs.io/v1/convai/twilio/outbound-call"

def place_outbound_call(target_number: str, initial_greeting: str = "", additional_context: str = "") -> dict:
    """
    Initiate an outbound voice call via ElevenLabs' Conversational AI service.

    Args:
        target_number: Recipient's phone number in E.164 format (e.g., +1XXXXXXXXXX)
        initial_greeting: Optional custom first message for the agent
        additional_context: Optional dynamic context variable for the conversation

    Returns:
        Dictionary containing either success data or error information
    """
    # Validate required credentials are present
    if not API_KEY:
        return {"error": "ELEVENLABS_API_KEY not configured. Please set it in your environment."}
    if not AGENT_ID:
        return {"error": "ELEVENLABS_AGENT_ID not configured. Please set it in your environment."}
    if not PHONE_NUMBER_ID:
        return {"error": "ELEVENLABS_PHONE_NUMBER_ID not configured. Please set it in your environment."}

    # Validate phone number format (US E.164: +1 followed by 10 digits)
    if not re.match(r'^\+1\d{10}$', target_number):
        return {
            "error": f"Invalid US phone number: {target_number}. "
                     f"Expected format: +1XXXXXXXXXX (E.164)"
        }

    # Build request payload
    request_body = {
        "agent_id": AGENT_ID,
        "agent_phone_number_id": PHONE_NUMBER_ID,
        "to_number": target_number,
    }

    # Add optional client data overrides
    client_overrides = {}
    if initial_greeting:
        client_overrides["conversation_config_override"] = {
            "agent": {"first_message": initial_greeting}
        }
    if additional_context:
        client_overrides["dynamic_variables"] = {"call_context": additional_context}

    if client_overrides:
        request_body["conversation_initiation_client_data"] = client_overrides

    # Prepare and send HTTP request
    encoded_payload = json.dumps(request_body).encode('utf-8')
    http_request = urllib.request.Request(
        API_ENDPOINT,
        data=encoded_payload,
        headers={
            "xi-api-key": API_KEY,
            "Content-Type": "application/json",
        }
    )

    try:
        with urllib.request.urlopen(http_request) as response:
            api_response = json.loads(response.read().decode())

            # Check for API-level errors despite successful HTTP status
            if not api_response.get("success", True) or "error" in api_response:
                error_msg = api_response.get("error") or api_response.get("message")
                return {"error": error_msg or "Unknown API error occurred"}

            return {
                "success": True,
                "conversation_id": api_response.get("conversation_id", ""),
                "call_sid": api_response.get("callSid", ""),
                "message": api_response.get("message", "Call successfully initiated"),
            }

    except urllib.error.HTTPError as http_err:
        error_body = http_err.read().decode()
        return {
            "error": f"ElevenLabs API error (HTTP {http_err.code}): {error_body}"
        }
    except urllib.error.URLError as url_err:
        return {"error": f"Network connectivity issue: {url_err.reason}"}

if __name__ == "__main__":
    # Command-line argument handling
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Usage: call.py <phone_number> [initial_greeting] [context]"}))
        sys.exit(1)

    # Extract arguments
    destination_number = sys.argv[1]
    greeting_text = sys.argv[2] if len(sys.argv) > 2 else ""
    context_data = sys.argv[3] if len(sys.argv) > 3 else ""

    # Execute call function and output result
    call_result = place_outbound_call(destination_number, greeting_text, context_data)
    print(json.dumps(call_result, indent=2))

    # Exit with appropriate code based on success/failure
    sys.exit(0 if call_result.get("success") else 1)

