# Encode a string by rotating each group of three characters left by one position
def encode_cyclic(s: str):
    """
    returns encoded string by cycling groups of three characters.
    """
    # Split string into chunks of up to 3 characters
    result = []
    for i in range(0, len(s), 3):
        chunk = s[i:i+3]
        if len(chunk) == 3:
            # Rotate left: move first character to the end
            result.append(chunk[1] + chunk[2] + chunk[0])
        else:
            result.append(chunk)
    return "".join(result)

# Decode a string that was encoded with encode_cyclic
def decode_cyclic(s: str):
    """
    takes as input string encoded with encode_cyclic function. Returns decoded string.
    """
    # Split string into chunks of up to 3 characters
    result = []
    for i in range(0, len(s), 3):
        chunk = s[i:i+3]
        if len(chunk) == 3:
            # Rotate right: move last character to the beginning
            result.append(chunk[2] + chunk[0] + chunk[1])
        else:
            result.append(chunk)
    return "".join(result)

