# Test compatibility shim for cursor keyword argument handling

def test_compat_cursor_keyword_forwarding():
    call_log = []

    class MockConnection:
        def cursor(self, *args, **kwargs):
            # Record the arguments passed to simulate strict DB API behavior
            call_log.append(("invoked", args, kwargs))
            return "CURSOR_OK"

    connection = MockConnection()

    # Simulate strict cursor method that rejects keyword arguments
    def strict_cursor_method(*args, **kwargs):
        if "cursor" in kwargs:
            raise TypeError(
                "Connection.cursor() got an unexpected keyword argument 'cursor'"
            )
        return connection.cursor(*args, **kwargs)

    # Verify that using keyword raises TypeError under strict mode
    connection.cursor = strict_cursor_method
    try:
        connection.cursor(cursor="X")
        assert False, "Expected TypeError was not raised"
    except TypeError as e:
        assert "cursor" in str(e)

    # Implement compatibility layer
    def original_cursor(*args, **kwargs):
        # Use fresh instance to record calls for verification
        return MockConnection().cursor(*args, **kwargs)

    def compatible_cursor(*args, **kwargs):
        # Extract and reposition 'cursor' keyword arg as positional if present
        if "cursor" in kwargs:
            cursor_value = kwargs.pop("cursor")
            return original_cursor(cursor_value, *args, **kwargs)
        return original_cursor(*args, **kwargs)

    # Apply the compatibility wrapper
    connection.cursor = compatible_cursor

    # Test with keyword argument
    result1 = connection.cursor(cursor="X")
    assert result1 == "CURSOR_OK"

    # Test without keyword argument (ensure backward compatibility)
    result2 = connection.cursor()
    assert result2 == "CURSOR_OK"

# Alternative implementation of DBRef with equivalent functionality but different internal structure and method implementations

from copy import deepcopy
from ._helpers import _getstate_slots, _setstate_slots
from .son import SON

class DBRef(object):
    """A reference to a document stored in MongoDB."""

    # Using a dictionary-based storage instead of __slots__ for internal data
    def __init__(self, collection, id, database=None, _extra={}, **kwargs):
        """Initialize a new :class:`DBRef`.
        Raises :class:`TypeError` if `collection` or `database` is not
        an instance of :class:`basestring` (:class:`str` in python 3).
        `database` is optional and allows references to documents to work
        across databases. Any additional keyword arguments will create
        additional fields in the resultant embedded document.
        :Parameters:
          - `collection`: name of the collection the document is stored in
          - `id`: the value of the document's ``"_id"`` field
          - `database` (optional): name of the database to reference
          - `**kwargs` (optional): additional keyword arguments will
            create additional, custom fields
        .. seealso:: The MongoDB documentation on `dbrefs <https://dochub.mongodb.org/core/dbrefs>`_.
        """
        if not isinstance(collection, str):
            raise TypeError("collection must be an instance of str")
        if database is not None and not isinstance(database, str):
            raise TypeError("database must be an instance of str")

        # Store data in a private dictionary instead of individual attributes
        self._data = {
            'collection': collection,
            'id': id,
            'database': database,
            'kwargs': {}
        }

        # Merge extra kwargs with provided kwargs
        combined_kwargs = dict(_extra)
        combined_kwargs.update(kwargs)
        self._data['kwargs'] = combined_kwargs

    @property
    def collection(self):
        """Get the name of this DBRef's collection."""
        return self._data['collection']

    @property
    def id(self):
        """Get this DBRef's _id."""
        return self._data['id']

    @property
    def database(self):
        """Get the name of this DBRef's database.
        Returns None if this DBRef doesn't specify a database.
        """
        return self._data['database']

    def __getattr__(self, key):
        try:
            return self._data['kwargs'][key]
        except KeyError:
            raise AttributeError(key)

    def as_doc(self):
        """Get the SON document representation of this DBRef.
        Generally not needed by application developers
        """
        doc = SON([("$ref", self.collection), ("$id", self.id)])
        if self.database is not None:
            doc["$db"] = self.database
        doc.update(self._data['kwargs'])
        return doc

    def __repr__(self):
        kwargs_items = self._data['kwargs'].items()
        extra = "".join([", %s=%r" % (k, v) for k, v in kwargs_items])
        if self.database is None:
            return "DBRef(%r, %r%s)" % (self.collection, self.id, extra)
        return "DBRef(%r, %r, %r%s)" % (self.collection, self.id, self.database, extra)

    def __eq__(self, other):
        if isinstance(other, DBRef):
            # Compare using tuple of all relevant fields
            us = (self.database, self.collection, self.id, tuple(sorted(self._data['kwargs'].items())))
            them = (other.database, other.collection, other.id, tuple(sorted(other._data['kwargs'].items())))
            return us == them
        return NotImplemented

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        """Get a hash value for this :class:`DBRef`."""
        return hash(
            (self.collection, self.id, self.database, tuple(sorted(self._data['kwargs'].items())))
        )

    def __deepcopy__(self, memo):
        """Support function for `copy.deepcopy()`."""
        return DBRef(
            deepcopy(self.collection, memo),
            deepcopy(self.id, memo),
            deepcopy(self.database, memo),
            deepcopy(self._data['kwargs'], memo),
        )

# Add pickle support methods
def _getstate_dbref(obj):
    return obj._data

def _setstate_dbref(obj, state):
    obj._data = state

# Override the default pickle methods
DBRef.__getstate__ = _getstate_dbref
DBRef.__setstate__ = _setstate_dbref

