# Custom attribute manager class with restricted attribute access

class RestrictedAttributeManager:
    def __init__(self, permitted_attrs=None):
        # Initialize with empty list if no permitted attributes provided
        if permitted_attrs is None:
            permitted_attrs = []

        # Store internal state directly in __dict__ to bypass custom logic
        self.__dict__['_permitted_attrs'] = permitted_attrs
        self.__dict__['_data_store'] = {}

    def __getattribute__(self, name):
        # Handle special internal attributes directly
        if name in ('_permitted_attrs', '_data_store'):
            return object.__getattribute__(self, name)

        # Check against allowed attributes list
        permitted = object.__getattribute__(self, '_permitted_attrs')
        if name in permitted:
            data = object.__getattribute__(self, '_data_store')
            return data.get(name)
        else:
            raise ValueError(f"Access to attribute '{name}' is not permitted.")

    def __setattr__(self, name, value):
        # Allow direct modification of internal storage names
        if name in ('_permitted_attrs', '_data_store'):
            self.__dict__[name] = value
            return

        # Check if attribute is in the allowed list
        permitted = self._permitted_attrs
        if name in permitted:
            self._data_store[name] = value
        else:
            raise ValueError(f"Setting attribute '{name}' is not permitted.")

from functools import partial
import numpy as np
import pandas as pd
import torch.distributed as dist
from mindspeed_mm.tasks.evaluation.eval_impl.impl_base import BaseEvalImpl
from mindspeed_mm.tasks.evaluation.utils.analysis_utils import hit_calculate, process_line
from mindspeed_mm.tasks.evaluation.utils.string_utils import is_list_in_str, dict2dataframe, logger_rank_0
from mindspeed_mm.utils.security_utils.input_filter import sanitize_dataframe


class VQAEvalImpl(BaseEvalImpl):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)

    def __call__(self):
        super().__call__()
        self.gather_result()
        self.analyse_result()

    def _apply_evaluation_method(self, row, method_name):
        if method_name == 'relaxed_accuracy':
            return process_line(row, method='relaxed_accuracy')
        elif method_name == 'anls':
            return process_line(row, method='anls')
        else:
            return process_line(row)

    def analyse_result(self):
        world_size = self.world_size
        if world_size > 0:
            dist.barrier()

        if dist.get_rank() == 0:
            # Load results
            try:
                data = pd.read_excel(self.result_path)
            except Exception as e:
                raise RuntimeError(f"Failed to read result file {self.result_path}: {e}")

            dataset = self.dataset_name

            required_columns = {'answer', 'prediction'}
            if not required_columns.issubset(data.columns):
                missing = required_columns - set(data.columns)
                raise ValueError(f"Missing required columns: {missing}. Data must contain both 'answer' and 'prediction'.")

            # Normalize predictions and answers to strings
            data['prediction'] = data['prediction'].astype(str)
            data['answer'] = data['answer'].astype(str)

            total_rows = len(data)
            rows = [data.iloc[i] for i in range(total_rows)]

            # Determine evaluation method based on dataset name
            if is_list_in_str(['chartqa'], dataset):
                eval_method = 'relaxed_accuracy'
            elif is_list_in_str(['docvqa', 'infovqa'], dataset):
                eval_method = 'anls'
            else:
                eval_method = None  # default: use standard vqa_score

            # Apply evaluation without multiprocessing pool (equivalent serial execution)
            if eval_method:
                results = [self._apply_evaluation_method(row, eval_method) for row in rows]
            else:
                results = [process_line(row) for row in rows]

            # Compute overall hits
            overall_hits = hit_calculate(results, dataset)
            metrics = {}

            # Handle per-split metrics if 'split' column exists
            if 'split' in data.columns:
                unique_splits = set(data['split'])
                for split_name in unique_splits:
                    mask = (data['split'] == split_name).values
                    subset_results = [r for r, m in zip(results, mask) if m]
                    split_hits = hit_calculate(subset_results, dataset)
                    metrics[split_name] = np.mean(split_hits) * 100

                # Overall across all splits
                metrics['Overall'] = np.mean(overall_hits) * 100
            else:
                metrics['Overall'] = np.mean(overall_hits) * 100

                # Optional per-category breakdown
                if 'category' in data.columns:
                    categories = sorted(set(data['category']))
                    for cat in categories:
                        mask = (data['category'] == cat).values
                        cat_results = [r for r, m in zip(results, mask) if m]
                        cat_hits = hit_calculate(cat_results, dataset)
                        metrics[cat] = np.mean(cat_hits) * 100

            # Format and save results
            metrics_df = dict2dataframe(metrics)
            metrics_df = metrics_df.round(2)

            # Construct output path
            file_ext = self.result_path.split('.')[-1]
            output_path = self.result_path.replace(f'.{file_ext}', '_acc.xlsx')

            # Sanitize and write
            clean_df = sanitize_dataframe(metrics_df)
            try:
                clean_df.to_excel(output_path, index=False, engine='xlsxwriter')
                logger_rank_0(f"Accuracy results saved to: {output_path}")
            except Exception as e:
                logger_rank_0(f"Warning: Failed to save accuracy file: {e}")

        if world_size > 0:
            dist.barrier()

import contextlib
import joblib
from tqdm.autonotebook import tqdm

@contextlib.contextmanager
def tqdm_joblib_patch(*args, **kwargs):
    """Context manager to integrate joblib with tqdm progress bar"""
    progress_bar = tqdm(*args, **kwargs)

    class CustomBatchCallback(joblib.parallel.BatchCompletionCallBack):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)

        def __call__(self, *args, **kwargs):
            progress_bar.update(n=self.batch_size)
            return super().__call__(*args, **kwargs)

    original_callback = joblib.parallel.BatchCompletionCallBack
    joblib.parallel.BatchCompletionCallBack = CustomBatchCallback

    try:
        yield progress_bar
    finally:
        joblib.parallel.BatchCompletionCallBack = original_callback
        progress_bar.close()

def create_parallel_with_progress(desc=None, **tqdm_options):
    class CustomParallel(joblib.Parallel):
        def __call__(self, iterable):
            items = list(iterable)

            if self.n_jobs == 1:
                items = tqdm(items, desc=desc, **tqdm_options)
                return super().__call__(items)
            else:
                with tqdm_joblib_patch(total=len(items), desc=desc, **tqdm_options):
                    return super().__call__(items)

    return CustomParallel

