from transformers import AutoProcessor


class GlmPipeline(Qwen2VlPipeline, GenerationMixin):
    def __init__(self, config):
        super().__init__(config)
        tokenizer_path = config.tokenizer.from_pretrained
        self.image_processor = AutoProcessor.from_pretrained(
            tokenizer_path,
            local_files_only=True,
            use_fast=True
        )

    def compute_rope_indices(self, token_ids, img_dims=None, vid_dims=None, mask=None):
        return glm_position(
            config=self.generation_config,
            input_ids=token_ids,
            image_grid_thw=img_dims,
            video_grid_thw=vid_dims,
            attention_mask=mask
        )

    def __call__(self, text_prompt=None, img_list=None, vid_list=None, include_token_ids=False):
        return super().__call__(
            text_prompt, img_list, vid_list,
            include_token_ids,
            skip_special_tokens=False
        )

    def build_inputs(self, prompt=None, images=None, videos=None, chat_history=None):
        # Early exit if no modalities provided
        if not any([images, videos, chat_history]):
            return None

        # Construct message list if not already given
        if chat_history is None:
            media_items = []
            if images:
                media_items.append({"type": "image", "image": images})
            if videos:
                media_items.append({"type": "video", "video": videos})
            media_items.append({"type": "text", "text": prompt})
            chat_history = [[{"role": "user", "content": media_items}]]

        # Apply chat template and prepare model inputs
        processed = self.image_processor.apply_chat_template(
            chat_history,
            tokenize=True,
            add_generation_prompt=True,
            return_dict=True,
            return_tensors="pt",
            padding=True
        )
        processed = {k: v.to(self.infer_config.device) for k, v in processed.items()}
        return processed

import os
from web3 import Web3
import requests

def get_clob_credentials(private_key):
    # Initialize connection to Polygon network via Ankr endpoint
    provider_url = 'https://rpc.ankr.com/polygon'
    web3_instance = Web3(Web3.HTTPProvider(provider_url))

    # Extract account from private key
    account_obj = web3_instance.eth.account.from_key(private_key)

    # Prepare EIP-712 typed data structure (minimal example; adjust fields per Polymarket spec)
    typed_data = {
        "types": {
            "EIP712Domain": [],
            "SomeType": []
        },
        "domain": {},
        "primaryType": "SomeType",
        "message": {}
    }

    # Sign the typed data using the private key
    signature_result = web3_instance.eth.account.sign_typed_data(
        private_key=private_key,
        typed_data=typed_data
    )

    # Submit request to CLOB API for credentials
    api_endpoint = "https://clob.polymarket.com/api-keys"
    payload = {
        "signed_message": signature_result.signature.hex()
    }

    http_response = requests.post(api_endpoint, json=payload)

    if http_response.status_code == 200:
        return http_response.json()
    else:
        raise RuntimeError(f"Failed to authenticate: {http_response.text}")

# Main execution block
if __name__ == "__main__":
    secret_key = os.environ.get('POLY_PRIVATE_KEY')

    if secret_key:
        try:
            credentials = get_clob_credentials(secret_key)
            print("Successfully retrieved credentials:", credentials)
        except Exception as error:
            print(f"Authentication error occurred: {error}")
    else:
        print("Environment variable POLY_PRIVATE_KEY is not set.")

def convert_to_markdown_list(
    items: list[str], 
    style: str = "unordered"
) -> str:
    """
    Convert a list of strings into a markdown-formatted list.
    :param items: list of strings to format
    :param style: either 'unordered' for bullet points or 'ordered' for numbered list
    :return: string with markdown list syntax
    """
    if style == "unordered":
        # Use hyphen prefix for each item
        return "\n".join(map(lambda x: f"- {x}", items))
    elif style == "ordered":
        # Number items starting from 1
        result_lines = []
        index = 1
        for element in items:
            result_lines.append(f"{index}. {element}")
            index += 1
        return "\n".join(result_lines)
    else:
        raise ValueError("style must be either 'unordered' or 'ordered'")

import json
from pathlib import Path
from Levenshtein import ratio
from offline_tarteel.normalizer import normalize_arabic

DATA_PATH = Path(__file__).parent.parent.parent / "data" / "quran.json"

class QuranDatabase:
    def __init__(self, file_path: Path = DATA_PATH):
        with open(file_path) as file:
            self.verses_data = json.load(file)
        self._index_by_reference = {}
        self._index_by_chapter = {}
        for verse in self.verses_data:
            key = (verse["surah"], verse["ayah"])
            self._index_by_reference[key] = verse
            chapter_num = verse["surah"]
            self._index_by_chapter.setdefault(chapter_num, []).append(verse)

    @property
    def total_verses_count(self):
        return len(self.verses_data)

    @property
    def number_of_chapters(self):
        return len(self._index_by_chapter)

    def find_verse(self, chapter: int, verse_num: int):
        return self._index_by_reference.get((chapter, verse_num))

    def find_chapter_verses(self, chapter: int):
        return self._index_by_chapter.get(chapter, [])

    def query(self, query_text: str, limit: int = 5) -> list[dict]:
        normalized_query = normalize_arabic(query_text)
        results_with_scores = []
        for verse in self.verses_data:
            similarity = ratio(normalized_query, verse["text_clean"])
            result = {**verse, "similarity": similarity, "original_text": verse["text_uthmani"]}
            results_with_scores.append(result)
        results_with_scores.sort(key=lambda x: x["similarity"], reverse=True)
        return results_with_scores[:limit]

    def locate_verse(self, query_text: str, min_similarity: float = 0.3, max_length: int = 3) -> dict | None:
        """Identify the most similar verse or consecutive sequence of verses.
        Two-stage process: first evaluate individual verses quickly, then examine 
        multi-verse segments only near promising candidates."""
        normalized_input = normalize_arabic(query_text)
        if not normalized_input.strip():
            return None

        # Stage 1: Score each individual verse
        verse_scores = []
        for verse in self.verses_data:
            match_score = ratio(normalized_input, verse["text_clean"])
            verse_scores.append((verse, match_score))
        verse_scores.sort(key=lambda x: x[1], reverse=True)

        top_single_verse = {**verse_scores[0][0], "similarity": verse_scores[0][1]}
        current_best_score = verse_scores[0][1]

        # Stage 2: Examine multi-verse spans around top 20 candidates
        processed_chapters = set()
        for verse, _ in verse_scores[:20]:
            chapter_id = verse["surah"]
            if chapter_id in processed_chapters:
                continue
            processed_chapters.add(chapter_id)

            chapter_verses = self._index_by_chapter[chapter_id]
            for start_idx in range(len(chapter_verses)):
                for span_size in range(2, max_length + 1):
                    end_idx = start_idx + span_size
                    if end_idx > len(chapter_verses):
                        break

                    selected_verses = chapter_verses[start_idx:end_idx]
                    merged_text = " ".join(v["text_clean"] for v in selected_verses)
                    new_score = ratio(normalized_input, merged_text)

                    if new_score > current_best_score:
                        current_best_score = new_score
                        top_single_verse = {
                            "surah": chapter_id,
                            "ayah": selected_verses[0]["ayah"],
                            "ayah_end": selected_verses[-1]["ayah"],
                            "text": " ".join(v["text_uthmani"] for v in selected_verses),
                            "text_clean": merged_text,
                            "similarity": new_score,
                        }

        return top_single_verse if current_best_score >= min_similarity else None

# Alternative implementation that verifies argument parsing behavior 
# for functions with and without add_arguments support

import sys
from unittest.mock import patch
import argparse
import pytest

# Simulated registry and utility modules (simplified for demonstration)
class FunctionRegistry:
    def __init__(self):
        self._registry = {}

    def temporary(self, key, value):
        original = self._registry.get(key)
        self._registry[key] = value
        yield
        if original is not None:
            self._registry[key] = original
        else:
            self._registry.pop(key, None)

    def get(self, key):
        return self._registry.get(key)

function_registry = FunctionRegistry()

def get_miles_extra_args_provider():
    def provider(parser):
        parser.add_argument("--rollout-function-path", dest="rollout_function_path")
        parser.add_argument("--custom-generate-function-path", dest="custom_generate_function_path")
        # Parse function-specific arguments if the function has add_arguments
        path_arg = getattr(parser.parse_known_args()[0], "rollout_function_path", None) or \
                   getattr(parser.parse_known_args()[0], "custom_generate_function_path", None)

        if path_arg and ":" in path_arg:
            module_name, func_name = path_arg.split(":", 1)
            fn = function_registry.get(path_arg)
            if fn and hasattr(fn, "add_arguments"):
                fn.add_arguments(parser)
    return provider

PATH_ARGS = ["--rollout-function-path", "--custom-generate-function-path"]
REQUIRED_ARGS = ["--rollout-batch-size", "64"]

def make_class_with_add_arguments():
    class MyFn:
        @classmethod
        def add_arguments(cls, parser):
            parser.add_argument("--my-custom-arg", type=int, default=42)
    return MyFn

def make_function_with_add_arguments():
    def my_fn():
        pass
    my_fn.add_arguments = lambda parser: parser.add_argument("--my-custom-arg", type=int, default=42)
    return my_fn

def make_function_without_add_arguments():
    def my_fn():
        pass
    return my_fn

@pytest.mark.parametrize("path_arg", PATH_ARGS)
class TestAddArgumentsSupport:
    @pytest.mark.parametrize("fn_factory", [make_class_with_add_arguments, make_function_with_add_arguments])
    def test_add_arguments_is_called_and_arg_is_parsed(self, path_arg, fn_factory):
        fn = fn_factory()
        with function_registry.temporary("test:fn", fn), patch.object(
            sys, "argv", ["test", path_arg, "test:fn", "--my-custom-arg", "100"] + REQUIRED_ARGS
        ):
            parser = argparse.ArgumentParser()
            get_miles_extra_args_provider()(parser)
            args, _ = parser.parse_known_args()
            assert args.my_custom_arg == 100

    def test_skips_function_without_add_arguments(self, path_arg):
        fn = make_function_without_add_arguments()
        with function_registry.temporary("test:fn", fn), patch.object(
            sys, "argv", ["test", path_arg, "test:fn"] + REQUIRED_ARGS
        ):
            parser = argparse.ArgumentParser()
            get_miles_extra_args_provider()(parser)
            # Should not raise an error even though function lacks add_arguments
            args, _ = parser.parse_known_args()
            assert not hasattr(args, 'my_custom_arg') or args.my_custom_arg == 42

"""
ChemAudit Client Custom Exceptions
Exception classes for handling errors in the ChemAudit API client.
"""

class BaseChemAuditException(Exception):
    """Root exception class for all ChemAudit-related errors."""
    pass

class ServerCommunicationError(BaseChemAuditException):
    """Raised when the server returns an error status or response."""
    def __init__(self, message: str, http_status: int = None, payload: dict = None):
        super().__init__(message)
        self.http_status = http_status
        self.payload = payload if payload is not None else {}

    def __str__(self):
        if self.http_status is not None:
            return f"Server Communication Error [{self.http_status}]: {super().__str__()}"
        return super().__str__()

class ThrottlingError(ServerCommunicationError):
    """Raised when too many requests are sent and throttling is applied."""
    def __init__(self, message: str, wait_time: int = None):
        super().__init__(message, http_status=429)
        self.wait_time = wait_time

    def __str__(self):
        if self.wait_time is not None:
            return f"Request throttled. Please wait {self.wait_time} seconds before retrying."
        return "Too many requests. Please slow down."

class AuthorizationFailure(ServerCommunicationError):
    """Raised when authentication credentials are invalid or missing."""
    def __init__(self, message: str = "Authentication failed: API key invalid or absent"):
        super().__init__(message, http_status=401)

class InputValidationException(BaseChemAuditException):
    """Raised when input data fails validation checks."""
    pass

class JobLookupError(ServerCommunicationError):
    """Raised when a requested batch processing job cannot be located."""
    def __init__(self, job_identifier: str):
        super().__init__(f"Batch processing job '{job_identifier}' could not be found", http_status=404)
        self.job_identifier = job_identifier

class ExecutionTimeoutException(BaseChemAuditException):
    """Raised when a batch operation exceeds its allowed time limit."""
    pass

