import sys
from dataclasses import dataclass

# Type III clone: Renamed variables, restructured logic, used alternative control flow,
# but preserved same functionality (detect overlapping bounding boxes and validate entry heights)

@dataclass
class BoundingBoxInfo:
    bounds: list[float]
    box_category: str
    field_data: dict

def analyze_pdf_fields(input_stream) -> list[str]:
    output_lines = []
    try:
        data = json.load(input_stream)
    except json.JSONDecodeError:
        return ["ERROR: Invalid JSON in input file"]

    form_items = data.get("form_fields", [])
    output_lines.append(f"Processed {len(form_items)} form fields")

    def boxes_overlap(box_a, box_b):
        # Check if two axis-aligned rectangles intersect
        no_overlap_x = box_a[0] >= box_b[2] or box_a[2] <= box_b[0]
        no_overlap_y = box_a[1] >= box_b[3] or box_a[3] <= box_b[1]
        return not (no_overlap_x or no_overlap_y)

    # Collect all bounding boxes with metadata
    collected_boxes = []
    for item in form_items:
        label_box = item.get("label_bounding_box", [0.0, 0.0, 0.0, 0.0])
        entry_box = item.get("entry_bounding_box", [0.0, 0.0, 0.0, 0.0])
        collected_boxes.append(BoundingBoxInfo(label_box, "label", item))
        collected_boxes.append(BoundingBoxInfo(entry_box, "entry", item))

    issues_found = False

    # Compare each pair of boxes (avoiding duplicates)
    total_boxes = len(collected_boxes)
    for idx_a in range(total_boxes):
        current_box = collected_boxes[idx_a]

        for idx_b in range(idx_a + 1, total_boxes):
            compare_box = collected_boxes[idx_b]

            # Only check boxes on the same page
            if current_box.field_data["page_number"] == compare_box.field_data["page_number"]:
                if boxes_overlap(current_box.bounds, compare_box.bounds):
                    issues_found = True

                    # Distinguish same-field vs different-field intersections
                    if current_box.field_data is compare_box.field_data:
                        desc = current_box.field_data["description"]
                        output_lines.append(
                            f"CRITICAL: Overlap between label and entry boxes for '{desc}' "
                            f"({current_box.bounds}, {compare_box.bounds})"
                        )
                    else:
                        output_lines.append(
                            f"CRITICAL: Overlap between {current_box.box_category} box for "
                            f"'{current_box.field_data['description']}' ({current_box.bounds}) "
                            f"and {compare_box.box_category} box for "
                            f"'{compare_box.field_data['description']}' ({compare_box.bounds})"
                        )

                    # Limit number of error messages to prevent overwhelming output
                    if len(output_lines) >= 20:
                        output_lines.append("Stopping analysis after 20 errors - please fix issues and rerun")
                        return output_lines

    # Validate entry box height against font size
    for box_info in collected_boxes:
        if box_info.box_category == "entry":
            text_info = box_info.field_data.get("entry_text", {})
            min_font_size = text_info.get("font_size", 14)
            actual_height = box_info.bounds[3] - box_info.bounds[1]

            if actual_height < min_font_size:
                issues_found = True
                desc = box_info.field_data["description"]
                output_lines.append(
                    f"CRITICAL: Entry box for '{desc}' has insufficient height ({actual_height:.2f}) "
                    f"for specified font size ({min_font_size}). Please increase box height."
                )

                if len(output_lines) >= 20:
                    output_lines.append("Stopping analysis after 20 errors - please fix issues and rerun")
                    return output_lines

    if not issues_found:
        output_lines.append("VERIFIED: All bounding boxes meet requirements")

    return output_lines

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: verify_bounding_boxes.py [fields.json]")
        sys.exit(1)

    with open(sys.argv[1], 'r') as file_handle:
        results = analyze_pdf_fields(file_handle)

    for line in results:
        print(line)

