# Custom dataset class that extends PyTorch's functionality to load images 
# from a root directory and all its subdirectories recursively

import os
import torch.utils.data as data
from PIL import Image

# Supported image file extensions
IMAGE_EXTENSIONS = [
    '.jpg', '.JPG', '.jpeg', '.JPEG',
    '.png', '.PNG', '.ppm', '.PPM', '.bmp', '.BMP',
    '.tif', '.TIF', '.tiff', '.TIFF'
]

def has_valid_image_extension(filename):
    """Check if the given filename has a supported image extension."""
    return any(filename.endswith(ext) for ext in IMAGE_EXTENSIONS)

def collect_image_paths(directory, limit_size=float("inf")):
    """Recursively collect all image paths from the directory and subdirectories."""
    image_list = []

    # Validate that the provided path is a directory or symbolic link to a directory
    if not (os.path.isdir(directory) or os.path.islink(directory)):
        raise ValueError(f"'{directory}' is not a valid directory")

    # Walk through directory tree, following symbolic links
    for dirpath, _, filenames in sorted(os.walk(directory, followlinks=True)):
        for filename in filenames:
            if has_valid_image_extension(filename):
                full_path = os.path.join(dirpath, filename)
                image_list.append(full_path)

    # Apply size limit if specified
    return image_list[:min(limit_size, len(image_list))]

def standard_image_loader(filepath):
    """Load an image from the given path and convert to RGB."""
    return Image.open(filepath).convert('RGB')

class RecursiveImageFolder(data.Dataset):
    def __init__(self, root_dir, transform=None, include_paths=False,
                 image_loader=standard_image_loader):
        # Collect all image paths from root and subdirectories
        self.image_paths = collect_image_paths(root_dir)

        # Raise error if no images were found
        if len(self.image_paths) == 0:
            raise RuntimeError(
                f"Found 0 images in: {root_dir}\n"
                f"Supported image extensions are: {', '.join(IMAGE_EXTENSIONS)}"
            )

        # Store configuration
        self.root = root_dir
        self.transforms = transform
        self.include_paths = include_paths
        self.loader = image_loader

    def __getitem__(self, idx):
        # Load image at the specified index
        image_path = self.image_paths[idx]
        image = self.loader(image_path)

        # Apply transformations if provided
        if self.transforms is not None:
            image = self.transforms(image)

        # Return image with or without path depending on configuration
        if self.include_paths:
            return image, image_path
        else:
            return image

    def __len__(self):
        return len(self.image_paths)

