# API information storage (can be extended dynamically)
api_info = {}

class BaseTrait(Service):
    def __init__(self, config=None):
        # Initialize with optional configuration dictionary
        if config is None:
            config = {}

        self.config = config

        # Extract region and service info map from config
        region = config.get('region', REGION_CN_NORTH1)
        service_info_map = config.get('service_info_map', {})

        # Set up service and API info
        self.service_info = self._resolve_service_info(region, service_info_map)
        self.api_info = self._get_static_api_info()

        # Handle authentication if credentials provided
        if config.get('ak') and config.get('sk'):
            self.set_access_key(config['ak'])
            self.set_secret_key(config['sk'])

        # Initialize parent class
        super(BaseTrait, self).__init__(self.service_info, self.api_info)

    @staticmethod
    def _resolve_service_info(region, service_info_map):
        """Resolve service info for given region"""
        service_info = service_info_map.get(region)
        if not service_info:
            raise Exception(f"BaseService does not support region: {region}")
        return service_info

    @staticmethod
    def _get_static_api_info():
        """Return static API information"""
        return api_info

    def update_api_info(self, additional_api_info):
        """Merge new API info into existing API info"""
        self.api_info = {**self.api_info, **additional_api_info}
        return self

    def execute_get_request(self, operation_name, query_params=None, allow_list=False):
        """Execute GET request and parse JSON response"""
        if query_params is None:
            query_params = {}

        response = self.get(operation_name, query_params, allow_list)
        if not response:
            raise Exception(f"{operation_name}: empty response received")

        # Convert response to JSON-compatible format
        response_json = json.loads(json.dumps(response))
        return response_json

    def execute_post_request(self, operation_name, query_params=None, payload=None):
        """Execute POST request with JSON body and parse response"""
        if query_params is None:
            query_params = {}
        if payload is None:
            payload = {}

        response = self.json(operation_name, query_params, payload)
        if not response:
            raise Exception(f"{operation_name}: empty response received")

        # Convert response to JSON-compatible format
        response_json = json.loads(json.dumps(response))
        return response_json

def solve(s):
