# Custom weight initialization utilities for neural networks

import jax
from flax.linen import initializers as nn_initializers
from jax import numpy as jnp
from flowrl.types import *

def orthogonal_initializer(scale: Optional[float] = None):
    """Create an orthogonal initializer with optional scaling."""
    if scale is None:
        scale = jnp.sqrt(2.0)
    return nn_initializers.orthogonal(scale)

def pytorch_style_kernel_init():
    """Initialize weights using PyTorch-style uniform distribution based on fan_in."""
    return nn_initializers.variance_scaling(
        scale=1.0 / 3.0,
        mode="fan_in",
        distribution="uniform"
    )

def pytorch_style_bias_init():
    """Initialize biases using uniform distribution scaled by fan_in."""
    def init_fn(key, shape, dtype=jnp.float32):
        return (jax.random.uniform(key, shape, dtype) * 2.0 - 1.0) / jnp.sqrt(shape[0])
    return init_fn

# Default initializers for kernel and bias
default_kernel_init = orthogonal_initializer
default_bias_init = nn_initializers.zeros

