            "info": str(exception)
        }), 400

    @app.errorhandler(404)
    def on_not_found_error(exception):
        """Handle HTTP 404 (Not Found) errors."""
        return jsonify({"error": "Resource not accessible"}), 404

    @app.errorhandler(500)
    def on_server_error(exception):
        """Handle internal server errors."""
        return jsonify({
            "error": "Server encountered an issue", 
            "message": str(exception)
        }), 500

