import json
import sys
import urllib.request

BASE_URL = "http://127.0.0.1:9501"

def make_rpc_call(method_name: str, parameters: dict = None, identifier=None):
    payload = json.dumps({
        "jsonrpc": "2.0",
        "id": identifier,
        "method": method_name,
        "params": parameters if parameters is not None else {},
    }).encode('utf-8')

    request = urllib.request.Request(
        f"{BASE_URL}/message",
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST"
    )

    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.loads(response.read().decode('utf-8'))
    except Exception as error:
        return {
            "jsonrpc": "2.0",
            "id": identifier,
            "error": {"code": -1, "message": str(error)}
        }

def process_input():
    for input_line in sys.stdin:
        clean_line = input_line.strip()
        if not clean_line:
            continue

        try:
            parsed_message = json.loads(clean_line)
        except json.JSONDecodeError:
            continue

        rpc_method = parsed_message.get("method", "")
        message_id = parsed_message.get("id")
        call_params = parsed_message.get("params", {})

        if rpc_method == "notifications/initialized":
            continue

        result = make_rpc_call(rpc_method, call_params, message_id)
        sys.stdout.write(json.dumps(result) + "\n")
        sys.stdout.flush()

if __name__ == "__main__":
    process_input()

