import torch.nn as nn
import re

class PassThrough(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, input_tensor, *args, **kwargs):
        return input_tensor

    @property
    def configuration(self):
        return {"mm_projector_type": 'identity'}

class ResidualBlock(nn.Module):
    def __init__(self, feature_dim):
        super().__init__()
        self.norm_layer = nn.LayerNorm(feature_dim)
        self.residual_path = nn.Sequential(
            nn.Linear(feature_dim, feature_dim),
            nn.GELU(),
            nn.Linear(feature_dim, feature_dim)
        )

    def forward(self, x):
        x = self.norm_layer(x)
        return x + self.residual_path(x)

def create_vision_projector(model_config, skip_loading=False, **extra_kwargs):
    proj_type = getattr(model_config, 'mm_projector_type', 'linear')

    if proj_type == 'linear':
        return nn.Linear(model_config.mm_hidden_size, model_config.hidden_size)

    mlp_gelu_pattern = re.match(r'^mlp(\d+)x_gelu$', proj_type)
    if mlp_gelu_pattern:
        num_layers = int(mlp_gelu_pattern.group(1))
        layers = [nn.Linear(model_config.mm_hidden_size, model_config.hidden_size)]

        for _ in range(1, num_layers):
            layers.append(nn.GELU())
            layers.append(nn.Linear(model_config.hidden_size, model_config.hidden_size))

        return nn.Sequential(*layers)

    if proj_type == 'identity':
        return PassThrough()

    raise ValueError(f'Unsupported projector type: {proj_type}')

