def merge_lora_weights(unet_model, vae_model=None, checkpoint_path=None, blend_factor=1.0, base_model_path=""):
    # Return early if no checkpoint path is provided
    if checkpoint_path is None:
        return unet_model

    loaded_state_dict = {}

    # Load state dict based on file format
    if checkpoint_path.endswith(".ckpt"):
        checkpoint_data = torch.load(checkpoint_path, map_location="cpu")
        loaded_state_dict = checkpoint_data.get("state_dict", {})
    elif checkpoint_path.endswith(".safetensors"):
        with safe_open(checkpoint_path, framework="pt", device="cpu") as f:
            loaded_state_dict = {key: f.get_tensor(key) for key in f.keys()}

    # Determine if it's a LoRA checkpoint or full model checkpoint
    is_lora_format = all("lora" in key for key in loaded_state_dict.keys())

    if not is_lora_format:
        source_state_dict = loaded_state_dict
    else:
        # For LoRA, load base model to compute interpolation
        source_state_dict = {}
        with safe_open(base_model_path, framework="pt", device="cpu") as f:
            source_state_dict = {key: f.get_tensor(key) for key in f.keys()}

    # Convert UNet checkpoint and apply blending
    converted_unet = convert_ldm_unet_checkpoint(source_state_dict, unet_model.config)
    current_unet_state = unet_model.state_dict()

    # Apply weighted interpolation between converted weights and current weights
    for param_name in converted_unet:
        if param_name in current_unet_state:
            converted_unet[param_name] = (blend_factor * converted_unet[param_name] + 
                                         (1 - blend_factor) * current_unet_state[param_name])

    # Load updated weights into UNet
    unet_model.load_state_dict(converted_unet, strict=False)

    # Handle VAE conversion if VAE model is provided
    if vae_model is not None:
        converted_vae = convert_ldm_vae_checkpoint(source_state_dict, vae_model.config)
        vae_model.load_state_dict(converted_vae)

    return unet_model, vae_model

