import os

class RewritingPass(DimensionGeneralizationPass):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    @classmethod
    def pass_identifier(cls) -> str:
        return os.path.splitext(os.path.basename(__file__))[0]

    def requires_modification(self, traced_module: fx.GraphModule) -> bool:
        # Skip if batch axis (0) is involved
        if 0 in self.axes:
            return False

        # Check each node individually for rewrite necessity
        for node in traced_module.graph.nodes:
            if self._requires_rewrite(node):
                return True
        return False

    def target_op(self):
        return torch.arange

    def _requires_rewrite(self, node) -> bool:
        # Must be a function call
        if node.op != "call_function":
            return False

        # Must match target operation
        if node.target != self.target_op():
            return False

        # Handle argument patterns
        args = node.args
        if len(args) == 1:
            return args[0] == self.dim
        elif len(args) == 2:
            return args[0] == 0 and args[1] == self.dim
        else:
            return False

    def transform(self, traced_module: fx.GraphModule) -> fx.GraphModule:
        # Initialize new graph and mapping structure
        updated_graph = fx.Graph()
        node_mapping = {}

        # Track last node with matching dimension
        AxisRecord = namedtuple("AxisRecord", ["node", "dim_index"])
        recent_axis = None

        def update_recent_axis_if_applicable(original_node, new_node):
            nonlocal recent_axis
            tensor_info = original_node.meta.get("tensor_meta")
            if tensor_info is None or not hasattr(tensor_info, "shape"):
                return

            shape = tensor_info.shape
            for idx, dim_size in enumerate(shape):
                if dim_size == self.dim and idx > 0:
                    recent_axis = AxisRecord(node=new_node, dim_index=idx)
                    break

        def resolve_argument(index, original_arg, total_args):
            # Only rewrite specific positions: second arg in 2-arg case, or first in 1-arg case
            if not ((total_args == 2 and index == 1) or (total_args == 1 and index == 0)):
                return node_mapping.get(original_arg, original_arg)

            # Replace with dynamic size lookup
            assert original_arg == self.dim
            size_call = updated_graph.call_method(
                "size", args=(recent_axis.node, recent_axis.dim_index)
            )
            return size_call

        def process_node(original_node):
            # Decide whether to rewrite this node
            should_rewrite = self._requires_rewrite(original_node) and recent_axis is not None

            if not should_rewrite:
                # Standard copy for non-matching nodes
                copied = updated_graph.node_copy(
                    original_node,
                    lambda n: node_mapping.get(n, n)
                )
                update_recent_axis_if_applicable(original_node, copied)
                return copied

            # Rewrite using dynamic dimension
            rewritten_args = tuple(
                resolve_argument(i, arg, len(original_node.args))
                for i, arg in enumerate(original_node.args)
            )
            new_node = updated_graph.call_function(
                self.target_op(),
                args=rewritten_args,
                kwargs=original_node.kwargs
            )
            return new_node

        # Traverse original graph and build new one
        for node in traced_module.graph.nodes:
            node_mapping[node] = process_node(node)

        # Finalize transformation
        traced_module.graph = updated_graph
        traced_module.recompile()
        return traced_module

from typing import Any, Optional

def get_string_value_from_dict(d: dict, keys: tuple) -> Optional[str]:
    """Helper function to retrieve the first string value for any of the given keys."""
    for k in keys:
        val = d.get(k)
        if isinstance(val, str):
            return val
    return None

def extract_turn_identifier(payload: Any) -> Optional[str]:
    # Validate payload is a dictionary
    if not isinstance(payload, dict):
        return None

    # Direct lookup at top level
    top_keys = ("turnId", "turn_id", "id")
    result = get_string_value_from_dict(payload, top_keys)
    if result:
        return result

    # Check nested 'turn' object
    turn_obj = payload.get("turn")
    if isinstance(turn_obj, dict):
        turn_nested_keys = ("id", "turnId", "turn_id")
        result = get_string_value_from_dict(turn_obj, turn_nested_keys)
        if result:
            return result

    # Check nested 'item' object
    item_obj = payload.get("item")
    if isinstance(item_obj, dict):
        item_nested_keys = ("turnId", "turn_id", "id")
        result = get_string_value_from_dict(item_obj, item_nested_keys)
        if result:
            return result

    return None

def _extract_thread_identifier_from_structure(payload: Any) -> Optional[str]:
    # Validate payload is a dictionary
    if not isinstance(payload, dict):
        return None

    # Direct lookup at top level
    top_keys = ("threadId", "thread_id")
    result = get_string_value_from_dict(payload, top_keys)
    if result:
        return result

    # Check nested 'thread' object
    thread_obj = payload.get("thread")
    if isinstance(thread_obj, dict):
        thread_nested_keys = ("id", "threadId", "thread_id")
        result = get_string_value_from_dict(thread_obj, thread_nested_keys)
        if result:
            return result

    return None

def extract_thread_id_for_turn(payload: Any) -> Optional[str]:
    # Validate payload is a dictionary
    if not isinstance(payload, dict):
        return None

    # Try multiple candidate containers
    candidates = [payload, payload.get("turn"), payload.get("item")]
    for candidate in candidates:
        thread_id = _extract_thread_identifier_from_structure(candidate)
        if thread_id:
            return thread_id

    return None

def extract_thread_identifier(payload: Any) -> Optional[str]:
    # Validate payload is a dictionary
    if not isinstance(payload, dict):
        return None

    # Direct lookup at top level
    top_keys = ("threadId", "thread_id", "id")
