def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Handle empty or whitespace-only input
    if not test or test.strip() == "":
        return {}

    # Split the string into individual letters
    char_list = test.split()

    # Count occurrences using a dictionary
    frequency = {}
    for char in char_list:
        if char:  # Skip empty strings
            frequency[char] = frequency.get(char, 0) + 1

    # Return empty dict if no valid characters found
    if not frequency:
        return {}

    # Find the maximum frequency value
    highest_frequency = max(frequency.values())

    # Build result dictionary with only the letters having the maximum frequency
    result = {}
    for letter, freq in frequency.items():
        if freq == highest_frequency:
            result[letter] = freq

    return result

import sys
import json
from extract_form_field_info import get_field_info
from pypdf import PdfReader, PdfWriter

def populate_pdf_form(input_path: str, config_path: str, output_path: str):
    with open(config_path) as file:
        field_data = json.load(file)

    organized_fields = {}
    for item in field_data:
        if "value" in item:
            identifier = item["field_id"]
            page_num = item["page"]
            if page_num not in organized_fields:
                organized_fields[page_num] = {}
            organized_fields[page_num][identifier] = item["value"]

    document_reader = PdfReader(input_path)
    encountered_issues = False

    available_fields = get_field_info(document_reader)
    field_lookup = {f["field_id"]: f for f in available_fields}

    for entry in field_data:
        matched_field = field_lookup.get(entry["field_id"])
        if matched_field is None:
            encountered_issues = True
            print(f"ERROR: `{entry['field_id']}` is not a valid field ID")
        elif entry["page"] != matched_field["page"]:
            encountered_issues = True
            print(
                f"ERROR: Incorrect page number for `{entry['field_id']}` (got {entry['page']}, expected {matched_field['page']})"
            )
        else:
            if "value" in entry:
                validation_issue = check_field_value(matched_field, entry["value"])
                if validation_issue:
                    print(validation_issue)
                    encountered_issues = True

    if encountered_issues:
        sys.exit(1)

    document_writer = PdfWriter(clone_from=document_reader)
    for page_index, field_values in organized_fields.items():
        document_writer.update_page_form_field_values(
            document_writer.pages[page_index - 1], 
            field_values, 
            auto_regenerate=False
        )

    document_writer.set_need_appearances_writer(True)
    with open(output_path, "wb") as output_file:
        document_writer.write(output_file)

def check_field_value(field_metadata, provided_value):
    field_category = field_metadata["type"]
    field_name = field_metadata["field_id"]

    if field_category == "checkbox":
        selected_val = field_metadata["checked_value"]
        deselected_val = field_metadata["unchecked_value"]
        if provided_value != selected_val and provided_value != deselected_val:
            return f'ERROR: Invalid value "{provided_value}" for checkbox field "{field_name}". The checked value is "{selected_val}" and the unchecked value is "{deselected_val}"'

    elif field_category == "radio_group":
        valid_options = [opt["value"] for opt in field_metadata["radio_options"]]
        if provided_value not in valid_options:
            return f'ERROR: Invalid value "{provided_value}" for radio group field "{field_name}". Valid values are: {valid_options}'

    elif field_category == "choice":
        acceptable_choices = [opt["value"] for opt in field_metadata["choice_options"]]
        if provided_value not in acceptable_choices:
            return f'ERROR: Invalid value "{provided_value}" for choice field "{field_name}". Valid values are: {acceptable_choices}'

    return None

def apply_pypdf_patch():
    from pypdf.constants import FieldDictionaryAttributes
    from pypdf.generic import DictionaryObject

    original_inherited_getter = DictionaryObject.get_inherited

    def modified_inherited_getter(self, key: str, default=None):
        raw_result = original_inherited_getter(self, key, default)
        if (
            key == FieldDictionaryAttributes.Opt
            and isinstance(raw_result, list)
            and all(isinstance(v, list) and len(v) == 2 for v in raw_result)
        ):
            processed_result = [item[0] for item in raw_result]
            return processed_result
        return raw_result

    DictionaryObject.get_inherited = modified_inherited_getter

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    apply_pypdf_patch()
    input_pdf_file = sys.argv[1]
    configuration_json = sys.argv[2]
    output_pdf_file = sys.argv[3]

    populate_pdf_form(input_pdf_file, configuration_json, output_pdf_file)

