class WanVideoTI2VProcessor(WanVideoI2VProcessor):
    def __call__(self, vae_model, videos, first_frame, **kwargs):
        clip_features, vae_features = None, None

        # Save original tiling configuration
        original_tiling = vae_model.get_tiling_state()

        # Adjust VAE tiling if needed for image-to-video encoding
        current_tiling = self.enable_i2v_vae_encode_tiling
        if current_tiling not in ("auto", original_tiling):
            self.set_vae_tiling_state(vae_model, current_tiling)

        # Encode the first frame as latents
        first_frame_latents = vae_model.encode(first_frame.unsqueeze(2))

        # Restore original tiling state after encoding
        if vae_model.get_tiling_state() != original_tiling:
            self.set_vae_tiling_state(vae_model, original_tiling)

        return {
            "i2v_clip_feature": clip_features,
            "i2v_vae_feature": vae_features,
            "first_frame_latents": first_frame_latents
        }

import ctypes
import torch
from megatron.core.dist_checkpointing.strategies.filesystem_async import (
    FileSystemWriterAsync,
)
from primus.modules.module_utils import log_rank_0, warning_rank_0


class PrimusFileSystemWriterAsync(FileSystemWriterAsync):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    @staticmethod
    def preload_tensors(*args, **kwargs):
        # Detect ROCm/HIP environment via torch version info
        is_hip_env = getattr(torch.version, 'hip', None) is not None

        if is_hip_env:
            major, minor = PrimusFileSystemWriterAsync._query_hip_runtime_version()
            log_rank_0(f"Detected HIP runtime version: {major}.{minor}")

            # Apply workaround for HIP < 7.1
            needs_fix = (major < 7) or (major == 7 and minor < 1)
            if needs_fix:
                log_rank_0("HIP version < 7.1 detected; disabling non_blocking to avoid segfaults")
                kwargs = PrimusFileSystemWriterAsync._adjust_non_blocking_arg(args, kwargs)
                args = ()  # Reset positional args since they were embedded into kwargs

        return super(PrimusFileSystemWriterAsync, PrimusFileSystemWriterAsync).preload_tensors(
            *args, **kwargs
        )

    @staticmethod
    def _adjust_non_blocking_arg(pos_args, kw_args):
        """Rebuild kwargs with non_blocking=False when needed."""
        updated_kw = dict(kw_args)
        if 'non_blocking' in updated_kw:
            updated_kw['non_blocking'] = False
        elif pos_args and isinstance(pos_args[-1], bool):
            # Replace last positional arg if it's a boolean (assumed to be non_blocking)
            updated_kw['non_blocking'] = False
        else:
            warning_rank_0("Could not determine location of 'non_blocking' argument")
        return updated_kw

    @staticmethod
    def _query_hip_runtime_version():
        """Query HIP runtime version using libamdhip64.so via ctypes."""
        try:
            from ctypes.util import find_library
            lib_path = find_library("amdhip64")
            if not lib_path:
                raise RuntimeError("libamdhip64.so not found")

            hip_lib = ctypes.CDLL(lib_path)
            func = hip_lib.hipRuntimeGetVersion
            func.argtypes = [ctypes.POINTER(ctypes.c_int)]
            func.restype = ctypes.c_int

            ver = ctypes.c_int()
            ret = func(ctypes.byref(ver))
            if ret != 0:
                return (-1, -1)

            # Parse version as per HIP spec: major * 1e7 + minor * 1e5 + patch
            raw = ver.value
            major = raw // 10_000_000
            minor = (raw % 10_000_000) // 100_000
            return (major, minor)

        except Exception as e:
            log_rank_0(f"Failed to query HIP runtime version: {e}")
            return (-1, -1)

