import sys
import platform

def _read_requirements(file_path):
    """Read and parse requirements from a file, filtering comments and empty lines."""
    requirements = []
    with open(file_path, 'r') as f:
        for line in f:
            stripped = line.strip()
            if stripped and not stripped.startswith('#'):
                requirements.append(stripped)
    return requirements

# Custom wheel builder class to adjust wheel metadata
class CustomWheelBuilder:
    def __init__(self, original_bdist_wheel):
        self.original = original_bdist_wheel

    def finalize_options(self, instance):
        # Call the original finalize_options method
        self.original.finalize_options(instance)
        instance.root_is_pure = False

    def get_tag(self, instance):
        python_version = f"cp{sys.version_info.major}{sys.version_info.minor}"
        abi_tag = python_version

        system = platform.system()
        if system == "Linux":
            platform_tag = "manylinux1_x86_64"
        else:
            platform_tag = system.lower()

        return (python_version, abi_tag, platform_tag)

