import re

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    def convert_spaces(match):
        space_sequence = match.group(0)
        if len(space_sequence) > 2:
            return '-'
        else:
            return '_' * len(space_sequence)

    pattern = r' +'
    return re.sub(pattern, convert_spaces, text)

import torch
from .tensor_operations import Operation

class DeviceSetup:
    """A serializable device configuration class."""
    def __init__(self, gpu_count, gpu_ids=None):
        self.gpu_count = gpu_count
        self.gpu_ids = gpu_ids

    def apply(self):
        """Configure device settings for the current process."""
        import multiprocessing as mp
        proc_name = mp.current_process().name
        proc_rank = int(proc_name.split("-")[-1]) - 1
        Operation.local_idx = proc_rank

        if self.gpu_count > 0:
            if self.gpu_ids is not None:
                selected_gpu = self.gpu_ids[proc_rank % self.gpu_count]
            else:
                selected_gpu = proc_rank % self.gpu_count
            torch.cuda.set_device(selected_gpu)
            Operation.global_device = f"cuda:{selected_gpu}"
        else:
            Operation.global_device = "cpu"

        torch.set_grad_enabled(False)

def create_device_setup(config):
    """Constructs a DeviceSetup instance suitable for pickling."""
    return DeviceSetup(config.use_gpu_num, config.use_gpu_index)

def initialize_single_process(config):
    """Sets up device for single-process execution."""
    if config.use_gpu_num > 0:
        if config.use_gpu_index is not None:
            Operation.global_device = f"cuda:{config.use_gpu_index[0]}"
        else:
            Operation.global_device = "cuda"
    else:
        Operation.global_device = "cpu"

    torch.set_grad_enabled(False)

# Type III Clone: InlineObject9 equivalent with modified logic and structure

class OrderRequestWrapper:
    """
    A wrapper class for order request data, adapted from OpenAPI model.
    This version uses alternative implementation patterns while preserving functionality.
    """

    # Class-level definitions for attribute mapping
    _field_types = {
        'order_identifier': 'str'
    }

    _json_mapping = {
        'order_identifier': 'order_id'
    }

    def __init__(self, order_identifier=None, config=None):
        # Initialize configuration - use default if none provided
        self.config = config if config is not None else Configuration()

        # Set up internal storage and metadata
        self._internal_order_id = None
        self._metadata = {}

        # Apply input value through property setter
        self.order_identifier = order_identifier

    @property
    def order_identifier(self):
        """Get the stored order identifier"""
        return self._internal_order_id

    @order_identifier.setter
    def order_identifier(self, value):
        """Set the order identifier with validation"""
        # Perform client-side validation if enabled
        if self.config.client_side_validation and value is None:
            raise ValueError("Order identifier cannot be null")

        self._internal_order_id = value

    def serialize(self):
        """Convert object to dictionary representation"""
        output = {}

        # Iterate over field types using alternative iteration method
        for field_name in self._field_types.keys():
            current_value = getattr(self, field_name)

            # Handle different data types appropriately
            if isinstance(current_value, list):
                output[field_name] = [
                    item.serialize() if hasattr(item, 'serialize') else item 
                    for item in current_value
                ]
            elif hasattr(current_value, 'serialize'):
                output[field_name] = current_value.serialize()
            elif isinstance(current_value, dict):
                output[field_name] = {
                    k: v.serialize() if hasattr(v, 'serialize') else v 
                    for k, v in current_value.items()
                }
            else:
                output[field_name] = current_value

        return output

    def __str__(self):
        """String representation using pretty formatting"""
        import pprint
        return pprint.pformat(self.serialize())

    def __repr__(self):
        """Detailed string representation"""
        return self.__str__()

    def __eq__(self, other):
        """Check equality with another instance"""
        if not isinstance(other, OrderRequestWrapper):
            return False
        return self.serialize() == other.serialize()

    def __ne__(self, other):
        """Check inequality with another instance"""
        if not isinstance(other, OrderRequestWrapper):
            return True
        return self.serialize() != other.serialize()

import torch
from typing import Callable

def add_extra_dimensions(tensor: torch.Tensor, target_dim: int):
    current_shape = tensor.shape
    extra_dims = target_dim - len(current_shape)
    new_shape = current_shape + (1,) * max(0, extra_dims)
    return tensor.view(new_shape)

def validate_schedule_and_timesteps(schedule, timesteps):
    if schedule.T != timesteps.T:
        raise ValueError("Schedule and timesteps must have matching T values.")
    if schedule.is_continuous() != timesteps.is_continuous():
        raise ValueError("Schedule and timesteps must share the same continuity type.")

def apply_classifier_free_guidance(
    positive_output: torch.Tensor,
    negative_output: torch.Tensor,
    guidance_scale: float,
    rescale_factor: float = 0.0,
):
    # Compute CFG combination
    combined = negative_output + guidance_scale * (positive_output - negative_output)

    # Apply rescaling if enabled
    if rescale_factor != 0.0:
        # Calculate standard deviations across non-batch dimensions
        pos_std = positive_output.std(dim=list(range(1, positive_output.dim())), keepdim=True)
        cfg_std = combined.std(dim=list(range(1, combined.dim())), keepdim=True)

        # Compute scaling factor
        scale_factor = pos_std / cfg_std
        adjusted_factor = rescale_factor * scale_factor + (1 - rescale_factor)
        combined *= adjusted_factor

    return combined

def classifier_free_guidance_wrapper(
    positive_fn: Callable[[], torch.Tensor],
    negative_fn: Callable[[], torch.Tensor],
    guidance_scale: float,
    rescale_value: float = 0.0,
):
    # When no guidance is needed (scale=1), just return positive output
    if guidance_scale == 1.0:
        return positive_fn()

    # Otherwise apply full CFG logic
    return apply_classifier_free_guidance(
        positive_output=positive_fn(),
        negative_output=negative_fn(),
        guidance_scale=guidance_scale,
        rescale_factor=rescale_value,
    )

# Compute the nth Fibonacci number using an iterative approach

def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        prev, curr = 0, 1
        for _ in range(2, n + 1):
            prev, curr = curr, prev + curr
        return curr

