class ConfigWrapper:
    """Recursive configuration object that converts nested dicts into objects."""
    def __init__(self, data):
        for key, value in data.items():
            if isinstance(value, dict):
                setattr(self, key, ConfigWrapper(value))
            else:
                setattr(self, key, value)

    def flatten(self):
        """Convert the ConfigWrapper back to a dictionary recursively."""
        result = {}
        for attr_name in dir(self):
            if not attr_name.startswith('_'):
                attr_value = getattr(self, attr_name)
                if isinstance(attr_value, self.__class__):
                    result[attr_name] = attr_value.flatten()
                else:
                    result[attr_name] = attr_value
        return result

def setup_model_parallel(
    tensor_size=1,
    pipeline_size=1,
    virtual_pipeline_size=None,
    split_rank=None,
    context_size=1,
):
    """Initialize or reset model parallelism with given configuration."""
    ps.destroy_model_parallel()
    ps.initialize_model_parallel(
        tensor_model_parallel_size=tensor_size,
        pipeline_model_parallel_size=pipeline_size,
        virtual_pipeline_model_parallel_size=virtual_pipeline_size,
        pipeline_model_parallel_split_rank=split_rank,
        context_parallel_size=context_size,
    )

def reload_module_prefix(prefix):
    """Remove all loaded modules whose names start with the given prefix."""
    to_remove = [name for name in sys.modules if name.startswith(prefix)]
    for mod_name in to_remove:
        del sys.modules[mod_name]

