# Define API information dictionary (initially empty)
api_info = {}

class BaseTrait(Service):
    def __init__(self, config=None):
        # Initialize with provided configuration or empty dict if None
        config = config if config is not None else {}
        self.config = config

        # Extract region and service info map from config
        region = config.get('region', REGION_CN_NORTH1)
        service_info_map = config.get('service_info_map', {})

        # Set up service and API info using static methods
        self.service_info = BaseTrait._fetch_service_info(region, service_info_map)
        self.api_info = BaseTrait._retrieve_api_info()

        # Handle authentication credentials if provided
        if config.get('ak') and config.get('sk'):
            self.set_access_key(config['ak'])
            self.set_secret_key(config['sk'])

        # Initialize parent class with configured service and API info
        super(BaseTrait, self).__init__(self.service_info, self.api_info)

    @staticmethod
    def _fetch_service_info(region, service_info_map):
        # Retrieve service info for the specified region
        service_info = service_info_map.get(region)
        if not service_info:
            raise Exception(f'BaseService does not support region: {region}')
        return service_info

    @staticmethod
    def _retrieve_api_info():
        # Return current API information
        return api_info

    def update_api_info(self, additional_api_info):
        # Merge new API info with existing one
        self.api_info = {**self.api_info, **additional_api_info}
        return self

    def execute_get_request(self, operation, query_params=None, allow_list=False):
        # Perform GET request and handle response
        query_params = query_params or {}
        response = self.get(operation, query_params, allow_list)
        if not response:
            raise Exception(f"{operation}: no response received")
        # Convert response to JSON-compatible format
        response_json = json.loads(json.dumps(response))
        return response_json

    def execute_post_request(self, operation, query_params=None, payload=None):
        # Perform POST request with JSON body and handle response
        query_params = query_params or {}
        payload = payload or {}
        response = self.json(operation, query_params, payload)
        if not response:
            raise Exception(f"{operation}: no response received")
        # Convert response to JSON-compatible format
        response_json = json.loads(json.dumps(response))
        return response_json

