import sys
import os
import re
import yaml
from pathlib import Path

def check_skill_validity(skill_dir):
    """Perform validation on a skill directory"""
    skill_dir = Path(skill_dir).resolve()

    # Verify SKILL.md file presence
    skill_file = skill_dir / 'SKILL.md'
    if not skill_file.is_file():
        return False, "SKILL.md file is missing"

    # Load and inspect content
    raw_content = skill_file.read_text()
    if not raw_content.startswith('---'):
        return False, "Missing YAML header (frontmatter)"

    # Extract frontmatter section
    header_match = re.match(r'^---\n(.*?)\n---', raw_content, re.DOTALL)
    if not header_match:
        return False, "Malformed frontmatter structure"

    yaml_section = header_match.group(1)

    # Parse YAML data
    try:
        metadata = yaml.safe_load(yaml_section)
        if not isinstance(metadata, dict):
            return False, "Frontmatter must be structured as a dictionary"
    except yaml.YAMLError as error:
        return False, f"YAML parsing failed: {error}"

    # Define permitted top-level keys per Agent Skills spec
    VALID_KEYS = {'name', 'description', 'license', 'compatibility', 'allowed-tools', 'metadata'}

    # Detect invalid keys
    extra_keys = set(metadata.keys()) - VALID_KEYS
    if extra_keys:
        return False, (
            f"Invalid field(s) in frontmatter: {', '.join(sorted(extra_keys))}. "
            f"Only these are allowed: {', '.join(sorted(VALID_KEYS))}"
        )

    # Enforce required fields
    if 'name' not in metadata:
        return False, "Required 'name' field is absent"
    if 'description' not in metadata:
        return False, "Required 'description' field is absent"

    # Validate name property
    skill_name = metadata.get('name', '')
    if not isinstance(skill_name, str):
        return False, f"'name' must be a string, found {type(skill_name).__name__}"
    skill_name = skill_name.strip()

    if not skill_name:
        return False, "'name' cannot be blank. Use hyphen-separated lowercase identifiers (e.g., 'example-skill')"

    # Enforce naming rules
    if not re.fullmatch(r'[a-z0-9-]+', skill_name):
        return False, f"'{skill_name}' violates naming conventions (lowercase letters, digits, hyphens only)"
    if skill_name.startswith('-') or skill_name.endswith('-') or '--' in skill_name:
        return False, f"'{skill_name}' has improper hyphen usage"

    if len(skill_name) > 64:
        return False, f"'{skill_name}' exceeds maximum length of 64 characters ({len(skill_name)} chars)"

    # Confirm directory name matches skill name
    actual_dir = skill_dir.name
    if actual_dir != skill_name:
        return False, f"Directory '{actual_dir}' does not match skill name '{skill_name}'"

    # Validate description field
    skill_desc = metadata.get('description', '')
    if not isinstance(skill_desc, str):
        return False, f"'description' must be a string, found {type(skill_desc).__name__}"
    skill_desc = skill_desc.strip()

    if not skill_desc:
        return False, "'description' cannot be empty"

    if '<' in skill_desc or '>' in skill_desc:
        return False, "'description' must not contain angle brackets"

    if len(skill_desc) > 1024:
        return False, f"'description' exceeds limit of 1024 characters ({len(skill_desc)} chars)"

    # Check for incomplete placeholders
    if '[TODO' in skill_desc or 'TODO:' in skill_desc:
        return False, "Description contains uncompleted TODO markers"

    # Process body content
    body_match = re.match(r'^---\n.*?\n---\n?(.*)', raw_content, re.DOTALL)
    if body_match:
        remaining_text = body_match.group(1).strip()
        if not remaining_text:
            return False, "Body content is missing after frontmatter"

        # Flag TODOs in body as errors
        todo_occurrences = remaining_text.count('[TODO') + remaining_text.count('TODO:')
        if todo_occurrences > 0:
            return False, f"Found {todo_occurrences} TODO placeholder(s) in the skill body"

    return True, "Skill validation passed!"

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python validate_skill.py <skill_directory>")
        sys.exit(1)

    is_valid, result_message = check_skill_validity(sys.argv[1])
    print(result_message)
    sys.exit(0 if is_valid else 1)

