class ExcelSchemaExtractor:
    def __init__(self, excel_file: File, model: LLMModel):
        self.excel_file = excel_file
        self.model_client = LLM(model)

    def extract_schema(self, sheet_index: int) -> dict:
        # Resolve the full path to the Excel file
        file_path = self.excel_file.path

        # Open the Excel file and retrieve sheet names
        excel_reader = pd.ExcelFile(file_path)
        target_sheet = excel_reader.sheet_names[sheet_index]

        # Load the sheet data without header, limiting to first 200 rows/columns
        raw_data_df = pd.read_excel(file_path, sheet_name=target_sheet, header=None)
        limited_data = raw_data_df.iloc[:200, :200]

        # Convert to dictionary in 'split' format for structured prompt input
        data_dict = limited_data.to_dict(orient='split')

        # Construct detailed prompt for schema extraction
        prompt = f"""
        File details:
        - Name: {self.excel_file.filename}
        - Path: {file_path}
        - Target Sheet: {target_sheet}
        - Sheet Index: {sheet_index}

        Sample Data (first 200x200 cells):
        {data_dict}

        Your task:
        Analyze the provided sample of the Excel sheet and produce a JSON schema describing all identified fields/metrics.
        For each field/metric, include:
          - name: descriptive identifier
          - type: inferred from content (int, float, string, date, bool)
          - cell_address: exact single-cell reference (e.g., "B3")
          - orientation: either "vertical" or "horizontal"
          - range: if applicable, specify multi-cell range (e.g., "C5:C10"); otherwise leave empty

        Output format must be strictly:
        {{
          "sheet_name": "{target_sheet}",
          "sheet_index": {sheet_index},
          "sheet_file_path": "{file_path}",
          "fields": {{
            "field_key": {{
              "name": "Field Name",
              "data": {{
                "type": "string/int/float/date/bool",
                "cell_address": "A1",
                "orientation": "vertical/horizontal",
                "range": ""
              }}
            }}
          }}
        }}

        Requirements:
        - Return only valid JSON — no extra text, explanations, or markdown.
        - Ensure cell addresses are accurate based on the provided data.
        """

        # Generate schema via LLM inference
        raw_response = self.model_client.inference(prompt)
        parsed_schema = json.loads(raw_response)

        return parsed_schema

# Platform-specific code scanner for repository maintenance
# Scans files to detect platform-dependent patterns that may affect portability
# Run locally or in CI pipelines with: python tools/scan_platform_issues.py

import re
from pathlib import Path

# Root directory of the project (two levels up from this script)
PROJECT_ROOT = Path(__file__).resolve().parent.parent

# Define regex patterns to detect platform-specific constructs
DETECTION_RULES = {
    "shell_shebang": re.compile(r"^#!.*\b(bash|sh)\b"),
    "permission_commands": re.compile(r"\b(chown|chmod|id\s+-[ug])\b"),
    "audio_system": re.compile(r"\b(pulseaudio|pactl)\b"),
    "service_manager": re.compile(r"\bs6-"),
    "unix_domain_socket": re.compile(r"unix:"),
    "container_tools": re.compile(
        r"docker[- ]?compose|dockerfile|docker-compose\.yml", re.IGNORECASE
    ),
}

# Store findings as list of (pattern_name, file_path) tuples
FINDINGS = []

# Traverse all files in the project
for file_path in PROJECT_ROOT.rglob("*"):
    # Only process regular files with specific extensions or no extension
    if not file_path.is_file() or file_path.suffix not in {".sh", ".py", ""}:
        continue

    try:
        content = file_path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        continue

    # Check each pattern against the file content
    for rule_name, pattern in DETECTION_RULES.items():
        if pattern.search(content):
            FINDINGS.append((rule_name, str(file_path)))

# Output results
if not FINDINGS:
    print("No platform-specific patterns detected.")
else:
    print("Platform-specific scan results:")

    # Group findings by pattern type
    categorized_findings = {}
    for rule_name, file_path in FINDINGS:
        categorized_findings.setdefault(rule_name, []).append(file_path)

    # Print grouped results
    for rule_name, files in categorized_findings.items():
        print(f"\n[{rule_name}]")
        for file in files[:30]:
            print(" -", file)
        if len(files) > 30:
            print("  ... and more")

print("\nScan completed successfully.")

