def parse_page_ranges(spec: str | None, total_pages: int) -> list[int]:
    # Handle empty or None input - return all pages
    if spec is None or not spec.strip():
        return list(range(total_pages))

    # Normalize the specification string
    normalized_spec = spec.strip().lower()

    # Handle special keywords for all pages
    if normalized_spec in {"all", "*"}:
        return list(range(total_pages))

    # Handle odd/even page selection (1-indexed)
    if normalized_spec == "odd":
        return [page_idx for page_idx in range(total_pages) if (page_idx + 1) % 2 == 1]
    if normalized_spec == "even":
        return [page_idx for page_idx in range(total_pages) if (page_idx + 1) % 2 == 0]

    # Parse comma-separated ranges
    result_indices = set()
    for segment in normalized_spec.split(","):
        segment = segment.strip()
        if not segment:
            continue

        # Check if this segment contains a range (hyphen)
        if "-" in segment:
            start_str, end_str = segment.split("-", 1)
            start_page = int(start_str)
            end_page = int(end_str)
        else:
            # Single page specification
            page_num = int(segment)
            start_page = end_page = page_num

        # Validate page numbers are within bounds (1-indexed)
        if start_page < 1 or end_page < 1 or start_page > total_pages or end_page > total_pages:
            raise ValueError(f"Page range out of bounds: {start_page}-{end_page} of {total_pages}")

        # Ensure valid range order
        if end_page < start_page:
            raise ValueError(f"Invalid page range: {start_page}-{end_page}")

        # Add all pages in the range to our set (convert to 0-indexed)
        for idx in range(start_page - 1, end_page):
            result_indices.add(idx)

    # Verify at least one page was specified
    if not result_indices:
        raise ValueError("No valid ranges provided")

    # Return sorted list of unique indices
    return sorted(result_indices)

# Optimized caching mechanism for function arguments to accelerate inference

class MemoryCache:
    def __init__(self, enabled=True, prefix="", storage=None):
        self.storage = storage if storage is not None else {}
        self.enabled = enabled
        self.prefix = prefix

    def execute(self, identifier: str, func: callable):
        if not self.enabled:
            return func()

        full_key = self.prefix + identifier
        if full_key in self.storage:
            return self.storage[full_key]

        value = func()
        self.storage[full_key] = value
        return value

    def with_prefix(self, segment: str):
        return MemoryCache(
            enabled=self.enabled,
            prefix=self.prefix + segment + ".",
            storage=self.storage,
        )

    def fetch(self, identifier: str):
        full_key = self.prefix + identifier
        return self.storage[full_key]

import torch.nn as nn

def stochastic_depth(x, drop_rate: float = 0.0, is_training: bool = False):
    # Return input unchanged if no dropout or not in training mode
    if drop_rate == 0.0 or not is_training:
        return x

    survival_prob = 1.0 - drop_rate
    # Create shape for broadcasting across batch dimension and preserving spatial dimensions
    broadcast_shape = (x.size(0),) + (1,) * (x.dim() - 1)

    # Generate random tensor with Bernoulli distribution
    mask = torch.empty(broadcast_shape, dtype=x.dtype, device=x.device).bernoulli_(survival_prob)

    # Scale the mask to maintain expected value
    if survival_prob > 0.0:
        mask.div_(survival_prob)

    # Apply dropout mask to input
    return x * mask

class StochasticDepth(nn.Module):
    """Implements stochastic depth regularization for residual networks."""
    def __init__(self, drop_prob=None):
        super(StochasticDepth, self).__init__()
        self.drop_prob = drop_prob

    def forward(self, x):
        return stochastic_depth(x, self.drop_prob, self.training)

