# Module for handling request hooks system
# Available hooks:
# `response`: The response object generated after sending a Request

HOOK_NAMES = ["response"]

def initialize_hooks():
    """Create and return a dictionary with empty hook lists for each hook type."""
    return {event: [] for event in HOOK_NAMES}

def execute_hook(event_name, registered_hooks, data, **additional_kwargs):
    """Executes all registered hooks for a specific event on the provided data."""
    registered_hooks = registered_hooks or {}
    target_hooks = registered_hooks.get(event_name)

    if target_hooks:
        # Ensure hooks is always iterable (convert single callable to list)
        if callable(target_hooks):
            target_hooks = [target_hooks]

        for hook_func in target_hooks:
            updated_data = hook_func(data, **additional_kwargs)
            if updated_data is not None:
                data = updated_data

    return data

import torch

def apply_mixins_to_instance(instance, mixin_class):
    """Dynamically add mixin functionality to an existing object instance"""
    original_class = instance.__class__
    class_name = instance.__class__.__name__
    instance.__class__ = type(
        f"{class_name}WithMixin", 
        (mixin_class, original_class), 
        {}
    )

class EmbeddingNormalizationMixin(torch.nn.Module):
    """
    A mixin for normalizing embeddings in transformer models.
    Applies scaling only when 'use_embedding_scale' is True in the config.
    The scaling factor is computed as the square root of the model's hidden dimension.
    """
    def forward(self, **kwargs):
        # Get embeddings from parent class implementation
        output_embeddings = super().forward(**kwargs)

        # Apply scaling conditionally based on configuration
        if getattr(self.config, 'use_embedding_scale', False):
            scale_factor = self.config.hidden_size ** 0.5
            return output_embeddings * torch.tensor(scale_factor, dtype=output_embeddings.dtype)
        else:
