from pip._vendor.requests.models import CONTENT_CHUNK_SIZE, Response
from pip._internal.exceptions import NetworkConnectionError
from typing import Dict, Generator

# Original comment preserved but slightly rephrased for clarity
HEADERS: Dict[str, str] = {"Accept-Encoding": "identity"}

def check_response_status(resp: Response) -> None:
    error_message = ""

    # Handle reason string decoding with fallbacks
    if isinstance(resp.reason, bytes):
        try:
            decoded_reason = resp.reason.decode("utf-8")
        except UnicodeDecodeError:
            decoded_reason = resp.reason.decode("iso-8859-1")
    else:
        decoded_reason = resp.reason

    # Check status codes for client or server errors
    status_code = resp.status_code
    if 400 <= status_code < 500:
        error_message = (
            f"{status_code} Client Error: {decoded_reason} for url: {resp.url}"
        )
    elif 500 <= status_code < 600:
        error_message = (
            f"{status_code} Server Error: {decoded_reason} for url: {resp.url}"
        )

    # Raise exception only if an error message was constructed
    if error_message:
        raise NetworkConnectionError(error_message, response=resp)

def stream_response_data(
    response: Response, 
    buffer_size: int = CONTENT_CHUNK_SIZE
) -> Generator[bytes, None, None]:
    """Yield data chunks from a requests Response object."""
    try:
        # Use urllib3's stream method directly
        raw_stream = response.raw.stream(
            buffer_size,
            decode_content=False  # Avoid decompression to preserve checksum integrity
        )
        for chunk in raw_stream:
            yield chunk
    except AttributeError:
        # Fallback for standard file-like objects without .stream()
        while True:
            data_chunk = response.raw.read(buffer_size)
            if not data_chunk:
                break
            yield data_chunk

# Retrieve environment variable with fallback and boolean interpretation
def get_env_var_with_fallback(key, default=None):
    import os
    env_value = os.environ.get(key, None)
    if env_value is None:
        return default

    # Normalize string to lowercase for comparison
    normalized_value = env_value.lower()

    # Check for truthy values
    if normalized_value in ("1", "yes", "true"):
        return True
    # Check for falsy values
    elif normalized_value in ("0", "no", "false"):
        return False
    else:
        return default

