def extract_tensor_factory_parameters(**kwargs):
    valid_params = {"device", "dtype", "layout", "requires_grad", "pin_memory", "memory_format"}
    result_kwargs = {}

    for param_name, param_value in kwargs.items():
        if param_value is not None and param_name in valid_params:
            result_kwargs[param_name] = param_value

    return result_kwargs

