import torch

# Determine device module dynamically
device_module = getattr(torch, AI_DEVICE)

class HunyuanVideo15OffloadTransformerInfer(HunyuanVideo15TransformerInfer):
    def __init__(self, config_dict):
        super().__init__(config_dict)

        # Check if CPU offloading is enabled
        enable_offload = config_dict.get("cpu_offload", False)
        if enable_offload:
            granularity_level = config_dict.get("offload_granularity", "block")

            # Select inference strategy based on granularity
            if granularity_level == "block":
                self.compute_strategy = self._run_with_blockwise_offload
            elif granularity_level == "model":
                self.compute_strategy = self._run_full_on_gpu
            else:
                raise ValueError(f"Unsupported offload granularity: {granularity_level}")

            # Initialize offload manager only when not full-model mode
            if granularity_level != "model":
                self.async_weight_manager = WeightAsyncStreamManager(offload_granularity=granularity_level)

    @torch.no_grad()
    def _run_with_blockwise_offload(self, param_container, output_holder):
        total_blocks = self.double_blocks_num

        for idx in range(total_blocks):
            self.current_block_index = idx

            # First block initialization
            if idx == 0:
                self.async_weight_manager.setup_initial_buffer(param_container.double_blocks)

            # Prefetch next block (if any remain)
            if idx < total_blocks - 1:
                self.async_weight_manager.schedule_prefetch(idx + 1, param_container.double_blocks)

            # Perform computation on dedicated stream
            with device_module.stream(self.async_weight_manager.compute_stream):
                output_holder.img, output_holder.txt = self.process_double_block(
                    self.async_weight_manager.active_cuda_buffer, output_holder
                )

            # Swap buffers after processing current block
            self.async_weight_manager.exchange_buffers()

    @torch.no_grad()
    def _run_full_on_gpu(self, param_container, output_holder):
        # Default inference without offloading (same as parent class behavior)
        return super().infer_without_offload(param_container, output_holder)

    # Alias infer_func to selected strategy
    def infer_func(self, weights, infer_module_out):
        return self.compute_strategy(weights, infer_module_out)

