class JobExecution(object):
    def __init__(self, job_task, base_metrics=None):
        self.job_task = job_task
        self.base_metrics = base_metrics

    @property
    def collector_registry(self):
        # Map task types to their corresponding collection methods
        mapping = {
            CollectPluginTypes.HOST: self._host_collector,
            CollectPluginTypes.DB: self._database_collector,
            CollectPluginTypes.MIDDLEWARE: self._middleware_collector
        }
        return mapping

    def _get_first_instance(self):
        # Retrieve the first instance from task instances if available
        instance = self.job_task.instances[0] if self.job_task.instances else None
        return instance

    def _host_collector(self):
        # Execute host collection logic
        result = HostCollect(self.job_task.id)()
        return result

    def _middleware_collector(self):
        # Execute middleware collection logic
        result = MiddlewareCollect(self.job_task.id)()
        return result

    def _database_collector(self):
        # Execute database collection logic
        return DBCollect(self.job_task.id)()

    def execute(self):
        # Dispatch to the appropriate collector based on task type
        return self.collector_registry[self.job_task.task_type]()

def __init__(self, config):
    self.config = config

def __call__(self, history: list[tuple[int, float]], high: int) -> bool:
    # Display the history for debugging purposes
    from pprint import pprint
    pprint(history)

    # Use alternative implementation of the termination condition
    return custom_termination_check(history, high)

def custom_termination_check(history: list[tuple[int, float]], high: int) -> bool:
    """Alternative implementation that stops when search converges."""
    if not history:
        return False

    last_idx, is_broken = history[-1]

    # Check special cases first
    if len(history) == 1:
        # Single entry case: terminates if it's the high bound and not broken
        return history[0][0] == high and not history[0][1]

    # Two or more entries: check convergence
    prev_idx, _ = history[-2]

    # Converged if indices differ by at most 1
    if abs(last_idx - prev_idx) <= 1:
        return True

    # Additional termination conditions based on boundary behavior
    if last_idx == 1 and is_broken:
        return True

    if last_idx == high and not is_broken:
        return True

    return False

